-- Runtime game systems, event handling, gameplay UI, state, scoring and callbacks.

------------------
-- During the Game
------------------
function tryObjectEnterContainer(container, object)
    if gStates.preEndTurn==false and container.type=="Card" and object.type=="Card" then
		for _, turnDetails in pairs(turnOrder) do
			if turnDetails.seatPos~=nil then
				for _, c in pairs(getObjectFromGUID(playerPlayAreas[turnDetails.seatPos]).getObjects()) do --players Play Areas
					if c.guid==container.guid or c.guid==object.guid then return false end
				end
				for _, c in pairs(getObjectFromGUID(playerUnitAreas[turnDetails.seatPos]).getObjects()) do --players Unit Areas
					if c.guid==container.guid or c.guid==object.guid then return false end
				end
			end
		end
	end
    return true -- Allows object to enter.
end

--Repair the saved home locations for live skill tokens. This is skill bookkeeping, not UI bookkeeping,
--so only run it when skill state is being initialized/refreshed rather than on every main UI update.
function refreshMageSkillLocations()
	local double={}
	for skillGUID, _ in pairs(skillTokens) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil then
			local objPos=skill.getPosition()
			if gStates.mageSkills[skillGUID]==nil then gStates.mageSkills[skillGUID]={objPos[1], objPos[2], objPos[3]} end
			local skillPos=gStates.mageSkills[skillGUID]
			local key=(math.floor(skillPos[1]/0.3)*0.3)..(math.floor(skillPos[3]/0.3)*0.3)
			if double[key]~=nil then
				skillPos[1]=skillPos[1]+0.4
				skillPos[3]=skillPos[3]-0.4
				key=(math.floor(skillPos[1]/0.3)*0.3)..(math.floor(skillPos[3]/0.3)*0.3)
			end
			double[key]=true
		end
	end
end

--Keep City scripting zones and stored defender return positions aligned with their City cards.
--City cards only move during City/map bookkeeping, so this should not run on ordinary UI refreshes.
function refreshCityScriptZones()
	for _, cityDetails in pairs(cityScriptZones) do
		if gStates.cityCard[cityDetails.cityGUID]~=nil then cityDetails.cityCard=gStates.cityCard[cityDetails.cityGUID] end
	end
	for zoneGUID, cityDetails in pairs(cityScriptZones) do
		local zoneObj=getObjectFromGUID(zoneGUID)
		local cityCardObj=getObjectFromGUID(cityDetails.cityCard)
		local cityMonsters=gStates.cityMonsterQty[cityDetails.cityGUID]
		if zoneObj~=nil and cityCardObj~=nil and cityMonsters~=nil and (cityMonsters.extra.megapolisPair==nil or cityMonsters.extra.megapolisPair~=cityDetails.cityGUID) then
			local zoneScale={x=4.6, y=1, z=3.3}
			local monsterOffset={1.15, -0.7}
			if zoneGUID==volkare.discZone then zoneScale={x=7.5, y=1, z=7.5} monsterOffset={5.5, -1}
			elseif zoneGUID==darkCrusader.discZone or zoneGUID==elementalist.discZone then zoneScale={x=7.5, y=1, z=7.5} monsterOffset={-5.5, -1} end
			if cityCardObj.getScale()[1]==1.5 then zoneScale={x=4.6, y=1, z=4.6} end
			local cityPos=cityCardObj.getPosition()
			zoneObj.setScale(zoneScale)
			zoneObj.setPosition({cityPos[1], 1.4, cityPos[3]})
			local count=0
			for monsterGUID, _ in pairs(cityMonsters) do
				if monsterGUID~="shieldNeeded" and gStates.monsterPlayLocation[monsterGUID]~=nil and getObjectFromGUID(monsterGUID)~=nil then
					gStates.monsterPlayLocation[monsterGUID][1]=cityPos[1]+monsterOffset[1]
					gStates.monsterPlayLocation[monsterGUID][2]=1+(0.6*count)
					gStates.monsterPlayLocation[monsterGUID][3]=cityPos[3]+monsterOffset[2]+(0.4*count)
					count=count+1
				end
			end
		end
	end
end

--Update the text in the Main User Interface
--Deed/discard descriptions are informational and only need rebuilding when that physical pile changes.
--Key the debounce by scripting zone rather than Deck GUID because TTS can replace/collapse Deck objects as cards merge or are drawn.
local deckDescriptionWait={}
--Deed draws are always single-digit in normal play. TTS otherwise waits to see if another digit is coming before firing onObjectNumberTyped.
local function setDeedDeckImmediateNumberTyping(seatPos)
	local zoneGUID=deedDeckZones[seatPos]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone==nil then return end
	for _, obj in pairs(zone.getObjects()) do if obj.type=="Deck" then obj.max_typed_number=1 end end
end
