	elseif state=="ReadyToEnd" then
		spec.label="{en}Volkare Processed{ru}Волкар сходил{zh-tw}沃卡里行動結束{zh-cn}沃卡里行动结束{ko}진행 완료{es}Volkare Procesado{fr}Volkare Traité{pt-br}Volkare Processado{de}Volkare Verarbeitet"
		spec.notes=gStates.blurb
	else
		spec.label="{en}Processing Volkare...{ru}Обработка Волкара...{zh-tw}沃卡里行動處理中...{zh-cn}沃卡里行动处理中...{ko}볼케어 처리 중...{es}Procesando Volkare...{fr}Traitement de Volkare...{pt-br}Processando Volkare...{de}Volkare wird verarbeitet..."
		spec.notes=gStates.blurb
		spec.interactable=false
	end
	if automatedPanelHasDeedCards(stats)==false and gStates.volkareWon==false and gStates.volkareFrenzied==true then
		if state=="Start" then
			spec.label="{en}Process Frenzied Volkare{ru}Ход Волкара в состоянии Ярости{zh-tw}狂暴沃卡里行動{zh-cn}狂暴沃卡里行动{ko}볼케어(광폭) 진행{es}Procesar Volkare en Frenesí{fr}Processus Volkare Frénétique{pt-br}Processar Volkare em Frenesi{de}Rasender Volkare wird verarbeitet"
			spec.notes="{en}Volkare's Deck is Empty.\n-< FRENZY >-\nVolkare acts as if he drew a Blue Spell and doesn't Reroll any Die.{ru}Колода Волкара пуста.\n-< ЯРОСТЬ >-\nВолкар действует так, как будто он вытащил Синее Заклинание, и не перебрасывает кубики.{zh-tw}沃卡里牌的牌庫已空。\n-<狂暴>-\n接下來的每一回合，\n沃卡里視為翻開一張藍色法術卡\n來行動。（即移動或攻擊兩次）\n此次行動不重擲任何骰子。{zh-cn}沃卡里牌的牌库已空。\n-<狂暴>-\n接下来的每一回合，\n沃卡里视为翻开一张蓝色法术卡\n来行动。（即移动或攻击两次）\n此次行动不重掷任何骰子。{ko}볼케어의 더미가 비었습니다.\n-< 광폭 >-\n이제 볼케어는 파란색 마법을 뽑은 것처럼 행동하며, 주사위를 굴리지 않습니다.{es}El mazo de Volkare está vacío.\n-< FRENESÍ >-\nVolkare actúa como si hubiera robado un Hechizo Azul, y no vuelve a lanzar ningún dado.{fr}Le Deck de Volkare est vide.\n-< FRÈSIE >-\nVolkare agit comme s'il avait pioché un sort bleu et ne relance aucun dé.{pt-br}Deck do Volkare está vazio.\n-< FRENESI >-\nVolkare age como se ele tirasse um Feitiço azul e não re-rola nenhum dado.{de}Volkare Deck ist leer.\n-< FRENZY >-\nVolkare tut so, als ob er einen blauen Zauberspruch gezogen hätte und würfelt nicht neu."
		else
			spec.label="{en}Frenzied Volkare Processed{ru}Волкар в состоянии Ярости сходил{zh-tw}狂暴沃卡里行動結束{zh-cn}狂暴沃卡里行动结束{ko}진행 완료{es}Volkare en Frenesí Procesado{fr}Volkare Frénétique Traité{pt-br}Volkare em Frenesi Processado{de}Rasender Volkare verarbeitet"
		end
	end
	if gStates.tacticRemove==true or gStates.tacticShown==true then
		spec.notes="{en}Click the button in the Center to claim a random tactic.{ru}Нажмите кнопку в центре, чтобы выбрать случайную Тактику.{zh-tw}點擊中間的按鈕來隨機選擇戰術卡。{zh-cn}点击中间的按钮来随机选择战术卡。{ko}중앙에 있는 버튼을 클릭하여 무작위 전략 카드를 고르세요.{es}Pulsar el Botón del Centro para Robar una Táctica al Azar.{fr}Cliquez sur le bouton dans le Centre pour réclamer une tactique aléatoire.{pt-br}Clique no botão no centro para pegar uma tática aleatória.{de}Klicken Sie auf die Schaltfläche in der Mitte, um eine zufällige Taktik zu fordern."
		if gStates.tacticRemove==true then spec.interactable=false end
	end
	if ((gStates.endRoundCalled==true and gStates.currentRound>=gStates.rounds) or gStates.volkareWon==true) and state=="Start" then
		spec.notes="{en}Final round of turns is complete. For most players this would have meant just flipping your Turn Order token back upright.{ru}Завершен последний круг ходов. Для большинства игроков это означало бы просто перевернуть жетон очередности хода обратно в вертикальное положение.{zh-tw}最後一輪的最終回合已結束。\n對於大多數玩家只需將你的順位\n標記翻轉回來即可。{zh-cn}最后一轮的最终回合已結束。\n對於大多数玩家只需将你的順位\n标记翻转回来即可。{ko}차례의 마지막 순서가 끝났습니다. 대부분의 플레이어들은 라운드 순서 토큰을 앞면으로 뒤집었을겁니다.{es}La Última Ronda de Turnos se ha completado. Para la mayoría de jugadores esto significa simplemente poner boca arriba el marcador de turno.{fr}Le dernier tour est terminé. Pour la plupart des joueurs, cela aurait signifié simplement retourner votre jeton Ordre du tour à la verticale.{pt-br}Rodada Final de turnos está completa. Para a maioria dos jogadores isso significa apenas virar sua ficha de ordem de turno de volta para cima.{de}Die letzte Zugrundelegung ist abgeschlossen. Für die meisten Spieler würde dies bedeuten, dass sie ihr Zugreihenfolgeplättchen einfach wieder umdrehen."
		if gStates.volkareReturnTimeoutLoss==true then spec.notes=gStates.blurb end
	end
	return spec
end

function automatedCurrentPlayerPanelSpec()
	if gStates==nil or gStates.turnNumber==nil or turnOrder[gStates.turnNumber]==nil or gStates.positionMageKnight==nil then return nil end
	local stats=turnOrder[gStates.turnNumber]
	if stats.mage~=gStates.positionMageKnight[5] then return nil end
	if gStates.positionMageKnight[5]=="Volkare" then return automatedVolkarePanelSpec(stats) end
	if proxyPlayerActive~=nil and proxyPlayerActive()==true then return automatedProxyPanelSpec(stats) end
	return automatedDummyPanelSpec(stats)
end

function automatedMainPanelApply(spec)
	if spec==nil then
		UI.setAttribute("DummyTurn","active","false")
		UI.setAttribute("ExtraTurnTactic","active","false")
		UI.setAttribute("DummyChoiceButtons","active","false")
		automatedAttackResponseUI(nil)
		return false
	end
	if spec.preserveResponse~=true then
		if spec.responseSpec~=nil then automatedAttackResponseUI(spec.responseSpec) else automatedAttackResponseUI(nil) end
	end
	UI.setAttribute("ExtraTurnTactic","active","false")
	if spec.panelActive==false then
		UI.setAttribute("DummyTurn","active","false")
		UI.setAttribute("DummyChoiceButtons","active","false")
		return true
	end
	UI.setAttribute("DummyTurn","active","true")
	if spec.mainText~=nil then UI.setAttribute("MainGameNotes","text",spec.mainText) UI.setAttribute("MainGameNotes","color","white") end
	if spec.notes~=nil then UI.setAttribute("DummyNotes","Text",spec.notes) end
	if spec.actor=="proxy" and proxyManaChoiceUI~=nil then proxyManaChoiceUI(nil) else UI.setAttribute("DummyChoiceButtons","active","false") end
	UI.setAttribute("DummyButton","active",spec.buttonVisible==false and "false" or "true")
	if spec.onClick~=nil then UI.setAttribute("DummyButton","onClick",spec.onClick) end
	if spec.label~=nil then UI.setAttribute("DummyButtonText","Text",spec.label) end
	local enabled=spec.interactable~=false
	UI.setAttribute("DummyButton","interactable",enabled and "True" or "False")
	UI.setAttribute("DummyButtonImage","image",enabled and "Sliced Button/Button New Active" or "Sliced Button/Button New Deactive")
	if spec.proxyManaChoice~=nil and proxyManaChoiceUI~=nil then proxyManaChoiceUI(spec.proxyManaChoice) end
	return true
end

function automatedMainPanelRefresh(overrideSpec)
	local spec=overrideSpec
	if spec==nil and gStates~=nil and gStates.apocalypseDragonTurnActive==true and againstDragonMainUIPanelSpec~=nil then spec=againstDragonMainUIPanelSpec() end
	if spec==nil and gStates~=nil and gStates.apocalypseHereHorsemenTurnActive==true and apocalypseIsHereMainUIPanelSpec~=nil then spec=apocalypseIsHereMainUIPanelSpec() end
	if spec==nil then spec=automatedCurrentPlayerPanelSpec() end
	return automatedMainPanelApply(spec)
end

function mainUIUpdate(source)
	if gStates.firstStarted==true then
		if mainUIPause~=nil then Wait.stop(mainUIPause) end
		mainUIPause=Wait.time(function()
			local playerAreaCardCount=0
			local playerAreaSkillCount=0
			local nextPlayer=nextTurnMerged("nextMage")
			local nextPlayerEndCalled=turnOrder[nextPlayer].endCalled
			if nextPlayerEndCalled~=true and turnOrder[nextPlayer].mage==gStates.positionMageKnight[5] then nextPlayerEndCalled=turnOrder[nextTurnMerged("nextMageSkipDummy")].endCalled end
			--if nextPlayerEndCalled~=true then nextPlayerEndCalled=turnOrder[nextPlayer].gameEnder end
			--if nextPlayerEndCalled~=true then nextPlayerEndCalled=turnOrder[nextTurnMerged("nextMageSkipDummy")].gameEnder end

			--Check for Game Over state. Normal final-turn completion is promoted to
			--gStates.gameOver by nextTurnMerged("incrementTurn"), after Rewards Claimed
			--has finished the last player's cleanup.
			gameOver=gStates.gameOver==true or gStates.volkareWon==true

			local currentPlayerGameEnder=turnOrder[gStates.turnNumber].gameEnder==true

			--Card/skill counts come from the play-area GUID registry maintained by zone enter/leave events.
			playerAreaCardCount, playerAreaSkillCount=cachedPlayAreaCounts(turnOrder[gStates.turnNumber].seatPos)


			--Play-area card scaling is handled by the play-area zone callbacks.
			--This keeps physical setScale calls out of the full main UI refresh.

			--Fame is cached when a fame shield moves; ordinary UI refreshes do not reread every fame shield.

			--Out of Turn Menu visibility is event-driven/cached. Ordinary card movement uses the cheap empty/non-empty hot path.
			local outOfTurnHotPlayAreaOnly=source=="Object entered into play area" or source=="Object removed from zone"
			refreshOutOfTurnActions(playerAreaCardCount, playerAreaSkillCount, false, outOfTurnHotPlayAreaOnly)


			--change End turn button to say End Round on the last player turn
			UI.setAttribute("EndTurnButton", "interactable", "True")
			UI.setAttribute("EndTurnButton", "tooltip", "At least one card must be played or discarded to 'End Your Turn'.")
			UI.setAttribute("EndTurnButtonImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("EndTurnButtonAlt", "interactable", "True")
			UI.setAttribute("EndTurnButtonAltImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("ExtraTurnTacticButton", "interactable", "True")
			UI.setAttribute("ExtraTurnTacticButtonImage", "image", "Sliced Button/Button New Active")
			UI.setAttribute("PreEndTurnText", "text", "{en}Rewards Claimed{ru}Награды получены{zh-tw}獲得獎勵{zh-cn}获得奖励{ko}보상 처리 완료{es}Recompensas Reclamadas{fr}Récompenses réclamées{pt-br}Recompensas Coletadas{de}Belohnungen Beansprucht")
			local endText="{en}End Turn{ru}Конец хода{zh-tw}結束回合{zh-cn}结束回合{ko}차례 종료{es}Fin de Turno{fr}Fin de Tour{pt-br}Fim de Turno{de}Zug Beenden"
			if nextPlayerEndCalled==true then
				endText="{en}End Turn and Round{ru}Конец хода и Раунда{zh-tw}結束回合及本輪次{zh-cn}结束回合及本轮次{ko}차례 및 라운드 종료{es}Fin de Turno y Ronda{fr}Fin du Tour et du Round{pt-br}Fim de Turno e Rodada{de}Zug und Runde Beenden" end
			if gStates.endGameAchieved=="true" and ((gStates.finalTurnReason=="victory" and currentPlayerGameEnder==true) or (gStates.finalTurnReason=="endRound" and nextPlayerEndCalled==true))==true then
				endText="{en}End Game{ru}Конец игры{zh-tw}結束遊戲{zh-cn}结束游戏{ko}게임 종료{es}Fin del Juego{fr}Fin du Jeu{pt-br}Fim de Jogo{de}Spiel Beenden" end
			local nextIsCoopAssaulter=gStates.coopAssaultPhase=="combat" and gStates.coopAssaultParticipants~=nil and gStates.coopAssaultParticipants[nextPlayer]~=nil
			if nextIsCoopAssaulter and turnOrder[nextPlayer].mage~=gStates.positionMageKnight[5] and getObjectFromGUID(turnOrder[nextPlayer].turnOrderTokenGUID).is_face_down==true then
				endText="{en}Next Assaulter{ru}Следующий штурмующий{zh-tw}換下一個襲擊者{zh-cn}换下一个袭击者{ko}다음 강습자{es}Siguiente Asaltante{fr}Prochain Agresseur{pt-br}Próximo Invasor{de}Nächster Spieler" end
			UI.setAttribute("EndTurnButtonText", "text", endText)
			UI.setAttribute("EndTurnButtonAltText", "text", endText)


			--Automated-player presentation is centralized in automatedMainPanelRefresh().
			--Keep only the gameplay branch split here so normal-player Fame/Rep work is never run for the automated seat.
			local fameForUp=0
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				if scenarioList[gStates.scenarioRef][gStates.playersRef].dummyTacticSelection=="F" then turnOrder[gStates.turnNumber].fame=-1 else turnOrder[gStates.turnNumber].fame=999 end
			else--normal players
				if againstDragonAttendanceUIRefresh==nil or againstDragonAttendanceUIRefresh()~=true then UI.setAttribute("VolkareAttacked", "active", "false") end
				--Reputation is cached when its shield moves; no reputation-track zone scan is needed here.
				--Resource Tracker is manually controlled by the player; mainUIUpdate does not redraw it.

				--Work out how much more fame is needed until a level up is required.
				--Fame is already cached when the shield moves, so derive its board row instead of rereading the physical shield.
				local currentPlayer=turnOrder[gStates.turnNumber]
				local boardFame=currentPlayer.fame-(gStates.scoreIfLooped*currentPlayer.scoreLoop)
				if boardFame<0 then boardFame=0 end
				local fameVerticle=math.floor(math.sqrt(boardFame+1))
				if fameVerticle>gStates.rowsOnBoard then fameVerticle=gStates.rowsOnBoard end
				if currentPlayer.level<gStates.rowsOnBoard then
					local fameToLevel=math.floor(math.sqrt(currentPlayer.fame+1))
					if fameToLevel>gStates.rowsOnBoard then fameToLevel=gStates.rowsOnBoard end
					if fameVerticle<gStates.rowsOnBoard then fameForUp=((fameToLevel+1)*(fameToLevel+1))-1-currentPlayer.fame end
					--see if the current fame value would cause a level up
					currentPlayer.levelUp=0
					if fameToLevel>currentPlayer.level then
						if fameToLevel==2 or fameToLevel==4 or fameToLevel==6 or fameToLevel==8 or fameToLevel==10 or fameToLevel==12 or fameToLevel-currentPlayer.level>1 then gStates.levelingUp=true end
						currentPlayer.levelUp=fameToLevel-currentPlayer.level
						if gStates.preEndTurn==true and gStates.coopAssaultPhase~="combat" and levelUpcalled==false then levelUpcalled=true levelUp(gStates.turnNumber) end
					end
				end


				--Read all objects found in play area. Used to decide on off states of "End.." buttons, plus fame and rep gains
				local timeBending=false
				local avatarLocation=turnOrder[gStates.turnNumber].avatarLocation
				for a, b in pairs(gStates.gainList) do b.exists=false end
				if gStates.preEndTurn==false then
					local hiddenValleyKeep=false
					for _, obj in pairs(playerCombatObjects(turnOrder[gStates.turnNumber].seatPos)) do
						--Read Monster tokens in the current player's Play/Unit areas and update fame and reputation gain values.
						if obj.guid=="2eb8e2" then timeBending=true end
						if monsterPugs[obj.guid]~=nil and gStates.summonStates[obj.guid]~="summoned" and monsterPugs[obj.guid].pugType~="possessed" then
							local doMath=false
							local cityRepLoss=false
							for cityguid, monsters in pairs(gStates.cityMonsterQty) do
								if monsters[obj.guid]=="alive" then cityRepLoss=true break end
							end
							--If no entry found create a new entry for this token
							if gStates.gainList[obj.guid]==nil then
								--record token orientation and do the math if face up.
								gStates.gainList[obj.guid]={exists=true, siteRepLoss=0, keepHalfFame=false}
								if obj.is_face_down==false then
									gStates.gainList[obj.guid].tokenDirection=1
									doMath=true
								else
									gStates.gainList[obj.guid].tokenDirection=-1
								end
								--store leader overkil value
								if obj.guid==darkCrusader.token or obj.guid==elementalist.token then gStates.gainList[obj.guid].overkill=0 end
								--just existing is enough orientation has no effect
								--city rep loss
								for cityguid, monsters in pairs(gStates.cityMonsterQty) do
									if cityguid~=darkCrusader.terrainHex and cityguid~=elementalist.terrainHex and cityguid~=volkare.model and cityguid~=volkare.terrainHex and monsters[obj.guid]=="alive" and gStates.gainList[cityguid]==nil then
									 	turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1
										gStates.gainList[cityguid]={exists=true}
										if monsters.extra.megapolisPair~=nil and monsters.extra.megapolisPair~=cityguid then gStates.gainList[monsters.extra.megapolisPair]={exists=true} end
										break
									end
								end
								--Mage Tower and keep rep loss
								local count=0
								for c, d in pairs(gStates.gainList) do
									if c==gStates.hiddenValleyKeep[1] or c==gStates.hiddenValleyKeep[2] then count=count+1 end
								end
								if count==2 then hiddenValleyKeep=true end
								if cityRepLoss==false and
								   ((monsterPugs[obj.guid].pugType=="gray" and avatarLocation=="keep") or
	   							   (monsterPugs[obj.guid].pugType=="purple" and avatarLocation=="mage tower") or
								   ((obj.guid==gStates.hiddenValleyKeep[1] or obj.guid==gStates.hiddenValleyKeep[2]) and hiddenValleyKeep==false)) then
									turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1
									gStates.gainList[obj.guid].siteRepLoss=1
									if obj.guid==gStates.hiddenValleyKeep[1] or obj.guid==gStates.hiddenValleyKeep[2] then hiddenValleyKeep=true end
								end
								--monastery rep loss
								if avatarLocation~=nil then
									if monsterPugs[obj.guid].pugType=="purple" and gStates.monsterPlayLocation[obj.guid]==nil and avatarLocation=="monastery" then
										turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-3
										gStates.gainList[obj.guid].siteRepLoss=3
									end
								end
								--Keep defenders use half Fame; remember this so reset does not depend on the avatar still being on the Keep.
								gStates.gainList[obj.guid].keepHalfFame=gStates.monsterPlayLocation[obj.guid]==nil and monsterPugs[obj.guid].pugType=="gray" and avatarLocation=="keep"
							end
							--existing token found, but it has been flipped
							if (obj.is_face_down==false and gStates.gainList[obj.guid].tokenDirection==-1)
							or (obj.is_face_down==true and gStates.gainList[obj.guid].tokenDirection==1) then
								gStates.gainList[obj.guid].tokenDirection=gStates.gainList[obj.guid].tokenDirection*-1
								doMath=true
							end
							--mines liberation corect fame and rep
							local minesLibMonster=false
							for terrainguid, monsters in pairs(gStates.mineMonsterQty) do
								if monsters[obj.guid]~=nil and gStates.gameScenario~="The Hidden Valley Blitz" then
									minesLibMonster=true--current monster has come from a mine
									if gStates.gameScenario~="The Realm of the Dead Blitz" then
										for monsterGUID, state in pairs(monsters) do
											if monsterGUID~=obj.guid then--found second mine monster
												if (state=="alive" and gStates.gainList[monsterGUID]~=nil) or state=="dead" then
													local x=1
													if terrainTiles[terrainguid].tileType=="core" then x=2 end--and gStates.gameScenario~="Mines Liberation"
													if gStates.gainList[terrainguid]==nil then
														gStates.gainList[terrainguid]={exists=true}
														gStates.gainList[terrainguid].tokenDirection=-1
														if gStates.gainList[obj.guid].tokenDirection==1 and (state=="dead" or gStates.gainList[monsterGUID].tokenDirection==1) then
															gStates.gainList[terrainguid].tokenDirection=1
															turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(x*gStates.gainList[terrainguid].tokenDirection)
														end
													else
														gStates.gainList[terrainguid].exists=true
														if (gStates.gainList[obj.guid].tokenDirection==1 and (state=="dead" or gStates.gainList[monsterGUID].tokenDirection==1) and gStates.gainList[terrainguid].tokenDirection==-1)
														or ((gStates.gainList[obj.guid].tokenDirection==-1 or (state=="alive" and gStates.gainList[monsterGUID].tokenDirection==-1)) and gStates.gainList[terrainguid].tokenDirection==1) then
															gStates.gainList[terrainguid].tokenDirection=gStates.gainList[terrainguid].tokenDirection*-1
															turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(x*gStates.gainList[terrainguid].tokenDirection)
														end
													end
													break
												end
											end
										end
									end
									break
								end
							end
							--Check if leader Overkill Changed
							if gStates.gainList[obj.guid].overkill~=nil and gStates.gainList[obj.guid].overkill~=gStates.leaderOverkill and obj.is_face_down==false then doMath=true end
							--if allowed add or subtract fame and reputation
							if doMath==true then
								--All tokens Fame
								if gStates.gainList[obj.guid].keepHalfFame==true then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(math.ceil(monsterPugs[obj.guid].fame/2)*gStates.gainList[obj.guid].tokenDirection)
								else
									local multiple=1
									if obj.guid==darkCrusader.token or obj.guid==elementalist.token then
										if gStates.gainList[obj.guid].overkill~=gStates.leaderOverkill then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-(monsterPugs[obj.guid].fame*gStates.gainList[obj.guid].overkill) end
										multiple=gStates.leaderOverkill
										gStates.gainList[obj.guid].overkill=gStates.leaderOverkill
									end
									if gStates.druidNightsSummon~=nil then multiple=2 end
									local perks=0
									if gStates.monsterPerks[obj.guid]~=nil and gStates.monsterPerks[obj.guid].fame~=nil then perks=gStates.monsterPerks[obj.guid].fame end
									local questFame=monsterPugs[obj.guid].fame+perks
									--Dragon heads use custom reward resolution: airborne gives Round Fame once, while
									--landed heads give 1 Fame for each selected level reduction at combat cleanup.
									if gStates.monsterPerks[obj.guid]~=nil and (gStates.monsterPerks[obj.guid].dragonAirborne==true or gStates.monsterPerks[obj.guid].dragonGround==true) then questFame=0 end
									if gStates.monsterPerks[obj.guid]~=nil and gStates.monsterPerks[obj.guid].questHalfFame==true then questFame=math.ceil(questFame/2) end
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(questFame*multiple*gStates.gainList[obj.guid].tokenDirection)
								end
								local rewardPug,rewardPerk=monsterFactionRewardFameFallback(obj.guid)
								if rewardPug>0 or rewardPerk>0 then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+((rewardPug+rewardPerk)*gStates.gainList[obj.guid].tokenDirection)
									if gStates.druidNightsSummon~=nil then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+(rewardPug*gStates.gainList[obj.guid].tokenDirection) end
								end
								--Rampaging Reputation
								if gStates.monsterPlayLocation[obj.guid]~=nil and minesLibMonster==false and cityRepLoss==false and (gStates.ruinMonsters==nil or gStates.ruinMonsters[obj.guid]==nil) and
									(gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[obj.guid]~=true) and
									obj.guid~=gStates.hiddenValleyKeep[1] and obj.guid~=gStates.hiddenValleyKeep[2] then
									if monsterPugs[obj.guid].pugType=="green" or monsterPugs[obj.guid].pugType=="tan" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(1*gStates.gainList[obj.guid].tokenDirection) end --Why do I have Tan??
									if monsterPugs[obj.guid].pugType=="red" and gStates.gameScenario~="The Lost Relic Blitz" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(2*gStates.gainList[obj.guid].tokenDirection) end
								end
								--add hero and thug reputation
								if monsterPugs[obj.guid].reputation~=nil and (gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[obj.guid]~=true) then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+(monsterPugs[obj.guid].reputation*gStates.gainList[obj.guid].tokenDirection) end
							end
							gStates.gainList[obj.guid].exists=true
						end
					end
					--if a token has been removed subtract it's values
					hiddenValleyKeep=false
					for a, b in pairs(gStates.gainList) do
						if b.exists==false and monsterPugs[a]~=nil then
							local cityRepLoss=false
							for cityguid, monsters in pairs(gStates.cityMonsterQty) do
								if monsters[a]=="alive" then cityRepLoss=true break end
							end
							if b.tokenDirection==1 then
								--fame
								if b.keepHalfFame==true then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-math.ceil(monsterPugs[a].fame/2)
								else
									local multiple=1
									if a==darkCrusader.token or a==elementalist.token then multiple=gStates.leaderOverkill end
									if gStates.druidNightsSummon~=nil then multiple=2 end
									local perks=0
									if gStates.monsterPerks[a]~=nil and gStates.monsterPerks[a].fame~=nil then perks=gStates.monsterPerks[a].fame end
									local questFame=monsterPugs[a].fame+perks
									--Dragon rewards are owned by their custom combat tracker. Mirror the add-side suppression
									--here so removing a Dragon head cannot subtract ordinary monster Fame behind its back.
									if gStates.monsterPerks[a]~=nil and (gStates.monsterPerks[a].dragonAirborne==true or gStates.monsterPerks[a].dragonGround==true) then questFame=0 end
									if gStates.monsterPerks[a]~=nil and gStates.monsterPerks[a].questHalfFame==true then questFame=math.ceil(questFame/2) end
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-(questFame*multiple)
								end
								local rewardPug,rewardPerk=monsterFactionRewardFameFallback(a)
								if rewardPug>0 or rewardPerk>0 then
									turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-rewardPug-rewardPerk
									if gStates.druidNightsSummon~=nil then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain-rewardPug end
								end
								--Mine Liberation Reputation gStates.gameScenario=="Mines Liberation"
								local minesLibMonster=false
								for terrainguid, monsters in pairs(gStates.mineMonsterQty) do
									if monsters[a]~=nil then
										minesLibMonster=true--current monster has come from a mine
										if gStates.gainList[terrainguid]~=nil and gStates.gainList[terrainguid].tokenDirection==1 then
											local x=1
											if terrainTiles[terrainguid].tileType=="core" then x=2 end
											turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-x
											gStates.gainList[terrainguid]=nil
										end
										break
									end
								end
								--Rampaging reputation
								if gStates.monsterPlayLocation[a]~=nil and minesLibMonster==false and cityRepLoss==false and (gStates.ruinMonsters==nil or gStates.ruinMonsters[a]==nil) and
									(gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[a]~=true) and
									a~=gStates.hiddenValleyKeep[1] and a~=gStates.hiddenValleyKeep[2] then
									if monsterPugs[a].pugType=="green" or monsterPugs[a].pugType=="tan" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-1 end
									if monsterPugs[a].pugType=="red" and gStates.gameScenario~="The Lost Relic Blitz" then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-2 end
								end
								--Hero and thug reputation
								if monsterPugs[a].reputation~=nil and (gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[a]~=true) then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain-monsterPugs[a].reputation end
							end
							--City monsters
							for cityguid, monsters in pairs(gStates.cityMonsterQty) do
								if cityguid~=darkCrusader.terrainHex and cityguid~=elementalist.terrainHex and monsters[a]=="alive" and gStates.gainList[cityguid]~=nil then
									local found=false
									for monsterGUID, state in pairs(monsters) do
										if gStates.gainList[monsterGUID]~=nil then
											if gStates.gainList[monsterGUID].exists==true then found=true end
										end
									end
									if found==false then
										turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+1
										gStates.gainList[cityguid]=nil
										if monsters.extra.megapolisPair~=nil and monsters.extra.megapolisPair~=cityguid then gStates.gainList[monsters.extra.megapolisPair]=nil end
									end
									break
								end
							end
							--Refund the exact temporary Keep/Mage Tower/Hidden Valley/Monastery assault loss applied when this token entered combat.
							--The avatar may already have been moved away to cancel/reset the combat, so do not re-check avatarLocation here.
							if (b.siteRepLoss or 0)>0 then turnOrder[gStates.turnNumber].repGain=turnOrder[gStates.turnNumber].repGain+b.siteRepLoss end
							gStates.gainList[a]=nil
						end
					end
					--Cap the gain values if exceeding limits
					if turnOrder[gStates.turnNumber].fameGain<0 then turnOrder[gStates.turnNumber].fameGain=0 end
				end


				--Change End turn button text if level up expected
				if gStates.coopAssaultPhase~="combat" and (fameForUp<=turnOrder[gStates.turnNumber].fameGain or turnOrder[gStates.turnNumber].levelUp>0) and turnOrder[gStates.turnNumber].fame<gStates.scoreIfLooped and fameVerticle<gStates.rowsOnBoard then
					UI.setAttribute("EndTurnButtonText", "text", "{en}End Turn & Level Up{ru}Конец хода и Повышение уровня{zh-tw}結束回合並升級{zh-cn}结束回合并升级{ko}차례 종료 & 레벨 업{es}Fin de turno y Subir Nivel{fr}Fin du Tour et Level Up{pt-br}Finalizar Turno e Subir Nível{de}Zug beenden und aufleveln")
					UI.setAttribute("EndTurnButtonAltText", "text", "{en}End Turn & Level Up{ru}Конец хода и Повышение уровня{zh-tw}結束回合並升級{zh-cn}结束回合并升级{ko}차례 종료 & 레벨 업{es}Fin de turno y Subir Nivel{fr}Fin du Tour et Level Up{pt-br}Finalizar Turno e Subir Nível{de}Zug beenden und aufleveln")
					local expectedFame=turnOrder[gStates.turnNumber].fame+turnOrder[gStates.turnNumber].fameGain
					local excessLevels=math.floor(math.sqrt(expectedFame+1))-turnOrder[gStates.turnNumber].level
					expectedFame=expectedFame+(1*excessLevels*gStates.blitz)
					excessLevels=math.floor(math.sqrt(expectedFame+1))-turnOrder[gStates.turnNumber].level
					if excessLevels>1 then
						UI.setAttribute("EndTurnButtonText", "text", joinLang({"{en}End Turn & {ru}Конец хода и {zh-tw}結束回合 & {zh-cn}结束回合 & {ko}차례 종료 & {es}Fin de Turno & {fr}Fin du tour & {pt-br}Fim do turno & {de}Zug beenden & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-tw} 等提升{zh-cn} 等提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de}Stufenaufstiege"}))
						UI.setAttribute("EndTurnButtonAltText", "text", joinLang({"{en}End Turn & {ru}Конец хода и {zh-tw}結束回合 & {zh-cn}结束回合 & {ko}차례 종료 & {es}Fin de Turno & {fr}Fin du tour & {pt-br}Fim do turno & {de}Zug beenden & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-tw} 等提升{zh-cn} 等提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de}Stufenaufstiege"}))
					end
					if nextPlayerEndCalled==true then
						UI.setAttribute("EndTurnButtonText", "text", "End Turn, Rnd & Lev Up")
						UI.setAttribute("EndTurnButtonAltText", "text", "End Turn, Rnd & Lev Up")
						if excessLevels>1 then
							UI.setAttribute("EndTurnButtonText", "text", joinLang({"{en}End Turn, Rnd & {ru}Конец хода, Раунда и {zh-tw}結束回合，輪次 & {zh-cn}结束回合，轮次 & {ko}차례 및 라운드 종료 & {es}Fin de turno, ronda y {fr}Fin du tour, Rnd & {pt-br}Fim de turno, ronda & {de}Zug, Runde beenden & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-tw} 等提升{zh-cn} 等提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de}Stufenaufstiege"}))
							UI.setAttribute("EndTurnButtonAltText", "text", joinLang({"{en}End Turn, Rnd & {ru}Конец хода, Раунда и {zh-tw}結束回合，輪次 & {zh-cn}结束回合，轮次 & {ko}차례 및 라운드 종료 & {es}Fin de turno, ronda y {fr}Fin du tour, Rnd & {pt-br}Fim de turno, ronda & {de}Zug, Runde beenden & ", excessLevels, "{en} Level Ups{ru} Повышения уровня{zh-tw} 等提升{zh-cn} 等提升{ko} 레벨 업{es} Subidas de nivel{fr} Montée en niveau{pt-br} Subidas de nível{de}Stufenaufstiege"}))
						end
					end
				end


				local function defeatedElementalistRampagerThisTurn()
					if gStates.gameScenario~="The Hidden Valley Blitz" then return false end
					for guid, gain in pairs(gStates.gainList or {}) do
						if gain.tokenDirection==1 and gStates.rampagingMonsters~=nil and gStates.rampagingMonsters[guid]==true and monsterEffectiveFaction(guid)=="Elem" then return true end
					end
					return false
				end

				--Change Reward text to be player location sensitive
				local rewardChecklistActive=(gStates.preEndTurn==true and gStates.coopAssaultPhase~="combat") or gameOver==true
				if rewardChecklistActive then
					local count=1
					local rewardText="{en}Have you:-\n{ru}Проверьте, что вы:-\n{zh-tw}你是否已經：\n{zh-cn}你是否已经：\n{ko}차례 종료 과정 진행:-\n{es}Has:-\n{fr}Avez-vous:-\n{pt-br}Você já:-\n{de}Hast du:-\n"
					local linefeed=false
					if gStates.gameScenario=="Mines Liberation" and gStates.endRoundCalled==true and gStates.turnForfeited==false then
						rewardText=joinLang({rewardText, count, "{en}. Collected 1 Crystal from your Liberated Mine(s){ru}. Получили 1 кристалл из ваших освобожденных шахт{zh-tw}. 從你解放的礦山獲得 1 顆魔晶{zh-cn}. 从你解放的矿山获得 1 块魔晶{ko}. 해방한 광산에서 수정 1개 획득{es}. Obtenido 1 Cristal de tus Minas liberadas{fr}. Obtenu 1 cristal de vos Mines libérées{pt-br}. Ganhou 1 Cristal das suas Minas libertadas{de}. 1 Kristall aus deinen befreiten Minen erhalten"})
						count=count+1 linefeed=true
					end
					if gStates.gameScenario=="Druid Nights" and gStates.druidNightsSummon~=nil then
						local crystalReward=gStates.druidNightsCrystalReward or gStates.druidNightsSummon
						rewardText=joinLang({rewardText, count, "{en}. Gained ", tostring(crystalReward), "{en} Random Crystal(s) from incantation"})
						count=count+1 linefeed=true
					end
					if defeatedElementalistRampagerThisTurn()==true then
						rewardText=joinLang({rewardText, count, ". Explored (Defeated Elementalist)"})
						count=count+1 linefeed=true
					end
					if avatarLocation~=nil then
						--see if a matching shield is near the avatar
						local function findNearOwnShield()
							local nearOwnShield="false"
							local avPos=mageKnightAvatarPosition(gStates.turnNumber) or {}
							if (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") and
								gStates.volkareModel~=nil and getObjectFromGUID(gStates.volkareModel)~=nil and math.sqrt(((getObjectFromGUID(gStates.volkareModel).getPosition()[1]-avPos[1])^2)+((getObjectFromGUID(gStates.volkareModel).getPosition()[3]-avPos[3])^2))<1 then
								return volkare.model
							end
							if avatarLocation:sub(1, 4)=="city" or avatarLocation=="Volkare's Camp" or avatarLocation=="necropolis" or avatarLocation=="hidden valley" then
								refreshCityDefeatState()
								--check if avatar dropped on city card, then use the city model as the avatar location
								for zone, citySearch in pairs(cityScriptZones) do
									for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
										for _, avatar in pairs(mageKnights) do
											if detail.guid==avatar.model or detail.guid==avatar.standee or detail.guid==avatar.token then
												if zone==volkare.discZone and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") then
													return volkare.model
												else
													return citySearch.cityGUID
												end
											end
										end
									end
								end
							end
							for _, shieldCheck in pairs(getObjectFromGUID(mapArea).getObjects()) do
								if ((shieldCheck.getName()=="Shield" and volkarePursuitShieldRegistered(shieldCheck)~=true and shieldCheck.getDescription()==turnOrder[gStates.turnNumber].mage) or shieldCheck.getName()=="Hidden Valley" or shieldCheck.getName()=="Necropolis" or shieldCheck.getName()=="Volkare's Camp" or shieldCheck.getName()=="Volkare" or shieldCheck.getGMNotes()=="White City" or shieldCheck.getGMNotes()=="Red City" or shieldCheck.getGMNotes()=="Green City" or shieldCheck.getGMNotes()=="Blue City") and
									math.sqrt(((shieldCheck.getPosition()[1]-avPos[1])^2)+((shieldCheck.getPosition()[3]-avPos[3])^2))<1 then
									nearOwnShield=shieldCheck.guid break
								end
							end
							return nearOwnShield
						end
						local nearbyOwnShield=findNearOwnShield()

						--Victory Shield
						if (avatarLocation=="glade" and gStates.gameScenario=="Druid Nights") then
							if nearbyOwnShield=="false" and gStates.turnForfeited==false then
								rewardText=joinLang({rewardText, count, "{en}. Placed a Victory Shield{ru}. Разместили Жетон щита{zh-tw}. 放置勝利盾徽{zh-cn}. 放置胜利盾徽{ko}. 방패 토큰 놓기{es}. Colocado un Escudo de Conquista.{fr}. Placé un Bouclier de Victoire{pt-br}. Colocou um Escudo de Vitória.{de}. Einen Siegesschild platziert"})
								count=count+1 linefeed=true
							end
						end
						--Victory Shield
						if avatarLocation=="graveyard" and gStates.gameScenario=="The Realm of the Dead Blitz" and nearbyOwnShield=="false" and gStates.turnForfeited==false then
							rewardText=joinLang({rewardText, count, "{en}. Paid to Seal the Graveyard{ru}. Заплатили за запечатывание Кладбища{zh-tw}. 支付魔力來封印墓地{zh-cn}. 支付魔力来封印墓地{ko}. 묘지 봉인 마나 지불(선택){es}. Pagado para Sellar el Cementerio{fr}. Payé pour Sceller le Cimetière{pt-br}Pago para Selar o Cemitério{de}. Für die Versiegelung des Friedhofs bezahlt."})
							count=count+1 linefeed=true
						end
						if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
						--The retreat checklist can run before faction-state bookkeeping finishes. Use the real leader state,
						--and also detect a defeat already committed by the current combat but still waiting for cleanup.
						local coopLeaderCombat=gStates.coopAssaultPhase=="combat" and coopAssaultTargetType()=="leader"
						local leaderDefeatedPendingCleanup=false
						local factionLeaderDefeated=false
						if avatarLocation=="necropolis" or avatarLocation=="hidden valley" then
							local currentLeader=avatarLocation=="necropolis" and darkCrusader or elementalist
							local leaderLevel=avatarLocation=="necropolis" and gStates.darkCrusaderLevel or gStates.elementalistLevel
							factionLeaderDefeated=(leaderLevel or 1)<=0 or (gStates.cityMonsterQty[currentLeader.terrainHex]~=nil and gStates.cityMonsterQty[currentLeader.terrainHex][currentLeader.token]=="dead") or (gStates.defeatedFactionTest~=nil and gStates.defeatedFactionTest[currentLeader.terrainHex]=="Beat")
							local leaderObj=getObjectFromGUID(currentLeader.token)
							if factionLeaderDefeated==false and leaderObj~=nil and leaderObj.is_face_down==false and leaderLevel~=nil and ((gStates.leaderReduction or 0)+(gStates.leaderOverkill or 0))>=leaderLevel then
								for _, obj in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
									if obj.guid==currentLeader.token then leaderDefeatedPendingCleanup=true break end
								end
							end
						end
						local dragonRetreatRequired=false
						if gStates.apocalypseDragonDefeated~=true and apocalypseDragonLairContainsPosition~=nil then
							local dragonAvatarPos=mageKnightAvatarPosition(gStates.turnNumber)
							dragonRetreatRequired=dragonAvatarPos~=nil and apocalypseDragonLairContainsPosition(dragonAvatarPos)==true
						end
						if gStates.turnForfeited==false and
							(dragonRetreatRequired==true or
							((avatarLocation=="keep" or avatarLocation=="mage tower") and nearbyOwnShield=="false") or
							((avatarLocation:sub(1, 4)=="city" or avatarLocation=="Volkare's Camp") and gStates.friendlyCity[nearbyOwnShield]~=true and ((gStates.gameScenario~="The Lost Relic Blitz" and gStates.defeatedCities[nearbyOwnShield]~=true) or (gStates.gameScenario=="The Lost Relic Blitz" and nearbyOwnShield=="false"))) or
							((avatarLocation=="necropolis" or avatarLocation=="hidden valley") and coopLeaderCombat==false and leaderDefeatedPendingCleanup==false and factionLeaderDefeated==false) or
							(nearbyOwnShield==volkare.model)) then
							rewardText=joinLang({rewardText, count, "{en}. Retreated to a Safe space{ru}. Отступили в Безопасное место{zh-tw}. 撤離到一個安全位置{zh-cn}. 撤离到一个安全位置{ko}. 안전한 칸으로 후퇴{es}. Acabado en un Espacio Seguro{fr}. Retraité dans un espace sûr{pt-br}. Recuou para um espaço seguro{de}. Dich in ein sicheres Feld zurückgezogen"})
							count=count+1 linefeed=true
						end
						if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
						if gStates.turnForfeited==false and gladeFreeCheck()==true and (avatarLocation=="glade" or avatarLocation=="hidden valley" or
						(gStates.gameScenario=="The War of Four" and (avatarLocation=="necropolis" or avatarLocation=="graveyard"))) then
							rewardText=joinLang({rewardText, count, "{en}. Removed One Wound{ru}. Вернули в стопку одну рану{zh-tw}. 移除一點創傷{zh-cn}. 移除一点创伤{ko}. 부상 하나 제거{es}. Eliminado una Herida{fr}. Suppression d'une blessure{pt-br}. Removeu Um Ferimento{de}. Eine Wunde wurde entfernt"})
							count=count+1 linefeed=true
						end
						if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
						if gStates.turnForfeited==false and ((gStates.shieldsDropped[nearbyOwnShield]~=nil and (avatarLocation=="mage tower" or avatarLocation=="labyrinth"	or avatarLocation=="maze" or avatarLocation=="monastery" or avatarLocation=="monster den" or avatarLocation=="dungeon" or avatarLocation=="spawning grounds" or avatarLocation=="tomb" or avatarLocation=="ziggurat" or avatarLocation=="pyramid"
						or (avatarLocation=="ruin" and gStates.crytalRuin~=true)
						or ((avatarLocation=="graveyard" or avatarLocation=="glade") and gStates.gameScenario=="Life and Death")))
						or (avatarLocation=="graveyard" and gStates.gameScenario=="The Realm of the Dead Blitz")) then
							rewardText=joinLang({rewardText, count, "{en}. Gained Site Conquest Rewards{ru}. Получили награды за завоевание Места{zh-tw}. 獲得地點的征服獎勵{zh-cn}. 获得地点的征服奖励{ko}. 장소 정복 보상 획득{es}. Obtenido la Recompensa de Conquista{fr}. Récompenses de conquête de site obtenues{pt-br}. Ganhou As Recompensas de Conquista{de}. Gewonnene Eroberungsbelohnungen"})
							count=count+1 linefeed=true
						end
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gStates.levelingUp==true then
						if currentPlayer.skipHeroChallengeSkillReminder~=true then
							rewardText=joinLang({rewardText, count, "{en}. Gained a New Skill Token{ru}. Получили новый Жетон навыка{zh-tw}. 獲得新的技能{zh-cn}. 获得新的技能{ko}. 새로운 스킬 획득{es}. Obtuvo una ficha de habilidad nueva{fr}. Vous avez obtenu un nouveau jeton de compétence{pt-br}. Ganhou uma Nova Ficha de Habilidade{de}. Einen neuen Fertigkeitsmarker erhalten"})
							count=count+1 rewardText=joinLang({rewardText, "\n"})
						end
						rewardText=joinLang({rewardText, count, "{en}. Gained a New Advanced Action{ru}. Получили новое Особое действие{zh-tw}. 獲得新的高級行動卡{zh-cn}. 获得新的高级行动卡{ko}. 새로운 상급 액션 획득{es}. Obtuvo una nueva acción avanzada{fr}. Vous avez obtenu une nouvelle action avancée{pt-br}. Ganhou uma Nova Ação Avançada{de}. Eine neue fortgeschrittene Aktion erhalten"})
						count=count+1 linefeed=true
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gStates.volkareArmyReduced==true and gStates.endGameAchieved=="false" and gStates.volkareState=="Attacking City" then
						if gStates.volkareModel~=nil and getObjectFromGUID(gStates.volkareModel)~=nil then getObjectFromGUID(gStates.volkareModel).unlock() end
					end
					if gStates.turnForfeited==true then
						rewardText=joinLang({rewardText, count, "{en}. Forfeit Turn, no site Rewards{ru}. Пропустили ход, и не получаете Награды за Места{zh-tw}. 放棄回合，無地點獎勵{zh-cn}. 放弃回合，无地点奖励{ko}. 차례 포기, 장소 혜택 사용불가{es}. Saltar Turno, sin Recompensas de Lugar{fr}. Forfait Turn, pas de récompenses de site{pt-br}. Desistir do Turno. Sem Recompensas de Local{de}. Zug ausgelassen, keine Ortsbelohnung"})
						count=count+1 linefeed=true
					end
					if linefeed==true then rewardText=joinLang({rewardText, "\n"}) linefeed=false end
					if gameOver==false then
						rewardText=joinLang({rewardText, count, "{en}. Confirmed your hand size{ru}. Проверили предел карт в вашей руке{zh-tw}. 更新你的手牌上限{zh-cn}. 更新你的手牌上限{ko}. 카드 보유 제한 체크{es}. Confirmado tu tamaño de Mano{fr}. Confirmé votre taille de main{pt-br}. Confirmou seu tamanho de Mão{de}. Handkartenzahl bestätigt"})
					else
						rewardText=joinLang({rewardText, count, "{en}. Looked at your final Score{ru}. Посмотрели на ваш окончательный результат{zh-tw}. 查看你的最終分數{zh-cn}. 查看你的最终分数{ko}. 최종 점수 확인{es}. Revisado tu Puntuación Final{fr}. Regardé votre score final{pt-br}. Ollhou para a sua Pontuação Final{de}. Deine Endpunktzahl angesehen"})
					end
					UI.setAttribute("RewardNotes", "text", rewardText)
				end


				--lock end turn button if no cards are played or discarded
				--discard object detection
				local discardAreaCards=0
				for _, b in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
					if b.type=="Card" then discardAreaCards=1 break end
					if b.type=="Deck" then discardAreaCards=b.getQuantity() break end
				end
				UI.setAttribute("EndTurnButton", "tooltip", "At least one card must be played or discarded to 'End Your Turn'.")
				if gStates.endRoundCalled==true then UI.setAttribute("EndTurnButton", "tooltip", "") end
				local coopCombatButtonLocked=gStates.coopAssaultPhase=="combat" and (gStates.preEndTurn==true or playerAreaCardCount<1)
				if (playerAreaCardCount<1 and gStates.endRoundCalled==false and discardAreaCards==turnOrder[gStates.turnNumber].discardCount) or coopCombatButtonLocked or gStates.tacticShown==true or gStates.tacticRemove==true then
					UI.setAttribute("EndTurnButton", "interactable", "False")
					UI.setAttribute("EndTurnButtonImage", "image", "Sliced Button/Button New Deactive")
					UI.setAttribute("EndTurnButtonAlt", "interactable", "False")
					UI.setAttribute("EndTurnButtonAltImage", "image", "Sliced Button/Button New Deactive")
					UI.setAttribute("ExtraTurnTacticButton", "interactable", "False")
					UI.setAttribute("ExtraTurnTacticButtonImage", "image", "Sliced Button/Button New Deactive")
				end

				--Show extra-turn button. If Time Bending and Day Tactic 6 are both available, ask which one is being used.
				local tacticSixAvailable=turnOrder[gStates.turnNumber].tactic==6 and gStates.dayRound==true and gStates.tacticSixState~="Used"
				local timeBendingAvailable=timeBending==true
				if (tacticSixAvailable or timeBendingAvailable) and gStates.tacticRemove==false and gStates.tacticShown==false then
					UI.setAttribute("ExtraTurnTactic", "active", "true")
					if tacticSixAvailable and timeBendingAvailable then
						UI.setAttribute("ExtraTurnTacticButtonText", "text", "{en}Extra Turn{ru}Дополнительный ход{zh-tw}額外回合{zh-cn}额外回合{ko}추가 턴{es}Turno Extra{fr}Tour Supplémentaire{pt-br}Turno Extra{de}Extra-Zug")
					elseif timeBendingAvailable then
						UI.setAttribute("ExtraTurnTacticButtonText", "text", "{en}Time Bend{ru}Изгиб Времени{zh-tw}時間扭曲{zh-cn}时间扭曲{ko}시간 왜곡{es}Salto en el Tiempo{fr}Courbe du Temps{pt-br}Dobrar Tempo{de}Zeitkrümmung")
					else
						UI.setAttribute("ExtraTurnTacticButtonText", "text", "{en}Use Tactic{ru}Использовать Тактику{zh-tw}使用戰術卡{zh-cn}使用战术卡{ko}전략카드 사용{es}Usar la Táctica{fr}Utiliser la Tactique{pt-br}Usar Tática{de}Taktik Benutzen")
					end
				end

				--Update Fame and Reputation menus only when their displayed values change.
				local fameRepPlayer=turnOrder[gStates.turnNumber]
				local fameRepKey=table.concat({gStates.turnNumber, fameRepPlayer.fameGain, fameRepPlayer.repGain, fameRepPlayer.reputation}, "|")
				if endTurnFameRepCache~=fameRepKey then
					endTurnFameRepCache=fameRepKey
					local limetedRepGain=fameRepPlayer.repGain
					if limetedRepGain<(-7-fameRepPlayer.reputation) then limetedRepGain=(-7-fameRepPlayer.reputation) end
					if limetedRepGain>(7-fameRepPlayer.reputation) then limetedRepGain=(7-fameRepPlayer.reputation) end
					UI.setAttribute("EndRoundPlusFameText", "text", joinLang({"{en}Gain {ru}Получить {zh-tw}增加 {zh-cn}增加 {ko}획득 {es}Ganar {fr}Gagner {pt-br}Ganhe {de}Erhalte ", tostring(fameRepPlayer.fameGain), "{en} Fame{ru} Славу(ы){zh-tw} 名望{zh-cn} 名望{ko} 명성{es} Fama{fr} Gloire{pt-br} Fama{de} Ruhm"}))
					local prefix="{en}Lose {ru}Потерять {zh-tw}減少 {zh-cn}减少 {ko}감소 {es}Perder {fr}Perdez {pt-br}Perca {de}Verliere "
					if limetedRepGain>-1 then prefix="{en}Gain {ru}Получить {zh-tw}增加 {zh-cn}增加 {ko}획득 {es}Ganar {fr}Gagner {pt-br}Ganhe {de}Erhalte " end
					local sufix1="{en} Reputation{ru} Репутацию(и){zh-tw} 聲譽{zh-cn} 声誉{ko} 평판{es} Reputación{fr} Réputation{pt-br} Reputação{de} Ansehen"
					if limetedRepGain~=0 and (limetedRepGain<=(-7-fameRepPlayer.reputation) or limetedRepGain>=(7-fameRepPlayer.reputation)) then
						sufix1="{en} Rep. Max.{ru} Макс. Реп.{zh-tw} 聲譽到最底{zh-cn} 声誉到最底{ko} 최대 평판{es} Rep. Máx.{fr} Rép. Max.{pt-br} Rep. Máx.{de} Ruf Max."
					end
					local sufix2=""
					if limetedRepGain~=0 and reputationTable[fameRepPlayer.reputation+limetedRepGain]~=nil then
						sufix2=" ('"..reputationTable[fameRepPlayer.reputation+limetedRepGain].repDisplay.."')"
						if fameRepPlayer.reputation+limetedRepGain<=-7 then sufix2=" ('X')" end
					end
					UI.setAttribute("EndRoundPlusRepText", "text", joinLang({prefix, tostring(math.abs(limetedRepGain)), sufix1, sufix2}))
				end
			end


			--Deed-pile events refresh End Round directly. During routine play/discard object updates,
			--played-card count only matters once the current deed pile is actually empty.
			local routineZoneUpdate=source=="Object entered into play area" or source=="Object removed from zone"
			local currentSeat=turnOrder[gStates.turnNumber].seatPos
			if routineZoneUpdate~=true or endRoundDeedHasCards[currentSeat]~=true then refreshEndRoundState(playerAreaCardCount) end


			local notice=false
			local UIColor=positionToColor(gStates.turnNumber)
			--Display Info Pannel if pursuing monsters have two options.
			if gStates.pursuitTwoOption==true then
				UI.setAttribute("NoticeText", "Text", "{en}Pursuing Monster(s) have two Options for the current Player to decide between.{ru}Игрок, чьего героя преследуют, решает, на какую из двух клеток переместится враг.{zh-cn}追击的怪物有两个选项供当前玩家选择. {ko}현재 플레이어는 추적 중인 몬스터의 두 옵션 중 하나를 결정하세요.{es}Los Monstruos que persiguen tienen dos Opciones para que el Jugador actual decida entre ellas.{fr}Les Monstres Poursuivants ont deux Options entre lesquelles le Joueur actuel doit choisir.{pt-br}Monstro(s) Perseguidor(es) tem 2 opções para o jogador atual escolher.{de}Verfolgende Monster haben zwei Optionen, zwischen denen der aktuelle Spieler wählen kann.")
				UI.setAttribute("NoticeBoard", "visibility", "")
				UI.setAttribute("NoticeBoard", "height", "50")
				notice=true
			end

			--Display Info pannel if player needs to deploy a tomb or dungeon token
			if #gStates.locationPlace>0 then
				local pendingSecretName=dungeonLordsPendingSecretName(gStates.locationPlace[#gStates.locationPlace])
				local site="{en}Village{ru}Деревней{zh-cn}\n要求2: 挨着刚翻开的村庄{ko}마을{es}una Aldea{fr}Village{pt-br}Vila{de}Dorf"
				if pendingSecretName=="Secret Tomb" then site="{en}Monastery{ru}Монастырем{zh-cn}\n要求2: 挨着刚翻开的修道院{ko}수도원{es}un Monasterio{fr}Monastère{pt-br}Mosteiro{de}Kloster" end
				UI.setAttribute("NoticeText", "Text", joinLang({"{en}Place a {ru}Поместите жетон {zh-cn}在地图上放置一个{ko}{es}Coloca una ficha de {fr}Placer un{pt-br}Coloque uma ficha de {de}Platziere ein ", translateWord[pendingSecretName], "{en} token on an accessible non-swamp, non-feature space next to the {ru} на любую доступную клетку без болота на которой нет никаких мест, соседнюю с {zh-cn}\n要求1: 可进入、非沼泽、上面无地点{ko}을 비어있고, 늪이 아니면서 다음의 장소 주변인 칸에 설치하세요: {es} en un espacio accesible que no sea un pantano, o no tenga ningún elemento adyacente a {fr} jeton sur un espace non marécageux accessible à côté du {pt-br} em um espaço acessível sem ser pântano ou que já tenha algo próximo a {de} plättchen auf ein zugängliches Nicht-Sumpf-, Nicht-Feature-Feld neben dem ", site}))
				UI.setAttribute("NoticeBoard", "visibility", "")
				UI.setAttribute("NoticeBoard", "height", "50")
				notice=true
			end

			--Display Info pannel if End of round is immenant
			if ((nextPlayerEndCalled==true and gStates.playerCount>1) or (gStates.endRoundCalled==true and gStates.playerCount==1)) and
				(gStates.preEndTurn==true or turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5]) and gStates.currentRound<gStates.rounds then
				local boxHeight=50
				local endRoundText="{en}The game is about to experience end of round updates.\nPut Banners in discard if desired.{ru}Конец раунда. Скрипт произведет нужные обновления.\nЕсли хотите, можете сбросить знамёна с отрядов.{zh-cn}回合即将结束, 如果需要, 将清理弃牌区{ko}이제 라운드가 종료됩니다.\n원한다면 지금 깃발 장착을 해제하세요.{es}El juego está a punto de experimentar actualizaciones de fin de ronda.\nDescarte los Banners si lo desea.{fr}Le jeu est sur le point de connaître des mises à jour de fin de manche.\nMettez les bannières au rebut si vous le souhaitez.{pt-br}O jogo está prestes a executar as atualizações de fim de Rodada.<size=6>\n\n</size>Coloque os Estandartes na pilha de descarte se assim desejar.{de}Das Spiel wird zum Ende der Runde aktualisiert.\nLegt die Banner auf den Ablagestapel, falls gewünscht."
				if gStates.playerCount==1 then endRoundText=joinLang({endRoundText, "{en}\nDiscard the 2nd offer if playing 'Control over the Offers'{ru}\nПри 'Контроле над доступными картами', сбросьте среднюю доступную карту{zh-cn}\n如果使用“控制供应区”变体规则, 弃掉最左侧两个供应的卡牌{ko}\n변형 규칙 '공급처 갱신 조정'을 적용하려면 지금 하세요.{es}\nDescarta la segunda oferta si juegas 'Control sobre las Ofertas'{fr}\nJetez la 2e offre si vous jouez à 'Contrôle des Offres'{pt-br}\nDiscarte a 2a oferta se estiver jogando com 'Controle sobre ofertas'{de}\nWirf das 2. Angebot ab, wenn du 'Kontrolle über die Angebote' spielst."}) boxHeight=boxHeight+20 end
				if gStates.gameScenario=="Mines Liberation" then endRoundText=joinLang({endRoundText, "{en}\nCollect 1 Crystal from your liberated Mine(s).{ru}Получите 1 кристалл из каждой освобожденной вами шахты.{zh-cn}从你解放的每个矿山获得 1 块魔晶。{ko}\n해방한 각 광산에서 수정 1개를 얻으세요.{es}\nRecoge 1 Cristal de cada Mina que hayas liberado.{fr}\nRécupérez 1 cristal de chaque Mine que vous avez libérée.{pt-br}\nColete 1 Cristal de cada Mina que você libertou.{de}\nSammle 1 Kristall aus jeder Mine, die du befreit hast."}) boxHeight=boxHeight+20 end
				UI.setAttribute("NoticeBoard", "height", boxHeight)
				UI.setAttribute("NoticeText", "Text", endRoundText)
				UI.setAttribute("NoticeBoard", "visibility", "")
				notice=true
			end

			--Display Info pannel if tactics are shown
			UI.setAttribute("DrawOne", "interactable", "true")
			UI.setAttribute("DrawOneImage", "image", "Sliced Button/Button New Active")
			if gStates.tacticRemove==true or gStates.tacticShown==true then
				if gStates.tacticRemove==true then
					UI.setAttribute("NoticeText", "Text", "{en}Choose tactic(s) to be removed from the Game{ru}Выберите тактику(и), которая будет удалена из игры{zh-cn}选择要从游戏中移除的战术卡{ko}게임에서 제거할 전략 카드를 고르세요.{es}Elige la táctica(s) que quieres eliminar del Juego{fr}Choisissez la tactique(s) à retirer du Jeu{pt-br}Escolha tática(s) a ser(em) removida(s) do jogo.{de}Wähle die Taktik(en), die aus dem Spiel entfernt werden sollen")
				else
					UI.setAttribute("NoticeText", "Text", joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} needs to choose a tactic from the center{ru} должен(на) выбрать Тактику из центра{zh-cn}需要从中间选择一个战术{ko}의 전략 카드를 선택하세요.{es} necesita elegir una táctica del centro{fr} doit choisir une tactique du centre{pt-br} precisa escolher uma tática do centro.{de} muss eine Taktik aus dem Zentrum wählen"}))
				end
				UI.setAttribute("DrawOne", "interactable", "False")
				UI.setAttribute("DrawOneImage", "image", "Sliced Button/Button New Deactive")
				UI.setAttribute("NoticeBoard", "visibility", "")
				UI.setAttribute("NoticeBoard", "height", "50")
				notice=true
			else --turn off help notes after first round of tactic selection
				if gStates.help==true then DisplayHelp(nil, "-1", "Game Started") end
			end

			--Remove or Display the notice board as needed
			if notice==false and gStates.noticeShown==true then
				UI.hide("NoticeBoard")
				gStates.noticeShown=false
			end
			if notice==true and gStates.noticeShown==false then
				UI.show("NoticeBoard")
				gStates.noticeShown=true
			end



			UI.setAttribute("RewardCheck", "active", "false")
			UI.setAttribute("EndGameButton", "active", "false")
			if (gStates.preEndTurn==true and gStates.coopAssaultPhase~="combat") or gameOver==true then
				UI.setAttribute("RewardCheck", "active", "true")
				UI.setAttribute("EndGameButton", "active", "true")
				if gStates.timeBending=="Started" and gStates.turnNumber==gStates.realTurn then--or (gStates.endRoundCalled==true and gStates.currentRound>=gStates.rounds)
					UI.setAttribute("EndGameButton", "active", "false")
				end
			end
			--Steady Tempo must resolve before Rewards Claimed can refresh the hand, because Top can be the next card drawn.
			if steadyTempoUpdateRewardGate~=nil and turnOrder[gStates.turnNumber]~=nil then steadyTempoUpdateRewardGate(turnOrder[gStates.turnNumber].seatPos) end
			if UIColor=="Black" then UIColor="rgb(0,0,0)" end
			UI.setAttribute("MainGameNotes", "color", UIColor)
			UI.setAttribute("RewardNotes", "color", UIColor)


			local currentPlayer=turnOrder[gStates.turnNumber]
			local meditationBonus=(gStates.meditationDrawBonus~=nil and gStates.meditationDrawBonus[gStates.turnNumber]) or 0
			local drawHandSize=currentPlayer.hand+currentPlayer.handBonus+gStates.tactic4HandBonus+meditationBonus
			local cityShields=currentCityShieldInfluence(currentPlayer)
			local handMainKey=table.concat({gStates.turnNumber, currentPlayer.mage, currentPlayer.hand, currentPlayer.handBonus, gStates.tactic4HandBonus, meditationBonus, currentPlayer.baseHand, currentPlayer.reputation, cityShields, currentPlayer.fame, currentPlayer.level, fameForUp, gStates.positionMageKnight[5]}, "|")
			if handMainTextCache~=handMainKey then
				handMainTextCache=handMainKey
				UI.setAttribute("DrawHandText", "text", joinLang({"{en}Draw up to {ru}Добрать до {zh-tw}抽滿至 {zh-cn}抽满至 {ko}카드 보유 제한 {es}Roba hasta {fr}Piochez jusqu'à {pt-br}Compre até {de}Zieh auf ", tostring(drawHandSize), "{en} cards{ru} карт{zh-tw} 張手牌{zh-cn} 张手牌{ko} 장{es} cartas{fr} cartes{pt-br} cartas{de} karten"}))
				UI.setAttribute("DrawHandText", "color", drawHandSize>currentPlayer.baseHand and "rgb(0.4, 0.1, 0.2)" or "Black")
				if currentPlayer.mage~=gStates.positionMageKnight[5] then
					local repDisplay=reputationTable[currentPlayer.reputation].repDisplay
					local repLabel="{en}'s Turn</size><size=6>\n\n</size>Reputation = {ru} Ходит</size><size=6>\n\n</size>Репутация =  {zh-tw}的回合</size><size=6>\n\n</size>聲譽 = {zh-cn}的回合</size><size=6>\n\n</size>声誉 = {ko} 차례</size><size=6>\n\n</size>평판 = {es}</size><size=6>\n\n</size>Reputación = {fr}</size><size=6>\n\n</size>Réputation = {pt-br}</size><size=6>\n\n</size>Reputação = {de}'s Zug</size><size=6>\n\n</size>Ansehen = "
					if cityShields>0 and repDisplay~="No Interaction" then
						local repValue=tonumber(repDisplay) or 0
						repLabel="{en}'s Turn</size><size=6>\n\n</size>Rep Bonus = {ru} Ходит</size><size=6>\n\n</size>Бонус реп. = {zh-tw}的回合</size><size=6>\n\n</size>聲譽加成 = {zh-cn}的回合</size><size=6>\n\n</size>声誉加成 = {ko} 차례</size><size=6>\n\n</size>평판 보너스 = {es}</size><size=6>\n\n</size>Bonif. Rep. = {fr}</size><size=6>\n\n</size>Bonus Rép. = {pt-br}</size><size=6>\n\n</size>Bônus Rep. = {de}'s Zug</size><size=6>\n\n</size>Rufbonus = "
						repDisplay=joinLang({signedBonus(repValue+cityShields), " (", signedBonus(repValue), "{en} Rep + {ru} Реп. + {zh-tw} 聲譽 + {zh-cn} 声誉 + {ko} 평판 + {es} Rep. + {fr} Rép. + {pt-br} Rep. + {de} Ruf + ", cityShields, "{en} City){ru} Город){zh-tw} 城市){zh-cn} 城市){ko} 도시){es} Ciudad){fr} Ville){pt-br} Cidade){de} Stadt)"})
					end
					local mainText=joinLang({"{en}<size=25>{ru}<size=25>{zh-tw}<size=25>{zh-cn}<size=25>{ko}<size=25>{es}<size=25>Turno de {fr}<size=25>Au tour de {pt-br}<size=25>Turno de {de}<size=25>", translateWord[currentPlayer.mage], repLabel, repDisplay, "{en}\nFame = {ru}\nСлава = {zh-tw}\n名望 = {zh-cn}\n名望 = {ko}\n명성 = {es}\nFama = {fr}\nGloire = {pt-br}\nFama = {de}\nRuhm = ", currentPlayer.fame})
					local levelUpType="{en}\n(Skill & Advanced Action){ru}\n(Навык и Особое действие){zh-tw}\n（技能和高級行動）{zh-cn}\n（技能和高级行动）{ko}\n(스킬 및 상급 액션){es}\n(Habilidad y Acción Avanzada){fr}\n(Compétence et Action Avancée){pt-br}\n(Habilidade e Ação Avançada){de}\n(Fähigkeit & Fortgeschrittene Aktion)"
					if currentPlayer.level==2 or currentPlayer.level==4 or currentPlayer.level==6 or currentPlayer.level==8 or currentPlayer.level==10 or currentPlayer.level==12 then levelUpType="{en}\n(Command Token){ru}\n(Жетон командования){zh-tw}\n（指揮標記）{zh-cn}\n（指挥标记）{ko}\n(지휘 토큰){es}\n(Token de Comando){fr}\n(Jeton de Commande){pt-br}\n(Token de Comando){de}\n(Befehlsplättchen)" end
					if fameForUp>0 then mainText=joinLang({mainText, "{en}<size=6>\n\n</size>Next Level in {ru}<size=6>\n\n</size>До повышения уровня {zh-tw}<size=6>\n\n</size>升級還需 {zh-cn}<size=6>\n\n</size>升级还需 {ko}<size=6>\n\n</size>다음 레벨까지 {es}<size=6>\n\n</size>Siguiente nivel en {fr}<size=6>\n\n</size>Niveau suivant dans {pt-br}<size=6>\n\n</size>Próximo Nível em {de}<size=6>\n\n</size>Nächstes Level in ", fameForUp, "{en} Fame{ru} Слава(ы){zh-tw} 名望{zh-cn} 名望{ko} 명성 남음{es} Fama{fr} Gloire{pt-br} Fama{de} Ruhm", levelUpType}) else mainText=joinLang({mainText, "\n "}) end
					UI.setAttribute("MainGameNotes", "text", mainText)
				else
					if proxyPlayerActive()==true then
						UI.setAttribute("MainGameNotes", "text", joinLang({"{en}<size=25>Proxy {ru}<size=25>Прокси {zh-tw}<size=25>代理玩家 {zh-cn}<size=25>代理玩家 {ko}<size=25>프록시 {es}<size=25>Proxy {fr}<size=25>Proxy {pt-br}<size=25>Proxy {de}<size=25>Proxy ", translateWord[currentPlayer.mage], "{en}'s Turn</size>{ru} Ходит</size>{zh-tw}的回合</size>{zh-cn}的回合</size>{ko} 차례</size>{es}</size>{fr}</size>{pt-br}</size>{de}'s Zug</size>"}))
					else
						UI.setAttribute("MainGameNotes", "text", joinLang({"{en}<size=25>Dummy {ru}<size=25>Манекен {zh-tw}<size=25>虛擬玩家 {zh-cn}<size=25>虚拟玩家 {ko}<size=25>더미{es}<size=25>Turno de Maniquí {fr}<size=25>Au tour de Mannequin {pt-br}<size=25>Turno de Manequim {de}<size=25>Dummy ", translateWord[currentPlayer.mage], "{en}'s Turn</size>{ru} Ходит</size>{zh-tw}的回合</size>{zh-cn}的回合</size>{ko} 차례</size>{es}</size>{fr}</size>{pt-br}</size>{de}'s Zug</size>"}))
					end
				end
			end


			automatedMainPanelRefresh()

			UI.setAttribute("PreEndTurn", "onClick", "endTurn")
			if gStates.coopAssaultPhase=="combat" and gStates.preEndTurn==false then
				UI.setAttribute("EndTurnButtonText", "text", "{en}Combat Complete{ru}Бой завершён{zh-tw}戰鬥完成{zh-cn}战斗完成{ko}전투 완료{es}Combate Completo{fr}Combat Terminé{pt-br}Combate Concluído{de}Kampf Abgeschlossen")
				UI.setAttribute("EndTurnButtonAltText", "text", UI.getAttribute("EndTurnButtonText", "text"))
			elseif gStates.coopAssaultPhase=="rewards" then
				local nextText="{en}Finish Co-op Rewards{ru}Завершить совместные награды{zh-tw}完成合作獎勵{zh-cn}完成合作奖励{ko}협력 보상 완료{es}Finalizar Recompensas Coop.{fr}Terminer les Récompenses Coop.{pt-br}Finalizar Recompensas Coop.{de}Koop-Belohnungen Beenden"
				if gStates.coopRewardIndex<#gStates.coopRewardQueue then nextText="{en}Rewards Claimed - Next Reward{ru}Награды получены - Следующая награда{zh-tw}獎勵完成－下一位{zh-cn}奖励完成－下一位{ko}보상 완료 - 다음 보상{es}Recompensas Reclamadas - Siguiente{fr}Récompenses Réclamées - Suivant{pt-br}Recompensas Coletadas - Próximo{de}Belohnungen Beansprucht - Weiter" end
				UI.setAttribute("PreEndTurnText", "text", nextText)
				UI.setAttribute("EndTurnButtonText", "text", "{en}Co-op Rewards{ru}Совместные награды{zh-tw}合作獎勵{zh-cn}合作奖励{ko}협력 보상{es}Recompensas Coop.{fr}Récompenses Coop.{pt-br}Recompensas Coop.{de}Koop-Belohnungen")
				UI.setAttribute("EndTurnButtonAltText", "text", UI.getAttribute("EndTurnButtonText", "text"))
				UI.setAttribute("EndTurnButton", "interactable", "false")
				UI.setAttribute("EndTurnButtonImage", "image", "Sliced Button/Button New Deactive")
				UI.setAttribute("EndTurnButtonAlt", "interactable", "false")
				UI.setAttribute("EndTurnButtonAltImage", "image", "Sliced Button/Button New Deactive")
			end
			UI.setAttribute("ScoreButtonReal", "onClick", "displayScore")
			if gameOver==true then
				UI.setAttribute("PreEndTurn", "onClick", "layoutClaimedCards")
				UI.setAttribute("PreEndTurnText", "text", "{en}Game Over - Show Score{ru}Игра окончена{zh-tw}遊戲結束{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Spiel Beendet")
				UI.setAttribute("DummyButton", "onClick", "layoutClaimedCards")
				UI.setAttribute("DummyButtonText", "Text", "{en}Game Over - Show Score{ru}Игра окончена{zh-tw}遊戲結束{zh-cn}游戏结束{ko}게임 종료{es}Fin de Partida{fr}Jeu Terminé{pt-br}Fim de Jogo{de}Spiel Beendet")
				UI.setAttribute("ScoreButtonReal", "onClick", "layoutClaimedCards")
				local noTurnsLeftToUndoInto=gStates.endRoundCalled==true and nextPlayerEndCalled==true and gStates.currentRound>=gStates.rounds
				local victoryRegistered=false
				for _, turnDetails in pairs(turnOrder) do if turnDetails.gameEnder==true then victoryRegistered=true break end end
				local canUndoVictory=victoryRegistered==true and noTurnsLeftToUndoInto==false
				UI.setAttribute("EndGameButton", "active", canUndoVictory and "true" or "false")
			end


			refreshGladeDiscardHealButton()
			UI.show("MainGame")
			mainUIPause=nil
		end, 0.1)
	end
end

--work out which color hand has the current turns mage
function positionToColor(turnNumber)
	local color="Black"
	local turnDetails=turnOrder[turnNumber]
	if turnDetails==nil then return color end
	if turnDetails.mage~=gStates.positionMageKnight[5] then
		for _, handColor in pairs(Player.getAvailableColors()) do
			local handPlayer=Player[handColor]
			local handTransform=handPlayer~=nil and handPlayer.getHandTransform() or nil
			if handTransform~=nil and handTransform.position~=nil and turnDetails.seatPos==math.ceil((handTransform.position[1]+97.59)/40) then color=handColor break end
		end
	end
	return color
end

--Tactic Showing and Hiding
function tacticToggle()
	--rearanges the turn order tokens
	function turnOrderSort()
		for a=1, #turnOrder, 1 do
			getObjectFromGUID(turnOrder[a].turnOrderTokenGUID).unlock()
			getObjectFromGUID(turnOrder[a].turnOrderTokenGUID).setPositionSmooth({-1.90, 1.2, -18.00-(1.4*a)})
		end
		if againstDragonPositionRoundOrderToken~=nil then againstDragonPositionRoundOrderToken() end
		if apocalypseIsHerePositionRoundOrderToken~=nil then apocalypseIsHerePositionRoundOrderToken() end
	end

	if againstDragonRoundStart~=nil then againstDragonRoundStart() end

	--Show all tactics available
	if gStates.tacticShown==true then
		broadcastToAll("{en}Turn order Re-Organised based on tactic card selection{ru}Порядок хода игроков изменился в соответствии с выбранными Тактиками{zh-cn}玩家行动顺序基于战术卡的选择改变了{ko}라운드 순서가 전략 카드에 따라 배치되었습니다{es}Orden de turnos reorganizado según la selección de la tarjeta de táctica{fr}Ordre de tour réorganisé en fonction de la sélection de la carte tactique{pt-br}Ordem de Turno re-organizada baseada nas seleções de táticas{de}Zugreihenfolge neu organisiert basierend auf der Auswahl der Taktikkarten", {1,1,0.5})
		turnOrderSort()
		Wait.time(function()
			local depth=-8
			if gStates.dayRound==true then depth=-4 end
			for a=1, 6, 1 do
				for _, obj in pairs(getObjectFromGUID(tacticZones[a]).getObjects()) do
					if isTacticCard(obj) then
						obj.lock()
						obj.setPosition({obj.getPosition()[1], depth, obj.getPosition()[3]})
						break
					end
				end
			end
		end, 0.5)--allow time for the smooth claim to pull the cards out of the zone
		UI.setAttribute("ScoreButtonReal", "interactable", "True")
		UI.setAttribute("ScoreButtonRealImage", "image", "Sliced Button/Button New Active")
		gStates.tacticShown=false
		if apocalypseIsHereRoundStart~=nil then apocalypseIsHereRoundStart() end
		refreshTactic4HandBonus(true)
		--Day Tactic 2's button cannot replace the central tactic UI while tactics are being chosen.
		--Refresh it now that tactic selection has fully closed.
		Wait.frames(function()
			dayTactic2ButtonActivate()
		end, 5)
		--remove note about re-areanging turn tokens
		if getObjectFromGUID("0934f2")~=nil then getObjectFromGUID("0934f2").destruct()	end
	else
		gStates.tacticSixState="notClaimed"
		gStates.tacticShown=true
		refreshTactic4HandBonus(false)
		broadcastToAll("{en}Start of a Round. Please select a tactic Card for the round.{ru}Начало раунда. Пожалуйста, выберите Тактику на этот раунд из центра.{zh-cn}轮次开始了, 请选择本轮战术卡.{ko}라운드가 시작되었습니다. 전략 카드를 고르세요.{es}Inicio de una Ronda. Selecciona una carta de táctica para la Ronda.{fr}Début d'une Manche. Veuillez sélectionner une carte tactique pour le Rounde.{pt-br}Início de Rodada. Por favor selecione uma carta de Tática para a Rodada.{de}Beginn einer Runde. Bitte wählen Sie eine taktische Karte für die Runde", {1,1,0.5})
		local hide=0
		local show=6
		local depth=-8
		if gStates.dayRound==true then hide=6 show=0 depth=-4 end
		for a=1, 6, 1 do
			if getObjectFromGUID(tacticCard[a+hide])~=nil then
				getObjectFromGUID(tacticCard[a+hide]).setPosition({-16.50+(4*a), depth, 24.00})
				getObjectFromGUID(tacticCard[a+hide]).lock()
			end
			if getObjectFromGUID(tacticCard[a+show])~=nil then
				getObjectFromGUID(tacticCard[a+show]).unlock()
				getObjectFromGUID(tacticCard[a+show]).setRotation({0.00, 180, 0.00})
				getObjectFromGUID(tacticCard[a+show]).setPosition({-16.50+(4*a), 1.5, -14.00})
				getObjectFromGUID(tacticCard[a+show]).lock()
			end
		end
		UI.setAttribute("ScoreButtonReal", "interactable", "False")
		UI.setAttribute("ScoreButtonRealImage", "image", "Sliced Button/Button New Deactive")
		if getObjectFromGUID("0934f2")==nil then turnOrderSort() end
		mainUIUpdate("Tactic Togle")
	end
	claimButtonRefresh()
	cameraControl(nil, "-1", "tacticChanged")
end

--Move cards visibly to a player's Deed deck without allowing two cards to converge on the same pile.
--Each seat owns its own queue, so different players can receive cards simultaneously.
deedTransferState={queues={},active={},transit={}}

function deedTransferBusy(seatPos)
	local queue=deedTransferState.queues[seatPos]
	return deedTransferState.active[seatPos]~=nil or (queue~=nil and #queue>0)
end

function deedTransferAnyBusy()
	for seatPos=1,4 do if deedTransferBusy(seatPos)==true then return true end end
	return false
end

function deedTransferPile(zone,ignoreGUID)
	if zone==nil then return nil end
	local single=nil
	for _, obj in pairs(zone.getObjects()) do
		if obj.guid~=ignoreGUID then
			if obj.type=="Deck" then return obj end
			if obj.type=="Card" then single=obj end
		end
	end
	return single
end

function deedTransferHomePosition(seatPos)
	return {-74.19+(40*(seatPos-1)),1.50,-43.16}
end

function deedTransferComplete(seatPos,entry,placed)
	deedTransferState.transit[entry.guid]=nil
	deedTransferState.active[seatPos]=nil
	local queue=deedTransferState.queues[seatPos]
	local transferFinished=false
	if queue~=nil then
		for index, queued in ipairs(queue) do
			if queued.guid==entry.guid then table.remove(queue,index) break end
		end
		if #queue==0 then deedTransferState.queues[seatPos]=nil transferFinished=true end
	else
		transferFinished=true
	end
	if transferFinished==true then rewindTransactionFinish("Deed transfer "..tostring(seatPos)) end
	if placed==true and turnOrder[entry.playerIndex]~=nil then
		turnOrder[entry.playerIndex].deedCount=(turnOrder[entry.playerIndex].deedCount or 0)+1
	end
	Wait.frames(function() deedTransferProcess(seatPos) end,2)
end

function deedTransferFinishHover(seatPos,entry)
	local card=getObjectFromGUID(entry.guid)
	local zone=getObjectFromGUID(deedDeckZones[seatPos])
	if card==nil or zone==nil then deedTransferComplete(seatPos,entry,false) return end
	local pile=deedTransferPile(zone,entry.guid)
	if pile~=nil then
		local pilePos=pile.getPosition()
		local cardPos=card.getPosition()
		card.setPosition({pilePos[1],math.max(cardPos[2],pilePos[2]+1.0),pilePos[3]})
		pile.putObject(card)
		deedTransferComplete(seatPos,entry,true)
		return
	end
	--An empty Deed zone has no container to receive putObject. Smooth the first card down to the normal
	--deck home, then let the next queued card use that card as its pile.
	local home=deedTransferHomePosition(seatPos)
	card.setRotationSmooth({0,180,180})
	card.setPositionSmooth(home)
	Wait.condition(function()
		deedTransferComplete(seatPos,entry,true)
	end,function()
		local moving=getObjectFromGUID(entry.guid)
		if moving==nil then return true end
		local pos=moving.getPosition()
		return moving.resting==true and math.abs(pos[1]-home[1])<0.25 and math.abs(pos[2]-home[2])<0.35 and math.abs(pos[3]-home[3])<0.25
	end,2.5,function()
		local moving=getObjectFromGUID(entry.guid)
		if moving~=nil then moving.setPosition(home) moving.setRotation({0,180,180}) end
		deedTransferComplete(seatPos,entry,moving~=nil)
	end)
end

function deedTransferProcess(seatPos)
	if deedTransferState.active[seatPos]~=nil then return end
	local queue=deedTransferState.queues[seatPos]
	if queue==nil or #queue==0 then return end
	local entry=queue[1]
	local card=getObjectFromGUID(entry.guid)
	local zone=getObjectFromGUID(deedDeckZones[seatPos])
	if card==nil or zone==nil then deedTransferComplete(seatPos,entry,false) return end
	deedTransferState.active[seatPos]=entry.guid
	deedTransferState.transit[entry.guid]=zone.guid
	local pile=deedTransferPile(zone,entry.guid)
	local target=pile~=nil and pile.getPosition() or deedTransferHomePosition(seatPos)
	local rotation=pile~=nil and pile.getRotation() or {0,180,180}
	local hover={target[1],target[2]+2.0,target[3]}
	card.setRotationSmooth(rotation)
	card.setPositionSmooth(hover)
	Wait.condition(function()
		deedTransferFinishHover(seatPos,entry)
	end,function()
		local moving=getObjectFromGUID(entry.guid)
		if moving==nil then return true end
		local pos=moving.getPosition()
		return math.abs(pos[1]-hover[1])<0.35 and math.abs(pos[2]-hover[2])<0.5 and math.abs(pos[3]-hover[3])<0.35
	end,3.0,function()
		deedTransferFinishHover(seatPos,entry)
	end)
end

function queueCardToDeedDeck(playerIndex,card,rewindReady)
	if card==nil or turnOrder[playerIndex]==nil then return false end
	local seatPos=turnOrder[playerIndex].seatPos
	if seatPos==nil or deedDeckZones[seatPos]==nil or getObjectFromGUID(deedDeckZones[seatPos])==nil then return false end
	local guid=card.guid
	local queue=deedTransferState.queues[seatPos]
	if deedTransferState.active[seatPos]==guid then return true end
	if queue~=nil then for _, entry in ipairs(queue) do if entry.guid==guid then return true end end end
	--The transfer queue is runtime-only, so take the rewind point before lifting the first card. Closely
	--spaced claims for the same seat share this owner and are all allowed to queue behind the same snapshot.
	if rewindReady~=true then
		rewindTransactionStart(function() queueCardToDeedDeck(playerIndex,card,true) end,"Deed transfer "..tostring(seatPos))
		return true
	end
	card.unlock()
	card.UI.setXmlTable({{}})
	card.setScale({1.5,1,1.5})
	--Lift vertically before any horizontal movement. This clears Quest cards and offer cards, and gives the
	--ordinary source-zone leave callback a chance to resolve before transit suppression begins.
	local pos=card.getPosition()
	card.setPosition({pos[1],pos[2]+3.0,pos[3]})
	--Register immediately so closely spaced claims keep click order and other systems see this seat as busy
	--during the short lift delay. Horizontal transit does not begin until the source zone has had two frames.
	deedTransferState.queues[seatPos]=deedTransferState.queues[seatPos] or {}
	deedTransferState.queues[seatPos][#deedTransferState.queues[seatPos]+1]={guid=guid,playerIndex=playerIndex}
	Wait.frames(function() deedTransferProcess(seatPos) end,2)
	return true
end

--Move's an offer or tactic card to a player's location
local fillWait=false
function claimMove(player, mouseButton, id, rewindReady)
	if mouseButton~="-3" then
		if legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
			local claimedCard=getObjectFromGUID(id:sub(1, 6))
			if claimedCard~=nil then
				local source=id:sub(7, string.len(id))
				local cardClaimRewindOwner="Card claim "..tostring(claimedCard.guid)
				--Left-click card claims can update offers/rewards immediately while the physical card then travels
				--through the Deed-transfer queue. Protect the whole claim so a failed rewind-store never applies
				--the bookkeeping without also starting the physical transfer.
				if source~="unit" and mouseButton=="-1" and rewindReady~=true then
					if rewindTransactionOwnerActive(cardClaimRewindOwner)==true then return end
					rewindTransactionStart(function() claimMove(player,mouseButton,id,true) end,cardClaimRewindOwner)
					return
				end
				claimedCard.unlock()
				if source~="unit" then
					local tacticSource=source:sub(1, string.len(source)-1)=="tactic"
					if tacticSource==true then
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-117.83 , 3.0, -43.16})
					elseif mouseButton=="-1" then
						queueCardToDeedDeck(gStates.turnNumber,claimedCard)
					else
						claimedCard.setPosition({claimedCard.getPosition()[1], claimedCard.getPosition()[2]+3, claimedCard.getPosition()[3]})
					end
					cardClaim=true
					Wait.time(function() cardClaim=false end, 2)
					--add decal to tactic if playing Ultimate Conquest
					if gStates.gameScenario=="Ultimate Conquest" then
						for _, mage2 in pairs(mageKnights) do
							if mage2.mage==turnOrder[gStates.turnNumber].mage then
								local posX=-1*((turnOrder[gStates.turnNumber].seatPos*0.34)-0.85)
								Wait.time(function()
									claimedCard.addDecal({name="Used Already Shield", url=mage2.shieldImage,
									position={posX, 0.11, -0.9}, rotation={90.0, 180.0, 0.0}, scale={0.4, 0.4, 1}})
								end, 1)
							end
						end
					end
					--Left-click Deed claims are handled by the serialized smooth-transfer queue above. Preserve the
					--existing alternate claim action and tactic destination exactly as before.
					if mouseButton=="-2" and tacticSource~=true then
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-105.0 , 4.59, -47.55})
					elseif mouseButton~="-1" and tacticSource~=true then
						claimedCard.flip()
						claimedCard.setPositionSmooth({(turnOrder[gStates.turnNumber].seatPos*40)-114.19 , 3.0, -43.16})
					end
					if source=="offer" and fillWait==false then fillWait=true Wait.time(function() fillSlide() fillWait=false end, 1.2) end
					if source=="artifactReward" then
						if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" then gStates.theGauntletArtifactClaimed=true end
						gStates.dealtArtifacts[id:sub(1, 6)]=false
						claimedCard.UI.setXmlTable({{}})
						local remainingGUID={}
						for GUID, state in pairs(gStates.dealtArtifacts) do if state==true then remainingGUID[#remainingGUID+1]=GUID end end
						if #remainingGUID==1 then
							--return last card
							local PosOrigin=getObjectFromGUID(GUID.deck.artifact).getPosition()
							getObjectFromGUID(GUID.deck.artifact).setPositionSmooth({getObjectFromGUID(GUID.deck.artifact).getPosition()[1], getObjectFromGUID(GUID.deck.artifact).getPosition()[2]+2, getObjectFromGUID(GUID.deck.artifact).getPosition()[3]})
							standardDeckCycleMarkReturned("Artifact", getObjectFromGUID(remainingGUID[1]))
							getObjectFromGUID(remainingGUID[1]).unlock()
							getObjectFromGUID(remainingGUID[1]).setRotation({0, 180, 180})
							getObjectFromGUID(remainingGUID[1]).setPositionSmooth(PosOrigin)
							getObjectFromGUID(remainingGUID[1]).UI.setXmlTable({{}})
							--reset buttons
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactDown", "active", "true")
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactUp", "active", "true")
							gStates.artifactRewards=1
							gStates.dealtArtifacts=nil
							getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOfferText", "text", joinLang({"{en}Reward {ru}Награда {zh-tw}獎勵{zh-cn}奖励{ko}보상 {es}Premiar {fr}Reward {pt-br}Premiar {de}Belohnung ", gStates.artifactRewards}))
						end
					end
					if gameCards[claimedCard.guid]~=nil and source~="artifactReward" then
						broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", gameCards[claimedCard.guid].name[1], "."}), positionToColor(gStates.turnNumber))
					else
						broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", getObjectFromGUID(claimedCard.guid).getName(), "."}), positionToColor(gStates.turnNumber))
					end
				else
					if fillWait==false then--Move the Unit card to an empty command-source column
						local seatPos=turnOrder[gStates.turnNumber].seatPos
						local slot, unitX, commandSource, layout=unitLayoutFirstFreeCommand(seatPos)
						local found=slot~=nil
						if found==true then
							local scale=unitLayoutCardScale(#layout.commands)
							claimedCard.setScale({scale,1,scale})
							claimedCard.setPositionSmooth({unitX,2.0,-34.74})
							fillWait=true
							Wait.frames(function() Wait.condition(function() fillWait=false scheduleUnitLayoutRefresh(seatPos) end, function() return claimedCard.resting end) end,5)
							if gameCards[claimedCard.guid]~=nil then
								broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} gained {ru} получает {zh-cn}增加了{ko}의 획득:  {es} ganó {fr} a subi {pt-br} ganhou {de} gewonnen ", gameCards[claimedCard.guid].name[1], "."}), positionToColor(gStates.turnNumber))
							end
						end
						if found==false then broadcastToAll("{en}You have no free command tokens to enlist another unit{ru}У вас нет свободного жетона командования, чтобы нанять еще один отряд{zh-cn}你没有闲置的位置招募新部队{ko}유닛을 고용할 지휘 토큰이 부족합니다{es}No tienes fichas de mando gratuitas para alistar otra unidad{fr}Vous n'avez pas de jetons de commande gratuits pour enrôler une autre unité{pt-br}Você não tem Fichas de Comando livres para recrutar outra unidade{de}Du hast keine freien Befehlsmarken, um eine andere Einheit anzuwerben.", warningColor) end
						--Warn only after the normal location rules plus conquered Camp-as-City proximity are checked.
						if gameCards[claimedCard.guid]~=nil and unitRecruitableAtCurrentLocation(gStates.turnNumber,claimedCard)~=true then
							broadcastToAll("{en}Claimed Unit normally isn't recruited from the location you're currently at.{ru}Забранный Отряд обычно не нанимается из того места, где вы в данный момент находитесь.{zh-cn}你所在的位置通常不能招募这个部队{ko}보통은, 그 유닛을 현재 장소에서 고용할 수 없습니다{es}La Unidad reclamada normalmente no se recluta en la ubicación en la que se encuentra actualmente.{fr}L'Unité réclamée n'est normalement pas recrutée à l'endroit où vous vous trouvez actuellement.{pt-br}Unidade Clamada normalmente não é recrutada da localização que você está agora.{de}Die beanspruchte Einheit wird normalerweise nicht von dem Ort rekrutiert, an dem Sie sich gerade befinden.", positionToColor(gStates.turnNumber))
						end
					else
						broadcastToAll("{en}Let the last card settle before claiming the next unit.{ru}Не спешите. Позвольте предыдущей карте переместиться, прежде чем брать следующую.{zh-cn}征召下一个部队前, 把上一个结算清{ko}이전 유닛이 완전히 놓일 때 까지 기다려주세요{es}Deje que la última carta se asiente antes de reclamar la siguiente unidad.{fr}Laissez la dernière carte s'installer avant de réclamer l'unité suivante.{pt-br}Deixe a última carta se encaixar antes de clamar a próxima unidade.{de}Lassen Sie die letzte Karte ruhen, bevor Sie die nächste Einheit beanspruchen.", warningColor)
					end
				end
				--activate some of the tactics effects.
				if source:sub(1, string.len(source)-1)=="tactic" then
					turnOrder[gStates.turnNumber].tactic=tonumber(source:sub(7, string.len(source)))
					if gStates.dayRound==true and turnOrder[gStates.turnNumber].tactic==5 then
						drawExactDeedCards(gStates.turnNumber, 2, "DrawOne")
					end
					if gStates.dayRound==true and turnOrder[gStates.turnNumber].tactic==2 then
						Wait.time(function() dayTactic2ButtonActivate() end, 2)--activate after the tactic card finishes moving to the player area
					end
					nextTurnMerged("incrementTurn")
				end
				if rewindReady==true then Wait.time(function() rewindTransactionFinish(cardClaimRewindOwner) end,1.5) end
			end
		else
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				if turnOrder[gStates.turnNumber].mage=="Volkare" then
					broadcastToAll("{en}Volkare doesn't claim cards{ru}Волкар не берет карты{zh-cn}傻孩子, 沃里卡不选卡{ko}볼케어는 카드를 획득하지 않습니다{es}Volkare no reclama cartas{fr}Volkare ne réclame pas de cartes{pt-br}Volkare não clama cartas{de}Volkare beansprucht keine Karten", warningColor)
				else
					broadcastToAll("{en}Dummy doesn't claim cards this way{ru}Виртуальный игрок не получает карты таким образом{zh-cn}虚拟玩家不会这样选卡{ko}가상 플레이어는 카드를 이런 방식으로 얻지 않습니다{es}El muñeco no reclama cartas de esta manera{fr}Le mannequin ne réclame pas les cartes de cette façon{pt-br}Jog. Fictício não clama cartas desta forma{de}Dummy beansprucht auf diese Weise keine Karten", warningColor)
				end
			end
		end
	end
end

--Alternating reward highlights show the two legal Skill + Advanced Action pairings without enforcing either choice.
rewardSkillHighlightWait=nil
rewardSkillHighlightReadyWait=nil
rewardSkillHighlightPhase=false
rewardSkillHighlighted={}
rewardSkillHighlightColor={1,0.9,0}

function clearRewardSkillChoiceHighlights(keepFirstAction)
	local keepGUID=nil
	if keepFirstAction==true then
		local zone=getObjectFromGUID(GUID.zone.actionOffer)
		if zone~=nil then for _, obj in pairs(zone.getObjects()) do if obj.type=="Card" then keepGUID=obj.guid break end end end
	end
	local kept={}
	for guid, _ in pairs(rewardSkillHighlighted) do
		if guid==keepGUID then kept[guid]=true
		else
			local obj=getObjectFromGUID(guid)
			if obj~=nil then obj.highlightOff(rewardSkillHighlightColor) end
		end
	end
	rewardSkillHighlighted=kept
end

function addRewardSkillChoiceHighlight(obj)
	if obj==nil or rewardSkillHighlighted[obj.guid]==true then return end
	--Explicitly clear highlights between phases; no timed expiry means the first AA can remain highlighted across both legal pairings.
	obj.highlightOn(rewardSkillHighlightColor)
	rewardSkillHighlighted[obj.guid]=true
end

function rewardSkillChoiceActionCards()
	local zone=getObjectFromGUID(GUID.zone.offer)
	local cards={}
	if zone~=nil then
		for _, obj in pairs(zone.getObjects()) do
			if obj.type=="Card" and obj.getGMNotes()=="Advanced Action" then cards[#cards+1]=obj end
		end
	end
	table.sort(cards, function(a,b) return a.getPosition()[1]<b.getPosition()[1] end)
	return cards
end

function rewardSkillChoiceActionHighlights(allCards)
	if allCards==true then
		for _, card in ipairs(rewardSkillChoiceActionCards()) do addRewardSkillChoiceHighlight(card) end
	else
		--The dedicated actionOffer zone is the first Advanced Action slot only.
		local zone=getObjectFromGUID(GUID.zone.actionOffer)
		if zone~=nil then for _, obj in pairs(zone.getObjects()) do if obj.type=="Card" then addRewardSkillChoiceHighlight(obj) return end end end
	end
end

function rewardSkillChoiceForeignSkillExists()
	--Hero Challenges never permit the Common Skills alternative after the forced first Skill.
	if gStates.heroChallenges==true then return false end
	if gStates.mageSkills==nil or gStates.skillButtons==nil or gStates.skillButtons<=0 then return false end
	for skillGUID, skillPos in pairs(gStates.mageSkills) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]>-30 then
			local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
			if skillColumn+1~=gStates.skillButtons then return true end
		end
	end
	return false
end

function rewardSkillChoiceCurrentSkills()
	local currentPlayerSkills={}
	if gStates.mageSkills==nil or gStates.skillButtons==nil or gStates.skillButtons<=0 then return currentPlayerSkills end
	for skillGUID, skillPos in pairs(gStates.mageSkills) do
		local skill=getObjectFromGUID(skillGUID)
		if skill~=nil and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]>-30 then
			local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
			if skillColumn+1==gStates.skillButtons then currentPlayerSkills[#currentPlayerSkills+1]={obj=skill, z=skillPos[3]} end
		end
	end
	table.sort(currentPlayerSkills, function(a,b) return a.z>b.z end)
	return currentPlayerSkills
end

function rewardSkillChoiceHighlightsReady()
	if rewardSkillChoiceForeignSkillExists()==false then return false end
	local currentPlayerSkills=rewardSkillChoiceCurrentSkills()
	if currentPlayerSkills[1]==nil or currentPlayerSkills[2]==nil or currentPlayerSkills[1].obj.resting==false or currentPlayerSkills[2].obj.resting==false then return false end
	local actionCards=rewardSkillChoiceActionCards()
	--Do not start while the Advanced Action offer is still being dealt/slid into place.
	if #actionCards<(gStates.offerSize or 3) then return false end
	for _, card in ipairs(actionCards) do if card.resting==false then return false end end
	return true
end

function rewardSkillChoiceSkillHighlights(ownSkills)
	if gStates.mageSkills==nil or gStates.skillButtons==nil or gStates.skillButtons<=0 then return end
	local currentPlayerSkills=rewardSkillChoiceCurrentSkills()
	local playerLevel=0
	for _, details in pairs(turnOrder) do if details.seatPos==gStates.skillButtons then playerLevel=details.level or 0 break end end
	if ownSkills==true then
		if currentPlayerSkills[1]~=nil then addRewardSkillChoiceHighlight(currentPlayerSkills[1].obj) end
		if currentPlayerSkills[2]~=nil and playerLevel<=10 then addRewardSkillChoiceHighlight(currentPlayerSkills[2].obj) end
	else
		for skillGUID, skillPos in pairs(gStates.mageSkills) do
			local skill=getObjectFromGUID(skillGUID)
			if skill~=nil and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]>-30 then
				local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
				if skillColumn+1~=gStates.skillButtons then addRewardSkillChoiceHighlight(skill) end
			end
		end
	end
end

function stopRewardSkillChoiceHighlights()
	if rewardSkillHighlightReadyWait~=nil then Wait.stop(rewardSkillHighlightReadyWait) rewardSkillHighlightReadyWait=nil end
	if rewardSkillHighlightWait~=nil then Wait.stop(rewardSkillHighlightWait) rewardSkillHighlightWait=nil end
	clearRewardSkillChoiceHighlights()
end

function beginRewardSkillChoiceHighlights()
	if gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillChoiceForeignSkillExists()==false then return end
	rewardSkillHighlightPhase=false
	local function alternateHighlights()
		if gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillChoiceForeignSkillExists()==false then stopRewardSkillChoiceHighlights() return end
		--The first Advanced Action belongs to both pairings, so keep it highlighted across the phase switch.
		clearRewardSkillChoiceHighlights(true)
		rewardSkillHighlightPhase=not rewardSkillHighlightPhase
		if rewardSkillHighlightPhase==true then
			--Foreign Skill choice: only the first Advanced Action is paired with it.
			rewardSkillChoiceActionHighlights(false)
			rewardSkillChoiceSkillHighlights(false)
		else
			--Own Skill choice: every Advanced Action in the offer is paired with it.
			rewardSkillChoiceActionHighlights(true)
			rewardSkillChoiceSkillHighlights(true)
		end
	end
	alternateHighlights()
	rewardSkillHighlightWait=Wait.time(alternateHighlights, 2, -1)
end

function startRewardSkillChoiceHighlights()
	if gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillHighlightWait~=nil or rewardSkillHighlightReadyWait~=nil then return end
	--On the first Skill claim there are no foreign Skills, so the reminder has nothing useful to explain.
	if rewardSkillChoiceForeignSkillExists()==false then return end
	if rewardSkillChoiceHighlightsReady()==true then beginRewardSkillChoiceHighlights() return end
	rewardSkillHighlightReadyWait=Wait.condition(function()
		rewardSkillHighlightReadyWait=nil
		if rewardSkillChoiceHighlightsReady()==true then beginRewardSkillChoiceHighlights() end
	end, function()
		return gStates.skillButtons==nil or gStates.skillButtons<=0 or rewardSkillChoiceForeignSkillExists()==false or rewardSkillChoiceHighlightsReady()==true
	end)
end

--Moves claimed skill to player location
local masterOfChaosPause=false
function __skillMove_raw(player, mouseButton, id, rewindReady)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, gStates.skillButtons)==true then--and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5]
			local skillRewindOwner="Skill claim "..tostring(gStates.skillButtons)
			stopRewardSkillChoiceHighlights()
			--The Claim button already contains the exact Skill GUID. Use that as the authority instead of
			--decoding the communal row/column number back into approximate coordinates; the old decode was
			--fragile if the pool shifted and was wrong on row numbers 8/16/24/32.
			local claimedGUID=id:sub(1, 6)
			local claimedSkill=getObjectFromGUID(claimedGUID)
			local claimedHome=gStates.mageSkills~=nil and gStates.mageSkills[claimedGUID] or nil
			--A live Claim button also carries its 1..32 offer slot. Normally the saved GUID location is
			--present, but keep a correctly decoded fallback so damaged bookkeeping cannot deadlock the reward.
			if claimedHome==nil then
				local source=tonumber(id:sub(7, string.len(id)))
				if source~=nil and source>=1 and source<=32 then
					local column=math.floor((source-1)/8)
					local row=((source-1)%8)+1
					claimedHome={(column*3.7)+11,2,(row*1.35)-25.3}
				end
			end
			if gStates.heroChallenges==true and claimedSkill~=nil and claimedHome~=nil and claimedHome[3]>-30 then
				local claimedColumn=math.ceil((claimedHome[1]-12.85)/3.7)+1
				if claimedColumn~=gStates.skillButtons then
					claimedSkill.unlock()
					claimedSkill.setPositionSmooth(claimedHome)
					broadcastToColor("Hero Challenges: choose one of your two newly flipped Skills.",player.color or "Black",{1,0.6,0.2})
					if rewindReady==true then rewindTransactionFinish(skillRewindOwner) end
					return
				end
			end
			--Skill claiming rewrites the saved skill-location table while several tokens are still moving.
			--Take the rewind point before that transaction begins, then release after the layout has settled.
			if rewindReady~=true then
				if rewindTransactionOwnerActive(skillRewindOwner)==true then return end
				rewindTransactionStart(function() skillMove(player,mouseButton,id,true) end,skillRewindOwner)
				return
			end
			if claimedSkill==nil or claimedHome==nil or claimedHome[1]==nil or claimedHome[3]==nil then
				rewindTransactionFinish(skillRewindOwner)
				skillButtonActivate()
				return
			end
			local communalHome={claimedHome[1], claimedHome[2] or 2, claimedHome[3]}
			--update skill location register with a free spot on player board
			local count=0
			for skillGUID, skillPos in pairs(gStates.mageSkills) do
				if skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil and skillPos[3]<-36.9 and math.floor(skillPos[1])==math.floor(((gStates.skillButtons*40)-107.45)) then count=count+1 end
			end
			gStates.mageSkills[claimedGUID]={((gStates.skillButtons*40)-107.45), 1.1, -38.67-(1.48*count)}
			--Bonds of Loyalty goes to unit area
			if claimedGUID=="f30dd4" then
				local bondsX=unitLayoutNextCommandX(gStates.skillButtons)
				gStates.mageSkills[claimedGUID]={bondsX,1.1,-31.19}
				scheduleUnitLayoutRefresh(gStates.skillButtons)
				local unitPlace={{36.0, 1.25, -4.2}, {31.2, 1.25, -4.2}, {26.4, 1.25, -4.2}, {21.6, 1.25, -4.2}, {16.8, 1.25, -4.2}, {12.0, 1.25, -4.2}, {7.2, 1.25, -4.2}, {2.4, 1.25, -4.2}, {-2.4, 1.25, -4.2}}
				local params={smooth=true, rotation={0, 180, 0}}
				--Place Unit Cards. If the normal offer has already expanded beyond the legacy nine slots,
				--claiming the Skill must still complete rather than aborting the whole Skill transaction.
				for a=gStates.totalUnitCount+1, gStates.totalUnitCount+2, 1 do
					if unitPlace[a]~=nil then
						params.position=unitPlace[a]
						standardDeckCycleShuffleIfReached("Regular Unit")
						local unitDeckZone=getObjectFromGUID(GUID.zone.regularUnit)
						local unitDeckObjects=unitDeckZone~=nil and unitDeckZone.getObjects() or nil
						local unitDeck=unitDeckObjects~=nil and unitDeckObjects[1] or nil
						if unitDeck~=nil then
							local deckObj=getObjectFromGUID(unitDeck.guid)
							if deckObj~=nil then deckObj.takeObject(params) end
						end
					end
				end
				broadcastToAll("{en}Two more Regular units added to the Unit Offer for this round.{ru}Два дополнительных обычных отряда доступны в этом раунде{zh-cn}本轮增加了两个部队供应{ko}일반 유닛 두 개를 공급처에 추가합니다{es}Se agregaron dos unidades regulares más a la oferta de unidades para esta ronda.{fr}Deux autres unités régulières ajoutées à l'offre d'unités pour ce tour.{pt-br}2 unidades Regulares a mais adicionadas a Oferta de Unidades por esta Rodada{de}Zwei weitere reguläre Einheiten wurden dem Einheitenangebot für diese Runde hinzugefügt.", {1,1,0.5})
			end
			--Master of Chaos
			if claimedGUID=="1ff34f" then masterOfChaosSetup(gStates.skillButtons) end
			--move selected skill
			claimedSkill.unlock()
			claimedSkill.setPositionSmooth(gStates.mageSkills[claimedGUID])
			if gStates.motivationSkill[claimedGUID]~=nil then
				gStates.motivationSkill[claimedGUID].pos=gStates.skillButtons
				gStates.motivationSkill[claimedGUID].state="active"
				mainUIUpdate("Skill Claimed")
			end
			--move remaining skills in the claimed communal column down. Missing/stale GUIDs are ignored;
			--they must never be able to strand a completed claim with gStates.skillButtons still active.
			for skillGUID, skillPos in pairs(gStates.mageSkills) do
				if skillGUID~=claimedGUID and skillPos~=nil and skillPos[1]~=nil and skillPos[3]~=nil
					and math.floor(communalHome[1])==math.floor(skillPos[1]) and skillPos[3]>communalHome[3] then
					local remainingSkill=getObjectFromGUID(skillGUID)
					if remainingSkill~=nil then
						gStates.mageSkills[skillGUID][3]=gStates.mageSkills[skillGUID][3]-1.35
						remainingSkill.unlock()
						remainingSkill.setPositionSmooth(gStates.mageSkills[skillGUID])
						local remainingGUID=skillGUID
						Wait.time(function()
							Wait.condition(function()
								local obj=getObjectFromGUID(remainingGUID)
								if obj~=nil then obj.unlock() end
							end, function()
								local obj=getObjectFromGUID(remainingGUID)
								return obj==nil or obj.resting
							end)
						end, 1)
					end
				end
			end
			--Lock Reward claim check button

			--limit advanced action selection if another players skill chosen

			--deploy a dummy skill for next level up.
			if gStates.playersRef==5 then
				local exist=0
				local dummyPos=0
				for a=1, #turnOrder, 1 do
					if turnOrder[a].mage==gStates.positionMageKnight[5] then dummyPos=a break end
				end
				if dummyPos>0 and turnOrder[dummyPos]~=nil then
					for skillGUID, skillPos in pairs(gStates.mageSkills) do
						if skillPos~=nil and skillPos[1]~=nil and math.floor(skillPos[1])==math.floor((turnOrder[dummyPos].seatPos*3.7)+7.3) then exist=exist+1 end
					end
					local pos={(turnOrder[dummyPos].seatPos*3.7)+7.3, 2.00, -23.95+(exist*1.35)}
					local b=nil
					local allSkillsBag=getObjectFromGUID(GUID.bag.allSkills)
					if allSkillsBag~=nil then--use "all Skills" bag if it exists
						b=allSkillsBag.takeObject({position=pos, rotation={0, 180, 0}})
					else
						local dummySkillBag=getObjectFromGUID(turnOrder[dummyPos].skillBagGUID)
						if dummySkillBag~=nil then b=dummySkillBag.takeObject({position=pos, rotation={0, 180, 0}}) end
					end
					if b~=nil then
						Wait.condition(function() if b~=nil then b.lock() end end, function() return b==nil or b.resting end)
						gStates.mageSkills[b.guid]=pos
					end
				end
			end
			--turn off skill claim buttons
			local found=false
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==gStates.skillButtons and turnOrder[a].levelUp>0 then levelUp(a) found=true end
			end
			if found==false then
				gStates.skillButtons=0
				stopRewardSkillChoiceHighlights()
				Wait.frames(function()
					for skillGUID, _ in pairs(gStates.mageSkills) do
						local skill=getObjectFromGUID(skillGUID)
						if skill~=nil then skill.UI.setXmlTable({{}}) end
					end
				end, 5)
			end
			Wait.time(function() rewindTransactionFinish(skillRewindOwner) end,2.0)
		else
			if rewindReady==true then rewindTransactionFinish("Skill claim "..tostring(gStates.skillButtons)) end
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				broadcastToAll("{en}Dummy doesn't claim skill!{ru}Виртуальный игрок не получает навыков!{zh-cn}虚拟玩家不会选技能{ko}가상 플레이어는 스킬을 얻지 않습니다!{es}¡Dummy no dice tener habilidad!{fr}Le mannequin ne réclame pas de compétence !{pt-br}Jog. Fictício não clama habilidades{de}Dummy beansprucht keine Fertigkeit!", warningColor)
			end
		end
	end
end

--Removes all claim buttons and re-activates only buttons with cards
function claimButtonRefresh()
	--Remove buttons if dummy is choosing
	getObjectFromGUID("483ed5").UI.setXmlTable({{}})
	if gStates.tacticShown==false or turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
		for zoneGUID, cardSource in pairs(tacticClaimingZones) do
			for _, obj in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
				if isTacticCard(obj) then
					obj.UI.setXmlTable({{}})
				end
			end
		end
	end
	--Add buttons
	Wait.time(function()
		if gStates.tacticShown==true then
			--Tactic card claim buttons
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				getObjectFromGUID("483ed5").UI.setXmlTable({createClaimButton("483ed5", "tactic7")})
			else
				for zoneGUID, cardSource in pairs(tacticClaimingZones) do
					if getObjectFromGUID(zoneGUID).getObjects()~=nil then
						for _, obj in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
							for a=1, 12, 1 do
								if obj.guid==tacticCard[a] then
									obj.UI.setXmlTable({createClaimButton(obj.guid, cardSource)})
									break
								end
							end
						end
					end
				end
			end
		end
		if gStates.tacticRemove==true then
			--Remove Tactic Claim Button
			if gStates.discardTactics==2 then
				getObjectFromGUID("483ed5").UI.setXmlTable({createClaimButton("483ed5", "removeTactic5")})
			else
				for zoneGUID, cardSource in pairs(tacticClaimingZones) do
					if cardSource:sub(1,6)=="tactic" then
						local cardSourceRemove="removeTactic"..cardSource:sub(7,8)
						local card=getObjectFromGUID(zoneGUID).getObjects()
						if #card>=1 then
							card[1].UI.setXmlTable({createClaimButton(card[1].guid, cardSourceRemove)})
						end
					end
				end
			end
		end
		if gStates.tacticRemove==false and gStates.tacticShown==false then
			--offer buttons
			for zoneGUID, cardSource in pairs(cardClaimingZones) do
				for _, card in pairs(getObjectFromGUID(zoneGUID).getObjects()) do
					if card.type=="Card" and gameCards[card.guid]~=nil then
						card.UI.setXmlTable({{}})
						if gStates.preEndTurn==false or (cardSource~="monastery" and gStates.preEndTurn==true) then
							card.UI.setXmlTable({createClaimButton(card.guid, cardSource)})
						end
					end
				end
			end
			--artifact buttons
			local count=0
			if gStates.dealtArtifacts~=nil then
				for guid, state in pairs(gStates.dealtArtifacts) do
					if state==true then
						count=count+1
						getObjectFromGUID(guid).UI.setXmlTable({createClaimButton(guid, "artifactReward")})
					end
				end
			end
			if count==0 then
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactDown", "active", "true")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOffer", "active", "true")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactUp", "active", "true")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactDownImage", "image", "Overkill Down")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOfferImage", "image", "Sliced Button/Button Object Active")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactUpImage", "image", "Overkill Up")
			end
		end
	end, 0.3)
end

--The combined-defense choice is a transient lock; it does not need to be saved with the game.
local dropoutCoopDefensePrompt=false

--Get's the dummy to pick a tactic card
function dummyRefreshDeedState(seatPos)
	if seatPos==nil then return end
	local newCount=readDeedPileCardCount(seatPos)
	deedPileCardCount[seatPos]=newCount
	endRoundDeedHasCards[seatPos]=newCount>0
	if gStates.turnNumber~=nil and turnOrder[gStates.turnNumber]~=nil and turnOrder[gStates.turnNumber].seatPos==seatPos then endRoundUIStateKey=nil refreshEndRoundState() end
end

--Short scripted transactions can span several delayed/physics callbacks. Store one known-good rewind point
--before the first mutation, then suppress TTS automatic rewind snapshots until every nested transaction is stable.
--Owners make the guard nestable: a Quest refill can safely run inside End of Round, and several queued card claims
--for one seat can share the same rewind transaction without releasing the outer transaction early.
rewindTransactionStorePending=false
rewindTransactionBlocked=false
rewindTransactionGeneration=0
rewindTransactionOwners={}
rewindTransactionPending={}
rewindTransactionPendingOwners={}

function rewindTransactionOwnerActive(owner)
	owner=owner or "Automated turn"
	return rewindTransactionOwners[owner]==true or rewindTransactionPendingOwners[owner]==true
end

function rewindTransactionStart(andThen,owner,onFailure)
	owner=owner or "Automated turn"
	if type(andThen)~="function" then return false end
	if rewindTransactionBlocked==true then
		rewindTransactionOwners[owner]=true
		andThen()
		return true
	end
	if type(storeRewindState)~="function" then
		rewindTransactionOwners[owner]=true
		andThen()
		return true
	end
	rewindTransactionPending[#rewindTransactionPending+1]={owner=owner,run=andThen,fail=onFailure}
	rewindTransactionPendingOwners[owner]=true
	if rewindTransactionStorePending==true then return true end
	rewindTransactionStorePending=true
	storeRewindState(function(success,didSave)
		local pending=rewindTransactionPending
		rewindTransactionPending={}
		rewindTransactionPendingOwners={}
		rewindTransactionStorePending=false
		if success~=true then
			for _,entry in ipairs(pending) do if type(entry.fail)=="function" then entry.fail() end end
			broadcastToAll("Could not store a safe rewind point. The scripted action was not started.",{1,0.25,0.25})
			return
		end
		rewindTransactionBlocked=true
		rewindTransactionGeneration=(rewindTransactionGeneration or 0)+1
		local rewindGeneration=rewindTransactionGeneration
		for _,entry in ipairs(pending) do rewindTransactionOwners[entry.owner]=true end
		--TTS automatically lifts block_further_stores after 60 seconds. Mirror that expiry so the Lua
		--owner table cannot remain stuck if a protected sequence hands control to a long human decision.
		Wait.time(function()
			if rewindTransactionBlocked==true and rewindTransactionGeneration==rewindGeneration then rewindTransactionForceRelease() end
		end,59)
		for _,entry in ipairs(pending) do entry.run() end
	end,true)
	return true
end

function rewindTransactionFinish(owner)
	owner=owner or "Automated turn"
	rewindTransactionOwners[owner]=nil
	if next(rewindTransactionOwners)~=nil then return end
	if rewindTransactionBlocked==true and type(allowRewindStore)=="function" then allowRewindStore() end
	rewindTransactionBlocked=false
	rewindTransactionGeneration=(rewindTransactionGeneration or 0)+1
end

function rewindTransactionForceRelease()
	rewindTransactionOwners={}
	rewindTransactionPending={}
	rewindTransactionPendingOwners={}
	rewindTransactionStorePending=false
	if rewindTransactionBlocked==true and type(allowRewindStore)=="function" then allowRewindStore() end
	rewindTransactionBlocked=false
	rewindTransactionGeneration=(rewindTransactionGeneration or 0)+1
end

--Compatibility names for the three automated-player systems.
function automatedTurnRewindStart(andThen) return rewindTransactionStart(andThen,"Automated turn") end
function automatedTurnRewindRelease() rewindTransactionFinish("Automated turn") end

function automatedTacticRewindRelease()
	--The tactic itself moves smoothly after the turn advances, so keep rewind storage blocked briefly.
	Wait.time(automatedTurnRewindRelease,1.5)
end

function volkareReleaseRewindWhenStable()
	if rewindTransactionOwnerActive("Automated turn")~=true then return end
	local v=getObjectFromGUID(gStates.volkareModel)
	if v==nil or (v.resting and v.isSmoothMoving()==false) then automatedTurnRewindRelease() return end
	Wait.condition(automatedTurnRewindRelease,function()
		local current=getObjectFromGUID(gStates.volkareModel)
		return current==nil or (current.resting and current.isSmoothMoving()==false)
	end,8,function()
		local current=getObjectFromGUID(gStates.volkareModel)
		if current~=nil then
			current.setPosition(current.getPosition())
			current.setVelocity({0,0,0})
			current.setAngularVelocity({0,0,0})
			if gStates.volkareLock~=false then current.lock() end
		end
		automatedTurnRewindRelease()
	end)
end

--Dummy and Volkare both use the center random-Tactic button, but their actual turns are processed separately.
function automatedPlayerRandomTactic()
	local dummyTactic=nil
	local claimedCard=nil
	while dummyTactic==nil do
		dummyTactic=math.random(1,6)
		for _, obj in pairs(getObjectFromGUID(tacticZones[dummyTactic]).getObjects()) do
			if isTacticCard(obj) then claimedCard=obj break end
		end
		if claimedCard==nil then dummyTactic=nil end
	end
	broadcastToAll(joinLang({gStates.positionMageKnight[5]=="Volkare" and "{en}Volkare RANDOMLY gained Tactic for {ru}Волкар получает СЛУЧАЙНУЮ Тактику для {zh-tw}沃卡里隨機選取戰術給{zh-cn}沃卡里随机选取战术给{ko}볼케어가 무작위 전략을 가져갑니다: {es}Volkare ganó ALEATORIAMENTE Táctica para {fr}Volkare a gagné au hasard une Tactique pour {pt-br}Volkare ALEATORIAMENTE ganhou a Tática por {de}Volkare hat ZUFÄLLIG eine Taktik für " or (proxyPlayerActive()==true and "{en}Proxy RANDOMLY gained Tactic for {ru}Прокси получает СЛУЧАЙНУЮ Тактику для {zh-tw}代理玩家隨機選取戰術給{zh-cn}代理玩家随机选取战术给{ko}프록시가 무작위 전략을 가져갑니다: {es}Proxy ganó ALEATORIAMENTE Táctica para {fr}Le Proxy a gagné au hasard une Tactique pour {pt-br}Proxy ALEATORIAMENTE ganhou a Tática por {de}Proxy hat ZUFÄLLIG eine Taktik für " or "{en}Dummy RANDOMLY gained Tactic for {ru}Виртуальный игрок получает СЛУЧАЙНУЮ Тактику для {zh-cn}虚拟玩家随机选取战术给{ko}가상 플레이어가 무작위의 전략 카드를 가져갑니다: {es}Dummy ganada ALEATORIAMENTE Táctica para {fr}Le mannequin a gagné au hasard une Tactique pour {pt-br}Jog. Fictício ALEATORIAMENTE ganhou a Tática por {de}Dummy hat ZUFÄLLIG eine Taktik für "), translateWord[turnOrder[gStates.turnNumber].mage]}), positionToColor(gStates.turnNumber))
	if claimedCard~=nil then
		claimedCard.unlock()
		claimedCard.setPositionSmooth({getObjectFromGUID(dummyBoard).getPosition()[1], 3.0, getObjectFromGUID(dummyBoard).getPosition()[3]-5.17})
	end
	turnOrder[gStates.turnNumber].tactic=dummyTactic
end

--Draw from an automated player's Deed pile without ever calling takeObject on a Deck after it collapses to its final Card.
--The returned card is the last card actually flipped, even when fewer cards were available than requested.
function automatedDeedDraw(seatPos, cardCount, passIndex)
	if seatPos==nil or cardCount==nil or cardCount<=0 then return nil,0 end
	local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
	local discardZone=getObjectFromGUID(deedDeckDiscardZones[seatPos])
	if deedZone==nil or discardZone==nil then return nil,0 end
	local pile=nil
	for _, obj in pairs(deedZone.getObjects()) do
		if obj.type=="Deck" or obj.type=="Card" then pile=obj break end
	end
	if pile==nil then return nil,0 end
	local destination=discardZone.getPosition()
	local passOffset=((passIndex or 1)-1)*4.5
	local drawn=0
	local lastCard=nil
	local function destinationFor(drawIndex) return {destination[1], destination[2]+(drawIndex*1.5)+passOffset, destination[3]} end
	if pile.type=="Card" then
		pile.setPositionSmooth(destinationFor(1))
		pile.setRotationSmooth({0,180,0})
		return pile,1
	end
	local quantity=pile.getQuantity()
	local takeCount=math.min(cardCount, math.max(quantity-1,0))
	for i=1,takeCount do
		local taken=pile.takeObject({position=destinationFor(i), rotation={0,180,0}})
		if taken==nil then break end
		drawn=drawn+1
		lastCard=taken
	end
	--Taking the second-last card destroys a TTS Deck. If this draw is meant to empty it,
	--move the spawned remainder instead of calling takeObject on the destroyed Deck reference.
	if cardCount>=quantity and drawn==quantity-1 then
		local remainder=pile.remainder
		if remainder~=nil then
			drawn=drawn+1
			remainder.setPositionSmooth(destinationFor(drawn))
			remainder.setRotationSmooth({0,180,0})
			lastCard=remainder
		end
	end
	return lastCard,drawn
end

function dummyCardColors(card)
	local colors={}
	if card~=nil and gameCards[card.guid]~=nil and type(gameCards[card.guid].color)=="table" then
		for _, color in ipairs(gameCards[card.guid].color) do if color=="Red" or color=="Green" or color=="Blue" or color=="White" then colors[#colors+1]=color end end
	end
	if #colors==0 and card~=nil then
		for color in tostring(card.getDescription()):gmatch("%a+") do if color=="Red" or color=="Green" or color=="Blue" or color=="White" then colors[#colors+1]=color end end
	end
	return colors
end

function volkareArmyStillAlive()
	local army=gStates~=nil and gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[volkare.model] or nil
	if type(army)~="table" then return false end
	for guid,state in pairs(army) do if guid~="extra" and state=="alive" then return true end end
	return false
end

--City raising is needed by both Volkare's movement processor and later combat-prompt callbacks.
function volkareRazesCity(cityKey)
	if cityKey==nil or cityKey==0 or gStates.cityRevealed[cityKey]==nil then return end
	local city=gStates.cityRevealed[cityKey]
	local cityColor={[cityModel.blue]="blue", [cityModel.red]="red", [cityModel.green]="green", [cityModel.white]="white"}
	terrainTiles[city.terrain].hexFeature.center="raised "..cityColor[city.model]
	if gStates.hexOverideSave[city.terrain]==nil then gStates.hexOverideSave[city.terrain]={} end
	gStates.hexOverideSave[city.terrain].center="raised "..cityColor[city.model]
	local cityZone={[cityModel.blue]=GUID.zone.blueCity, [cityModel.red]=GUID.zone.redCity, [cityModel.green]=GUID.zone.greenCity, [cityModel.white]=GUID.zone.whiteCity}
	getObjectFromGUID(cityScriptZones[cityZone[city.model]].cityCard).setDescription("Raised City - Provides no Interaction")
	getObjectFromGUID(cityScriptZones[cityZone[city.model]].cityCard).addDecal({name="City Raised", url="https://steamusercontent-a.akamaihd.net/ugc/938341811903683200/0910E72610C36BACDEF44CB3BA2A909BA4AFC12E/",
		position={0.0,0.5,0.0}, rotation={90.0,180.0,0.0}, scale={1,2,2}})
	gStates.volkareRaisedCity=true
end

--Volkare's Quest only: once he reaches three spaces from the portal the Council closes it permanently.
--Mark the closed portal with the dedicated portal-closure artwork.
volkarePortalClosedDecalURL="https://steamusercontent-a.akamaihd.net/ugc/9820771160644960489/29318B61F2A30E0E941F355C3664303B0C95BC60/"
function volkareQuestPortalTile()
	local portalTile=getObjectFromGUID(startTerrain.open)
	if portalTile==nil then portalTile=getObjectFromGUID(startTerrain.wedge) end
	return portalTile
end
function volkareQuestPortalStatus()
	if gStates.gameScenario~="Volkare's Quest" or gStates.volkarePortalClosed==true then return false end
	local volkareObj=gStates.volkareModel~=nil and getObjectFromGUID(gStates.volkareModel) or nil
	local portalTile=volkareQuestPortalTile()
	if volkareObj==nil or portalTile==nil then return false end
	local vPos=volkareObj.getPosition()
	local pPos=portalTile.getPosition()
	local distance=math.sqrt(((vPos[1]-pPos[1])^2)+((vPos[3]-pPos[3])^2))
	--Euclidean distance is sufficient here, but do not divide-and-round it: different hexes on the same ring have different radii.
	--These thresholds sit in the clear gaps between the 3/4-space and 4/5-space rings.
	local closeDistance=2.39*3.25
	local warningDistance=2.39*4.20
	if distance>closeDistance and distance<=warningDistance and gStates.volkarePortalWarningShown~=true then
		gStates.volkarePortalWarningShown=true
		broadcastToAll("WARNING: Volkare is four spaces from the Portal. If he moves within three spaces, the Council of the Void will close it.", {1,0.65,0.15})
	end
	if distance>closeDistance then return false end
	gStates.volkarePortalClosed=true
	gStates.volkarePortalWarningShown=true
	local decals=portalTile.getDecals() or {}
	local marked=false
	for _, decal in pairs(decals) do if decal.name=="Portal Closed" then marked=true break end end
	if marked==false then portalTile.addDecal({name="Portal Closed",url=volkarePortalClosedDecalURL,position={0,0.15,0},rotation={90,180,0},scale={0.88,0.88,1}}) end
	broadcastToAll("The Council of the Void has closed the Portal. From now on it is an ordinary space, and Volkare may be attacked there.", {1,0.45,0.15})
	for playerIndex, details in pairs(turnOrder) do
		if details.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false and details.avatarLocation=="portal" then
			details.dropoutState="dropped"
			gStates.skipTurn[playerIndex]=nil
			local token=getObjectFromGUID(details.turnOrderTokenGUID)
			if token~=nil and token.is_face_down==true then token.flip() end
			broadcastToAll(joinLang({translateWord[details.mage], "{en} was caught on the Portal when it closed and is out of the game.{ru} оказался на Портале в момент его закрытия и выбывает из игры.{zh-tw} 在傳送門關閉時仍站在其上，因此退出遊戲。{zh-cn} 在传送门关闭时仍站在其上，因此退出游戏。{ko} 포탈이 닫힐 때 그 위에 있어 게임에서 탈락합니다.{es} estaba en el Portal cuando se cerró y queda fuera de la partida.{fr} se trouvait sur le Portail lors de sa fermeture et est éliminé de la partie.{pt-br} estava no Portal quando ele se fechou e está fora do jogo.{de} befand sich beim Schließen auf dem Portal und scheidet aus dem Spiel aus."}), positionToColor(playerIndex))
		end
	end
	applyColorBarButtons()
	addAvatarButtons()
	volkareQuestCheckSkipTurn()
	if activeMageKnightCount()==0 then
		gStates.volkareWon=true
		gStates.blurb="{en}The Portal closed with every Mage Knight trapped upon it.<size=6>\n\n</size>No-one remains to oppose Volkare. You have Lost.{ru}Портал закрылся, когда все Рыцари-Маги находились на нем.<size=6>\n\n</size>Некому противостоять Волкару. Вы проиграли.{zh-tw}傳送門關閉時所有魔法騎士都被困在其上。<size=6>\n\n</size>已無人能阻止沃卡里。你輸了。{zh-cn}传送门关闭时所有魔法骑士都被困在其上。<size=6>\n\n</size>已无人能阻止沃卡里。你输了。{ko}포탈이 닫히며 모든 마법기사가 그 위에 갇혔습니다.<size=6>\n\n</size>볼케어를 막을 자가 없습니다. 패배했습니다.{es}El Portal se cerró con todos los Caballeros Mago atrapados sobre él.<size=6>\n\n</size>Nadie queda para oponerse a Volkare. Has perdido.{fr}Le Portail s'est fermé alors que tous les Chevaliers-Mages s'y trouvaient.<size=6>\n\n</size>Plus personne ne peut s'opposer à Volkare. Vous avez perdu.{pt-br}O Portal se fechou com todos os Cavaleiros Magos presos sobre ele.<size=6>\n\n</size>Ninguém resta para enfrentar Volkare. Você perdeu.{de}Das Portal schloss sich, während alle Mage Knights darauf standen.<size=6>\n\n</size>Niemand kann Volkare noch aufhalten. Ihr habt verloren."
		UI.setAttribute("DummyNotes", "Text", gStates.blurb)
		mainUIUpdate("Volkare portal closure eliminated all players")
	end
	return true
end

--One to Return: the starting Portal closes after the first Day, eliminating anyone still on it.
--After that it is an ordinary single-occupancy plains hex until it reopens at the end of the second Night.
function oneToReturnPortalTile()
	return volkareQuestPortalTile()
end

function oneToReturnSetPortalClosedDecal(closed)
	local portalTile=oneToReturnPortalTile()
	if portalTile==nil then return end
	local decals=portalTile.getDecals() or {}
	local kept={}
	local marked=false
	for _, decal in pairs(decals) do
		if decal.name=="Portal Closed" then marked=true else kept[#kept+1]=decal end
	end
	if closed==true then
		if marked==false then portalTile.addDecal({name="Portal Closed",url=volkarePortalClosedDecalURL,position={0,0.15,0},rotation={90,180,0},scale={0.88,0.88,1}}) end
	elseif marked==true then portalTile.setDecals(kept) end
end

function oneToReturnClosePortal()
	if gStates.gameScenario~="One to Return" or gStates.oneToReturnPortalClosed==true then return false end
	gStates.oneToReturnPortalClosed=true
	oneToReturnSetPortalClosedDecal(true)
	broadcastToAll("The Portal has closed. From now on it is an ordinary plains space until the end of the second Night.", warningColor)
	for playerIndex, details in pairs(turnOrder) do
		if details.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false and details.avatarLocation=="portal" then
			details.dropoutState="dropped"
			gStates.skipTurn[playerIndex]=nil
			local token=getObjectFromGUID(details.turnOrderTokenGUID)
			if token~=nil and token.is_face_down==true then token.flip() end
			broadcastToAll(joinLang({translateWord[details.mage], "{en} was still on the Portal when it closed and is out of the game.{ru} оставался на Портале, когда он закрылся, и выбывает из игры.{zh-tw} 在傳送門關閉時仍站在其上，因此退出遊戲。{zh-cn} 在传送门关闭时仍站在其上，因此退出游戏。{ko} 포탈이 닫힐 때 그 위에 있어 게임에서 탈락합니다.{es} seguía en el Portal cuando se cerró y queda fuera de la partida.{fr} se trouvait encore sur le Portail lorsqu'il s'est fermé et est éliminé de la partie.{pt-br} ainda estava no Portal quando ele se fechou e está fora do jogo.{de} befand sich noch auf dem Portal, als es sich schloss, und scheidet aus dem Spiel aus."}), positionToColor(playerIndex))
		end
	end
	applyColorBarButtons()
	addAvatarButtons()
	if activeMageKnightCount()==0 then
		gStates.oneToReturnWinner=nil
		gStates.oneToReturnWinnerLocked=true
		gStates.blurb="{en}The Portal closed with every Mage Knight still upon it.<size=6>\n\n</size>No Hero remains to return. There is no winner.{ru}Портал закрылся, когда все Рыцари-Маги оставались на нем.<size=6>\n\n</size>Никто не сможет вернуться. Победителя нет.{zh-tw}傳送門關閉時所有魔法騎士都還在其上。<size=6>\n\n</size>沒有英雄能夠返回。無人獲勝。{zh-cn}传送门关闭时所有魔法骑士都还在其上。<size=6>\n\n</size>没有英雄能够返回。无人获胜。{ko}포탈이 닫힐 때 모든 마법기사가 그 위에 남아 있었습니다.<size=6>\n\n</size>돌아갈 영웅이 없습니다. 승자는 없습니다.{es}El Portal se cerró con todos los Caballeros Mago todavía sobre él.<size=6>\n\n</size>No queda ningún Héroe que pueda regresar. No hay ganador.{fr}Le Portail s'est fermé alors que tous les Chevaliers-Mages s'y trouvaient encore.<size=6>\n\n</size>Aucun Héros ne peut rentrer. Il n'y a pas de vainqueur.{pt-br}O Portal se fechou com todos os Cavaleiros Magos ainda sobre ele.<size=6>\n\n</size>Nenhum Herói resta para retornar. Não há vencedor.{de}Das Portal schloss sich, während noch alle Mage Knights darauf standen.<size=6>\n\n</size>Kein Held kann zurückkehren. Es gibt keinen Gewinner."
		UI.setAttribute("DummyNotes", "Text", gStates.blurb)
		gStates.endGameAchieved="true"
		gStates.gameOver=true
		mainUIUpdate("One to Return portal closure eliminated all players")
	end
	return true
end

function oneToReturnPortalOccupant()
	if gStates.gameScenario~="One to Return" then return nil,nil end
	local portalTile=oneToReturnPortalTile()
	if portalTile==nil then return nil,nil end
	local portalPos=portalTile.getPosition()
	for playerIndex, details in pairs(turnOrder) do
		if details.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false then
			local avatarObj=nil
			for _, avatar in pairs(mageKnights) do
				if avatar.mage==details.mage then
					avatarObj=getObjectFromGUID(avatar.model) or getObjectFromGUID(avatar.standee) or getObjectFromGUID(avatar.token)
					break
				end
			end
			if avatarObj~=nil then
				local pos=avatarObj.getPosition()
				if ((pos[1]-portalPos[1])^2)+((pos[3]-portalPos[3])^2)<1 then return playerIndex,details end
			end
		end
	end
	return nil,nil
end

function oneToReturnLockFinalWinner()
	if gStates.gameScenario~="One to Return" then return false end
	oneToReturnSetPortalClosedDecal(false)
	local _,winner=oneToReturnPortalOccupant()
	if winner==nil then
		gStates.oneToReturnWinner=nil
		gStates.oneToReturnWinnerLocked=false
		return false
	end
	gStates.oneToReturnWinner=winner.mage
	gStates.oneToReturnWinnerLocked=true
	broadcastToAll(joinLang({translateWord[winner.mage], "{en} occupies the Portal as End of Night is announced and is the One to Return. Player vs. Player combat may not be initiated after End of Night is called.{ru} занимает Портал в момент объявления конца Ночи и становится Единственным, кто вернется. После объявления конца Ночи нельзя начинать бой между игроками.{zh-tw} 在宣告黑夜輪結束時佔據傳送門，成為唯一能返回的英雄。宣告黑夜輪結束後不能再發起玩家對玩家戰鬥。{zh-cn} 在宣布黑夜轮结束时占据传送门，成为唯一能返回的英雄。宣布黑夜轮结束后不能再发起玩家对玩家战斗。{ko} 밤 종료가 선언될 때 포탈을 차지하고 있어 돌아갈 단 한 명의 영웅이 됩니다. 밤 종료 선언 후에는 PvP 전투를 시작할 수 없습니다.{es} ocupa el Portal cuando se anuncia el Fin de la Noche y es el Único que Regresa. No se puede iniciar combate entre jugadores después de anunciar el Fin de la Noche.{fr} occupe le Portail lorsque la Fin de la Nuit est annoncée et devient l'Unique à Revenir. Aucun combat entre joueurs ne peut être initié après l'annonce de la Fin de la Nuit.{pt-br} ocupa o Portal quando o Fim da Noite é anunciado e é o Único a Retornar. Combate entre jogadores não pode ser iniciado depois que o Fim da Noite é anunciado.{de} besetzt das Portal, als das Ende der Nacht ausgerufen wird, und ist der Eine, der zurückkehrt. Nach dem Ausrufen des Nachtendes darf kein PvP-Kampf mehr begonnen werden."}), {1,1,0.5})
	return true
end

function oneToReturnResolveWinner()
	if gStates.gameScenario~="One to Return" then return false end
	oneToReturnSetPortalClosedDecal(false)
	local winnerMage=gStates.oneToReturnWinnerLocked==true and gStates.oneToReturnWinner or nil
	if winnerMage==nil then
		local _,winner=oneToReturnPortalOccupant()
		if winner~=nil then winnerMage=winner.mage end
	end
	gStates.oneToReturnWinner=winnerMage
	if winnerMage~=nil then
		gStates.blurb=joinLang({translateWord[winnerMage], "{en} is the One to Return.<size=6>\n\n</size>They occupy the Portal as the second Night ends and win the game.{ru} — Единственный, кто вернется.<size=6>\n\n</size>Он занимает Портал в конце второй Ночи и выигрывает игру.{zh-tw} 是唯一能返回的英雄。<size=6>\n\n</size>第二個黑夜輪結束時佔據傳送門並贏得遊戲。{zh-cn} 是唯一能返回的英雄。<size=6>\n\n</size>第二个黑夜轮结束时占据传送门并赢得游戏。{ko} 돌아갈 단 한 명의 영웅입니다.<size=6>\n\n</size>두 번째 밤이 끝날 때 포탈을 차지해 승리합니다.{es} es el Único que Regresa.<size=6>\n\n</size>Ocupa el Portal cuando termina la segunda Noche y gana la partida.{fr} est l'Unique à Revenir.<size=6>\n\n</size>Ce Héros occupe le Portail à la fin de la deuxième Nuit et remporte la partie.{pt-br} é o Único a Retornar.<size=6>\n\n</size>Ocupa o Portal quando a segunda Noite termina e vence o jogo.{de} ist der Eine, der zurückkehrt.<size=6>\n\n</size>Dieser Held besetzt das Portal am Ende der zweiten Nacht und gewinnt das Spiel."})
	else
		gStates.blurb="{en}The second Night has ended and no Hero occupies the Portal.<size=6>\n\n</size>There is no winner.{ru}Вторая Ночь закончилась, но Портал никто не занимает.<size=6>\n\n</size>Победителя нет.{zh-tw}第二個黑夜輪已結束，但沒有英雄佔據傳送門。<size=6>\n\n</size>無人獲勝。{zh-cn}第二个黑夜轮已结束，但没有英雄占据传送门。<size=6>\n\n</size>无人获胜。{ko}두 번째 밤이 끝났지만 포탈을 차지한 영웅이 없습니다.<size=6>\n\n</size>승자는 없습니다.{es}La segunda Noche ha terminado y ningún Héroe ocupa el Portal.<size=6>\n\n</size>No hay ganador.{fr}La deuxième Nuit est terminée et aucun Héros n'occupe le Portail.<size=6>\n\n</size>Il n'y a pas de vainqueur.{pt-br}A segunda Noite terminou e nenhum Herói ocupa o Portal.<size=6>\n\n</size>Não há vencedor.{de}Die zweite Nacht ist beendet und kein Held besetzt das Portal.<size=6>\n\n</size>Es gibt keinen Gewinner."
	end
	UI.setAttribute("DummyNotes", "Text", gStates.blurb)
	broadcastToAll(gStates.blurb, {1,1,0.5})
	return winnerMage~=nil
end

--Apocalypse Dragon Proxy Player variant. It shares the normal Dummy deck/tactic machinery, but keeps its Hero on the map and resolves its turn visibly.
proxyStandardBasicNames={Stamina=true,Determination=true,Crystallize=true,March=true,Tranquility=true,Concentration=true,Swiftness=true,["Mana Draw"]=true,Promise=true,Improvisation=true,Threaten=true,Rage=true}

