--Magical Glade reward: during the Rewards Claimed stage, offer one scripted Wound heal from the discard pile.
local gladeDiscardHealButtonGUID=nil
local function removeGladeDiscardHealButton(obj)
	if obj==nil then return end
	local remove={}
	for _, button in pairs(obj.getButtons() or {}) do if button.click_function=="gladeDiscardHeal" then remove[#remove+1]=button.index end end
	table.sort(remove, function(a,b) return a>b end)
	for _, index in ipairs(remove) do obj.removeButton(index) end
	local xml=obj.UI.getXmlTable() or {}
	local changed=false
	for i=#xml, 1, -1 do
		if xml[i].attributes~=nil and xml[i].attributes.id=="GladeDiscardHealButton" then table.remove(xml, i) changed=true end
	end
	if changed==true then
		if #xml>0 then obj.UI.setXmlTable(xml) else obj.UI.setXmlTable({{}}) end
	end
end
local function clearGladeDiscardHealButtons()
	if gladeDiscardHealButtonGUID~=nil then removeGladeDiscardHealButton(getObjectFromGUID(gladeDiscardHealButtonGUID)) gladeDiscardHealButtonGUID=nil end
	for _, details in pairs(turnOrder or {}) do
		if details.seatPos~=nil then
			local zone=getObjectFromGUID(deedDeckDiscardZones[details.seatPos])
			if zone~=nil then for _, obj in pairs(zone.getObjects()) do removeGladeDiscardHealButton(obj) end end
		end
	end
end
local function gladeDiscardWound(playerIndex)
	local details=turnOrder[playerIndex]
	local zone=details~=nil and getObjectFromGUID(deedDeckDiscardZones[details.seatPos]) or nil
	if zone==nil then return nil, nil end
	for _, obj in pairs(zone.getObjects()) do
		if obj.type=="Card" and obj.getGMNotes()=="Wound" then return obj, obj.guid end
		if obj.type=="Deck" then
			for _, data in pairs(obj.getObjects()) do if data.gm_notes=="Wound" then return obj, data.guid end end
		end
	end
	return nil, nil
end
function refreshGladeDiscardHealButton()
	clearGladeDiscardHealButtons()
	local playerIndex=gStates.turnNumber
	local details=turnOrder[playerIndex]
	if details==nil or details.mage==gStates.positionMageKnight[5] or playerDropoutInactive(playerIndex)==true then return end
	if gStates.preEndTurn~=true or gStates.coopAssaultPhase=="combat" or gameOver==true or UI.getAttribute("RewardCheck", "active")~="true" then return end
	if details.avatarLocation~="glade" and not (gStates.gameScenario=="The Hidden Valley Blitz" and details.avatarLocation=="hidden valley") then return end
	if gladeFreeCheck()~=true then return end
	if gStates.gladeDiscardHealUsed==nil then gStates.gladeDiscardHealUsed={} end
	if gStates.gladeDiscardHealUsed[details.seatPos]==true then return end
	local discardObj=gladeDiscardWound(playerIndex)
	if discardObj==nil then return end
	removeGladeDiscardHealButton(discardObj)
	local xml=discardObj.UI.getXmlTable() or {}
	xml[#xml+1]={tag="Button", attributes={id="GladeDiscardHealButton", onClick="global/gladeDiscardHealUI", width=100, height=100, position="0 0 -100", rotation="0 0 0", colors="#00000000|#00000000|#00000000|#00000000"},
		children={{tag="Image", attributes={image="Glade Heal Button", width=100, height=100, rotation="0 0 180", preserveAspect="true"}}}}
	discardObj.UI.setXmlTable(xml)
	gladeDiscardHealButtonGUID=discardObj.guid
end
function gladeDiscardHealUI(player, value, id)
	local obj=gladeDiscardHealButtonGUID~=nil and getObjectFromGUID(gladeDiscardHealButtonGUID) or nil
	if obj~=nil and player~=nil then gladeDiscardHeal(obj, player.color, false) end
end
function gladeDiscardHeal(obj, playerColor, altClick)
	local playerIndex=gStates.turnNumber
	local details=turnOrder[playerIndex]
	if details==nil or legalPlayerCheck(playerColor, details.seatPos)~=true then return end
	if gStates.preEndTurn~=true or gStates.coopAssaultPhase=="combat" or gameOver==true or UI.getAttribute("RewardCheck", "active")~="true" or
		(details.avatarLocation~="glade" and not (gStates.gameScenario=="The Hidden Valley Blitz" and details.avatarLocation=="hidden valley")) or gladeFreeCheck()~=true then refreshGladeDiscardHealButton() return end
	if gStates.gladeDiscardHealUsed==nil then gStates.gladeDiscardHealUsed={} end
	if gStates.gladeDiscardHealUsed[details.seatPos]==true then refreshGladeDiscardHealButton() return end
	local source, woundGUID=gladeDiscardWound(playerIndex)
	if source==nil or woundGUID==nil then refreshGladeDiscardHealButton() return end
	gStates.gladeDiscardHealUsed[details.seatPos]=true
	clearGladeDiscardHealButtons()
	local playArea=getObjectFromGUID(playerPlayAreas[details.seatPos])
	local pos=playArea~=nil and playArea.getPosition() or {(details.seatPos*40)-100,1.5,-39.4}
	local destination={pos[1],2.7,pos[3]}
	local function finishHeal(wound)
		if wound==nil then return end
		wound.setScale({1.5,1,1.5})
	end
	if source.type=="Deck" then
		source.takeObject({guid=woundGUID, position=destination, rotation={0,180,0}, smooth=true, callback_function=finishHeal})
	else
		source.setScale({1.5,1,1.5})
		source.setRotationSmooth({0,180,0})
		source.setPositionSmooth(destination)
		finishHeal(source)
	end
end

--Puppet Master is driven by the physical Enemy/Puppet tokens rather than by playing the Skill token.
--A defeated Enemy is requested as a Puppet by dragging it from its owner's combat area into Inventory.
--The original is returned to the exact pickup position after a legal clone is created, so normal combat
--cleanup still owns Fame, rewards, site conquest and the real Enemy's discard/return path.
puppetMasterSkillGUID="893537"
puppetMasterDecalURL="https://steamusercontent-a.akamaihd.net/ugc/9238819073352977936/805A3875C8D1AD843302CC3E9AE3307EAC961883/" --Permanent Puppet Master marker applied to every registered Puppet.
puppetMasterPickup={}

function puppetMasterPlayerIndexForSeat(seatPos)
	if seatPos==nil then return nil end
	for playerIndex, details in pairs(turnOrder or {}) do
		if details.seatPos==seatPos and details.mage~=gStates.positionMageKnight[5] then return playerIndex end
	end
	return nil
end

function puppetMasterPlayerIndexForMage(mage)
	if mage==nil then return nil end
	for playerIndex, details in pairs(turnOrder or {}) do if details.mage==mage then return playerIndex end end
	return nil
end

function puppetMasterSeatForColor(playerColor)
	if playerColor==nil or playerColor=="Black" or playerColor=="Grey" then return nil end
	local player=Player[playerColor]
	if player==nil or player.seated~=true or player.getHandTransform()==nil then return nil end
	return math.ceil((player.getHandTransform().position[1]+97.59)/40)
end

function puppetMasterColorCanMovePlayer(playerColor, playerIndex)
	if playerColor=="Black" then return true end
	local details=turnOrder[playerIndex]
	return details~=nil and puppetMasterSeatForColor(playerColor)==details.seatPos
end

function puppetMasterObjectInZone(objectGUID, zoneGUID)
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==objectGUID then return true end end
	return false
end

function puppetMasterCombatAreaPlayer(objectGUID)
	for playerIndex, details in pairs(turnOrder or {}) do
		if details.seatPos~=nil and details.mage~=gStates.positionMageKnight[5] then
			if puppetMasterObjectInZone(objectGUID,playerPlayAreas[details.seatPos])==true or puppetMasterObjectInZone(objectGUID,playerUnitAreas[details.seatPos])==true then return playerIndex end
		end
	end
	return nil
end

function puppetMasterInventoryPlayer(objectGUID)
	for playerIndex, details in pairs(turnOrder or {}) do
		if details.seatPos~=nil and details.mage~=gStates.positionMageKnight[5] and puppetMasterObjectInZone(objectGUID,playerCrystalAreas[details.seatPos])==true then return playerIndex end
	end
	return nil
end

function puppetMasterOwnsSkill(playerIndex)
	local details=turnOrder[playerIndex]
	local skillPos=gStates.mageSkills~=nil and gStates.mageSkills[puppetMasterSkillGUID] or nil
	if details==nil or skillPos==nil or skillPos[1]==nil or skillPos[3]==nil then return false end
	--Claimed Skills keep their home position in the owner's Skill column even while a Turn Skill is in play.
	local skillX=(details.seatPos*40)-107.45
	return skillPos[3]<-35 and math.abs(skillPos[1]-skillX)<2
end

function puppetMasterEnemyEligible(enemy)
	if enemy==nil then return false end
	local details=monsterPugs[enemy.guid]
	return details~=nil and details.name~="Ruin" and details.pugType~="possessed"
end

function puppetMasterWarn(playerIndex,message,controllerColor)
	local text="Puppet Master: "..tostring(message)
	local color=controllerColor
	if color==nil or Player[color]==nil or Player[color].seated~=true then
		color=playerIndex~=nil and positionToColor(playerIndex) or nil
	end
	if color~=nil and Player[color]~=nil and Player[color].seated==true then
		broadcastToColor(text,color,{1,0.65,0.2})
	elseif Player["Black"]~=nil and Player["Black"].seated==true then
		broadcastToColor(text,"Black",{1,0.65,0.2})
	else
		broadcastToAll(text,{1,0.65,0.2})
	end
end

function puppetMasterReturnToPickup(obj,pickup,message)
	if pickup==nil then return end
	if message~=nil then puppetMasterWarn(pickup.player,message,pickup.color) end
	puppetMasterPickup[obj~=nil and obj.guid or ""]=nil
	if obj==nil then return end
	if pickup.rotation~=nil then obj.setRotation(pickup.rotation) end
	if pickup.position~=nil then obj.setPosition(pickup.position) end
end

function puppetMasterApplyDecal(puppet)
	if puppet==nil or puppetMasterDecalURL==nil or puppetMasterDecalURL=="" then return end
	--Replace the marker rather than returning when one already exists, so saved Puppets also pick up
	--future size/position changes to the Puppet Master decal. Preserve any unrelated decals.
	local decals={}
	for _, decal in pairs(puppet.getDecals() or {}) do if decal.name~="Puppet Master" then table.insert(decals,decal) end end
	puppet.setDecals(decals)
	puppet.addDecal({name="Puppet Master",url=puppetMasterDecalURL,position={0,0.15,0},rotation={90,180,0},scale={0.96,0.96,1}})
end


function puppetMasterHalfAttacks(attack)
	if type(attack)~="table" then return nil end
	local result={}
	for attackType, values in pairs(attack) do
		local halved={}
		if type(values)=="table" then
			for _, value in ipairs(values) do if type(value)=="number" then halved[#halved+1]=math.ceil(value/2) end end
		elseif type(values)=="number" then
			halved[1]=math.ceil(values/2)
		end
		if #halved>0 then result[attackType]=halved end
	end
	return next(result)~=nil and result or nil
end

--Puppets are one-use Attack/Block effects, not enemies or Units. Keep only the values Puppet Master
--actually uses in monsterPerks so the normal monster hover renderer can display them. Enemy abilities,
--Fame, rewards and Physical Resistance deliberately do not carry over.
function puppetMasterPerksForData(data)
	local perks={}
	if type(data)~="table" then return perks end
	local attack=puppetMasterHalfAttacks(data.attack)
	if attack~=nil then perks.attack=attack end
	if type(data.armour)=="number" then
		local blockType="P"
		--Puppet Master reverses a single elemental resistance for Block; both become Cold Fire Block.
		if data.fResist~=nil and data.iResist~=nil then blockType="IF"
		elseif data.fResist~=nil then blockType="I"
		elseif data.iResist~=nil then blockType="F" end
		perks.block={[blockType]={math.ceil(data.armour/2)}}
	end
	return perks
end

function puppetMasterRefreshPresentation(puppet,record)
	if puppet==nil then return end
	puppetMasterApplyDecal(puppet)
	local data=record~=nil and record.data or nil --0152/0153 save migration.
	if data==nil and record~=nil and record.sourceGUID~=nil then
		local _, sourceData=puppetMasterDataForSourceGUID(record.sourceGUID)
		data=sourceData
	end
	if gStates.monsterPerks==nil then gStates.monsterPerks={} end
	gStates.monsterPerks[puppet.guid]=puppetMasterPerksForData(data)
	--Old Puppet records stored a full enemy copy for a bespoke tooltip. The hover system now owns all
	--combat presentation, so discard those legacy fields after using them once for migration.
	if record~=nil then record.data=nil record.fame=nil end
	puppet.setDescription("")
end

function puppetMasterObjectImage(obj)
	if obj==nil then return nil end
	local custom=obj.getCustomObject()
	if custom==nil then return nil end
	return custom.image or custom.image_url or custom.ImageURL or custom.diffuse or custom.DiffuseURL
end

function puppetMasterDataForSourceGUID(sourceGUID)
	if sourceGUID==nil then return nil,nil end
	local details=monsterPugs[sourceGUID]
	if details==nil then return nil,nil end
	local puppetData=details
	if sourceGUID==darkCrusader.token or sourceGUID==elementalist.token then
		local leader=sourceGUID==darkCrusader.token and darkCrusader or elementalist
		if leaderData[leader.terrainHex]~=nil and leaderData[leader.terrainHex][1]~=nil and leaderData[leader.terrainHex][1].abilities~=nil then puppetData=leaderData[leader.terrainHex][1].abilities end
	end
	return details,puppetData
end

function puppetMasterDataForEnemy(enemy)
	if enemy==nil then return nil,nil end
	return puppetMasterDataForSourceGUID(enemy.guid)
end

function puppetMasterPreparePuppet(puppet)
	if puppet==nil then return end
	--Possession/buff attachments and combat controls belong to the real Enemy, never to the kept Puppet.
	if #puppet.getAttachments()>0 then for _, attachment in pairs(puppet.removeAttachments() or {}) do attachment.destruct() end end
	puppet.clearButtons()
	puppet.UI.setXmlTable({{}})
	puppet.setDecals({})
	puppet.setGMNotes("Puppet Master")
	puppet.setDescription("")
end

function puppetMasterRegisterPuppet(puppet,enemy,playerIndex,controllerColor)
	local playerData=turnOrder[playerIndex]
	local details,puppetData=puppetMasterDataForEnemy(enemy)
	if puppet==nil or playerData==nil or details==nil or puppetData==nil then return false end
	puppetMasterPreparePuppet(puppet)
	if gStates.puppetMasterPuppets==nil then gStates.puppetMasterPuppets={} end
	gStates.puppetMasterPuppets[puppet.guid]={ownerMage=playerData.mage,ownerSeat=playerData.seatPos,sourceGUID=enemy.guid,name=puppetData.name or details.name,location="inventory",played=false}
	puppetMasterRefreshPresentation(puppet,gStates.puppetMasterPuppets[puppet.guid])
	playerData.puppetMasterUsed=true
	puppetMasterWarn(playerIndex,tostring(details.name or "Enemy").." was kept as a Puppet.",controllerColor)
	return true
end

function puppetMasterRegisterClone(enemy,pickup)
	local dropPos=enemy.getPosition()
	local dropRot=enemy.getRotation()
	--Object.clone() gives the new token a brief physics/autoraise kick even when spawned at its final
	--position. Build the Puppet from the Enemy's ObjectState instead and keep it locked for its first
	--couple of frames so there is never a clone-separation "pop".
	local puppetData=enemy.getData()
	if puppetData==nil then return false end
	puppetData.GUID=nil
	puppetData.Locked=true
	if pickup.rotation~=nil then enemy.setRotation(pickup.rotation) end
	if pickup.position~=nil then enemy.setPosition(pickup.position) end
	local puppet=spawnObjectData({data=puppetData,position={dropPos[1],dropPos[2],dropPos[3]},rotation={dropRot[1],dropRot[2],dropRot[3]}})
	if puppet==nil then return false end
	puppet.setVelocity({0,0,0})
	puppet.setAngularVelocity({0,0,0})
	puppet.setPosition(dropPos)
	puppet.setRotation(dropRot)
	if puppetMasterRegisterPuppet(puppet,enemy,pickup.player,pickup.color)~=true then puppet.destruct() return false end
	local puppetGUID=puppet.guid
	Wait.frames(function()
		local live=getObjectFromGUID(puppetGUID)
		if live~=nil then
			live.setPosition(dropPos)
			live.setRotation(dropRot)
			live.setVelocity({0,0,0})
			live.setAngularVelocity({0,0,0})
			live.unlock()
		end
	end,2)
	puppetMasterPickup[enemy.guid]=nil
	return true
end

--Deleting or trashing a Puppet immediately after claiming it is treated as undo while the exact real
--Enemy used to create it is still in that Mage Knight's combat area. Once normal combat cleanup has
--removed the source Enemy, disposing of the Puppet is just an ordinary Puppet deletion.
function puppetMasterUndoFreshClaim(puppetGUID,controllerColor)
	local record=gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[puppetGUID] or nil
	if record==nil or record.sourceGUID==nil or record.played==true then return false end
	local owner=puppetMasterRecordOwnerIndex(record)
	local source=getObjectFromGUID(record.sourceGUID)
	if owner==nil or source==nil or puppetMasterCombatAreaPlayer(source.guid)~=owner then return false end
	gStates.puppetMasterPuppets[puppetGUID]=nil
	if gStates.monsterPerks~=nil then gStates.monsterPerks[puppetGUID]=nil end
	puppetMasterPickup[puppetGUID]=nil
	if turnOrder[owner]~=nil then turnOrder[owner].puppetMasterUsed=false end
	puppetMasterWarn(owner,tostring(record.name or "Puppet").." Puppet claim was undone.",controllerColor)
	return true
end

function puppetMasterClaimReason(enemy,pickup,destinationPlayer)
	local playerData=pickup~=nil and turnOrder[pickup.player] or nil
	if playerData==nil or destinationPlayer~=pickup.player then return "That Enemy must be dropped into its owner's Inventory." end
	if pickup.fromCombat~=true then return "Only an Enemy taken directly from your combat area can be kept." end
	if puppetMasterEnemyEligible(enemy)~=true then return "That object is not an eligible Enemy token." end
	if pickup.faceUp~=true or enemy.is_face_down==true then return "Only a defeated, face-up Enemy can be kept." end
	if enemy.guid==darkCrusader.token or enemy.guid==elementalist.token then
		local leaderLevel=enemy.guid==darkCrusader.token and gStates.darkCrusaderLevel or gStates.elementalistLevel
		if leaderLevel~=nil and ((gStates.leaderReduction or 0)+(gStates.leaderOverkill or 0))<leaderLevel then return "A Faction Leader can only be kept after it is completely defeated." end
	end
	if gStates.turnNumber~=pickup.player then return "You can only use the Skill during this Mage Knight's turn." end
	if gStates.preEndTurn==true then return "The turn is already being cleaned up." end
	if puppetMasterOwnsSkill(pickup.player)~=true then return tostring(playerData.mage).." does not own Puppet Master." end
	if playerData.puppetMasterUsed==true then return "Puppet Master has already been used this turn." end
	return nil
end

function puppetMasterResolveEnemyDrop(enemy,pickup)
	local inventoryPlayer=puppetMasterInventoryPlayer(enemy.guid)
	if inventoryPlayer==nil then puppetMasterPickup[enemy.guid]=nil return end
	local reason=puppetMasterClaimReason(enemy,pickup,inventoryPlayer)
	if reason~=nil then puppetMasterReturnToPickup(enemy,pickup,reason) return end
	if puppetMasterRegisterClone(enemy,pickup)~=true then puppetMasterReturnToPickup(enemy,pickup,"The Puppet copy could not be created; the Enemy was returned.") end
end

--Manual copy/paste remains a supported Puppet Master interaction. A pasted token has a new GUID,
--so match its face image to the real defeated Enemy still sitting in that player's combat area.
function puppetMasterManualCopySource(copy,playerIndex)
	local playerData=turnOrder[playerIndex]
	local image=puppetMasterObjectImage(copy)
	if playerData==nil or image==nil or image=="" then return nil end
	for _, enemy in pairs(playerCombatObjects(playerData.seatPos)) do
		if enemy.guid~=copy.guid and puppetMasterEnemyEligible(enemy)==true and puppetMasterObjectImage(enemy)==image then return enemy end
	end
	return nil
end

function puppetMasterResolveManualCopy(copy)
	if copy==nil or copy.guid==nil or monsterPugs[copy.guid]~=nil then return false end
	if gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[copy.guid]~=nil then return false end
	local owner=puppetMasterInventoryPlayer(copy.guid)
	if owner==nil then return false end
	local enemy=puppetMasterManualCopySource(copy,owner)
	if enemy==nil then return false end
	local pickup={kind="manualCopy",player=owner,fromCombat=true,faceUp=enemy.is_face_down==false}
	local reason=puppetMasterClaimReason(enemy,pickup,owner)
	if reason~=nil then
		puppetMasterWarn(owner,reason.." The pasted copy was removed.")
		copy.destruct()
		return true
	end
	if puppetMasterRegisterPuppet(copy,enemy,owner)~=true then
		puppetMasterWarn(owner,"The pasted Enemy could not be registered as a Puppet and was removed.")
		copy.destruct()
	end
	return true
end

function puppetMasterCheckManualCopyWhenResting(obj)
	if obj==nil or obj.guid==nil then return end
	local guid=obj.guid
	Wait.condition(function()
		local live=getObjectFromGUID(guid)
		if live~=nil then puppetMasterResolveManualCopy(live) end
	end,function()
		local live=getObjectFromGUID(guid)
		return live==nil or live.resting==true
	end)
end

function puppetMasterRecordOwnerIndex(record)
	if record==nil then return nil end
	local playerIndex=puppetMasterPlayerIndexForMage(record.ownerMage)
	if playerIndex~=nil then return playerIndex end
	return puppetMasterPlayerIndexForSeat(record.ownerSeat)
end

function puppetMasterResolvePuppetDrop(puppet,pickup)
	local record=gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[puppet.guid] or nil
	if record==nil then puppetMasterPickup[puppet.guid]=nil return end
	local owner=puppetMasterRecordOwnerIndex(record)
	if owner==nil then puppetMasterReturnToPickup(puppet,pickup,"The Puppet's owner could not be identified.") return end
	local inventoryPlayer=puppetMasterInventoryPlayer(puppet.guid)
	if inventoryPlayer==owner then
		record.location="inventory"
		record.lastInventoryPosition={puppet.getPosition()[1],puppet.getPosition()[2],puppet.getPosition()[3]}
		record.lastInventoryRotation={puppet.getRotation()[1],puppet.getRotation()[2],puppet.getRotation()[3]}
		puppetMasterPickup[puppet.guid]=nil
		return
	end
	local combatPlayer=puppetMasterCombatAreaPlayer(puppet.guid)
	if combatPlayer~=owner then puppetMasterReturnToPickup(puppet,pickup,"A stored Puppet can only be played into its owner's combat area.") return end
	local playerData=turnOrder[owner]
	if gStates.turnNumber~=owner then puppetMasterReturnToPickup(puppet,pickup,"You can only use the Skill during this Mage Knight's turn.") return end
	if gStates.preEndTurn==true then puppetMasterReturnToPickup(puppet,pickup,"The turn is already being cleaned up.") return end
	if puppetMasterOwnsSkill(owner)~=true then puppetMasterReturnToPickup(puppet,pickup,tostring(playerData.mage).." does not own Puppet Master.") return end
	if playerData.puppetMasterUsed==true then puppetMasterReturnToPickup(puppet,pickup,"Puppet Master has already been used this turn.") return end
	playerData.puppetMasterUsed=true
	record.played=true
	record.location="played"
	puppetMasterPickup[puppet.guid]=nil
	puppetMasterWarn(owner,tostring(record.name or "Puppet").." was played; no Enemy can be kept with Puppet Master this turn.",pickup.color)
end

function puppetMasterTrackPickup(playerColor,obj)
	if obj==nil or obj.guid==nil then return end
	puppetMasterPickup[obj.guid]=nil
	local puppetRecord=gStates.puppetMasterPuppets~=nil and gStates.puppetMasterPuppets[obj.guid] or nil
	if puppetRecord~=nil and puppetRecord.played~=true and puppetRecord.location=="inventory" then
		local owner=puppetMasterRecordOwnerIndex(puppetRecord)
		if owner~=nil and puppetMasterColorCanMovePlayer(playerColor,owner)==true then
			puppetMasterPickup[obj.guid]={kind="puppet",player=owner,color=playerColor,position={obj.getPosition()[1],obj.getPosition()[2],obj.getPosition()[3]},rotation={obj.getRotation()[1],obj.getRotation()[2],obj.getRotation()[3]}}
		end
		return
	end
	if puppetMasterEnemyEligible(obj)~=true then return end
	local combatPlayer=puppetMasterCombatAreaPlayer(obj.guid)
	if combatPlayer==nil or puppetMasterColorCanMovePlayer(playerColor,combatPlayer)~=true then return end
	puppetMasterPickup[obj.guid]={kind="enemy",player=combatPlayer,color=playerColor,fromCombat=true,faceUp=obj.is_face_down==false,position={obj.getPosition()[1],obj.getPosition()[2],obj.getPosition()[3]},rotation={obj.getRotation()[1],obj.getRotation()[2],obj.getRotation()[3]}}
end

function puppetMasterDropped(obj)
	if obj==nil or obj.guid==nil then return false end
	local pickup=puppetMasterPickup[obj.guid]
	if pickup==nil then return false end
	local guid=obj.guid
	Wait.condition(function()
		local live=getObjectFromGUID(guid)
		if live==nil or puppetMasterPickup[guid]~=pickup then return end
		if pickup.kind=="enemy" then puppetMasterResolveEnemyDrop(live,pickup)
		elseif pickup.kind=="puppet" then puppetMasterResolvePuppetDrop(live,pickup)
		else puppetMasterPickup[guid]=nil end
	end,function()
		local live=getObjectFromGUID(guid)
		return live==nil or puppetMasterPickup[guid]~=pickup or live.resting==true
	end)
	return true
end

function puppetMasterCleanupPlayedPuppets(playerIndex)
	local details=turnOrder[playerIndex]
	if details==nil or gStates.puppetMasterPuppets==nil then return end
	for guid, record in pairs(gStates.puppetMasterPuppets) do
		if record.ownerMage==details.mage and record.played==true then
			local puppet=getObjectFromGUID(guid)
			gStates.puppetMasterPuppets[guid]=nil
			if gStates.monsterPerks~=nil then gStates.monsterPerks[guid]=nil end
			puppetMasterPickup[guid]=nil
			if puppet~=nil then puppet.destruct() end
		end
	end
end

--give mana token if starting on a Glade
function startOfTurn()
	if apocalypseQuestsUsed()==true then gStates.apocalypseQuestScoringChoiceLocked=true end
	local currentPlayer=turnOrder[gStates.turnNumber]
	if currentPlayer~=nil then currentPlayer.puppetMasterUsed=false end
	gStates.volkarePursuitEnemies={}
	gStates.volkarePursuitCombat=nil
	gStates.volkarePursuitChoicePlayer=nil
	--Camera-choice suppression belongs only to the combat choice that created it. A new turn always starts clean.
	combatCameraChoiceSuppressedPlayer=nil
	resetMeditationTranceState()
	--Quest Score markers are physical/unlocked so players can correct them manually. Revalidate them
	--once per turn in case board physics displaced one between score changes.
	apocalypseQuestRefreshScoreMarkers()
	local virtualCoopCombat=coopAssaultVirtualPlayer(gStates.turnNumber)
	local horsemenGladeReturned=false
	if virtualCoopCombat==false and currentPlayer~=nil and gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted~=true and
		(againstHorsemenPlayerAtCentralGlade(currentPlayer)==true or currentPlayer.horsemenGladeParked==true) then
		portalSwap("startOfTurn", gStates.turnNumber)
		horsemenGladeReturned=true
	end
	local proxyStart=virtualCoopCombat==false and proxyPlayerActive()==true and currentPlayer~=nil and currentPlayer.mage==gStates.positionMageKnight[5]
	if virtualCoopCombat==false and currentPlayer~=nil and currentPlayer.mage==gStates.positionMageKnight[5] and gStates.positionMageKnight[5]~="Volkare" then
		currentPlayer.dummyProcessedThisTurn=false
		if proxyStart==true then gStates.proxyState="Start" end
	end
	--The Proxy has a turn in the order, but is not a normal Mage Knight player. Do only the shared turn
	--cleanup above plus the UI/avatar parking needed to process them. In particular, do not run Quest
	--start hooks, hand/discard/tactic bookkeeping, pursuit start-position tracking, or site benefits such
	--as Glades and Oases.
	if proxyStart==true then
		mainUIUpdate("New Turn")
		portalSwap("startOfTurn", gStates.turnNumber)
		return
	end
	if virtualCoopCombat==false then
		gStates.apocalypseQuestTurnSerial=(gStates.apocalypseQuestTurnSerial or 0)+1
		if gStates.apocalypseQuestConqueredThisTurn==nil then gStates.apocalypseQuestConqueredThisTurn={} end
		--Do Object-UI XML work after the turn-advance click callback has fully unwound.
		local questRefreshTurn=gStates.turnNumber
		Wait.frames(function()
			if gStates.turnNumber==questRefreshTurn then
				apocalypseQuestRichMerchantStartTurn()
				apocalypseQuestOfferRefresh()
			end
		end, 1)
	end
	Wait.frames(function() refreshFracturedLandsTeleportHighlights() end, 1)
	if gStates.gladeDiscardHealUsed==nil then gStates.gladeDiscardHealUsed={} end
	if virtualCoopCombat==false and turnOrder[gStates.turnNumber]~=nil then gStates.gladeDiscardHealUsed[turnOrder[gStates.turnNumber].seatPos]=nil end
	--Records current amount of discarded cards
	turnOrder[gStates.turnNumber].discardCount=0
	for _, b in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
		if b.type=="Card" then turnOrder[gStates.turnNumber].discardCount=1 break end
		if b.type=="Deck" then turnOrder[gStates.turnNumber].discardCount=b.getQuantity() break end
	end

	--remove the manual increase to hand size
	turnOrder[gStates.turnNumber].handBonus=0
	refreshTactic4HandBonus(false)

	--record avatar start location
	for b, details in pairs(mageKnights) do
		if details.mage==turnOrder[gStates.turnNumber].mage then
			if getObjectFromGUID(details.model)~=nil then turnOrder[gStates.turnNumber].turnStartLoc=getObjectFromGUID(details.model).getPosition() end
			if getObjectFromGUID(details.token)~=nil then turnOrder[gStates.turnNumber].turnStartLoc=getObjectFromGUID(details.token).getPosition() end
			if getObjectFromGUID(details.standee)~=nil then turnOrder[gStates.turnNumber].turnStartLoc=getObjectFromGUID(details.standee).getPosition() end
		end
	end
	if againstHorsemenPlayerAtCentralGlade(turnOrder[gStates.turnNumber])==true then
		local gladePos=againstHorsemenCentralGladePosition(1.5)
		if gladePos~=nil then turnOrder[gStates.turnNumber].turnStartLoc=gladePos end
	end
	if turnOrder[gStates.turnNumber].avatarLocation~=nil and (turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" or turnOrder[gStates.turnNumber].avatarLocation=="Volkare's Camp") then
		--figure out which city avatar is in
		for zone, citySearch in pairs(cityScriptZones) do
			for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
				if detail.getName()==turnOrder[gStates.turnNumber].mage then
					turnOrder[gStates.turnNumber].turnStartLoc=getObjectFromGUID(citySearch.cityGUID).getPosition()
					break
				end
			end
		end
	end

	--A co-op assistant's combat step is not a new turn at the temporary assault location.
	--Do not grant Glade/Hidden Valley/Necropolis/Graveyard/Oasis start-of-turn benefits.
	if virtualCoopCombat==false and (turnOrder[gStates.turnNumber].avatarLocation=="glade" or turnOrder[gStates.turnNumber].avatarLocation=="graveyard"
	 	or turnOrder[gStates.turnNumber].avatarLocation=="hidden valley" or turnOrder[gStates.turnNumber].avatarLocation=="necropolis") then
		--check if glade is conquered
		if gladeFreeCheck()==true then
			local params={position={(turnOrder[gStates.turnNumber].seatPos*40)-103, 1.65, -39}, rotation={0, 0, 0}, smooth=false}
			if gStates.dayRound==true and turnOrder[gStates.turnNumber].avatarLocation~="graveyard" and turnOrder[gStates.turnNumber].avatarLocation~="necropolis" then
				getObjectFromGUID("4a836f").takeObject(params)
				broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} gained a Gold Mana Token from the Magical Glade.{ru} получает Золотой жетон маны от Магической поляны.{zh-cn}从魔法林地中获得一个金色魔晶{ko}: 마법 숲속 빈터에서 금색 마나 획득{es} ganó una ficha de Maná de Oro del Claro Mágico.{fr} gagné un jeton de Mana D'or de la Clairière Magique.{pt-br} marcador de Mana Dourada ganho da Clareira Mágica.{de} erhält ein goldenes Mana-Plättchen von der magischen Lichtung."}), positionToColor(gStates.turnNumber))
			end
			if gStates.dayRound==false then
				getObjectFromGUID("74d666").takeObject(params)
				if turnOrder[gStates.turnNumber].avatarLocation~="graveyard" and turnOrder[gStates.turnNumber].avatarLocation~="necropolis" then
					broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} gained a Black Mana Token from the Magical Glade.{ru} получает Черный жетон маны от Магической поляны.{zh-cn}从魔法林地中获得一个黑色魔晶{ko}: 마법 숲속 빈터에서 흑색 마나 획득{es} ganó una ficha de Maná Negra del Claro Mágico.{fr} gagné un jeton de Mana Noir de la Clairière Magique.{pt-br} marcador de Mana Preta ganho da Clareira Mágica.{de} ein schwarzes Mana-Plättchen von der Magischen Lichtung erhalten."}), positionToColor(gStates.turnNumber))
				else
					broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} gained a Black Mana Token from the Graveyard.{ru} получает Черный жетон маны от Кладбища.{zh-cn}从墓地增加一个黑色魔力{ko}: 묘지에서 흑색 마나 획득{es} ganó una ficha de Maná Negra del Cementerio.{fr} gagné un jeton de Mana Noir du Cimetière.{pt-br} marcador de Mana Preta ganho do Cemitério.{de} ein schwarzes Mana-Plättchen vom Friedhof erhalten."}), positionToColor(gStates.turnNumber))
				end
			end
		end
	end

	--Gain Reminder token from oasis
	if virtualCoopCombat==false and turnOrder[gStates.turnNumber].avatarLocation=="oasis" then
		getObjectFromGUID("a8bf9c").clone({position={(turnOrder[gStates.turnNumber].seatPos*40)-103, 1.65, -39}, rotation={0.00, 180.00, 0.00}, smooth=false}).unlock()
	end

	mainUIUpdate("New Turn")

	--During a co-op assault an assistant is only virtually at the assault location until the result is known.
	if virtualCoopCombat==false and horsemenGladeReturned==false then portalSwap("startOfTurn", gStates.turnNumber) end
end

function realmDeadEnemiesAtPosition(position)
	if position==nil or position[1]==nil then return false end
	local map=getObjectFromGUID(mapArea)
	if map==nil then return false end
	for _, obj in pairs(map.getObjects()) do
		local data=monsterPugs[obj.guid]
		if data~=nil and data.pugType~="possessed" then
			local pos=obj.getPosition()
			if ((pos[1]-position[1])^2)+((pos[3]-position[3])^2)<1 then return true end
		end
	end
	return false
end

function currentMageAvatarPosition(playerIndex)
	local player=turnOrder[playerIndex]
	if player==nil then return nil end
	for _, avatar in pairs(mageKnights) do
		if avatar.mage==player.mage then
			if getObjectFromGUID(avatar.model)~=nil then return getObjectFromGUID(avatar.model).getPosition() end
			if getObjectFromGUID(avatar.token)~=nil then return getObjectFromGUID(avatar.token).getPosition() end
			if getObjectFromGUID(avatar.standee)~=nil then return getObjectFromGUID(avatar.standee).getPosition() end
		end
	end
	return nil
end

function hiddenValleyLiberated()
	if gStates.gameScenario~="The Hidden Valley Blitz" then return true end
	if (gStates.elementalistLevel or 1)<=0 then return true end
	local monsters=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[elementalist.terrainHex] or nil
	if monsters~=nil and monsters[elementalist.token]=="dead" then return true end
	if gStates.defeatedFactionTest~=nil and gStates.defeatedFactionTest[elementalist.terrainHex]=="Beat" then return true end
	return false
end

function gladeFreeCheck()
	local player=turnOrder[gStates.turnNumber]
	if player==nil then return true end
	local location=player.avatarLocation
	if gStates.gameScenario=="The Realm of the Dead Blitz" then
		if location=="graveyard" then return realmDeadEnemiesAtPosition(currentMageAvatarPosition(gStates.turnNumber))~=true end
		if location=="necropolis" then return (gStates.defeatedFaction or 0)>0 end
		return true
	end
	if gStates.gameScenario=="The Hidden Valley Blitz" then
		if location=="hidden valley" then return hiddenValleyLiberated() end
		return true
	end
	local gladeOpen=true
	if gStates.gameScenario=="Life and Death" and (location=="glade" or location=="graveyard") then
		gladeOpen=false
		local avatarLocation=currentMageAvatarPosition(gStates.turnNumber)
		if avatarLocation==nil then return false end
		local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
		table.sort(objectsInPlay, function (k1, k2) return k1.getPosition()[2]>k2.getPosition()[2] end)
		for _, obj in pairs(objectsInPlay) do
			if obj.getName()=="Shield" and volkarePursuitShieldRegistered(obj)~=true then
				if math.sqrt(((obj.getPosition()[1]-avatarLocation[1])^2)+((obj.getPosition()[3]-avatarLocation[3])^2))<1 then
					gladeOpen=true
					break
				end
			end
		end
	end
	return gladeOpen
end



againstHorsemenSharedHexKey="horsemenCentralGlade"

function againstHorsemenCentralGladeHex(terrain, bearing)
	return gStates~=nil and gStates.gameScenario=="Against the Horsemen Blitz" and terrain~=nil
		and terrain.guid==GUID.tile.country01 and tostring(bearing)=="center"
end

function againstHorsemenCentralGladePosition(y)
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" then return nil end
	local terrain=getObjectFromGUID(GUID.tile.country01)
	if terrain==nil then return nil end
	local p=terrain.getPosition()
	p[2]=y or 1.5
	return p
end

function againstHorsemenPlayerAtCentralGlade(player)
	return gStates~=nil and gStates.gameScenario=="Against the Horsemen Blitz" and player~=nil
		and player.avatarLocation=="glade" and player.avatarSharedHex==againstHorsemenSharedHexKey
end

function againstHorsemenSetStartingAvatarLocations()
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" then return end
	for playerIndex,player in pairs(turnOrder or {}) do
		--The standard Dummy has no map figure. Human Mage Knights and the optional Proxy do, including
		--the five-avatar case where the Proxy's physical storage starts on the Dummy board.
		local proxyAvatar=proxyPlayerActive()==true and player.mage==gStates.positionMageKnight[5]
		if (player.avatarLocation~=nil or proxyAvatar==true) and player.mage~=nil and player.mage~="nobody" and player.mage~="Volkare" then
			player.avatarLocation="glade"
			player.avatarSharedHex=againstHorsemenSharedHexKey
			player.avatarSwapCity=nil
			player.horsemenGladeParked=true
			--Physically park every shared-Glade avatar on the Portal card during tactic selection.
			--startOfTurn() will put the active Mage Knight on Country 01's centre and keep the others parked.
			portalSwap("endOfTurn",playerIndex)
		end
	end
end

function portalSwap(state, playerIndex)
	playerIndex=playerIndex or gStates.turnNumber
	local player=turnOrder[playerIndex]
	--There is no Portal map hex in Against the Horsemen. Normalize any setup Portal state
	--to the shared central Glade before deciding where the active avatar belongs. Also remember when a
	--Mage Knight was deliberately parked from that Glade so later callbacks cannot lose the logical hex.
	if player~=nil and gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted~=true then
		if player.avatarLocation=="portal" or (state=="startOfTurn" and player.horsemenGladeParked==true) then
			player.avatarLocation="glade"
			player.avatarSharedHex=againstHorsemenSharedHexKey
		end
	end
	local horsemenGlade=againstHorsemenPlayerAtCentralGlade(player) and gStates.againstHorsemenRitualStarted~=true
	if player==nil or player.avatarLocation==nil or (player.avatarLocation~="portal" and player.avatarLocation:sub(1, 4)~="city" and horsemenGlade~=true) or gStates.gameScenario=="The Lost Relic Blitz" then return end
	--A closed Portal is an ordinary single-occupancy map hex. City avatar swapping remains unchanged.
	local portalClosed=(gStates.gameScenario=="Volkare's Quest" and gStates.volkarePortalClosed==true) or
		(gStates.gameScenario=="One to Return" and gStates.oneToReturnPortalClosed==true)
	if player.avatarLocation=="portal" and portalClosed==true then return end
	local portalPosition={{-45.5, 1.1, -11.4}, {-42.5, 1.1, -11.4}, {-45.5, 1.1, -13.2}, {-42.5, 1.1, -13.2}}
	local cityConvert={["red"]=cityModel.red, ["whi"]=cityModel.white, ["blu"]=cityModel.blue, ["gre"]=cityModel.green}
	local isProxy=proxyPlayerActive()==true and player.mage==gStates.positionMageKnight[5]
	local parkingSeat=isProxy==true and gStates.proxyParkingSeat or player.seatPos

	local function dummyBoardParking()
		local board=getObjectFromGUID(dummyBoard)
		if board~=nil then local p=board.getPosition() return {p[1],1.4,p[3]} end
		return {-43.94,1.4,-12.36}
	end

	local function portalParking(index)
		local details=turnOrder[index]
		if details==nil then return nil end
		if proxyPlayerActive()==true and details.mage==gStates.positionMageKnight[5] then
			local seat=gStates.proxyParkingSeat
			return seat~=nil and portalPosition[seat] or dummyBoardParking()
		end
		return portalPosition[details.seatPos]
	end

	local function moveAvatar(index, destination)
		if turnOrder[index]==nil or destination==nil then return end
		for _, details in pairs(mageKnights) do
			if details.mage==turnOrder[index].mage then
				if getObjectFromGUID(details.model)~=nil then getObjectFromGUID(details.model).setPositionSmooth(destination) end
				if getObjectFromGUID(details.token)~=nil then getObjectFromGUID(details.token).setPositionSmooth(destination) end
				if getObjectFromGUID(details.standee)~=nil then getObjectFromGUID(details.standee).setPositionSmooth(destination) end
				break
			end
		end
	end

	local avatarDestination={-24.03, 1.11, -16.08}--fallback wedge portal hex location
	local startTile=getObjectFromGUID(startTerrain.wedge) or getObjectFromGUID(startTerrain.open)
	if startTile~=nil then
		local startPos=startTile.getPosition()
		avatarDestination={startPos[1],1.11,startPos[3]}
	end
	if state=="startOfTurn" then
		if player.avatarLocation=="portal" then
			--Only the active Mage Knight belongs on the physical portal hex. Park every other
			--portal Mage Knight on their own portal-card slot (or the Dummy board for a 4-player Proxy).
			for otherIndex, other in pairs(turnOrder) do
				if otherIndex~=playerIndex and other.avatarLocation=="portal" then moveAvatar(otherIndex,portalParking(otherIndex)) end
			end
		elseif horsemenGlade==true then
			--Country01's centre is a shared space in this scenario. Inactive occupants remain parked
			--on the Portal card; only the active Mage Knight is represented on the Glade itself.
			for otherIndex, other in pairs(turnOrder) do
				if otherIndex~=playerIndex and againstHorsemenPlayerAtCentralGlade(other)==true then
					other.horsemenGladeParked=true
					moveAvatar(otherIndex,portalParking(otherIndex))
				end
			end
			avatarDestination=againstHorsemenCentralGladePosition(1.5)
			if avatarDestination==nil then return end
			player.horsemenGladeParked=false
		else
			local cityObj=getObjectFromGUID(cityConvert[player.avatarLocation:sub(6, 8)])
			if cityObj==nil then return end
			avatarDestination=cityObj.getPosition()
			if player.avatarSwapCity~=nil and getObjectFromGUID(player.avatarSwapCity)~=nil then avatarDestination=getObjectFromGUID(player.avatarSwapCity).getPosition() end
			avatarDestination[2]=avatarDestination[2]+2
		end
		player.avatarSwapCity=nil
	else
		local parkedPosition=portalParking(playerIndex)
		if parkedPosition==nil then return end
		avatarDestination=parkedPosition
		if horsemenGlade==true then player.horsemenGladeParked=true end
		if player.avatarLocation:sub(1, 4)=="city" then
			local cityGUID=cityConvert[player.avatarLocation:sub(6, 8)]
			local cardGUID=gStates.cityCard[cityGUID]
			local cityCard=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
			if cityCard==nil then return end
			if isProxy==true and parkingSeat==nil then
				--Four human players already occupy every normal City-card parking slot.
				avatarDestination=dummyBoardParking()
			else
				avatarDestination=cityCard.getPosition()
				local seat=parkingSeat or player.seatPos
				avatarDestination[1]=(avatarDestination[1]+(seat*1.83))-4.58
				avatarDestination[2]=avatarDestination[2]+1
				avatarDestination[3]=avatarDestination[3]-0.66
			end
			player.avatarSwapCity=cityGUID
		end
	end
	moveAvatar(playerIndex, avatarDestination)
end

--Physical activation state is kept separately from doingTheRounds. Tome/Circlet can move a real token
--after it has been played, while the effect that token created may still need to survive.
local function skillPositionCopy(position)
	if position==nil then return nil end
	return {position[1], position[2], position[3]}
end

local function coopCompSkillActivationTable()
	if gStates.coopCompSkillActivation==nil then gStates.coopCompSkillActivation={} end
	return gStates.coopCompSkillActivation
end

local function coopCompSkillOwnedAreaPlayer(position)
	if position==nil or position[3]>=-35 then return nil end
	for playerIndex, details in pairs(turnOrder) do
		if details.seatPos~=nil and math.abs(position[1]-((details.seatPos*40)-107.45))<2 then return playerIndex end
	end
	return nil
end

local function coopCompSkillPoolPosition(position)
	return position~=nil and position[3]>-25
end

local function coopCompSkillBroadcast(message, playerIndex)
	if playerIndex~=nil and turnOrder[playerIndex]~=nil then broadcastToAll(message, positionToColor(playerIndex))
	else broadcastToAll(message, {1,1,0.5}) end
end

local function deactivateCoopCompSkill(skillGUID, showBroadcast)
	local active=coopCompSkillActivationTable()
	local record=active[skillGUID]
	if record==nil then return false end
	active[skillGUID]=nil
	if showBroadcast~=false then coopCompSkillBroadcast("Skill Deactivated", record.player) end
	return true
end

--A Tome swap is inferred from an owned Skill being physically dropped in the common Skill area. This
--also lets a replacement go straight from the pool into the Play Area without losing its new home.
local function tomeSkillSwapTable()
	if gStates.tomeSkillSwapPending==nil then gStates.tomeSkillSwapPending={} end
	return gStates.tomeSkillSwapPending
end

--Motivation ownership is normally assigned by the Skill claim button. Tome/Circlet swaps are physical,
--so mirror that ownership here and refresh only the Out of Turn Actions menu.
local function tomeMotivationSnapshot(skillGUID)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	if stats==nil then return nil end
	return {pos=stats.pos, state=stats.state}
end

local function tomeRestoreMotivation(skillGUID, snapshot)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	if stats==nil or snapshot==nil then return false end
	stats.pos=snapshot.pos
	stats.state=snapshot.state
	return true
end

local function tomeAssignMotivation(skillGUID, playerIndex)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	local player=turnOrder[playerIndex]
	if stats==nil or player==nil or player.seatPos==nil then return false end
	stats.pos=player.seatPos
	stats.state="active"
	return true
end

local function tomeRemoveMotivationOwner(skillGUID)
	local stats=gStates.motivationSkill~=nil and gStates.motivationSkill[skillGUID] or nil
	if stats==nil then return false end
	stats.pos=0
	return true
end

local function tomeRefreshMotivationUI(changed)
	if changed==true and refreshOutOfTurnActions~=nil then refreshOutOfTurnActions(nil, nil, true, false) end
end

local function tomeRestoreReplacement(pending, deactivateReplacement)
	if pending==nil or pending.replacementGUID==nil then return end
	local replacementGUID=pending.replacementGUID
	if pending.replacementPoolHome~=nil then gStates.mageSkills[replacementGUID]=skillPositionCopy(pending.replacementPoolHome) end
	local motivationChanged=tomeRestoreMotivation(replacementGUID, pending.replacementMotivation)
	if deactivateReplacement==true then
		local record=coopCompSkillActivationTable()[replacementGUID]
		if record~=nil and record.tomeReplacement==true and gStates.doingTheRounds[replacementGUID]==nil then deactivateCoopCompSkill(replacementGUID, true) end
	end
	pending.replacementGUID=nil
	pending.replacementPoolHome=nil
	pending.replacementMotivation=nil
	tomeRefreshMotivationUI(motivationChanged)
end

local function tomeUndoSkillSwap(playerIndex)
	local swaps=tomeSkillSwapTable()
	local pending=swaps[playerIndex]
	if pending==nil then return false end
	tomeRestoreReplacement(pending, true)
	if pending.oldSkill~=nil and pending.ownerHome~=nil then gStates.mageSkills[pending.oldSkill]=skillPositionCopy(pending.ownerHome) end
	local motivationChanged=tomeRestoreMotivation(pending.oldSkill, pending.oldMotivation)
	swaps[playerIndex]=nil
	tomeRefreshMotivationUI(motivationChanged)
	return true
end

local function tomeAssignReplacement(skillGUID, playerIndex)
	local pending=tomeSkillSwapTable()[playerIndex]
	if pending==nil or skillGUID==pending.oldSkill then return false end
	if pending.replacementGUID==skillGUID then return true end
	local currentHome=gStates.mageSkills[skillGUID]
	if coopCompSkillPoolPosition(currentHome)~=true then return false end
	tomeRestoreReplacement(pending, true)
	pending.replacementGUID=skillGUID
	pending.replacementPoolHome=skillPositionCopy(currentHome)
	pending.replacementMotivation=tomeMotivationSnapshot(skillGUID)
	gStates.mageSkills[skillGUID]=skillPositionCopy(pending.ownerHome)
	tomeRefreshMotivationUI(tomeAssignMotivation(skillGUID, playerIndex))
	return true
end

local function tomeSkillEnteredPlay(skillGUID, playerIndex)
	local pending=tomeSkillSwapTable()[playerIndex]
	if pending==nil then return end
	if skillGUID==pending.oldSkill then tomeUndoSkillSwap(playerIndex)
	else tomeAssignReplacement(skillGUID, playerIndex) end
end

--Run immediately on human drop, before the older resting/home-position update, so a quick physical
--swap cannot put the replacement into the Play Area before we remember which owned Skill was traded.
local function tomeSkillDropped(skillGUID, position)
	if skillGUID==nil or skillTokens[skillGUID]==nil or position==nil then return end
	local swaps=tomeSkillSwapTable()

	--Returning a tentative replacement to the pool means the player changed their choice.
	if coopCompSkillPoolPosition(position)==true then
		for _, pending in pairs(swaps) do
			if pending.replacementGUID==skillGUID then
				tomeRestoreReplacement(pending, true)
				break
			end
		end
	end

	--Dropping the original Skill back into its owner's Skill column cancels the physical swap.
	local droppedOwner=coopCompSkillOwnedAreaPlayer(position)
	if droppedOwner~=nil then
		local pending=swaps[droppedOwner]
		if pending~=nil then
			if pending.oldSkill==skillGUID then tomeUndoSkillSwap(droppedOwner) return
			elseif tomeAssignReplacement(skillGUID, droppedOwner)==true then return end
		end
	end

	--An owned Skill entering the common offer begins/replaces the pending Tome transaction. A temporary
	--Circlet Skill already has a pool home, so it deliberately does not satisfy this test.
	if coopCompSkillPoolPosition(position)==true then
		local oldHome=gStates.mageSkills[skillGUID]
		local owner=coopCompSkillOwnedAreaPlayer(oldHome)
		if owner~=nil then
			local existing=swaps[owner]
			if existing~=nil and existing.oldSkill~=skillGUID then tomeUndoSkillSwap(owner) end
			swaps[owner]={player=owner, oldSkill=skillGUID, ownerHome=skillPositionCopy(oldHome), oldPoolHome=skillPositionCopy(position), oldMotivation=tomeMotivationSnapshot(skillGUID)}
			--Commit the traded Skill's new home immediately; the older resting callback will refine the exact Y/Z later.
			gStates.mageSkills[skillGUID]=skillPositionCopy(position)
			tomeRefreshMotivationUI(tomeRemoveMotivationOwner(skillGUID))
		end
	end
end

local function activateCoopCompSkill(skillGUID, playerIndex)
	local details=skillTokens[skillGUID]
	if details==nil or (details.skillType~="Coop" and details.skillType~="Comp") then return end
	local active=coopCompSkillActivationTable()
	local record=active[skillGUID]
	if record==nil then
		--A newly played Interactive skill is illegal once End of Round / Scenario End has locked new plays.
		if coopCompSkillPlayLocked~=nil and coopCompSkillPlayLocked()==true then return end
		record={player=playerIndex, round=gStates.currentRound, location="play"}
		local pending=tomeSkillSwapTable()[playerIndex]
		if pending~=nil and pending.replacementGUID==skillGUID then record.tomeReplacement=true end
		active[skillGUID]=record
		coopCompSkillBroadcast("Skill Activated", playerIndex)
	else
		if record.player==nil then record.player=playerIndex end
		record.location="play"
		record.detached=nil
		record.leftPlayArea=nil
	end
end

local function coopCompSkillLeftPlayArea(skillGUID, playerIndex)
	local record=coopCompSkillActivationTable()[skillGUID]
	if record==nil then return end
	record.leftPlayArea=true
	record.leftPlayer=playerIndex
	record.location="moving"
end

local function coopCompSkillDropped(skillGUID, position)
	local record=coopCompSkillActivationTable()[skillGUID]
	if record==nil then return end
	if coopCompSkillPoolPosition(position)==true then
		--A tentative Tome replacement being put back is an undo, not a surviving activation.
		if record.tomeReplacement==true then return end
		if record.location~="pool" then coopCompSkillBroadcast("Skill Still Activated", record.player) end
		record.location="pool"
		record.detached=true
		record.leftPlayArea=nil
		return
	end
	if coopCompSkillOwnedAreaPlayer(position)~=nil then
		if gStates.doingTheRounds[skillGUID]~=nil and doingTheRounds~=nil then doingTheRounds(skillGUID, "", 0, true)
		else deactivateCoopCompSkill(skillGUID, true) end
	end
end

local function commitTomeSkillSwap(playerIndex)
	local swaps=tomeSkillSwapTable()
	local pending=swaps[playerIndex]
	if pending==nil then return end
	if pending.replacementGUID~=nil then
		local record=coopCompSkillActivationTable()[pending.replacementGUID]
		if record~=nil then record.tomeReplacement=nil end
	end
	swaps[playerIndex]=nil
end

local function unlockCommonSkillPoolTokens()
	for skillGUID, position in pairs(gStates.mageSkills or {}) do
		if coopCompSkillPoolPosition(position)==true then
			local skill=getObjectFromGUID(skillGUID)
			if skill~=nil then skill.unlock() end
		end
	end
end

--Coop/competitive skills cannot be newly played after End of Round or Scenario End.
function coopCompSkillPlayLocked()
	return gStates.endRoundCalled==true or (gStates.endGameAchieved~=nil and gStates.endGameAchieved~="false")
end

function coopCompSkillPlayAreaPlayer(skillGUID)
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.seatPos~=nil then
			local playArea=getObjectFromGUID(playerPlayAreas[playerDetails.seatPos])
			if playArea~=nil then
				for _, obj in pairs(playArea.getObjects()) do if obj.guid==skillGUID then return playerIndex end end
			end
		end
	end
	return nil
end

--Mark Coop/Competitive skills that cannot be newly played. Skills already legally doing the rounds stay available.
function coopCompSkillXClick() end
local function clearCoopCompSkillX(skill)
	local remove={}
	for _, button in pairs(skill.getButtons() or {}) do if button.click_function=="coopCompSkillXClick" then remove[#remove+1]=button.index end end
	table.sort(remove, function(a,b) return a>b end)
	for _, index in ipairs(remove) do skill.removeButton(index) end
end
function refreshCoopCompSkillXs()
	local locked=coopCompSkillPlayLocked()
	for skillGUID, details in pairs(skillTokens) do
		if details.skillType=="Coop" or details.skillType=="Comp" then
			local skill=getObjectFromGUID(skillGUID)
			if skill~=nil then
				clearCoopCompSkillX(skill)
				local paused=gStates.coopCompSkillPaused~=nil and gStates.coopCompSkillPaused[skillGUID]~=nil
				local inRotation=gStates.doingTheRounds[skillGUID]~=nil and paused==false
				if locked==true and inRotation==false then
					skill.createButton({click_function="coopCompSkillXClick", function_owner=Global, label="X", position={0,0.25,0}, rotation={0,0,0}, width=0, height=0, font_size=800, font_color={1,0.1,0.1}, tooltip="Unavailable after End of Round / Scenario End"})
				end
			end
		end
	end
end

function pauseLateCoopCompSkill(skillGUID, playerIndex)
	if skillTokens[skillGUID]==nil or (skillTokens[skillGUID].skillType~="Coop" and skillTokens[skillGUID].skillType~="Comp") then return false end
	if coopCompSkillPlayLocked()==false then return false end
	if playerIndex==nil then playerIndex=coopCompSkillPlayAreaPlayer(skillGUID) end
	if playerIndex==nil then return false end
	if gStates.coopCompSkillPaused==nil then gStates.coopCompSkillPaused={} end
	if gStates.coopCompSkillPaused[skillGUID]==nil then
		gStates.coopCompSkillPaused[skillGUID]={round=gStates.currentRound, player=playerIndex}
		--Keep it registered as doing the rounds so the normal next-round reset returns it home, but skip movement until then.
		if gStates.doingTheRounds[skillGUID]==nil then gStates.doingTheRounds[skillGUID]=playerIndex end
		broadcastToAll("Cooperative and Competitive Skills cannot be played after End of Round has been called or Scenario End has been achieved. Skill automation is paused until the next round.", {1,0.5,0})
		refreshCoopCompSkillXs()
	end
	return true
end

--Competitive skill clones are reminders only and are never registered as skills. Source Freeze and Mana Suppression stay played for their owner reward.
local sharedSkillAboveZone={	["725de9"]="40ef14",--Krang's Coop Skill
							["818aea"]="8fc095",--Tovak's Coop Skill
							["c4546c"]="d28865",--Tovak's Comp Skill
							["958209"]="22b866"}--Krang's Comp Skill
local competitiveOwnerReward={ ["3bd08e"]=true, ["958209"]=true }

local function lockCompetitiveSkillCloneWhenSettled(clone)
	if clone==nil then return end
	local cloneGUID=clone.guid
	clone.unlock()
	Wait.frames(function() Wait.condition(function()
		local obj=getObjectFromGUID(cloneGUID)
		if obj~=nil then obj.lock() end
	end, function()
		local obj=getObjectFromGUID(cloneGUID)
		return obj==nil or obj.resting
	end) end, 5)
end

local function competitiveSkillPlayerForSeat(seatPos)
	for playerIndex, details in pairs(turnOrder) do
		if details.seatPos==seatPos and details.seatPos<5 and details.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false then return playerIndex end
	end
	return nil
end

local function competitiveSkillReminderCount(seatPos)
	local count=0
	for _, record in pairs(gStates.competitiveSkillReminders or {}) do
		for reminderGUID, reminderSeat in pairs(record.reminders or {}) do
			if reminderSeat==seatPos and getObjectFromGUID(reminderGUID)~=nil then count=count+1 end
		end
	end
	return count
end

local basicManaToken={ ["Red Mana"]=true, ["Blue Mana"]=true, ["Green Mana"]=true, ["White Mana"]=true }

local function competitiveSkillReminderForSeat(record, seatPos)
	for reminderGUID, reminderSeat in pairs(record.reminders or {}) do
		if reminderSeat==seatPos then
			local reminder=getObjectFromGUID(reminderGUID)
			if reminder~=nil then return reminder end
		end
	end
	return nil
end

local function nextCompetitiveSkillReminder(record, fromSeat, nextPlayer)
	if nextPlayer~=nil and turnOrder[nextPlayer]~=nil and turnOrder[nextPlayer].seatPos~=fromSeat then
		local reminder=competitiveSkillReminderForSeat(record, turnOrder[nextPlayer].seatPos)
		if reminder~=nil then return reminder end
	end
	local currentPlayer=gStates.turnNumber
	for playerIndex, details in pairs(turnOrder) do if details.seatPos==fromSeat then currentPlayer=playerIndex break end end
	local best=nil
	local bestDistance=nil
	for reminderGUID, seatPos in pairs(record.reminders or {}) do
		local reminder=getObjectFromGUID(reminderGUID)
		local playerIndex=seatPos~=fromSeat and competitiveSkillPlayerForSeat(seatPos) or nil
		if reminder~=nil and playerIndex~=nil then
			local distance=playerIndex-currentPlayer
			if distance<=0 then distance=distance+#turnOrder end
			if bestDistance==nil or distance<bestDistance then best=reminder bestDistance=distance end
		end
	end
	return best or getObjectFromGUID("958209")
end

local function manaSuppressionTokensAtReminder(record, seatPos)
	local tokens={}
	local reminder=record~=nil and competitiveSkillReminderForSeat(record, seatPos) or nil
	local playArea=playerPlayAreas[seatPos]~=nil and getObjectFromGUID(playerPlayAreas[seatPos]) or nil
	if reminder==nil or playArea==nil then return tokens, reminder end
	local reminderPos=reminder.getPosition()
	for _, token in pairs(playArea.getObjects()) do
		if basicManaToken[token.getName()]==true then
			local tokenPos=token.getPosition()
			if math.abs(tokenPos[1]-reminderPos[1])<=1 and math.abs(tokenPos[3]-reminderPos[3])<=0.65 then tokens[#tokens+1]=token end
		end
	end
	return tokens, reminder
end

local function passManaSuppressionTokens(record, fromSeat, nextPlayer)
	local moved={}
	local tokens, reminder=manaSuppressionTokensAtReminder(record, fromSeat)
	local destination=record~=nil and nextCompetitiveSkillReminder(record, fromSeat, nextPlayer) or nil
	if reminder==nil or destination==nil or destination.guid==reminder.guid then return moved end
	local destinationPos=destination.getPosition()
	local spacing=0.45
	local start=-((#tokens-1)*spacing)/2
	for index, token in ipairs(tokens) do
		token.unlock()
		token.setPositionSmooth({destinationPos[1]+start+((index-1)*spacing), 2+(index*0.25), destinationPos[3]})
		moved[token.guid]=true
	end
	return moved
end

local function clearCompetitiveSkillSeat(skillGUID, seatPos, nextPlayer)
	local record=gStates.competitiveSkillReminders~=nil and gStates.competitiveSkillReminders[skillGUID] or nil
	if record==nil then return {} end
	local moved=skillGUID=="958209" and passManaSuppressionTokens(record, seatPos, nextPlayer) or {}
	for reminderGUID, reminderSeat in pairs(record.reminders or {}) do
		if reminderSeat==seatPos then
			local reminder=getObjectFromGUID(reminderGUID)
			if reminder~=nil then reminder.destruct() end
			record.reminders[reminderGUID]=nil
		end
	end
	for markerGUID, details in pairs(record.markers or {}) do
		if details.seat==seatPos then
			local marker=getObjectFromGUID(markerGUID)
			if marker~=nil then marker.destruct() end
			record.markers[markerGUID]=nil
		end
	end
	return moved
end

local function clearCompetitiveSkillReminders(skillGUID)
	if gStates.competitiveSkillReminders==nil then return end
	local record=gStates.competitiveSkillReminders[skillGUID]
	if record==nil then return end
	if skillGUID=="958209" then
		local clearedSeats={}
		for _, seatPos in pairs(record.reminders or {}) do
			if clearedSeats[seatPos]~=true then
				local tokens=manaSuppressionTokensAtReminder(record, seatPos)
				for _, token in pairs(tokens) do getObjectFromGUID(trashCan).putObject(token) end
				clearedSeats[seatPos]=true
			end
		end
	end
	for reminderGUID, _ in pairs(record.reminders or {}) do
		local reminder=getObjectFromGUID(reminderGUID)
		if reminder~=nil then reminder.destruct() end
	end
	for markerGUID, _ in pairs(record.markers or {}) do
		local marker=getObjectFromGUID(markerGUID)
		if marker~=nil then marker.destruct() end
	end
	gStates.competitiveSkillReminders[skillGUID]=nil
end

local function refreshCompetitiveSkillReminderMarkers(skillGUID)
	local record=gStates.competitiveSkillReminders~=nil and gStates.competitiveSkillReminders[skillGUID] or nil
	local zoneGUID=sharedSkillAboveZone[skillGUID]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if record==nil then return end
	local seatsToClear={}
	for reminderGUID, seatPos in pairs(record.reminders or {}) do
		if getObjectFromGUID(reminderGUID)==nil or competitiveSkillPlayerForSeat(seatPos)==nil then seatsToClear[seatPos]=true end
	end
	for seatPos, _ in pairs(seatsToClear) do clearCompetitiveSkillSeat(skillGUID, seatPos) end
	if zone==nil then return end
	local originals={}
	for _, marker in pairs(zone.getObjects()) do if marker.type=="Figurine" then originals[marker.guid]=marker end end
	for cloneGUID, details in pairs(record.markers or {}) do
		local clone=getObjectFromGUID(cloneGUID)
		local reminderExists=false
		for reminderGUID, seatPos in pairs(record.reminders or {}) do
			if seatPos==details.seat and getObjectFromGUID(reminderGUID)~=nil then reminderExists=true break end
		end
		if clone==nil then record.markers[cloneGUID]=nil
		elseif reminderExists==false or (competitiveOwnerReward[skillGUID]==true and originals[details.source]==nil) then clone.destruct() record.markers[cloneGUID]=nil end
	end
	local zonePos=zone.getPosition()
	for reminderGUID, seatPos in pairs(record.reminders or {}) do
		local reminder=getObjectFromGUID(reminderGUID)
		if reminder~=nil then
			local reminderPos=reminder.getPosition()
			for sourceGUID, marker in pairs(originals) do
				local found=false
				for cloneGUID, details in pairs(record.markers or {}) do
					if details.source==sourceGUID and details.seat==seatPos and getObjectFromGUID(cloneGUID)~=nil then found=true break end
				end
				if found==false then
					local markerPos=marker.getPosition()
					local clone=marker.clone({position={reminderPos[1]+zonePos[1]-markerPos[1], 2, reminderPos[3]+zonePos[3]-markerPos[3]}, rotation=marker.getRotation()})
					clone.setGMNotes("Competitive Skill Marker:"..skillGUID..":"..sourceGUID..":"..seatPos)
					clone.interactable=false
					lockCompetitiveSkillCloneWhenSettled(clone)
					record.markers[clone.guid]={source=sourceGUID, seat=seatPos}
				end
			end
		end
	end
end

local function createCompetitiveSkillReminders(skillGUID, owner)
	if skillTokens[skillGUID]==nil or skillTokens[skillGUID].skillType~="Comp" then return end
	local skill=getObjectFromGUID(skillGUID)
	if skill==nil then return end
	if gStates.competitiveSkillReminders==nil then gStates.competitiveSkillReminders={} end
	local record=gStates.competitiveSkillReminders[skillGUID]
	if record==nil then record={owner=owner, reminders={}, markers={}} gStates.competitiveSkillReminders[skillGUID]=record end
	record.owner=owner record.reminders=record.reminders or {} record.markers=record.markers or {}
	local physicalPlayer=coopCompSkillPlayAreaPlayer(skillGUID)
	if physicalPlayer~=nil and physicalPlayer~=owner and turnOrder[owner]~=nil then
		local target={turnOrder[owner].seatPos*40-109.5, 1.5, -39.41}
		local zoneGUID=sharedSkillAboveZone[skillGUID]
		local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
		if zone~=nil then
			local zonePos=zone.getPosition()
			for _, marker in pairs(zone.getObjects()) do
				if marker.type=="Figurine" then marker.setPositionSmooth({target[1]+zonePos[1]-marker.getPosition()[1], 2, target[3]+zonePos[3]-marker.getPosition()[3]}) end
			end
			zone.setPosition({target[1], 1.4, target[3]})
		end
		skill.setPositionSmooth(target)
	end
	local targetSeats={}
	for playerIndex, details in pairs(turnOrder) do
		if details.seatPos~=nil and details.seatPos<5 and details.mage~=gStates.positionMageKnight[5] and playerIndex~=owner and playerDropoutInactive(playerIndex)==false then targetSeats[details.seatPos]=true end
	end
	for reminderGUID, seatPos in pairs(record.reminders) do
		if targetSeats[seatPos]~=true or getObjectFromGUID(reminderGUID)==nil then clearCompetitiveSkillSeat(skillGUID, seatPos) end
	end
	for seatPos, _ in pairs(targetSeats) do
		local found=false
		for reminderGUID, reminderSeat in pairs(record.reminders) do if reminderSeat==seatPos and getObjectFromGUID(reminderGUID)~=nil then found=true break end end
		if found==false then
			local count=competitiveSkillReminderCount(seatPos)
			local reminder=skill.clone({position={seatPos*40-105, 1.5, -39.41-(1.48*count)}, rotation={0,180,0}})
			reminder.setGMNotes("Competitive Skill Reminder:"..skillGUID..":"..seatPos)
			reminder.clearButtons()
			reminder.UI.setXml("")
			lockCompetitiveSkillCloneWhenSettled(reminder)
			record.reminders[reminder.guid]=seatPos
		end
	end
	refreshCompetitiveSkillReminderMarkers(skillGUID)
	if competitiveOwnerReward[skillGUID]~=true and gStates.mageSkills[skillGUID]~=nil then
		skill.setPositionSmooth({gStates.mageSkills[skillGUID][1], 1.5, gStates.mageSkills[skillGUID][3]})
		skill.setRotationSmooth({0,180,180})
	end
end

local function finishCompetitiveSkill(skillGUID, reset)
	clearCompetitiveSkillReminders(skillGUID)
	local skill=getObjectFromGUID(skillGUID)
	if skill~=nil and gStates.mageSkills[skillGUID]~=nil then
		skill.setPositionSmooth({gStates.mageSkills[skillGUID][1], 1.5, gStates.mageSkills[skillGUID][3]})
		if reset~=true then skill.setRotationSmooth({0,180,180}) end
	end
	gStates.doingTheRounds[skillGUID]=nil
	gStates.soloCoop[skillGUID]=nil
	if gStates.doingTheRoundsVisited~=nil then gStates.doingTheRoundsVisited[skillGUID]=nil end
	deactivateCoopCompSkill(skillGUID, true)
	local zoneGUID=sharedSkillAboveZone[skillGUID]
	local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
	if zone~=nil then for _, marker in pairs(zone.getObjects()) do if marker.type=="Figurine" then getObjectFromGUID(trashCan).putObject(marker) end end end
end

--Move cooperative skills to the next player. Competitive reminders are removed as each affected player's turn finishes.
function doingTheRounds(skillGUID, nextPlayer, count, reset)
	local keepSafe={}
	local skillDetails=skillTokens[skillGUID]
	if skillDetails~=nil and skillDetails.skillType=="Comp" then
		local owner=gStates.doingTheRounds[skillGUID]
		if reset==true then finishCompetitiveSkill(skillGUID, true) return {keepSafe, count} end
		if owner==nil then return {keepSafe, count} end
		if gStates.competitiveSkillReminders==nil or gStates.competitiveSkillReminders[skillGUID]==nil then createCompetitiveSkillReminders(skillGUID, owner) end
		local ownerRewardPending=gStates.soloCoop[skillGUID]==true
		local extraTurnStarted=(gStates.tacticSixState=="Started" or gStates.timeBending=="Started") and gStates.turnNumber==gStates.realTurn
		local currentSeat=turnOrder[gStates.turnNumber]~=nil and turnOrder[gStates.turnNumber].seatPos or nil
		if currentSeat~=nil and extraTurnStarted==false then
			local moved=clearCompetitiveSkillSeat(skillGUID, currentSeat, nextPlayer)
			for tokenGUID, _ in pairs(moved) do keepSafe[tokenGUID]=true end
		end
		refreshCompetitiveSkillReminderMarkers(skillGUID)
		local record=gStates.competitiveSkillReminders~=nil and gStates.competitiveSkillReminders[skillGUID] or nil
		local remindersLeft=0
		if record~=nil then for reminderGUID, _ in pairs(record.reminders or {}) do if getObjectFromGUID(reminderGUID)~=nil then remindersLeft=remindersLeft+1 end end end
		if ownerRewardPending==true and gStates.turnNumber==owner and extraTurnStarted==false then finishCompetitiveSkill(skillGUID, false) return {keepSafe, count}
		elseif ownerRewardPending==false and remindersLeft==0 then
			if gStates.playerCount<=1 or competitiveOwnerReward[skillGUID]==true then gStates.soloCoop[skillGUID]=true
			else finishCompetitiveSkill(skillGUID, false) return {keepSafe, count} end
		end
		local zoneGUID=sharedSkillAboveZone[skillGUID]
		local zone=zoneGUID~=nil and getObjectFromGUID(zoneGUID) or nil
		if zone~=nil and competitiveOwnerReward[skillGUID]==true then for _, marker in pairs(zone.getObjects()) do if marker.type=="Figurine" then keepSafe[marker.guid]=true end end end
		if record~=nil and currentSeat~=nil then
			for markerGUID, details in pairs(record.markers or {}) do if details.seat==currentSeat and getObjectFromGUID(markerGUID)~=nil then keepSafe[markerGUID]=true end end
		end
		return {keepSafe, count}
	end

	if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
	local roundSkill=skillDetails~=nil and skillDetails.skillType=="Coop"
	local roundVisitedLoop=false
	if roundSkill and reset~=true then
		if gStates.doingTheRoundsVisited[skillGUID]==nil then
			gStates.doingTheRoundsVisited[skillGUID]={}
			if gStates.doingTheRounds[skillGUID]~=nil then gStates.doingTheRoundsVisited[skillGUID][gStates.doingTheRounds[skillGUID]]=true end
		end
		--Out-of-order turns such as co-op assaults can skip the original return marker. Reaching any player
		--already visited means a Coop skill has completed one circuit. Same-player extra turns do not count.
		roundVisitedLoop=nextPlayer~=gStates.turnNumber and gStates.doingTheRoundsVisited[skillGUID][nextPlayer]==true
	end
	if gStates.doingTheRounds[skillGUID]==nextPlayer or roundVisitedLoop==true or gStates.soloCoop[skillGUID]==true or reset==true then
		if gStates.playerCount>1 or gStates.soloCoop[skillGUID]==true or reset==true then
			--Flip and return completed skill
			getObjectFromGUID(skillGUID).setPositionSmooth({gStates.mageSkills[skillGUID][1], 1.5, gStates.mageSkills[skillGUID][3]})
			if reset~=true then getObjectFromGUID(skillGUID).setRotationSmooth({0.0, 180.0, 180.0}) end
			gStates.doingTheRounds[skillGUID]=nil
			gStates.soloCoop[skillGUID]=nil
			if gStates.doingTheRoundsVisited~=nil then gStates.doingTheRoundsVisited[skillGUID]=nil end
			deactivateCoopCompSkill(skillGUID, true)
			if sharedSkillAboveZone[skillGUID]~=nil then
				for _, b in pairs(getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getObjects()) do
					if b.type=="Figurine" then getObjectFromGUID(trashCan).putObject(b) end
				end
			end
		else
			--place next to owner skill for solo cooperative play
			if sharedSkillAboveZone[skillGUID]~=nil then
				for _, b in pairs(getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getObjects()) do
					if b.type=="Figurine" then
						local offsetX=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[1]-b.getPosition()[1]
						local offsetZ=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[3]-b.getPosition()[3]
						b.setPositionSmooth({turnOrder[nextPlayer].seatPos*40-109.5+offsetX , 2.0, -39.41+offsetZ})
						keepSafe[b.guid]=true
					end
				end
			end
			getObjectFromGUID(skillGUID).setPositionSmooth({turnOrder[nextPlayer].seatPos*40-109.5 , 1.5, -39.41})
			gStates.soloCoop[skillGUID]=true
		end
	else
		--move cooperative token to next player board
		local position={109.5, 1.48}
		if sharedSkillAboveZone[skillGUID]~=nil then
			for _, b in pairs(getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getObjects()) do
				if b.type=="Figurine" then
					local offsetX=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[1]-b.getPosition()[1]
					local offsetZ=getObjectFromGUID(sharedSkillAboveZone[skillGUID]).getPosition()[3]-b.getPosition()[3]
					b.setPositionSmooth({turnOrder[nextPlayer].seatPos*40-position[1]+offsetX , 2.0, -39.41+(position[2]*count)+offsetZ})
					keepSafe[b.guid]=true
				end
			end
		end
		getObjectFromGUID(skillGUID).setPositionSmooth({turnOrder[nextPlayer].seatPos*40-position[1] , 1.5, -39.41+(position[2]*count)})
		if roundSkill then
			if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
			if gStates.doingTheRoundsVisited[skillGUID]==nil then gStates.doingTheRoundsVisited[skillGUID]={} end
			gStates.doingTheRoundsVisited[skillGUID][nextPlayer]=true
		end
		count=count+1
	end
	return {keepSafe, count}
end

--Recover a played Interactive skill that Tome moved to the common offer before the normal play-area scan.
--Competitive effects can continue from their remembered activation. Cooperative secondary effects require
--the real token, and Source Freeze explicitly works only while its real token remains in the Source.
local function registerDetachedCoopCompSkills(playerIndex)
	local toDeactivate={}
	for skillGUID, record in pairs(coopCompSkillActivationTable()) do
		local details=skillTokens[skillGUID]
		if record.player==playerIndex and record.round==gStates.currentRound and record.location=="pool" and details~=nil and gStates.doingTheRounds[skillGUID]==nil then
			if details.skillType=="Comp" and skillGUID~="3bd08e" then
				gStates.doingTheRounds[skillGUID]=playerIndex
				createCompetitiveSkillReminders(skillGUID, playerIndex)
				record.rotationStarted=true
			else
				toDeactivate[#toDeactivate+1]=skillGUID
			end
		end
	end
	for _, skillGUID in ipairs(toDeactivate) do deactivateCoopCompSkill(skillGUID, true) end
	commitTomeSkillSwap(playerIndex)
end

--drop a shield
function dropShield(location, lockToken, rotation)
	for a, details in pairs(mageKnights) do
		if details.mage==turnOrder[gStates.turnNumber].mage then
			local shield=getObjectFromGUID(details.shieldContainer).takeObject({position=location, rotation=rotation, smooth=false})
			if lockToken==true then
				Wait.time(function() Wait.condition(function()
					shield.lock()
				end, function() return shield.resting end) end, 1.5)
			end
			UI.setAttribute("PreEndTurn", "interactable", "false")
			UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Deactive")
			Wait.time(function()
				UI.setAttribute("PreEndTurn", "interactable", "true")
				UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Active")
			end, 2.1)
			break
		end
	end
end

--Coral's Tales skills collect a shield when Coral marks the matching type of site.
function coralTalesSiteShield(siteType)
	local playerDetails=turnOrder[gStates.turnNumber]
	if playerDetails==nil or playerDetails.mage~="Coral" then return end
	local adventureSites={['monster den']=true, ['spawning grounds']=true, maze=true, labyrinth=true, ruin=true, dungeon=true, tomb=true, ziggurat=true, pyramid=true}
	local skillGUID=nil
	if adventureSites[siteType]==true then skillGUID="9cf272"--Tales of Adventure
	elseif siteType=="keep" or siteType=="mage tower" then skillGUID="de5b04" end--Tales of Conquest
	if skillGUID==nil then return end
	local skill=getObjectFromGUID(skillGUID)
	local recordedPos=gStates.mageSkills~=nil and gStates.mageSkills[skillGUID] or nil
	if skill==nil or recordedPos==nil then return end
	--Claimed skills live in the owner's skill column; communal/pool skills are recorded elsewhere.
	local claimedX=(playerDetails.seatPos*40)-107.45
	if math.abs(recordedPos[1]-claimedX)>2 or recordedPos[3]>-35 then return end
	local shieldContainer=nil
	for _, details in pairs(mageKnights) do if details.mage=="Coral" then shieldContainer=getObjectFromGUID(details.shieldContainer) break end end
	if shieldContainer==nil then return end
	local location=skill.getPosition()
	local snapPoints=skill.getSnapPoints()
	if snapPoints~=nil and snapPoints[1]~=nil then location=skill.positionToWorld(snapPoints[1].position) end
	--Drop above the snap point so the first shield snaps to the skill and later shields can stack naturally.
	location={location[1], skill.getPosition()[2]+2.5, location[3]}
	shieldContainer.takeObject({position=location, rotation={0, skill.getRotation()[2], 0}, smooth=false})
end

--Claim the Skill reserved by Hero Challenges. higherLevel=true mirrors the Start-at-Higher-Level
--Bonds of Loyalty setup rather than adding cards to the live Unit Offer.
function heroChallengeClaimReservedSkill(playerIndex,higherLevel)
	if gStates.heroChallenges~=true or turnOrder[playerIndex]==nil then return false end
	local playerData=turnOrder[playerIndex]
	local challenge=heroChallengesData[playerData.mage]
	if challenge==nil then return false end
	--The prescribed GUID is the source of truth. Reservations are keyed by Mage Knight because turnOrder
	--changes order during the game; an array-index reservation can otherwise point at another Hero's Skill.
	local reserved=(gStates.heroChallengeReservedSkills or {})[playerData.mage]
	local guid=reserved==challenge.skillGUID and reserved or challenge.skillGUID
	local skillDetails=skillTokens[guid]
	if skillDetails==nil or skillDetails.mage~=playerData.mage then
		print("HERO CHALLENGE SKILL ERROR: "..tostring(challenge.skillName).." does not belong to "..tostring(playerData.mage)..".")
		return false
	end
	local skill=getObjectFromGUID(guid)
	if skill==nil then print("HERO CHALLENGE SKILL ERROR: "..tostring(challenge.skillName).." could not be found.") return false end
	local count=0
	local skillX=(playerData.seatPos*40)-107.45
	for _,skillPos in pairs(gStates.mageSkills or {}) do if skillPos[3]<-36.9 and math.abs(skillPos[1]-skillX)<1 then count=count+1 end end
	local target={skillX,1.1,-38.67-(1.48*count)}
	if guid=="f30dd4" then
		local bondsX=unitLayoutNextCommandX(playerData.seatPos)
		target={bondsX,1.1,-31.19}
		scheduleUnitLayoutRefresh(playerData.seatPos)
		if higherLevel==true then
			local unitDeck=getObjectFromGUID(GUID.zone.regularUnit).getObjects()[1]
			for _=1,2 do
				standardDeckCycleShuffleIfReached("Regular Unit",unitDeck)
				unitDeck=getObjectFromGUID(GUID.zone.regularUnit).getObjects()[1]
				unitDeck.takeObject({position={(playerData.seatPos*40)-101,3.0,-48.4},smooth=true,rotation={0,180,0}})
			end
			gStates.bondsOfLoyalty[playerIndex]=5
			UI.setAttribute("Mage"..playerData.seatPos.."influenceTotalText","Text",joinLang({"{en}Influence to Spend : {ru}Доступно влияния: {zh-cn}影响力额度：{ko}주어진 영향력: {es}Influencia para Gastar : {fr}Influence à Dépenser : {pt-br}Influência para Gastar : {de}Einfluss zum Ausgeben : ",(playerData.influence*playerData.level)+gStates.bondsOfLoyalty[playerIndex]}))
		else
			local unitPlace={{36.0,1.25,-4.2},{31.2,1.25,-4.2},{26.4,1.25,-4.2},{21.6,1.25,-4.2},{16.8,1.25,-4.2},{12.0,1.25,-4.2},{7.2,1.25,-4.2},{2.4,1.25,-4.2},{-2.4,1.25,-4.2}}
			for slot=gStates.totalUnitCount+1,gStates.totalUnitCount+2 do
				standardDeckCycleShuffleIfReached("Regular Unit")
				local deck=getObjectFromGUID(GUID.zone.regularUnit).getObjects()[1]
				if deck~=nil and unitPlace[slot]~=nil then getObjectFromGUID(deck.guid).takeObject({position=unitPlace[slot],smooth=true,rotation={0,180,0}}) end
			end
		end
	end
	gStates.mageSkills[guid]=target
	skill.unlock()
	skill.setPositionSmooth(target)
	skill.UI.setXmlTable({{}})
	if gStates.motivationSkill[guid]~=nil then gStates.motivationSkill[guid].state="active" gStates.motivationSkill[guid].pos=playerData.seatPos end
	broadcastToAll(tostring(playerData.mage).." gained "..tostring(challenge.skillName).." from Hero Challenges.",positionToColor(playerIndex))
	return true
end

--perform Level Up
function levelUp(playerTurnSequence)
	if turnOrder[playerTurnSequence].levelUp>0 then
		--The prescribed level-2 Hero Challenge Skill is automatic, so it does not need the normal
		--end-turn "Gained a New Skill Token" reminder. Reset this for every live level-up sequence;
		--a later normal Skill level in the same sequence turns the reminder back on.
		turnOrder[playerTurnSequence].skipHeroChallengeSkillReminder=false
		local multiSkill=false
		local loops=turnOrder[playerTurnSequence].levelUp
		for a=1, loops, 1 do
			if ((turnOrder[playerTurnSequence].level)+1)%2==0 then --Skill and Advanced Action Level Up
				local nextLevel=turnOrder[playerTurnSequence].level+1
				if gStates.heroChallenges==true and nextLevel==2 and heroChallengesData[turnOrder[playerTurnSequence].mage]~=nil then
					if heroChallengeClaimReservedSkill(playerTurnSequence,false)==true then
						turnOrder[playerTurnSequence].skipHeroChallengeSkillReminder=true
					end
					broadcastToAll(tostring(turnOrder[playerTurnSequence].mage).." may gain any one Advanced Action card.",positionToColor(playerTurnSequence))
				elseif multiSkill==false then
					--This is a normal Skill choice, so keep the standard reminder even if level 2 was also
					--crossed earlier in an unusual multi-level jump.
					turnOrder[playerTurnSequence].skipHeroChallengeSkillReminder=false
					--draw two skills to communal
					local exist=0
					local drawnSkillGUIDs={}
					for skillGUID, skillPos in pairs(gStates.mageSkills) do
						if math.floor(skillPos[1])==math.floor((turnOrder[playerTurnSequence].seatPos*3.7)+7.3) then exist=exist+1 end
					end
					for b=0, 1, 1 do
						local pos={(turnOrder[playerTurnSequence].seatPos*3.7)+7.3, 2.00, -23.95+(b*1.35)+(exist*1.35)}
						local skillDrawn=nil
						local usedFallback=false
						if getObjectFromGUID(turnOrder[playerTurnSequence].skillBagGUID).getQuantity()>=1 then
							skillDrawn=getObjectFromGUID(turnOrder[playerTurnSequence].skillBagGUID).takeObject({position=pos, smooth=true, rotation={0, 180, 0}})
						else
							skillDrawn=getObjectFromGUID("70c31f").clone({position=pos, rotation={0, 180, 0}})
							usedFallback=true
						end
						if skillDrawn~=nil then
							gStates.mageSkills[skillDrawn.guid]=pos
							drawnSkillGUIDs[#drawnSkillGUIDs+1]=skillDrawn.guid
						end
						if usedFallback==true then break end
					end
					--activate claim buttons only after every newly dealt Skill has actually settled.
					gStates.skillButtons=turnOrder[playerTurnSequence].seatPos
					Wait.condition(function()
						for _, guid in ipairs(drawnSkillGUIDs) do local skill=getObjectFromGUID(guid) if skill~=nil then skill.unlock() end end
						skillButtonActivate()
					end, function()
						if #drawnSkillGUIDs==0 then return true end
						for _, guid in ipairs(drawnSkillGUIDs) do local skill=getObjectFromGUID(guid) if skill==nil or skill.resting~=true then return false end end
						return true
					end, 10, function() skillButtonActivate() end)
					--Highlight reminder starts from the same synchronized skillButtonActivate refresh.
					--Look at skill Area
					broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage], "{en} needs to gain a new Skill and Advanced Action card.{ru} должен получить новый Навык и карту Особых действий.{zh-cn}需要获得新技能和高级行动卡{ko}: 스킬과 상급 액션을 선택하세요.{es} necesita obtener una nueva tarjeta de Habilidad y Acción Avanzada.{fr} doit gagner une nouvelle carte de compétence et d'action avancée.{pt-br} precisa ganhar uma nova Carta de ação e Habilidade.{de} muss eine neue Fertigkeit und eine erweiterte Aktionskarte erhalten."}), positionToColor(playerTurnSequence))
					multiSkill=true
				else
					break
				end
			else --odd number levels
				--Command Token Deploy. Bonus Command sources can already occupy the printed row, so use the shared elastic layout.
				local commandSeat=turnOrder[playerTurnSequence].seatPos
				local xPlayLocation=unitLayoutNextCommandX(commandSeat)
				getObjectFromGUID(turnOrder[playerTurnSequence].commandGUID).takeObject({position={xPlayLocation,2.00,-31.2}, rotation={0,180,180}})
				scheduleUnitLayoutRefresh(commandSeat)
				broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage], "{en} gained a new Command token.{ru} получает новый Жетон командования.{zh-cn}增加一个新的部队控制标记{ko}: 새 지휘 토큰 획득{es} ganó una nueva ficha de Comando.{fr} gagné un nouveau jeton Commandement.{pt-br} ganhou uma nova FIcha de Comando.{de} hat ein neues Befehlsplättchen erhalten."}), positionToColor(playerTurnSequence))
				--Hand Size Increase
				if (turnOrder[playerTurnSequence].level)+1==5 or (turnOrder[playerTurnSequence].level)+1==9 then
					turnOrder[playerTurnSequence].baseHand=turnOrder[playerTurnSequence].baseHand+1
					turnOrder[playerTurnSequence].hand=turnOrder[playerTurnSequence].hand+1
					broadcastToAll(joinLang({translateWord[turnOrder[playerTurnSequence].mage], "{en}'s hand size increased by one.{ru} имеет увеличенный предел карт на 1.{zh-cn}的手牌上限增加了1{ko}: 카드 보유 제한 1 증가{es}'s tamaño de la mano aumenta en uno.{fr}'s la taille de la main a augmenté de un.{pt-br}'s tamanho de mão aumentado em 1.{de} die Handgröße des Spielers wurde um eins erhöht."}), positionToColor(playerTurnSequence))
				end
			end
			turnOrder[playerTurnSequence].level=turnOrder[playerTurnSequence].level+1
			turnOrder[playerTurnSequence].levelUp=turnOrder[playerTurnSequence].levelUp-1
		end
		if turnOrder[playerTurnSequence].levelUp==0 then levelUpcalled=false end
	end
end

--put skill buttons on skills when appropiate
function skillButtonActivate()
	refreshMageSkillLocations()
	unlockCommonSkillPoolTokens()
	if gStates.skillButtons~=nil and gStates.skillButtons>0 then startRewardSkillChoiceHighlights() end
	Wait.time(function()
		--blank existing claim buttons
		for skillGUID, x in pairs(gStates.mageSkills) do
			if getObjectFromGUID(skillGUID)~=nil then getObjectFromGUID(skillGUID).UI.setXmlTable({{}}) end
		end
		if gStates.tacticShown==false and gStates.tacticRemove==false then
			--Work out which skills exist where.
			local skillSort={currentPlayer={}}
			if gStates.skillButtons>0 then
				for skillGUID, skillPos in pairs(gStates.mageSkills) do
					if skillPos[3]>-30 then
						local skillColumn=math.ceil((skillPos[1]-12.85)/3.7)
						local skillRow=math.ceil((skillPos[3]+24.625)/1.35)
						if gStates.skillButtons~=skillColumn+1 then
							skillSort[(skillColumn*8)+skillRow]=skillGUID
						else
							skillSort.currentPlayer[#skillSort.currentPlayer+1]={skillGUID, skillPos[3], (skillColumn*8)+skillRow}
						end
					end
				end
			end
			--Add claim buttons for skills that are legal
			table.sort(skillSort.currentPlayer, function (k1, k2) return k1[2] > k2[2] end)
			for buttonNumber=1, 32, 1 do
				if gStates.skillButtons>0 then
					if math.ceil(buttonNumber/8)~=gStates.skillButtons then
						if gStates.heroChallenges~=true and skillSort[buttonNumber]~=nil then
							local skill=getObjectFromGUID(skillSort[buttonNumber])
							if skill~=nil then skill.UI.setXmlTable({createClaimButton(skillSort[buttonNumber], tostring(buttonNumber))}) end
						end
					else
						if skillSort.currentPlayer[1]~=nil and buttonNumber==skillSort.currentPlayer[1][3] then
							local skill=getObjectFromGUID(skillSort.currentPlayer[1][1])
							if skill~=nil then skill.UI.setXmlTable({createClaimButton(skillSort.currentPlayer[1][1], tostring(buttonNumber))}) end
						end
						if skillSort.currentPlayer[2]~=nil and buttonNumber==skillSort.currentPlayer[2][3] and turnOrder[gStates.turnNumber].level<=10 then
							local skill=getObjectFromGUID(skillSort.currentPlayer[2][1])
							if skill~=nil then skill.UI.setXmlTable({createClaimButton(skillSort.currentPlayer[2][1], tostring(buttonNumber))}) end
						end
					end
				end
			end
		end
	end, 0.5)
end

--Players may leave the game between turns. Pending dropouts can still be undone until normal turn order advances.
function playerDropoutInactive(playerIndex)
	if turnOrder[playerIndex]==nil then return false end
	return turnOrder[playerIndex].dropoutState=="pending" or turnOrder[playerIndex].dropoutState=="dropped"
end

function dropoutCoopLocked()
	return dropoutCoopDefensePrompt==true or gStates.coopAssaultPhase~=nil or (gStates.coopAssaultCityGUID~=nil and gStates.assaultData~=nil and next(gStates.assaultData)~=nil)
end

function activeMageKnightCount()
	local count=0
	for a, playerData in pairs(turnOrder) do
		if playerData.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(a)==false then count=count+1 end
	end
	return count
end


function volkareQuestSkipThreshold()
	return activeMageKnightCount()*2
end

function volkareQuestCheckSkipTurn()
	if gStates.gameScenario~="Volkare's Quest" then return false end
	local threshold=volkareQuestSkipThreshold()
	local reminder=getObjectFromGUID("09a991")
	if threshold<=0 or gStates.volkareArmyDefeated<threshold or reminder==nil or reminder.is_face_down==true then return false end
	gStates.volkareQuestSkipThreshold=threshold
	reminder.flip()
	broadcastToAll(joinLang({"{en}At Least {ru}Как минимум {zh-cn}至少{ko}최소 {es}Al menos {fr}Au moins {pt-br}Pelo menos {de}Zumindest ", tostring(threshold), "{en} of Volkare's Army defeated, he skips his next turn.{ru} отряда из армии Волкара побеждено, он пропускает следующий ход{zh-cn}个敌人被击败了, 沃里卡跳过了他的回合. {ko}개의 볼케어 군대 적 토큰을 제거했기에, 볼케어의 차례를 건너뜁니다{es} de los ejércitos de Volkare derrotados, se salta su siguiente turno.{fr} de l'armée de Volkare vaincus, il saute son prochain tour.{pt-br} do exército de Volkare derrotado, ele pulará seu próximo turno.{de} von Volkare's Armee besiegt, überspringt er seinen nächsten Zug."}), {1,1,0.5})
	return true
end

function volkareQuestFullAttendAllowed(mageName)
	if gStates.gameScenario~="Volkare's Quest" then return true end
	for _, details in pairs(turnOrder) do
		if details.mage==mageName then
			local token=getObjectFromGUID(details.turnOrderTokenGUID)
			if token~=nil and token.is_face_down==true then return false end
			local handZone=getObjectFromGUID(handZones[details.seatPos])
			if handZone~=nil then
				for _, card in pairs(handZone.getObjects()) do
					if card.type=="Card" and card.getGMNotes()~="Wound" then return true end
				end
			end
			return false
		end
	end
	return false
end

function volkareQuestRefreshFullAttend(mageName)
	if gStates.gameScenario~="Volkare's Quest" then return end
	local allowed=volkareQuestFullAttendAllowed(mageName)
	UI.setAttribute("VolkareAttackedFull", "interactable", allowed and "true" or "false")
	UI.setAttribute("VolkareAttackedFullImage", "image", allowed and "Sliced Button/Button New Active" or "Sliced Button/Button New Deactive")
end

function volkareQuestCombatWithdrawalReminder(mageName)
	if gStates.gameScenario~="Volkare's Quest" or gStates.volkareMovementStepPending==true or mageName==nil then return false end
	local attacked=gStates.volkareAttacked~=nil and gStates.volkareAttacked[1] or nil
	if attacked==nil or attacked.mage~=mageName then return false end
	local volkareObj=gStates.volkareModel~=nil and getObjectFromGUID(gStates.volkareModel) or nil
	if volkareObj==nil then return false end
	local mageObj=nil
	for _, avatar in pairs(mageKnights) do
		if avatar.mage==mageName then
			mageObj=getObjectFromGUID(avatar.model) or getObjectFromGUID(avatar.standee) or getObjectFromGUID(avatar.token)
			break
		end
	end
	if mageObj==nil then return false end
	local vPos,mPos=volkareObj.getPosition(),mageObj.getPosition()
	if math.sqrt(((vPos[1]-mPos[1])^2)+((vPos[3]-mPos[3])^2))>=1.5 then return false end
	broadcastToAll(joinLang({translateWord[mageName], "{en} needs to withdraw to a neighboring Safe space after fighting Volkare.{ru} должен отступить на соседнюю безопасную клетку после боя с Волкаром.{zh-tw} 與沃卡里戰鬥後必須撤退到相鄰的安全格。{zh-cn} 与沃卡里战斗后必须撤退到相邻的安全格。{ko} 볼케어와 전투한 뒤 인접한 안전한 칸으로 후퇴해야 합니다.{es} debe retirarse a un espacio seguro vecino después de luchar contra Volkare.{fr} doit se retirer vers un espace sûr adjacent après avoir combattu Volkare.{pt-br} precisa recuar para um espaço Seguro adjacente depois de lutar com Volkare.{de} muss sich nach dem Kampf gegen Volkare auf ein benachbartes sicheres Feld zurückziehen."}), warningColor)
	return true
end

function commitPendingDropouts()
	if dropoutCoopLocked()==true then return false end
	local changed=false
	for a, playerData in pairs(turnOrder) do
		if playerData.dropoutState=="pending" then
			playerData.dropoutState="dropped"
			gStates.skipTurn[a]=nil
			local token=getObjectFromGUID(playerData.turnOrderTokenGUID)
			if token~=nil and token.is_face_down==true then token.flip() end
			broadcastToAll(joinLang({translateWord[playerData.mage], "{en} has dropped out of the game.{ru} вышел из игры.{zh-tw} 已退出遊戲。{zh-cn} 已退出游戏。{ko} 게임에서 나갔습니다.{es} ha abandonado la partida.{fr} a quitté la partie.{pt-br} saiu do jogo.{de} hat das Spiel verlassen."}), positionToColor(a))
			changed=true
		end
	end
	if changed==true then
		applyColorBarButtons()
		volkareQuestCheckSkipTurn()
	end
	return changed
end

--Co-op assault combat is resolved first; rewards are then claimed by each participant in fight order.
function coopAssaultPendingCombat()
	if gStates.coopAssaultPhase~="combat" or gStates.coopAssaultParticipants==nil then return false end
	for playerIndex, _ in pairs(gStates.coopAssaultParticipants) do
		if playerIndex~=gStates.turnNumber and turnOrder[playerIndex]~=nil and playerDropoutInactive(playerIndex)==false then
			local token=getObjectFromGUID(turnOrder[playerIndex].turnOrderTokenGUID)
			if token~=nil and token.is_face_down==true and gStates.skipTurn[playerIndex]==nil then return true end
		end
	end
	return false
end

--Faction-leader co-op participants get unlocked planning copies. These clones are visual only and are never registered as monsters.
function clearCoopLeaderPreviewClones()
	for playerIndex, cloneGUID in pairs(gStates.coopLeaderPreviewClones or {}) do
		local clone=getObjectFromGUID(cloneGUID)
		if clone~=nil then clone.destruct() end
	end
	gStates.coopLeaderPreviewClones={}
end

function createCoopLeaderPreviewClones()
	clearCoopLeaderPreviewClones()
	if gStates.coopAssaultPhase~="combat" or coopAssaultTargetType()~="leader" then return end
	local leaderGUID=elementalist.token
	if gStates.coopAssaultCityGUID==darkCrusader.terrainHex then leaderGUID=darkCrusader.token end
	local leaderObj=getObjectFromGUID(leaderGUID)
	if leaderObj==nil then return end
	for playerIndex, _ in pairs(gStates.coopAssaultParticipants or {}) do
		if playerIndex~=gStates.turnNumber and turnOrder[playerIndex]~=nil then
			local clone=leaderObj.clone({position={turnOrder[playerIndex].seatPos*40-100, 1.5, -39.41}, rotation={0, 180, 0}, smooth=false})
			if clone~=nil then
				clone.unlock()
				clone.interactable=true
				clone.UI.setXmlTable({{}})
				gStates.coopLeaderPreviewClones[playerIndex]=clone.guid
			end
		end
	end
end

--Replace the next player's movable planning copy with the real leader token and its combat controls.
function promoteCoopLeaderPreview(playerIndex, leaderObj)
	if leaderObj==nil or turnOrder[playerIndex]==nil then return end
	local destination={turnOrder[playerIndex].seatPos*40-100, 1.5, -39.41}
	local cloneGUID=gStates.coopLeaderPreviewClones~=nil and gStates.coopLeaderPreviewClones[playerIndex] or nil
	local clone=cloneGUID~=nil and getObjectFromGUID(cloneGUID) or nil
	if clone~=nil then
		--Respect where the player moved the preview as long as it is still inside that player's combat area.
		local playZone=getObjectFromGUID(playerPlayAreas[turnOrder[playerIndex].seatPos])
		if playZone~=nil then
			for _, obj in pairs(playZone.getObjects()) do
				if obj.guid==clone.guid then
					local clonePos=clone.getPosition()
					destination={clonePos[1], 1.5, clonePos[3]}
					break
				end
			end
		end
		clone.destruct()
	end
	if gStates.coopLeaderPreviewClones~=nil then gStates.coopLeaderPreviewClones[playerIndex]=nil end
	leaderObj.unlock()
	leaderObj.setPositionSmooth(destination)
	leaderObj.setRotation({0, 180, 0})
	setMonsterObjectButtons(leaderObj)
end

--Assisting Mage Knights are treated as being in the assaulted city without moving their avatar until the assault result is known.
function coopAssaultAvatarObject(playerIndex)
	return mageKnightAvatarObject(playerIndex,false)
end

function coopAssaultVirtualPlayer(playerIndex)
	return gStates.coopAssaultPhase=="combat" and gStates.coopAssaultParticipants~=nil and gStates.coopAssaultParticipants[playerIndex]~=nil
end

function moveCoopAssaultAvatarToCityCard(playerIndex)
	local cityGUID=gStates.coopAssaultCityGUID
	if cityGUID==nil or gStates.cityCard[cityGUID]==nil or getObjectFromGUID(gStates.cityCard[cityGUID])==nil then return false end
	local cardPos=getObjectFromGUID(gStates.cityCard[cityGUID]).getPosition()
	local destination={cardPos[1]+(turnOrder[playerIndex].seatPos*1.83)-4.58, cardPos[2]+1, cardPos[3]-0.66}
	local avatar=coopAssaultAvatarObject(playerIndex)
	if avatar~=nil then avatar.setPositionSmooth(destination) end
	turnOrder[playerIndex].avatarSwapCity=cityGUID
	return true
end

--Co-op assaults share combat/reward handling, but their post-combat movement is different.
--Cities (including Volkare's Camp when used as a city) move successful assistants into the city.
--Moving Volkare and Shades of Tezla faction leaders return assisting players to their original spaces;
--the player who initiated the assault is already on the assaulted space and remains there on victory.
--The Dragon data is forward-declared with the map-setup helpers above.
function coopAssaultTargetType()
	local target=gStates.coopAssaultCityGUID
	if target==apocalypseDragon.model and apocalypseDragonScenario~=nil and apocalypseDragonScenario()==true then return "dragon" end
	if gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted==true and target==GUID.tile.country01 then return "horsemen" end
	if target==volkare.model then return "volkare" end
	if target==darkCrusader.terrainHex or target==elementalist.terrainHex then return "leader" end
	return "city"
end

function coopAssaultTargetDefeated()
	local target=gStates.coopAssaultCityGUID
	local assaultType=coopAssaultTargetType()

	if assaultType=="dragon" then return apocalypseDragonColoredHeadsDefeated() end
	if assaultType=="horsemen" then return againstHorsemenAllDefeated() end

	if assaultType=="volkare" then
		if gStates.cityMonsterQty[target]==nil then return false end
		for monsterGUID, state in pairs(gStates.cityMonsterQty[target]) do
			if monsterGUID~="extra" and state=="alive" then return false end
		end
		return true
	end

	if assaultType=="leader" then
		if cityTargetDefeated(target)==true then return true end
		--The leader's followers are discarded shortly after the leader reaches level 0, so use the
		--leader token/level as an immediate fallback while that delayed cleanup is still finishing.
		if target==darkCrusader.terrainHex then
			return (gStates.darkCrusaderLevel or 1)<=0 or (gStates.cityMonsterQty[target]~=nil and gStates.cityMonsterQty[target][darkCrusader.token]=="dead")
		end
		if target==elementalist.terrainHex then
			return (gStates.elementalistLevel or 1)<=0 or (gStates.cityMonsterQty[target]~=nil and gStates.cityMonsterQty[target][elementalist.token]=="dead")
		end
		return false
	end

	return cityTargetDefeated(target)
end

function restoreCoopAssaultAvatar(playerIndex, original)
	if turnOrder[playerIndex]==nil or original==nil then return end
	turnOrder[playerIndex].avatarLocation=original.avatarLocation
	turnOrder[playerIndex].avatarSharedHex=original.avatarSharedHex
	turnOrder[playerIndex].avatarSwapCity=original.avatarSwapCity
	local avatar=coopAssaultAvatarObject(playerIndex)
	if avatar~=nil and original.position~=nil then avatar.setPositionSmooth(original.position) end
end

function registerVolkareCampAsCityKeep()
	if gStates.volkareCampAsCity~=true or gStates.volkareCityDefeat==true or gStates.defeatedCities[volkare.terrainHex]~=true then return end
	gStates.volkareCityDefeat=true
	for _, player in pairs(turnOrder) do
		if player.defeatedCities[volkare.terrainHex]=="Lead" then player.keepsBeat=player.keepsBeat+1 break end
	end
end

function resolveCoopAssaultLocations()
	if gStates.coopAssaultParticipants==nil or gStates.coopAssaultCityGUID==nil then return end
	gStates.coopAssaultType=coopAssaultTargetType()
	gStates.coopAssaultConquered=coopAssaultTargetDefeated()
	local volkareCampCity=gStates.volkareCampAsCity==true and gStates.coopAssaultCityGUID==volkare.terrainHex
	if volkareCampCity and gStates.coopAssaultConquered==true then registerVolkareCampAsCityKeep() end

	for playerIndex, original in pairs(gStates.coopAssaultParticipants) do
		if turnOrder[playerIndex]~=nil then
			if gStates.coopAssaultType=="dragon" then
				--Only the initiator enters the Dragon space on victory. All assisting Mage Knights
				--remain where they started; a failed assault withdraws the initiator as well.
				if gStates.coopAssaultConquered==true and playerIndex==gStates.coopAssaultInitiator then
					local avatar=coopAssaultAvatarObject(playerIndex)
					if avatar~=nil then refreshAvatarLocationOnly(playerIndex,avatar) end
				else restoreCoopAssaultAvatar(playerIndex,original) end
			elseif gStates.coopAssaultType=="horsemen" and gStates.coopAssaultConquered==true then
				--The rules place only the initiating Mage Knight in the Glade after a successful combined attack.
				if playerIndex==gStates.coopAssaultInitiator then
					turnOrder[playerIndex].avatarLocation="glade"
					turnOrder[playerIndex].avatarSharedHex=nil
					turnOrder[playerIndex].avatarSwapCity=nil
				else restoreCoopAssaultAvatar(playerIndex, original) end
			elseif volkareCampCity and gStates.coopAssaultConquered==true then
				--Camp-as-City keeps Volkare's cooperative assault movement: initiator stays, assistants return.
				if playerIndex==gStates.coopAssaultInitiator then
					turnOrder[playerIndex].avatarLocation=gStates.coopAssaultLocation
					turnOrder[playerIndex].avatarSwapCity=nil
				else restoreCoopAssaultAvatar(playerIndex, original) end
			elseif gStates.coopAssaultType=="city" and gStates.coopAssaultConquered==true then
				turnOrder[playerIndex].avatarLocation=gStates.coopAssaultLocation
				moveCoopAssaultAvatarToCityCard(playerIndex)
			else
				--Moving Volkare/leader assistants always return. Unconquered city participants also return.
				restoreCoopAssaultAvatar(playerIndex, original)
			end
		end
	end

	--The Volkare initiator stays where the assault was made. Once Volkare is defeated, refresh the
	--stored location from the terrain under the avatar so reward reminders no longer see "Volkare's Camp".
	if gStates.coopAssaultType=="volkare" and gStates.coopAssaultConquered==true and gStates.coopAssaultInitiator~=nil then
		local initiator=gStates.coopAssaultInitiator
		local avatar=coopAssaultAvatarObject(initiator)
		if turnOrder[initiator]~=nil and avatar~=nil then
			local terrain, bearing=terrainHexAtPosition(avatar.getPosition())
			if terrain~=nil and bearing~=nil and terrainTiles[terrain.guid]~=nil then
				turnOrder[initiator].avatarLocation=terrainTiles[terrain.guid].hexFeature[bearing]
				turnOrder[initiator].avatarSwapCity=nil
			end
		end
	end
end

function applyPlayerFameReputation(playerIndex)
	local player=turnOrder[playerIndex]
	local startingFameToLevel=math.floor(math.sqrt((player.fame-(gStates.scoreIfLooped*player.scoreLoop))+1))
	local newFame=player.fame+player.fameGain-(gStates.scoreIfLooped*player.scoreLoop)
	local scoreLooped=false
	if newFame>=gStates.scoreIfLooped then newFame=newFame-gStates.scoreIfLooped scoreLooped=true end
	local fameToLevel=math.floor(math.sqrt(newFame+1))
	local startPosition=(newFame-(fameToLevel*fameToLevel))+2
	if scoreLooped==false then startPosition=startPosition+((fameToLevel-startingFameToLevel)*gStates.blitz) end
	local levelRowFameQuantity=(((fameToLevel-1)*cellGainPerLevel)+normalCellAmount)
	if startPosition>levelRowFameQuantity then fameToLevel=fameToLevel+1 startPosition=2 levelRowFameQuantity=levelRowFameQuantity+2 end
	local levelRowLength=((fameToLevel-1)*gStates.rowLengthGainPerLevel)+gStates.normalRowLength
	local xOffset=(1/levelRowFameQuantity*levelRowLength)/2
	local yOffset=(heightOfFameBoard/gStates.rowsOnBoard)/2
	local horizontalValue=leftOfFameBoard+(startPosition/levelRowFameQuantity*levelRowLength)-xOffset
	local verticalValue=(topOfFameBoard-((fameToLevel/gStates.rowsOnBoard)*heightOfFameBoard))+yOffset-0.35
	getObjectFromGUID(player.fameGUID).setPosition({horizontalValue, 1.5, verticalValue+((player.seatPos-2.5)/5)})
	recordPlayerFameChange(playerIndex, player.fameGain)

	if player.repGain<(-7-player.reputation) then player.repGain=(-7-player.reputation) end
	if player.repGain>(7-player.reputation) then player.repGain=(7-player.reputation) end
	local repPos=reputationTable[player.reputation+player.repGain].reputationPos
	getObjectFromGUID(player.reputationGUID).setPosition({repPos[1], repPos[2], repPos[3]})
	player.reputation=player.reputation+player.repGain
end

function factionRewardPileGUID(faction)
	local piles={Dark=monsterPiles.rewardDark, Elem=monsterPiles.rewardElem, Apoc=monsterPiles.rewardApoc, Coun=monsterPiles.rewardCouncil}
	return piles[faction]
end

--A missing reward pile means that faction is using the Just Fame variant. An existing empty pile
--stays in token mode and may refill from its matching discard pile.
function factionRewardUsesJustFame(faction)
	local pileGUID=factionRewardPileGUID(faction)
	return pileGUID==nil or getObjectFromGUID(pileGUID)==nil
end

function monsterFactionRewardFameFallback(monsterGUID)
	local printedReward, perkReward=0,0
	local data=monsterPugs~=nil and monsterPugs[monsterGUID] or nil
	if data~=nil and data.pugType~="yellow" and type(data.reward)=="number" and data.reward>0 and factionRewardUsesJustFame(data.faction)==true then
		printedReward=tonumber(data.reward) or 0
	end
	local perks=gStates.monsterPerks~=nil and gStates.monsterPerks[monsterGUID] or nil
	if perks~=nil and type(perks.reward)=="number" and perks.reward>0 and factionRewardUsesJustFame(perks.faction)==true then
		perkReward=tonumber(perks.reward) or 0
	end
	return printedReward, perkReward
end

function takeFactionRewardToken(playerIndex, pileGUID, position)
	local pile=pileGUID~=nil and getObjectFromGUID(pileGUID) or nil
	if pile==nil then return false, "justFame" end
	if pile.getQuantity()==0 then
		tokenRefill()
		pile=getObjectFromGUID(pileGUID)
	end
	if pile~=nil and pile.getQuantity()>0 then
		position=position or {(turnOrder[playerIndex].seatPos*40)-117.2+(math.random()*6.5), 2, -35+(math.random()*3.2)}
		pile.takeObject({position=position})
		return true
	end
	return false, "empty"
end

function awardFactionRewardToken(playerIndex, pileGUID, coopCombatReward, rewardKey)
	if pileGUID==nil or getObjectFromGUID(pileGUID)==nil then return false, "justFame" end
	if coopCombatReward~=nil then
		coopCombatReward.factionRewards[rewardKey]=(coopCombatReward.factionRewards[rewardKey] or 0)+1
		if coopCombatReward.factionRewardsGiven~=true then return true end
		playerIndex=coopCombatReward.player
	end
	return takeFactionRewardToken(playerIndex, pileGUID)
end

function giveQueuedFactionReward(playerIndex, pileGUID)
	local claimed, reason=takeFactionRewardToken(playerIndex, pileGUID)
	if claimed~=true and reason~="justFame" then broadcastToAll("No faction reward tokens remain to claim.", positionToColor(playerIndex)) end
end

function showCoopReward()
	local entry=gStates.coopRewardQueue[gStates.coopRewardIndex]
	if entry==nil then return end
	gStates.turnNumber=entry.player
	refreshTactic4HandBonus(false)
	gStates.preEndTurn=true
	gStates.levelingUp=false
	--The conquered city hand bonus is known now, before this player claims rewards and draws their new hand.
	if gStates.coopAssaultType=="city" and gStates.coopAssaultConquered==true and gStates.coopAssaultCityGUID~=nil then
		local cityRole=turnOrder[entry.player].defeatedCities[gStates.coopAssaultCityGUID]
		if gStates.volkareCampAsCity==true and gStates.coopAssaultCityGUID==volkare.terrainHex then
			turnOrder[entry.player].hand=turnOrder[entry.player].baseHand
			if cityRole~=nil then turnOrder[entry.player].hand=turnOrder[entry.player].baseHand+turnOrder[entry.player].keepsBeat end
		elseif cityRole=="Lead" then turnOrder[entry.player].hand=turnOrder[entry.player].baseHand+2
		elseif cityRole=="Assist" then turnOrder[entry.player].hand=turnOrder[entry.player].baseHand+1 end
	end
	turnOrder[entry.player].fameGain=entry.fame
	turnOrder[entry.player].repGain=entry.reputation
	applyPlayerFameReputation(entry.player)
	if entry.factionRewardsGiven~=true then
		for a=1, entry.factionRewards.dark do giveQueuedFactionReward(entry.player, monsterPiles.rewardDark) end
		for a=1, entry.factionRewards.elementalist do giveQueuedFactionReward(entry.player, monsterPiles.rewardElem) end
		for a=1, entry.factionRewards.apocalypse do giveQueuedFactionReward(entry.player, monsterPiles.rewardApoc) end
		for a=1, (entry.factionRewards.council or 0) do giveQueuedFactionReward(entry.player, monsterPiles.rewardCouncil) end
		entry.factionRewardsGiven=true
	end
	claimButtonRefresh()
	Wait.frames(function() mainUIUpdate("Co-op Rewards") end, 2)
end

function coopAssaultAvatarsSettled()
	if gStates.coopAssaultParticipants==nil then return true end
	for playerIndex, _ in pairs(gStates.coopAssaultParticipants) do
		local avatar=coopAssaultAvatarObject(playerIndex)
		if avatar~=nil and avatar.resting~=true then return false end
	end
	return true
end

--Faction-leader level changes are resolved only after every participant in a cooperative assault has finished combat.
function finalizeCoopLeaderCombat()
	if gStates.coopAssaultPhase~="combat" or coopAssaultTargetType()~="leader" then return end
	clearCoopLeaderPreviewClones()
	if (gStates.leaderReduction or 0)<=0 then return end
	local currentLeader=elementalist
	local currentLevel=gStates.elementalistLevel
	if gStates.coopAssaultCityGUID==darkCrusader.terrainHex then currentLeader=darkCrusader currentLevel=gStates.darkCrusaderLevel end
	if currentLevel==nil then gStates.leaderReduction=0 return end
	local finalLevel=math.max(0, currentLevel-gStates.leaderReduction)
	gStates.leaderReduction=0
	if currentLeader==darkCrusader then gStates.darkCrusaderLevel=finalLevel else gStates.elementalistLevel=finalLevel end
	local leaderObj=getObjectFromGUID(currentLeader.token)
	if finalLevel==0 then
		if leaderObj~=nil then getObjectFromGUID(trashCan).putObject(leaderObj) end
		if gStates.cityMonsterQty[currentLeader.terrainHex]~=nil then gStates.cityMonsterQty[currentLeader.terrainHex][currentLeader.token]="dead" end
		local disc=getObjectFromGUID(currentLeader.disc)
		if disc~=nil then disc.setCustomObject({image=leaderData[currentLeader.terrainHex]["dead"].discImg}) disc.reload() end
		--The whole cooperative assault is now over, so surviving followers may finally flee.
		if gStates.cityMonsterQty[currentLeader.terrainHex]~=nil then
			for monsterGUID, state in pairs(gStates.cityMonsterQty[currentLeader.terrainHex]) do
				if monsterGUID~="extra" and monsterGUID~=currentLeader.token and state~="dead" then
					local monster=getObjectFromGUID(monsterGUID)
					if monster~=nil and monster.getRotationValues()[2]~=nil then discardMonster(monster, false) end
				end
			end
		end
	else
		if leaderObj~=nil then
			if gStates.monsterPlayLocation[leaderObj.guid]~=nil then leaderObj.setPositionSmooth(gStates.monsterPlayLocation[leaderObj.guid]) end
			leaderObj.setCustomObject({image=leaderData[currentLeader.terrainHex][finalLevel].tokenImg})
			leaderObj.setName(currentLeader==darkCrusader and "Dark Crusader Leader Level "..finalLevel or "Elementalist Leader Level "..finalLevel)
			leaderObj.reload()
			monsterPugs[currentLeader.token]=leaderData[currentLeader.terrainHex][finalLevel].abilities
		end
		local disc=getObjectFromGUID(currentLeader.disc)
		if disc~=nil then disc.setCustomObject({image=leaderData[currentLeader.terrainHex][finalLevel].discImg}) disc.reload() end
	end
end

--A cooperative faction-leader assault finalizes the leader after the normal end-of-combat scenario check has already run.
--Re-check only scenario conditions that can become true specifically because that deferred leader was just defeated.
function coopLeaderScenarioEndAchieved()
	if gStates.endGameAchieved~="false" then return false end
	refreshCityDefeatState()
	if gStates.gameScenario=="Life and Death" then return gStates.defeatedFaction==2 end
	if gStates.gameScenario=="The Hidden Valley Blitz" then return gStates.defeatedFaction==1 end
	if gStates.gameScenario=="Ultimate Conquest" then
		return gStates.defeatedCities.amount==gStates.cityTiles and (gStates.removeShadesOfTezlaMonsters==true or gStates.defeatedFaction==2)
	end
	if gStates.gameScenario=="The Realm of the Dead Blitz" then
		local graveYardCount=0
		local graveYardTileCount=0
		local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
		for _, obj in pairs(objectsInPlay) do
			if obj.getName()=="GraveYard" then graveYardTileCount=graveYardTileCount+1 end
			if obj.getName()=="Shield" and volkarePursuitShieldRegistered(obj)~=true then
				local shieldPos=obj.getPosition()
				for _, graveYard in pairs(objectsInPlay) do
					if graveYard.getName()=="GraveYard" then
						local gravePos=graveYard.getPosition()
						if math.sqrt(((shieldPos[1]-gravePos[1])^2)+((shieldPos[3]-gravePos[3])^2))<1 then graveYardCount=graveYardCount+1 break end
					end
				end
			end
		end
		return gStates.defeatedFaction==1 and graveYardCount==graveYardTileCount
	end
	return false
end

function startCoopRewardPhase()
	if coopAssaultTargetType()=="dragon" then finalizeCoopDragonCombat() end
	finalizeCoopLeaderCombat()
	local assaultType=coopAssaultTargetType()
	if gStates.endGameAchieved=="false" and ((assaultType=="leader" and coopLeaderScenarioEndAchieved()==true) or (assaultType=="horsemen" and againstHorsemenAllDefeated()==true) or (assaultType=="dragon" and apocalypseDragonColoredHeadsDefeated()==true)) then gStates.coopAssaultScenarioEndPending=true end
	resolveCoopAssaultLocations()
	if gStates.coopRewardQueue==nil or #gStates.coopRewardQueue==0 then
		local scenarioEndPending=gStates.coopAssaultScenarioEndPending==true
		gStates.coopAssaultPhase=nil
		gStates.coopAssaultScenarioEndPending=false
		if scenarioEndPending then
			--Do not end immediately after a victorious co-op assault. The normal turn
			--engine must first consume assisting players' flipped turn tokens, then
			--return to the victory owner for their final turn.
			scenarioEnd(false)
			if gStates.gameOver==true then return end
			if gStates.endGameAchieved=="started" then gStates.endGameAchieved="true" end
		end
		nextTurnMerged("incrementTurn")
		return
	end
	gStates.coopRewardIndex=1
	local function beginRewards() gStates.coopAssaultPhase="rewards" showCoopReward() end
	Wait.frames(function() Wait.condition(beginRewards, coopAssaultAvatarsSettled, 3, beginRewards) end, 2)
end

function advanceCoopRewardPhase()
	local entry=gStates.coopRewardQueue[gStates.coopRewardIndex]
	if entry~=nil then
		turnOrder[entry.player].fameGain=0
		turnOrder[entry.player].repGain=0
	end
	gStates.levelingUp=false
	gStates.coopRewardIndex=gStates.coopRewardIndex+1
	if gStates.coopRewardIndex<=#gStates.coopRewardQueue then
		showCoopReward()
	else
		local scenarioEndPending=gStates.coopAssaultScenarioEndPending==true
		gStates.coopAssaultPhase=nil
		gStates.coopRewardQueue={}
		gStates.coopRewardIndex=1
		gStates.coopAssaultParticipants={}
		gStates.coopAssaultCityGUID=nil
		gStates.coopAssaultLocation=nil
		gStates.coopAssaultType=nil
		gStates.coopAssaultInitiator=nil
		gStates.coopAssaultConquered=nil
		gStates.coopAssaultScenarioEndPending=false
		gStates.preEndTurn=false
		if scenarioEndPending then
			--Victory is registered here, but gameOver waits for nextTurnMerged.
			--That lets an assister's skipped turn flip their token upright and lets
			--the initiating victory owner receive their required final turn.
			scenarioEnd(false)
			if gStates.gameOver==true then return end
			if gStates.endGameAchieved=="started" then gStates.endGameAchieved="true" end
		end
		nextTurnMerged("incrementTurn")
		recourceTrackerReset()
		claimButtonRefresh()
		addAvatarButtons()
	end
end

--Time Bending is set aside for the rest of the round when its extra-turn button is actually used.
--Keep its owner seat so the card can be recovered from the trash chest at round end or before final scoring.
local timeBendingGUID="2eb8e2"
local timeBendingRecoveryPending=false
local function reclaimTimeBending(callback)
	if gStates==nil or gStates.timeBendingRemovedSeat==nil then if callback~=nil then callback() end return false end
	if timeBendingRecoveryPending==true then return true end
	local seatPos=gStates.timeBendingRemovedSeat
	local existing=getObjectFromGUID(timeBendingGUID)
	if existing~=nil then
		gStates.timeBendingRemovedSeat=nil
		if callback~=nil then callback() end
		return false
	end
	local trash=getObjectFromGUID(trashCan)
	local discardZone=deedDeckDiscardZones~=nil and deedDeckDiscardZones[seatPos]~=nil and getObjectFromGUID(deedDeckDiscardZones[seatPos]) or nil
	if trash==nil or discardZone==nil then
		log("Unable to reclaim Time Bending: trash chest or owner discard zone is missing.")
		return false
	end
	local inTrash=false
	for _, obj in pairs(trash.getObjects()) do if obj.guid==timeBendingGUID then inTrash=true break end end
	if inTrash==false then
		gStates.timeBendingRemovedSeat=nil
		if callback~=nil then callback() end
		return false
	end
	timeBendingRecoveryPending=true
	local pos=discardZone.getPosition()
	local recovered=trash.takeObject({guid=timeBendingGUID, position={pos[1], pos[2]+1.5, pos[3]}, rotation={0,180,0}, smooth=false, callback_function=function()
		gStates.timeBendingRemovedSeat=nil
		timeBendingRecoveryPending=false
		Wait.frames(function() if callback~=nil then callback() end end, 2)
	end})
	if recovered==nil then
		timeBendingRecoveryPending=false
		log("Unable to reclaim Time Bending from the trash chest.")
		return false
	end
	return true
end

--Returns which immediate extra-turn effects are currently available to the active player.
local function extraTurnOptions(playerIndex)
	local details=turnOrder[playerIndex]
	if details==nil then return false, false end
	local tacticSixAvailable=details.tactic==6 and gStates.dayRound==true and gStates.tacticSixState~="Used" and gStates.tacticRemove==false and gStates.tacticShown==false
	local timeBendingAvailable=false
	local playArea=getObjectFromGUID(playerPlayAreas[details.seatPos])
	if playArea~=nil then
		for _, obj in pairs(playArea.getObjects()) do if obj.guid=="2eb8e2" then timeBendingAvailable=true break end end
	end
	return tacticSixAvailable, timeBendingAvailable
end

--The normal extra-turn button opens a choice only when both effects are genuinely available.
function extraTurnButton(player, mouseButton, id)
	if mouseButton~="-1" or legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)~=true then return end
	local tacticSixAvailable, timeBendingAvailable=extraTurnOptions(gStates.turnNumber)
	if tacticSixAvailable and timeBendingAvailable then
		UI.setAttribute("ExtraTurnChoice", "visibility", positionToColor(gStates.turnNumber).."|Black")
		UI.show("ExtraTurnChoice")
		return
	end
	UI.hide("ExtraTurnChoice")
	if tacticSixAvailable then
		preEndTurn(player, "-1", "ExtraTurnChoiceTactic6")
	elseif timeBendingAvailable then
		preEndTurn(player, "-1", "ExtraTurnChoiceTimeBending")
	end
end

function extraTurnChoice(player, mouseButton, id)
	if mouseButton~="-1" or legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)~=true then return end
	local tacticSixAvailable, timeBendingAvailable=extraTurnOptions(gStates.turnNumber)
	if id=="ExtraTurnChoiceTimeBending" and timeBendingAvailable then
		UI.hide("ExtraTurnChoice")
		preEndTurn(player, "-1", "ExtraTurnChoiceTimeBending")
	elseif id=="ExtraTurnChoiceTactic6" and tacticSixAvailable then
		UI.hide("ExtraTurnChoice")
		preEndTurn(player, "-1", "ExtraTurnChoiceTactic6")
	end
end

--Mine crystal claim: resolve before cleanup/rewards so Deep Mine choice follows the End of Turn sequence.
mineCrystalBagKey={Red="red", Blue="blue", Green="green", White="white"}

function mineCrystalCount(playerIndex, color)
	local details=turnOrder[playerIndex]
	if details==nil then return 0 end
	local zone=getObjectFromGUID(playerCrystalAreas[details.seatPos])
	if zone==nil then return 0 end
	local count=0
	for _, obj in pairs(zone.getObjects()) do
		if obj.getDescription()==color or obj.getName()==color.." Mana" then count=count+1 end
	end
	return count
end

function mineLiberatedForClaim(playerIndex, terrainGUID, hexPos)
	if gStates.gameScenario~="Mines Liberation" then return true end
	local map=getObjectFromGUID(mapArea)
	if map~=nil then
		for _, obj in pairs(map.getObjects()) do
			if obj.getName()=="Shield" and volkarePursuitShieldRegistered(obj)~=true then
				local p=obj.getPosition()
				if ((p[1]-hexPos[1])^2)+((p[3]-hexPos[3])^2)<1 then return true end
			end
		end
	end
	--A mine conquered this turn does not receive its Shield until cleanup. Treat its face-up
	--mine enemies in this player's play area as defeated-pending so the crystal can be chosen first.
	local monsters=gStates.mineMonsterQty~=nil and gStates.mineMonsterQty[terrainGUID] or nil
	if monsters==nil then return false end
	local playArea=getObjectFromGUID(playerPlayAreas[turnOrder[playerIndex].seatPos])
	local pendingDefeat={}
	if playArea~=nil then
		for _, obj in pairs(playArea.getObjects()) do if obj.is_face_down==false then pendingDefeat[obj.guid]=true end end
	end
	local found=false
	for monsterGUID, state in pairs(monsters) do
		found=true
		if state~="dead" and pendingDefeat[monsterGUID]~=true then return false end
	end
	return found
end

function mineClaimData(playerIndex)
	local avatar=coopAssaultAvatarObject(playerIndex)
	if avatar==nil then return nil end
	local terrain, bearing, hexPos, feature=terrainHexAtPosition(avatar.getPosition())
	if terrain==nil or bearing==nil or feature~="mine" then return nil end
	local details=terrainTiles[terrain.guid]
	local colors=details~=nil and details.mineColors~=nil and details.mineColors[bearing] or nil
	if colors==nil or #colors==0 or mineLiberatedForClaim(playerIndex, terrain.guid, hexPos)==false then return nil end
	return {terrainGUID=terrain.guid, bearing=bearing, colors=colors}
end

function mineInventoryPosition(playerIndex, color)
	local seatPos=turnOrder[playerIndex].seatPos
	local board=getObjectFromGUID(playerBoard[seatPos])
	local zone=getObjectFromGUID(playerCrystalAreas[seatPos])
	if board==nil or zone==nil then return {(seatPos*40)-114, 2.0, -36.8} end
	local zonePos, zoneScale=zone.getPosition(), zone.getScale()
	local objects=zone.getObjects()
	local matching={}
	for _, obj in pairs(objects) do
		if obj.getDescription()==color or obj.getName()==color.." Mana" then matching[#matching+1]=obj.getPosition() end
	end
	local choices={}
	for _, snap in pairs(board.getSnapPoints() or {}) do
		local p=board.positionToWorld(snap.position)
		if math.abs(p[1]-zonePos[1])<=zoneScale[1]/2 and math.abs(p[3]-zonePos[3])<=zoneScale[3]/2 then
			local occupied=false
			for _, obj in pairs(objects) do
				local op=obj.getPosition()
				if ((op[1]-p[1])^2)+((op[3]-p[3])^2)<0.56 then occupied=true break end
			end
			if occupied==false then
				local nearest=999999
				for _, mp in pairs(matching) do nearest=math.min(nearest, ((mp[1]-p[1])^2)+((mp[3]-p[3])^2)) end
				choices[#choices+1]={position={p[1], 2.0, p[3]}, score=nearest}
			end
		end
	end
	if #choices>0 then
		table.sort(choices, function(a,b) if a.score==b.score then return a.position[1]<b.position[1] end return a.score<b.score end)
		return choices[1].position
	end
	--No board snap is free (usually because reward tokens were placed over them). Find the clearest
	--physical point in the inventory instead of stacking the new crystal on an existing object.
	local best={position={zonePos[1],2.0,zonePos[3]}, clearance=-1}
	for i=1, 24 do
		local p={zonePos[1]-((zoneScale[1]/2)-0.6)+(math.random()*math.max(0.1,zoneScale[1]-1.2)), 2.0,
			zonePos[3]-((zoneScale[3]/2)-0.6)+(math.random()*math.max(0.1,zoneScale[3]-1.2))}
		local clearance=999999
		for _, obj in pairs(objects) do local op=obj.getPosition() clearance=math.min(clearance, ((op[1]-p[1])^2)+((op[3]-p[3])^2)) end
		if clearance>best.clearance then best={position=p, clearance=clearance} end
	end
	return best.position
end

function refreshMineClaimPanel()
	local pending=gStates.mineClaimPending
	if pending==nil or turnOrder[pending.playerIndex]==nil then UI.hide("MineClaimChoice") return end
	UI.setAttribute("MineClaimChoiceTitle", "text", pending.source=="Quest" and "Quest Crystal" or "Mined Crystal")
	for i=1, 4 do
		local color=pending.colors[i]
		UI.setAttribute("MineClaimButton"..i, "active", color~=nil and "true" or "false")
		if color~=nil then UI.setAttribute("MineClaimButtonText"..i, "text", color) end
	end
	UI.setAttribute("MineClaimRow2", "active", #pending.colors>2 and "true" or "false")
	UI.setAttribute("MineClaimChoice", "visibility", positionToColor(pending.playerIndex).."|Black")
	UI.show("MineClaimChoice")
end

function beginMineCrystalClaim(playerIndex, messageColor)
	local data=mineClaimData(playerIndex)
	if data==nil then return false end
	local available={}
	for _, color in ipairs(data.colors) do if mineCrystalCount(playerIndex, color)<3 then available[#available+1]=color end end
	if #available==0 then
		if messageColor~=nil then broadcastToColor("No crystal gained from the Mine: your Inventory already has 3 of every available color.", messageColor, warningColor)
		else broadcastToAll("No crystal gained from the Mine: your Inventory already has 3 of every available color.", warningColor) end
		return false
	end
	gStates.mineClaimPending={source="Mine", playerIndex=playerIndex, terrainGUID=data.terrainGUID, bearing=data.bearing, colors=available}
	refreshMineClaimPanel()
	return true
end

function mineClaimChoice(player, mouseButton, id)
	if mouseButton~="-1" or player==nil then return end
	local pending=gStates.mineClaimPending
	if pending==nil or turnOrder[pending.playerIndex]==nil then UI.hide("MineClaimChoice") return end
	local claimantColor=positionToColor(pending.playerIndex)
	local sourceName=pending.source=="Quest" and "Quest" or "Mine"
	if player.color~=claimantColor and player.color~="Black" then
		broadcastToColor("Only the claiming player can choose this "..sourceName.." crystal.", player.color, {1,0.3,0.3})
		return
	end
	local index=tonumber(id:match("(%d+)$"))
	local color=index~=nil and pending.colors[index] or nil
	if color==nil then return end
	if mineCrystalCount(pending.playerIndex, color)>=3 then
		broadcastToColor("You already have 3 "..color.." crystals in your Inventory.", player.color, warningColor)
		return
	end
	local bagKey=mineCrystalBagKey[color]
	local bag=bagKey~=nil and getObjectFromGUID(GUID.bag.mana[bagKey]) or nil
	if bag==nil or bag.getQuantity()==0 then
		broadcastToColor("No "..color.." crystal is available in the supply.", player.color, {1,0.3,0.3})
		return
	end
	local questCardGUID=pending.questCardGUID
	takeManaCrystal(bag,{position=mineInventoryPosition(pending.playerIndex, color),smooth=false})
	broadcastToColor("Claimed a "..color.." Crystal from the "..sourceName..".", player.color, {1,1,0.5})
	gStates.mineClaimPending=nil
	UI.hide("MineClaimChoice")
	if questCardGUID~=nil and getObjectFromGUID(questCardGUID)~=nil then apocalypseQuestUpdateProgressButtons(getObjectFromGUID(questCardGUID)) end
end

--Clears a players board area and Asks if rewards are claimed
--Keep Rewards Claimed locked briefly while cleanup objects/UI are still settling.
local rewardClaimDelayActive=false
local rewardClaimDelayWait=nil
--local slightPause=true
function __preEndTurn_raw(player, mouseButton, id, rewindReady)
	if gStates.apocalypseDragonTurnActive==true and (againstDragonFullAttendInProgress==nil or againstDragonFullAttendInProgress(gStates.turnNumber)~=true) then
		if player~=nil and player.color~=nil then broadcastToColor("Finish the Apocalypse Dragon turn first.",player.color,warningColor) end
		return
	end
	--Wait.time(function() slightPause=false end, 1)
	if mouseButton=="-1" and legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true then
		if gStates.mineClaimPending~=nil then
			broadcastToColor("Resolve the pending crystal choice before ending the turn.", player.color, warningColor)
			if rewindReady==true then rewindTransactionFinish("Pre-end-turn cleanup") end
			return
		end
		if rewindReady~=true then
			if rewindTransactionOwnerActive("Pre-end-turn cleanup")==true then return end
			rewindTransactionStart(function() preEndTurn(player,mouseButton,id,true) end,"Pre-end-turn cleanup")
			return
		end
		local cleanupPlayer=gStates.turnNumber
		volkarePursuitResolveCombat(cleanupPlayer)
		puppetMasterCleanupPlayedPuppets(cleanupPlayer)
		--A Quest marker may still be settling under this Hero. Finish that temporary lift before the older
		--end-turn site-cleanup lift records avatarPos/locks the same object, or it can be left floating.
		apocalypseQuestRestoreRaisedAvatar(cleanupPlayer,true)
		local coopCombatReward=nil
		if gStates.coopAssaultPhase=="combat" then
			coopCombatReward={player=gStates.turnNumber, mage=turnOrder[gStates.turnNumber].mage, fame=turnOrder[gStates.turnNumber].fameGain, reputation=turnOrder[gStates.turnNumber].repGain, factionRewards={dark=0, elementalist=0, apocalypse=0, council=0}}
			gStates.coopRewardQueue[#gStates.coopRewardQueue+1]=coopCombatReward
			UI.setAttribute("EndTurnButton", "interactable", "false")
			UI.setAttribute("EndTurnButtonImage", "image", "Sliced Button/Button New Deactive")
			UI.setAttribute("EndTurnButtonAlt", "interactable", "false")
			UI.setAttribute("EndTurnButtonAltImage", "image", "Sliced Button/Button New Deactive")
		end
		--reset variables for next turn
		gStates.preEndTurn=true
		--Before combat cleanup moves/discards Quest enemies, remember successful combat-gated Quest
		--resolutions. This keeps Rewards Claimed unavailable until the player presses Progress/Complete.
		apocalypseQuestCaptureRewardCompletionGate(cleanupPlayer)
		--Free Wine uses a normal Keep assault rather than a Quest-spawned combat, so capture its outcome
		--separately now that the rewards boundary has been reached.
		apocalypseQuestCaptureFreeWineResolutionGate(cleanupPlayer)
		--Mine of Doom enemies now use the normal end-of-turn combat cleanup with every other enemy.
		rewardClaimDelayActive=true
		if rewardClaimDelayWait~=nil then Wait.stop(rewardClaimDelayWait) rewardClaimDelayWait=nil end
		gStates.monsterOffsetX=0
		gStates.monsterOffsetZ=0
		gStates.attackedMonsters={}
		combatCameraChoiceSuppressedPlayer=nil
		turnOrder[gStates.turnNumber].combatIconHide="Both"
		if turnOrder[gStates.turnNumber].masterOfChaos~=nil then turnOrder[gStates.turnNumber].masterOfChaos="available" end
		addAvatarButtons()
		if gStates.coopAssaultPhase~="combat" then claimButtonRefresh() end
		UI.setAttribute("PreEndTurn", "interactable", "false")
		UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Deactive")
		rewardClaimDelayWait=Wait.time(function()
			rewardClaimDelayWait=nil
			local function finishRewardDelay()
				rewardClaimDelayActive=false
				if gStates.preEndTurn==true and turnOrder[gStates.turnNumber]~=nil then
					if steadyTempoUpdateRewardGate~=nil then steadyTempoUpdateRewardGate(turnOrder[gStates.turnNumber].seatPos)
					else
						UI.setAttribute("PreEndTurn", "interactable", "true")
						UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Active")
					end
				end
				rewindTransactionFinish("Pre-end-turn cleanup")
			end
			local dragonCombat=gStates.apocalypseDragonGroundCombat
			if dragonCombat~=nil and dragonCombat.coop~=true and dragonCombat.playerIndex==gStates.turnNumber and dragonCombat.levelsApplied~=true then
				Wait.condition(finishRewardDelay,function()
					local current=gStates.apocalypseDragonGroundCombat
					return current==nil or current.levelsApplied==true
				end,5,finishRewardDelay)
			else
				finishRewardDelay()
			end
		end, 2.0)

		if id=="ExtraTurnTacticButton" or id=="ExtraTurnChoiceTactic6" or id=="ExtraTurnChoiceTimeBending" then
			local tacticSixAvailable, timeBendingAvailable=extraTurnOptions(gStates.turnNumber)
			local useTactic=id=="ExtraTurnChoiceTactic6" or (id=="ExtraTurnTacticButton" and tacticSixAvailable and timeBendingAvailable==false)
			local useTimeBending=id=="ExtraTurnChoiceTimeBending" or (id=="ExtraTurnTacticButton" and timeBendingAvailable and tacticSixAvailable==false)
			--flip Day tactic six if using the second turn
			if useTactic then
				gStates.tacticSixState="Started"
				getObjectFromGUID("2404f1").setRotationSmooth({0.00, 180.00, 180.00})
				if getObjectFromGUID(turnOrder[gStates.turnNumber].turnOrderTokenGUID).is_face_down==true then
					getObjectFromGUID(turnOrder[gStates.turnNumber].turnOrderTokenGUID).flip()
					gStates.tacticSixState="Used"
					gStates.skipTurn[gStates.turnNumber]=nil
				end
			end
			--Change clean up if Time Bending used
			if useTimeBending then
				gStates.timeBending="Started"
				if getObjectFromGUID(turnOrder[gStates.turnNumber].turnOrderTokenGUID).is_face_down==true then
					getObjectFromGUID(turnOrder[gStates.turnNumber].turnOrderTokenGUID).flip()
					gStates.timeBending="Used"
					gStates.skipTurn[gStates.turnNumber]=nil
				end
			end
		end
		mainUIUpdate("Pre End Turn")
		--Mine rewards are chosen alongside the normal Rewards Claimed stage. The turn cannot advance until resolved.
		local mineTurnEligible=turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] and turnOrder[gStates.turnNumber].endCalled~=true
		if mineTurnEligible and gStates.coopAssaultPhase~="combat" then beginMineCrystalClaim(gStates.turnNumber, player.color) end

		--lift player Avatar for token(s) to go under
		local tokenRaised=0
		local avatarPos={}
		local avatarModel=nil
		if (turnOrder[gStates.turnNumber].avatarLocation=="mine" and gStates.gameScenario=="Mines Liberation")
			or (turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" and gStates.gameScenario=="The Lost Relic Blitz")
			or (turnOrder[gStates.turnNumber].avatarLocation=="glade" and gStates.gameScenario=="Life and Death")
			or turnOrder[gStates.turnNumber].avatarLocation=="graveyard"
			or turnOrder[gStates.turnNumber].avatarLocation=="keep"	or turnOrder[gStates.turnNumber].avatarLocation=="mage tower"
			or turnOrder[gStates.turnNumber].avatarLocation=="tomb"	or turnOrder[gStates.turnNumber].avatarLocation=="dungeon"
			or turnOrder[gStates.turnNumber].avatarLocation=="labyrinth" or turnOrder[gStates.turnNumber].avatarLocation=="maze"
			or turnOrder[gStates.turnNumber].avatarLocation=="ziggurat" or turnOrder[gStates.turnNumber].avatarLocation=="pyramid"
			or turnOrder[gStates.turnNumber].avatarLocation=="ruin"
			or turnOrder[gStates.turnNumber].avatarLocation=="monster den" or turnOrder[gStates.turnNumber].avatarLocation=="spawning grounds"
			or turnOrder[gStates.turnNumber].avatarLocation=="monastery"
			or (againstDragonFullAttendInProgress~=nil and againstDragonFullAttendInProgress(gStates.turnNumber)==true
				and againstDragonAirborneProtectionDestroysSite~=nil and againstDragonAirborneProtectionDestroysSite(turnOrder[gStates.turnNumber].avatarLocation)==true) then
			for _, b in pairs(mageKnights) do
				if b.mage==turnOrder[gStates.turnNumber].mage then
					if getObjectFromGUID(b.model)~=nil then avatarModel=getObjectFromGUID(b.model) end
					if getObjectFromGUID(b.token)~=nil then avatarModel=getObjectFromGUID(b.token) end
					if getObjectFromGUID(b.standee)~=nil then avatarModel=getObjectFromGUID(b.standee) end
					if avatarModel~=nil then
						avatarPos=avatarModel.getPosition()
						avatarModel.setPosition({avatarPos[1], avatarPos[2]+2, avatarPos[3]})
						avatarModel.lock()
					end
					tokenRaised=gStates.turnNumber
					break
				end
			end
		end

		--return dice function needed twice
		function returnDice(diceGUID)
			--make sure coop assault isn't happening before returning dice.
			gStates.coopAssaultDice[#gStates.coopAssaultDice+1]=diceGUID
			if getObjectFromGUID(turnOrder[nextTurnMerged("nextMageSkipDummy")].turnOrderTokenGUID).is_face_down==false or #turnOrder<=2 then
				for _, diceG in pairs(gStates.coopAssaultDice) do
					if getObjectFromGUID(diceG)~=nil then
						getObjectFromGUID(diceG).setPosition({-12.5+(math.random()*7), 2.7, -25.0+(math.random()*4.0)})
						getObjectFromGUID(diceG).randomize()
						onObjectRandomize({type="Dice"})
					end
				end
				gStates.coopAssaultDice={}
			end
		end

		--locate discard deck
		local cardDestination=nil
		for _, deckSearch in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
			if deckSearch.type=="Card" or deckSearch.type=="Deck" then cardDestination=deckSearch break end
		end

		--seperate any decks and possessed tokens found. Unit Area monsters use the same combat cleanup path.
		local tokenWait=0
		for _, playAreaObj in pairs(playerCombatObjects(turnOrder[gStates.turnNumber].seatPos)) do
			--seperate decks
			if playAreaObj.type=="Deck" then
				for count=1, #playAreaObj.getObjects()-1, 1 do
					playAreaObj.takeObject({position={playAreaObj.getPosition()[1]+(0.8*count), playAreaObj.getPosition()[2]+(0.06*count), playAreaObj.getPosition()[3]+(0.8*count)}, smooth=false})
				end
			end
			--Separate possessed tokens only after the base enemy was actually defeated.
			--An undefeated face-down rampager returns to the map with its possession still attached.
			if playAreaObj.getAttachments()[1]~=nil and playAreaObj.is_face_down==false then
				if gStates.gameScenario=="Against the Apocalypse Blitz" and UI.getAttribute("zigguratPyramidInteract", "active")=="false" and (monsterPugs[playAreaObj.guid].pugType=="red" or monsterPugs[playAreaObj.guid].pugType=="green") then
					--Award Destroyed Site tokens only for defeated possessed rampagers.
					getObjectFromGUID(GUID.bag.destroyedSite).takeObject({position={(turnOrder[gStates.turnNumber].seatPos*40)-117.2+(math.random()*6.5), 2, -35+(math.random()*3.2)}})
					if monsterPugs[playAreaObj.guid].pugType=="red" then getObjectFromGUID(GUID.bag.destroyedSite).takeObject({position={(turnOrder[gStates.turnNumber].seatPos*40)-117.2+(math.random()*6.5), 2, -35+(math.random()*3.2)}}) end
				end
				attachEnemy(nil, nil, "detach", playAreaObj, nil)
			end
			tokenWait=40
		end

		Wait.frames(function()
			--Get objects from player area to clean them up
			local objectAvoidance=1
			local volkareCityShield=0
			local lastObject=nil
			local VolkarePaused=false
			local spawningGroundMonstersReturned=0
			local spawningGroundMonstersBeat=0
			gStates.turnForfeited=true
			--Goblin Warrens is resolved by the normal monster-cleanup result below. Fresh Goblins begin
			--face up, so checking them here would incorrectly count an untouched/failed fight as success.
			for _, playAreaObj in pairs(playerCombatObjects(turnOrder[gStates.turnNumber].seatPos)) do
				local cleanupObjectGUID=playAreaObj.guid
				Wait.frames(function() tokenRefill() end, tokenWait+1)
				Wait.frames(function()
					--Returning an airborne Dragon head restores its real image with reload(), which invalidates
					--the old TTS Object userdata for all four captured head objects. Identify them by GUID before
					--touching that userdata, return the set once, and stop this object's ordinary cleanup here.
					local dragonAirborneCleanup=againstDragonFullAttendInProgress~=nil and againstDragonFullAttendInProgress(gStates.turnNumber)==true and againstDragonAirborneHeadGUID~=nil and againstDragonAirborneHeadGUID(cleanupObjectGUID)==true
					if dragonAirborneCleanup==true then
						againstDragonReturnAirborneHeads()
						--The avatar is still raised at this cleanup boundary. Resolve site protection now so
						--the Destroyed Site marker can settle underneath it before the avatar comes back down.
						local pendingDragonAttack=gStates~=nil and gStates.apocalypseDragonPendingAttack or nil
						if againstDragonResolveAirborneProtection~=nil then againstDragonResolveAirborneProtection(pendingDragonAttack) end
						return
					end
					playAreaObj=getObjectFromGUID(cleanupObjectGUID)
					if playAreaObj==nil then return end

					--Return any Mana dice
					if playAreaObj.type=="Dice" then
						returnDice(playAreaObj.guid)
					end

					--Delete wound tokens, shards and face up potions.
					if playAreaObj.getGMNotes()=="Unit Wound" or playAreaObj.getGMNotes()=="Volkare Reminder Token" or playAreaObj.getGMNotes()=="Trap Reminder Token" or playAreaObj.getGMNotes()=="Oasis Reminder Token" or
						playAreaObj.getName()=="Green Shard" or playAreaObj.getName()=="Red Shard" or playAreaObj.getName()=="Blue Shard" or playAreaObj.getName()=="White Shard" or
						((playAreaObj.getName()=="Green Potion" or playAreaObj.getName()=="Red Potion" or playAreaObj.getName()=="Blue Potion" or playAreaObj.getName()=="White Potion") and playAreaObj.is_face_down==false) or
						(playAreaObj.getName()=="" and playAreaObj.type=="Tile" and monsterPugs[playAreaObj.guid]==nil) then
						getObjectFromGUID(trashCan).putObject(playAreaObj)
					end

					--Return face down Potion
					if ((playAreaObj.getName()=="Green Potion" or playAreaObj.getName()=="Red Potion" or playAreaObj.getName()=="Blue Potion" or playAreaObj.getName()=="White Potion") and playAreaObj.is_face_down==true) then
						if gStates.mageSkills[playAreaObj.guid]~=nil then playAreaObj.setPositionSmooth(gStates.mageSkills[playAreaObj.guid]) end
					end

					--Mark mine monster as defeated
					for _, monsters in pairs(gStates.mineMonsterQty) do
						if monsters[playAreaObj.guid]~=nil and playAreaObj.is_face_down==false then
							monsters[playAreaObj.guid]="dead"
							break
						end
					end

					local dragonGroundCleanup=apocalypseDragonGroundCombatForPlayer~=nil and apocalypseDragonGroundCombatForPlayer(gStates.turnNumber)==true and apocalypseDragonGroundCombatToken~=nil and select(1,apocalypseDragonGroundCombatToken(playAreaObj.guid))==true
					if dragonGroundCleanup==true then
						apocalypseDragonGroundResolveToken(playAreaObj)
						apocalypseDragonGroundTryApplyLevelsBeforeRewards(gStates.turnNumber)
						return
					end

					--Return undefeated face down tokens
					if monsterPugs[playAreaObj.guid]~=nil and playAreaObj.is_face_down==true and dragonGroundCleanup~=true then
						if gStates.monsterPlayLocation[playAreaObj.guid]==nil or turnOrder[gStates.turnNumber].avatarLocation=="spawning grounds" then
							--if manual drawn assign the avatar location as return spot.
							if (gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[playAreaObj.guid]~=true) and gStates.summonStates[playAreaObj.guid]~="summoned" and (turnOrder[gStates.turnNumber].avatarLocation=="monster den" or turnOrder[gStates.turnNumber].avatarLocation=="spawning grounds" or turnOrder[gStates.turnNumber].avatarLocation=="ruin") then
								gStates.monsterPlayLocation[playAreaObj.guid]={avatarPos[1], 2.5, avatarPos[3]}
							end
						end
						if gStates.monsterPlayLocation[playAreaObj.guid]~=nil then
							if gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]~=nil and gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage][playAreaObj.guid]~=nil then
								local pursuit=gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage][playAreaObj.guid]
								pursuit.state="Stunned" pursuit.stunned=true
								playAreaObj.setRotation({0, 180, 0})
								broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} Stunned the Pursuing Rampager (Skips next turns Movement){ru} «оглушает» преследователя (тот пропускает одно Движение){zh-cn}晕眩了狂暴追击者(它跳过下次行动){ko}: 추적하는 적 기절시킴. (다음 추적 단계 건너뜀.){es} Aturdido al agresor que lo persigue (se salta el movimiento del siguiente turno){fr} Étourdi le saccageur à la poursuite (ignore le mouvement des tours suivants){pt-br} Atordoou o Irascível Perseguidor (Pule próximos turnos de movimento).{de} hat den Verfolger betäubt (überspringt die Bewegung des nächsten Zuges)"}), positionToColor(gStates.turnNumber))
							else
								Wait.time(function() if  getObjectFromGUID(playAreaObj.guid)~=nil then playAreaObj.setRotation({0, 180, 0}) end end, 3)--long enough to have traveled back to the board.
							end
							if gStates.coopAssaultPhase=="combat" and coopAssaultTargetType()=="horsemen" and horsemanTokenToName~=nil and horsemanTokenToName[playAreaObj.guid]~=nil then
								--Each Horseman is assigned to exactly one participant; a survivor returns to its Portal-card slot.
								playAreaObj.setRotation({0,180,0})
								playAreaObj.setPositionSmooth(gStates.monsterPlayLocation[playAreaObj.guid])
								lastObject=playAreaObj
							elseif gStates.coopAssaultPhase=="combat" and coopAssaultTargetType()=="leader" and (playAreaObj.guid==elementalist.token or playAreaObj.guid==darkCrusader.token) then
								--A face-down leader means this player defeated no leader levels. Advance the real token through
								--the same preview handoff used by a face-up surviving leader so the next planning copy is consumed.
								if coopAssaultPendingCombat()==true then
									local nextPlayer=nextTurnMerged("nextMage")
									promoteCoopLeaderPreview(nextPlayer, playAreaObj)
								else
									clearCoopLeaderPreviewClones()
									playAreaObj.setRotation({0, 180, 0})
									playAreaObj.setPositionSmooth(gStates.monsterPlayLocation[playAreaObj.guid])
								end
							elseif getObjectFromGUID(turnOrder[nextTurnMerged("nextMage")].turnOrderTokenGUID).is_face_down==true and playAreaObj.getRotationValues()[2]==nil then
								--Move to next players play area.
								playAreaObj.setPositionSmooth({turnOrder[nextTurnMerged("nextMage")].seatPos*40-100, 1.5, -39.41})
							else
								if turnOrder[gStates.turnNumber].avatarLocation=="spawning grounds" and (gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[playAreaObj.guid]~=true) then
									gStates.monsterPlayLocation[playAreaObj.guid][1]=gStates.monsterPlayLocation[playAreaObj.guid][1]-0.22+(spawningGroundMonstersReturned*0.44)
									gStates.monsterPlayLocation[playAreaObj.guid][2]=gStates.monsterPlayLocation[playAreaObj.guid][2]+(spawningGroundMonstersReturned*0.12)
									spawningGroundMonstersReturned=spawningGroundMonstersReturned+1
								end
								if gStates.monsterPerks[playAreaObj.guid]~=nil and gStates.monsterPerks[playAreaObj.guid].wallFortified~=nil then setAssaultWallFortified(playAreaObj, false) end
								playAreaObj.setPositionSmooth(gStates.monsterPlayLocation[playAreaObj.guid])
								lastObject=playAreaObj
							end
						end
					end

					function discardMonster(playAreaObj, giveRewards)
						if gStates.apocalypseQuestGoblinEnemies~=nil and gStates.apocalypseQuestGoblinEnemies[playAreaObj.guid]~=nil then
							--Goblin Warrens enemies come from an Infinite Bag and are not members of a normal
							--monster discard cycle. Record the same face-up/face-down result normal cleanup uses
							--before deleting the temporary enemy; only an all-face-up cleanup earns Step 1.
							apocalypseQuestGoblinRecordCleanup(playAreaObj.guid,playAreaObj.is_face_down==false)
							objectAvoidance=objectAvoidance+1
							gStates.apocalypseQuestGoblinEnemies[playAreaObj.guid]=nil
							if gStates.monsterPerks~=nil then gStates.monsterPerks[playAreaObj.guid]=nil end
							if gStates.attackedMonsters~=nil then gStates.attackedMonsters[playAreaObj.guid]=nil end
							if gStates.monsterPlayLocation~=nil then gStates.monsterPlayLocation[playAreaObj.guid]=nil end
							if gStates.summonStates~=nil then gStates.summonStates[playAreaObj.guid]=nil end
							monsterPugs[playAreaObj.guid]=nil
							playAreaObj.destruct()
							return
						end
						local tokens={"Dark Crusader Draconum", GUID.bag.discard.darkDraconum, "Dark Crusader Dungeon Monster", GUID.bag.discard.darkDungeon, "Marauding Dark Crusader", GUID.bag.discard.darkMarauders	--Dark Crusader Pugs
									,"Elementalist Draconum", GUID.bag.discard.elementalistDraconum, "Elementalist Dungeon Monster", GUID.bag.discard.elementalistDungeon, "Marauding Elementalist", GUID.bag.discard.elementalistOrcs	--Elementalist Faction
									,"Draconum", GUID.bag.discard.draconum, "Dungeon Monster", GUID.bag.discard.dungeon, "Marauding Orcs", GUID.bag.discard.orcs, "City Garrison", GUID.bag.discard.cityGarrison, "Ruin", GUID.bag.discard.ruin, "Mage Tower Garrison", GUID.bag.discard.towerGarrison, "Keep Garrison", GUID.bag.discard.keepGarrison, "Possessed", GUID.bag.discard.possessed}--General Pug
						for x=1, #tokens, 2 do
							if playAreaObj.getRotationValues()[2].value==tokens[x] then
								playAreaObj.setRotation({0, 180, 0})
								local discardBag={}
								if getObjectFromGUID(tokens[x+1])~=nil then
									discardBag=getObjectFromGUID(tokens[x+1])
								end
								if x<=6 then
									if gStates.gameScenario~="Life and Death" and gStates.gameScenario~="The Realm of the Dead Blitz" then
										discardBag=getObjectFromGUID(tokens[x+13])
									end
									--Put Dark Crusader reward in player inventory. A missing pile means Just Fame; an empty
									--existing pile refills from its discard before the reward is declared unavailable.
									if giveRewards==true and gStates.summonStates[playAreaObj.guid]~="summoned" and playAreaObj.is_face_down==false then
										local claimed,reason=awardFactionRewardToken(gStates.turnNumber,monsterPiles.rewardDark,coopCombatReward,"dark")
										if claimed~=true and reason=="empty" then broadcastToAll("Sorry, there are no more Dark Crusader Faction Reward Tokens to claim.",positionToColor(gStates.turnNumber)) end
									end
								end
								if x>=7 and x<=12 then
									if gStates.gameScenario~="Life and Death" and gStates.gameScenario~="The Hidden Valley Blitz" then
										discardBag=getObjectFromGUID(tokens[x+7])
									end
									--Put Elementalist reward in player inventory.
									if giveRewards==true and gStates.summonStates[playAreaObj.guid]~="summoned" and playAreaObj.is_face_down==false then
										local claimed,reason=awardFactionRewardToken(gStates.turnNumber,monsterPiles.rewardElem,coopCombatReward,"elementalist")
										if claimed~=true and reason=="empty" then broadcastToAll("Sorry, there are no more Elementalist Faction Reward Tokens to claim.",positionToColor(gStates.turnNumber)) end
									end
								end
								if x==27 then--possessed token
									local possessedFaction=(gStates.apocalypsePossessedFactionByToken~=nil and gStates.apocalypsePossessedFactionByToken[playAreaObj.guid]) or "Apoc"
									local possessedRewards={Dark={pile=monsterPiles.rewardDark,key="dark"}, Elem={pile=monsterPiles.rewardElem,key="elementalist"}, Apoc={pile=monsterPiles.rewardApoc,key="apocalypse"}, Coun={pile=monsterPiles.rewardCouncil,key="council"}}
									local rewardData=possessedRewards[possessedFaction] or possessedRewards.Apoc
									if giveRewards==true and gStates.summonStates[playAreaObj.guid]~="summoned" and playAreaObj.is_face_down==false then
										local claimed,reason=awardFactionRewardToken(gStates.turnNumber,rewardData.pile,coopCombatReward,rewardData.key)
										if claimed~=true and reason=="empty" then broadcastToAll("Sorry, there are no more Faction Reward Tokens to claim.",positionToColor(gStates.turnNumber)) end
									end
									--Faction identity belongs to this use of the Possessed token only. Clear it after its reward is resolved,
									--not when it is detached from the enemy, so Quest faction rewards survive end-turn separation.
									if gStates.apocalypsePossessedFactionByToken~=nil then gStates.apocalypsePossessedFactionByToken[playAreaObj.guid]=nil end
								end
								--mark city monsters defeated
								for cityguid, monsters in pairs(gStates.cityMonsterQty) do
									if monsters[playAreaObj.guid]~=nil then
										--mark monster dead
										monsters[playAreaObj.guid]="dead"
										--drop shield
										if monsters.extra~=nil and (monsters.extra.megapolisPair==nil or monsters.extra.megapolisPair~=cityguid) then
											local cityZone={[cityModel.blue]=GUID.zone.blueCity, [cityModel.red]=GUID.zone.redCity, [cityModel.green]=GUID.zone.greenCity, [cityModel.white]=GUID.zone.whiteCity, [volkare.terrainHex]=volkare.discZone}
											if cityZone[cityguid]~=nil then
												local location={getObjectFromGUID(cityZone[cityguid]).getPosition()[1]+(-2+monsters.extra.shieldsThere), 1.13, getObjectFromGUID(cityZone[cityguid]).getPosition()[3]+1}
												if monsters.extra.shieldsThere>4 then location[1]=location[1]-5 location[3]=location[3]-0.5 end
												--Volkares camp gives only half shields to green and gray rounded down.
												if cityguid==volkare.terrainHex and (monsterPugs[playAreaObj.guid].pugType=="green" or monsterPugs[playAreaObj.guid].pugType=="gray") then
													volkareCityShield=volkareCityShield+0.5
												end
												if cityguid~=volkare.terrainHex or (cityguid==volkare.terrainHex and (monsterPugs[playAreaObj.guid].pugType=="red" or monsterPugs[playAreaObj.guid].pugType=="white")) or volkareCityShield==1 then
													if volkareCityShield==1 then volkareCityShield=0 end
													monsters.extra.shieldsThere=monsters.extra.shieldsThere+1
													dropShield(location, true)
												end
											end
										end
										--count volkares army defeat
										if cityguid==volkare.model then
											gStates.volkareArmyDefeated=gStates.volkareArmyDefeated+1
											gStates.volkareArmyReduced=true
											if gStates.gameScenario=="Volkare's Quest" and VolkarePaused==false and volkareQuestCheckSkipTurn()==true then VolkarePaused=true end
										end
									end
								end
								--record if ruin is just an offering ruin.
								if monsterPugs[playAreaObj.guid].pugType=="yellow" and monsterPugs[playAreaObj.guid].fame>0 then gStates.crytalRuin=true end
								--Add shields to known victory Locations
								if playAreaObj.is_face_down==false and gStates.druidNightsSummon==nil and (gStates.volkarePursuitEnemies==nil or gStates.volkarePursuitEnemies[playAreaObj.guid]~=true) and (
									(monsterPugs[playAreaObj.guid].pugType=="gray" 	 and turnOrder[gStates.turnNumber].avatarLocation=="keep") or
									(monsterPugs[playAreaObj.guid].pugType=="yellow" and turnOrder[gStates.turnNumber].avatarLocation=="ruin") or
									(monsterPugs[playAreaObj.guid].pugType=="red" 	 and (turnOrder[gStates.turnNumber].avatarLocation=="tomb" or turnOrder[gStates.turnNumber].avatarLocation=="labyrinth" or ((turnOrder[gStates.turnNumber].avatarLocation:sub(1,4)=="city" or turnOrder[gStates.turnNumber].avatarLocation=="Volkare's Camp") and gStates.gameScenario=="The Lost Relic Blitz"))) or
									(monsterPugs[playAreaObj.guid].pugType=="tan" 	 and (turnOrder[gStates.turnNumber].avatarLocation=="maze" or turnOrder[gStates.turnNumber].avatarLocation=="monster den" or turnOrder[gStates.turnNumber].avatarLocation=="dungeon")) or
									(monsterPugs[playAreaObj.guid].pugType=="possessed" and (turnOrder[gStates.turnNumber].avatarLocation=="ziggurat" or turnOrder[gStates.turnNumber].avatarLocation=="pyramid")) or
									(monsterPugs[playAreaObj.guid].pugType=="purple" and (turnOrder[gStates.turnNumber].avatarLocation=="mage tower" or turnOrder[gStates.turnNumber].avatarLocation=="monastery"))) then
									local shieldExists=false
									if turnOrder[gStates.turnNumber].avatarLocation~="ziggurat" and turnOrder[gStates.turnNumber].avatarLocation~="pyramid" and turnOrder[gStates.turnNumber].avatarLocation~="maze" and turnOrder[gStates.turnNumber].avatarLocation~="labyrinth" then
										for _, shield in pairs(getObjectFromGUID(mapArea).getObjects()) do
											if shield.getName()=="Shield" and volkarePursuitShieldRegistered(shield)~=true and math.sqrt(((shield.getPosition()[1]-avatarPos[1])^2)+((shield.getPosition()[3]-avatarPos[3])^2))<1 then
												shieldExists=true
												if (turnOrder[gStates.turnNumber].avatarLocation=="keep" and shield.getDescription()~=turnOrder[gStates.turnNumber].mage) then shield.destruct() shieldExists=false end
												if (turnOrder[gStates.turnNumber].avatarLocation=="dungeon" or turnOrder[gStates.turnNumber].avatarLocation=="tomb") then gStates.shieldsDropped[shield.guid]=true end
												break
											end
										end
									end
									if shieldExists==false then
										if gStates.monsterPlayLocation[playAreaObj.guid]~=nil then
											dropShield(gStates.monsterPlayLocation[playAreaObj.guid], true)
											coralTalesSiteShield(turnOrder[gStates.turnNumber].avatarLocation)
										else
											local shieldPos={avatarPos[1], 2, avatarPos[3]}
											local shieldRotation=nil
											if turnOrder[gStates.turnNumber].avatarLocation=="ziggurat" or turnOrder[gStates.turnNumber].avatarLocation=="pyramid" then
												local floor=nil
												if UI.getAttribute("zigguratPyramidInteractFight1Image", "color")=="Yellow" then floor=1 end
												if UI.getAttribute("zigguratPyramidInteractFight2Image", "color")=="Yellow" then floor=2 end
												if UI.getAttribute("zigguratPyramidInteractFight3Image", "color")=="Yellow" then floor=3 end
												local terrain, _, sitePos=terrainHexAtPosition(avatarPos)
												if terrain~=nil then shieldRotation={0, terrain.getRotation()[2], 0} end
												if floor~=nil then shieldPos=zigguratPyramidFloorPosition(terrain, sitePos or avatarPos, floor) end
											end
											dropShield(shieldPos, true, shieldRotation)
											coralTalesSiteShield(turnOrder[gStates.turnNumber].avatarLocation)
										end
									end
								end
								if playAreaObj.is_face_down==false and monsterPugs[playAreaObj.guid].pugType=="tan" and turnOrder[gStates.turnNumber].avatarLocation=="spawning grounds" then spawningGroundMonstersBeat=spawningGroundMonstersBeat+1 end

								--drop shield for mines liberation and "Life and Death"
								if gStates.gameScenario=="Mines Liberation" or gStates.gameScenario=="Life and Death" or gStates.gameScenario=="The Hidden Valley Blitz" then
									for _, monsters in pairs(gStates.mineMonsterQty) do
										if monsters[playAreaObj.guid]~=nil then
											for monsterGUID, monsterState in pairs(monsters) do
												if monsterGUID~=playAreaObj.guid and monsterState=="dead" then
													dropShield({avatarPos[1], 2, avatarPos[3]}, true)
													break
												end
											end
											break
										end
									end
								end
								objectAvoidance=objectAvoidance+1
								gStates.monsterPerks[playAreaObj.guid]=nil
								discardBag.putObject(playAreaObj)
								break
							end
						end
					end

					--Process and Discard Face up monsters. Horsemen are persistent Custom Tiles, so identify
					--them before any generic rotation-value discard route can mistake them for a normal token.
					if monsterPugs[playAreaObj.guid]~=nil and dragonGroundCleanup~=true and (playAreaObj.is_face_down==false or gStates.monsterPlayLocation[playAreaObj.guid]==nil) then
						if horsemanTokenToName~=nil and horsemanTokenToName[playAreaObj.guid]~=nil then
							againstHorsemenResolveDefeat(playAreaObj,gStates.turnNumber,coopCombatReward)
						elseif playAreaObj.getRotationValues()[2]~=nil then
							discardMonster(playAreaObj, true)
						else--process leaders
							local currentLeader=elementalist
							if playAreaObj.guid==darkCrusader.token then currentLeader=darkCrusader end
							--drop shield(s) on leader disc
							for b=1, gStates.leaderOverkill, 1 do
								local obj=getObjectFromGUID(currentLeader.disc)
								local hexRotationRad=math.rad(-1*(-120+tonumber(30*(gStates.elementalistLevel-gStates.leaderReduction-(b-1)))))
								if playAreaObj.guid==darkCrusader.token then hexRotationRad=math.rad(-1*(-120+tonumber(30*(gStates.darkCrusaderLevel-gStates.leaderReduction-(b-1))))) end
								local location={obj.getPosition()[1]+(math.cos(hexRotationRad)*2.9), 2+(b*1.5), obj.getPosition()[3]+(math.sin(hexRotationRad)*2.9)}
								dropShield(location, false)
							end
							--Record damage to the faction leader, but during a cooperative assault do not move its
							--actual level marker/state until every participating player has finished combat.
							gStates.leaderReduction=gStates.leaderReduction+gStates.leaderOverkill
							local leaderStartingLevel=gStates.elementalistLevel
							if playAreaObj.guid==darkCrusader.token then leaderStartingLevel=gStates.darkCrusaderLevel end
							local leaderDefeatedNow=gStates.leaderReduction>=leaderStartingLevel
							gStates.leaderOverkill=1
							if gStates.coopAssaultPhase=="combat" and coopAssaultTargetType()=="leader" then
								--The next participant already has a planning clone. Swap the real leader into that copy's
								--current position so the combat controls move with the real token. If the leader was fully
								--marked, remove every remaining preview because later participants no longer face it.
								if coopAssaultPendingCombat()==true and leaderDefeatedNow==false then
									local nextPlayer=nextTurnMerged("nextMage")
									promoteCoopLeaderPreview(nextPlayer, playAreaObj)
								else
									clearCoopLeaderPreviewClones()
									if gStates.monsterPlayLocation[playAreaObj.guid]~=nil then playAreaObj.setPositionSmooth(gStates.monsterPlayLocation[playAreaObj.guid]) end
								end
							else
								--Solo/non-co-op leader combat keeps the existing immediate resolution.
								local currenLeaderLevel=math.max(0, leaderStartingLevel-gStates.leaderReduction)
								if playAreaObj.guid==darkCrusader.token then gStates.darkCrusaderLevel=currenLeaderLevel else gStates.elementalistLevel=currenLeaderLevel end
								gStates.leaderReduction=0
								if currenLeaderLevel==0 then
									getObjectFromGUID(trashCan).putObject(playAreaObj)
									gStates.cityMonsterQty[currentLeader.terrainHex][currentLeader.token]="dead"
									getObjectFromGUID(currentLeader.disc).setCustomObject({image=leaderData[currentLeader.terrainHex]["dead"].discImg})
									getObjectFromGUID(currentLeader.disc).reload()
									Wait.time(function()
										for monsterGUID, state in pairs(gStates.cityMonsterQty[currentLeader.terrainHex]) do
											if getObjectFromGUID(monsterGUID)~=nil and getObjectFromGUID(monsterGUID).getRotationValues()[2]~=nil then discardMonster(getObjectFromGUID(monsterGUID), false) end
										end
									end, 2)
								else
									playAreaObj.setPositionSmooth(gStates.monsterPlayLocation[playAreaObj.guid])
									Wait.frames(function()
										getObjectFromGUID(currentLeader.disc).setCustomObject({image=leaderData[currentLeader.terrainHex][currenLeaderLevel].discImg})
										getObjectFromGUID(currentLeader.disc).reload()
										getObjectFromGUID(currentLeader.token).setCustomObject({image=leaderData[currentLeader.terrainHex][currenLeaderLevel].tokenImg})
										getObjectFromGUID(currentLeader.token).setName(currentLeader==darkCrusader and "Dark Crusader Leader Level "..currenLeaderLevel or "Elementalist Leader Level "..currenLeaderLevel)
										getObjectFromGUID(currentLeader.token).reload()
										monsterPugs[currentLeader.token]=leaderData[currentLeader.terrainHex][currenLeaderLevel].abilities
									end, 100)
								end
							end
						end
					end

					--Discard Reward Tokens
					local tokens={["Dark Crusader Reward"]=GUID.bag.discard.darkReward, ["Elementalist Reward"]=GUID.bag.discard.elementalistReward, ["Apocalypse Cult Reward"]=GUID.bag.discard.apocReward, ["Council of the Void Reward"]=GUID.bag.discard.councilReward}
					if tokens[playAreaObj.getGMNotes()]~=nil then
						playAreaObj.setRotation({0, 180, 180})
						getObjectFromGUID(tokens[playAreaObj.getGMNotes()]).putObject(playAreaObj)
					end

					--Discard or delete players cards
					if playAreaObj.type=="Card" then
						--Check for and leave banner Cards
						local found=false
						if gameCards[playAreaObj.guid]~=nil and gameCards[playAreaObj.guid].full~=nil then gStates.bannercard[playAreaObj.guid]="played" found=true end
						--Steady Tempo stays in the play area during cleanup so the player can choose
						--Discard / bottom of Deed deck / top of Deed deck. Cover both physical copies.
						if (playAreaObj.guid=="1f362f" or playAreaObj.guid=="6e506a") and cardEffectIsVertical(playAreaObj)==true then
							found=true gStates.turnForfeited=false
							if playAreaObj.is_face_down==false then steadyTempoPrepare(playAreaObj, gStates.turnNumber) end
						elseif playAreaObj.guid=="085e69" or playAreaObj.guid=="7ebe5e"
							and playAreaObj.getRotation()[2]>175 and playAreaObj.getRotation()[2]<185
							and (playAreaObj.is_face_down==false) then found=true gStates.turnForfeited=false end--Mysterious Box and Crystal Joy
						if playAreaObj.getDescription()=="Quest" then found=true gStates.turnForfeited=false end
						--Check if the card is registered to the player and place on deed pile
						if found==false then
							gStates.turnForfeited=false
							--Delete face down cards
							if playAreaObj.is_face_down==true then
								getObjectFromGUID(trashCan).putObject(playAreaObj)
							else
								for x=1,#turnOrder[gStates.turnNumber].deadDeckInventory, 1 do
									if playAreaObj.guid==turnOrder[gStates.turnNumber].deadDeckInventory[x] then
										if gStates.timeBending=="Started" and gStates.turnNumber==gStates.realTurn then
											if playAreaObj.guid==timeBendingGUID then
												gStates.timeBendingRemovedSeat=turnOrder[gStates.turnNumber].seatPos
												getObjectFromGUID(trashCan).putObject(playAreaObj)
												broadcastToAll("Time Bend Left Play", positionToColor(gStates.turnNumber))
											else
												playAreaObj.setRotation({0.0, 180.0, 0.0})
												playAreaObj.setPosition({(turnOrder[gStates.turnNumber].seatPos*40)-100, 4, -48.40})
											end
										else
											if cardDestination==nil then
												playAreaObj.setRotation({0.0, 180.0, 0.0})
												playAreaObj.setPosition({(turnOrder[gStates.turnNumber].seatPos*40)-110.54, 1.12, -43.20})
												cardDestination=playAreaObj
											else
												playAreaObj.setPosition({playAreaObj.getPosition()[1], 1.9, playAreaObj.getPosition()[3]})
												cardDestination=cardDestination.putObject(playAreaObj)
											end
										end
										break
									end
								end
							end
						end
					end

					--Cleanup Skills
					if skillTokens[playAreaObj.guid]~=nil then
						--Flip all per round skills in current play area face down
						if skillTokens[playAreaObj.guid].skillType=="Round" then
							getObjectFromGUID(playAreaObj.guid).setRotationSmooth({0.0, 180.0, 180.0})
						end
						--Return all non coop and comp skills to their recorded position
						if skillTokens[playAreaObj.guid].skillType=="Round" or skillTokens[playAreaObj.guid].skillType=="Turn" then
							getObjectFromGUID(playAreaObj.guid).setPositionSmooth({gStates.mageSkills[playAreaObj.guid][1], 1.5, gStates.mageSkills[playAreaObj.guid][3]})
						end
						--stop motivation Skills
						if gStates.mageSkills[playAreaObj.guid]~=nil and gStates.motivationSkill[playAreaObj.guid]~=nil then
							gStates.motivationSkill[playAreaObj.guid].state="used"
						end
						--increment master of Chaos
						if playAreaObj.guid=="1ff34f" then
							gStates.masterOfChaos=gStates.masterOfChaos+1
							if gStates.masterOfChaos==7 then gStates.masterOfChaos=1 end
							getObjectFromGUID("1ff34f").setDescription(masterOfChaosData[gStates.masterOfChaos].description)
							turnOrder[gStates.turnNumber].masterOfChaos="incrementented in turn"
						end
						--Coop and Comp Skills
						if skillTokens[playAreaObj.guid].skillType=="Coop" or skillTokens[playAreaObj.guid].skillType=="Comp" then
							local paused=gStates.coopCompSkillPaused~=nil and gStates.coopCompSkillPaused[playAreaObj.guid]~=nil
							local playedBeforeLock=gStates.coopCompSkillLegalThisRound~=nil and gStates.coopCompSkillLegalThisRound[playAreaObj.guid]==true
							local inRotation=gStates.doingTheRounds[playAreaObj.guid]~=nil and paused==false
							if paused==false and coopCompSkillPlayLocked()==true and playedBeforeLock==false and inRotation==false then paused=pauseLateCoopCompSkill(playAreaObj.guid, gStates.turnNumber) end
							if paused==false then
								if gStates.doingTheRounds[playAreaObj.guid]==nil then
									--The real Coop skill starts its circuit; a Comp skill creates reminders and only its owner-reward exceptions stay played.
									gStates.doingTheRounds[playAreaObj.guid]=gStates.turnNumber
									if skillTokens[playAreaObj.guid].skillType=="Comp" then createCompetitiveSkillReminders(playAreaObj.guid, gStates.turnNumber)
									else
										if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
										gStates.doingTheRoundsVisited[playAreaObj.guid]={[gStates.turnNumber]=true}
									end
								elseif skillTokens[playAreaObj.guid].skillType=="Coop" then
									--A Coop skill already doing the rounds has now been used, so its circuit ends here.
									gStates.doingTheRounds[playAreaObj.guid]=nextTurnMerged("nextMageSkipDummy")
								end
							end
						end
					end
				end, tokenWait+3)
				tokenWait=tokenWait+3
			end

			--Drop Avatar after a pause. A returning undefeated monster can still be smooth-moving when the
			--two-second settle check expires (Quest failures make this common). The old wait had no timeout
			--handler, so the avatar could remain locked at +2 height forever. Run the same finish routine on
			--either a normal settle or timeout.
			Wait.frames(function()
				local avatarDropFinished=false
				local function finishAvatarDrop()
					if avatarDropFinished==true then return end
					avatarDropFinished=true
					--place shield or replenish monster in spawning grounds
					if turnOrder[cleanupPlayer]~=nil and turnOrder[cleanupPlayer].avatarLocation=="spawning grounds" then
						if spawningGroundMonstersBeat==2 then dropShield({avatarPos[1], 2, avatarPos[3]}, true) coralTalesSiteShield("spawning grounds") end
						if spawningGroundMonstersReturned==1 then
							local newMonster=getObjectFromGUID(monsterPiles.tan).takeObject({position={avatarPos[1]+0.22, 2.12, avatarPos[3]}, smooth=false})
							gStates.monsterPlayLocation[newMonster.guid]={avatarPos[1]+0.22, 2.12, avatarPos[3]}
						end
					end
					local horsemenReturn=againstHorsemenFinishSoloAssault(cleanupPlayer)
					if horsemenReturn~=nil then
						if avatarModel~=nil then
							avatarPos={horsemenReturn[1],horsemenReturn[2],horsemenReturn[3]}
						else
							local horsemenAvatar=coopAssaultAvatarObject(cleanupPlayer)
							if horsemenAvatar~=nil then horsemenAvatar.setPositionSmooth(horsemenReturn) end
						end
					end
					if avatarModel~=nil then
						avatarModel.setLock(false)
						avatarModel.setPositionSmooth({avatarPos[1], avatarPos[2]+1.0, avatarPos[3]})
					end
				end
				Wait.condition(finishAvatarDrop, function()
					if tokenRaised<=0 or (lastObject~=nil and lastObject.resting~=true) then return false end
					local pendingDragonAttack=gStates~=nil and gStates.apocalypseDragonPendingAttack or nil
					local destroyedGUID=pendingDragonAttack~=nil and pendingDragonAttack.destroyedSiteTokenGUID or nil
					if destroyedGUID~=nil then
						local destroyed=getObjectFromGUID(destroyedGUID)
						if destroyed==nil then return false end
						local destroyedPos=destroyed.getPosition()
						if math.abs(destroyedPos[2]-1.13)>0.05 then return false end
					end
					return true
				end, 5, finishAvatarDrop)
			end, tokenWait+3)

			--Adjust hand size and Check for scenario completion to Start the final round of turns.
			--A completed City assault has just changed both monster state and physical shields. Rebuild ownership once,
			--at this settled cleanup boundary, before fakeDropAvatar reads Lead/Assist for the new hand limit.
			--Other cleanup only needs the cheaper defeat-state refresh; co-op combat rebuilds ownership in its reward phase.
			Wait.frames(function() Wait.condition(function()
				if gStates.coopAssaultPhase~="combat" and (turnOrder[gStates.turnNumber].avatarLocation:sub(1,4)=="city" or turnOrder[gStates.turnNumber].avatarLocation:sub(1,6)=="raised") then cityBeatCheck()
				else refreshCityDefeatState() end
		 		fakeDropAvatar()
				--Check for scenario completion to Start the final round of turns.
				if gStates.endGameAchieved=="false" and gStates.tacticShown==false then
					--local gladeCount=0
					local dungeonCount=0
					local dungeonHexCount=0
					local mineCount=0
					local mineTileCount=0
					local graveYardCount=0
					local graveYardTileCount=0
					local relicCount=0
					local floorCount=0
					local zigPyrBeat={}
					if gStates.gameScenario=="Mines Liberation" or gStates.gameScenario=="The Realm of the Dead Blitz" or gStates.gameScenario=="Dungeon Lords" or gStates.gameScenario=="The Lost Relic Blitz" or gStates.gameScenario=="Against the Apocalypse Blitz" then
						local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
						table.sort(objectsInPlay, function (k1, k2) return k1.getPosition()[2]>k2.getPosition()[2] end)
						for _, playAreaObject in pairs(objectsInPlay) do
							--Count Shield tokens
							if playAreaObject.getName()=="Shield" and volkarePursuitShieldRegistered(playAreaObject)~=true then
								local found=false
								local shieldPos=playAreaObject.getPosition()
								local locatedTerrain, _, _, locatedFeature=terrainHexAtPosition(shieldPos, objectsInPlay)
								for _, terTile in pairs(objectsInPlay) do
									local tilePos=terTile.getPosition()
									local shieldToTileDist=math.sqrt(((shieldPos[1]-tilePos[1])^2)+((shieldPos[3]-tilePos[3])^2))
									if terTile==locatedTerrain then
										found=true
										if locatedFeature=="ziggurat" or locatedFeature=="pyramid" then floorCount=floorCount+1 zigPyrBeat[terTile.guid]=true end
										if locatedFeature=="dungeon" or locatedFeature=="tomb" then dungeonCount=dungeonCount+1 end
										if locatedFeature=="mine" then mineCount=mineCount+1 end
										if locatedFeature~=nil and (locatedFeature:sub(1,4)=="city" or locatedFeature=="Volkare's Camp") and gStates.gameScenario=="The Lost Relic Blitz" then relicCount=relicCount+1 end
									end
									if shieldToTileDist<1 and terTile.getName()=="GraveYard" then graveYardCount=graveYardCount+1 found=true end
									if found==true then break end
								end
							end
							local mineTiles={[GUID.tile.core02]=2, [GUID.tile.core04]=2, [GUID.tile.core03]=2, [GUID.tile.country03]=2, [GUID.tile.country06]=2, [GUID.tile.country02]=2, [GUID.tile.country05]=2, [GUID.tile.city08]=2, [GUID.tile.country13]=2, [GUID.tile.country14]=2, [GUID.tile.country15]=2, [GUID.tile.country17]=2, [GUID.tile.core10]=2}
							if terrainTiles[playAreaObject.guid]~=nil and mineTiles[playAreaObject.guid]~=nil then mineTileCount=mineTileCount+1 end
							if playAreaObject.getName()=="GraveYard" then graveYardTileCount=graveYardTileCount+1 end
							local dungeonTombTiles={[GUID.tile.core01]=2, [GUID.tile.core03]=2, [GUID.tile.country07]=2, [GUID.tile.country09]=2}
							if terrainTiles[playAreaObject.guid]~=nil and dungeonTombTiles[playAreaObject.guid]~=nil then dungeonHexCount=dungeonHexCount+1 end
							if playAreaObject.getName()=="Secret Tomb" or playAreaObject.getName()=="Secret Dungeon" then dungeonHexCount=dungeonHexCount+1 end
						end
					end
					local zigPyrBeatCount=0
					for a, b in pairs(zigPyrBeat) do zigPyrBeatCount=zigPyrBeatCount+1 end
					local restoredCount=0
					local playerZones={"13f39d", "5bb87a", "621d88", "2936ad"}--Crystal inventory
					for _, zone in pairs(playerZones) do
						for _, destroyed in pairs(getObjectFromGUID(zone).getObjects()) do
							if destroyed.getGMNotes()=="Destroyed" then restoredCount=restoredCount+1 end
						end
					end
					local allRituals=true
					if gStates.gameScenario=="Druid Nights" then
						for _, playerDetails in pairs(turnOrder) do
							if playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.druidNightsFinalRitual~=true then allRituals=false break end
						end
					end
					local cardInHand=false
					if gStates.gameScenario=="Quest for the Golden Grail" then
						for _, handobject in pairs(getObjectFromGUID(handZones[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
							if handobject.guid=="085e59" then cardInHand=true break end
						end
					end
					local volkareBeaten=true
					if getObjectFromGUID(gStates.volkareModel)~=nil then
						for _, state in pairs(gStates.cityMonsterQty[volkare.model]) do
							if state=="alive" then volkareBeaten=false break end
						end
						if volkareBeaten==true then	getObjectFromGUID(trashCan).putObject(getObjectFromGUID(gStates.volkareModel)) end
					end
					if ((gStates.gameScenario=="Conquest" or gStates.gameScenario=="Conquest Blitz" or gStates.gameScenario=="First Conquest" or gStates.gameScenario=="Fast Forwarded Conquest") and gStates.defeatedCities.amount==gStates.cityTiles) or
						((gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") and volkareBeaten==true) or
						(gStates.gameScenario=="First Reconnaissance" and #gStates.citiesPlayed>=1) or
						(gStates.gameScenario=="Ultimate Conquest" and gStates.defeatedCities.amount==gStates.cityTiles and (gStates.removeShadesOfTezlaMonsters==true or (gStates.removeShadesOfTezlaMonsters~=true and gStates.defeatedFaction==2))) or
						(gStates.gameScenario=="The Hidden Valley Blitz" and gStates.defeatedFaction==1) or
						(gStates.gameScenario=="Mines Liberation" and getObjectFromGUID(GUID.bag.terrain.stack).getQuantity()==0 and mineCount==mineTileCount) or
						(gStates.gameScenario=="Dungeon Lords" and getObjectFromGUID(GUID.bag.terrain.stack).getQuantity()==0 and dungeonCount==dungeonHexCount-2) or
						(gStates.gameScenario=="The Realm of the Dead Blitz" and gStates.defeatedFaction==1 and graveYardCount==graveYardTileCount) or
						(gStates.gameScenario=="The Lost Relic Blitz" and relicCount==gStates.cityTiles) or
						(gStates.gameScenario=="Quest for the Golden Grail" and turnOrder[gStates.turnNumber].avatarLocation=="portal" and cardInHand==true) or
						(gStates.gameScenario=="The Gauntlet" and gStates.theGauntletArtifactClaimed==true) or
						(gStates.gameScenario=="Druid Nights" and gStates.currentRound==gStates.rounds and allRituals==true) or
						(gStates.gameScenario=="Life and Death" and gStates.defeatedFaction==2) or
						(gStates.gameScenario=="Against the Horsemen Blitz" and againstHorsemenAllDefeated()==true) or
						(gStates.gameScenario=="Against the Dragon Blitz" and apocalypseDragonColoredHeadsDefeated()==true) or
						(gStates.gameScenario=="Against the Apocalypse Blitz" and ((zigPyrBeatCount==2 and gStates.playerCount==1) or (zigPyrBeatCount==3 and gStates.playerCount~=1)) and
							((gStates.coop==1 and gStates.playerCount~=1 and restoredCount>=gStates.playerCount+2 and floorCount>=gStates.playerCount+2) or
							(gStates.coop==1 and gStates.playerCount==1 and restoredCount>=2 and floorCount>=2) or
							(gStates.coop==0 and restoredCount>=gStates.playerCount+1 and floorCount>=gStates.playerCount+1))) then
						if gStates.endGameAchieved=="false" then
						if gStates.coopAssaultPhase=="combat" then gStates.coopAssaultScenarioEndPending=true else scenarioEnd() end
					end
					end
					--Judge Volkare's Return city defense only when the entire defense is complete; co-op kills are combined across all defenders.
					local volkareReturnDefense=gStates.positionMageKnight[5]=="Volkare" and gStates.volkareState=="Attacking City" and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz")
					local volkareReturnDefenseFinished=volkareReturnDefense and (gStates.coopAssaultPhase~="combat" or coopAssaultPendingCombat()==false)
					if volkareReturnDefenseFinished then
						if gStates.volkareArmyDefeated<gStates.playerCount then
							gStates.volkareCityDefenseMove=nil
							getObjectFromGUID(trashCan).putObject(getObjectFromGUID(gStates.volkareModel))
							gStates.volkareWon=true
							mainUIUpdate("Volkare Won")
						else volkareReturnCityDefenseMove() end
					end
					--Combat Complete is the only confirmation during the combat stage. Advance as soon as cleanup is finished.
					if gStates.coopAssaultPhase=="combat" then
						Wait.frames(function()
							if gStates.coopAssaultPhase=="combat" and gStates.preEndTurn==true then endTurn(player, "-1", "CoopCombatComplete") end
						end, 2)
					end
				end
		 	end, function() return lastObject==nil or lastObject.resting end, 2, function()
				if gStates.coopAssaultPhase=="combat" and gStates.preEndTurn==true then endTurn(player, "-1", "CoopCombatComplete") end
			end) end, tokenWait+50)

			--Manipulate skills
			local nextPlayer=nextTurnMerged("nextMageSkipDummy")
			local count=0
			local keepSafe={}
			for skillGUID, Skillzone in pairs(sharedSkillAboveZone) do
				if getObjectFromGUID(skillGUID)~=nil then
					getObjectFromGUID(Skillzone).setPosition({getObjectFromGUID(skillGUID).getPosition()[1], 1.4, getObjectFromGUID(skillGUID).getPosition()[3]})
				end
			end

			--Skills doing the rounds
			Wait.frames(function()
				registerDetachedCoopCompSkills(gStates.turnNumber)
				for skillGUID, skillDetails in pairs(skillTokens) do
					if getObjectFromGUID(skillGUID)~=nil then
						--Flip up per turn skills
						if skillDetails.skillType=="Turn" and getObjectFromGUID(skillGUID).is_face_down==true then getObjectFromGUID(skillGUID).flip() end

						--Comp and Unplayed coop skills that are doing the rounds.
						if gStates.doingTheRounds[skillGUID]~=nil and (gStates.coopCompSkillPaused==nil or gStates.coopCompSkillPaused[skillGUID]==nil) then
							data=doingTheRounds(skillGUID, nextPlayer, count)
							count=data[2]
							for saveObjGuid, _ in pairs(data[1]) do
								keepSafe[saveObjGuid]=true
							end
						end
					end
				end

				if coopCompSkillPlayLocked()==true then refreshCoopCompSkillXs() end

				--Delete Crystals and wound tokens Unit Wound
				for _, playAreaObj in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
					if (playAreaObj.type=="Figurine" and keepSafe[playAreaObj.guid]~=true)
					or playAreaObj.getName()=="Blue Defender Bonus Reminder" or playAreaObj.getName()=="Green Defender Bonus Reminder"
					or playAreaObj.getName()=="White Defender Bonus Reminder" or playAreaObj.getName()=="Red Defender Bonus Reminder" then
						getObjectFromGUID(trashCan).putObject(playAreaObj)
					end
				end
			end, tokenWait+3)

			--Remove crystals and dice used to power Units
			local crystalsToDestroy={}
			local unitAreaObjects=getObjectFromGUID(playerUnitAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()
			for _, unitAreaObj in pairs(unitAreaObjects) do
				--Return any Mana dice
				if unitAreaObj.type=="Dice" then
					returnDice(unitAreaObj.guid)
				end
				--A Coop/Comp skill used on a Unit still follows the normal doing-the-rounds rules.
				--This mirrors the play-area handling so future Unit-affecting round skills are not mistaken for reminders.
				if skillTokens[unitAreaObj.guid]~=nil and (skillTokens[unitAreaObj.guid].skillType=="Coop" or skillTokens[unitAreaObj.guid].skillType=="Comp") then
					local paused=gStates.coopCompSkillPaused~=nil and gStates.coopCompSkillPaused[unitAreaObj.guid]~=nil
					local playedBeforeLock=gStates.coopCompSkillLegalThisRound~=nil and gStates.coopCompSkillLegalThisRound[unitAreaObj.guid]==true
					local inRotation=gStates.doingTheRounds[unitAreaObj.guid]~=nil and paused==false
					if paused==false and coopCompSkillPlayLocked()==true and playedBeforeLock==false and inRotation==false then paused=pauseLateCoopCompSkill(unitAreaObj.guid, gStates.turnNumber) end
					if paused==false then
						if gStates.doingTheRounds[unitAreaObj.guid]==nil then
							gStates.doingTheRounds[unitAreaObj.guid]=gStates.turnNumber
							if skillTokens[unitAreaObj.guid].skillType=="Comp" then createCompetitiveSkillReminders(unitAreaObj.guid, gStates.turnNumber)
							else
								if gStates.doingTheRoundsVisited==nil then gStates.doingTheRoundsVisited={} end
								gStates.doingTheRoundsVisited[unitAreaObj.guid]={[gStates.turnNumber]=true}
							end
						elseif skillTokens[unitAreaObj.guid].skillType=="Coop" then
							--A Coop skill already doing the rounds has now been used, so its circuit ends here.
							gStates.doingTheRounds[unitAreaObj.guid]=nextTurnMerged("nextMageSkipDummy")
						end
					end
				end
				--Return ordinary skill tokens used as Unit reminders to their recorded Skill positions.
				--Bonds of Loyalty stays in Norowas' Unit Area as a Command token; Coop/Comp skills registered above keep rotating.
				if unitAreaObj.guid~="f30dd4" and skillTokens[unitAreaObj.guid]~=nil and gStates.mageSkills[unitAreaObj.guid]~=nil and gStates.doingTheRounds[unitAreaObj.guid]==nil then
					local skillHome=gStates.mageSkills[unitAreaObj.guid]
					if skillHome[1]~=nil and skillHome[2]~=nil and skillHome[3]~=nil then
						unitAreaObj.setPositionSmooth({skillHome[1], skillHome[2], skillHome[3]})
						unitAreaObj.setRotationSmooth({0, 180, 0})
					end
				end
				--Record Crystals in the Unit Area. Registered skill tokens are never disposable crystals.
				if unitAreaObj.type=="Figurine" and unitAreaObj.getGMNotes()~="Unit Wound" and skillTokens[unitAreaObj.guid]==nil and monsterPugs[unitAreaObj.guid]==nil then crystalsToDestroy[#crystalsToDestroy+1]=unitAreaObj.guid end
			end
			for _, crystals in pairs(crystalsToDestroy) do
				local crystal=getObjectFromGUID(crystals)
				local delete=true
				if crystal~=nil then
					local nearestUnit, distance=unitLayoutNearestUnit(unitAreaObjects,crystal.getPosition()[1])
					if nearestUnit~=nil and distance<=1.5 and (nearestUnit.guid=="0a2e0b" or nearestUnit.guid=="d8e49b") then delete=false end
				end
				if delete==true and crystal~=nil then getObjectFromGUID(trashCan).putObject(crystal) end
			end

			--Fame and Reputation are held until every participant has finished a co-op assault.
			if gStates.coopAssaultPhase~="combat" then applyPlayerFameReputation(gStates.turnNumber) end

			--Use the player whose cleanup started, not whatever turn happens to be current when
			--this delayed callback fires. This prevents two Mage Knights being left on the portal.
			if coopAssaultVirtualPlayer(cleanupPlayer)==false then portalSwap("endOfTurn", cleanupPlayer) end
		end, tokenWait)
	end
end

--Deals player Hand then increments turn
function __endTurn_raw(player, mouseButton, id, rewindReady)
	if legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true then --and slightPause==false
		local rewardSeat=turnOrder[gStates.turnNumber].seatPos
		local questRewardPending,_,questRewardAction=apocalypseQuestRewardCompletionPendingForPlayer(gStates.turnNumber)
		if questRewardPending==true then
			apocalypseQuestRefreshOfferButtons()
			rewardReminderCameraFocus(player.color,"questView")
			local questGateMessage=(questRewardAction=="Fail" or questRewardAction=="CompleteOrFail") and "Complete/Fail the Quest First" or "Complete/Progress the Quest First"
			broadcastToColor(questGateMessage,player.color,warningColor)
			if rewindReady==true then rewindTransactionFinish("End turn") end
			return
		end
		if steadyTempoPendingForSeat~=nil and steadyTempoPendingForSeat(rewardSeat)==true then
			steadyTempoRefreshAll() steadyTempoUpdateRewardGate(rewardSeat)
			broadcastToAll("Resolve Steady Tempo before claiming rewards.", positionToColor(gStates.turnNumber))
			if rewindReady==true then rewindTransactionFinish("End turn") end
			return
		end
		if gStates.mineClaimPending~=nil then
			broadcastToColor("Resolve the pending crystal choice before proceeding to the next player.", player.color, warningColor)
			if rewindReady==true then rewindTransactionFinish("End turn") end
			return
		end
		if rewindReady~=true and rewindTransactionOwnerActive("End turn")==true then return end
		if gStates.coopAssaultPhase=="rewards" then
			if gStates.skillButtons==0 then
				if rewindReady~=true then
					rewindTransactionStart(function() endTurn(player,mouseButton,id,true) end,"End turn")
					return
				end
				local function finishCoopRewardAdvance()
					advanceCoopRewardPhase()
					Wait.frames(function() rewindTransactionFinish("End turn") end,10)
				end
				--Co-op hand draw is delayed until Rewards Claimed, after the city result has set the final hand limit.
				if (gStates.timeBending~="Started" or gStates.turnNumber~=gStates.realTurn) and turnOrder[nextTurnMerged("nextMage")].endCalled~=true and turnOrder[nextTurnMerged("nextMageSkipDummy")].endCalled~=true then drawUpTo(player, "-1", "DrawHand") end
				--Don't switch reward players while a visible Deed transfer is still travelling or queued.
				if cardClaim==true or deedTransferAnyBusy()==true then
					Wait.condition(finishCoopRewardAdvance,function() return cardClaim~=true and deedTransferAnyBusy()~=true end,10,finishCoopRewardAdvance)
				else
					finishCoopRewardAdvance()
				end
			else
				if rewindReady==true then rewindTransactionFinish("End turn") end
				rewardReminderCameraFocus(player.color,"offerView")
				broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} needs to select a skill before claiming these rewards.{ru} должен выбрать Навык перед получением наград.{zh-cn}需要先选择一项技能再领取奖励.{ko}: 보상을 받기 전에 스킬을 선택하세요.{es} necesita seleccionar una habilidad antes de reclamar estas recompensas.{fr} doit sélectionner une compétence avant de réclamer ces récompenses.{pt-br} precisa selecionar uma habilidade antes de pegar estas recompensas.{de} muss eine Fertigkeit auswählen, bevor diese Belohnungen beansprucht werden."}), warningColor)
			end
			return
		end
		--slightPause=true
		if gStates.skillButtons==0 then--must choose from offered skill to proceed
			if rewindReady~=true then
				rewindTransactionStart(function() endTurn(player,mouseButton,id,true) end,"End turn")
				return
			end

			apocalypseQuestMineDoomEndTurnCleanup(gStates.turnNumber)
			apocalypseQuestClearMarkerHighlights()
			UI.setAttribute("NightTacticSix", "active", "false")
			UI.setAttribute("zigguratPyramidInteract", "active", "false")
			gStates.preEndTurn=false
			gStates.levelingUp=false
			gStates.crytalRuin=false
			gStates.volkareArmyReduced=false
			turnOrder[gStates.turnNumber].fameGain=0 gStates.gainList={}
			turnOrder[gStates.turnNumber].repGain=0
			turnOrder[gStates.turnNumber].combatIconHide="None"
			turnOrder[gStates.turnNumber].pillagedVillage=false
			gStates.skippedMove=false
			gStates.druidNightsSummon=nil
			gStates.druidNightsCrystalReward=nil
			gStates.locationPlace={}
			gStates.summonStates={}
			gStates.shieldsDropped={}
			if gStates.endGameAchieved=="started" then gStates.endGameAchieved="true" end
			--Update all pursuing monsters, new deployed or stunned will be on the move.
			if gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]~=nil then
				for guid, monster in pairs(gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]) do
					if getObjectFromGUID(guid)~=nil then
						local monsterObj=getObjectFromGUID(guid)
						if monster.state=="Deployed" and monsterObj.is_face_down==true then monsterObj.flip() end
						if monster.state=="Stunned" then monster.stunned=true monster.state="Deployed" else if monster.state=="Deployed" then monster.stunned=nil setPursuitStunnedImage(monsterObj, false) end monster.state="Pursuing" end
						monster.location={monsterObj.getPosition()[1], monsterObj.getPosition()[2], monsterObj.getPosition()[3]}
						gStates.monsterPlayLocation[guid]=monster.location
					end
				end
				--delete the help arrows
				for guid, _ in pairs(gStates.arrowDelete) do
					if getObjectFromGUID(guid)~=nil then getObjectFromGUID(guid).destruct() end
				end
				gStates.arrowDelete={}
			end

			if (gStates.timeBending~="Started" or gStates.turnNumber~=gStates.realTurn) and gStates.coopAssaultPhase~="combat" then
				--Normal turns draw here. Co-op assault hands wait until that player clicks Rewards Claimed.
				if turnOrder[nextTurnMerged("nextMage")].endCalled~=true and turnOrder[nextTurnMerged("nextMageSkipDummy")].endCalled~=true then
					drawUpTo(player, "-1", "DrawHand")
				end
			end

			--remove any wound cards played because of glade, regardless of which face is showing.
			for _, playAreaObj in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
				if playAreaObj.getGMNotes()=="Wound" then
					getObjectFromGUID(trashCan).putObject(playAreaObj)
				end
			end

			--re-enable night tactic six buttons
			if turnOrder[gStates.turnNumber].tactic==6 and gStates.tacticSixState~="Used" and gStates.dayRound==false then
				gStates.tacticSixState="notClaimed"
			end

			--Update Motivation Skill status
			for a, stats in pairs(gStates.motivationSkill) do
				if stats.state=="used" then stats.state="deactive" end
			end

			--During a co-op Dragon assault this player's physical head tokens have now been read and
			--returned. Mark their combat complete before asking whether another assaulter remains.
			if gStates.coopAssaultPhase=="combat" and coopAssaultTargetType()=="dragon" and apocalypseDragonGroundPlayerFinished~=nil then apocalypseDragonGroundPlayerFinished(gStates.turnNumber) end
			--During a co-op assault finish every combat before starting the reward queue.
			if gStates.coopAssaultPhase=="combat" and coopAssaultPendingCombat()==false then
				startCoopRewardPhase()
			elseif gStates.volkareMovementStepPending==true and gStates.volkareMovementPaused==true and gStates.volkarePendingCombatMage==turnOrder[gStates.turnNumber].mage then
				--A first-half Volkare attack consumed this Mage Knight's turn. Release the second movement only now, after combat/rewards are finished.
				gStates.volkareMovementPaused=false
				gStates.volkareAdvanceAfterMovement=true
				gStates.volkarePendingCombatMage=nil
			elseif againstDragonFullAttendInProgress~=nil and againstDragonFullAttendInProgress(gStates.turnNumber)==true then
				--The target just took their normal turn in advance. Resolve the airborne attack and release
				--the suspended Dragon turn directly; do not return to a Dragon Processed interface.
				againstDragonFinishAttackForPlayer(gStates.turnNumber,true)
			elseif apocalypseDragonGroundCombatForPlayer~=nil and apocalypseDragonGroundCombatForPlayer(gStates.turnNumber)==true then
				--Dragon levels only move after the whole ground combat is over. The pre-end-turn pass has
				--already read every physical head token and placed the player's level-marking Shields.
				apocalypseDragonFinalizeGroundCombat(gStates.turnNumber)
				nextTurnMerged("incrementTurn")
			else
				volkareQuestCombatWithdrawalReminder(turnOrder[gStates.turnNumber].mage)
				nextTurnMerged("incrementTurn")
			end
			recourceTrackerReset()
			if gStates.coopAssaultPhase~="combat" then claimButtonRefresh() end
			addAvatarButtons()
			Wait.frames(function() rewindTransactionFinish("End turn") end,10)
		else
			if rewindReady==true then rewindTransactionFinish("End turn") end
			rewardReminderCameraFocus(player.color,"offerView")
			broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} needs to select a skill before you can end their Turn.{ru} должен выбрать Навык перед окончанием хода.{zh-cn}需要先选择一项技能, 然后才能结束他们的回合. {ko}: 차례를 넘기기 전에 스킬을 선택하세요.{es} necesita seleccionar una habilidad antes de que pueda finalizar su turno.{fr} doit sélectionner une compétence avant de pouvoir terminer son tour.{pt-br} precisa selecionar uma habilidade antes que você possa encerrar seu turno.{de} muss eine Fertigkeit wählen, bevor du seinen Zug beenden kannst."}), warningColor)
		end
	end
end

--The first finish-line event owns the final-turn circuit.
--End of Round: stop when play returns to the caller; the caller gets no extra turn.
--Player victory: return to the victory player, give them one final turn, then stop.
--Volkare victory: Volkare is the owner but is never given a final turn.
local function clearFinalTurnBoundary()
	gStates.finalTurnReason=nil
	gStates.finalTurnOwnerMage=nil
	gStates.finalTurnOwnerGetsTurn=nil
	gStates.finalTurnOwnerTurnStarted=false
end

local function ensureFinalTurnBoundary()
	if gStates==nil or gStates.finalTurnReason==nil then return nil end
	if gStates.finalTurnOwnerMage==nil then
		local marker=gStates.finalTurnReason=="victory" and "gameEnder" or "endCalled"
		for _, details in pairs(turnOrder) do
			if details[marker]==true then gStates.finalTurnOwnerMage=details.mage break end
		end
	end
	if gStates.finalTurnOwnerGetsTurn==nil then
		gStates.finalTurnOwnerGetsTurn=gStates.finalTurnReason=="victory" and gStates.finalTurnOwnerMage~=nil and gStates.finalTurnOwnerMage~=gStates.positionMageKnight[5]
	end
	if gStates.finalTurnOwnerTurnStarted==nil then gStates.finalTurnOwnerTurnStarted=false end
	return gStates.finalTurnOwnerMage
end

local function establishFinalTurnBoundary(reason, playerIndex)
	if gStates.finalTurnReason~=nil then ensureFinalTurnBoundary() return false end
	local details=turnOrder[playerIndex]
	if details==nil then return false end
	gStates.finalTurnReason=reason
	gStates.finalTurnOwnerMage=details.mage
	gStates.finalTurnOwnerGetsTurn=reason=="victory" and details.mage~=gStates.positionMageKnight[5]
	gStates.finalTurnOwnerTurnStarted=false
	return true
end

local function finalTurnOwnerIs(playerIndex)
	local owner=ensureFinalTurnBoundary()
	return owner~=nil and turnOrder[playerIndex]~=nil and turnOrder[playerIndex].mage==owner
end

local function finalTurnBoundaryActive()
	if gStates.finalTurnReason=="endRound" then return gStates.endRoundCalled==true end
	if gStates.finalTurnReason=="victory" then return gStates.endGameAchieved=="true" end
	return false
end

function scenarioEnd(endImmediately)
	if gStates.endGameAchieved=="false" then
		UI.setAttribute("EndGameButtonText", "text", "{en}Scenario End Achieved - Yes{ru}Конец сценария достигнут - Да{zh-tw}達成劇本結束 - 是{zh-cn}達成剧本结束 - 是{ko}시나리오 종료 조건 충족 됨{es}Escenario Fin Realizados - Sí{fr}Scénario Fin Atteint - Oui{pt-br}Fim do Cenário Alcançado - Sim{de}Szenarioziel Erreicht – Ja")
		UI.setAttribute("EndGameButtonImage", "image", "Sliced Button/Button New Deactive")
		UI.setAttribute("EndGameButtonImage", "color", "rgb(1.0,0.7,0.2)")
		gStates.endGameAchieved="started"
		turnOrder[gStates.realTurn].gameEnder=true
		establishFinalTurnBoundary("victory", gStates.realTurn)
		if gStates.gameScenario=="The Gauntlet" or gStates.gameScenario=="Quest for the Golden Grail" then
			broadcastToAll("{en}Congratulations{ru}Поздравляем{zh-cn}恭喜{ko}축하합니다{es}Felicidades{fr}Toutes nos félicitations{pt-br}Parabéns{de}Glückwunsch", {1,1,0.5})
			gStates.endGameAchieved="true"
			gStates.gameOver=true
			mainUIUpdate("Scenario End")
		elseif endImmediately==true then
			gStates.endGameAchieved="true"
			gStates.gameOver=true
			mainUIUpdate("Game Over")
		else
			broadcastToAll("{en}Final Round of Turns Started{ru}Начался последний круг ходов{zh-cn}最终轮的回合开始了{ko}마지막 턴 시작{es}Inicio de la Ultima Ronda de Turnos{fr}Dernier Rounde de Tours Commencé{pt-br}Rodada Final de Turnos começou{de}Die letzte Runde hat begonnen", {1,1,0.5})
		end
	else
		UI.setAttribute("EndGameButtonText", "text", "{en}Scenario End Achieved - No{ru}Конец сценария достигнут - Нет{zh-tw}達成劇本結束 - 否{zh-cn}達成剧本结束 - 否{ko}시나리오 종료 조건 충족 전{es}Escenario Fin Realizados - No{fr}Scénario Fin Atteint - Non{pt-br}Fim do Cenário Alcançado - Não{de}Szenarioziel Erreicht – Nein")
		UI.setAttribute("EndGameButtonImage", "image", "Sliced Button/Button New Active")
		UI.setAttribute("EndGameButtonImage", "color", "white")
		UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Active")
		UI.setAttribute("PreEndTurn", "interactable", "True")
		gStates.gameOver=false
		for _, turnDetails in pairs(turnOrder) do turnDetails.gameEnder=false end
		if gStates.finalTurnReason=="victory" then clearFinalTurnBoundary() else ensureFinalTurnBoundary() end
		gStates.endGameAchieved=(gStates.finalTurnReason=="endRound" and gStates.currentRound==gStates.rounds) and "true" or "false"
		broadcastToAll("{en}Turn order resumed{ru}Порядок хода восстановлен{zh-cn}回合顺序恢复了{ko}턴 순서가 재개되었습니다{es}Se reanudó el orden de turno{fr}L'ordre des tours a repris{pt-br}Ordem de Turno retomada{de}Reihenfolge der Drehung wieder aufgenommen", {1,1,0.5})
		mainUIUpdate("Scenario End")
	end
	refreshCoopCompSkillXs()
end

--Commit a Mage Knight/Dummy/Volkare turn after any interstitial scenario turn has finished.
function mergedTurnCommit(nextTurnNumber,newOutOfTurn,sameTurn)
	gStates.turnNumber=nextTurnNumber
	if newOutOfTurn==false then gStates.realTurn=gStates.turnNumber end
	if sameTurn==false and gStates.finalTurnReason=="victory" and gStates.finalTurnOwnerGetsTurn==true and
		finalTurnBoundaryActive()==true and finalTurnOwnerIs(gStates.turnNumber) then gStates.finalTurnOwnerTurnStarted=true end
	applyColorBarButtons()
	broadcastToAll(joinLang({"{en}It is now {ru}Ходит {zh-cn}现在是{ko}{es}Ahora es el turno de {fr}C'est maintenant au tour de {pt-br}é agora turno de {de}Jetzt ist ", translateWord[turnOrder[gStates.turnNumber].mage], "{en}'s turn.{ru} {zh-cn}的回合{ko}의 차례입니다.{es}.{fr}.{pt-br}.{de} an der Reihe."}), positionToColor(gStates.turnNumber))
	if gStates.coopAssaultPhase=="combat" and coopAssaultTargetType~=nil and coopAssaultTargetType()=="dragon" and apocalypseDragonGroundCombatForPlayer~=nil and apocalypseDragonGroundCombatForPlayer(gStates.turnNumber)==true then apocalypseDragonRefreshGroundAttackSuppression() end
	if gStates.tacticShown==false then startOfTurn() else claimButtonRefresh() end
	fakeDropAvatar()
	return gStates.turnNumber
end

--Return the value of the next turn
function nextTurnMerged(type)--"nextMage", "nextMageSkipDummy", "incrementTurn",
	local extraTurnStarted=gStates.tacticSixState=="Started" or gStates.timeBending=="Started"
	--A wrap while players are choosing Tactics closes tactic selection; it is not the end of a
	--real turn circuit and must not give the Dragon a turn before the first Mage Knight acts.
	local startedDuringTacticSelection=gStates.tacticShown==true
	ensureFinalTurnBoundary()

	--A real victory owner ends the game only after completing the extra final turn.
	if type=="incrementTurn" and gStates.finalTurnReason=="victory" and gStates.finalTurnOwnerGetsTurn==true and
		gStates.finalTurnOwnerTurnStarted==true and finalTurnOwnerIs(gStates.turnNumber) and extraTurnStarted==false then
		gStates.gameOver=true
		mainUIUpdate("Game Over")
		return gStates.turnNumber
	end

	--finds all players with a flipped down turn order token
	local nextTurnNumber=gStates.realTurn
	local wrappedCircuit=false
	local function advanceTurnNumber()
		nextTurnNumber=nextTurnNumber+1
		if nextTurnNumber>#turnOrder then
			nextTurnNumber=1
			wrappedCircuit=true
			--Work out new turn order from tactics after all active players have chosen.
			if gStates.tacticShown==true and type=="incrementTurn" then
				table.sort(turnOrder, function (k1, k2) return k1.tactic < k2.tactic end)
				tacticToggle()
			end
		end
	end
	local turnSearch=nextTurnNumber+1
	if turnSearch>#turnOrder then turnSearch=1 end
	local newOutOfTurn=false
	--I search in turn order for any new face down turn order tokens. If I find a new one, I record it and jump to it's turn imediately.
	for a=1, #turnOrder, 1 do
		local turnToken=nil
		if playerDropoutInactive(turnSearch)==false and gStates.skipTurn[turnSearch]==nil and gStates.firstStarted==true then turnToken=getObjectFromGUID(turnOrder[turnSearch].turnOrderTokenGUID) end
		if turnToken~=nil and turnToken.is_face_down==true then --and gStates.turnNumber~=turnSearch
			if type=="incrementTurn" then gStates.skipTurn[turnSearch]=true end
			if turnOrder[turnSearch].mage~="Volkare" then
				nextTurnNumber=turnSearch
				newOutOfTurn=true
				break
			end
		end
		turnSearch=turnSearch+1
		if turnSearch>#turnOrder then turnSearch=1 end
	end

	local finalBoundaryReached=false
	local function candidateEndsFinalCircuit()
		if type~="incrementTurn" or extraTurnStarted==true or finalTurnBoundaryActive()==false or finalTurnOwnerIs(nextTurnNumber)==false then return false end
		--End-of-Round owners and Volkare stop before receiving another turn.
		if gStates.finalTurnOwnerGetsTurn~=true then return true end
		--Never start the owner's final turn twice (important after save/load or unusual out-of-order play).
		if gStates.finalTurnOwnerTurnStarted==true then return true end
		--A dropped owner or an owner who already spent this turn out of order has no normal final turn left to start.
		if playerDropoutInactive(nextTurnNumber)==true or gStates.skipTurn[nextTurnNumber]==true then return true end
		return false
	end

	--if no new out of order mages find next legit mage's turn
	--A pending extra turn returns to the real-turn player before normal turn-order advancement.
	--This preserves co-op assistants' skipTurn markers until their actual positions in the later turn circuit.
	if newOutOfTurn==false and extraTurnStarted==false then
		if type=="incrementTurn" then gStates.volkareState="Start" end
		advanceTurnNumber()

		local function skipDummy()
			if candidateEndsFinalCircuit()==true then finalBoundaryReached=true return true end
			--Otherwise skip dummy during final turns as normal.
			if (type=="nextMageSkipDummy" or ((gStates.endGameAchieved=="true" or gStates.endRoundCalled==true) and type=="incrementTurn")) and gStates.tacticShown~=true and turnOrder[nextTurnNumber].mage==gStates.positionMageKnight[5] then
				if type=="incrementTurn" then broadcastToAll(joinLang({translateWord[turnOrder[nextTurnNumber].mage], "{en} isn't included in the final round of turns{ru} не участвует в последнем ходе Раунда.{zh-cn}不包括在最后一轮的回合中{ko}: 마지막 턴 중에서 제외됨{es} no está incluido en la ronda final de turnos{fr} n'est pas inclus dans le dernier rounde de tours{pt-br} não está incluído na rodada final de turnos.{de} ist nicht in der letzten Runde dabei"}), {1,1,0.5}) end
				advanceTurnNumber()
				return false
			end
			return true
		end
		skipDummy()

		if finalBoundaryReached==false then
			--skip players who played out of turn or have dropped out
			for a=1, #turnOrder+1, 1 do
				local validTurn=true
				if playerDropoutInactive(nextTurnNumber)==true then
					validTurn=false
					advanceTurnNumber()
				elseif gStates.skipTurn[nextTurnNumber]==true then
					validTurn=false
					if type=="incrementTurn" then
						gStates.skipTurn[nextTurnNumber]=nil
						if turnOrder[nextTurnNumber].mage~="Volkare" then
							broadcastToAll(joinLang({translateWord[turnOrder[nextTurnNumber].mage], "{en} skips their turn. They played out of order. Turn order token flipped back upright.{ru} пропускает ход. Их ход был сыгран не по порядку. Жетон порядка хода переворачивается обратно вверх.{zh-cn}跳过他们的回合. 他们打乱了顺序. 顺位指示标记翻转. {ko}: 차례를 건너뜁니다. 다시 라운드 순서 토큰이 앞면으로 뒤집힙니다.{es} omite su turno. Jugaron fuera de orden. Ficha de orden de giro volteada hacia atrás.{fr} passe leur tour. Ils ont joué dans le désordre. Jeton d'ordre de tour retourné à la verticale.{pt-br} pule seus turnos. Eles jogaram fora de ordem. Marcador de ordem de turno virado de volta para cima.{de} überspringt seinen Zug. Sie haben außer der Reihe gespielt. Das Zugreihenfolgeplättchen wird wieder aufgedreht."}), positionToColor(nextTurnNumber))
						else
							broadcastToAll("{en}Volkare skips his turn. He's recovering from the battle.{ru}Волкар пропускает ход. Он восстанавливается после битвы.{zh-cn}沃尔卡雷跳过了他的回合. 他正在从战斗中恢复过来. {ko}볼케어는 전투 후 정비 중입니다. 볼케어의 차례를 건너뜁니다.{es}Volkare se salta su turno. Se está recuperando de la batalla.{fr}Volkare passe son tour. Il se remet de la bataille.{pt-br}Volkare pula sua vez. Ele está se recuperando da batalha.{de}Volkare überspringt seinen Zug. Er erholt sich von dem Kampf.", positionToColor(nextTurnNumber))
						end
						local token=getObjectFromGUID(turnOrder[nextTurnNumber].turnOrderTokenGUID)
						if token~=nil and token.is_face_down==true then token.flip() end
					end
					advanceTurnNumber()
				end
				--Skip dummy if end of game started
				local dummyValidTurn=skipDummy()
				if finalBoundaryReached==true then break end
				if validTurn==true and dummyValidTurn==true then break end
			end
		end
	end

	if type=="incrementTurn" and finalBoundaryReached==true then
		for ownerIndex, details in pairs(turnOrder) do
			if details.mage==gStates.finalTurnOwnerMage then
				if gStates.skipTurn[ownerIndex]==true then
					gStates.skipTurn[ownerIndex]=nil
					local token=getObjectFromGUID(details.turnOrderTokenGUID)
					if token~=nil and token.is_face_down==true then token.flip() end
				end
				if gStates.finalTurnReason=="endRound" then details.endCalled=false end
				break
			end
		end
		if gStates.finalTurnReason=="endRound" then
			if gStates.endGameAchieved=="true" then
				if gStates.currentRound>=gStates.rounds and gStates.gameScenario=="One to Return" then oneToReturnResolveWinner() end
				if gStates.currentRound>=gStates.rounds and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz") and volkareArmyStillAlive()==true then
					gStates.volkareWon=true
					gStates.volkareReturnTimeoutLoss=true
					gStates.blurb="{en}The final Round ended while Volkare still had an army.<size=6>\n\n</size>You have Lost.{ru}Последний раунд закончился, пока у Волкара еще оставалась армия.<size=6>\n\n</size>Вы проиграли.{zh-tw}最後一輪結束時沃卡里仍有軍隊。<size=6>\n\n</size>你輸了。{zh-cn}最后一轮结束时沃卡里仍有军队。<size=6>\n\n</size>你输了。{ko}마지막 라운드가 끝났지만 볼케어의 군대가 남아 있습니다.<size=6>\n\n</size>패배했습니다.{es}La Ronda final terminó mientras Volkare aún tenía un ejército.<size=6>\n\n</size>Has perdido.{fr}La dernière Manche s'est terminée alors que Volkare avait encore une armée.<size=6>\n\n</size>Vous avez perdu.{pt-br}A Rodada final terminou enquanto Volkare ainda tinha um exército.<size=6>\n\n</size>Você perdeu.{de}Die letzte Runde endete, während Volkare noch eine Armee hatte.<size=6>\n\n</size>Ihr habt verloren."
					UI.setAttribute("DummyNotes", "Text", gStates.blurb)
				end
				gStates.gameOver=true
				mainUIUpdate("Game Over")
			else endRound() end
		else
			gStates.gameOver=true
			mainUIUpdate("Game Over")
		end
		return gStates.turnNumber
	end

	--have another turn option replaces found next turn.
	local sameTurn=false
	if extraTurnStarted==true then
		sameTurn=true
		if newOutOfTurn==false then
			nextTurnNumber=gStates.realTurn
			--Only consume the extra-turn effect when the turn engine actually returns to the real-turn player.
			--During a co-op assault, handoffs to face-down assisting players must leave it Started until combat/rewards finish.
			if type=="incrementTurn" then
				if gStates.timeBending=="Started" then gStates.timeBending="Used" end
				if gStates.tacticSixState=="Started" then gStates.tacticSixState="Used" end
			end
		end
	end
	--Pending dropouts become permanent only when play genuinely advances to another turn.
	if type=="incrementTurn" and sameTurn==false then commitPendingDropouts() end

	--Against the Dragon acts after each complete normal turn circuit. Out-of-order and extra turns do
	--not create extra Dragon turns, and End of Round / first lair attack suppresses them in the helper.
	if type=="incrementTurn" and sameTurn==false and newOutOfTurn==false and wrappedCircuit==true and startedDuringTacticSelection==false and gStates.tacticShown==false and againstDragonBeginTurn~=nil then
		if againstDragonBeginTurn(nextTurnNumber,newOutOfTurn,sameTurn)==true then return nextTurnNumber end
	end
	if type=="incrementTurn" and sameTurn==false and newOutOfTurn==false and wrappedCircuit==true and startedDuringTacticSelection==false and gStates.tacticShown==false and apocalypseIsHereBeginHorsemenTurn~=nil then
		if apocalypseIsHereBeginHorsemenTurn(nextTurnNumber,newOutOfTurn,sameTurn)==true then return nextTurnNumber end
	end

	--increment the turn
	if type=="incrementTurn" then mergedTurnCommit(nextTurnNumber,newOutOfTurn,sameTurn) end
	return nextTurnNumber
end

--record the player who called end of round
function __PreEndRound_raw(player, mouseButton, id)
	if gStates.apocalypseHereHorsemenTurnActive==true then
		if player~=nil and player.color~=nil then broadcastToColor("Finish the Horsemen turn first.",player.color,warningColor) end
		return
	end
	if gStates.apocalypseDragonTurnActive==true then
		if player~=nil and player.color~=nil then broadcastToColor("Finish the Apocalypse Dragon turn first.",player.color,warningColor) end
		return
	end
	if gStates.endGameAchieved~="false" then return end
	if mouseButton=="-1" and legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true then
		turnOrder[gStates.turnNumber].endCalled=true
		gStates.endRoundCalled=true
		establishFinalTurnBoundary("endRound", gStates.turnNumber)
		--Show Game over Screen
		if gStates.currentRound==gStates.rounds and gStates.endGameAchieved~="true" then
		    gStates.endGameAchieved="true"
			if gStates.gameScenario=="One to Return" then oneToReturnLockFinalWinner() end
		end
		-- if gStates.currentRound==gStates.rounds and gStates.endGameAchieved~="true" then
		-- 	if gStates.playersRef==5 and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then UI.setAttribute("GameOver", "active", "true") layoutClaimedCards() return end
		-- 	gStates.endGameAchieved="true"
		-- end--GameOver

		--move on coop skills
		local nextPlayer=nextTurnMerged("nextMageSkipDummy")
		local count=0
		for skillGUID, details in pairs(gStates.doingTheRounds) do
			if gStates.coopCompSkillPaused==nil or gStates.coopCompSkillPaused[skillGUID]==nil then
				data=doingTheRounds(skillGUID, nextPlayer, count)
				count=data[2]
			end
		end
		refreshCoopCompSkillXs()

		--unlock second action for control over the offer.
		for _, object in pairs(getObjectFromGUID("109d8e").getObjects()) do
			if object.type=="Card" then object.unlock() break end
		end
		for _, object in pairs(getObjectFromGUID("e88f19").getObjects()) do
			if object.type=="Card" then object.unlock() break end
		end

		if activeMageKnightCount()>1 or turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
			broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage],"{en} called End of Round. Everyone else has one final turn.{ru} объявил конец Раунда. Остальные делают по одному ходу.{zh-cn}宣布结束轮次, 所有其他玩家还有最后一回合{ko}: 라운드 종료 선언. 모두 마지막 차례를 한 번씩 더 갖습니다.{es} llamado Fin de Ronda. Todos los demás tienen un turno final.{fr} appelé la Fin de Rounde. Tout le monde a un dernier tour.{pt-br} chamado o fim de Rodada. Todos outros tem um turno final.{de} ende der Runde ausgerufen. Alle anderen haben einen letzten Zug."}), positionToColor(gStates.turnNumber))
			--Delete mana token given by glade
			for a, playAreaObj in pairs(getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects()) do
				if playAreaObj.type=="Figurine" then playAreaObj.destruct() end
			end
			nextTurnMerged("incrementTurn")
		else
			preEndTurn({color="Black"}, "-1", "EndTurnButton")
		end
	end
end

--Run all the End of Round Tasks
endRoundRewindRequestPending=false
function __endRound_raw(rewindReady)
	if rewindReady~=true then
		if endRoundRewindRequestPending==true then return end
		--Unlike the other protected actions, the true round-reset boundary has no player button to press
		--again after a rewind. Save a durable checkpoint marker so onLoad can resume this reset automatically.
		gStates.endRoundResetPending=true
		endRoundRewindRequestPending=true
		rewindTransactionStart(function()
			endRoundRewindRequestPending=false
			--The stored rewind state keeps the marker; the live game clears it before any reset mutation.
			gStates.endRoundResetPending=false
			endRound(true)
		end,"End of round",function()
			endRoundRewindRequestPending=false
			gStates.endRoundResetPending=false
		end)
		return
	end
	--Time Bending returns before the round reset rebuilds and shuffles the owner's Deed deck.
	if gStates.timeBendingRemovedSeat~=nil then if reclaimTimeBending(endRound)==true then return end end
	--Against the Horsemen resolves its Round 1/2 approach, or the Round 3 ritual move, before tactics or the round reset.
	if againstHorsemenBeginEndRoundMovement()==true then return end
	--A Proxy objective is part of its Deed deck between rounds, just like the physical rules.
	if proxyPlayerActive()==true and gStates.proxyObjectiveGUID~=nil then proxyClearObjective(true) end
	--One to Return closes the starting Portal after the first Day's final-turn circuit is complete.
	if gStates.gameScenario=="One to Return" and gStates.currentRound==1 then
		oneToReturnClosePortal()
		if gStates.gameOver==true then return end
	end
	--Update round count and check for end of game
	broadcastToAll("-------------------",{1,1,0.5})
	apocalypseQuestEndRoundCleanup()
	gStates.currentRound=gStates.currentRound+1
	apocalypseQuestRefreshStrayToken()
	gStates.powerStored={}
	for _, details in pairs(turnOrder) do if details.tactic==6 then scheduleDeedPileDescriptionRefresh(details.seatPos, "deed") end end

	--Switch Day/Night Objects for Darkness is Comming
	local dieValue={"{en}Red{ru}Красный{zh-cn}红色的{ko}빨간색{es}Rojo{fr}Rouge{pt-br}Vermelho{de}Rote",
					"{en}Green{ru}Зеленый{zh-cn}绿色的{ko}녹색{es}Verde{fr}Vert{pt-br}Verde{de}Grüne",
					"{en}Blue{ru}Синий{zh-cn}蓝色的{ko}파란색{es}Azul{fr}Bleu{pt-br}Azul{de}Blaue",
					"{en}White{ru}Белый{zh-cn}白色的{ko}흰색{es}Blanco{fr}Blanc{pt-br}Branco{de}Weiße",
					"{en}Gold{ru}Золотой{zh-cn}金色的{ko}금색{es}Oro{fr}Or{pt-br}Ouro{de}Gold",
					"{en}Black{ru}Черный{zh-cn}黑色的{ko}흑색{es}Negro{fr}Noir{pt-br}Preto{de}Schwarz"}
	local virtualDie1=math.random(1,6)
	local virtualDie2=math.random(1,6)
	if gStates.darknessComing==true then broadcastToAll(joinLang({"{en}Virtual Dice rolled {ru}Виртуальный бросок кубика выпал на {zh-cn}投掷出{ko}다음의 색 주사위 굴려짐: {es}Dados virtuales enrollados en {fr}Dés virtuels lancés {pt-br}Dados Virtuais Rolados {de}Virtuelle Würfel gewürfelt ", dieValue[virtualDie1], "{en} and {ru} и {zh-cn}和{ko}그리고{es} y {fr} et {pt-br} e {de} und ", dieValue[virtualDie2]}), {1,1,0.5}) end
	if gStates.darknessComing==true and (virtualDie1==6 or virtualDie2==6) then broadcastToAll("{en}Time of day has changed permenantly{ru}Время дня изменилось до конца игры{zh-cn}白昼/黑夜停止交替了{ko}낮 또는 밤이 영원히 지속됩니다{es}La hora del día ha cambiado permanentemente{fr}L'heure de la journée a changé en permanence{pt-br}Tempo do dia mudado permanentemente.{de}Die Tageszeit hat sich dauerhaft geändert", {1,1,0.5}) end
	if gStates.darknessComing==false or (gStates.darknessComing==true and (virtualDie1==6 or virtualDie2==6) and gStates.timeChanged==false) then
	 	gStates.timeChanged=true
	 	dayNight()
	end

	--return unused mana steal die
	if getObjectFromGUID("fbd7fd")~=nil then --day tactic 3
		getObjectFromGUID("fbd7fd").registerCollisions()
		getObjectFromGUID("fbd7fd").lock()
	end
	Wait.frames(function()
		if getObjectFromGUID("fbd7fd")~=nil then getObjectFromGUID("fbd7fd").unregisterCollisions() end

		--Reroll all mana dice
		broadcastToAll("{en}Mana Dice Reset{ru}Кубики маны переброшены{zh-cn}魔力骰子重置{ko}마나 주사위 리셋{es}Reinicio de Dados de Maná{fr}Réinitialisation des dés de Mana{pt-br}Dado de Mana Reiniciado.{de}Manawürfel zurückgesetzt", {1,1,0.5})
		for a, die in pairs(getObjectFromGUID(GUID.zone.mana).getObjects()) do
			if die.getName()=="Mana Dice" then
				die.randomize()
			end
		end
	end, 5)

	--Rampage defeated sites
	if gStates.rampage>=1 then
		broadcastToAll("{en}Rampaging Tokens have been Replenished{ru}Клетки с яростными врагами получили новые жетоны{zh-cn}肆虐怪物标记已经补充{ko}광분하는 적 토큰이 보충되었습니다.{es}Se han reabastecido las fichas violentas.{fr}Les jetons déchaînés ont été réapprovisionnés{pt-br}Fichas Irascíveis foram Reabastecidas{de}Zornige Spielsteine wurden aufgefüllt", {1,1,0.5})
		local northBearing=40
		local startTileGUID=gStates.gameScenario=="Against the Horsemen Blitz" and GUID.tile.country01 or startTerrain.open
		if getObjectFromGUID(startTileGUID)==nil and gStates.gameScenario~="Against the Horsemen Blitz" then startTileGUID=startTerrain.wedge northBearing=70 end
		local startBearing=0
		for a, terrain in pairs(getObjectFromGUID(mapArea).getObjects()) do
			--Find terrain with rampaging or draconum
			if terrainTiles[terrain.guid]~=nil then
				if terrain.is_face_down==false then--check if terrain is face up
					for hexLocation, hexFeature in pairs(terrainTiles[terrain.guid].hexFeature) do
						if hexFeature=="rampaging" or hexFeature=="draconum" then
							startBearing=math.deg(math.atan2(terrain.getPosition()[3]-getObjectFromGUID(startTileGUID).getPosition()[3], terrain.getPosition()[1]-getObjectFromGUID(startTileGUID).getPosition()[1]))
							playRampagingTokens(terrain, startBearing, northBearing, hexLocation, hexFeature, false)
						end
					end
				end
			end
		end
	end

	--Update Dummy Player
	Wait.time(function()
		if gStates.positionMageKnight[5]~="nobody" and gStates.positionMageKnight[5]~="Volkare" then
			--Put advanced action in dummy deck
			broadcastToAll(proxyPlayerActive()==true and "{en}Proxy Collected The First Advanced Action Card{ru}Прокси получил первую карту Продвинутого действия{zh-cn}代理玩家拿到了第一张高级行动卡{ko}프록시가 첫 번째 상급 액션 카드를 가져갔습니다{es}Proxy consiguió la primera carta de Acción Avanzada.{fr}Le Proxy a récupéré la première carte d’Action Avancée{pt-br}Proxy pegou a primeira Carta de Ação Avançada{de}Proxy hat die erste Fortgeschrittene Aktionskarte genommen" or "{en}Dummy Collected The First Advance Action Card{ru}Нижняя карта из доступных Особых действий, добавлена в колоду деяний виртуального игрока{zh-cn}虚拟玩家拿到了第一张行动卡{ko}마지막 상급 액션이 가상 플레이어 더미에 추가되었습니다{es}El muñeco ha conseguido la Primera carta de Acción Avanzada.{fr}Mannequin a récupéré la Première carte d'Action Avancée{pt-br}Jog. Fictício Clamou a primeira Carta de Ação{de}Dummy hat die erste Vorstoß-Aktionskarte gesammelt", {1,1,0.5})
			local objCard=getObjectFromGUID(GUID.zone.actionOffer).getObjects()
			for i=1, #objCard, 1 do
				if objCard[i].type=="Card" then
					getObjectFromGUID(objCard[i].guid).unlock()
					getObjectFromGUID(objCard[i].guid).setRotationSmooth({0,180,180})
					getObjectFromGUID(objCard[i].guid).setPositionSmooth({getObjectFromGUID(dummyBoard).getPosition()[1]+4.5, 1.17, getObjectFromGUID(dummyBoard).getPosition()[3]-5.2})
					break
				end
			end
			--Put spell colored crystal in the automated player's inventory. A damaged/empty Spell offer
			--must not leave obj pointing at a mana bag and then try to count the bag as a crystal.
			local spellColor=""--read information from the card in the first spell position
			for _, card in pairs(getObjectFromGUID(GUID.zone.spellOffer).getObjects()) do
				if card.type=="Card" then spellColor=card.getDescription() break end
			end
			if spellColor=="Red" or spellColor=="Blue" or spellColor=="Green" or spellColor=="White" then
				broadcastToAll(joinLang({proxyPlayerActive()==true and "{en}Proxy added a {ru}Прокси получил {zh-cn}代理玩家添加了一个{ko}프록시 저장 칸에 {es}Proxy agregó un cristal de maná {fr}Le Proxy a ajouté un cristal de mana {pt-br}Proxy adicionou um(a) {de}Der Proxy hat einen " or "{en}Dummy added a {ru}Виртуальный игрок получил {zh-cn}虚拟玩家添加了一个{ko}가상 플레이어 저장 칸에 {es}Dummy agregó un cristal de maná {fr}Le mannequin a ajouté un cristal de mana {pt-br}Jog. Fictício adicionou um(a) {de}Die Puppe hat einen ", translateWord[spellColor], "{en} mana crystal to its inventory.{ru} кристалл маны{zh-cn}魔晶到他的装备区. {ko}수정을 추가했습니다{es} a su inventario.{fr} à son inventaire.{pt-br} Cristal de Mana para seu inventário.{de} manakristall in sein Inventar aufgenommen."}), {1,1,0.5})
				local params={position={0, 1.65, 0}, rotation={0, 30, 0}, smooth=false}
				local obj=nil
				local crystalsPerRow=3
				if gStates.rounds>6 then crystalsPerRow=4 end
				if gStates.rounds>8 then crystalsPerRow=5 end
				params.position[1]=getObjectFromGUID(dummyBoard).getPosition()[1]-2.0+((3.4/(crystalsPerRow-1))*(gStates.currentRound-2))-(((3.4/(crystalsPerRow-1))*crystalsPerRow)*math.floor((gStates.currentRound-2)/crystalsPerRow))
				params.position[3]=getObjectFromGUID(dummyBoard).getPosition()[3]+0.3-(1.2*math.floor((gStates.currentRound-2)/crystalsPerRow))
				if spellColor=="Red" then obj=takeManaCrystal(getObjectFromGUID(GUID.bag.mana.red),params) end
				if spellColor=="Blue" then obj=takeManaCrystal(getObjectFromGUID(GUID.bag.mana.blue),params) end
				if spellColor=="Green" then obj=takeManaCrystal(getObjectFromGUID(GUID.bag.mana.green),params) end
				if spellColor=="White" then obj=takeManaCrystal(getObjectFromGUID(GUID.bag.mana.white),params) end
				if obj~=nil then
					obj.lock()
					for a=1, #turnOrder, 1 do
						if turnOrder[a].mage==gStates.positionMageKnight[5] then
							local b=obj.getDescription()
							if turnOrder[a].dummyCrystals[b]==nil then turnOrder[a].dummyCrystals[b]=0 end
							turnOrder[a].dummyCrystals[b]=turnOrder[a].dummyCrystals[b]+1
							break
						end
					end
				end
			else
				broadcastToAll("Automated player found no valid Spell card during round preparation; no crystal was added.",{1,0.65,0.2})
			end
		else
			--Discards an Advance Action
			local MainDeck=getObjectFromGUID(GUID.zone.actionDeck).getObjects()
			local discard=getObjectFromGUID(GUID.zone.actionOffer).getObjects()
			if discard[1]~=nil and MainDeck[1]~=nil then
				discard[1].unlock()
				standardDeckCycleMarkReturned("Advanced Action", discard[1])
				MainDeck[1].putObject(discard[1])
			end
		end
		--Discards the last Spell
		local MainDeck=getObjectFromGUID(GUID.zone.spellDeck).getObjects()
		local discard=getObjectFromGUID(GUID.zone.spellOffer).getObjects()
		if discard[1]~=nil and MainDeck[1]~=nil then
			discard[1].unlock()
			standardDeckCycleMarkReturned("Spell", discard[1])
			MainDeck[1].putObject(discard[1])
		end

		--Fury delays Elite Units until exploration reaches a City or a Hero has entered one.
		if furyDragonPrepareEliteUnits~=nil then furyDragonPrepareEliteUnits() end

		--Turn on advanced units for last half of game in "Conquer and Hold"
		if gStates.currentRound > gStates.rounds/2 and gStates.gameScenario=="Conquer and Hold" then
			gStates.eliteUnitsUsed=true
			broadcastToAll("{en}Elite Units are included in the next Offer{zh-cn}精英部队包含在下个供应区{ko}다음 라운드부터 엘리트 유닛이 추가됩니다{es}Las Unidades Elite están incluidas en la próxima Oferta{fr}Les unités Elite sont incluses dans la prochaine Offre{pt-br}Unidades Elite estão incluídas na próxima oferta", {1,1,0.5})
		end

		--Cycle all the offers
		Wait.time(function()
			broadcastToAll("{en}Unit Offer Refreshed{ru}Доступные отряды обновлены{zh-cn}部队供应区刷新了{ko}유닛 공급처가 갱신되었습니다{es}Oferta de Unidad Actualizada{fr}Offre Unitaire Rafraîchie{pt-br}Oferta de Unidades Atualizadas{de}Einheitenangebot aufgefrischt", {1,1,0.5})
			broadcastToAll("{en}Advanced Actions and Spells cycled.{ru}Особые действия и Заклинания обновлены.{zh-cn}高级动作卡和法术卡供应区更新了{ko}상급 액션과 마법 카드 공급처가 갱신되었습니다.{es}Acciones Avanzadas y Hechizos ciclados.{fr}Actions Avancées et Sorts cyclés.{pt-br}Ações Avançadas e Feitiços reciclados.{de}Fortgeschrittene Aktionen und Zaubersprüche gewirkt.", {1,1,0.5})
			broadcastToAll("-------------------", {1,1,0.5})
			unitOffer()
			fillSlide()
		end, 1)
	end, 1)

	--Flip all skills
	broadcastToAll("{en}All Mage Knight Skills Reset{ru}Жетоны навыков снова готовы к использованию{zh-cn}所有魔法骑士的技能重置{ko}모든 스킬이 리셋 되었습니다{es}Restablecimiento de Todas las Habilidades de Mage Knight{fr}Réinitialisation de Toutes les Compétences de Mage Knight{pt-br}Todas as Hab. de MK Redefinidas{de}Alle Magier-Ritter-Fähigkeiten zurückgesetzt", {1,1,0.5})
	for skillGUID, skillDetails in pairs(skillTokens) do
		if getObjectFromGUID(skillGUID)~=nil then getObjectFromGUID(skillGUID).setRotationSmooth({0.0, 180.0, 0.0}) end
	end
	--Update Motivation Skills status
	for a, stats in pairs(gStates.motivationSkill) do
		if stats.state~="notClaimed" then stats.state="active" end
	end
	--Reset Coop and Comp Skills, including any that were illegally played after the previous round ended.
	for skillGUID, details in pairs(gStates.doingTheRounds) do
		doingTheRounds(skillGUID, "", 0, true)
	end
	for skillGUID, _ in pairs(gStates.competitiveSkillReminders or {}) do clearCompetitiveSkillReminders(skillGUID) end
	gStates.coopCompSkillPaused={}
	gStates.coopCompSkillLegalThisRound={}
	gStates.coopCompSkillActivation={}
	gStates.tomeSkillSwapPending={}

	--Ready all units
	broadcastToAll ("{en}All Units are Ready for combat again{ru}Все отряды готовы к бою{zh-cn}所有部队准备好再次迎战了{ko}유닛이 다시 전투할 준비가 되었습니다{es}Todas las unidades están listas para el combate de nuevo.{fr}Toutes les unités sont à nouveau prêtes pour le combat{pt-br}Todas Unidades estão prontas para combater novamente{de}Alle Einheiten sind wieder bereit für den Kampf", {1,1,0.5})
	local commandTokens={"12e399", "87cff0", "7a2083", "4af106", "ab5b0d", "88f6c1",--Braevalar Command
						 "07eec8", "d9f39d", "ea80e4", "dbc3f1", "442ad5", "4aa025",--Krang command
						 "a0f780", "47d922", "a8f242", "d960d3", "493833", "6bfe5b",--Ymirgh command
						 "104cff", "20a938", "2c51b2", "519062", "31e29d", "ab61c0",--Arythea command
						 "a345a3", "77dd3d", "c53d0a", "d55244", "4c1c1b", "2eb846",--Norowas command
						 "c5b17e", "7c0270", "4ea3a1", "4bbe27", "867634", "0162e7",--Goldyx command
						 "aa0a9d", "fa99cf", "10295b", "92bd25", "7e91b7", "7e6c4f",--Tovak command
						 "07661c", "bf879c", "6b7e70", "439a0a", "fb74bd", "361a24",--Wolfhawk command
						 "005290", "10feb1", "ff9201", "af501e", "cc32e5", "2b6131",--Coral command
						 "22a7bb", "bb619e", "6688df", "2a2da1", "f3f02c", "8e1952",--Jormund command
						 "fbf2cb", "405221", "787513", "2e1d38", "832228", "4b661b",--Malek command
						 "f30dd4"}--Norowas Skill is also a command token
	for _, commandGUID in pairs (commandTokens) do
		if getObjectFromGUID(commandGUID)~=nil then
			local token=getObjectFromGUID(commandGUID)
			if commandGUID~="f30dd4" or (commandGUID=="f30dd4" and token.getPosition()[3]<-25) then token.setPosition({token.getPosition()[1],token.getPosition()[2],-31.19}) end
		end
	end

	--Flip banner Cards
	for _, bannerGUID in pairs({"596cfa", "986216", "0b5b32", "e48e44", "8dbce4", "8e4b92", "75a627"}) do
		if getObjectFromGUID(bannerGUID)~=nil then getObjectFromGUID(bannerGUID).setRotationSmooth({0, 180, 0}) end
	end
	if getObjectFromGUID("8dbce4")~=nil then
		Wait.frames(function() Wait.condition(function()
			bannerOfCommandDecal()
		end, function() return getObjectFromGUID("8dbce4").resting end) end, 10)
	end

	--Move any player claimed Magic familiars down to indicate they need a new crystal
	local magicFamiliars={"d8e49b", "0a2e0b"}
	local blurbed=false
	for _, magicFamiliarGUID in pairs(magicFamiliars) do
		if getObjectFromGUID(magicFamiliarGUID)~=nil and getObjectFromGUID(magicFamiliarGUID).getPosition()[3]<-30 then
			local pos=getObjectFromGUID(magicFamiliarGUID).getPosition()
			getObjectFromGUID(magicFamiliarGUID).setPositionSmooth({pos[1], pos[2], pos[3]-3})
			if blurbed==false then broadcastToAll("{en}Magic Familiars are looking for more Mana to sustain them.{ru}Магические фамильяры жаждут ману для поддержания своей жизни.{zh-cn}法师们正在寻找更多的法力来供能他们。 {ko}마법 패밀리어가 힘을 유지하기 위한 마나를 요구합니다.{es}Los Familiares Mágicos buscan más Maná para sustentarlos.{fr}Les Familiers Magiques recherchent plus de Mana pour les soutenir.{pt-br}Familiares Mágicos estão procurando por mais Mana para sustentá-los.{de}Magische Vertraute suchen nach mehr Mana, um sie zu unterstützen.", {1,1,0.5}) blurbed=true end
		end
	end

	--Shuffle all discarded player decks and loose cards back to starting position and remove Magic Familiar Crystals
	for _, playerDetails in pairs(turnOrder) do
		--Volkare does not reset his deck
		if playerDetails.dropoutState==nil and getObjectFromGUID(deedDeckDiscardZones[playerDetails.seatPos])~=nil and playerDetails.mage~="Volkare" then
			local newDeck=nil
			local test=0
			for _, obj in pairs(getObjectFromGUID(deedDeckDiscardZones[playerDetails.seatPos]).getObjects()) do
				if obj.type=="Deck" then
					newDeck=obj
					newDeck.setRotationSmooth({0.0, 180.0, 180.0})
					newDeck.setPosition({getObjectFromGUID(deedDeckZones[playerDetails.seatPos]).getPosition()[1], 1.2, getObjectFromGUID(deedDeckZones[playerDetails.seatPos]).getPosition()[3]})
					test=1
					break
				end
			end
			--If testing (or cheating) their won't be a discard pile, so assign the normal deck as the destination for loose cards
			if test==0 then
				for _, obj in pairs(getObjectFromGUID(deedDeckZones[playerDetails.seatPos]).getObjects()) do
					if obj.type=="Deck" then
						newDeck=obj
						break
					end
				end
			end
			--remove crystals from unit area likely for magic familiars
			for _, obj in pairs(getObjectFromGUID(playerUnitAreas[playerDetails.seatPos]).getObjects()) do
				if obj.type=="Figurine" and obj.getGMNotes()~="Unit Wound" then getObjectFromGUID(trashCan).putObject(obj) end
			end

			--remove shields from glades in druid nights scenario
			if gStates.currentRound==3 or gStates.currentRound==5 or gStates.currentRound==7 then
				for _, shieldGuid in pairs(playerDetails.gladesMarked) do
					if getObjectFromGUID(shieldGuid)~=nil then
						getObjectFromGUID(shieldGuid).unlock()
						getObjectFromGUID(trashCan).putObject(getObjectFromGUID(shieldGuid))
					end
				end
				playerDetails.gladesMarked={}
			end

			--pull all the cards recorded as part of that players hand back to the floating deed deck, then it will fall into any existing cards
			for _, playerCard in pairs(playerDetails.deadDeckInventory) do
				if getObjectFromGUID(playerCard)~=nil then
					if ((gameCards[playerCard]~=nil and gameCards[playerCard].full==nil) or
						getObjectFromGUID(playerCard).getGMNotes()=="Wound") and newDeck~=nil then
						newDeck.putObject(getObjectFromGUID(playerCard))
					end
				end
			end
		end
	end
	broadcastToAll ("{en}Deed Decks reset and shuffled{ru}Колоды деяний собраны и перетасованы{zh-cn}功能牌区重置并洗牌{ko}카드 더미를 셔플했습니다{es}Deed Decks reiniciados y barajados{fr}Deed Decks réinitialisés et mélangés{pt-br}Baralhos de Façanhas reiniciados e embaralhados{de}Deed Decks werden zurückgesetzt und neu gemischt", {1,1,0.5})

	--Work out new tactics picking order
	table.sort(turnOrder, function (k1, k2) return k1.fame < k2.fame end)
	for a=1, #turnOrder-1, 1 do
		if turnOrder[a].fame==turnOrder[a+1].fame and turnOrder[a].tactic<turnOrder[a+1].tactic then
		 	local temp=turnOrder[a]
			turnOrder[a]=turnOrder[a+1]
			turnOrder[a+1]=temp
		end
	end
	gStates.turnNumber=1
	for a=1, #turnOrder, 1 do if playerDropoutInactive(a)==false then gStates.turnNumber=a break end end
	gStates.realTurn=gStates.turnNumber
	applyColorBarButtons()
	broadcastToAll(joinLang({"{en}It is now {ru}Ходит {zh-cn}现在是{ko}{es}Ahora es el turno de {fr}C'est maintenant au tour de {pt-br}é agora turno de {de}Jetzt ist ", translateWord[turnOrder[gStates.turnNumber].mage], "{en}'s turn.{ru} {zh-cn}的回合{ko}의 차례입니다.{es}.{fr}.{pt-br}.{de} an der Reihe."}), positionToColor(gStates.turnNumber))
	gStates.tacticTwoState="notUsed"
	gStates.tacticFourState="notUsed"
	gStates.tacticSixState="notClaimed"
	gStates.timeBending="notUsed"
	gStates.endRoundCalled=false
	clearFinalTurnBoundary()
	for _, details in pairs(turnOrder) do details.endCalled=false end
	refreshCoopCompSkillXs()

	--Lay out tactics for removal
	Wait.frames(function()
		--No tactics removed Scenarios
		if gStates.darknessComing==true or gStates.discardTactics==0 or gStates.currentRound>gStates.rounds-1 then
			tacticToggle()
		else
			--Remove the player's tactic Scenarios
			gStates.tacticRemove=true
			local d=1
			for a=1, 6, 1 do
				for b=1, #turnOrder, 1 do
					local c=0
					if gStates.dayRound==true then c=6 end
					if turnOrder[b].tactic==a and ((turnOrder[b].mage~=gStates.positionMageKnight[5] and gStates.discardTactics==1) or gStates.discardTactics==2) then
						getObjectFromGUID(tacticCard[turnOrder[b].tactic+c]).setRotation({0.0, 180.0, 0.0})
						getObjectFromGUID(tacticCard[turnOrder[b].tactic+c]).setPosition({-12.50+(4*d), 1.5, -14.00})
						getObjectFromGUID(tacticCard[turnOrder[b].tactic+c]).lock()
						d=d+1
						break
					end
					if turnOrder[b].tactic==a and turnOrder[b].mage==gStates.positionMageKnight[5] then
						local depth=-8
						if gStates.dayRound==true then depth=-4 end
						getObjectFromGUID(tacticCard[turnOrder[b].tactic+c]).setPosition({-16.50+(4*a), depth, -14.00})
						getObjectFromGUID(tacticCard[turnOrder[b].tactic+c]).lock()
					end
				end
			end
			claimButtonRefresh()
		end
	end, 20)--long enough for dice collision on mana steal to complete

	--shuffles, deals cards
	Wait.time(function()
		--shuffle and scale decks down for more room
		for a=1, #turnOrder, 1 do
			if getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos])~=nil and turnOrder[a].mage~="Volkare" then
				for _, obj in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
					if obj.type=="Deck" then
						obj.shuffle()
						break
					end
				end
			end
		end
		--After shuffling, force Quick Witted back to the bottom of Coral's Deed Deck.
		coralSetAsideQuickWitted()

		--deal once Quick Witted is definitely back inside Coral's Deed Deck.
		Wait.condition(function()
			dealAllHands()
			Wait.time(function()
				--Records current amount of cards in deed deck
				for a=1, #turnOrder, 1 do
					turnOrder[a].deedCount=0
					for _, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[a].seatPos]).getObjects()) do
						if b.type=="Card" then turnOrder[a].deedCount=1 break end
						if b.type=="Deck" then turnOrder[a].deedCount=b.getQuantity() break end
					end
				end
				gStates.endRoundResetPending=false
				rewindTransactionFinish("End of round")
			end, 1)
		end, function() return coralQuickWittedReadyForDraw() end)
	end, 2)

	--set discards count to 0
	for a, b in pairs(turnOrder) do	b.discardCount=0 end

	--Stops the button on last round
	if gStates.currentRound==gStates.rounds then broadcastToAll("{en}Final Round{ru}Последний Раунд{zh-cn}最终回合{ko}마지막 라운드{es}Ronda Final{fr}Tour Final{pt-br}Rodada Final{de}Letzte Runde", {1,1,0.5}) end
end

function layoutClaimedCards()
	--A Time Bending set aside on the victorious final round still belongs to its owner and must be present for scoring.
	if gStates~=nil and gStates.timeBendingRemovedSeat~=nil then if reclaimTimeBending(layoutClaimedCards)==true then return end end
	--Never dismantle live deed decks/hands while the active turn is still waiting
	--for Rewards Claimed. The final boundary must be crossed first.
	if gStates~=nil and gStates.preEndTurn==true then
		log("layoutClaimedCards ignored: Rewards Claimed is still pending.")
		return
	end
	--Score the untouched deck/discard/hand/play-area state before dismantling Deck objects.
	--TTS zone membership can lag behind takeObject/setPosition by a frame, and Deck remainders below
	--are deliberately moved later, so scoring after the layout could temporarily miss claimed cards.
	displayScore("all", "-1", nil)
	for _, turnDetails in pairs(turnOrder) do
		if turnDetails.mage~=gStates.positionMageKnight[5] then
			--UI.setAttribute("PreEndTurn", "interactable", "False")
			--UI.setAttribute("PreEndTurnImage", "image", "Sliced Button/Button New Deactive")
			local obj={}
			local OffsetX={["Advanced Action"]=0, ["Spell"]=0, ["Artifact"]=0, ["Wound"]=0}
			local OffsetY={["Advanced Action"]=0, ["Spell"]=0, ["Artifact"]=0, ["Wound"]=0}
			local OffsetZ={["Advanced Action"]=0, ["Spell"]=0, ["Artifact"]=0, ["Wound"]=0}
			local OffsetStart={["Advanced Action"]=-97, ["Spell"]=-91, ["Artifact"]=-85, ["Wound"]=-103}
			local xOffset=0.4
			local yOffset=0.04
			local zOffset=0.8
			--Look for Cards
			for _, c in pairs(getObjectFromGUID(deedDeckZones[turnDetails.seatPos]).getObjects()) do obj[#obj+1]=c end
			for _, c in pairs(getObjectFromGUID(deedDeckDiscardZones[turnDetails.seatPos]).getObjects()) do obj[#obj+1]=c end
			for _, c in pairs(getObjectFromGUID(handZones[turnDetails.seatPos]).getObjects()) do obj[#obj+1]=c end
			for _, c in pairs(obj) do
				if c.type=="Deck" then
					for _, card in pairs(c.getObjects()) do
						if c.remainder~=nil and (card.gm_notes=="Advanced Action" or card.gm_notes=="Spell" or card.gm_notes=="Artifact" or card.gm_notes=="Wound") then
							local lastCard=c.remainder
							Wait.frames(function()
								lastCard.setPosition({(turnDetails.seatPos*40)+OffsetStart[card.gm_notes]+OffsetX[card.gm_notes], 1.1+OffsetY[card.gm_notes], -39.4-OffsetZ[card.gm_notes]})
								OffsetX[card.gm_notes]=OffsetX[card.gm_notes]+xOffset
								OffsetY[card.gm_notes]=OffsetY[card.gm_notes]+yOffset
								OffsetZ[card.gm_notes]=OffsetZ[card.gm_notes]+zOffset
								if OffsetZ[card.gm_notes]>4.8 then OffsetZ[card.gm_notes]=0 end
							end, 10)
							break
						end
						if card.gm_notes=="Advanced Action" or card.gm_notes=="Spell" or card.gm_notes=="Artifact" or card.gm_notes=="Wound" then
							c.takeObject({position={(turnDetails.seatPos*40)+OffsetStart[card.gm_notes]+OffsetX[card.gm_notes], 1.1+OffsetY[card.gm_notes], -39.4-OffsetZ[card.gm_notes]}, rotation={0, 180, 0}, guid=card.guid, smooth=false})
							OffsetX[card.gm_notes]=OffsetX[card.gm_notes]+xOffset
							OffsetY[card.gm_notes]=OffsetY[card.gm_notes]+yOffset
							OffsetZ[card.gm_notes]=OffsetZ[card.gm_notes]+zOffset
							if OffsetZ[card.gm_notes]>4.8 then OffsetZ[card.gm_notes]=0 end
						end
					end
				end
				if c.type=="Card" and (c.getGMNotes()=="Advanced Action" or c.getGMNotes()=="Spell" or c.getGMNotes()=="Artifact" or c.getGMNotes()=="Wound") then
					c.setPosition({(turnDetails.seatPos*40)+OffsetStart[c.getGMNotes()]+OffsetX[c.getGMNotes()], 1.1+OffsetY[c.getGMNotes()], -39.4-OffsetZ[c.getGMNotes()]})
					OffsetX[c.getGMNotes()]=OffsetX[c.getGMNotes()]+xOffset
					OffsetY[c.getGMNotes()]=OffsetY[c.getGMNotes()]+yOffset
					OffsetZ[c.getGMNotes()]=OffsetZ[c.getGMNotes()]+zOffset
					if OffsetZ[c.getGMNotes()]>4.8 then OffsetZ[c.getGMNotes()]=0 end
				end
			end
		end
	end
end

--Swap Day and Night items
