	--Swith day night board
	local tileColor={}
	if gStates.dayRound==false then
		tileColor={r=1.0, g=1.0, b=1.0}
		local nightObject={"43fa2e", "0f95b7", "9e7de3", "ee9e66", "717bcc", "39ca3f", GUID.deck.nightWeather}
