--used to workout the offset for each hex on a terrain tile
function angleToXY(obj, ang, cachedPos, cachedRotation)
	local pos=cachedPos or obj.getPosition()
	if ang=="center" then return {pos[1], pos[3]} end
	local rotation=cachedRotation or obj.getRotation()
	local hexRotationRad=math.rad(360-rotation[2]+tonumber(ang))
	return {pos[1]+(math.cos(hexRotationRad)*2.39), pos[3]+(math.sin(hexRotationRad)*2.39)}
end

--Find a world position's bearing on one terrain tile. This is also used when a wall needs both bearings relative to the same tile.
function terrainHexBearing(terrain, pos, cachedTerrainPos, cachedTerrainRotation)
	if terrain==nil or pos==nil or terrainTiles[terrain.guid]==nil then return end
	local tilePos=cachedTerrainPos or terrain.getPosition()
	local dist=math.sqrt(((pos[1]-tilePos[1])^2)+((pos[3]-tilePos[3])^2))
	if dist>=3.1 then return end
	local bearing="center"
	if dist>1 then
		local rotation=cachedTerrainRotation or terrain.getRotation()
		local temp=60*math.floor((math.deg(math.atan2(pos[3]-tilePos[3], pos[1]-tilePos[1]))+rotation[2]+30)/60)
		if temp>=360 then temp=temp-360 end
		if temp<0 then temp=temp+360 end
		bearing=tostring(temp)
	end
	return bearing
end

--Find the terrain tile, bearing, exact centre, feature and terrain type under a world position.
--Cached map object, position and rotation tables can be supplied by callers already scanning the map.
function terrainHexAtPosition(pos, objectsInPlay, cachedPositions, cachedRotations)
	if pos==nil then return end
	if objectsInPlay==nil then
		local map=getObjectFromGUID(mapArea)
		if map==nil then return end
		objectsInPlay=map.getObjects()
	end
	for _, terrain in pairs(objectsInPlay) do
		local terrainPos=cachedPositions~=nil and cachedPositions[terrain.guid] or nil
		local terrainRotation=cachedRotations~=nil and cachedRotations[terrain.guid] or nil
		local bearing=terrainHexBearing(terrain, pos, terrainPos, terrainRotation)
		if bearing~=nil then
			local hexPos=angleToXY(terrain, bearing, terrainPos, terrainRotation)
			local details=terrainTiles[terrain.guid]
			local feature=details.hexFeature~=nil and details.hexFeature[bearing] or nil
			local hexType=details.hexType~=nil and details.hexType[bearing] or nil
			return terrain, bearing, {hexPos[1], pos[2], hexPos[2]}, feature, hexType
		end
	end
end

--Avatar-location scans repeatedly inspect the current hex plus its six neighbours. Snapshot map
--positions once and bucket physical objects so each neighbour only checks nearby pieces, while
--terrain lookup works from terrain tiles only.
avatarLocationSpatialCell=3
function avatarLocationMapSnapshot()
	local mapObj=getObjectFromGUID(mapArea)
	if mapObj==nil then return {}, {}, {}, {}, {} end
	local mapObjects=mapObj.getObjects()
	local positions={}
	local terrainObjects={}
	local terrainRotations={}
	local buckets={}
	for _, mapObject in pairs(mapObjects) do
		local pos=mapObject.getPosition()
		positions[mapObject.guid]=pos
		if terrainTiles[mapObject.guid]~=nil then
			terrainObjects[#terrainObjects+1]=mapObject
			terrainRotations[mapObject.guid]=mapObject.getRotation()
		end
		local key=tostring(math.floor(pos[1]/avatarLocationSpatialCell))..":"..tostring(math.floor(pos[3]/avatarLocationSpatialCell))
		if buckets[key]==nil then buckets[key]={} end
		buckets[key][#buckets[key]+1]=mapObject
	end
	return mapObjects, positions, terrainObjects, terrainRotations, buckets
end

function avatarLocationRelevantObjects(locatedTerrain, pos, buckets)
	local result={}
	local seen={}
	if locatedTerrain~=nil then result[#result+1]=locatedTerrain seen[locatedTerrain.guid]=true end
	local baseX=math.floor(pos[1]/avatarLocationSpatialCell)
	local baseZ=math.floor(pos[3]/avatarLocationSpatialCell)
	for x=baseX-1, baseX+1 do
		for z=baseZ-1, baseZ+1 do
			local bucket=buckets[tostring(x)..":"..tostring(z)]
			if bucket~=nil then
				for _, obj in ipairs(bucket) do
					if seen[obj.guid]~=true then result[#result+1]=obj seen[obj.guid]=true end
				end
			end
		end
	end
	return result
end

--Fractured Lands: show the folding-corridor marker on every other explored hex matching
--the active Mage Knight's current terrain type. These are guidance only; movement stays manual.
fracturedLandsTeleportDecalName="Fractured Lands Teleport"
fracturedLandsTeleportDecalURL="https://steamusercontent-a.akamaihd.net/ugc/9408415852573608798/AAD04981F964B49DD1479EFE6DFBD6D294294B82/"
function fracturedLandsTeleportHexLegal(hexType)
	if hexType==nil or hexType=="" or hexType=="ocean" then return false end
	if gStates.moveCost~=nil and gStates.moveCost[hexType]~=nil then return gStates.moveCost[hexType]<900 end
	return hexType~="lake" and hexType~="mountain"
end
function fracturedLandsTeleportRampageKey(terrainGUID, bearing)
	return tostring(terrainGUID).."|"..tostring(bearing)
end
function fracturedLandsTeleportRecordDefeatedRampager(position)
	if gStates.gameScenario~="The Fractured Lands Blitz" or position==nil then return end
	local map=getObjectFromGUID(mapArea)
	if map==nil then return end
	local terrain, bearing, _, feature=terrainHexAtPosition(position, map.getObjects())
	if terrain==nil or bearing==nil or (feature~="rampaging" and feature~="draconum") then return end
	if gStates.fracturedLandsDefeatedRampagingHexes==nil then gStates.fracturedLandsDefeatedRampagingHexes={} end
	gStates.fracturedLandsDefeatedRampagingHexes[fracturedLandsTeleportRampageKey(terrain.guid, bearing)]=true
end
function fracturedLandsTeleportHexSafeNoSite(terrain, bearing, feature, hexPos, objectsInPlay)
	if terrain==nil or bearing==nil or hexPos==nil then return false end
	feature=feature or ""
	local noSite=feature=="" or feature=="portal"
	if feature=="monastery" and gStates.monasteryBurned~=nil and gStates.monasteryBurned[terrain.guid]==true then noSite=true end
	if feature=="rampaging" or feature=="draconum" then
		local cleared=gStates.fracturedLandsDefeatedRampagingHexes or {}
		noSite=cleared[fracturedLandsTeleportRampageKey(terrain.guid, bearing)]==true
	end
	if noSite~=true then return false end
	--A safe destination cannot currently contain an enemy or another Mage Knight.
	for _, obj in pairs(objectsInPlay or {}) do
		local pos=obj.getPosition()
		if ((pos[1]-hexPos[1])^2)+((pos[3]-hexPos[3])^2)<1 then
			if monsterPugs[obj.guid]~=nil then return false end
			if feature~="portal" then
				for _, details in pairs(mageKnights) do
					if obj.guid==details.model or obj.guid==details.token or obj.guid==details.standee then return false end
				end
			end
		end
	end
	return true
end
function fracturedLandsTeleportSourcePosition(playerIndex)
	local player=turnOrder[playerIndex]
	if player==nil or player.mage==gStates.positionMageKnight[5] or coopAssaultVirtualPlayer(playerIndex)==true then return nil end
	local avatar=coopAssaultAvatarObject(playerIndex)
	if avatar==nil then return nil end
	local position=avatar.getPosition()
	--Avatars physically sit on City cards after entering a City, so translate that back to the map hex.
	for zone, citySearch in pairs(cityScriptZones) do
		local zoneObj=getObjectFromGUID(zone)
		if zoneObj~=nil then
			for _, obj in pairs(zoneObj.getObjects()) do
				if obj.guid==avatar.guid then
					local cityObj=nil
					if zone==volkare.discZone and gStates.volkareModel~=nil then cityObj=getObjectFromGUID(gStates.volkareModel) else cityObj=getObjectFromGUID(citySearch.cityGUID) end
					if cityObj~=nil then position=cityObj.getPosition() end
					return position
				end
			end
		end
	end
	return position
end
function fracturedLandsTeleportDecals()
	local decals={}
	if gStates.gameScenario~="The Fractured Lands Blitz" or gStates.firstStarted~=true or turnOrder[gStates.turnNumber]==nil then return decals end
	local sourcePos=fracturedLandsTeleportSourcePosition(gStates.turnNumber)
	local map=getObjectFromGUID(mapArea)
	if sourcePos==nil or map==nil then return decals end
	local objectsInPlay=map.getObjects()
	local cachedPositions={}
	for _, obj in pairs(objectsInPlay) do if terrainTiles[obj.guid]~=nil then cachedPositions[obj.guid]=obj.getPosition() end end
	local sourceTerrain, sourceBearing, _, _, sourceType=terrainHexAtPosition(sourcePos, objectsInPlay, cachedPositions)
	if sourceTerrain==nil or sourceBearing==nil or fracturedLandsTeleportHexLegal(sourceType)~=true then return decals end
	for _, terrain in pairs(objectsInPlay) do
		local details=terrainTiles[terrain.guid]
		if details~=nil and terrain.is_face_down==false then
			for bearing, hexType in pairs(details.hexType or {}) do
				if hexType==sourceType and fracturedLandsTeleportHexLegal(hexType)==true and not (terrain.guid==sourceTerrain.guid and tostring(bearing)==tostring(sourceBearing)) then
					local xy=angleToXY(terrain, bearing)
					local feature=(details.hexFeature or {})[bearing]
					local hexPos={xy[1],1.12,xy[2]}
					if fracturedLandsTeleportHexSafeNoSite(terrain, bearing, feature, hexPos, objectsInPlay)==true then
						decals[#decals+1]={name=fracturedLandsTeleportDecalName, url=fracturedLandsTeleportDecalURL, position=hexPos, rotation={90,0,0}, scale={2.0,2.0,1}}
					end
				end
			end
		end
	end
	return decals
end
function refreshFracturedLandsTeleportHighlights()
	--Fresh-start games never switch scenarios mid-game, so non-Fractured-Lands games do not need to touch Global decals every turn.
	if gStates.gameScenario~="The Fractured Lands Blitz" then return end
	local existing=Global.getDecals() or {}
	local decals={}
	for _, decal in pairs(existing) do if decal.name~=fracturedLandsTeleportDecalName then decals[#decals+1]=decal end end
	for _, decal in pairs(fracturedLandsTeleportDecals()) do decals[#decals+1]=decal end
	Global.setDecals(decals)
end

--Return the legal top-tile exploration position that contains a world hex.
--This deliberately reuses the normal EXPLORE set, so Volkare obeys the same tile-placement rules as players.
function volkareLegalExploreSpot(pos)
	if pos==nil or gStates.exploreButtons==nil then return end
	local best=nil
	local bestDist=999
	for _, button in pairs(gStates.exploreButtons) do
		local attributes=button.attributes
		if attributes~=nil then
			local x=tonumber(attributes.tilePosX)
			local z=tonumber(attributes.tilePosZ)
			if x~=nil and z~=nil then
				local dist=math.sqrt(((pos[1]-x)^2)+((pos[3]-z)^2))
				if dist<3.1 and dist<bestDist then best={x, 2.0, z} bestDist=dist end
			end
		end
	end
	return best
end

function normalizeVolkareBearing(bearing)
	bearing=bearing%360
	if bearing<0 then bearing=bearing+360 end
	return bearing
end

--Plan each first-phase Volkare step from the card's original direction.
--If that step needs an illegal tile, try the closest neighbouring direction and test the movement again.
function planVolkareExploreMove(volkarePos, originalBearing, moveCount, objectsInPlay)
	local bearings={}
	local plannedTile=nil
	local simPos={volkarePos[1], volkarePos[2], volkarePos[3]}
	local offsets={0, -60, 60, -120, 120, 180}
	for step=1, moveCount do
		local chosenBearing=nil
		local chosenPos=nil
		for _, offset in ipairs(offsets) do
			local bearing=normalizeVolkareBearing(originalBearing+offset)
			local testPos={simPos[1]-(2.39*math.cos(math.rad(bearing))), 3.5, simPos[3]-(2.39*math.sin(math.rad(bearing)))}
			local explored=terrainHexAtPosition(testPos, objectsInPlay)~=nil
			if explored==false and plannedTile~=nil then explored=math.sqrt(((testPos[1]-plannedTile[1])^2)+((testPos[3]-plannedTile[3])^2))<3.1 end
			if explored==true then
				chosenBearing=bearing
				chosenPos=testPos
				break
			end
			if plannedTile==nil then
				local legalSpot=volkareLegalExploreSpot(testPos)
				if legalSpot~=nil then
					plannedTile=legalSpot
					chosenBearing=bearing
					chosenPos=testPos
					break
				end
			end
		end
		if chosenBearing==nil then return bearings, plannedTile end
		bearings[step]=chosenBearing
		simPos=chosenPos
	end
	return bearings, plannedTile
end

--Refresh only the stored location of a manually moved off-turn Mage Knight.
--This deliberately avoids attack, site, hand-size, reward and pursuit side effects.
function refreshAvatarLocationOnly(playerIndex, avatarObj)
	local player=turnOrder[playerIndex]
	if player==nil or avatarObj==nil then return false end
	local avatarPos=avatarObj.getPosition()
	local previousSharedHex=player.avatarSharedHex
	player.avatarLocation=""
	player.avatarSharedHex=nil
	player.avatarSwapCity=nil
	local cityFound=false
	for zone, citySearch in pairs(cityScriptZones) do
		local zoneObj=getObjectFromGUID(zone)
		if zoneObj~=nil then
			for _, detail in pairs(zoneObj.getObjects()) do
				if detail.guid==avatarObj.guid then
					local locationObj=nil
					if zone==volkare.discZone and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") then locationObj=getObjectFromGUID(gStates.volkareModel)
					else locationObj=getObjectFromGUID(citySearch.cityGUID) if gStates.cityCard[citySearch.cityGUID]~=nil then player.avatarSwapCity=citySearch.cityGUID end end
					if locationObj~=nil then avatarPos=locationObj.getPosition() end
					cityFound=true break
				end
			end
		end
		if cityFound==true then break end
	end
	local terrain, bearing=terrainHexAtPosition(avatarPos)
	if terrain~=nil and bearing~=nil and terrainTiles[terrain.guid]~=nil then
		player.avatarLocation=terrainTiles[terrain.guid].hexFeature[bearing]
		if againstHorsemenCentralGladeHex(terrain,bearing)==true and gStates.againstHorsemenRitualStarted~=true then player.avatarSharedHex=againstHorsemenSharedHexKey end
	elseif avatarPos[1]<-42 then
		--Scripted parking on the Portal card does not change the Mage Knight's logical shared-Glade location.
		if gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted~=true and previousSharedHex==againstHorsemenSharedHexKey then
			player.avatarLocation="glade"
			player.avatarSharedHex=againstHorsemenSharedHexKey
		else player.avatarLocation="portal" end
	end
	return true
end

local playerPickedUpPos={}
local playerPickedUpHex=nil
local locationAttacked=false
local assaultApproachOrigin=nil
local assaultTargetPosition=nil
local wallAssaultChoiceResult=nil
local wallAssaultPending=nil

--The initiator's pickup position only tells us the entry side when it was an adjacent hex.
function assaultOriginAdjacent(targetPos, attackerPos)
	if targetPos==nil or attackerPos==nil then return false end
	local _, _, targetHexPos=terrainHexAtPosition(targetPos)
	local _, _, attackerHexPos=terrainHexAtPosition(attackerPos)
	if targetHexPos==nil or attackerHexPos==nil then return false end
	local dist=math.sqrt(((targetHexPos[1]-attackerHexPos[1])^2)+((targetHexPos[3]-attackerHexPos[3])^2))
	return dist>1 and dist<2.8
end

function assaultTargetHasWall(targetPos)
	if targetPos==nil then return false end
	local terrain, targetBearing=terrainHexAtPosition(targetPos)
	return terrain~=nil and targetBearing~=nil and terrainTiles[terrain.guid]~=nil and terrainTiles[terrain.guid].wallList~=nil and terrainTiles[terrain.guid].wallList[targetBearing]~=nil and next(terrainTiles[terrain.guid].wallList[targetBearing])~=nil
end

function wallAssaultChoiceNeeded(targetPos, attackerPos)
	if attackerPos==nil then attackerPos=assaultApproachOrigin end
	return assaultTargetHasWall(targetPos)==true and assaultOriginAdjacent(targetPos, attackerPos)==false
end

function showWallAssaultChoice(mode, id, viewerColor)
	wallAssaultPending={mode=mode, id=id}
	UI.setAttribute("WallAssaultChoice", "visibility", (viewerColor or positionToColor(gStates.turnNumber)).."|Black")
	if mode=="rampagerAttack" or mode=="manualMonster" then
		UI.setAttribute("WallAssaultChoiceQuestion", "text", "{en}The attack approach is unclear.\nDid your attack cross a wall?{ru}Направление атаки неясно.\nВаша атака проходила через стену?{zh-tw}攻擊的方向不明確。\n你的攻擊是否穿過城牆？{zh-cn}攻击的方向不明确。\n你的攻击是否穿过城墙？{ko}공격 방향이 불분명합니다.\n공격 중 성벽을 넘었습니까?{es}La dirección del ataque no está clara.\n¿Tu ataque cruzó una muralla?{fr}La direction de l'attaque n'est pas claire.\nVotre attaque a-t-elle franchi un mur ?{pt-br}A direção do ataque não está clara.\nSeu ataque atravessou uma muralha?{de}Die Angriffsrichtung ist unklar.\nHat dein Angriff eine Mauer überquert?")
	else
		UI.setAttribute("WallAssaultChoiceQuestion", "text", "{en}The assault approach is unclear.\nDid your assault cross a wall?{ru}Направление штурма неясно.\nВаш штурм проходил через стену?{zh-tw}突襲的進入方向不明確。\n你的突襲是否穿過城牆？{zh-cn}突袭的进入方向不明确。\n你的突袭是否穿过城墙？{ko}강습 진입 방향이 불분명합니다.\n강습 중 성벽을 넘었습니까?{es}La dirección del asalto no está clara.\n¿Tu asalto cruzó una muralla?{fr}La direction de l'assaut n'est pas claire.\nVotre assaut a-t-il franchi un mur ?{pt-br}A direção do ataque não está clara.\nSeu ataque atravessou uma muralha?{de}Die Angriffsrichtung ist unklar.\nHat dein Angriff eine Mauer überquert?")
	end
	UI.show("WallAssaultChoice")
end

function clearWallAssaultChoice()
	wallAssaultChoiceResult=nil
	wallAssaultPending=nil
	UI.hide("WallAssaultChoice")
end

function wallAssaultChoice(player, mouseButton, id)
	if mouseButton~="-1" or player==nil or legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)~=true then return end
	if id=="WallAssaultChoiceYes" then wallAssaultChoiceResult=true
	elseif id=="WallAssaultChoiceNo" then wallAssaultChoiceResult=false
	else return end
	local pending=wallAssaultPending
	wallAssaultPending=nil
	UI.hide("WallAssaultChoice")
	if pending~=nil then
		if pending.mode=="attackLocation" or pending.mode=="rampagerAttack" then attackLocation(nil, "-1", pending.id)
		elseif pending.mode=="attackCity" then attackCity(nil, "-1", pending.id)
		elseif pending.mode=="manualMonster" then
			local monster=getObjectFromGUID(pending.id)
			if monster~=nil then
				setAssaultWallFortified(monster, wallAssaultChoiceResult)
				settleAssaultWallFortified(monster.guid, wallAssaultChoiceResult)
			end
			wallAssaultChoiceResult=nil
		end
	end
end

function resolveAssaultWallFortified(targetPos, attackerPos, useManualChoice)
	if targetPos==nil or assaultTargetHasWall(targetPos)~=true then return false end
	if useManualChoice~=false and wallAssaultChoiceResult~=nil and assaultOriginAdjacent(targetPos, attackerPos)==false then return wallAssaultChoiceResult end
	return assaultCrossesWall(targetPos, attackerPos)
end

--Moving the initiating avatar away before Begin Assault cancels the pending co-op proposal.
function clearPendingCoopAssault()
	if gStates.coopAssaultPhase~=nil or gStates.coopAssaultCityGUID==nil then return end
	UI.hide("CoopAssault")
	gStates.assaultData={}
	gStates.coopAssaultUnassigned={}
	gStates.coopAssaultParticipants={}
	gStates.coopAssaultCityGUID=nil
	gStates.coopAssaultLocation=nil
	gStates.coopAssaultType=nil
	gStates.coopAssaultInitiator=nil
	gStates.coopAssaultConquered=nil
	gStates.coopAssaultScenarioEndPending=false
	gStates.againstHorsemenAssaultOrigin=nil
	gStates.apocalypseDragonAssaultOrigin=nil
	locationAttacked=false
	applyColorBarButtons()
end

--Test whether an assault from attackerPos to targetPos crosses a printed wall on the target terrain tile.
function assaultCrossesWall(targetPos, attackerPos)
	if targetPos==nil or attackerPos==nil then return false end
	local terrain, targetBearing=terrainHexAtPosition(targetPos)
	if terrain==nil or targetBearing==nil or terrainTiles[terrain.guid]==nil or terrainTiles[terrain.guid].wallList==nil or terrainTiles[terrain.guid].wallList[targetBearing]==nil then return false end
	local attackerBearing=terrainHexBearing(terrain, attackerPos)
	if attackerBearing==nil then return false end
	return terrainTiles[terrain.guid].wallList[targetBearing][attackerBearing]~=nil
end

function setAssaultWallFortified(monster, fortified)
	if monster==nil or monsterPugs[monster.guid]==nil then return end
	local wallFound=false
	for _, decal in pairs(monster.getDecals() or {}) do if decal.name=="WallFortified" then wallFound=true break end end
	if fortified==true and monsterPugs[monster.guid].unfortified==nil then
		if wallFound==false then monster.addDecal({name="WallFortified", url="https://steamusercontent-a.akamaihd.net/ugc/11147958722484508587/09808504747D568FFAECC06537C487DF223C3872/", position={0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.85, 0.85, 1}}) end
		if gStates.monsterPerks[monster.guid]==nil then gStates.monsterPerks[monster.guid]={wallFortified=true} else gStates.monsterPerks[monster.guid].wallFortified=true end
	else
		if wallFound==true then
			local decals={}
			for _, decal in pairs(monster.getDecals() or {}) do if decal.name~="WallFortified" then decals[#decals+1]=decal end end
			monster.setDecals(decals)
		end
		if gStates.monsterPerks[monster.guid]~=nil then gStates.monsterPerks[monster.guid].wallFortified=nil end
	end
end

--Smooth movement can trigger zone decal cleanup after fortification was assigned. Re-apply the visual once the defender settles.
function settleAssaultWallFortified(monsterGUID, fortified)
	local function apply() local monster=getObjectFromGUID(monsterGUID) if monster~=nil then setAssaultWallFortified(monster, fortified) end end
	Wait.frames(function() Wait.condition(apply, function() local monster=getObjectFromGUID(monsterGUID) return monster==nil or monster.resting==true end, 3, apply) end, 2)
end

--A monster dragged directly from the map to a player area may not have a legal adjacent avatar position.
--Use the current avatar when that proves the wall crossing; otherwise ask rather than silently guessing.
function resolveManualMonsterWallFortified(monster)
	if monster==nil or monsterPugs[monster.guid]==nil or monsterPugs[monster.guid].unfortified~=nil then return end
	if gStates.attackedMonsters~=nil and gStates.attackedMonsters[monster.guid]~=nil then return end--scripted attacks resolve their own approach
	local target=gStates.monsterPlayLocation[monster.guid]
	if target==nil then return end
	if assaultTargetHasWall(target)~=true then
		setAssaultWallFortified(monster, false)
		return
	end
	local avatar=coopAssaultAvatarObject(gStates.turnNumber)
	local attackerPos=nil
	if avatar~=nil then
		local pos=avatar.getPosition()
		attackerPos={pos[1], pos[2], pos[3]}
	end
	if wallAssaultChoiceNeeded(target, attackerPos)==true then
		showWallAssaultChoice("manualMonster", monster.guid, positionToColor(gStates.turnNumber))
		return
	end
	local fortified=resolveAssaultWallFortified(target, attackerPos, false)
	setAssaultWallFortified(monster, fortified)
	settleAssaultWallFortified(monster.guid, fortified)
end

function applyCurrentAssaultWallFortified(fortified)
	for monsterGUID, _ in pairs(gStates.attackedMonsters) do
		local monster=getObjectFromGUID(monsterGUID)
		if monster~=nil and monsterPugs[monsterGUID]~=nil then
			setAssaultWallFortified(monster, fortified)
			settleAssaultWallFortified(monsterGUID, fortified)
		end
	end
end

--Pyramid/Ziggurat shield spots match the Shield snap points at the normal 180 degree terrain orientation
local zigguratPyramidFloorOffsets={{-0.4275,-0.405},{0.6975,-0.0225},{-0.09,0.6975}}
function zigguratPyramidFloorPosition(terrain, sitePos, floor)
	local offset=zigguratPyramidFloorOffsets[floor]
	local angle=0
	if terrain~=nil then angle=math.rad(180-terrain.getRotation()[2]) end
	local x=(offset[1]*math.cos(angle))-(offset[2]*math.sin(angle))
	local z=(offset[1]*math.sin(angle))+(offset[2]*math.cos(angle))
	return {sitePos[1]+x, 2, sitePos[3]+z}
end

function zigguratPyramidFloorFromPosition(terrain, sitePos, shieldPos)
	local closestFloor, closestDist=nil, math.huge
	for floor=1, 3 do
		local floorPos=zigguratPyramidFloorPosition(terrain, sitePos, floor)
		local dist=((shieldPos[1]-floorPos[1])^2)+((shieldPos[3]-floorPos[3])^2)
		if dist<closestDist then closestFloor, closestDist=floor, dist end
	end
	return closestFloor
end

--Plays rampaging tokens. Both onObjectEnterScriptingZone and endRound call this routine
function playRampagingTokens(obj, startBearing, northBearing, hexLocation, hexFeature, dropped, ambushEligible)
	if ambushEligible==nil then ambushEligible=true end
	local free=true
	--set position of terrain hex in real world coordinates
	local params={position={angleToXY(obj, hexLocation)[1], 2, angleToXY(obj, hexLocation)[2]}}
	--Check if the hex has any existing tokens for Rampage Variant
	if gStates.rampage>0 then
		for _, shield in pairs(getObjectFromGUID(mapArea).getObjects()) do
			if math.sqrt(((shield.getPosition()[1]-params.position[1])^2)+((shield.getPosition()[3]-params.position[3])^2))<1 then
				local name=nil
				if shield.getRotationValues()[2]~=nil then name=shield.getRotationValues()[2].value else name=shield.getName() end
				local nameList={"Marauding Orcs", "Marauding Elementalist", "Marauding Dark Crusader",
								"Draconum", "Elementalist Draconum", "Dark Crusader Draconum",
								"Arythea", "Braevalar", "Goldyx", "Krang", "Norowas", "Tovak", "Volkare", "Wolfhawk", "Coral", "Ymirgh", "Jormund", "Mevok", "Duscenia", "Malek", "Zirtae"}
				for _, h in pairs(nameList) do
					if name==h then free=false break end
				end
			end
		end
	end
	local dice=nil
	if free==true and dropped==false then
		if gStates.rampage==1 then dice=getObjectFromGUID("95ca17").clone(params) end
		if gStates.rampage==2 then dice=getObjectFromGUID("48089f").clone(params) end
	end
	if dice~=nil then Wait.time(function() dice.destruct() end, 10) end
	Wait.frames(function()--wait for clone to spawn
		if dice~=nil then dice.unlock() dice.shuffle() end
		Wait.frames(function()
			Wait.condition(function()
				if dice~=nil then
					dice.setPosition({params.position[1], 3.0, params.position[3]})
					dice.lock()
				end
				tokenRefill()
				if dropped==true or (gStates.rampage==1 and dice~=nil and dice.getRotationValue():sub(1,7)=="Rampage" and free==true) or (gStates.rampage==2 and free==true) then
					local tokenPileGreen=	monsterPiles.green--Standard green Tokens
					local tokenPileBrown=	monsterPiles.tan--Standard Brown Tokens
					local tokenPileRed=		monsterPiles.red--Standard Red Tokens
					local tokenFaction=nil
					if gStates.gameScenario=="Life and Death" or gStates.gameScenario=="The War of Four" then
						--War of four which column
						local warOfFourLoc="center"
						if gStates.gameScenario=="The War of Four" then --Open Limited to ? Columns
							local pos=obj.getPosition()
							local edgeCoordinates={	{-38.43,  0.54},  {-33.63,  4.70},  {-28.83,  8.86}, {-24.03, 13.02}, {0, 0},--Far North Column Coordinates
													{-37.23, -5.69},  {-32.43, -1.52},  {-27.63,  2.62}, {-22.83,  6.79}, {-18.02, 10.94},--North Column Coordinates
													{-30.03, -14.01}, {-25.23, -9.84},  {-20.43, -5.69}, {-15.63, -1.54}, {-10.81,  2.63},--South Column Coordinates
													{-24.03, -16.08}, {-19.23, -11.93}, {-14.43, -7.77}, {-9.63,  -3.61}}--Far South Column Coordinates
							for tileLoc, coords in pairs(edgeCoordinates) do
								if math.sqrt(((pos[1]-coords[1])^2)+((pos[3]-coords[2])^2))<1 then
									if math.ceil(tileLoc/5)==1 then warOfFourLoc="FarNorth" end
									if math.ceil(tileLoc/5)==2 then warOfFourLoc="North" end
									if math.ceil(tileLoc/5)==3 then warOfFourLoc="South" end
									if math.ceil(tileLoc/5)==4 then warOfFourLoc="FarSouth" end
									break
								end
							end
						end
						--deploy faction tokens
						local factionPlayed=math.random(1,2)
						if 	(gStates.gameScenario=="Life and Death" and ((startBearing<northBearing-1) or
								(startBearing<=northBearing+1 and startBearing>=northBearing-1 and gStates.coop==1 and factionPlayed==1) or
								(gStates.coop==0 and factionPlayed==1 and obj.getPosition()[3]<-7 and obj.getPosition()[3]>-8 and obj.getPosition()[1]<-31 and obj.getPosition()[1]>-32))) or
						 	(gStates.gameScenario=="The War of Four" and ((warOfFourLoc=="South" and math.random(1,2)==1) or (warOfFourLoc=="FarSouth" and math.random(1,3)==1))) then
						 		tokenFaction="Elem"
							if getObjectFromGUID(monsterPiles.greenElem).getQuantity()>0 then tokenPileGreen=monsterPiles.greenElem end
							if getObjectFromGUID(monsterPiles.tanElem).getQuantity()>0 then tokenPileBrown=monsterPiles.tanElem end
							if getObjectFromGUID(monsterPiles.redElem).getQuantity()>0 then tokenPileRed=monsterPiles.redElem end --elementalist Tokens
						end
						if 	(gStates.gameScenario=="Life and Death" and ((startBearing>northBearing+1) or
								(startBearing<=northBearing+1 and startBearing>=northBearing-1 and gStates.coop==1 and factionPlayed==2) or
								(gStates.coop==0 and factionPlayed==2 and obj.getPosition()[3]<-7 and obj.getPosition()[3]>-8 and obj.getPosition()[1]<-31 and obj.getPosition()[1]>-32))) or
						 	(gStates.gameScenario=="The War of Four" and ((warOfFourLoc=="North" and math.random(1,2)==1) or (warOfFourLoc=="FarNorth" and math.random(1,3)==1))) then
						 		tokenFaction="Dark"
							if getObjectFromGUID(monsterPiles.greenDark).getQuantity()>0 then tokenPileGreen=monsterPiles.greenDark end
							if getObjectFromGUID(monsterPiles.tanDark).getQuantity()>0 then tokenPileBrown=monsterPiles.tanDark end
							if getObjectFromGUID(monsterPiles.redDark).getQuantity()>0 then tokenPileRed=monsterPiles.redDark end---Dark Crusader Tokens
						end
					end
					if gStates.gameScenario=="The Realm of the Dead Blitz" then
						tokenFaction="Dark"
						if getObjectFromGUID(monsterPiles.greenDark).getQuantity()>0 then tokenPileGreen=monsterPiles.greenDark end
						if getObjectFromGUID(monsterPiles.tanDark).getQuantity()>0 then tokenPileBrown=monsterPiles.tanDark end
						if getObjectFromGUID(monsterPiles.redDark).getQuantity()>0 then tokenPileRed=monsterPiles.redDark end---Dark Crusader Tokens
					end
					if gStates.gameScenario=="The Hidden Valley Blitz" then
						tokenFaction="Elem"
						if getObjectFromGUID(monsterPiles.greenElem).getQuantity()>0 then tokenPileGreen=monsterPiles.greenElem end
						if getObjectFromGUID(monsterPiles.tanElem).getQuantity()>0 then tokenPileBrown=monsterPiles.tanElem end
						if getObjectFromGUID(monsterPiles.redElem).getQuantity()>0 then tokenPileRed=  monsterPiles.redElem end --elementalist Tokens
					end
					params.rotation={0.0, 180.0, 0.0}
					if (hexFeature=="draconum" or hexFeature=="mine") and gStates.gameScenario~="The Lost Relic Blitz" then tokenPileGreen=tokenPileRed end
					if hexFeature=="village" or (hexFeature=="" and obj.guid==GUID.tile.city08) then tokenPileGreen=tokenPileBrown end
					--play Green token
					if getObjectFromGUID(tokenPileGreen)~=nil and getObjectFromGUID(tokenPileGreen).getQuantity()>0 then
						local token=getObjectFromGUID(tokenPileGreen).takeObject(params)
						markMonsterFactionSubstitute(token, tokenFaction)
						gStates.monsterPlayLocation[token.guid]=params.position
						gStates.rampagingMonsters[token.guid]=true
						if gStates.rampageAmbush==true and gStates.tacticShown==false and dropped==true and ambushEligible==true then
							gStates.ambushingMonsters[token.guid]=params.position
						end
						if gStates.rampagePursuit==true and gStates.tacticShown==false and dropped==true and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
							for _, mage in pairs(mageKnights) do
								if mage.mage==turnOrder[gStates.turnNumber].mage then
									if gStates.pursuingMonsters[mage.mage]==nil then gStates.pursuingMonsters[mage.mage]={} end
									gStates.pursuingMonsters[mage.mage][token.guid]={state="Deployed", location=params.position}
								end
							end
						end
						--brutal red city
						if gStates.gameScenario=="The Chaos Rift" and obj.guid==GUID.tile.city08 and monsterPugs[token.guid].brutal==nil then
							token.addDecal({name="Brutal", url="https://steamusercontent-a.akamaihd.net/ugc/14173504696154614110/C885A392A7488395AEB158E0DAA7EA420F9C4560/",
							position={-1.1, 0.15, -0.25}, rotation={90, 180, 0}, scale={0.72, 0.72, 1}})
							if gStates.monsterPerks[token.guid]==nil then gStates.monsterPerks[token.guid]={brutal=true} else gStates.monsterPerks[token.guid].brutal=true end
						end
					else
						broadcastToAll("{en}Sorry, there are no Rampage tokens left to deploy{ru}Извините, жетоны яростных врагов закончились.{zh-cn}抱歉，没有紫色标记可供部署{ko}여분의 광분하는 적 토큰이 없습니다{es}Lo sentimos, no quedan tokens de Rampage para implementar{fr}Désolé, il n'y a plus de jetons Rampage à déployer{pt-br}Desculpe, Não tem Fichas Irascíveis sobrando para distribuir{de}Leider gibt es keine Rampage-Plättchen mehr zum Einsetzen", warningColor)
					end
					--play Brown token
					if dropped==false and gStates.rampage>0 and dice~=nil and dice.getRotationValue()=="Rampage Full" then
						params.position[1]=params.position[1]+0.2
						params.position[2]=params.position[2]+0.5
						params.position[3]=params.position[3]+0.2
						if getObjectFromGUID(tokenPileBrown).getQuantity()>0 then
							local token=getObjectFromGUID(tokenPileBrown).takeObject(params)
							markMonsterFactionSubstitute(token, tokenFaction)
							gStates.monsterPlayLocation[token.guid]=params.position
							gStates.rampagingMonsters[token.guid]=true
						else
							broadcastToAll("{en}Sorry, there are no Brown tokens left to deploy{ru}Извините, коричневые жетоны закончились.{zh-cn}抱歉，没有棕色标记可供部署{ko}여분의 갈색 토큰이 없습니다{es}Lo sentimos, no quedan tokens marrones para implementar{fr}Désolé, il n'y a plus de jetons bruns à déployer{pt-br}Desculpe, Não tem Fichas Marrons sobrando para distribuir{de}Tut mir leid, es gibt keine braunen Plättchen mehr zum Auslegen", warningColor)
						end
					end
				end
			end, function() return dice==nil or dice.resting end)
		end, 5)
	end, 5)
end

--Standard cities use the printed level data through 11. Higher levels keep the level 11 model art
--and extend the garrison by repeating the 9/10/11 pattern with one extra White token every 3 levels.
function isStandardCityGUID(cityGUID)
	return cityGUID==cityModel.red or cityGUID==cityModel.green or cityGUID==cityModel.blue or cityGUID==cityModel.white
end

function cityModelDisplayLevel(cityGUID, cityLevel)
	if isStandardCityGUID(cityGUID) then return math.min(tonumber(cityLevel) or 1, 11) end
	return tonumber(cityLevel) or 1
end

