cityRebuildPause={}

function cityMegapolisPair(cityGUID)
	local data=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[cityGUID] or nil
	if data==nil or data.extra==nil then return nil end
	return data.extra.megapolisPair
end

function cityMegapolisPending(cityGUID)
	local data=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[cityGUID] or nil
	return data~=nil and data.extra~=nil and data.extra.megapolisPending==true
end

function cityHasMegapolis(cityGUID)
	return cityMegapolisPair(cityGUID)~=nil or cityMegapolisPending(cityGUID)==true
end

function cityPlayedContains(cityGUID)
	for _, playedGUID in ipairs(gStates.citiesPlayed or {}) do if playedGUID==cityGUID then return true end end
	return false
end

function cityRemoveFromPlayed(cityGUID)
	for index=#(gStates.citiesPlayed or {}), 1, -1 do if gStates.citiesPlayed[index]==cityGUID then table.remove(gStates.citiesPlayed, index) end end
end

function refreshUltimateConquestCityCounts()
	if gStates.gameScenario~="Ultimate Conquest" then return 0 end
	local cityCount=-(gStates.megapolisPlayed or 0)
	gStates.ultimateLeaders=0
	for _, playedCityGUID in ipairs(gStates.citiesPlayed or {}) do
		if playedCityGUID==darkCrusader.terrainHex or playedCityGUID==elementalist.terrainHex then
			gStates.ultimateLeaders=gStates.ultimateLeaders+1
		else
			cityCount=cityCount+1
		end
	end
	return cityCount
end

function ultimateConquestLeaderLevel(cityCount)
	if cityCount>0 and gStates.cityLevels[cityCount]~=nil then return gStates.cityLevels[cityCount] end
	local lowest=nil
	for cityIndex=1, gStates.cityTiles do
		local cityLevel=gStates.cityLevels[cityIndex]
		if cityLevel~=nil and (lowest==nil or cityLevel<lowest) then lowest=cityLevel end
	end
	return lowest or 1
end

cityMaintenanceLockSeen={}

--Once a City/Volkare garrison or faction leader reveals new information, its setup controls are permanently locked.
--The physical checks remain here as a last-line guard so a fast click can never beat the UI refresh.
function cityControlLockedByReveal(cityGUID, terrainGUID)
	if cityGUID==nil then return false end
	local data=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[cityGUID] or nil
	if data==nil and terrainGUID=="Volkar" and gStates.cityMonsterQty~=nil then
		data=gStates.cityMonsterQty[gStates.volkareModel] or gStates.cityMonsterQty[volkare.model]
	end
	if type(data)=="table" then
		local extra=rawget(data,"extra")
		if type(extra)=="table" and extra.levelLocked==true then return true end
	end

	local revealed=false
	if cityGUID==elementalist.terrainHex or cityGUID==darkCrusader.terrainHex then
		local leader=cityGUID==elementalist.terrainHex and elementalist or darkCrusader
		local token=getObjectFromGUID(leader.token)
		local disc=getObjectFromGUID(leader.disc)
		if token~=nil and disc~=nil then revealed=math.floor(token.getPosition()[1]-disc.getPosition()[1])~=-4 end
	elseif type(data)=="table" then
		for monsterGUID, state in pairs(data) do
			if monsterGUID~="extra" then
				local monsterObj=getObjectFromGUID(monsterGUID)
				if state=="dead" or (monsterObj~=nil and monsterObj.is_face_down==false) then revealed=true break end
			end
		end
	end

	if revealed==true then
		if type(data)=="table" then
			if type(rawget(data,"extra"))~="table" then rawset(data,"extra",{}) end
			data.extra.levelLocked=true
		end
		if terrainGUID=="Volkar" then gStates.volkareLevelLocked=true end
	end
	if terrainGUID=="Volkar" and gStates.volkareLevelLocked==true then return true end
	return revealed
end

function cityControlState(cityGUID, terrainGUID)
	local state={level=0, minLevel=0, maxLevel=0, canLevelUp=false, canLevelDown=false, canAddMegapolis=false, canRemoveMegapolis=false, showLevel=false}
	if terrainGUID=="Volkar" then
		state.level=tonumber(gStates.volkareLevel) or 4
		state.minLevel=4 state.maxLevel=60
		local locked=cityControlLockedByReveal(cityGUID, terrainGUID)
		state.canLevelUp=locked~=true and state.level<state.maxLevel
		state.canLevelDown=locked~=true and state.level>state.minLevel
		state.showLevel=state.level>15
		return state
	end
	local order=gStates.cityDeployOrder~=nil and gStates.cityDeployOrder[cityGUID] or nil
	local data=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[cityGUID] or nil
	if order==nil or data==nil or data.extra==nil or gStates.cityLevels==nil then return state end
	state.level=tonumber(gStates.cityLevels[order]) or 0
	local pair=data.extra.megapolisPair
	local pending=data.extra.megapolisPending==true
	if isStandardCityGUID(cityGUID) then state.minLevel=pair~=nil and 2 or 1 state.maxLevel=22
	elseif cityGUID==volkare.terrainHex then state.minLevel=1 state.maxLevel=15
	elseif cityGUID==elementalist.terrainHex or cityGUID==darkCrusader.terrainHex then state.minLevel=1 state.maxLevel=12
	else return state end
	local locked=cityControlLockedByReveal(cityGUID, terrainGUID)
	if state.level>0 and pending==false and locked~=true then
		state.canLevelUp=state.level<state.maxLevel
		state.canLevelDown=state.level>state.minLevel
	end
	if isStandardCityGUID(cityGUID) and pending==false and locked~=true then
		local megapolisMaximum=megapolisMaximumForSetup(gStates.scenarioRef,gStates.playersRef)
		state.canAddMegapolis=pair==nil and state.level>0 and (gStates.megapolis or 0)<megapolisMaximum
		state.canRemoveMegapolis=pair~=nil and pair~=cityGUID and (gStates.megapolis or 0)>0
	end
	state.showLevel=(cityGUID==darkCrusader.terrainHex or cityGUID==elementalist.terrainHex or (isStandardCityGUID(cityGUID) and state.level>11))
	return state
end

function setCityDisplayLevel(cityGUID, level)
	local cityObj=getObjectFromGUID(cityGUID)
	local images=cityLevelImage[cityGUID]
	local imageLevel=cityModelDisplayLevel(cityGUID, level)
	if cityObj==nil or images==nil or images[imageLevel]==nil then return false end
	cityObj.setCustomObject({diffuse=images[imageLevel]})
	cityObj.reload()
	Wait.frames(function()
		local currentCity=getObjectFromGUID(cityGUID)
		if currentCity~=nil then applyAltViewAngle(currentCity) end
	end, 2)
	return true
end


--Four Horsemen helpers. The Horsemen use one persistent Custom_Tile GUID each; setHorsemanLevel()
--swaps only the front image (once level art is supplied) and replaces that GUID's normal monster data.
--Cards/neutral level Shields are therefore not required by the scripted implementation.
function horsemanDataFor(ref)
	if ref==nil or horsemanData==nil then return nil, nil end
	local key=tostring(ref)
	if horsemanData[key]~=nil then return horsemanData[key], key end
	local name=horsemanTokenToName~=nil and horsemanTokenToName[key] or nil
	if name~=nil then return horsemanData[name], name end
	return nil, nil
end

function horsemanMonsterData(ref, level)
	local data,name=horsemanDataFor(ref)
	level=math.max(1,math.min(6,tonumber(level) or 1))
	local levelData=data~=nil and data.levels~=nil and data.levels[level] or nil
	if data==nil or levelData==nil then return nil end
	---@type table<string, any>
	local abilities={
		name="Horseman - "..name,
		pugType="horseman",
		horseman=name,
		fame=levelData.fame,
		armour=levelData.armour,
		attack={[data.attackType]={[1]=levelData.attack}},
		reward=1,
		faction="Apoc",
	}
	for ability,value in pairs(data.abilities or {}) do abilities[ability]=value end
	return abilities
end

function horsemanPriorityDescription(ref)
	local data,name=horsemanDataFor(ref)
	if data==nil then return "" end
	local state=gStates~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local level=state~=nil and state.level or nil
	local heading="[00ff00]HORSEMAN - "..string.upper(name)..(level~=nil and " (LEVEL "..tostring(level)..")" or "").."[-]\n"
	return heading..
		"Priority A: "..data.priorityText.A.."\n"..
		"Priority B: "..data.priorityText.B.."\n"..
		"Priority C: "..data.priorityText.C.."\n\n"
end

function setHorsemanLevel(ref, level, hideIdentity)
	local data,name=horsemanDataFor(ref)
	level=math.max(1,math.min(6,tonumber(level) or 1))
	local levelData=data~=nil and data.levels~=nil and data.levels[level] or nil
	if data==nil or name==nil or levelData==nil then return false end
	local token=getObjectFromGUID(data.tokenGUID)
	if token~=nil then
		--The physical rotation now hides an unrevealed Horseman's face, so load the real level art
		--from setup onward instead of swapping to a separate blank image.
		local displayName=hideIdentity==true and "" or (name.." Level "..tostring(level))
		local imageURL=levelData.tokenImg
		if type(imageURL)=="string" and imageURL~="" then
			token.setCustomObject({image=imageURL})
			token.setName(displayName)
			token.reload()
		else
			token.setName(displayName)
		end
	end
	monsterPugs[data.tokenGUID]=horsemanMonsterData(name,level)
	if gStates.horsemen==nil then gStates.horsemen={} end
	local state=gStates.horsemen[name] or {}
	state.level=level
	state.tokenGUID=data.tokenGUID
	if state.defeated==nil then state.defeated=false end
	gStates.horsemen[name]=state
	return true
end

function againstHorsemenAllDefeated()
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" then return false end
	local found=false
	for _,state in pairs(gStates.horsemen or {}) do
		found=true
		if state.defeated~=true then return false end
	end
	return found
end

--Scenario scoring uses the actual Horseman defeats rather than inventory reward tokens. This remains
--stable if a reward token is temporarily unavailable, and also preserves exactly who earned each kill.
function againstHorsemenDefeatSummary()
	local summary={total=0,byMage={},fameByMage={}}
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") then return summary end
	for name,state in pairs(gStates.horsemen or {}) do
		if state~=nil and state.defeated==true then
			summary.total=summary.total+1
			local mage=state.defeatedBy or (gStates.horsemenDefeatedBy~=nil and gStates.horsemenDefeatedBy[name] or nil)
			if mage~=nil then
				summary.byMage[mage]=(summary.byMage[mage] or 0)+1
				local data=horsemanData~=nil and horsemanData[name] or nil
				local level=math.max(1,math.min(6,tonumber(state.level) or 1))
				local fame=data~=nil and data.levels~=nil and data.levels[level]~=nil and tonumber(data.levels[level].fame) or 0
				summary.fameByMage[mage]=(summary.fameByMage[mage] or 0)+fame
			end
		end
	end
	return summary
end

--The cooperative +6 bonus refers to the scoring Mage Knights, not the standard Dummy/optional Proxy.
function againstHorsemenEveryScoringPlayerDefeatedOne(summary)
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") or gStates.playerCount<=1 then return false end
	summary=summary or againstHorsemenDefeatSummary()
	local found=false
	for _,details in pairs(turnOrder or {}) do
		if details.mage~=nil and details.mage~="nobody" and details.mage~=gStates.positionMageKnight[5] then
			found=true
			if (summary.byMage[details.mage] or 0)<1 then return false end
		end
	end
	return found
end

function againstHorsemenRitualDefenders()
	local defenders={}
	for name,state in pairs(gStates~=nil and gStates.horsemen or {}) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		if state~=nil and state.defeated~=true and state.atCentralGlade==true and data~=nil and getObjectFromGUID(data.tokenGUID)~=nil then
			defenders[#defenders+1]={name=name,guid=data.tokenGUID,slot=tonumber(state.mapSlot) or 99}
		end
	end
	table.sort(defenders,function(a,b) if a.slot==b.slot then return a.name<b.name end return a.slot<b.slot end)
	return defenders
end

--The Portal card becomes the Round-4 garrison display. The tokens are physical there, but each
--surviving Horseman's logical map location remains the central Glade. Layouts stay centered for 1-4.
function againstHorsemenPortalCardLayout(count)
	local cx,cz=-44.0,-12.30
	if count<=1 then return {{cx,1.22,cz}} end
	if count==2 then return {{cx-1.25,1.22,cz},{cx+1.25,1.22,cz}} end
	if count==3 then return {{cx-1.25,1.22,cz-0.78},{cx+1.25,1.22,cz-0.78},{cx,1.22,cz+0.78}} end
	return {{cx-1.25,1.22,cz-0.78},{cx+1.25,1.22,cz-0.78},{cx-1.25,1.22,cz+0.78},{cx+1.25,1.22,cz+0.78}}
end

--Defeated Horsemen are trophies as well as saved scoring state. Keep a tidy 2x2 group in the
--slayer's Inventory and make their defeated status obvious without changing the level artwork.
function againstHorsemenDefeatedInventoryPosition(playerIndex,name)
	local player=turnOrder[playerIndex]
	local state=name~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	if player==nil then return {55,2,20} end
	local slot=math.max(1,math.min(4,tonumber(state~=nil and state.mapSlot) or 1))
	local col=(slot-1)%2
	local row=math.floor((slot-1)/2)
	return {(player.seatPos*40)-115.8+(col*3.2),1.35,-32.7-(row*2.7)}
end

function againstHorsemenMarkDefeatedToken(token,name,playerIndex,smooth)
	local state=name~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local player=turnOrder[playerIndex]
	if token==nil or state==nil or player==nil then return false end
	local level=math.max(1,math.min(6,tonumber(state.level) or 1))
	token.setName("DEFEATED - "..name.." Level "..tostring(level))
	token.setDescription("Defeated by "..tostring(player.mage))
	token.setGMNotes("Defeated Horseman")
	token.setRotation({0,180,0})
	local destination=againstHorsemenDefeatedInventoryPosition(playerIndex,name)
	if smooth==false then token.setPosition(destination) else token.setPositionSmooth(destination,false) end
	return true
end

--A one-player ritual assault uses the ordinary turn/reward interface, but still needs the same
--failed-assault retreat that the combined-assault location resolver provided.
function againstHorsemenFinishSoloAssault(playerIndex)
	local pending=gStates~=nil and gStates.againstHorsemenSoloAssault or nil
	if pending==nil or pending.player~=playerIndex then return nil end
	gStates.againstHorsemenSoloAssault=nil
	local player=turnOrder[playerIndex]
	if player==nil then return nil end
	if againstHorsemenAllDefeated()==true then
		player.avatarLocation="glade"
		player.avatarSharedHex=nil
		player.avatarSwapCity=nil
		return nil
	end
	local origin=pending.origin
	if origin==nil then return nil end
	player.avatarLocation=origin.avatarLocation or ""
	player.avatarSharedHex=origin.avatarSharedHex
	player.avatarSwapCity=origin.avatarSwapCity
	return origin.position
end

--Rebuild dynamic Horseman combat data after loading a current save.
function againstHorsemenRestoreRuntimeState()
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") then return end
	if type(gStates.horsemenDefeatedBy)~="table" then gStates.horsemenDefeatedBy={} end
	for name,state in pairs(gStates.horsemen or {}) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		if data~=nil and state~=nil then
			if state.defeated==true or state.retired==true then
				--The trophy is already physically saved in the player's Inventory; only keep it out of active combat data.
				monsterPugs[data.tokenGUID]=nil
				if gStates.monsterPerks~=nil then gStates.monsterPerks[data.tokenGUID]=nil end
			else
				monsterPugs[data.tokenGUID]=horsemanMonsterData(name,state.level)
				if gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted==true then
					state.atCentralGlade=true
					state.terrainGUID=GUID.tile.country01
					state.bearing="center"
					state.revealed=true
					if monsterPugs[data.tokenGUID]~=nil and monsterPugs[data.tokenGUID].unfortified==nil then monsterPugs[data.tokenGUID].fortified=true end
				end
			end
		end
	end
	if gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted==true then againstHorsemenEliminateCentralPlayers() end
	--Do not pull tokens away from a saved combat/reward sequence. An idle Round-4 save is safe to
	--normalize immediately to the tidy garrison display.
	if gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted==true and gStates.coopAssaultPhase==nil and next(gStates.attackedMonsters or {})==nil and gStates.againstHorsemenMovePending==nil then
		local defenders=againstHorsemenRitualDefenders()
		local layout=againstHorsemenPortalCardLayout(#defenders)
		for i,entry in ipairs(defenders) do
			local token=getObjectFromGUID(entry.guid)
			if token~=nil and layout[i]~=nil then
				token.setRotation({0,180,0})
				token.setPositionSmooth(layout[i],false)
			end
		end
	end
end

function againstHorsemenEliminateCentralPlayers()
	for playerIndex,details in pairs(turnOrder or {}) do
		--The standard Dummy has no Glade figure and therefore never matches this test; an active Proxy
		--does have a Mage Knight figure and is eliminated by the ritual like any other player.
		if playerDropoutInactive(playerIndex)==false and againstHorsemenPlayerAtCentralGlade(details)==true then
			details.dropoutState="dropped"
			details.avatarLocation="eliminated"
			details.avatarSharedHex=nil
			details.horsemenGladeParked=false
			gStates.skipTurn[playerIndex]=nil
			local turnToken=getObjectFromGUID(details.turnOrderTokenGUID)
			if turnToken~=nil and turnToken.is_face_down==true then turnToken.flip() end
			--Clear the old shared Portal-card parking before the Horsemen garrison arrives. Keep the
			--eliminated figure beside its own board rather than deleting a Mage Knight object.
			local avatar=coopAssaultAvatarObject(playerIndex)
			if avatar~=nil then avatar.setPosition({(details.seatPos*40)-100,1.5,-51.2}) end
			broadcastToAll(details.mage.." was in the Magical Glade when the ritual began and is out of the game.",positionToColor(playerIndex))
		end
	end
	applyColorBarButtons()
end

function againstHorsemenPrepareRitual()
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" or gStates.againstHorsemenRitualStarted==true then return end
	gStates.againstHorsemenRitualStarted=true
	againstHorsemenEliminateCentralPlayers()
	for name,state in pairs(gStates.horsemen or {}) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
		if state~=nil and data~=nil and state.defeated~=true and token~=nil then
			state.atCentralGlade=true
			state.terrainGUID=GUID.tile.country01
			state.bearing="center"
			state.revealed=true
			token.setName(name.." Level "..tostring(state.level or 1))
			if token.is_face_down==true then token.flip() end
			monsterPugs[data.tokenGUID]=monsterPugs[data.tokenGUID] or horsemanMonsterData(name,state.level)
			--The Glade now counts as a fortified site; this is site fortification only, with no city bonus.
			if monsterPugs[data.tokenGUID]~=nil and monsterPugs[data.tokenGUID].unfortified==nil then monsterPugs[data.tokenGUID].fortified=true end
		end
	end
	broadcastToAll("The ritual has begun. The central Magical Glade is now a fortified assault site defended by every surviving Horseman.",{1,0.35,0.15})
	addAvatarButtons()
end

function againstHorsemenAssaultOrigin(approachPosition)
	local origin={avatarLocation="",avatarSharedHex=nil,avatarSwapCity=nil,position=nil}
	if approachPosition~=nil then
		origin.position={approachPosition[1],approachPosition[2],approachPosition[3]}
		local terrain,bearing,_,feature=terrainHexAtPosition(approachPosition)
		if terrain~=nil and bearing~=nil then origin.avatarLocation=feature or "" end
	end
	return origin
end

--Dropping the active Mage Knight onto the post-ritual Glade declares the assault. From here the
--existing city/co-op assault machinery owns defender allocation, skipped turns, combat order and rewards.
function againstHorsemenBeginGladeAssault(playerIndex,approachPosition)
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" or gStates.againstHorsemenRitualStarted~=true then return false end
	local player=turnOrder[playerIndex]
	if player==nil or playerIndex~=gStates.turnNumber or playerDropoutInactive(playerIndex)==true then return false end
	local defenders=againstHorsemenRitualDefenders()
	if #defenders<1 then return false end
	local gladePos=againstHorsemenCentralGladePosition(1.45)
	if gladePos==nil then return false end
	gStates.againstHorsemenAssaultOrigin=againstHorsemenAssaultOrigin(approachPosition)
	gStates.assaultData={[player.mage]={primary={},secondary={},UIPos={1},joined=true}}
	for _,entry in ipairs(defenders) do
		gStates.assaultData[player.mage].primary[#gStates.assaultData[player.mage].primary+1]=entry.guid
		local token=getObjectFromGUID(entry.guid)
		if token~=nil then
			local p=token.getPosition()
			gStates.monsterPlayLocation[entry.guid]={p[1],p[2],p[3]}
		end
	end
	gStates.coopAssaultUnassigned={primary={},secondary={}}
	local nearby=findNearbyMages(gladePos,2.5)
	local count=1
	for _,candidate in pairs(nearby) do
		if candidate.mage~=player.mage and turnOrder[candidate.turn]~=nil then
			count=count+1
			gStates.assaultData[candidate.mage]={primary={},secondary={},UIPos={count},joined=false}
		end
	end
	gStates.coopAssaultCityGUID=GUID.tile.country01
	gStates.coopAssaultLocation="glade"
	gStates.coopAssaultType="horsemen"
	gStates.coopAssaultInitiator=playerIndex
	player.combatIconHide="Avatar"
	locationAttacked=true
	applyColorBarButtons()
	--The special cooperative attack is available only with 2+ surviving Horsemen. With one Horseman
	--or no adjacent helper, begin immediately just as a city assault with no co-op option does.
	if #defenders>1 and count>1 then coopAssaultUIUpdate() else attackCity(nil,"-1","startAssault") end
	return true
end

--Against the Horsemen reveals a token as soon as the map space under it is revealed. The token's
--rotation hides the real level image before that point; once revealed it stays face up for the scenario.
function againstHorsemenRefreshHorseman(name)
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" or name==nil then return false end
	local state=gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local data=horsemanData~=nil and horsemanData[name] or nil
	local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
	if state==nil or data==nil or token==nil or state.defeated==true then return false end
	if state.atCentralGlade==true then
		state.terrainGUID=GUID.tile.country01
		state.bearing="center"
		if state.revealed~=true then
			state.revealed=true
			token.setName(name.." Level "..tostring(state.level or 1))
			if token.is_face_down==true then token.flip() end
			return true
		end
		return false
	end
	local terrain,bearing=terrainHexAtPosition(token.getPosition())
	if terrain==nil or bearing==nil then return false end
	state.terrainGUID=terrain.guid
	state.bearing=bearing
	if state.revealed==true or terrain.is_face_down==true then return false end
	state.revealed=true
	token.setName(name.." Level "..tostring(state.level or 1))
	if token.is_face_down==true then token.flip() end
	broadcastToAll(name.." has been revealed at Level "..tostring(state.level or 1)..".",{1,0.75,0.2})
	return true
end

function againstHorsemenRefreshReveals()
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" then return end
	for name,_ in pairs(gStates.horsemen or {}) do againstHorsemenRefreshHorseman(name) end
end

--Before the ritual, a Horseman is a same-space action rather than a Rampaging-style adjacent attack.
--Once the Round-4 ritual begins these individual actions disappear: dropping onto the central Glade
--starts its fortified city-style assault against every surviving Horseman instead.
function againstHorsemenAttackOptions(playerIndex,mapPosition)
	if gStates==nil or (gStates.gameScenario~="Against the Horsemen Blitz" and gStates.gameScenario~="Apocalypse is Here") or (gStates.gameScenario=="Against the Horsemen Blitz" and gStates.againstHorsemenRitualStarted==true) then return {} end
	local player=turnOrder[playerIndex]
	if player==nil or player.mage==nil then return {} end
	againstHorsemenRefreshReveals()
	local avPos=mapPosition or mageKnightAvatarPositionByName(player.mage)
	--City/Volkare-Camp avatars can be physically parked on their shared city card. Convert that
	--parking position back to the actual map location just as addAvatarButtons does for site attacks.
	if mapPosition==nil and player.avatarLocation~=nil and (player.avatarLocation:sub(1,4)=="city" or player.avatarLocation=="Volkare's Camp") then
		for zoneGUID,citySearch in pairs(cityScriptZones) do
			local zoneObj=getObjectFromGUID(zoneGUID)
			if zoneObj~=nil then
				local found=false
				for _,obj in pairs(zoneObj.getObjects()) do if obj.getName()==player.mage then found=true break end end
				if found==true then
					local cityObj=nil
					if zoneGUID==volkare.discZone and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") then cityObj=getObjectFromGUID(gStates.volkareModel)
					else cityObj=getObjectFromGUID(citySearch.cityGUID) end
					if cityObj~=nil then avPos=cityObj.getPosition() end
					break
				end
			end
		end
	end
	if avPos==nil then return {} end
	local avTerrain,avBearing,avHexCenter=terrainHexAtPosition(avPos)
	if avTerrain==nil or avBearing==nil then return {} end
	local here={}
	for name,state in pairs(gStates.horsemen or {}) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
		if state~=nil and data~=nil and state.defeated~=true and state.retired~=true and state.revealed==true and token~=nil then
			local tokenPos=token.getPosition()
			local terrain,bearing=terrainHexAtPosition(tokenPos)
			local sameHex=terrain~=nil and terrain.guid==avTerrain.guid and tostring(bearing)==tostring(avBearing)
			--Occupied sites can physically nudge the Horseman when the Mage Knight is dropped on top.
			--Allow a small centre tolerance without reaching the neighbouring hex 2.39 units away.
			if sameHex~=true and avHexCenter~=nil then
				sameHex=((tokenPos[1]-avHexCenter[1])^2)+((tokenPos[3]-avHexCenter[3])^2)<2.25
			end
			if sameHex==true then here[#here+1]={name=name,guid=data.tokenGUID,slot=tonumber(state.mapSlot) or 99} end
		end
	end
	table.sort(here,function(a,b) if a.slot==b.slot then return a.name<b.name end return a.slot<b.slot end)
	local options={}
	for _,entry in ipairs(here) do options[#options+1]={key=entry.guid,name=entry.name,label=entry.name:sub(1,1),targets={[entry.guid]=true}} end
	return options
end

function againstHorsemenAttackAction(playerDud,mouseButton,id)
	if mouseButton~="-1" then return end
	local key,mage=tostring(id or ""):match("^Horse|([^|]+)|(.+)$")
	if key==nil or mage==nil then return end
	local playerIndex=nil
	for index,details in pairs(turnOrder) do if details.mage==mage then playerIndex=index break end end
	if playerIndex==nil or playerIndex~=gStates.turnNumber then return end
	local player=turnOrder[playerIndex]
	--"Avatar" means a first defender has already been staged, but further optional enemies may still
	--be added to that combat. Only "Both" closes the Horseman choice completely.
	if player==nil or player.combatIconHide=="Both" then return end
	local turnToken=getObjectFromGUID(player.turnOrderTokenGUID)
	if turnToken==nil or turnToken.is_face_down==true then return end
	if playerDud~=nil and playerDud.color~=nil and legalPlayerCheck(playerDud.color,player.seatPos)~=true then return end
	local chosen=nil
	for _,option in ipairs(againstHorsemenAttackOptions(playerIndex)) do if option.key==key then chosen=option break end end
	if chosen==nil then addAvatarButtons() return end
	gStates.againstHorsemenAttackSelection={player=playerIndex,targets=chosen.targets}
	attackLocation(playerDud,mouseButton,"Attack"..mage)
end

--Horseman tokens are persistent Custom Tiles, so normal monster-discard logic must not treat them as
--Faction Leaders. A face-up Horseman at cleanup was defeated: record the slayer, award the Apocalypse
--Faction token, and keep the marked Horseman as a trophy in that player's Inventory. Failed face-down
--combats use monsterPlayLocation and the existing undefeated-monster return path instead.
function againstHorsemenResolveDefeat(token,playerIndex,coopCombatReward)
	local name=horsemanTokenToName~=nil and horsemanTokenToName[token~=nil and token.guid or ""] or nil
	local state=name~=nil and gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local player=turnOrder[playerIndex]
	if token==nil or name==nil or state==nil or player==nil then return false end
	if state.defeated==true then
		againstHorsemenMarkDefeatedToken(token,name,playerIndex,true)
		return true
	end
	state.defeated=true
	state.defeatedLevel=tonumber(state.level) or 1
	state.defeatedBy=player.mage
	state.defeatedRound=gStates.currentRound
	state.atCentralGlade=false
	if gStates.horsemenDefeatedBy==nil then gStates.horsemenDefeatedBy={} end
	gStates.horsemenDefeatedBy[name]=player.mage
	local rewardBag=getObjectFromGUID(monsterPiles.rewardApoc)
	if rewardBag~=nil and rewardBag.getQuantity()>0 then
		if coopCombatReward~=nil then
			coopCombatReward.factionRewards.apocalypse=(coopCombatReward.factionRewards.apocalypse or 0)+1
			if coopCombatReward.factionRewardsGiven==true then rewardBag.takeObject({position={(player.seatPos*40)-117.2+(math.random()*6.5),2,-35+(math.random()*3.2)}}) end
		else
			rewardBag.takeObject({position={(player.seatPos*40)-117.2+(math.random()*6.5),2,-35+(math.random()*3.2)}})
		end
	else
		broadcastToAll("Sorry, there are no more Apocalypse Faction Reward Tokens. Use a reminder and collect one when a token becomes available.",positionToColor(playerIndex))
	end
	if gStates.monsterPlayLocation~=nil then gStates.monsterPlayLocation[token.guid]=nil end
	if gStates.monsterPerks~=nil then gStates.monsterPerks[token.guid]=nil end
	if gStates.attackedMonsters~=nil then gStates.attackedMonsters[token.guid]=nil end
	monsterPugs[token.guid]=nil
	againstHorsemenMarkDefeatedToken(token,name,playerIndex,true)
	broadcastToAll(player.mage.." defeated "..name..". The Horseman has been placed in their Inventory.",positionToColor(playerIndex))
	return true
end

--Against the Horsemen uses a fixed hex grid around Countryside 1. There is no reason to build a
--map graph or run path-finding here: convert the token position directly to axial coordinates, take
--one deterministic step toward the nearest centre-line, then keep following that line into the Glade.
function againstHorsemenGladePosition()
	local terrain=getObjectFromGUID(GUID.tile.country01)
	if terrain==nil then return nil end
	local xy=angleToXY(terrain,"center")
	if xy==nil then return nil end
	return {xy[1],1.45,xy[2]}
end

function againstHorsemenGridFromPosition(position,center)
	if position==nil or center==nil then return nil,nil end
	local r=math.floor(((position[3]-center[3])/2.0785)+0.5)
	local q=math.floor(((position[1]-center[1])/2.4)+(r/2)+0.5)
	return q,r
end

function againstHorsemenGridDistance(q,r)
	return math.max(math.abs(q),math.abs(r),math.abs(q-r))
end

function againstHorsemenInlineGridDistance(q,r)
	return math.min(math.abs(q),math.abs(r),math.abs(q-r))
end

function againstHorsemenGridPosition(q,r,center,y)
	return {center[1]+(2.4*(q-(r/2))),y or 1.45,center[3]+(2.0785*r)}
end

function againstHorsemenDefaultNextPosition(position,center)
	local q,r=againstHorsemenGridFromPosition(position,center)
	if q==nil or r==nil or (q==0 and r==0) then return nil end
	local currentCenter=againstHorsemenGridDistance(q,r)
	local currentInline=againstHorsemenInlineGridDistance(q,r)
	local neighbours={{1,0},{-1,0},{0,1},{0,-1},{1,1},{-1,-1}}
	local bestQ,bestR=nil,nil
	local bestInline,bestCenter=999,999
	for _,offset in ipairs(neighbours) do
		local nq=q+offset[1]
		local nr=r+offset[2]
		local inline=againstHorsemenInlineGridDistance(nq,nr)
		local centerDistance=againstHorsemenGridDistance(nq,nr)
		local legal=false
		if currentInline==0 then
			--Already on one of the three lines through the Glade: stay on it and go straight inward.
			legal=inline==0 and centerDistance==currentCenter-1
		else
			--Before reaching a centre-line, simply take the adjacent hex closest to one of those lines.
			legal=inline<currentInline
		end
		if legal==true and (bestQ==nil or inline<bestInline or
			(inline==bestInline and centerDistance<bestCenter) or
			(inline==bestInline and centerDistance==bestCenter and (nq<bestQ or (nq==bestQ and nr<bestR)))) then
			bestQ=nq bestR=nr bestInline=inline bestCenter=centerDistance
		end
	end
	if bestQ==nil then return nil end
	return againstHorsemenGridPosition(bestQ,bestR,center,1.45)
end

function againstHorsemenFinalizeMoveWave()
	local pending=gStates~=nil and gStates.againstHorsemenMovePending or nil
	if pending==nil or pending.movingTargets==nil then return end
	for name,_ in pairs(pending.movingTargets) do againstHorsemenRefreshHorseman(name) end
	pending.movingTargets=nil
	pending.stepsRemaining=math.max(0,(pending.stepsRemaining or 1)-1)
	Wait.frames(function() againstHorsemenContinueEndRoundMovement() end,4)
end

function againstHorsemenAnimateMoveWave(targets)
	local pending=gStates~=nil and gStates.againstHorsemenMovePending or nil
	if pending==nil or targets==nil then return end
	pending.movingTargets=targets
	for name,target in pairs(targets) do
		local data=horsemanData~=nil and horsemanData[name] or nil
		local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
		if token~=nil and target.position~=nil then token.setPositionSmooth(target.position,false) end
	end
	Wait.frames(function()
		local function allSettled()
			for name,_ in pairs(targets) do
				local data=horsemanData~=nil and horsemanData[name] or nil
				local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
				if token~=nil and token.resting~=true then return false end
			end
			return true
		end
		Wait.condition(function() againstHorsemenFinalizeMoveWave() end, allSettled, 3, function()
			for name,target in pairs(targets) do
				local data=horsemanData~=nil and horsemanData[name] or nil
				local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
				if token~=nil and target.position~=nil then token.setPosition(target.position) end
			end
			againstHorsemenFinalizeMoveWave()
		end)
	end,2)
end

function againstHorsemenContinueEndRoundMovement()
	local pending=gStates~=nil and gStates.againstHorsemenMovePending or nil
	if pending==nil then return end
	--If a save/load happens while a wave is moving, reissue the same destinations together.
	if pending.movingTargets~=nil then againstHorsemenAnimateMoveWave(pending.movingTargets) return end
	if (pending.stepsRemaining or 0)<=0 then
		gStates.againstHorsemenEndRoundMovedRound=pending.round
		gStates.againstHorsemenMovePending=nil
		Wait.frames(function() endRound(true) end,4)
		return
	end

	local center=againstHorsemenGladePosition()
	if center==nil then
		broadcastToAll("Horsemen movement could not locate the central Magical Glade on the map.",{1,0.3,0.2})
		pending.stepsRemaining=0
		againstHorsemenContinueEndRoundMovement()
		return
	end
	local targets={}
	local stackIndex=0
	if pending.finalGlade==true and pending.ritualPrepared~=true then
		againstHorsemenPrepareRitual()
		pending.ritualPrepared=true
	end
	local ritualDefenders=pending.finalGlade==true and againstHorsemenRitualDefenders() or nil
	local ritualLayout=ritualDefenders~=nil and againstHorsemenPortalCardLayout(#ritualDefenders) or nil
	local ritualSlot={}
	for i,entry in ipairs(ritualDefenders or {}) do ritualSlot[entry.name]=i end
	for _,name in ipairs(pending.queue or {}) do
		local state=gStates.horsemen~=nil and gStates.horsemen[name] or nil
		local data=horsemanData~=nil and horsemanData[name] or nil
		local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
		if state~=nil and state.defeated~=true and token~=nil then
			local nextPosition=nil
			if pending.finalGlade==true then
				--Logically they enter the Glade; physically they take their tidy garrison slots on the Portal card.
				stackIndex=stackIndex+1
				local slot=ritualSlot[name] or stackIndex
				nextPosition=ritualLayout~=nil and ritualLayout[slot] or nil
			else
				--Use the physical position every wave. Manual player corrections therefore become the new path.
				nextPosition=againstHorsemenDefaultNextPosition(token.getPosition(),center)
			end
			if nextPosition~=nil then targets[name]={position=nextPosition} end
		end
	end
	if next(targets)==nil then
		pending.stepsRemaining=0
		againstHorsemenContinueEndRoundMovement()
		return
	end
	againstHorsemenAnimateMoveWave(targets)
end

--Rounds 1 and 2 move every surviving Horseman two hexes inward. At the end of Round 3 all survivors
--move together directly onto the central Magical Glade, beginning the final ritual round.
function againstHorsemenBeginEndRoundMovement()
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" or gStates.currentRound>3 then return false end
	if gStates.againstHorsemenEndRoundMovedRound==gStates.currentRound then return false end
	if gStates.againstHorsemenMovePending~=nil then
		againstHorsemenContinueEndRoundMovement()
		return true
	end
	againstHorsemenRefreshReveals()
	local ordered={}
	for name,state in pairs(gStates.horsemen or {}) do ordered[#ordered+1]={name=name,slot=tonumber(state.mapSlot) or 99} end
	table.sort(ordered,function(a,b) if a.slot==b.slot then return a.name<b.name end return a.slot<b.slot end)
	local queue={}
	for _,entry in ipairs(ordered) do
		local state=gStates.horsemen[entry.name]
		local data=horsemanData[entry.name]
		if state~=nil and state.defeated~=true and data~=nil and getObjectFromGUID(data.tokenGUID)~=nil then queue[#queue+1]=entry.name end
	end
	if #queue<1 then return false end
	if gStates.currentRound==3 then
		gStates.againstHorsemenMovePending={round=gStates.currentRound,queue=queue,stepsRemaining=1,finalGlade=true}
		broadcastToAll("End of Round 3: the surviving Horsemen move into the central Magical Glade and begin the ritual.",{1,0.3,0.2})
	else
		gStates.againstHorsemenMovePending={round=gStates.currentRound,queue=queue,stepsRemaining=2}
		broadcastToAll("End of Round "..tostring(gStates.currentRound)..": each surviving Horseman moves two spaces closer to the central Magical Glade.",{1,0.75,0.2})
	end
	againstHorsemenContinueEndRoundMovement()
	return true
end

function againstHorsemenStartingLevel()
	if gStates.playerCount==1 then return 2 end
	if gStates.coop==1 then return math.min(6,gStates.playerCount+2) end
	return math.max(1,math.min(6,gStates.playerCount))
end

function againstHorsemenSetupTokens(coreTileGUIDs, coreTilePositions)
	if gStates==nil or gStates.gameScenario~="Against the Horsemen Blitz" then return end
	local bag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	if bag==nil then print("HORSEMEN SETUP ERROR: Apocalypse setup bag is missing") return end
	local names={"Famine","Pestilence","Death","War"}
	for i=#names,2,-1 do
		local j=math.random(i)
		names[i],names[j]=names[j],names[i]
	end
	local level=againstHorsemenStartingLevel()
	gStates.horsemen={}
	gStates.horsemenDefeatedBy={}
	gStates.againstHorsemenCoreTiles={}
	gStates.againstHorsemenRitualStarted=false
	gStates.againstHorsemenAssaultOrigin=nil
	gStates.againstHorsemenSoloAssault=nil
	for i,name in ipairs(names) do
		local data=horsemanData[name]
		local pos=coreTilePositions[i]
		local coreGUID=coreTileGUIDs[i]
		if data==nil or pos==nil or coreGUID==nil then
			print("HORSEMEN SETUP ERROR: missing setup data for slot "..tostring(i))
		else
			--The left/right Horsemen begin one additional hex outward from their Core-tile centres.
			--Slots 2 and 4 are the right and left Core tiles respectively; one horizontal hex is 2.4 world units.
			local horsemanX=pos[1]
			if i==2 then horsemanX=horsemanX+2.4 elseif i==4 then horsemanX=horsemanX-2.4 end
			local token=bag.takeObject({guid=data.tokenGUID,position={horsemanX,2.3,pos[3]},rotation={0,180,180},smooth=false})
			if token==nil then
				print("HORSEMEN SETUP ERROR: could not deploy "..name)
			else
				setHorsemanLevel(name,level,true)
				local state=gStates.horsemen[name]
				state.revealed=false
				--Record the actual hex, not merely the Core-tile centre. This matters for the two
				--side Horsemen now that their physical starting hex is one step farther outward.
				local horsemanTerrain,horsemanBearing=terrainHexAtPosition({horsemanX,1.1,pos[3]})
				state.terrainGUID=horsemanTerrain~=nil and horsemanTerrain.guid or coreGUID
				state.bearing=horsemanBearing or "center"
				state.mapSlot=i
				gStates.againstHorsemenCoreTiles[i]=coreGUID
			end
		end
	end
end


--Apocalypse is Here -------------------------------------------------------------
--This scenario reuses the existing Horseman combat objects and Apocalypse Dragon combat engine.
--The functions below supply the scenario-specific reveal order, roaming Horsemen turns, City/Dragon
--transition, Horseman-powered Dragon levels, and the first-Dragon-attack cleanup.
function apocalypseIsHereActive()
	return gStates~=nil and gStates.gameScenario=="Apocalypse is Here"
end

function apocalypseIsHereHorsemanStartingLevel()
	if apocalypseIsHereActive()~=true then return nil end
	if gStates.playerCount==1 then return 4 end
	if gStates.coop==1 then return 6 end
	return 5
end

function apocalypseIsHerePositionRoundOrderToken()
	if apocalypseIsHereActive()~=true then return false end
	local token=getObjectFromGUID("9ba54f")
	local bag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	local target={-1.90,0.97,-22.20}
	if token==nil and bag~=nil then token=bag.takeObject({guid="9ba54f",position=target,rotation={0,180,0},smooth=false}) end
	if token==nil then return false end
	token.unlock()
	token.setRotation({0,180,0})
	token.setPositionSmooth(target,false,true)
	Wait.condition(function() local current=getObjectFromGUID("9ba54f") if current~=nil then current.lock() end end,
		function() local current=getObjectFromGUID("9ba54f") return current==nil or current.isSmoothMoving()==false end)
	return true
end

function apocalypseIsHereSetup()
	if apocalypseIsHereActive()~=true then return false end
	local names={"Famine","Pestilence","Death","War"}
	for i=#names,2,-1 do local j=math.random(i) names[i],names[j]=names[j],names[i] end
	gStates.apocalypseHereHorsemanOrder=names
	gStates.apocalypseHereNextHorseman=1
	gStates.apocalypseHereTilesRevealed=0
	gStates.apocalypseHereRevealedTiles={}
	gStates.apocalypseHereCityTilesSeen=0
	gStates.apocalypseHereHorsemenEnded=false
	gStates.apocalypseHereForcedRevealPending=false
	gStates.apocalypseHereForcedRevealCount=0
	gStates.apocalypseHereForcedRevealCheckedRound=nil
	gStates.apocalypseHereHorsemenTurnActive=false
	gStates.apocalypseHereHorsemenResumeTurn=nil
	gStates.apocalypseHereHorsemenUIState=nil
	gStates.apocalypseHereHorsemenTurnReport=nil
	gStates.apocalypseHereHorsemenQueue={}
	gStates.apocalypseHereHorsemenQueueIndex=1
	gStates.apocalypseHereHorsemanPendingChoice=nil
	gStates.apocalypseHerePossessedPending={}
	gStates.apocalypseHereDragonCityRevealed=false
	gStates.apocalypseDragonAssaultFortifiedInitiator=false
	gStates.horsemen={}
	gStates.horsemenDefeatedBy={}
	local level=apocalypseIsHereHorsemanStartingLevel()
	local componentBag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	for i,name in ipairs(names) do
		local data=horsemanData[name]
		gStates.horsemen[name]={level=level,tokenGUID=data.tokenGUID,revealed=false,defeated=false,retired=false,sitesDestroyed=0,mapSlot=i,revealIndex=i}
		--The Apocalypse component bag is deleted after setup, so park every Horseman token on the
		--table now. Keep them face down and unnamed until their reveal condition fires, but leave
		--both the tokens and cards unlocked while this scenario flow is being tuned.
		local tokenPosition={-69.80+((i-1)*5.90),0.98,24.25}
		local token=getObjectFromGUID(data.tokenGUID)
		if token==nil and componentBag~=nil then
			token=componentBag.takeObject({guid=data.tokenGUID,position=tokenPosition,rotation={0,180,180},smooth=false})
		elseif token~=nil then
			token.unlock() token.setPosition(tokenPosition) token.setRotation({0,180,180})
		end
		if token~=nil then token.setName("") token.unlock() end
		--The physical Horseman cards form the shuffled face-down scenario stack in the same order.
		local card=getObjectFromGUID(data.cardGUID)
		if card==nil and componentBag~=nil then
			card=componentBag.takeObject({guid=data.cardGUID,position={-58.70,1.00+(i*0.035),26.30},rotation={0,180,180},smooth=false})
		elseif card~=nil then
			card.unlock() card.setPosition({-58.70,1.00+(i*0.035),26.30}) card.setRotation({0,180,180})
		end
		if card~=nil then card.unlock() end
	end
	apocalypseIsHerePositionRoundOrderToken()
	return true
end

function apocalypseIsHereRevealThreshold(index)
	local thresholds=nil
	if (gStates.playerCount or 1)<=2 then thresholds={1,2,4,6}
	elseif gStates.playerCount==3 then thresholds={1,3,5,7}
	else thresholds={2,4,6,8} end
	return thresholds[index]
end

function apocalypseIsHereRevealNextHorseman(tile,forced)
	if apocalypseIsHereActive()~=true or gStates.apocalypseHereHorsemenEnded==true or tile==nil then return false end
	local index=tonumber(gStates.apocalypseHereNextHorseman) or 1
	local name=(gStates.apocalypseHereHorsemanOrder or {})[index]
	local data=name~=nil and horsemanData[name] or nil
	local state=name~=nil and gStates.horsemen[name] or nil
	if data==nil or state==nil then return false end
	local xy=angleToXY(tile,"center")
	local tilePos=tile.getPosition()
	--Bring the Horseman in above the settled terrain instead of teleporting him onto the tile.
	--One unit of clearance lets the smooth move finish cleanly; physics then drops him onto the map.
	local target={xy[1],tilePos[2]+1.0,xy[2]}
	local token=getObjectFromGUID(data.tokenGUID)
	local bag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	if token==nil and bag~=nil then token=bag.takeObject({guid=data.tokenGUID,position={target[1],target[2]+1.0,target[3]},rotation={0,180,0},smooth=false}) end
	if token==nil then return false end
	state.revealed=true
	state.retired=false
	state.terrainGUID=tile.guid
	state.bearing="center"
	state.revealTileGUID=tile.guid
	state.revealCount=gStates.apocalypseHereTilesRevealed
	setHorsemanLevel(name,state.level,false)
	token=getObjectFromGUID(data.tokenGUID) or token
	token.unlock()
	token.setRotation({0,180,0})
	token.setPositionSmooth(target,false)
	gStates.apocalypseHereNextHorseman=index+1
	local card=getObjectFromGUID(data.cardGUID)
	if card~=nil then
		card.unlock()
		card.setPositionSmooth({-69.80+((index-1)*5.90),0.98,28.10},false,true)
		if card.is_face_down==true then card.flip() end
	end
	if gStates.apocalypseHereForcedRevealPending==true then
		gStates.apocalypseHereForcedRevealCount=math.max(0,(tonumber(gStates.apocalypseHereForcedRevealCount) or 1)-1)
		gStates.apocalypseHereForcedRevealPending=gStates.apocalypseHereForcedRevealCount>0
	end
	broadcastToAll(name.." has been revealed at Level "..tostring(state.level)..(forced==true and " by the Round deadline." or "."),{1,0.75,0.2})
	return true
end

function apocalypseIsHereRoundStart()
	if apocalypseIsHereActive()~=true then return false end
	apocalypseIsHerePositionRoundOrderToken()
	local round=tonumber(gStates.currentRound) or 1
	if gStates.apocalypseHereForcedRevealCheckedRound==round then return false end
	gStates.apocalypseHereForcedRevealCheckedRound=round
	if round<2 or round>5 or gStates.apocalypseHereHorsemenEnded==true then return false end
	local deadlineIndex=round-1
	local nextIndex=tonumber(gStates.apocalypseHereNextHorseman) or 1
	if nextIndex>deadlineIndex then return false end
	gStates.apocalypseHereForcedRevealCount=deadlineIndex-nextIndex+1
	gStates.apocalypseHereForcedRevealPending=true
	local chooser=againstDragonChoicePlayerIndex~=nil and againstDragonChoicePlayerIndex() or nil
	broadcastToAll("A Horseman reveal deadline has been reached. Reveal the top Map tile and place it in a legal position as far as possible from every Mage Knight. "..againstDragonChoicePlayerLabel(chooser).." breaks a tied placement. The next placed Map tile will automatically reveal the overdue Horseman.",warningColor)
	return true
end

function apocalypseIsHerePossessEnemy(enemy)
	if enemy==nil or apocalypseIsHereActive()~=true then return false end
	gStates.apocalypseHerePossessedPending=gStates.apocalypseHerePossessedPending or {}
	if gStates.apocalypseHerePossessedPending[enemy.guid]==true then return false end
	for _,enemyGUID in pairs(gStates.apocalypsePossessedEnemyByToken or {}) do if enemyGUID==enemy.guid then return false end end
	local bag=getObjectFromGUID(GUID.bag.possessed)
	if bag==nil or bag.getQuantity()==0 then return false end
	gStates.apocalypseHerePossessedPending[enemy.guid]=true
	local p=enemy.getPosition()
	local token=bag.takeObject({position={p[1],p[2]+0.35,p[3]},rotation={0,180,0},smooth=false})
	if token==nil then gStates.apocalypseHerePossessedPending[enemy.guid]=nil return false end
	gStates.apocalypsePossessedFactionByToken=gStates.apocalypsePossessedFactionByToken or {}
	gStates.apocalypsePossessedFactionByToken[token.guid]="Apoc"
	token.setDescription(enemy.guid)
	local enemyGUID=enemy.guid
	local tokenGUID=token.guid
	Wait.frames(function()
		local currentToken=getObjectFromGUID(tokenGUID)
		local currentEnemy=getObjectFromGUID(enemyGUID)
		if currentToken~=nil and currentEnemy~=nil then
			currentToken.setPosition({currentEnemy.getPosition()[1],currentEnemy.getPosition()[2]+0.25,currentEnemy.getPosition()[3]})
			attachEnemy(nil,nil,"attach",currentToken,nil)
		end
		gStates.apocalypseHerePossessedPending[enemyGUID]=nil
	end,5)
	return true
end

function apocalypseIsHerePossessRampagersOnTile(tileGUID)
	if apocalypseIsHereActive()~=true or tileGUID==nil then return end
	local hexes,mapObjects=apocalypseQuestMapHexes()
	for _,hex in ipairs(hexes) do
		if hex.terrainGUID==tileGUID and (hex.feature=="rampaging" or hex.feature=="draconum") then
			for _,enemy in ipairs(proxyMonstersOnHex(hex,mapObjects)) do
				if gStates.rampagingMonsters~=nil and gStates.rampagingMonsters[enemy.guid]==true then apocalypseIsHerePossessEnemy(enemy) end
			end
		end
	end
end

function apocalypseIsHereRevealDragonCity(tile)
	if apocalypseIsHereActive()~=true or tile==nil or gStates.apocalypseHereDragonCityRevealed==true then return false end
	gStates.apocalypseHereDragonCityRevealed=true
	gStates.apocalypseDragonLairRevealed=true
	local tilePos=tile.getPosition()
	local fixedRotation={0,180,180}
	local positions={
		{tilePos[1],0.97,tilePos[3]},
		(function() local xy=angleToXY(tile,"240",tilePos,fixedRotation) return {xy[1],0.97,xy[2]} end)(),
		(function() local xy=angleToXY(tile,"300",tilePos,fixedRotation) return {xy[1],0.97,xy[2]} end)()
	}
	local hexes={}
	for i,pos in ipairs(positions) do
		local bearing=terrainHexBearing(tile,pos)
		hexes[#hexes+1]={bearing=bearing,position=pos,formerCity=i==1}
		if bearing~=nil then
			local feature=terrainTiles[tile.guid].hexFeature[bearing] or ""
			if i==1 then terrainTiles[tile.guid].hexType[bearing]="plains" end
			--The three Dragon spaces ignore printed sites; printed rampaging enemies remain and become Possessed.
			if feature~="rampaging" and feature~="draconum" then
				gStates.hexOverideSave=gStates.hexOverideSave or {}
				gStates.hexOverideSave[tile.guid]=gStates.hexOverideSave[tile.guid] or {}
				gStates.hexOverideSave[tile.guid][bearing]=""
				terrainTiles[tile.guid].hexFeature[bearing]=""
			end
		end
	end
	local target={positions[1][1],1.18,positions[1][3]}
	gStates.apocalypseDragonLair={tileGUID=tile.guid,hexes=hexes,position=target,rotation={0,180,180},cityHexKey=tile.guid.."|"..tostring(hexes[1].bearing)}
	local dragon=getObjectFromGUID("105141")
	local bag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	if dragon==nil and bag~=nil then dragon=bag.takeObject({guid="105141",position=target,rotation={0,180,180},smooth=false})
	elseif dragon~=nil then dragon.unlock() dragon.setRotationSmooth({0,180,180},false,true) dragon.setPositionSmooth(target,false,true) end
	if dragon~=nil then apocalypseDragonLockModelWhenSettled() end
	Wait.frames(function() apocalypseIsHerePossessRampagersOnTile(tile.guid) end,35)
	Wait.frames(function() apocalypseIsHerePossessRampagersOnTile(tile.guid) end,75)
	broadcastToAll("The second City has been destroyed by the Apocalypse Dragon. The City space is now Plains, and the Dragon has landed across the three spaces.",{1,0.75,0.2})
	return true
end

function apocalypseIsHereTerrainRevealed(tile)
	if apocalypseIsHereActive()~=true or tile==nil or tile.is_face_down==true then return false end
	local details=terrainTiles[tile.guid]
	if details==nil or details.tileType=="starting" or details.tileType=="tilePile" then return false end
	gStates.apocalypseHereRevealedTiles=gStates.apocalypseHereRevealedTiles or {}
	if gStates.apocalypseHereRevealedTiles[tile.guid]==true then return false end
	gStates.apocalypseHereRevealedTiles[tile.guid]=true
	gStates.apocalypseHereTilesRevealed=(tonumber(gStates.apocalypseHereTilesRevealed) or 0)+1
	local centerFeature=details.hexFeature~=nil and tostring(details.hexFeature.center or "") or ""
	if centerFeature:sub(1,4)=="city" then
		gStates.apocalypseHereCityTilesSeen=(tonumber(gStates.apocalypseHereCityTilesSeen) or 0)+1
		if gStates.apocalypseHereCityTilesSeen==2 then apocalypseIsHereRevealDragonCity(tile) end
	end
	if gStates.apocalypseHereHorsemenEnded==true then return true end
	local nextIndex=tonumber(gStates.apocalypseHereNextHorseman) or 1
	if nextIndex>4 then return true end
	local forced=gStates.apocalypseHereForcedRevealPending==true
	local threshold=apocalypseIsHereRevealThreshold(nextIndex)
	if forced==true or (threshold~=nil and gStates.apocalypseHereTilesRevealed>=threshold) then apocalypseIsHereRevealNextHorseman(tile,forced) end
	return true
end

function apocalypseIsHereCurrentHorsemanHex(name,hexes)
	local state=gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local data=horsemanData~=nil and horsemanData[name] or nil
	local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
	if state==nil or token==nil then return nil end
	local terrain,bearing=terrainHexAtPosition(token.getPosition())
	if terrain~=nil and bearing~=nil then state.terrainGUID=terrain.guid state.bearing=bearing end
	local key=tostring(state.terrainGUID).."|"..tostring(state.bearing)
	for _,hex in ipairs(hexes or {}) do if apocalypseQuestMapHexKey(hex)==key then return hex end end
	return nil
end

function apocalypseIsHereHorsemanTargetOptions(name)
	local state=gStates.horsemen~=nil and gStates.horsemen[name] or nil
	local data=horsemanData~=nil and horsemanData[name] or nil
	if state==nil or data==nil or state.defeated==true or state.retired==true then return {} end
	local hexes,mapObjects=apocalypseQuestMapHexes()
	local startHex=apocalypseIsHereCurrentHorsemanHex(name,hexes)
	if startHex==nil then return {} end
	local distances=apocalypseQuestHexDistanceMap(hexes,{startHex})
	for _,priority in ipairs({"A","B","C"}) do
		local wanted={}
		for _,feature in ipairs(data.priorities[priority] or {}) do wanted[feature]=true end
		local best=nil
		local options={}
		for _,hex in ipairs(hexes) do
			local feature=hex.feature or ""
			local eligible=wanted[feature]==true and feature~="destroyed"
			if eligible and feature=="monastery" and gStates.monasteryBurned~=nil and gStates.monasteryBurned[hex.terrainGUID]==true then eligible=false end
			if eligible and (feature=="rampaging" or feature=="draconum") then
				eligible=false
				for _,enemy in ipairs(proxyMonstersOnHex(hex,mapObjects)) do
					if gStates.rampagingMonsters~=nil and gStates.rampagingMonsters[enemy.guid]==true and horsemanTokenToName[enemy.guid]==nil then eligible=true break end
				end
			end
			if eligible then
				local distance=distances[apocalypseQuestMapHexKey(hex)]
				if distance~=nil and (best==nil or distance<best) then best=distance options={{key=apocalypseQuestMapHexKey(hex),hex=hex,distance=distance,priority=priority}}
				elseif distance~=nil and distance==best then options[#options+1]={key=apocalypseQuestMapHexKey(hex),hex=hex,distance=distance,priority=priority} end
			end
		end
		if #options>0 then table.sort(options,function(a,b) return a.key<b.key end) return options,startHex,hexes,mapObjects end
	end
	return {},startHex,hexes,mapObjects
end

function apocalypseIsHereHorsemanDestination(startHex,targetHex,hexes)
	if startHex==nil or targetHex==nil then return startHex end
	local fromTarget=apocalypseQuestHexDistanceMap(hexes,{targetHex})
	local current=startHex
	for _=1,2 do
		local currentDistance=fromTarget[apocalypseQuestMapHexKey(current)]
		if currentDistance==nil or currentDistance<=0 then break end
		local choices={}
		for _,candidate in ipairs(hexes) do
			if apocalypseQuestHexesAdjacent(current,candidate)==true and fromTarget[apocalypseQuestMapHexKey(candidate)]==currentDistance-1 then choices[#choices+1]=candidate end
		end
		if #choices<1 then break end
		table.sort(choices,function(a,b) return apocalypseQuestMapHexKey(a)<apocalypseQuestMapHexKey(b) end)
		current=choices[1]
	end
	return current
end

function apocalypseIsHereClearChoiceButtons()
	local map=getObjectFromGUID(mapArea)
	if map==nil then return end
	for _,terrain in pairs(map.getObjects()) do
		if terrainTiles[terrain.guid]~=nil then
			local xml=terrain.UI.getXmlTable() or {}
			local changed=false
			for i=#xml,1,-1 do local id=xml[i].attributes~=nil and tostring(xml[i].attributes.id or "") or "" if id:find("ApocalypseHorsemanTarget",1,true)~=nil then table.remove(xml,i) changed=true end end
			if changed then if #xml>0 then terrain.UI.setXmlTable(xml) else terrain.UI.setXml("") end end
		end
	end
end

function apocalypseIsHereShowTargetChoice(name,options)
	apocalypseIsHereClearChoiceButtons()
	local pending={name=name,options=options,playerIndex=againstDragonChoicePlayerIndex()}
	gStates.apocalypseHereHorsemanPendingChoice=pending
	local grouped={}
	for index,option in ipairs(options or {}) do
		local hex=option.hex
		local terrain=hex~=nil and hex.terrain or nil
		if terrain~=nil then
			local group=grouped[terrain.guid] or {terrain=terrain,xml=terrain.UI.getXmlTable() or {}}
			grouped[terrain.guid]=group
			local localPos=terrain.positionToLocal({hex.position[1],terrain.getPosition()[2],hex.position[3]})
			local tileScale=terrain.getScale()
			local uiFactor=terrainTiles[terrain.guid].tileType=="starting" and 1 or (0.16/0.38)
			local uiX=(localPos.x or localPos[1])*(tileScale.x or tileScale[1] or 2.25)*110*uiFactor
			local uiY=(localPos.z or localPos[3])*(tileScale.z or tileScale[3] or 2.25)*110*uiFactor
			local scale=0.38*uiFactor
			local id=terrain.guid.."ApocalypseHorsemanTarget"..tostring(index)
			group.xml[#group.xml+1]={tag="Button",attributes={id=id,onClick="global/apocalypseIsHereHorsemanTargetSelect",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",height=300,width=320,color="rgba(0,0,0,0.0)",position=uiX.." "..uiY.." "..(-40*uiFactor),rotation="0 0 "..tostring(terrain.getRotation()[2] or 180),scale=scale.." "..scale},children={{tag="Image",attributes={image="Sliced Button/Button Object Active",type="Sliced"}},{tag="Text",attributes={font="Fonts/MKCardText",fontSize="65",alignment="MiddleCenter",text=name.."\nTarget"}}}}
		end
	end
	for _,group in pairs(grouped) do group.terrain.UI.setXmlTable(group.xml) end
	gStates.apocalypseHereHorsemenUIState="WaitingChoice"
	gStates.apocalypseHereHorsemenTurnReport=name.." has tied preferred targets. "..againstDragonChoicePlayerLabel(pending.playerIndex).." must choose which site it moves toward."
	mainUIUpdate("Horseman target choice")
	return true
end

function apocalypseIsHereHorsemanTargetSelect(player,mouseButton,id)
	if mouseButton~="-1" or apocalypseIsHereActive()~=true then return end
	local pending=gStates.apocalypseHereHorsemanPendingChoice
	if pending==nil or againstDragonChoiceAuthorized(player,pending)~=true then return end
	local index=tonumber(tostring(id or ""):match("ApocalypseHorsemanTarget(%d+)$"))
	local option=index~=nil and pending.options[index] or nil
	if option==nil then return end
	apocalypseIsHereClearChoiceButtons()
	gStates.apocalypseHereHorsemanPendingChoice=nil
	gStates.apocalypseHereHorsemenUIState="Processing"
	apocalypseIsHereResolveHorsemanTarget(pending.name,option)
end

function apocalypseIsHereHorsemanDestroyTarget(name,targetHex)
	local state=gStates.horsemen[name]
	local data=horsemanData[name]
	if state==nil or data==nil or targetHex==nil then return false end
	local _,mapObjects=apocalypseQuestMapHexes()
	for _,enemy in ipairs(proxyMonstersOnHex(targetHex,mapObjects)) do
		if horsemanTokenToName[enemy.guid]==nil then proxyDiscardMonster(enemy) end
	end
	local bag=getObjectFromGUID(GUID.bag.destroyedSite)
	if bag~=nil and bag.getQuantity()~=0 then
		local token=bag.takeObject({position={targetHex.position[1],1.12,targetHex.position[3]},rotation={0,180,0},smooth=false})
		if token~=nil then destroySite(token,targetHex.terrain,targetHex.bearing,targetHex.position) token.lock() end
	end
	local oldHead=tonumber(gStates.apocalypseDragonHeadLevels~=nil and gStates.apocalypseDragonHeadLevels[name] or 0) or 0
	if oldHead>0 and oldHead<12 then apocalypseDragonSetHeadLevel(name,oldHead+1) end
	state.sitesDestroyed=(tonumber(state.sitesDestroyed) or 0)+1
	local report=name.." destroyed "..proxyFeatureDisplayName(targetHex.feature).." and raised the "..name.." Dragon head from Level "..tostring(oldHead).." to Level "..tostring(math.min(12,oldHead+1)).."."
	if state.sitesDestroyed>=4 then
		state.retired=true state.revealed=false state.removedAfterFour=true
		local token=getObjectFromGUID(data.tokenGUID)
		local apocBag=getObjectFromGUID(GUID.bag.apocalypseDragon)
		if token~=nil then token.unlock() if apocBag~=nil then apocBag.putObject(token) else token.setPosition({0,-20,0}) end end
		monsterPugs[data.tokenGUID]=nil
		if gStates.monsterPerks~=nil then gStates.monsterPerks[data.tokenGUID]=nil end
		report=report.." It has destroyed four sites and leaves the map."
	elseif (tonumber(state.level) or 1)>1 then
		state.level=state.level-1
		setHorsemanLevel(name,state.level,false)
		report=report.." "..name.." drops to Level "..tostring(state.level).."."
	end
	gStates.apocalypseHereHorsemenTurnReport=(gStates.apocalypseHereHorsemenTurnReport or "")..((gStates.apocalypseHereHorsemenTurnReport or "")~="" and "\n" or "")..report
	return true
end

function apocalypseIsHereResolveHorsemanTarget(name,option)
	local options,startHex,hexes=apocalypseIsHereHorsemanTargetOptions(name)
	local target=option~=nil and option.hex or nil
	if startHex==nil or target==nil then apocalypseIsHereContinueHorsemenTurn() return false end
	local destination=apocalypseIsHereHorsemanDestination(startHex,target,hexes)
	local data=horsemanData[name]
	local state=gStates.horsemen[name]
	local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
	if token==nil or destination==nil then apocalypseIsHereContinueHorsemenTurn() return false end
	state.terrainGUID=destination.terrainGUID state.bearing=destination.bearing
	token.unlock() token.setRotation({0,180,0}) token.setPositionSmooth({destination.position[1],1.42,destination.position[3]},false)
	Wait.condition(function()
		local reached=apocalypseQuestMapHexKey(destination)==apocalypseQuestMapHexKey(target)
		if reached then apocalypseIsHereHorsemanDestroyTarget(name,target)
		else
			local line=name.." moved two spaces toward "..proxyFeatureDisplayName(target.feature).."."
			gStates.apocalypseHereHorsemenTurnReport=(gStates.apocalypseHereHorsemenTurnReport or "")..((gStates.apocalypseHereHorsemenTurnReport or "")~="" and "\n" or "")..line
		end
		apocalypseIsHereContinueHorsemenTurn()
	end,function() local current=getObjectFromGUID(data.tokenGUID) return current==nil or current.isSmoothMoving()==false end,5,function() apocalypseIsHereContinueHorsemenTurn() end)
	return true
end

function apocalypseIsHereProcessNextHorseman()
	if gStates.apocalypseHereHorsemenTurnActive~=true then return end
	local queue=gStates.apocalypseHereHorsemenQueue or {}
	local index=tonumber(gStates.apocalypseHereHorsemenQueueIndex) or 1
	local name=queue[index]
	if name==nil then
		gStates.apocalypseHereHorsemenUIState="ReadyToEnd"
		if (gStates.apocalypseHereHorsemenTurnReport or "")=="" then gStates.apocalypseHereHorsemenTurnReport="The Horsemen had no action to resolve." end
		mainUIUpdate("Horsemen Processed")
		return
	end
	gStates.apocalypseHereHorsemenQueueIndex=index+1
	local options=apocalypseIsHereHorsemanTargetOptions(name)
	if #options<1 then
		local line=name.." found no preferred undestroyed target and did not move."
		gStates.apocalypseHereHorsemenTurnReport=(gStates.apocalypseHereHorsemenTurnReport or "")..((gStates.apocalypseHereHorsemenTurnReport or "")~="" and "\n" or "")..line
		Wait.frames(apocalypseIsHereProcessNextHorseman,1)
	elseif #options>1 then apocalypseIsHereShowTargetChoice(name,options)
	else apocalypseIsHereResolveHorsemanTarget(name,options[1]) end
end

function apocalypseIsHereContinueHorsemenTurn()
	if gStates.apocalypseHereHorsemenTurnActive~=true then return end
	gStates.apocalypseHereHorsemenUIState="Processing"
	Wait.frames(apocalypseIsHereProcessNextHorseman,2)
end

function apocalypseIsHereActiveHorsemen()
	local list={}
	for _,name in ipairs(gStates.apocalypseHereHorsemanOrder or {}) do
		local state=gStates.horsemen~=nil and gStates.horsemen[name] or nil
		local data=horsemanData~=nil and horsemanData[name] or nil
		if state~=nil and data~=nil and state.revealed==true and state.defeated~=true and state.retired~=true and getObjectFromGUID(data.tokenGUID)~=nil then list[#list+1]=name end
	end
	return list
end

function apocalypseIsHereBeginHorsemenTurn(nextTurnNumber,newOutOfTurn,sameTurn)
	if apocalypseIsHereActive()~=true or gStates.apocalypseHereHorsemenEnded==true or gStates.apocalypseDragonLairAttacked==true then return false end
	if gStates.endRoundCalled==true or gStates.endGameAchieved~="false" or gStates.tacticShown==true then return false end
	local queue=apocalypseIsHereActiveHorsemen()
	if #queue<1 then return false end
	gStates.apocalypseHereHorsemenTurnActive=true
	gStates.apocalypseHereHorsemenResumeTurn={turnNumber=nextTurnNumber,newOutOfTurn=newOutOfTurn,sameTurn=sameTurn}
	gStates.apocalypseHereHorsemenQueue=queue
	gStates.apocalypseHereHorsemenQueueIndex=1
	gStates.apocalypseHereHorsemenTurnReport="The revealed Horsemen are preparing to move in reveal order."
	gStates.apocalypseHereHorsemenUIState="ReadyToProcess"
	mainUIUpdate("Horsemen Turn")
	return true
end

function apocalypseIsHereMainUIPanelSpec()
	if apocalypseIsHereActive()~=true or gStates.apocalypseHereHorsemenTurnActive~=true then return nil end
	local state=gStates.apocalypseHereHorsemenUIState
	local label="{en}Processing Horsemen...{ru}Processing Horsemen...{zh-tw}Processing Horsemen...{zh-cn}Processing Horsemen...{ko}Processing Horsemen...{es}Processing Horsemen...{fr}Processing Horsemen...{pt-br}Processing Horsemen...{de}Processing Horsemen..."
	local active=false
	if state=="ReadyToProcess" then label="{en}Process Horsemen{ru}Process Horsemen{zh-tw}Process Horsemen{zh-cn}Process Horsemen{ko}Process Horsemen{es}Process Horsemen{fr}Process Horsemen{pt-br}Process Horsemen{de}Process Horsemen" active=true
	elseif state=="ReadyToEnd" then label="{en}Horsemen Processed{ru}Horsemen Processed{zh-tw}Horsemen Processed{zh-cn}Horsemen Processed{ko}Horsemen Processed{es}Horsemen Processed{fr}Horsemen Processed{pt-br}Horsemen Processed{de}Horsemen Processed" active=true
	elseif state=="WaitingChoice" then label="{en}Pick Target{ru}Pick Target{zh-tw}Pick Target{zh-cn}Pick Target{ko}Pick Target{es}Pick Target{fr}Pick Target{pt-br}Pick Target{de}Pick Target" end
	return {actor="horsemen",mainText="<size=25>Horsemen's Turn</size><size=6>\n\n</size>The Horsemen act in the order they were revealed.",notes=gStates.apocalypseHereHorsemenTurnReport or "Process the Horsemen.",onClick="apocalypseIsHereProcessHorsemenUI",label=label,interactable=active}
end

function apocalypseIsHereMainUIRefresh()
	local spec=apocalypseIsHereMainUIPanelSpec()
	if spec==nil then return false end
	return automatedMainPanelApply(spec)
end

function apocalypseIsHereProcessHorsemenUI(player,mouseButton,id)
	if mouseButton~="-1" or apocalypseIsHereActive()~=true or gStates.apocalypseHereHorsemenTurnActive~=true then return end
	if gStates.apocalypseHereHorsemenUIState=="ReadyToEnd" then apocalypseIsHereFinishHorsemenTurn() return end
	if gStates.apocalypseHereHorsemenUIState~="ReadyToProcess" then return end
	gStates.apocalypseHereHorsemenUIState="Processing"
	gStates.apocalypseHereHorsemenTurnReport=""
	apocalypseIsHereProcessNextHorseman()
end

function apocalypseIsHereFinishHorsemenTurn()
	if gStates.apocalypseHereHorsemenTurnActive~=true then return false end
	apocalypseIsHereClearChoiceButtons()
	UI.setAttribute("DummyTurn","active","false")
	local resume=gStates.apocalypseHereHorsemenResumeTurn
	gStates.apocalypseHereHorsemenTurnActive=false
	gStates.apocalypseHereHorsemenResumeTurn=nil
	gStates.apocalypseHereHorsemanPendingChoice=nil
	gStates.apocalypseHereHorsemenUIState=nil
	if resume~=nil then mergedTurnCommit(resume.turnNumber,resume.newOutOfTurn,resume.sameTurn) end
	return true
end

function apocalypseIsHereEndHorsemen()
	if apocalypseIsHereActive()~=true or gStates.apocalypseHereHorsemenEnded==true then return false end
	gStates.apocalypseHereHorsemenEnded=true
	gStates.apocalypseHereForcedRevealPending=false
	gStates.apocalypseHereForcedRevealCount=0
	apocalypseIsHereClearChoiceButtons()
	local bag=getObjectFromGUID(GUID.bag.apocalypseDragon)
	for name,state in pairs(gStates.horsemen or {}) do
		if state.defeated~=true then
			state.retired=true state.removedByDragon=true state.revealed=false
			local data=horsemanData[name]
			local token=data~=nil and getObjectFromGUID(data.tokenGUID) or nil
			if token~=nil then token.unlock() if bag~=nil then bag.putObject(token) else token.setPosition({0,-20,0}) end end
			if data~=nil then monsterPugs[data.tokenGUID]=nil if gStates.monsterPerks~=nil then gStates.monsterPerks[data.tokenGUID]=nil end end
		end
	end
	broadcastToAll("The Apocalypse Dragon has been attacked. Every Horseman still on the map is removed; this does not count as defeating them.",{1,0.75,0.2})
	return true
end

function apocalypseIsHereDragonCitySpacePlayer(playerIndex)
	if apocalypseIsHereActive()~=true or gStates.apocalypseDragonLair==nil then return false end
	local player=turnOrder[playerIndex]
	if player==nil then return false end
	local pos=fracturedLandsTeleportSourcePosition~=nil and fracturedLandsTeleportSourcePosition(playerIndex) or nil
	if pos==nil then local avatar=coopAssaultAvatarObject(playerIndex) if avatar~=nil then pos=avatar.getPosition() end end
	if pos==nil then return false end
	for _,hex in ipairs(gStates.apocalypseDragonLair.hexes or {}) do
		if hex.formerCity==true and hex.position~=nil and ((pos[1]-hex.position[1])^2)+((pos[3]-hex.position[3])^2)<2.25 then return true end
	end
	return false
end

function factionLeaderForCity(cityGUID)
	if cityGUID==elementalist.terrainHex then return elementalist end
	if cityGUID==darkCrusader.terrainHex then return darkCrusader end
	return nil
end

function setFactionLeaderLevel(cityGUID, level)
	local currentLeader=factionLeaderForCity(cityGUID)
	local levelData=currentLeader~=nil and leaderData[currentLeader.terrainHex] or nil
	level=math.min(tonumber(level) or 1, 12)
	if currentLeader==nil or levelData==nil or levelData[level]==nil then return false end
	local disc=getObjectFromGUID(currentLeader.disc)
	local token=getObjectFromGUID(currentLeader.token)
	if disc~=nil then disc.setCustomObject({image=levelData[level].discImg}) disc.reload() end
	if token~=nil then
		token.setCustomObject({image=levelData[level].tokenImg})
		token.setName((currentLeader==elementalist and "Elementalist" or "Dark Crusader").." Leader Level "..level)
		token.reload()
	end
	monsterPugs[currentLeader.token]=levelData[level].abilities
	if currentLeader==elementalist then gStates.elementalistLevel=level else gStates.darkCrusaderLevel=level end
	if gStates.cityMonsterQty[cityGUID]~=nil then gStates.cityMonsterQty[cityGUID][currentLeader.token]="alive" end
	return true
end

function cityArmyLevelData(cityGUID, cityLevel)
	cityLevel=tonumber(cityLevel)
	local cityArmy=CITY_ARMY_DATA[cityGUID]
	local cityArmyLevel=cityArmy~=nil and cityLevel~=nil and cityArmy[cityLevel] or nil
	if cityArmyLevel==nil and isStandardCityGUID(cityGUID) and cityLevel~=nil and cityLevel>11 then
		local baseLevel=9+((cityLevel-9)%3)
		local extraWhite=math.floor((cityLevel-baseLevel)/3)
		cityArmyLevel={}
		for index=1, 6 do cityArmyLevel[index]=cityArmy[baseLevel][index] end
		cityArmyLevel[1]=cityArmyLevel[1]+extraWhite
	end
	return cityArmyLevel
end

function cityDefenderPile(cityGUID, tokenType)
	local standardGUID=CITY_STANDARD_PILES[tokenType]
	local faction=cityGUID==elementalist.terrainHex and "Elem" or cityGUID==darkCrusader.terrainHex and "Dark" or nil
	local pileGUID, substitute=factionMonsterPileGUID(standardGUID, faction)
	local pile=pileGUID~=nil and getObjectFromGUID(pileGUID) or nil
	if pile~=nil and pile.getQuantity()>0 then return pile, substitute==true and faction or nil end
	return nil, nil
end

function takeCityDefender(cityGUID, tokenType, position, rotation)
	local pile, substituteFaction=cityDefenderPile(cityGUID, tokenType)
	if pile==nil then
		broadcastToAll("{en}Sorry, there are no tokens left to deploy{zh-cn}抱歉，没有token可供部署{ko}여분의 토큰이 없습니다{es}Lo sentimos, no quedan tokens para implementar{fr}Désolé, il n'y a plus de jetons à déployer{pt-br}Desculpe, Não tem Fichas sobrando para distribuir", warningColor)
		return nil
	end
	local token=pile.takeObject({position=position, rotation=rotation, smooth=true})
	if token==nil then return nil end
	markMonsterFactionSubstitute(token, substituteFaction)
	gStates.monsterPlayLocation[token.guid]={position[1], position[2], position[3]}
	if cityGUID==darkCrusader.terrainHex then
		token.addDecal({name="NightRules", position={0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}, url=nightRulesDecal})
		if gStates.monsterPerks[token.guid]==nil then gStates.monsterPerks[token.guid]={nightRules=true} else gStates.monsterPerks[token.guid].nightRules=true end
	end
	return token
end

function cityGarrisonBasePosition(cityGUID, ownerGUID, megapolis)
	local currentLeader=factionLeaderForCity(cityGUID)
	if cityGUID==volkare.terrainHex then
		local disc=getObjectFromGUID(volkare.disc)
		if disc~=nil then local pos=disc.getPosition() return {pos[1]+5.5, 1.0, pos[3]-1.3}, {0,180,180} end
	elseif currentLeader~=nil then
		local disc=getObjectFromGUID(currentLeader.disc)
		if disc~=nil then local pos=disc.getPosition() return {pos[1]-5.5, 1.0, pos[3]-1.3}, {0,180,0} end
	end
	local cardGUID=gStates.cityCard[ownerGUID or cityGUID]
	local card=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
	if card~=nil then
		local pos=card.getPosition()
		return {pos[1]+1.16, 1.0, pos[3]-(megapolis==true and 1.8 or 1.0)}, {0,180,180}
	end
	return {-49,1.0,0}, {0,180,180}
end

--Standalone City army deployment. startDelay/stackIndex let both halves of a Megapolis share one orderly stack
--without relying on a closure created inside playCity(). Returns the next delay and stack index.
function cityArmyPlace(cityGUID, cityLevel, basePosition, rotation, startDelay, stackIndex, ownerGUID)
	local army=cityArmyLevelData(cityGUID, cityLevel)
	if army==nil then
		broadcastToAll("Unable to deploy City army: no data for GUID "..tostring(cityGUID).." at level "..tostring(cityLevel)..".", warningColor)
		return startDelay or 0, stackIndex or 0
	end
	ownerGUID=ownerGUID or cityGUID
	local ownerData=gStates.cityMonsterQty[ownerGUID]
	if ownerData==nil then return startDelay or 0, stackIndex or 0 end
	local delay=startDelay or 0
	local stack=stackIndex or 0
	for tokenType=1, 6 do
		local quantity=army[tokenType] or 0
		if tokenType==3 and gStates.gameScenario=="The Chaos Rift" then quantity=quantity+1 end
		for _=1, quantity do
			delay=delay+5
			stack=stack+1
			local tokenDelay=delay
			local tokenStack=stack
			Wait.frames(function() tokenRefill() end, math.max(1, tokenDelay-4))
			Wait.frames(function()
				local pos={basePosition[1], basePosition[2]+(0.2*tokenStack), basePosition[3]+(0.4*tokenStack)}
				local token=takeCityDefender(cityGUID, tokenType, pos, rotation)
				if token~=nil and gStates.cityMonsterQty[ownerGUID]~=nil then gStates.cityMonsterQty[ownerGUID][token.guid]="alive" end
			end, tokenDelay)
		end
	end
	ownerData.extra.shieldsThere=0
	if CITY_PERK[cityGUID]~=nil then
		if ownerData.extra.monsterPerk==nil then ownerData.extra.monsterPerk={"Fortified"} end
		ownerData.extra.monsterPerk[#ownerData.extra.monsterPerk+1]=CITY_PERK[cityGUID]
	end
	return delay, stack
end

function returnCityGarrisonTokens(cityGUID)
	local data=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[cityGUID] or nil
	if data==nil then return end
	local leader=factionLeaderForCity(cityGUID)
	local leaderToken=leader~=nil and leader.token or nil
	for monsterGUID, _ in pairs(data) do
		if monsterGUID~="extra" and monsterGUID~="shieldNeeded" and monsterGUID~=leaderToken then
			local monster=getObjectFromGUID(monsterGUID)
			if monster~=nil then
				local rotationValues=monster.getRotationValues()
				local pugType=rotationValues~=nil and rotationValues[2]~=nil and rotationValues[2].value or nil
				local pileGUID=pugType~=nil and CITY_DEFENDER_PILE_BY_NAME[pugType] or nil
				if pileGUID~=nil and getObjectFromGUID(pileGUID)==nil and CITY_DEFENDER_FALLBACK[pugType]~=nil then pileGUID=CITY_DEFENDER_PILE_BY_NAME[CITY_DEFENDER_FALLBACK[pugType]] end
				local pile=pileGUID~=nil and getObjectFromGUID(pileGUID) or nil
				if pile~=nil then
					gStates.monsterPerks[monsterGUID]=nil
					gStates.monsterPlayLocation[monsterGUID]=nil
					monster.setDecals({})
					pile.putObject(monster)
				end
			end
		end
	end
end

function resetCityGarrisonData(cityGUID)
	cityMaintenanceLockSeen[cityGUID]=nil
	local oldData=gStates.cityMonsterQty[cityGUID] or {extra={}}
	local storedExtra=rawget(oldData,"extra")
	local newExtra={}
	if type(storedExtra)=="table" then
		newExtra.terainGUID=storedExtra.terainGUID
		newExtra.levelLocked=storedExtra.levelLocked
		newExtra.megapolisPair=storedExtra.megapolisPair
		newExtra.megapolisPending=storedExtra.megapolisPending
		newExtra.megapolisOriginalFeature=storedExtra.megapolisOriginalFeature
	end
	local newData={extra=newExtra}
	local leader=factionLeaderForCity(cityGUID)
	if leader~=nil then rawset(newData,leader.token,"alive") end
	gStates.cityMonsterQty[cityGUID]=newData
	local pair=newData.extra.megapolisPair
	if pair~=nil and pair~=cityGUID then gStates.cityMonsterQty[pair]=newData end
	return newData
end

function cityObjectsReady(cityGUID)
	if cityMegapolisPending(cityGUID)==true then return false end
	local cityObj=getObjectFromGUID(cityGUID)
	if cityObj~=nil and cityObj.resting~=true then return false end
	local pair=cityMegapolisPair(cityGUID)
	if pair~=nil and pair~=cityGUID then
		local pairObj=getObjectFromGUID(pair)
		if pairObj~=nil and pairObj.resting~=true then return false end
	end
	local cardGUID=gStates.cityCard~=nil and gStates.cityCard[cityGUID] or nil
	local card=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
	if card~=nil and card.resting~=true then return false end
	return true
end

function disableCityControls(cityGUID, terrainGUID)
	local cityObj=getObjectFromGUID(cityGUID)
	if cityObj==nil then return end
	for _, suffix in ipairs({"LevelUp", "LevelDown", "MegapolisAdd", "MegapolisSubtract"}) do cityObj.UI.setAttribute(cityGUID..terrainGUID..suffix, "onClick", "") end
end

function rebuildCityGarrisonNow(cityGUID, terrainGUID)
	if terrainGUID=="Volkar" then volkareArmy() cityLevelButtons(cityGUID, terrainGUID) return end
	local order=gStates.cityDeployOrder[cityGUID]
	local level=order~=nil and gStates.cityLevels[order] or nil
	if level==nil or level<=0 then addCityButtons() return end
	returnCityGarrisonTokens(cityGUID)
	local data=resetCityGarrisonData(cityGUID)
	local delay=0
	local stack=0
	local leader=factionLeaderForCity(cityGUID)
	if leader~=nil then
		setFactionLeaderLevel(cityGUID, level)
		local basePos, rotation=cityGarrisonBasePosition(cityGUID, cityGUID, false)
		delay, stack=cityArmyPlace(cityGUID, level, basePos, rotation, delay, stack, cityGUID)
	else
		local pair=data.extra.megapolisPair
		local hasPair=pair~=nil and pair~=cityGUID
		local basePos, rotation=cityGarrisonBasePosition(cityGUID, cityGUID, hasPair)
		if hasPair then
			local firstLevel=math.ceil(level/2)
			local secondLevel=math.floor(level/2)
			setCityDisplayLevel(cityGUID, firstLevel)
			setCityDisplayLevel(pair, secondLevel)
			gStates.cityMonsterQty[pair]=data
			delay, stack=cityArmyPlace(cityGUID, firstLevel, basePos, rotation, delay, stack, cityGUID)
			delay, stack=cityArmyPlace(pair, secondLevel, basePos, rotation, delay, stack, cityGUID)
		else
			setCityDisplayLevel(cityGUID, level)
			delay, stack=cityArmyPlace(cityGUID, level, basePos, rotation, delay, stack, cityGUID)
		end
	end
	Wait.frames(function()
		refreshCityScriptZones()
		mainUIUpdate("City garrison rebuilt")
		addCityButtons()
	end, delay+5)
end

function rebuildCityGarrison(cityGUID, terrainGUID)
	Wait.condition(function() rebuildCityGarrisonNow(cityGUID, terrainGUID) end, function() return cityObjectsReady(cityGUID) end)
end

function scheduleCityRebuild(cityGUID, terrainGUID)
	if cityRebuildPause[cityGUID]~=nil then Wait.stop(cityRebuildPause[cityGUID]) end
	cityRebuildPause[cityGUID]=Wait.time(function()
		cityRebuildPause[cityGUID]=nil
		disableCityControls(cityGUID, terrainGUID)
		rebuildCityGarrison(cityGUID, terrainGUID)
	end, 0.5)
end

function megapolisTerrainBearingData(terrainObj)
	local northBearing=40
	local startTileGUID=gStates.gameScenario=="Against the Horsemen Blitz" and GUID.tile.country01 or startTerrain.open
	if getObjectFromGUID(startTileGUID)==nil and gStates.gameScenario~="Against the Horsemen Blitz" then startTileGUID=startTerrain.wedge northBearing=70 end
	local startTile=getObjectFromGUID(startTileGUID)
	if terrainObj==nil or startTile==nil then return 0,northBearing end
	local pos=terrainObj.getPosition()
	local startPos=startTile.getPosition()
	return math.deg(math.atan2(pos[3]-startPos[3],pos[1]-startPos[1])),northBearing
end

function megapolisReturnHexMonsters(terrainObj,hexLocation)
	if terrainObj==nil then return end
	local center=angleToXY(terrainObj,hexLocation)
	local returning={}
	for monsterGUID,pos in pairs(gStates.monsterPlayLocation or {}) do
		if type(pos)=="table" and pos[1]~=nil and pos[3]~=nil and ((pos[1]-center[1])^2)+((pos[3]-center[2])^2)<0.85 then returning[#returning+1]=monsterGUID end
	end
	for _,monsterGUID in ipairs(returning) do
		local monster=getObjectFromGUID(monsterGUID)
		if monster~=nil and monsterPugs[monsterGUID]~=nil then
			local rotationValues=monster.getRotationValues()
			local tokenName=rotationValues~=nil and rotationValues[2]~=nil and rotationValues[2].value or nil
			local pileGUID=tokenName~=nil and CITY_DEFENDER_PILE_BY_NAME[tokenName] or nil
			if pileGUID==nil then pileGUID=monsterPiles[monsterPugs[monsterGUID].pugType] end
			local pile=pileGUID~=nil and getObjectFromGUID(pileGUID) or nil
			if gStates.mineMonsterQty~=nil and gStates.mineMonsterQty[terrainObj.guid]~=nil then gStates.mineMonsterQty[terrainObj.guid][monsterGUID]=nil end
			if pile~=nil then pile.putObject(monster) else monster.destruct() end
		end
	end
end

function megapolisRemoveGraveyardMarker(terrainObj,hexLocation)
	if terrainObj==nil then return end
	local center=angleToXY(terrainObj,hexLocation)
	local map=getObjectFromGUID(mapArea)
	if map==nil then return end
	for _,obj in pairs(map.getObjects()) do
		if obj.guid~=terrainObj.guid and monsterPugs[obj.guid]==nil and terrainTiles[obj.guid]==nil then
			local pos=obj.getPosition()
			if ((pos[1]-center[1])^2)+((pos[3]-center[2])^2)<0.35 and (obj.type=="Custom_Tile" or obj.tag=="Custom_Tile") then obj.destruct() break end
		end
	end
end

function megapolisRemoveMonasteryOffer()
	if (gStates.monasteryCount or 0)<=0 then return end
	local monasteryOffer={"b7cb3b","d925e4","caf03e","5c4c6d","d51391","7700a8"}
	for i=#monasteryOffer,1,-1 do
		local zone=getObjectFromGUID(monasteryOffer[i])
		if zone~=nil then
			for _,card in pairs(zone.getObjects()) do
				if card.type=="Card" and gameCardType(card)=="Advanced Action" then
					local deck=standardDeckCycleObject("Advanced Action")
					if deck~=nil then standardDeckCycleMarkReturned("Advanced Action",card) putCardAtBottom(deck,card) else card.destruct() end
					gStates.monasteryCount=math.max(0,(gStates.monasteryCount or 0)-1)
					return
				end
			end
		end
	end
	gStates.monasteryCount=math.max(0,(gStates.monasteryCount or 0)-1)
end

function megapolisSuppressTerrainHex(terrainObj,originalFeature,removeDeployedObjects)
	if terrainObj==nil or terrainTiles[terrainObj.guid]==nil then return nil,nil end
	local hexLocation=cityTerrainRotationKey(terrainObj)
	local feature=originalFeature
	if feature==nil or feature=="city" then feature=terrainTiles[terrainObj.guid].hexFeature[hexLocation] end
	gStates.megapolisOriginalFeatureByTerrain=gStates.megapolisOriginalFeatureByTerrain or {}
	if gStates.megapolisOriginalFeatureByTerrain[terrainObj.guid]==nil then gStates.megapolisOriginalFeatureByTerrain[terrainObj.guid]=feature end
	if removeDeployedObjects==true then
		megapolisReturnHexMonsters(terrainObj,hexLocation)
		if feature=="graveyard" then megapolisRemoveGraveyardMarker(terrainObj,hexLocation) end
		if feature=="monastery" then megapolisRemoveMonasteryOffer() end
	end
	terrainTiles[terrainObj.guid].hexFeature[hexLocation]="city"
	gStates.hexOverideSave[terrainObj.guid]=gStates.hexOverideSave[terrainObj.guid] or {}
	gStates.hexOverideSave[terrainObj.guid][hexLocation]="city"
	return feature,hexLocation
end

function megapolisWarOfFourGladeOnFactionEdge(terrainObj)
	if terrainObj==nil then return false end
	local pos=terrainObj.getPosition()
	local edgeCoordinates={{-38.43,0.54},{-33.63,4.70},{-28.83,8.86},{-24.03,13.02},{0,0},{-37.23,-5.69},{-32.43,-1.52},{-27.63,2.62},{-22.83,6.79},{-18.02,10.94},{-30.03,-14.01},{-25.23,-9.84},{-20.43,-5.69},{-15.63,-1.54},{-10.81,2.63},{-24.03,-16.08},{-19.23,-11.93},{-14.43,-7.77},{-9.63,-3.61}}
	for _,coords in pairs(edgeCoordinates) do if ((pos[1]-coords[1])^2)+((pos[3]-coords[2])^2)<1 then return true end end
	return false
end

function megapolisDeployWarOfFourGlade(terrainObj,hexLocation,faction,graveyard)
	local center=angleToXY(terrainObj,hexLocation)
	gStates.mineMonsterQty[terrainObj.guid]=gStates.mineMonsterQty[terrainObj.guid] or {}
	if graveyard==true then
		local grave=getObjectFromGUID(GUID.bag.cemetery).takeObject({rotation={0,180,0},position={center[1],1.09,center[2]}})
		if grave~=nil then grave.lock() end
	end
	local piles=faction=="Dark" and {monsterPiles.tanDark,monsterPiles.greenDark} or {monsterPiles.tanElem,monsterPiles.greenElem}
	for i,pileGUID in ipairs(piles) do
		local pile=getObjectFromGUID(pileGUID)
		if pile~=nil and pile.getQuantity()>0 then
			local offset=(i-1)*0.2
			local token=pile.takeObject({rotation={0,180,0},position={center[1]-0.1+offset,2+((i-1)*0.5),center[2]-0.1+offset}})
			if token~=nil then
				markMonsterFactionSubstitute(token,faction)
				gStates.monsterPlayLocation[token.guid]=token.getPosition()
				gStates.mineMonsterQty[terrainObj.guid][token.guid]="alive"
				if graveyard==true then
					token.addDecal({name="NightRules",position={0.85,0.15,-0.85},rotation={90,180,0},scale={0.6,0.6,1},url=nightRulesDecal})
					gStates.monsterPerks[token.guid]=gStates.monsterPerks[token.guid] or {}
					gStates.monsterPerks[token.guid].nightRules=true
				end
			end
		end
	end
end

function megapolisRestoreTerrainHex(terrainObj,feature)
	if terrainObj==nil or terrainTiles[terrainObj.guid]==nil then return end
	local hexLocation=cityTerrainRotationKey(terrainObj)
	terrainTiles[terrainObj.guid].hexFeature[hexLocation]=feature or ""
	gStates.hexOverideSave[terrainObj.guid]=gStates.hexOverideSave[terrainObj.guid] or {}
	gStates.hexOverideSave[terrainObj.guid][hexLocation]=feature or ""
	if feature=="monastery" then playMonastery() return end
	if feature=="keep" then
		local pile=getObjectFromGUID(monsterPiles.gray)
		if pile~=nil and pile.getQuantity()>0 then local pos=angleToXY(terrainObj,hexLocation) local token=pile.takeObject({rotation={0,180,180},position={pos[1],2,pos[2]}}) if token~=nil then gStates.monsterPlayLocation[token.guid]={pos[1],2,pos[2]} end end
		return
	end
	if feature=="ruin" then
		local pile=getObjectFromGUID(monsterPiles.yellow)
		if pile~=nil and pile.getQuantity()>0 then local pos=angleToXY(terrainObj,hexLocation) local rotation=gStates.dayRound==false and {0,180,180} or {0,180,0} local token=pile.takeObject({rotation=rotation,position={pos[1],2,pos[2]}}) if token~=nil then gStates.monsterPlayLocation[token.guid]={pos[1],2,pos[2]} end end
		return
	end
	if gStates.gameScenario=="The War of Four" and feature=="graveyard" then megapolisDeployWarOfFourGlade(terrainObj,hexLocation,"Dark",true) return end
	if gStates.gameScenario=="The War of Four" and feature=="glade" and megapolisWarOfFourGladeOnFactionEdge(terrainObj)==true then
		local startBearing,northBearing=megapolisTerrainBearingData(terrainObj)
		local pos=terrainObj.getPosition()
		local elementalist=startBearing<=northBearing or (((startBearing<=northBearing+1 and gStates.coop==1) or (gStates.coop==0 and pos[3]<-7 and pos[3]>-8 and pos[1]<-31 and pos[1]>-32)) and math.random(1,2)==1)
		if elementalist then megapolisDeployWarOfFourGlade(terrainObj,hexLocation,"Elem",false)
		else
			terrainTiles[terrainObj.guid].hexFeature[hexLocation]="graveyard"
			gStates.hexOverideSave[terrainObj.guid][hexLocation]="graveyard"
			megapolisDeployWarOfFourGlade(terrainObj,hexLocation,"Dark",true)
		end
		return
	end
	if feature=="rampaging" or feature=="draconum" or (gStates.gameScenario=="The Chaos Rift" and (feature=="village" or ((feature=="mine" or feature=="") and terrainObj.guid==GUID.tile.city08))) then
		local startBearing,northBearing=megapolisTerrainBearingData(terrainObj)
		playRampagingTokens(terrainObj,startBearing,northBearing,hexLocation,feature,true,startingMapTiles[terrainObj.guid]~=true)
	end
end

function chooseMegapolisPair(cityGUID)
	local choices={}
	for _, possible in ipairs({cityModel.red, cityModel.green, cityModel.blue, cityModel.white}) do if possible~=cityGUID and cityPlayedContains(possible)==false then choices[#choices+1]=possible end end
	if #choices<1 then return nil end
	return choices[math.random(1,#choices)]
end

function cityTerrainRotationKey(terrainObj)
	local rotation=math.floor(((terrainObj.getRotation()[2] or 0)/60)+0.5)*60
	if rotation<0 then rotation=rotation+360 end
	if rotation>=360 then rotation=rotation-360 end
	return tostring(rotation)
end

function createCityMegapolisPair(cityGUID, terrainObj)
	local data=gStates.cityMonsterQty[cityGUID]
	if data==nil or data.extra==nil or data.extra.megapolisPair~=nil or data.extra.megapolisPending==true then return false end
	local pair=chooseMegapolisPair(cityGUID)
	if pair==nil then return false end
	data.extra.megapolisPending=true
	data.extra.megapolisPair=pair
	gStates.cityMonsterQty[pair]=data
	if cityPlayedContains(pair)==false then table.insert(gStates.citiesPlayed, pair) end
	gStates.megapolisPlayed=(gStates.megapolisPlayed or 0)+1
	if terrainObj~=nil then
		local terrainGUID=terrainObj.guid
		local rotationKey=cityTerrainRotationKey(terrainObj)
		local storedOriginal=gStates.megapolisOriginalFeatureByTerrain~=nil and gStates.megapolisOriginalFeatureByTerrain[terrainGUID] or nil
		if storedOriginal==nil then storedOriginal=megapolisSuppressTerrainHex(terrainObj,nil,true) end
		data.extra.megapolisOriginalFeature=storedOriginal
		if gStates.megapolisOriginalFeatureByTerrain~=nil then gStates.megapolisOriginalFeatureByTerrain[terrainGUID]=nil end
		terrainTiles[terrainGUID].hexFeature[rotationKey]=CITY_NAME_BY_GUID[pair]
		if gStates.hexOverideSave[terrainGUID]==nil then gStates.hexOverideSave[terrainGUID]={} end
		gStates.hexOverideSave[terrainGUID][rotationKey]=CITY_NAME_BY_GUID[pair]
		local terrainPos=terrainObj.getPosition()
		local pairObj=getObjectFromGUID(pair)
		if pairObj~=nil then pairObj.setPositionSmooth({terrainPos[1]+2.38, 1.1, terrainPos[3]}) end
	end
	local cardGUID=gStates.cityCard[cityGUID]
	local card=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
	local state=CITY_MEGAPOLIS_MATRIX[cityGUID]~=nil and CITY_MEGAPOLIS_MATRIX[cityGUID][pair] or nil
	if card==nil or state==nil then data.extra.megapolisPending=nil return true end
	Wait.frames(function()
		Wait.condition(function()
			local currentCard=getObjectFromGUID(gStates.cityCard[cityGUID])
			if currentCard==nil then data.extra.megapolisPending=nil return end
			local pos=currentCard.getPosition()
			currentCard.setPosition({pos[1], 0.98, pos[3]+0.65})
			local combined=currentCard.setState(state)
			gStates.cityCard[cityGUID]=combined.guid
			gStates.cityCard[pair]=combined.guid
			combined.lock()
			data.extra.megapolisPending=nil
			refreshCityScriptZones()
		end, function()
			local currentCard=getObjectFromGUID(gStates.cityCard[cityGUID])
			return currentCard==nil or currentCard.resting==true
		end)
	end, 10)
	return true
end

function addCityMegapolis(cityGUID, terrainGUID)
	local state=cityControlState(cityGUID, terrainGUID)
	if state.canAddMegapolis~=true then return false end
	local terrain=getObjectFromGUID(terrainGUID)
	local order=gStates.cityDeployOrder~=nil and gStates.cityDeployOrder[cityGUID] or nil
	if order~=nil and tonumber(gStates.cityLevels[order])~=nil and gStates.cityLevels[order]<2 then gStates.cityLevels[order]=2 end
	gStates.megapolis=(gStates.megapolis or 0)+1
	if createCityMegapolisPair(cityGUID, terrain)==false then gStates.megapolis=gStates.megapolis-1 return false end
	refreshUltimateConquestCityCounts()
	return true
end

function removeCityMegapolis(cityGUID, terrainGUID)
	local state=cityControlState(cityGUID, terrainGUID)
	local data=gStates.cityMonsterQty[cityGUID]
	local pair=data~=nil and data.extra~=nil and data.extra.megapolisPair or nil
	if state.canRemoveMegapolis~=true or pair==nil or pair==cityGUID then return false end
	returnCityGarrisonTokens(cityGUID)
	gStates.megapolis=math.max(0,(gStates.megapolis or 0)-1)
	gStates.megapolisPlayed=math.max(0,(gStates.megapolisPlayed or 0)-1)
	cityRemoveFromPlayed(pair)
	local terrain=getObjectFromGUID(terrainGUID)
	local originalFeature=data.extra.megapolisOriginalFeature or ""
	local start=CITY_START_LOCATION[pair]
	local pairObj=getObjectFromGUID(pair)
	if pairObj~=nil and start~=nil then pairObj.setPositionSmooth(start[1]) end
	local baseCardGUID=CITY_BASE_CARD[pair]
	local baseCard=baseCardGUID~=nil and getObjectFromGUID(baseCardGUID) or nil
	if baseCard~=nil and start~=nil then baseCard.setPositionSmooth(start[2]) baseCard.setRotation({0,180,180}) end
	local cardGUID=gStates.cityCard[cityGUID]
	local card=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
	if card~=nil then
		local pos=card.getPosition()
		card.setPosition({pos[1],0.98,pos[3]-0.65})
		if card.getStateId()~=1 then card=card.setState(1) end
		gStates.cityCard[cityGUID]=card.guid
		card.lock()
	end
	gStates.cityCard[pair]=baseCardGUID
	gStates.cityMonsterQty[pair]=nil
	data.extra.megapolisPair=nil
	data.extra.megapolisPending=nil
	data.extra.megapolisOriginalFeature=nil
	if terrain~=nil and terrainTiles[terrainGUID]~=nil then Wait.frames(function() megapolisRestoreTerrainHex(terrain,originalFeature) end,5) end
	resetCityGarrisonData(cityGUID)
	refreshUltimateConquestCityCounts()
	refreshCityScriptZones()
	return true
end

function cityShouldCreateMegapolis(cityGUID, ultimateCitiesPlayed)
	if (gStates.megapolis or 0)<=0 or (gStates.megapolisPlayed or 0)>=(gStates.megapolis or 0) or isStandardCityGUID(cityGUID)==false then return false end
	if gStates.gameScenario=="Ultimate Conquest" then return ultimateCitiesPlayed>(gStates.cityTiles-gStates.megapolis) end
	return gStates.megapolis>gStates.cityTiles-#gStates.citiesPlayed
end

function cityInitialCardPosition(cityGUID, terrainObj)
	local cardGUID=gStates.cityCard[cityGUID]
	local card=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
	if card==nil then return nil end
	local terrainPos=terrainObj.getPosition()
	local cityPos={terrainPos[1],1.09,terrainPos[3]}
	local mapObjects=cityCardMapSnapshot()
	local movingGUIDs={[cityGUID]=true,[cardGUID]=true}
	local preferred=gStates.gameScenario=="The Gauntlet" and 3 or nil
	local desired=findCityCardPosition(cityPos, mapObjects, movingGUIDs, nil, nil, preferred)
	if desired~=nil then card.setPositionSmooth(desired) return desired end
	return card.getPosition()
end

function cityRegisterDeployOrder(cityGUID, ultimateCitiesPlayed)
	if gStates.cityDeployOrder[cityGUID]~=nil then return gStates.cityDeployOrder[cityGUID] end
	local playedCities=#gStates.citiesPlayed-(gStates.megapolisPlayed or 0)
	if gStates.gameScenario=="Ultimate Conquest" then playedCities=ultimateCitiesPlayed end
	if gStates.gameScenario=="The War of Four" then table.insert(gStates.cityLevels, playedCities, gStates.cityLevels[4]) table.remove(gStates.cityLevels, 5) end
	gStates.cityDeployOrder[cityGUID]=playedCities
	return playedCities
end

function cityLeaderDeployOrder(cityGUID, ultimateCitiesPlayed, leaderLevel)
	if gStates.cityDeployOrder[cityGUID]~=nil then return gStates.cityDeployOrder[cityGUID], gStates.cityLevels[gStates.cityDeployOrder[cityGUID]] end
	local leaderOrder=#gStates.citiesPlayed-(gStates.megapolisPlayed or 0)
	if gStates.gameScenario=="Ultimate Conquest" then leaderOrder=#gStates.cityLevels+1 gStates.cityLevels[leaderOrder]=leaderLevel end
	gStates.cityDeployOrder[cityGUID]=leaderOrder
	return leaderOrder, leaderLevel
end

function deployFriendlyCityShields(cityGUID)
	if gStates.friendlyCity==nil then gStates.friendlyCity={} end
	gStates.friendlyCity[cityGUID]=true
	local cityObj=getObjectFromGUID(cityGUID)
	Wait.frames(function()
		Wait.condition(function()
			refreshCityScriptZones()
			mainUIUpdate("City card move")
			if cityGUID==darkCrusader.terrainHex or cityGUID==elementalist.terrainHex then return end
			local cardGUID=gStates.cityCard[cityGUID]
			local card=cardGUID~=nil and getObjectFromGUID(cardGUID) or nil
			if card==nil then return end
			local tempPos=card.getPosition()
			for seatPos=1,4 do
				local mageName=gStates.positionMageKnight[seatPos]
				local mage=mageKnightsByName~=nil and mageKnightsByName[mageName] or nil
				if mage~=nil and mageName~="nobody" then getObjectFromGUID(mage.shieldContainer).takeObject({position={tempPos[1]-2.5+seatPos,2,tempPos[3]}}) end
			end
			--Standard Dummies never place friendly-City shields. The Proxy is a map player and does.
			if proxyPlayerActive()==true then proxyTakeShield({tempPos[1]+2.5,2,tempPos[3]},false) end
		end, function() return cityObj==nil or cityObj.resting==true end)
	end,10)
end

function resolveCityForTerrain(obj, hexFeature, dropped)
	local cityGUID=""
	if gStates.gameScenario~="Life and Death" and (hexFeature or ""):sub(6,8)=="red" then cityGUID=cityModel.red end
	if gStates.gameScenario~="Life and Death" and (hexFeature or ""):sub(6,10)=="green" then cityGUID=cityModel.green end
	if gStates.gameScenario~="The Realm of the Dead Blitz" and (hexFeature or ""):sub(6,9)=="blue" then cityGUID=cityModel.blue end
	if gStates.gameScenario~="The Hidden Valley Blitz" and (hexFeature or ""):sub(6,10)=="white" then cityGUID=cityModel.white end
	if hexFeature=="Volkare's Camp" then cityGUID=volkare.terrainHex end
	if gStates.hexOverideSave[obj.guid]==nil then gStates.hexOverideSave[obj.guid]={} end
	local randomizeThisCity=gStates.randomCities==true or cityPlayedContains(cityGUID)==true
	if randomizeThisCity==true and dropped==true then
		local choices={cityModel.green,cityModel.blue,cityModel.white,cityModel.red}
		if gStates.volkareCampAsCity==true then choices[#choices+1]=volkare.terrainHex end
		local available={}
		for _, possible in ipairs(choices) do if cityPlayedContains(possible)==false then available[#available+1]=possible end end
		if #available>0 then cityGUID=available[math.random(1,#available)] end
		terrainTiles[obj.guid].hexFeature.center=CITY_NAME_BY_GUID[cityGUID]
		gStates.hexOverideSave[obj.guid].center=CITY_NAME_BY_GUID[cityGUID]
	end
	if gStates.gameScenario=="The Gauntlet" and (hexFeature or ""):sub(6,8)=="red" then cityGUID=cityModel.red end
	if gStates.gameScenario=="Life and Death" and ((hexFeature or ""):sub(6,8)=="red" or hexFeature=="necropolis") then cityGUID=darkCrusader.terrainHex end
	if gStates.gameScenario=="Life and Death" and ((hexFeature or ""):sub(6,10)=="green" or hexFeature=="hidden valley") then cityGUID=elementalist.terrainHex end
	if gStates.gameScenario=="The Realm of the Dead Blitz" and ((hexFeature or ""):sub(6,9)=="blue" or hexFeature=="necropolis") then cityGUID=darkCrusader.terrainHex end
	if gStates.gameScenario=="The Hidden Valley Blitz" and ((hexFeature or ""):sub(6,10)=="white" or hexFeature=="hidden valley") then cityGUID=elementalist.terrainHex end
	if gStates.gameScenario=="Ultimate Conquest" and obj.guid==GUID.tile.core03 then cityGUID=darkCrusader.terrainHex end
	if gStates.gameScenario=="Ultimate Conquest" and obj.guid==GUID.tile.core10 then cityGUID=elementalist.terrainHex end
	local objPos=obj.getPosition()
	if gStates.gameScenario=="The War of Four" and objPos[1]<-22 and objPos[3]>6 then cityGUID=darkCrusader.terrainHex end
	if gStates.gameScenario=="The War of Four" and objPos[1]>-16 and objPos[3]>-8 then cityGUID=elementalist.terrainHex end
	return cityGUID
end

function revealCityInfoCard(cityGUID)
	local infoGUID=CITY_BASE_CARD[cityGUID]
	if infoGUID==nil then return end
	local info=getObjectFromGUID(infoGUID)
	if info~=nil then info.setRotationSmooth({0,180,0}) end
	local generalInfo=getObjectFromGUID("452c86")
	if generalInfo~=nil then generalInfo.setRotationSmooth({0,180,0}) end
end

--Initial City deployment only. Mid-game level and Megapolis controls rebuild the registered City directly and
--never re-run this selection/registration path.
function playCity(obj, hexFeature, dropped)
	local cityGUID=resolveCityForTerrain(obj, hexFeature, dropped)
	if cityGUID==nil or cityGUID=="" then return end
	if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" then gStates.cityRevealed={{model=cityGUID,terrain=obj.guid}} end
	revealCityInfoCard(cityGUID)
	local cityObj=getObjectFromGUID(cityGUID)
	if cityObj~=nil and gStates.gameScenario~="The Lost Relic Blitz" then
		local terrainPos=obj.getPosition()
		cityObj.setPositionSmooth({terrainPos[1],1.09,terrainPos[3]})
		if gStates.cityCard[cityGUID]~=nil and dropped==true then cityInitialCardPosition(cityGUID,obj) end
		table.insert(gStates.citiesPlayed,cityGUID)
		if gStates.ultimateLeaders==nil then gStates.ultimateLeaders=0 end
		if cityGUID==volkare.terrainHex then gStates.cityVolkareTile=obj.guid end
		if gStates.cityMonsterQty[cityGUID]==nil then gStates.cityMonsterQty[cityGUID]={extra={terainGUID=obj.guid}} else gStates.cityMonsterQty[cityGUID].extra.terainGUID=obj.guid end
		local ultimateCitiesPlayed=refreshUltimateConquestCityCounts()
		local leader=factionLeaderForCity(cityGUID)
		if leader~=nil then
			local leaderLevel=gStates.cityLevels[#gStates.citiesPlayed-(gStates.megapolisPlayed or 0)-math.ceil((gStates.megapolisPlayed or 0)/2)]
			if gStates.gameScenario=="Ultimate Conquest" then leaderLevel=ultimateConquestLeaderLevel(ultimateCitiesPlayed) end
			if gStates.gameScenario=="The War of Four" then
				leaderLevel=999
				for _, level in pairs(gStates.cityLevels) do if level<leaderLevel then leaderLevel=level end end
			end
			local order
			order, leaderLevel=cityLeaderDeployOrder(cityGUID, ultimateCitiesPlayed, leaderLevel)
			leaderLevel=math.min(tonumber(leaderLevel) or 1,12)
			gStates.cityLevels[order]=leaderLevel
			setFactionLeaderLevel(cityGUID,leaderLevel)
			if leader==elementalist then
				terrainTiles[obj.guid].hexFeature.center="hidden valley"
				gStates.hexOverideSave[obj.guid].center="hidden valley"
				gStates.monsterPlayLocation[elementalist.token]={-55.3,1.5,15.3}
			else
				terrainTiles[obj.guid].hexFeature.center="necropolis"
				gStates.hexOverideSave[obj.guid].center="necropolis"
				gStates.monsterPlayLocation[darkCrusader.token]={-55.3,1.5,6.7}
			end
			local basePos, rotation=cityGarrisonBasePosition(cityGUID,cityGUID,false)
			local delay=cityArmyPlace(cityGUID,leaderLevel,basePos,rotation,0,0,cityGUID)
			Wait.frames(function() refreshCityScriptZones() mainUIUpdate("City card move") addCityButtons() end, delay+5)
		else
			if cityShouldCreateMegapolis(cityGUID,ultimateCitiesPlayed)==true then createCityMegapolisPair(cityGUID,obj) end
			ultimateCitiesPlayed=refreshUltimateConquestCityCounts()
			local playedCities=cityRegisterDeployOrder(cityGUID,ultimateCitiesPlayed)
			local level=gStates.cityLevels~=nil and gStates.cityLevels[playedCities] or nil
			if level~=nil and level>0 and gStates.gameScenario~="The Lost Relic Blitz" and gStates.gameScenario~="The Realm of the Dead Blitz" and gStates.gameScenario~="Life and Death" and gStates.gameScenario~="The Hidden Valley Blitz" then
				if gStates.gameScenario=="Fury of the Apocalypse Dragon" then deployFriendlyCityShields(cityGUID) end
				Wait.frames(function() rebuildCityGarrison(cityGUID,obj.guid) end,10)
			elseif level~=nil then
				if cityGUID~=darkCrusader.terrainHex and cityGUID~=elementalist.terrainHex then table.insert(gStates.cityLevels,#gStates.citiesPlayed,0) table.remove(gStates.cityLevels,#gStates.cityLevels) end
				deployFriendlyCityShields(cityGUID)
			end
		end
		local cardGUID=gStates.cityCard[cityGUID]
		if cardGUID~=nil then
			Wait.frames(function()
				Wait.condition(function() local card=getObjectFromGUID(gStates.cityCard[cityGUID]) if card~=nil then card.lock() end end,
					function() local card=getObjectFromGUID(gStates.cityCard[cityGUID]) return card==nil or card.resting==true end)
			end,10)
		end
	end
	if gStates.gameScenario=="The Lost Relic Blitz" then
		local pos=obj.getPosition()
		local token=getObjectFromGUID(monsterPiles.red).takeObject({rotation=faceDown,position={pos[1],2,pos[3]}})
		gStates.monsterPlayLocation[token.guid]={pos[1],2,pos[3]}
	end
end

--Keep the non-interactive City level readout visible after its garrison is revealed.
function cityLevelReadoutOnly(cityGUID, terrainGUID)
	local cityObj=getObjectFromGUID(cityGUID)
	if cityObj==nil then return end
	local state=cityControlState(cityGUID,terrainGUID)
	if state.showLevel then
		cityObj.UI.setXmlTable({{tag="Image",attributes={image="Overkill Text",height=50,width=50,position="0 60 -30",rotation="0 0 180"},children={{tag="Text",attributes={id=cityGUID..terrainGUID.."Overkill",color="rgb(0,0,0)",fontSize="35",fontStyle="Bold",alignment="MiddleCenter",text=state.level}}}}})
	else
		cityObj.UI.setXmlTable({{}})
	end
end

--Add arrows to City models. UI visibility and click validation use the same control-state function.
function cityLevelButtons(cityGUID, terrainGUID)
	Wait.time(function()
		local cityObj=getObjectFromGUID(cityGUID)
		if cityObj==nil then return end
		local state=cityControlState(cityGUID,terrainGUID)
		local buttonXML={}
		if state.canLevelUp then
			buttonXML[#buttonXML+1]={tag="Button",attributes={id=cityGUID..terrainGUID.."LevelUp",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",onClick="global/addjustCityLevel",height=50,width=50,color="rgba(0,0,0,0.0)",position="-65 60 -30",rotation="0 0 180"},children={{tag="Image",attributes={id=cityGUID..terrainGUID.."LevelUpImage",image="Overkill Up"}}}}
		end
		if state.showLevel then
			buttonXML[#buttonXML+1]={tag="Image",attributes={image="Overkill Text",height=50,width=50,position="0 60 -30",rotation="0 0 180"},children={{tag="Text",attributes={id=cityGUID..terrainGUID.."Overkill",color="rgb(0,0,0)",fontSize="35",fontStyle="Bold",alignment="MiddleCenter",text=state.level}}}}
		end
		if state.canLevelDown then
			buttonXML[#buttonXML+1]={tag="Button",attributes={id=cityGUID..terrainGUID.."LevelDown",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",onClick="global/addjustCityLevel",height=50,width=50,color="rgba(0,0,0,0.0)",position="65 60 -30",rotation="0 0 180"},children={{tag="Image",attributes={id=cityGUID..terrainGUID.."LevelDownImage",image="Overkill Down"}}}}
		end
		if state.canAddMegapolis then
			buttonXML[#buttonXML+1]={tag="Button",attributes={id=cityGUID..terrainGUID.."MegapolisAdd",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",onClick="global/addjustCityLevel",height=80,width=80,color="rgba(0,0,0,0.0)",position="-100 0 -25",rotation="0 0 180"},children={{tag="Image",attributes={id=cityGUID..terrainGUID.."MegapolisAddImage",image="Megapolis Add"}}}}
		end
		if state.canRemoveMegapolis then
			buttonXML[#buttonXML+1]={tag="Button",attributes={id=cityGUID..terrainGUID.."MegapolisSubtract",onMouseDown="global/buttonClicked",onMouseUp="global/buttonClicked",onClick="global/addjustCityLevel",height=80,width=80,color="rgba(0,0,0,0.0)",position="-100 0 -25",rotation="0 0 180"},children={{tag="Image",attributes={id=cityGUID..terrainGUID.."MegapolisSubtractImage",image="Megapolis Subtract"}}}}
		end
		if #buttonXML==0 then buttonXML={{}} end
		cityObj.UI.setXmlTable(buttonXML)
	end,0.5)
end

--Change an already-deployed City's stored level/Megapolis state, then rebuild only its display and garrison.
function addjustCityLevel(player, mouseButton, id)
	if mouseButton~="-1" then return end
	local cityGUID=id:sub(1,6)
	local terrainGUID=id:sub(7,12)
	local state=cityControlState(cityGUID,terrainGUID)
	local changed=false
	if id:find("LevelUp",1,true)~=nil and state.canLevelUp then
		if terrainGUID=="Volkar" then gStates.volkareLevel=state.level+1 else gStates.cityLevels[gStates.cityDeployOrder[cityGUID]]=state.level+1 end
		changed=true
	elseif id:find("LevelDown",1,true)~=nil and state.canLevelDown then
		if terrainGUID=="Volkar" then gStates.volkareLevel=state.level-1 else gStates.cityLevels[gStates.cityDeployOrder[cityGUID]]=state.level-1 end
		changed=true
	elseif id:find("MegapolisAdd",1,true)~=nil and state.canAddMegapolis then
		changed=addCityMegapolis(cityGUID,terrainGUID)
	elseif id:find("MegapolisSubtract",1,true)~=nil and state.canRemoveMegapolis then
		changed=removeCityMegapolis(cityGUID,terrainGUID)
	end
	if changed then scheduleCityRebuild(cityGUID,terrainGUID) end
end

--Pillage Village, draw two cards for chosen mage and reduce Reputation by 1
function plunderVillage(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(8,8)))==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==tonumber(id:sub(8,8)) then
					broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} just Plundered their Village.{ru} разграбляет деревню.{zh-cn}刚刚劫掠了他们的村庄{ko}: 마을을 약탈했습니다.{es} acaba de saquear su aldea.{fr} vient de Piller leur Village.{pt-br} acabou de Saquear a Vila{de} hat gerade ihr Dorf geplündert. "}), positionToColor(a))
					--One exact two-card request avoids competing Quick Witted prompts for Coral.
					drawExactDeedCards(a, 2, "DrawOne")
					--reduce Reputation by 1
					local repPos=reputationTable[turnOrder[a].reputation-1].reputationPos
					getObjectFromGUID(turnOrder[a].reputationGUID).setPosition({repPos[1], repPos[2], repPos[3]})
					turnOrder[a].reputation=turnOrder[a].reputation-1
					--only alow once per turn
					turnOrder[a].pillagedVillage=true
					mainUIUpdate("Village Pillaged")
					break
				end
			end
		end
	end
end

local coralQuickWittedShufflePause=nil
function scheduleCoralQuickWittedBottom(delayFrames)
	if coralQuickWittedShufflePause~=nil then Wait.stop(coralQuickWittedShufflePause) end
	coralQuickWittedShufflePause=Wait.frames(function() coralQuickWittedShufflePause=nil coralSetAsideQuickWitted() end, delayFrames or 5)
end

--Day Tactic 2 is fully Global-owned. The physical tactic card only hosts this XML-style button.
--Use the tactic card's actual board position to identify its owner. During tactic selection,
--turnOrder can temporarily contain duplicate tactic numbers until everybody has chosen.
function dayTactic2Owner()
	local tactic=getObjectFromGUID("a000a4")
	if tactic==nil or gStates.dayRound~=true or gStates.tacticRemove==true then return nil, nil end
	local tacticPos=tactic.getPosition()
	if tacticPos[3]>=-15 then return nil, nil end
	local seatPos=math.ceil((tacticPos[1]+78)/40)
	for a=1, #turnOrder, 1 do
		if turnOrder[a].seatPos==seatPos and turnOrder[a].tactic==2 and turnOrder[a].mage~=gStates.positionMageKnight[5] then return a, seatPos end
	end
	return nil, nil
end

function dayTactic2ButtonActivate()
	local tactic=getObjectFromGUID("a000a4")
	if tactic==nil then return end
	--While the card is still in the tactic offer, leave its normal claim/remove UI alone.
	--Once it has reached its owner's board, Rethink can be available immediately even while
	--other players are still choosing tactics.
	local ownerIndex=dayTactic2Owner()
	if ownerIndex==nil then
		return
	end
	tactic.UI.setXmlTable({{}})
	Wait.frames(function()
		local card=getObjectFromGUID("a000a4")
		local currentOwner=dayTactic2Owner()
		if card==nil or currentOwner==nil then return end
		if cardEffectIsVertical(card)==true and gStates.tacticTwoState~="Used" then
			local scale=0.32*0.6521739130434783
			local text="{en}Day Tactic 2\nClick after Card(s) have been discarded{ru}Тактика дня 2\nЩелкните после сброса карт{zh-cn}白天战术卡2\n弃牌后单击此处{ko}낮 전략 2\n버릴 카드를 놓고 클릭하세요.{es}Táctica del día 2\nHaz clic después de descartar carta(s){fr}Tactique de Jour 2\nCliquez après avoir défaussé la/les carte(s){pt-br}Tática do Dia 2\nClique depois de descartar a(s) carta(s){de}Tagestaktik 2\nNach dem Abwerfen der Karte(n) klicken"
			card.UI.setXmlTable({{tag="Button", attributes={id="a000a4DayTactic2Discard", onClick="global/dayTactic2Discarded", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", height="300", width="650", position="-317 -140 -1", rotation="0 0 180", scale=tostring(scale).." "..tostring(scale)},
				children={{tag="Image", attributes={id="a000a4DayTactic2DiscardImage", image="Sliced Button/Button Object Active", type="Sliced"}},
					{tag="HorizontalLayout", attributes={padding="20 20 20 20"}, children={{tag="Text", attributes={id="a000a4DayTactic2DiscardText", font="Fonts/MKCardText", fontSize="65", fontStyle="Normal", alignment="MiddleCenter", resizeTextForBestFit="true", resizeTextMaxSize="65", text=text}}}}}}})
		end
	end, 10)
end

function dayTactic2SetUsed()
	if gStates.tacticTwoState=="Used" then return end
	gStates.tacticTwoState="Used"
	local tactic=getObjectFromGUID("a000a4")
	if tactic~=nil and tactic.is_face_down==false then tactic.flip() end
	dayTactic2ButtonActivate()
end

--Rethink is only available before its owner has played a card. This is deliberately based on
--the tactic owner's play area, not the active turn, so the tactic can be used during another
--player's turn.
function dayTactic2ExpireIfCardPlayed(seatPos)
	if gStates.tacticTwoState=="Used" then return end
	local ownerIndex, ownerSeat=dayTactic2Owner()
	if ownerIndex==nil or ownerSeat~=seatPos then return end
	local cardCount=cachedPlayAreaCounts(ownerSeat)
	if cardCount<1 then return end
	dayTactic2SetUsed()
end

--Give replacement cards for Day Tactic 2, then shuffle the discarded cards back into the Deed Deck.
function dayTactic2Discarded(player, mouseButton, id)
	if mouseButton~="-1" or player==nil then return end
	local tactic=getObjectFromGUID("a000a4")
	if tactic==nil then return end
	if gStates.tacticTwoState=="Used" then dayTactic2ButtonActivate() return end
	local playerColor=player.color
	local playerPosition=math.ceil((tactic.getPosition()[1]+78)/40)
	if Player[playerColor]~=nil and Player[playerColor].seated==true and playerColor~="Black" and Player[playerColor].getHandTransform()~=nil then playerPosition=math.ceil((Player[playerColor].getHandTransform().position[1]+97.59)/40) end
	local tacticPosition=math.ceil((tactic.getPosition()[1]+78)/40)
	if playerPosition~=tacticPosition then broadcastToAll("That's not for you to decide", warningColor) return end
	local playerIndex=nil
	local playerMage=nil
	for a, details in pairs(turnOrder) do if details.seatPos==playerPosition then playerIndex=a playerMage=details.mage break end end
	if playerIndex==nil or turnOrder[playerIndex].tactic~=2 then return end

	--Clean that player's play area in case cards were discarded there instead of directly onto the discard pile.
	local cardDestination=nil
	local waitTime=0
	for _, playAreaObj in pairs(getObjectFromGUID(playerPlayAreas[playerPosition]).getObjects()) do
		if playAreaObj.tag=="Card" then
			local found=false
			for _, bannerGUID in pairs({"596cfa", "986216", "0b5b32", "e48e44", "8dbce4", "8e4b92", "75a627"}) do if playAreaObj.guid==bannerGUID then found=true break end end
			if playAreaObj.getDescription()=="Quest" then found=true end
			if found==false then
				waitTime=1
				if cardDestination==nil then
					playAreaObj.setRotation({0,180,0})
					playAreaObj.setPosition({(playerPosition*40)-110.32, 1.12, -43.20})
					cardDestination=playAreaObj
				else
					playAreaObj.setPosition({playAreaObj.getPosition()[1], 1.9, playAreaObj.getPosition()[3]})
					cardDestination=cardDestination.putObject(playAreaObj)
				end
			end
		end
	end

	Wait.time(function()
		local discards=nil
		for _, possibleDiscards in pairs(getObjectFromGUID(deedDeckDiscardZones[playerPosition]).getObjects()) do
			if possibleDiscards.tag=="Deck" or possibleDiscards.tag=="Card" then discards=possibleDiscards break end
		end
		if discards==nil then return end
		local drawCount=discards.tag=="Deck" and discards.getQuantity() or 1
		if drawCount>3 then broadcastToAll("You have discarded too many cards", warningColor) return end
		--The use is committed once a valid discard pile has been found. Remove the button now
		--rather than leaving a second click available while the replacement draws are resolving.
		dayTactic2SetUsed()

		local function finishDayTactic2()
			local deedDeck=nil
			for _, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do if possibleDeck.tag=="Deck" or possibleDeck.tag=="Card" then deedDeck=possibleDeck break end end
			if deedDeck~=nil then
				Wait.time(function()
					if deedDeck~=nil and discards~=nil then deedDeck.putObject(discards) end
					Wait.time(function()
						local currentDeck=nil
						for _, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do if possibleDeck.tag=="Deck" then currentDeck=possibleDeck break end end
						if currentDeck~=nil then currentDeck.shuffle() end
						if playerMage=="Coral" then Wait.time(function() coralSetAsideQuickWitted() end, 0.5) end
					end, 1)
				end, 0.5)
			else
				local deckPos=getObjectFromGUID(deedDeckZones[playerPosition]).getPosition()
				discards.setRotation({0,180,180})
				discards.setPosition({deckPos[1],1.5,deckPos[3]})
				Wait.time(function()
					if discards~=nil and discards.tag=="Deck" then discards.shuffle() end
					if playerMage=="Coral" then Wait.time(function() coralSetAsideQuickWitted() end, 0.5) end
				end, 1)
			end
			mainUIUpdate("Day Tactic 2 Used")
		end

		if playerMage=="Coral" then
			coralExternalQuickWittedDraw({seatPos=playerPosition, count=drawCount, sourceId="DrawOne"})
			Wait.condition(function() Wait.time(finishDayTactic2, 0.5) end, function() return coralExternalDrawPending({seatPos=playerPosition})~=true end)
		else
			local deedDeck=nil
			for _, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do if possibleDeck.tag=="Deck" or possibleDeck.tag=="Card" then deedDeck=possibleDeck break end end
			if deedDeck~=nil then
				if deedDeck.tag=="Deck" then for a=1, drawCount, 1 do deedDeck.takeObject({position={(playerPosition*40)-100-(a*0.2), 4.59, -47.55}, rotation={0,180,0}}) end
				elseif drawCount>0 then deedDeck.setPositionSmooth({(playerPosition*40)-100, 4.59, -47.55}) deedDeck.setRotationSmooth({0,180,0}) end
			end
			Wait.time(finishDayTactic2, 0.5)
		end
	end, waitTime)
end

function nightTactic2(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(14,14)))==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==tonumber(id:sub(14,14)) then
					--Find Discard Deck
					for b, discards in pairs(getObjectFromGUID(deedDeckDiscardZones[turnOrder[a].seatPos]).getObjects()) do
						if discards.type=="Deck" then
							--shuffle discard
							discards.shuffle()
							--put three discards in deed deck
							Wait.time(function()
								local deckPos={-74.19+(40*(turnOrder[a].seatPos-1)), 1.50, -43.16}
								discards.takeObject({position=deckPos, smooth=true, rotation={0, 180, 180}})
								discards.takeObject({position=deckPos, smooth=true, rotation={0, 180, 180}})
								discards.takeObject({position=deckPos, smooth=true, rotation={0, 180, 180}})
							end, 0.5)
							break
						end
					end
					--stop from repeating
					gStates.tacticTwoState="Used"
					--flip over tactic
					if getObjectFromGUID("f6ad01").is_face_down==false then getObjectFromGUID("f6ad01").flip() end
					broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} used Tactic to refill Deed Deck with 3 Random discards{ru} использует Тактику 2 и кладет 3 карты из сброса в Колоду деяний{zh-cn}使用战术从弃牌堆中随机拿了3张手牌{ko}: 전략 카드 2 사용. 3장의 버려진 카드로 더미를 채웁니다.{es} usó Táctica para rellenar Deed Deck con 3 descartes aleatorios{fr} utilisé Tactic pour remplir Deed Deck avec 3 défausse aléatoires{pt-br} usou Tática para preencher o Baralho de Façanhas com 3 cartas aleatórias do Discarte.{de} taktik benutzt, um das Tatendeck mit 3 zufälligen Abwürfen aufzufüllen"}), positionToColor(a))
					mainUIUpdate("Night Tactic 2 Used")
					break
				end
			end
		end
	end
end

function nightTactic4(player, mouseButton, id)
	if mouseButton=="-1" then
		local playerPosition=tonumber(id:sub(14,14))
		if legalPlayerCheck(player.color, playerPosition)==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==playerPosition then
					--find positions deed deck
					local deedDeck=nil
					for b, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do
						if possibleDeck.type=="Deck" or possibleDeck.type=="Card" then deedDeck=possibleDeck break end
					end
					--Shuffle Deed Deck
					if deedDeck~=nil then
						--Record the redraw amount before Quick Witted is temporarily removed/reinserted.
						local deckQuantity=deedDeck.type=="Deck" and deedDeck.getQuantity() or 1
						local redrawCount=math.max(0, deckQuantity-turnOrder[a].deedCount)
						deedDeck.shuffle()
						if turnOrder[a].mage=="Coral" then scheduleCoralQuickWittedBottom(5) end
						Wait.time(function()
							--Run one redraw request for the full amount. For Coral this opens the Quick Witted choice
							--with the correct remaining count and keeps the Draw Full button available.
							if redrawCount>0 then coralTactic4Draw(a, redrawCount) end
							--flip Tactic face down
							if getObjectFromGUID("db7aaa").is_face_down==false then getObjectFromGUID("db7aaa").flip() end
							--Update states and buttons
							gStates.tacticFourState="Used"
							broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} used Tactic 4 to redraw hand{ru} использует Тактику 4 для добора{zh-cn}使用战术4重抽手牌{ko}: 전략 카드 4 사용. 카드를 다시 뽑습니다. {es} usé la Táctica 4 para volver a dibujar la mano{fr} utilisé Tactic 4 pour redessiner la main{pt-br} usou a Tática 4 para re-comprar mão.{de} taktik 4 verwendet, um die Hand neu zu ziehen"}), positionToColor(a))
							mainUIUpdate("night Tactic 4 Used")
						end, 1)
					end
				end
			end
		end
	end
end

--Claim Night Tactic 6 cards from the GUIDs recorded when they were stored. Stored cards may
--be loose or may have merged into a Deck, so resolve one GUID at a time and reacquire its container.
local function claimNightTactic6StoredCards(seatPos, callback)
	local storedGUIDs={}
	for _, stored in ipairs(gStates.powerStored or {}) do if stored.guid~=nil then storedGUIDs[#storedGUIDs+1]=stored.guid end end
	local destination={(seatPos*40)-100, 4.59, -47.55}
	local failed={}
	local function moveCard(card, index)
		card.setPosition({destination[1]+((index-1)*0.15), destination[2], destination[3]})
		card.setRotation({0, 180, 0})
	end
	local function resolve(index)
		if index>#storedGUIDs then if callback~=nil then callback(failed) end return end
		local guid=storedGUIDs[index]
		local card=getObjectFromGUID(guid)
		if card~=nil and card.type=="Card" then
			moveCard(card, index)
			Wait.frames(function() resolve(index+1) end, 1)
			return
		end

		--A stored pile can become a Deck. Find the current Deck containing this exact GUID.
		for _, object in pairs(getObjects()) do
			if object.type=="Deck" then
				for _, cardData in pairs(object.getObjects()) do
					if cardData.guid==guid then
						object.takeObject({guid=guid, position={destination[1]+((index-1)*0.15), destination[2], destination[3]}, rotation={0,180,0}, smooth=false, callback_function=function(taken)
							moveCard(taken, index)
							Wait.frames(function() resolve(index+1) end, 1)
						end})
						return
					end
				end
			end
		end
		failed[#failed+1]=guid
		resolve(index+1)
	end
	resolve(1)
end

function nightTactic6(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(18,18)))==true then
			if id:sub(1,17)=="NightTactic6Store" then
				local tactic=getObjectFromGUID("e2af14")
				local seatPos=tonumber(id:sub(18,18)) or math.ceil((tactic.getPosition()[1]+78)/40)
				local playerIndex=nil
				for a, details in pairs(turnOrder) do if details.seatPos==seatPos then playerIndex=a break end end
				if playerIndex==nil then return end

				local function storeTopCard()
					local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
					if deedZone==nil then return end
					local drawn=nil
					for _, deedZoneObj in pairs(deedZone.getObjects()) do
						if deedZoneObj.type=="Card" then
							--Quick Witted is set aside, so skip it and keep looking for a normal Deed card.
							if not (turnOrder[playerIndex].mage=="Coral" and deedZoneObj.guid=="6ecbc6") then
								deedZoneObj.setPositionSmooth({tactic.getPosition()[1], 1.2, tactic.getPosition()[3]})
								deedZoneObj.setRotation({0, 180, 180})
								drawn=deedZoneObj
								break
							end
						end
						if deedZoneObj.type=="Deck" then
							local normalCards=deedZoneObj.getQuantity()
							if turnOrder[playerIndex].mage=="Coral" then
								for _, cardData in pairs(deedZoneObj.getObjects()) do if cardData.guid=="6ecbc6" then normalCards=normalCards-1 break end end
							end
							if normalCards>0 then
								drawn=deedZoneObj.takeObject({position={tactic.getPosition()[1], 1.2, tactic.getPosition()[3]}, rotation={0, 180, 180}})
								break
							end
						end
					end
					if drawn==nil then
						if turnOrder[playerIndex].mage=="Coral" then broadcastToAll("Night Tactic 6: Coral has no normal Deed card available to store.", positionToColor(playerIndex)) end
						return
					end

					--The stored card is no longer in the Deed deck and will later be claimed to hand.
					turnOrder[playerIndex].deedCount=math.max(0,(turnOrder[playerIndex].deedCount or 0)-1)
					gStates.powerStored[#gStates.powerStored+1]={["guid"]=drawn.guid}
					gStates.tacticSixState="Stored"
					scheduleDeedPileDescriptionRefresh(seatPos, "deed")
					mainUIUpdate("Night Tactic 6 Stored")
				end

				--Let Coral's physical set-aside card settle back on the bottom before taking the top card.
				if turnOrder[playerIndex].mage=="Coral" then coralSetAsideQuickWitted() Wait.frames(storeTopCard, 5)
				else storeTopCard() end
				tactic.setPositionSmooth({tactic.getPosition()[1], 4, tactic.getPosition()[3]})
			end
			if id:sub(1,17)=="NightTactic6Claim" then
				local seatPos=tonumber(id:sub(18,18)) or math.ceil((getObjectFromGUID("e2af14").getPosition()[1]+78)/40)
				claimNightTactic6StoredCards(seatPos, function(failed)
					if #failed>0 then
						broadcastToAll("Night Tactic 6 could not find "..tostring(#failed).." stored card(s).", warningColor)
						return
					end
					--Only finish the tactic after every recorded stored card has actually been returned.
					if getObjectFromGUID("e2af14").is_face_down==false then getObjectFromGUID("e2af14").flip() end
					gStates.powerStored={}
					gStates.tacticSixState="Used"
					scheduleDeedPileDescriptionRefresh(seatPos, "deed")
					outOfTurnUIStateKey=nil
					mainUIUpdate("Night Tactic 6 Claimed")
				end)
			end
		end
	end
end

--Motivation Skill Usage. To run via script-motivation({color="Black"}, -1, skillGUID.."xxxxxxxxxxx"..PlayerPos)
function motivation(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(18, 18)))==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==tonumber(id:sub(18, 18)) then
					broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} used a Motivation skill.{ru} использует навык Мотивация.{zh-cn}使用了激励技能{ko}: 스킬 '동기 부여' 사용{es} usó una habilidad de Motivación.{fr} utilisé une compétence de Motivation.{pt-br} usou uma Habilidade de Motivação{de} eine Motivationsfertigkeit eingesetzt."}), positionToColor(a))
					--One exact two-card request keeps the whole Motivation draw inside one Quick Witted choice flow.
					drawExactDeedCards(a, 2, "DrawOne")
					--Gain Fame or mana token
					local lowestFame=1
					for b=2, #turnOrder, 1 do
						if turnOrder[b].mage~=gStates.positionMageKnight[5] then
							if turnOrder[b].fame<turnOrder[lowestFame].fame or turnOrder[lowestFame].mage==gStates.positionMageKnight[5] then lowestFame=b end
						end
					end
					for b=1, #turnOrder, 1 do if turnOrder[b].fame==turnOrder[lowestFame].fame and b~=lowestFame then lowestFame=0 break end end--find ties
					if lowestFame~=0 and turnOrder[lowestFame].seatPos==tonumber(id:sub(18, 18)) then
						local params={position={(gStates.motivationSkill[id:sub(1, 6)].pos*40)-101, 1.65, -39}, rotation={0, 0, 0}, smooth=false}
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 13)=="Red" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.red),params)
							broadcastToAll("{en}Also gained a Red Mana Token.{ru}Также получает Красный жетон маны.{zh-cn}同时增加了一个红色魔晶{ko}빨간색 마나 추가 획득.{es}También ganó una ficha de Maná Roja.{fr}A également gagné un jeton de Mana Rouge.{pt-br}Também ganhou um Marcador de Mana Vermelha.{de}Außerdem erhielt er ein rotes Mana-Plättchen.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 14)=="Blue" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.blue),params)
							broadcastToAll("{en}Also gained a Blue Mana Token.{ru}Также получает Синий жетон маны.{zh-cn}同时增加了一个蓝色魔晶{ko}파란색 마나 추가 획득.{es}También ganó una ficha de Maná Azul.{fr}A également gagné un jeton de Mana Bleu.{pt-br}Também ganhou um Marcador de Mana Azul.{de}Außerdem ein blaues Mana-Plättchen erhalten.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 15)=="White" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.white),params)
							broadcastToAll("{en}Also gained a White Mana Token.{ru}Также получает Белый жетон маны.{zh-cn}同时增加了一个白色魔晶{ko}흰색 마나 추가 획득.{es}También ganó una ficha de Maná Blanca.{fr}A également gagné un jeton de Mana Blanc.{pt-br}Também ganhou um Marcador de Mana Branca.{de}Außerdem erhielt er ein weißes Mana-Plättchen.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 15)=="Green" then
							takeManaCrystal(getObjectFromGUID(GUID.bag.mana.green),params)
							broadcastToAll("{en}Also gained a Green Mana Token.{ru}Также получает Зеленый жетон маны.{zh-cn}同时增加了一个绿色魔晶{ko}녹색 마나 추가 획득.{es}También ganó una ficha de Maná Verde.{fr}A également gagné un jeton de Mana Vert.{pt-br}Também ganhou um Marcador de Mana Verde.{de}Hat auch ein grünes Mana-Plättchen erhalten.", positionToColor(a))
						end
						if gStates.motivationSkill[id:sub(1, 6)].bonus:sub(11, 14)=="Fame" then
							local startingFameToLevel=math.floor(math.sqrt((turnOrder[a].fame-(gStates.scoreIfLooped*turnOrder[a].scoreLoop))+1))
							local newFame=turnOrder[a].fame+1-(gStates.scoreIfLooped*turnOrder[a].scoreLoop)
							local scoreLooped=false
							if newFame>=gStates.scoreIfLooped then newFame=newFame-gStates.scoreIfLooped scoreLooped=true end
							local fameToLevel=math.floor(math.sqrt(newFame+1))
							local startPosition=(newFame-(fameToLevel*fameToLevel))+2
							if scoreLooped==false then startPosition=startPosition+((fameToLevel-startingFameToLevel)*gStates.blitz) end
							local levelRowFameQuantity=(((fameToLevel-1)*cellGainPerLevel)+normalCellAmount)
							local levelRowLength=((fameToLevel-1)*gStates.rowLengthGainPerLevel)+gStates.normalRowLength
							local xOffset=(1/levelRowFameQuantity*levelRowLength)/2
							local yOffset=(heightOfFameBoard/gStates.rowsOnBoard)/2
							local horizontalValue=leftOfFameBoard+(startPosition/levelRowFameQuantity*levelRowLength)-xOffset
							local verticalValue=(topOfFameBoard-((fameToLevel/gStates.rowsOnBoard)*heightOfFameBoard))+yOffset-0.25
							getObjectFromGUID(turnOrder[a].fameGUID).setPosition({horizontalValue, 1.5, verticalValue+((turnOrder[a].seatPos-2.5)/5)})
							recordPlayerFameChange(a, 1)
							broadcastToAll("{en}and gained a Fame also{ru}и получает Славу{zh-cn}也增加了1名望{ko}명성 1 추가 획득.{es}y ganó Fama también{fr}et a également gagné une renommée{pt-br}e também ganhou uma Fama.{de}und auch einen Ruhmespunkt gewonnen", positionToColor(a))
						end
					end
					--flip skill down.
					getObjectFromGUID(id:sub(1, 6)).setRotationSmooth({0, 180, 180})
					getObjectFromGUID(id:sub(1, 6)).setPositionSmooth({gStates.mageSkills[id:sub(1, 6)][1], 1.5, gStates.mageSkills[id:sub(1, 6)][3]})
					--only allow once per round
					gStates.motivationSkill[id:sub(1, 6)].state="used"
					mainUIUpdate("Motivation Skill activated")
					break
				end
			end
		end
	end
end

function masterOfChaosSetup(position)
	masterOfChaosPause=true
	for a=1, #turnOrder, 1 do
		if turnOrder[a].seatPos==position then
			turnOrder[a].masterOfChaos="first played"
			break
		end
	end
	Wait.frames(function() masterOfChaosPause=false end, 80)
	Wait.frames(function() Wait.condition(function()
		gStates.masterOfChaos=math.random(1,6)
		getObjectFromGUID("1ff34f").setCustomObject({image=masterOfChaosData[gStates.masterOfChaos].image})
		getObjectFromGUID("1ff34f").setDescription(masterOfChaosData[gStates.masterOfChaos].description)
		getObjectFromGUID("1ff34f").reload()
		broadcastToAll("{en}'Master of Chaos' start Randomly picked.{ru}Старт «Мастер магии Хаоса» выбирается случайным образом.{zh-cn}“混乱大师”开始随机挑选{ko}스킬 '혼돈의 달인'의 첫 칸이 무작위로 결정되었습니다.{es}Inicio de 'Master of Chaos' Elegido al azar.{fr}Début de 'Master of Chaos' Choisi au hasard.{pt-br}Início de 'Mestre do Caos' é aleatóriamente escolhido.{de}Meister des Chaos' startet Zufällig gewählt.", {1,1,0.5})
	end, function() return getObjectFromGUID("1ff34f").resting end) end, 5)
end

--masterOfChaos
function masterOfChaos(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, tonumber(id:sub(14, 14)))==true then
			for a=1, #turnOrder, 1 do
				if turnOrder[a].seatPos==tonumber(id:sub(14, 141)) then
					broadcastToAll(joinLang({translateWord[turnOrder[a].mage], "{en} incremented 'Master of Chaos' skill.{ru} передвигает навык «Мастер магии Хаоса».{zh-cn}增加了混乱大师技能{ko}: '혼돈의 달인' 스킬 칸 이동{es} se incrementó la habilidad de 'Maestro del Caos'.{fr} compétence 'Maître du Chaos' incrémentée.{pt-br} incrementou a Habilidade 'Mestre do Caos'{de} hat die Fertigkeit 'Meister des Chaos' erhöht."}), positionToColor(a))
					--change skill to next image
					gStates.masterOfChaos=gStates.masterOfChaos+1
					if gStates.masterOfChaos==7 then gStates.masterOfChaos=1 end
					getObjectFromGUID("1ff34f").setCustomObject({image=masterOfChaosData[gStates.masterOfChaos].image})
					getObjectFromGUID("1ff34f").setDescription(masterOfChaosData[gStates.masterOfChaos].description)
					getObjectFromGUID("1ff34f").reload()
					--only allow once per turn
					turnOrder[a].masterOfChaos="incrementented out of turn"
					mainUIUpdate()
					break
				end
			end
		end
	end
end

--Quick Witted remains Set Aside at the bottom of Coral's physical Deed Deck.
--While another Deed card remains above it, the containing Deck is returned so the draw-choice UI can offer Quick Witted.
function coralQuickWittedSetAside(playerIndex)
	local playerDetails=turnOrder[playerIndex]
	if playerDetails==nil or playerDetails.mage~="Coral" or playerDetails.mage==gStates.positionMageKnight[5] or playerDetails.dropoutState~=nil then return nil end
	local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
	if deedZone==nil then return nil end
	for _, obj in pairs(deedZone.getObjects()) do
		if obj.type=="Deck" and obj.getQuantity()>1 then
			for _, cardData in pairs(obj.getObjects()) do if cardData.guid=="6ecbc6" then return obj end end
		end
	end
	return nil
end

--Returns Quick Witted only when it has become Coral's lone physical Deed card.
function coralQuickWittedLastDeedCard(playerIndex)
	local playerDetails=turnOrder[playerIndex]
	if playerDetails==nil or playerDetails.mage~="Coral" or playerDetails.mage==gStates.positionMageKnight[5] or playerDetails.dropoutState~=nil then return nil end
	local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
	if deedZone==nil then return nil end
	for _, obj in pairs(deedZone.getObjects()) do if obj.type=="Card" and obj.guid=="6ecbc6" then return obj end end
	return nil
end

local coralDrawPending=nil
local coralDrawBypass=false
local coralDrawExactCount=nil

--Quick Witted prompts can remain open while turnOrder is re-sorted. Resolve Coral by her fixed board seat instead of a stale turnOrder index.
local function coralDrawPlayerIndex(seatPos)
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.seatPos==seatPos and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then return playerIndex end
	end
	return nil
end

function showCoralDrawChoice(playerIndex, drawCount, sourceId)
	if drawCount<1 or turnOrder[playerIndex]==nil then return end
	local seatPos=turnOrder[playerIndex].seatPos
	if coralDrawPending~=nil and coralDrawPending.seatPos==seatPos then
		coralDrawPending.remaining=coralDrawPending.remaining+drawCount
		drawCount=coralDrawPending.remaining
	else
		coralDrawPending={seatPos=seatPos, remaining=drawCount, sourceId=sourceId}
	end
	UI.setAttribute("CoralDrawChoiceQuestion", "text", tostring(drawCount).." card draw"..(drawCount==1 and "" or "s").." remaining. Replace one draw with Quick Witted?")
	UI.setAttribute("CoralDrawFullPanel", "active", drawCount>1 and "true" or "false")
	UI.setAttribute("CoralDrawChoice", "visibility", positionToColor(playerIndex).."|Black")
	UI.show("CoralDrawChoice")
end

function clearCoralDrawChoice()
	coralDrawPending=nil
	UI.hide("CoralDrawChoice")
end

--A Coral draw can turn a Deck into a lone Card or rebuild it after a manual draw is intercepted.
--Refresh from the scripting zone after TTS has settled so hover text/counts describe the final physical pile.
local function coralScheduleDeedRefresh(seatPos, delayFrames)
	Wait.frames(function()
		scheduleDeedPileDescriptionRefresh(seatPos, "deed")
		scheduleEndRoundDeedStateRefresh(seatPos)
	end, delayFrames or 4)
end

--Returns Coral's player index only when this object is her physical Deed Deck and Quick Witted is still available inside it.
local function coralManualQuickWittedDeck(object)
	if object==nil or object.type~="Deck" then return nil end
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedDeck=coralQuickWittedSetAside(playerIndex)
			if deedDeck~=nil and deedDeck.guid==object.guid then return playerIndex end
			return nil
		end
	end
	return nil
end

--A manual top-card draw creates a Card from the Deck; onPlayerAction therefore does not reliably see the Deck.
--Use the exact container-leave event instead, then check held_by_color a few frames later to distinguish a player drag from scripted draws.
local function coralManualQuickWittedLeaveSource(container)
	if container==nil or container.type~="Deck" then return nil end
	for playerIndex, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return nil end
			local inDeedZone=false
			for _, zoneObj in pairs(deedZone.getObjects()) do
				if zoneObj.guid==container.guid then inDeedZone=true break end
			end
			if inDeedZone==false then return nil end
			for _, cardData in pairs(container.getObjects()) do
				if cardData.guid=="6ecbc6" then return playerIndex end
			end
			if container.remainder~=nil and container.remainder.guid=="6ecbc6" then return playerIndex end
			return nil
		end
	end
	return nil
end

local function coralRestoreManualDraw(playerIndex, deckGuid, card, showChoice)
	if playerIndex==nil or card==nil or card.isDestroyed() then return end
	local seatPos=turnOrder[playerIndex].seatPos
	card.drop()
	Wait.frames(function()
		if card==nil or card.isDestroyed() then return end
		local destination=getObjectFromGUID(deckGuid)
		if destination==nil or destination.type~="Deck" then
			local deedZone=getObjectFromGUID(deedDeckZones[seatPos])
			if deedZone~=nil then
				for _, obj in pairs(deedZone.getObjects()) do
					if obj.guid~=card.guid and (obj.type=="Deck" or obj.type=="Card") then
						destination=obj
						if obj.guid=="6ecbc6" then break end
					end
				end
			end
		end
		if destination==nil or destination.isDestroyed() then return end
		destination.putObject(card)
		coralScheduleDeedRefresh(seatPos, 3)
		if showChoice~=false then Wait.frames(function()
			local currentPlayerIndex=coralDrawPlayerIndex(seatPos)
			if currentPlayerIndex~=nil and coralDrawPending==nil then showCoralDrawChoice(currentPlayerIndex, 1, "DrawOne") end
		end, 5) end
	end, 1)
end

local function coralRunNormalDraw(playerIndex, id, exactCount)
	local previousTurn=gStates.turnNumber
	gStates.turnNumber=playerIndex
	coralDrawBypass=true
	coralDrawExactCount=exactCount
	drawUpTo({color="Black"}, "-1", id)
	coralDrawExactCount=nil
	coralDrawBypass=false
	gStates.turnNumber=previousTurn
end

--Object scripts such as Day Tactic 2 can route Coral draws through the same Quick Witted-aware draw path.
--Track the whole external draw flow, including the few frames where Draw One temporarily closes and then reopens the choice.
local coralExternalDrawSeat=nil
local coralExternalDrawFinishPause=nil
local function coralFinishExternalDraw(seatPos, delayFrames)
	if coralExternalDrawSeat~=seatPos then return end
	if coralExternalDrawFinishPause~=nil then Wait.stop(coralExternalDrawFinishPause) end
	coralExternalDrawFinishPause=Wait.frames(function()
		coralExternalDrawFinishPause=nil
		if coralExternalDrawSeat==seatPos then coralExternalDrawSeat=nil end
	end, delayFrames or 10)
end

function coralExternalQuickWittedDraw(params)
	if params==nil then return end
	local playerIndex=coralDrawPlayerIndex(params.seatPos)
	if playerIndex==nil then return end
	coralExternalDrawSeat=params.seatPos
	local previousTurn=gStates.turnNumber
	gStates.turnNumber=playerIndex
	coralDrawExactCount=tonumber(params.count) or 1
	drawUpTo({color="Black"}, "-1", params.sourceId or "DrawOne")
	coralDrawExactCount=nil
	gStates.turnNumber=previousTurn
	if coralDrawPending==nil or coralDrawPending.seatPos~=params.seatPos then coralFinishExternalDraw(params.seatPos, 10) end
end

function coralExternalDrawPending(params)
	return params~=nil and coralExternalDrawSeat==params.seatPos
end

--Run a scripted exact-count Deed draw as one operation. Coral uses the tracked external
--Quick Witted flow; every other Mage Knight uses the same exact-count draw engine without a prompt.
function drawExactDeedCards(playerIndex, count, sourceId)
	local details=turnOrder[playerIndex]
	count=tonumber(count) or 0
	if details==nil or count<1 then return end
	if details.mage=="Coral" and details.mage~=gStates.positionMageKnight[5] and details.dropoutState==nil then
		coralExternalQuickWittedDraw({seatPos=details.seatPos, count=count, sourceId=sourceId or "DrawOne"})
	else
		coralRunNormalDraw(playerIndex, sourceId or "DrawOne", count)
	end
end

--Night Tactic 4 needs a single multi-card draw request so Coral sees the normal Quick Witted choice,
--including Draw Full, instead of several one-card requests competing with the pending prompt.
function coralTactic4Draw(playerIndex, exactCount)
	local previousTurn=gStates.turnNumber
	gStates.turnNumber=playerIndex
	coralDrawExactCount=exactCount
	drawUpTo({color="Black"}, "-1", "DrawOne")
	coralDrawExactCount=nil
	gStates.turnNumber=previousTurn
end

local function coralTakeQuickWitted(playerIndex)
	local deedDeck=coralQuickWittedSetAside(playerIndex)
	if deedDeck==nil then return false end
	local playerPosition=turnOrder[playerIndex].seatPos
	deedDeck.takeObject({guid="6ecbc6", position={(playerPosition*40)-105, 4.59, -47.55}, rotation={0, 180, 0}, smooth=false, callback_function=function(card) card.setScale({1.5, 1, 1.5}) end})
	turnOrder[playerIndex].deedCount=math.max(0,(turnOrder[playerIndex].deedCount or 0)-1)
	coralScheduleDeedRefresh(playerPosition, 4)
	return true
end

function coralDrawChoice(player, mouseButton, id)
	if mouseButton~="-1" or coralDrawPending==nil or player==nil then return end
	local pending=coralDrawPending
	local playerIndex=coralDrawPlayerIndex(pending.seatPos)
	local playerDetails=playerIndex~=nil and turnOrder[playerIndex] or nil
	if playerDetails==nil or legalPlayerCheck(player.color, pending.seatPos, "NoDummyException")~=true then return end
	if id=="CoralDrawQuickWitted" then
		UI.hide("CoralDrawChoice")
		coralDrawPending=nil
		if coralTakeQuickWitted(playerIndex)==true then
			pending.remaining=pending.remaining-1
			if pending.remaining>0 then Wait.frames(function()
				local currentIndex=coralDrawPlayerIndex(pending.seatPos)
				if currentIndex~=nil then coralRunNormalDraw(currentIndex, pending.sourceId, pending.remaining) end
			end, 2) end
		else
			coralRunNormalDraw(playerIndex, pending.sourceId, pending.remaining)
		end
		coralScheduleDeedRefresh(pending.seatPos, 4)
		if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
	elseif id=="CoralDrawOne" then
		--Keep the choice visible while the single card is dealt; temporarily clear pending input so repeated clicks cannot queue extra draws.
		coralDrawPending=nil
		coralRunNormalDraw(playerIndex, "DrawOne", 1)
		pending.remaining=pending.remaining-1
		if pending.remaining>0 then
			--A few frames is enough for TTS to remove the drawn card from the Deck and update zone contents.
			Wait.frames(function()
				local currentIndex=coralDrawPlayerIndex(pending.seatPos)
				if currentIndex==nil then UI.hide("CoralDrawChoice") return end
				--If the last normal card was just drawn, Quick Witted has become the physical Deed Deck and the remaining draw is mandatory.
				if coralQuickWittedSetAside(currentIndex)==nil then
					UI.hide("CoralDrawChoice")
					coralRunNormalDraw(currentIndex, pending.sourceId, pending.remaining)
					if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
				else
					showCoralDrawChoice(currentIndex, pending.remaining, pending.sourceId)
				end
			end, 4)
		else
			UI.hide("CoralDrawChoice")
			if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
		end
		coralScheduleDeedRefresh(pending.seatPos, 5)
	elseif id=="CoralDrawFull" then
		UI.hide("CoralDrawChoice")
		coralDrawPending=nil
		coralRunNormalDraw(playerIndex, pending.sourceId, pending.remaining)
		coralScheduleDeedRefresh(pending.seatPos, 5)
		if coralExternalDrawSeat==pending.seatPos then coralFinishExternalDraw(pending.seatPos, 10) end
	end
end

--Draw cards from a deed deck into that positions hand
local cardClaim=false
function drawUpTo(player, mouseButton, id)
	if mouseButton=="-1" then
		local playerPosition=turnOrder[gStates.turnNumber].seatPos
		if legalPlayerCheck(player.color, playerPosition)==true then
			if deedTransferBusy(playerPosition)==true then
				Wait.condition(function() drawUpTo(player,mouseButton,id) end,function() return deedTransferBusy(playerPosition)~=true end,10,function() drawUpTo(player,mouseButton,id) end)
				return
			end
			local meditationBonus=0
			if id=="DrawHand" and gStates.meditationDrawBonus~=nil then
				meditationBonus=gStates.meditationDrawBonus[gStates.turnNumber] or 0
				if meditationBonus>0 then
					gStates.meditationDrawBonus[gStates.turnNumber]=nil
					Wait.frames(function() mainUIUpdate("Meditation Draw Bonus Used") end, 1)
				end
			end
			local deedDeck=nil
			for _, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do
				if possibleDeck.type=="Deck" or possibleDeck.type=="Card" then deedDeck=possibleDeck break end
			end
			--Quick Witted is already physically in Coral's Deed Deck; when it is the final card it resolves as a normal single-card Deed Deck.
			if deedDeck~=nil or (id=="DrawHand" and turnOrder[gStates.turnNumber].tactic==2 and gStates.dayRound==false and gStates.tacticTwoState~="Used" and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5]) then
				local cardsInHand=0
				local handSize=turnOrder[gStates.turnNumber].hand+turnOrder[gStates.turnNumber].handBonus+gStates.tactic4HandBonus+meditationBonus
				if id=="DrawHand" then
					for _, possibleCards in pairs(getObjectFromGUID(handZones[playerPosition]).getObjects()) do if possibleCards.type=="Card" then cardsInHand=cardsInHand+1 end end
				else--Draw one
					cardsInHand=handSize-1
				end
				local drawNeeded=coralDrawExactCount or (handSize-cardsInHand)
				if drawNeeded>0 then
					local turnAffected=gStates.turnNumber
					--While normal Deed cards remain, Coral may replace any individual card draw with Quick Witted.
					if coralDrawBypass==false and deedDeck~=nil and coralQuickWittedSetAside(turnAffected)~=nil then
						showCoralDrawChoice(turnAffected, drawNeeded, id)
						return
					end
					function drawCardstoHand()
						local excess=drawNeeded
						local deckPos={-74.19+(40*(turnOrder[turnAffected].seatPos-1)), 1.50, -43.16}
						if deedDeck~=nil then
							if deedDeck.type=="Deck" then
								local deckQuantity=deedDeck.getQuantity()
								local drawNow=math.min(drawNeeded, deckQuantity)
								excess=drawNeeded-drawNow
								local deckTakes=drawNow
								local takeRemainder=drawNow==deckQuantity
								if takeRemainder==true then deckTakes=math.max(0,deckQuantity-1) end
								for x=1, deckTakes do
									local drawn=deedDeck.takeObject({position={(playerPosition*40)-105-(x*0.2), 4.59, -47.55}, rotation={0, 180, 0}})
									if drawn~=nil then turnOrder[turnAffected].deedCount=math.max(0,(turnOrder[turnAffected].deedCount or 0)-1) end
								end
								if takeRemainder==true then
									Wait.frames(function()
										local deedZone=getObjectFromGUID(deedDeckZones[turnOrder[turnAffected].seatPos])
										if deedZone==nil then return end
										for _, remainder in pairs(deedZone.getObjects()) do
											if remainder.type=="Card" then
												remainder.setScale({1.5, 1, 1.5})
												remainder.setPositionSmooth({(playerPosition*40)-105-(drawNow*0.2), 4.59, -47.55})
												remainder.setRotationSmooth({0, 180, 0})
												turnOrder[turnAffected].deedCount=math.max(0,(turnOrder[turnAffected].deedCount or 0)-1)
												break
											end
										end
										coralScheduleDeedRefresh(turnOrder[turnAffected].seatPos, 3)
									end, 2)
								end
							else
								excess=drawNeeded-1
								deedDeck.setScale({1.5, 1, 1.5})
								deedDeck.setPositionSmooth({(playerPosition*40)-105, 4.59, -47.55})
								deedDeck.setRotationSmooth({0, 180, 0})
								turnOrder[turnAffected].deedCount=math.max(0,(turnOrder[turnAffected].deedCount or 0)-1)
							end
							coralScheduleDeedRefresh(turnOrder[turnAffected].seatPos, 4)
						end
						cardClaim=false
						Wait.frames(function()
							Wait.time(function()
								--Night tactic 2 grab three random discards back to deck if draw will reduce to 0.
								if id=="DrawHand" and excess>0 and gStates.endRoundCalled==false and turnOrder[turnAffected].tactic==2 and gStates.dayRound==false and gStates.tacticTwoState~="Used" and turnOrder[turnAffected].mage~=gStates.positionMageKnight[5] then
									for _, discards in pairs(getObjectFromGUID(deedDeckDiscardZones[playerPosition]).getObjects()) do
										if discards.type=="Deck" then
											discards.shuffle()
											Wait.time(function()
												discards.takeObject({position=deckPos, smooth=true, rotation={0, 180, 180}})
												discards.takeObject({position=deckPos, smooth=true, rotation={0, 180, 180}})
												discards.takeObject({position=deckPos, smooth=true, rotation={0, 180, 180}})
												Wait.time(function()
													for _, possibleDeck in pairs(getObjectFromGUID(deedDeckZones[playerPosition]).getObjects()) do
														if possibleDeck.type=="Deck" then
															for x=1, excess, 1 do possibleDeck.takeObject({position={(playerPosition*40)-105-(x*0.2), 4.59, -47.55}, rotation={0, 180, 0}}) end
															break
														end
													end
												end, 1)
											end, 1)
											break
										end
									end
									gStates.tacticTwoState="Used"
									if getObjectFromGUID("f6ad01")~=nil and getObjectFromGUID("f6ad01").is_face_down==false then getObjectFromGUID("f6ad01").flip() end
									broadcastToAll("{en}Night Tactic Two was used to refill Deed Deck with 3 Random discards{ru}Ночная Тактика 2 была использована для замешивания 3 карт из сброса в Колоду деяний{zh-cn}使用夜间战术卡2随机弃了3张牌{ko}밤 전략 카드 2가 사용되었습니다{es}La Segunda Táctica Nocturna se utilizó para rellenar el Deed Deck con 3 descartes aleatorios.{fr}Nuit Tactic Deux a été utilisé pour remplir Deed Deck avec 3 défausse aléatoires{pt-br}Tática da Noite 2 foi usada para recarregar o Baralho de Feitos com 3 Cartas Aleatórias{de}Nachttaktik Zwei wurde benutzt, um das Tatendeck mit 3 zufälligen Abwürfen aufzufüllen", positionToColor(turnAffected))
								end
							end, 0.5)
						end, 2)
					end
					if cardClaim==true then Wait.time(function() drawCardstoHand() end, 1.5) else drawCardstoHand() end--make sure the card has entered the deck
				end
		    end
		end
	end
end

--True once there is no real Coral player, or Quick Witted is physically back in Coral's Deed Deck.
function coralQuickWittedReadyForDraw()
	for _, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return false end
			for _, obj in pairs(deedZone.getObjects()) do
				if obj.type=="Card" and obj.guid=="6ecbc6" then return true end
				if obj.type=="Deck" then for _, cardData in pairs(obj.getObjects()) do if cardData.guid=="6ecbc6" then return true end end end
			end
			return false
		end
	end
	return true
end

--Starting Deed Decks are taken from bags and shuffled asynchronously. Deal only after every active
--Mage Knight's complete Deed pile is registered in its scripting zone and has finished moving.
function startingDeedDecksReadyForDraw()
	for playerIndex, playerDetails in ipairs(turnOrder) do
		if playerDetails.mage~=gStates.positionMageKnight[5] and playerDropoutInactive(playerIndex)==false then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return false end
			local deedPileFound=false
			for _, obj in pairs(deedZone.getObjects()) do
				if obj.type=="Deck" or obj.type=="Card" then
					deedPileFound=true
					if obj.resting~=true then return false end
				end
			end
			if deedPileFound==false then return false end
		end
	end
	return true
end

--Replace the old four-second setup cushion with actual Deck readiness. Coral preparation runs once
--after all Deed Decks exist; the timeout retains a final fallback if TTS never reports a settled state.
function dealStartingHandsWhenReady()
	local coralPrepared=false
	local function finishStartingHandsDeal()
		dealAllHands()
		--Give the dealt cards a few frames to leave their Deck objects before automatic rewind snapshots resume.
		Wait.frames(function() rewindTransactionFinish("Game setup") end,15)
	end
	Wait.condition(finishStartingHandsDeal, function()
		if startingDeedDecksReadyForDraw()==false then return false end
		if coralPrepared==false then
			coralPrepared=true
			coralSetAsideQuickWitted()
			return false
		end
		return coralQuickWittedReadyForDraw()
	end, 10, function()
		coralSetAsideQuickWitted()
		Wait.frames(finishStartingHandsDeal, 5)
	end)
end

--Meditation / Trance card smarts. Top/Bot starts as Meditation; adding discard cards to the Deed Deck tells the script Trance was powered.
local meditationTranceCardGUID="2eb8d0"
local function meditationPlayerIndex(card)
	if card==nil then return nil end
	for playerIndex, details in pairs(turnOrder) do
		local area=details.seatPos~=nil and getObjectFromGUID(playerPlayAreas[details.seatPos]) or nil
		if area~=nil then for _, obj in pairs(area.getObjects()) do if obj.guid==card.guid then return playerIndex end end end
	end
	return nil
end
local function meditationDiscardSnapshot(playerIndex)
	local cards={}
	local zone=turnOrder[playerIndex]~=nil and getObjectFromGUID(deedDeckDiscardZones[turnOrder[playerIndex].seatPos]) or nil
	if zone==nil then return cards end
	for _, obj in pairs(zone.getObjects()) do
		if obj.type=="Card" then cards[obj.guid]=true
		elseif obj.type=="Deck" then for _, data in pairs(obj.getObjects()) do cards[data.guid]=true end end
	end
	return cards
end
local function meditationCardCount(cards)
	local count=0
	for _, _ in pairs(cards or {}) do count=count+1 end
	return count
end
--Card-effect controls are only shown while the card is essentially vertical.
--Read the card's settled world rotation rather than inferring orientation from Q/E presses.
--The 10 degree tolerance is intentionally below TTS's normal 15 degree rotation step.
function cardEffectIsVertical(card)
	if card==nil then return false end
	local rotation=card.getRotation()
	local y=((rotation~=nil and rotation[2]) or 0)%180
	return math.min(y,180-y)<=10
end
local function meditationStripXmlButtons(card)
	local xml=card.UI.getXmlTable() or {}
	for a=#xml, 1, -1 do
		local id=xml[a].attributes~=nil and xml[a].attributes.id or nil
		if id=="MeditationTranceTop" or id=="MeditationTranceBot" or id==card.guid.."meditationTop" or id==card.guid.."meditationBot" or id==card.guid.."tranceTop" or id==card.guid.."tranceBot" then table.remove(xml,a) end
	end
	return xml
end
local function meditationRemoveButtons(card)
	if card==nil then return end
	--Clean up old 3D buttons left by saves from before the XML conversion.
	local remove={}
	for _, button in pairs(card.getButtons() or {}) do
		if button.click_function=="meditationTranceTop" or button.click_function=="meditationTranceBot" then remove[#remove+1]=button.index end
	end
	table.sort(remove, function(a,b) return a>b end)
	for _, index in ipairs(remove) do card.removeButton(index) end

	local before=card.UI.getXmlTable() or {}
	local xml=meditationStripXmlButtons(card)
	if #xml~=#before then
		if #xml>0 then card.UI.setXmlTable(xml) else card.UI.setXml("") end
	end
end
local function meditationAddButtons(card, tranceReady)
	if card==nil then return end
	if cardEffectIsVertical(card)==false then meditationRemoveButtons(card) return end
	--Replace only our two controls, preserving any unrelated object UI on the card.
	local xml=meditationStripXmlButtons(card)
	if tranceReady==true then
		xml[#xml+1]=createClaimButton(card.guid, "tranceTop") xml[#xml+1]=createClaimButton(card.guid, "tranceBot")
	else
		xml[#xml+1]=createClaimButton(card.guid, "meditationTop") xml[#xml+1]=createClaimButton(card.guid, "meditationBot")
	end
	card.UI.setXmlTable(xml)
end
local function meditationNewState(playerIndex)
	local discard=meditationDiscardSnapshot(playerIndex)
	local required=math.min(2, meditationCardCount(discard))
	return {player=playerIndex, mode="waiting", discard=discard, required=required, accepted={}, acceptedSet={}, resolved=false}
end
function resetMeditationTranceState()
	local card=getObjectFromGUID(meditationTranceCardGUID)
	if card~=nil then meditationRemoveButtons(card) end
	gStates.meditationTranceState=nil
end
function refreshMeditationTrance()
	local card=getObjectFromGUID(meditationTranceCardGUID)
	if card==nil then return end
	local playerIndex=meditationPlayerIndex(card)
	--Picking the card up can briefly move it outside the player zone. Hide its controls,
	--but keep the resolved/unresolved state until the next turn explicitly resets it.
	if playerIndex==nil or cardEffectIsVertical(card)==false then meditationRemoveButtons(card) return end
	local state=gStates.meditationTranceState
	--Discard old powered/unpowered state from the first implementation and rebuild using physical card movement instead.
	if state==nil or state.player~=playerIndex or state.powered~=nil then gStates.meditationTranceState=meditationNewState(playerIndex) state=gStates.meditationTranceState end
	if state.resolved==true then meditationRemoveButtons(card) return end
	if state.mode=="trance" then
		if #state.accepted>=(state.required or 2) then meditationAddButtons(card, true) else meditationRemoveButtons(card) end
	else meditationAddButtons(card, false) end
end
local function meditationContainerIsDeedDeck(container, playerIndex)
	if container==nil or turnOrder[playerIndex]==nil then return false end
	local zone=getObjectFromGUID(deedDeckZones[turnOrder[playerIndex].seatPos])
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==container.guid then return true end end
	local a,b=container.getPosition(),zone.getPosition()
	return ((a[1]-b[1])^2)+((a[3]-b[3])^2)<6.25
end
local function meditationAcceptTranceCard(cardGUID)
	local state=gStates.meditationTranceState
	if state==nil or state.resolved==true or #state.accepted>=(state.required or 2) or state.discard==nil or state.discard[cardGUID]~=true or (state.acceptedSet~=nil and state.acceptedSet[cardGUID]==true) then return false end
	if (state.required or 0)<1 then return false end
	if state.acceptedSet==nil then state.acceptedSet={} end
	state.mode="trance" state.accepted[#state.accepted+1]=cardGUID state.acceptedSet[cardGUID]=true
	broadcastToAll("Trance Card Accepted ("..tostring(#state.accepted).."/"..tostring(state.required)..")", positionToColor(state.player))
	Wait.frames(function() refreshMeditationTrance() end, 2)
	return true
end
function meditationTranceContainerEnter(container, obj)
	if obj==nil then return end
	if obj.guid==meditationTranceCardGUID then meditationRemoveButtons(obj) gStates.meditationTranceState=nil return end
	local state=gStates.meditationTranceState
	if state~=nil and state.resolved~=true and meditationContainerIsDeedDeck(container, state.player)==true then meditationAcceptTranceCard(obj.guid) end
end
function meditationTranceCheckLooseCard(cardGUID)
	local state=gStates.meditationTranceState
	if state==nil or state.resolved==true or state.discard==nil or state.discard[cardGUID]~=true then return end
	local card=getObjectFromGUID(cardGUID)
	if card==nil or turnOrder[state.player]==nil then return end
	local zone=getObjectFromGUID(deedDeckZones[turnOrder[state.player].seatPos])
	if zone==nil then return end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==cardGUID then meditationAcceptTranceCard(cardGUID) return end end
end
local function meditationTakeCard(zone, cardGUID, position, callback)
	if zone==nil then return false end
	for _, pile in pairs(zone.getObjects()) do
		if pile.type=="Card" and pile.guid==cardGUID then pile.setPosition(position) pile.setRotation({0,180,0}) callback(pile) return true end
		if pile.type=="Deck" then
			for _, data in pairs(pile.getObjects()) do
				if data.guid==cardGUID then pile.takeObject({guid=cardGUID, position=position, rotation={0,180,0}, smooth=false, callback_function=callback}) return true end
			end
		end
	end
	return false
end
local function meditationInsertDeedCard(playerIndex, card, destination, callback)
	local zone=turnOrder[playerIndex]~=nil and getObjectFromGUID(deedDeckZones[turnOrder[playerIndex].seatPos]) or nil
	if zone==nil or card==nil then if callback~=nil then callback(false) end return end
	local pile=nil
	for _, obj in pairs(zone.getObjects()) do if obj.guid~=card.guid then if obj.type=="Deck" then pile=obj break elseif obj.type=="Card" then pile=obj end end end
	if pile==nil then
		local pos=zone.getPosition() card.setRotation({0,180,180}) card.setPosition({pos[1],1.50,pos[3]})
		Wait.frames(function() if callback~=nil then callback(true) end end, 2) return
	end
	local pos=pile.getPosition()
	if pile.type=="Deck" then
		card.setScale({1.5,1,1.5}) card.setRotation(pile.getRotation()) card.setPosition({pos[1]+3,pos[2]+(destination=="top" and 0.5 or -0.5),pos[3]})
		Wait.frames(function() if pile~=nil and not pile.isDestroyed() and card~=nil and not card.isDestroyed() then pile.putObject(card) end Wait.frames(function() if callback~=nil then callback(true) end end, 1) end, 1)
	else
		local rotation=pile.getRotation() card.setScale({1.5,1,1.5}) card.setRotation(rotation)
		if destination=="top" then card.setPosition({pos[1],pos[2]+0.28,pos[3]}) else pile.setPosition({pos[1],pos[2]+0.28,pos[3]}) card.setPosition({pos[1],pos[2],pos[3]}) end
		Wait.frames(function() if callback~=nil then callback(true) end end, 4)
	end
end
local function meditationMoveCards(playerIndex, sourceType, cardGUIDs, destination, done)
	local moved=0
	local function moveNext(index)
		if index>#cardGUIDs then if done~=nil then done(moved) end return end
		local sourceZone=getObjectFromGUID((sourceType=="discard" and deedDeckDiscardZones or deedDeckZones)[turnOrder[playerIndex].seatPos])
		local deckZone=getObjectFromGUID(deedDeckZones[turnOrder[playerIndex].seatPos])
		local deckPos=deckZone~=nil and deckZone.getPosition() or {turnOrder[playerIndex].seatPos*40-114,1.5,-43}
		local staging={deckPos[1]+4,3.0,deckPos[3]}
		local found=meditationTakeCard(sourceZone, cardGUIDs[index], staging, function(card)
			meditationInsertDeedCard(playerIndex, card, destination, function(success) if success==true then moved=moved+1 end Wait.frames(function() moveNext(index+1) end, 2) end)
		end)
		if found==false then Wait.frames(function() moveNext(index+1) end, 1) end
	end
	moveNext(1)
end
local function meditationGrantDrawBonus(playerIndex)
	if gStates.meditationDrawBonus==nil then gStates.meditationDrawBonus={} end
	gStates.meditationDrawBonus[playerIndex]=2
	if playerIndex==gStates.turnNumber then Wait.frames(function() if gStates.turnNumber==playerIndex then mainUIUpdate("Meditation Draw Bonus") end end, 1) end
end
local function meditationFinish(playerIndex, destination, moved, expected, name)
	if moved~=expected then broadcastToAll(name.." could not find all selected discard cards.", positionToColor(playerIndex)) return end
	turnOrder[playerIndex].deedCount=(turnOrder[playerIndex].deedCount or 0)+moved
	if destination=="bottom" and turnOrder[playerIndex].mage=="Coral" then Wait.frames(function() coralSetAsideQuickWitted() end, 8) end
end
local function meditationResolve(destination, buttonPlayerColor)
	local card=getObjectFromGUID(meditationTranceCardGUID)
	local playerIndex=meditationPlayerIndex(card)
	if card==nil or playerIndex==nil or legalPlayerCheck(buttonPlayerColor, turnOrder[playerIndex].seatPos)~=true then return end
	local state=gStates.meditationTranceState
	if state==nil or state.player~=playerIndex or state.powered~=nil then refreshMeditationTrance() state=gStates.meditationTranceState end
	if state==nil or state.resolved==true then return end
	if state.mode=="trance" then
		local required=state.required or math.min(2,#state.accepted)
		if #state.accepted<required then broadcastToAll("Trance: add "..tostring(required-#state.accepted).." more chosen card"..((required-#state.accepted)==1 and "" or "s").." from your discard pile to your Deed deck first.", positionToColor(playerIndex)) return end
		state.resolved=true meditationRemoveButtons(card) meditationGrantDrawBonus(playerIndex)
		local selected={}
		for a=1, required do selected[#selected+1]=state.accepted[a] end
		meditationMoveCards(playerIndex, "deed", selected, destination, function(moved) meditationFinish(playerIndex, destination, moved, required, "Trance") end)
		return
	end
	local discard=meditationDiscardSnapshot(playerIndex)
	local choices={}
	for guid, _ in pairs(discard) do choices[#choices+1]=guid end
	local amount=math.min(2,#choices)
	local selected={}
	for a=1, amount do selected[#selected+1]=table.remove(choices,math.random(#choices)) end
	state.resolved=true meditationRemoveButtons(card) meditationGrantDrawBonus(playerIndex)
	if amount==0 then
		broadcastToAll("Meditation: no discard cards to return. Draw +2 over hand limit still applies.", positionToColor(playerIndex))
		return
	end
	meditationMoveCards(playerIndex, "discard", selected, destination, function(moved)
		meditationFinish(playerIndex, destination, moved, amount, "Meditation")
		if moved==amount then broadcastToAll("Meditation returned "..tostring(amount).." random discard card"..(amount==1 and "" or "s").." to the "..destination.." of the Deed deck.", positionToColor(playerIndex)) end
	end)
end
function meditationTranceTop(player, mouseButton, id) if mouseButton~="-3" then meditationResolve("top", player.color) end end
function meditationTranceBot(player, mouseButton, id) if mouseButton~="-3" then meditationResolve("bottom", player.color) end end

--Steady Tempo end-of-turn choice. The card deliberately remains in the play area
--during cleanup, then these small card-attached buttons decide where it goes.
local steadyTempoGUIDs={ ["1f362f"]=true, ["6e506a"]=true }
function isSteadyTempoGUID(guid) return guid~=nil and steadyTempoGUIDs[guid]==true end
local function steadyTempoPlayerIndex(seatPos)
	for playerIndex, details in pairs(turnOrder) do if details.seatPos==seatPos then return playerIndex end end
	return nil
end
function steadyTempoPendingForSeat(seatPos)
	if seatPos==nil or gStates.steadyTempoPending==nil then return false end
	for _, pendingSeat in pairs(gStates.steadyTempoPending) do if pendingSeat==seatPos then return true end end
	return false
end
function steadyTempoUpdateRewardGate(seatPos)
	if seatPos==nil or gStates.preEndTurn~=true or turnOrder[gStates.turnNumber]==nil or turnOrder[gStates.turnNumber].seatPos~=seatPos then return end
	--Quest resolution uses a soft gate: Rewards Claimed remains clickable, and __endTurn_raw refreshes
	--the Quest controls plus explains what must be resolved. Only genuinely asynchronous cleanup/Steady
	--Tempo physically disables this button. Free Wine now follows the same Quest behavior.
	local blocked=rewardClaimDelayActive==true or steadyTempoPendingForSeat(seatPos)
	UI.setAttribute("PreEndTurn", "interactable", blocked and "false" or "true")
	UI.setAttribute("PreEndTurnImage", "image", blocked and "Sliced Button/Button New Deactive" or "Sliced Button/Button New Active")
end
local function steadyTempoStripButtons(card)
	local xml=card~=nil and (card.UI.getXmlTable() or {}) or {}
	for a=#xml, 1, -1 do
		local id=xml[a].attributes~=nil and xml[a].attributes.id or nil
		if id==card.guid.."steadyTempoDiscard" or id==card.guid.."steadyTempoBot" or id==card.guid.."steadyTempoTop" then table.remove(xml,a) end
	end
	return xml
end
function steadyTempoRemoveButtons(card)
	if card==nil then return end
	local before=card.UI.getXmlTable() or {}
	local xml=steadyTempoStripButtons(card)
	if #xml~=#before then if #xml>0 then card.UI.setXmlTable(xml) else card.UI.setXml("") end end
end
local function steadyTempoHasDeedPile(playerIndex)
	local details=turnOrder[playerIndex]
	local zone=details~=nil and getObjectFromGUID(deedDeckZones[details.seatPos]) or nil
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.type=="Deck" or obj.type=="Card" then return true end end
	return false
end
local function steadyTempoCardInPlayArea(card, seatPos)
	local zone=card~=nil and getObjectFromGUID(playerPlayAreas[seatPos]) or nil
	if zone==nil then return false end
	for _, obj in pairs(zone.getObjects()) do if obj.guid==card.guid then return true end end
	return false
end
local function steadyTempoAddButtons(card, playerIndex)
	if card==nil or turnOrder[playerIndex]==nil then return end
	if cardEffectIsVertical(card)==false then steadyTempoRemoveButtons(card) return end
	local xml=steadyTempoStripButtons(card)
	xml[#xml+1]=createClaimButton(card.guid, "steadyTempoDiscard")
	--The printed basic effect only permits the bottom option while the Deed deck is not empty.
	if steadyTempoHasDeedPile(playerIndex)==true then xml[#xml+1]=createClaimButton(card.guid, "steadyTempoBot") end
	xml[#xml+1]=createClaimButton(card.guid, "steadyTempoTop")
	card.UI.setXmlTable(xml)
end
function steadyTempoPrepare(card, playerIndex)
	if card==nil or isSteadyTempoGUID(card.guid)==false or turnOrder[playerIndex]==nil then return end
	if cardEffectIsVertical(card)==false then steadyTempoRemoveButtons(card) return end
	if gStates.steadyTempoPending==nil then gStates.steadyTempoPending={} end
	local seatPos=turnOrder[playerIndex].seatPos
	gStates.steadyTempoPending[card.guid]=seatPos
	steadyTempoAddButtons(card, playerIndex)
	steadyTempoUpdateRewardGate(seatPos)
end
function steadyTempoClearPending(cardGUID)
	local seatPos=gStates.steadyTempoPending~=nil and gStates.steadyTempoPending[cardGUID] or nil
	if gStates.steadyTempoPending~=nil then gStates.steadyTempoPending[cardGUID]=nil end
	local card=getObjectFromGUID(cardGUID)
	if card~=nil then steadyTempoRemoveButtons(card) end
	if seatPos~=nil then steadyTempoUpdateRewardGate(seatPos) end
end
function steadyTempoRefreshCard(cardGUID)
	if gStates.steadyTempoPending==nil then return end
	local seatPos=gStates.steadyTempoPending[cardGUID]
	local card=seatPos~=nil and getObjectFromGUID(cardGUID) or nil
	local playerIndex=seatPos~=nil and steadyTempoPlayerIndex(seatPos) or nil
	if card==nil or playerIndex==nil then return end
	if steadyTempoCardInPlayArea(card, seatPos)==true and card.is_face_down==false and cardEffectIsVertical(card)==true then steadyTempoAddButtons(card, playerIndex) else steadyTempoRemoveButtons(card) end
end
function steadyTempoRefreshAll()
	if gStates.steadyTempoPending==nil then return end
	for cardGUID, _ in pairs(gStates.steadyTempoPending) do steadyTempoRefreshCard(cardGUID) end
end
local function steadyTempoMoveToDiscard(playerIndex, card)
	local details=turnOrder[playerIndex]
	local zone=details~=nil and getObjectFromGUID(deedDeckDiscardZones[details.seatPos]) or nil
	if zone==nil or card==nil then return false end
	local pile=nil
	for _, obj in pairs(zone.getObjects()) do if obj.type=="Deck" then pile=obj break elseif obj.type=="Card" then pile=obj end end
	card.setScale({1.5,1,1.5}) card.setRotation({0,180,0})
	if pile==nil then
		local pos=zone.getPosition() card.setPosition({pos[1],1.50,pos[3]})
	else
		local pos=pile.getPosition() card.setPosition({pos[1]+3,pos[2]+0.5,pos[3]})
		Wait.frames(function() if pile~=nil and not pile.isDestroyed() and card~=nil and not card.isDestroyed() then pile.putObject(card) end end, 1)
	end
	Wait.frames(function() scheduleDeedPileDescriptionRefresh(details.seatPos, "discard") end, 6)
	return true
end
function steadyTempoChoice(player, mouseButton, id)
	if mouseButton=="-3" or player==nil or id==nil then return end
	local cardGUID=id:sub(1,6)
	if isSteadyTempoGUID(cardGUID)==false or gStates.steadyTempoPending==nil then return end
	local seatPos=gStates.steadyTempoPending[cardGUID]
	local playerIndex=seatPos~=nil and steadyTempoPlayerIndex(seatPos) or nil
	local card=getObjectFromGUID(cardGUID)
	if playerIndex==nil or card==nil or legalPlayerCheck(player.color, seatPos)~=true then return end
	local choice=id:sub(7)
	if choice=="steadyTempoBot" and steadyTempoHasDeedPile(playerIndex)==false then steadyTempoAddButtons(card, playerIndex) return end
	--Remove the controls immediately, but keep the pending flag until the card physically reaches its destination.
	--Rewards Claimed therefore cannot race a Top insertion and draw the old top card first.
	steadyTempoRemoveButtons(card)
	if choice=="steadyTempoDiscard" then
		if steadyTempoMoveToDiscard(playerIndex, card)==true then Wait.frames(function() steadyTempoClearPending(cardGUID) end, 2)
		else steadyTempoAddButtons(card, playerIndex) end
		return
	end
	local destination=choice=="steadyTempoBot" and "bottom" or "top"
	meditationInsertDeedCard(playerIndex, card, destination, function(success)
		if success~=true then steadyTempoAddButtons(card, playerIndex) return end
		turnOrder[playerIndex].deedCount=(turnOrder[playerIndex].deedCount or 0)+1
		scheduleDeedPileDescriptionRefresh(seatPos, "deed")
		scheduleEndRoundDeedStateRefresh(seatPos)
		--Quick Witted remains Coral's actual set-aside bottom card; Steady Tempo sits immediately above it.
		if destination=="bottom" and turnOrder[playerIndex].mage=="Coral" then
			scheduleCoralQuickWittedBottom(6)
			Wait.frames(function() steadyTempoClearPending(cardGUID) end, 8)
		else steadyTempoClearPending(cardGUID) end
	end)
end

--Keep Quick Witted Set Aside at the bottom of Coral's physical Deed Deck.
--Taking it out and putting it back at the Deck's resting elevation inserts it at the bottom.
function coralSetAsideQuickWitted()
	local cardGUID="6ecbc6"
	for _, playerDetails in pairs(turnOrder) do
		if playerDetails.mage=="Coral" and playerDetails.mage~=gStates.positionMageKnight[5] and playerDetails.dropoutState==nil then
			local deedZone=getObjectFromGUID(deedDeckZones[playerDetails.seatPos])
			if deedZone==nil then return end
			local deedDeck=nil
			for _, obj in pairs(deedZone.getObjects()) do
				if obj.type=="Deck" then
					deedDeck=obj
					for _, cardData in pairs(obj.getObjects()) do
						if cardData.guid==cardGUID then
							local deckPos=obj.getPosition()
							obj.takeObject({guid=cardGUID, position={deckPos[1]+3, deckPos[2], deckPos[3]}, rotation={0, 180, 180}, smooth=false, callback_function=function(card)
								Wait.frames(function()
									local currentDeck=nil
									for _, currentObj in pairs(deedZone.getObjects()) do if currentObj.type=="Deck" then currentDeck=currentObj break end end
									if currentDeck~=nil then
										local currentPos=currentDeck.getPosition()
										card.setScale({1.5, 1, 1.5})
										card.setPosition({currentPos[1]+3, currentPos[2]-0.5, currentPos[3]})
										currentDeck.putObject(card)
									else
										card.setPosition({deckPos[1], deckPos[2], deckPos[3]})
									end
								end, 1)
							end})
							return
						end
					end
				end
			end
			--Compatibility with saves from the earlier inventory-based version. Only recover a loose
			--Quick Witted that is physically in Coral's Deed zone; once claimed to hand it is a normal card.
			local looseCard=getObjectFromGUID(cardGUID)
			local looseInDeedZone=false
			if looseCard~=nil then
				for _, deedObj in pairs(deedZone.getObjects()) do if deedObj.guid==cardGUID then looseInDeedZone=true break end end
			end
			if looseCard~=nil and looseInDeedZone==true and deedDeck~=nil then
				local deckPos=deedDeck.getPosition()
				looseCard.setScale({1.5, 1, 1.5})
				looseCard.setRotation({0, 180, 180})
				looseCard.setPosition({deckPos[1]+3, deckPos[2]-0.5, deckPos[3]})
				Wait.frames(function() if deedDeck~=nil then deedDeck.putObject(looseCard) end end, 1)
			elseif looseCard~=nil and looseInDeedZone==true and deedDeck==nil then
				local deckPos=deedZone.getPosition()
				looseCard.setScale({1.5, 1, 1.5})
				looseCard.setRotation({0, 180, 180})
				looseCard.setPosition({deckPos[1], 1.50, deckPos[3]})
			end
			return
		end
	end
end

--Deals all the hands by fast forwarding through the turns
function dealAllHands()
	local temp=gStates.turnNumber
	for a=1, #turnOrder, 1 do
		gStates.turnNumber=a
		if turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] and playerDropoutInactive(gStates.turnNumber)==false then drawUpTo({color="Black"}, "-1", "DrawHand") end--color is only there to stop error
	end
	gStates.turnNumber=temp
	Wait.time(function()
		for x=1, #turnOrder, 1 do
			--Records current amount of cards in deed deck
			turnOrder[x].deedCount=0
			for _, b in pairs(getObjectFromGUID(deedDeckZones[turnOrder[x].seatPos]).getObjects()) do
				if b.type=="Card" then turnOrder[x].deedCount=1 end
				if b.type=="Deck" then turnOrder[x].deedCount=b.getQuantity() end
			end
		end
	end, 0.5)
end

--Fill any gaps in the offer by sliding more cards down the line
function fillSlide()
	local offerList={{}, {}}
	local sourceDeck={GUID.zone.actionDeck, GUID.zone.spellDeck}
	for _, obj in pairs(getObjectFromGUID(GUID.zone.offer).getObjects()) do
		if obj.type=="Card" then --and obj.resting==true then
			local cardSpot=obj.getPosition()
			offerList[math.floor(((-cardSpot[3]-10.2)/6)+0.5)][math.floor(((cardSpot[1]-21.6)/4.8)+0.5)]=obj.guid
		end
	end
	--fill gaps in the offer
	for column=1, gStates.offerSize, 1 do
		for row=1, 2, 1 do
			if offerList[row][column]==nil then
				for replaceColumn=column+1, gStates.offerSize+1, 1 do
					if replaceColumn<gStates.offerSize+1 then
						--fill empty spaces with cards further up the offer
						if offerList[row][replaceColumn]~=nil then
							local cardMove=getObjectFromGUID(offerList[row][replaceColumn])
							cardMove.unlock()
							cardMove.setPositionSmooth({(column*4.8)+21.6, 1.5, -((row*6)+10.2)})
							cardMove.setRotationSmooth({0, 180, 0})
							Wait.condition(function() Wait.time(function() cardMove.lock() end, 1) end, function() return cardMove.resting end)
							offerList[row][column]=offerList[row][replaceColumn]
							offerList[row][replaceColumn]=nil
							break
						end
					else
						--fill empty spaces from deck when no cards are found
						local deckName=row==1 and "Advanced Action" or "Spell"
						standardDeckCycleShuffleIfReached(deckName)
						local MainDeck=getObjectFromGUID(sourceDeck[row]).getObjects()
						if MainDeck[1]~=nil then
							if MainDeck[1].type=="Deck" then
								local newcard=MainDeck[1].takeObject({position={((column*4.8)+21.6), 1.5, -((row*6)+10.2)}, rotation={0, 180, 0}})
								offerList[row][column]=newcard.guid
								Wait.condition(function() Wait.time(function() newcard.lock() end, 1) end, function() return newcard.resting end)
							else
								MainDeck[1].setPositionSmooth({(column*4.8)+21.6, 1.5, -((row*6)+10.2)})
								MainDeck[1].setRotationSmooth({0, 180, 0})
								MainDeck[1]=nil
							end
						end
					end
				end
			end
		end
	end
end

--Adjust artifact rewards claim amount
function artifactAdjust(player, mouseButton, id)
	if mouseButton=="-1" then
		if id=="ac75c4ArtifactDown" then
			gStates.artifactRewards=gStates.artifactRewards-1
			if gStates.artifactRewards<1 then gStates.artifactRewards=1 end
		else
			gStates.artifactRewards=gStates.artifactRewards+1
			if gStates.artifactRewards>4 then gStates.artifactRewards=4 end
		end
		getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOfferText", "text", joinLang({"{en}Reward {ru}Награда {zh-tw}獎勵{zh-cn}奖励{ko}보상 {es}Premiar {fr}Reward {pt-br}Premiar {de}Belohnung ", gStates.artifactRewards}))
	end
end

--Deploys artifacts to be claimed
function offerArtifacts(player, mouseButton, id)
	if mouseButton=="-1" then
		if legalPlayerCheck(player.color, turnOrder[gStates.turnNumber].seatPos)==true and turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] then
			--check if the game is in a state to claim artifacts
			if gStates.tacticShown~=true and gStates.tacticRemove~=true then
				--deal out cards
				local artifactDeck=getObjectFromGUID(GUID.deck.artifact)
				gStates.dealtArtifacts={}
				local hide={}
				if gStates.coop==0 then
					for _, seatColor in pairs(Player.getColors()) do
						if seatColor~=player.color then hide[#hide+1]=seatColor end
					end
				end
				for a=1, gStates.artifactRewards+1, 1 do
					standardDeckCycleShuffleIfReached("Artifact", artifactDeck)
					artifactDeck=getObjectFromGUID(GUID.deck.artifact)
					local dealtArtifact=artifactDeck.takeObject({position={artifactDeck.getPosition()[1]+(((artifactDeck.getScale()[1]/1.5)*4.8)*a), 2.0, artifactDeck.getPosition()[3]}, rotation={0, 180, 0}, smooth=true})
					dealtArtifact.setHiddenFrom(hide)
					dealtArtifact.UI.setXmlTable({createClaimButton(dealtArtifact.guid, "artifactReward")})
					Wait.condition(function() dealtArtifact.lock() end, function() return dealtArtifact.resting end)
					gStates.dealtArtifacts[dealtArtifact.guid]=true
				end
				--remove reward and arrow buttons.
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactDown", "active", "false")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactOffer", "active", "false")
				getObjectFromGUID(GUID.deck.artifact).UI.setAttribute("ac75c4ArtifactUp", "active", "false")
			else
				broadcastToAll("{en}Choose a tactic first{ru}Сперва выберите Тактику{zh-cn}先选一张战术卡吧{ko}먼저 전략 카드를 고르세요{es}Elige una táctica primero{fr}Choisissez d'abord une tactique{pt-br}Escolha uma Tática primeiro{de}Wähle zuerst eine Taktik",warningColor)
			end
		else
			if turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5] then
				broadcastToAll("{en}Dummy doesn't claim artifacts{ru}Виртуальный игрок не получает артефактов{zh-cn}虚拟玩家不选择圣器{ko}가상 플레이어는 유물을 얻지 않습니다!{es}Dummy no reclama artefactos{fr}Le mannequin ne revendique pas d'artefacts{pt-br}Jog. Fictício não clama Artefatos{de}Dummy beansprucht keine Artefakte",warningColor)
			end
		end
	end
end

--Unit and Monastery Offer update
function unitOffer()
	local unitPlace=		{{36.0, 0.98,  -4.2}, {31.2, 0.98,  -4.2}, {26.4, 0.98,  -4.2}, {21.6, 0.98,  -4.2}, {16.8, 0.98,  -4.2}, {12.0, 0.98,  -4.2}, {7.2, 0.98, -4.2}, {2.4, 0.98, -4.2}}
	local monasteryPlace=	{{36.0, 0.98, -10.2}, {31.2, 0.98, -10.2}, {26.4, 0.98, -10.2}, {21.6, 0.98, -10.2}, {16.8, 0.98, -10.2}, {12.0, 0.98, -10.2}}
	local drawDecks=		{["Regular Unit"]=GUID.zone.regularUnit, ["Elite Unit"]=GUID.zone.eliteUnit, ["Advanced Action"]=GUID.zone.actionDeck}--Zone covering Regular units draw deck, Elite Units Draw Deck, Advanced Actions Draw Deck
	local skip=false
	--Place existing cards under raised decks
	for _, offerCards in pairs(getObjectFromGUID("a3d99b").getObjects()) do--Zone where units and monastery cards are played
		local offerCardType=gameCardType(offerCards)
		if offerCards.type=="Card" and drawDecks[offerCardType]~=nil then
			offerCards.unlock()
			standardDeckCycleMarkReturned(offerCardType, offerCards)
			getObjectFromGUID(getObjectFromGUID(drawDecks[offerCardType]).getObjects()[1].guid).putObject(offerCards)
		end
		if offerCards.type=="Deck" then
			for j=1, offerCards.getQuantity(), 1 do
				local pos=offerCards.getPosition()
				local params={position={pos.x-j*0.85+1, pos.y+0.15, pos.z}}
				offerCards.takeObject(params)
			end
			broadcastToAll("{en}Sorry, I seem to have double dealt. Manual cleaning of Offer required{ru}Извините, что-то пошло не так. Требуется ручное исправление доступных карт{zh-cn}抱歉，我可能做了双重结算，请手动清除部队供应区{ko}죄송합니다, 공급처가 이중으로 겹쳐진 모양이네요. 직접 정리 부탁드립니다.{es}Lo siento, parece que he hecho un doblete. Se requiere limpieza manual de la Oferta{fr}Désolé, j'ai l'impression d'avoir joué deux fois. Nettoyage manuel de l'offre requis{pt-br}Desculpe, Parece que ofertei em dobro. Limpeza Manual da Oferta requerida.{de}Entschuldigung, ich habe wohl doppelt gehandelt. Manuelle Bereinigung des Angebots erforderlich", warningColor)
			skip=true
		end
	end
	if skip==false then
		local params={smooth=true, rotation={0, 180, 0}}
		standardDeckCycleShuffleIfReached("Regular Unit")
		standardDeckCycleShuffleIfReached("Elite Unit")
		standardDeckCycleShuffleIfReached("Advanced Action")
		--Place Unit Cards
		local function getUnitDrawList(drawDecks)
			local unitsInOffer={}
			local deckInfo={}
			local drawList={}
			--Prepare a deck's contents the first time we need it
			local function getDeckInfo(zoneGUID)
				if deckInfo[zoneGUID]~=nil then return deckInfo[zoneGUID] end
				local zone=getObjectFromGUID(zoneGUID)
				local deck=nil
				for _, obj in ipairs(zone.getObjects()) do
					if obj.type=="Deck" or obj.type=="Card" then deck=obj break end
				end
				if deck==nil then return nil end
				local cards={}
				if deck.type=="Deck" then cards=deck.getObjects() else cards={{guid=deck.guid}}	end
				deckInfo[zoneGUID]={deck=deck, cards=cards, nextCard=1, rejected={}}
				return deckInfo[zoneGUID]
			end

			--Find the next unit whose name is not already in the offer
			local function getNextUniqueUnit(zoneGUID, deckName)
				local info=getDeckInfo(zoneGUID)
				if info==nil then return nil end
				while info.nextCard<=#info.cards do
					local card=info.cards[info.nextCard]
					info.nextCard=info.nextCard+1
					local unitData=gameCards[card.guid]
					--Fallback to GUID if this card isn't in gameCards
					local unitName=card.guid
					if unitData~=nil and unitData.name~=nil and unitData.name[1]~=nil then unitName=unitData.name[1] end
					if unitsInOffer[unitName]~=true then
						if standardDeckCycleShuffleIfReached(deckName, info.deck, card.guid)==true then
							info.cards=info.deck.type=="Deck" and info.deck.getObjects() or {{guid=info.deck.guid}}
							info.nextCard=1
						else
							unitsInOffer[unitName]=true
							return {deck=info.deck, guid=card.guid}
						end
					end
				end
				return nil
			end

			--Work out every unit we want BEFORE physically drawing anything
			for a=1, gStates.totalUnitCount do
				local drawDeckName="Regular Unit"
				if gStates.eliteUnitsUsed==true	and (a==1 or a==3 or a==5 or a==7 or a==9) then drawDeckName="Elite Unit" end
				local drawDeckType=drawDecks[drawDeckName]
				local chosenUnit=getNextUniqueUnit(drawDeckType, drawDeckName)
				if chosenUnit~=nil then drawList[a]=chosenUnit else broadcastToAll("Could not find enough unique units for the offer.",	warningColor) break end
			end
			return drawList, deckInfo
		end
		local unitDrawList=getUnitDrawList(drawDecks)
		for a, draw in ipairs(unitDrawList) do
			draw.deck.takeObject({
				guid=draw.guid,
				position=unitPlace[a],
				rotation={0,180,0},
				smooth=true,
				callback_function=function(drawnCard)
					Wait.condition(function()
						drawnCard.lock()
					end, function() return drawnCard.resting end)
				end
			})
		end
		--Place Monastery offer cards
		for i=1, gStates.monasteryCount, 1 do
			params.position=monasteryPlace[i]
			standardDeckCycleShuffleIfReached("Advanced Action")
			local drawnCard=getObjectFromGUID(getObjectFromGUID(drawDecks["Advanced Action"]).getObjects()[1].guid).takeObject(params)
			Wait.condition(function() drawnCard.lock() end, function() return drawnCard.resting end)
		end
	end
end

--checks the clicking player matches the current turn
function legalPlayerCheck(clickingPlayersColor, playerPosExpected, rule)
	--converts player color in to a posiion value
	local playerPosition=0
	if clickingPlayersColor~="Grey" and clickingPlayersColor~="Black" and Player[clickingPlayersColor].seated==true and Player[clickingPlayersColor].getHandTransform()~=nil then playerPosition=math.ceil((Player[clickingPlayersColor].getHandTransform().position[1]+97.59)/40) end
	if playerPosition==playerPosExpected or clickingPlayersColor=="Black" or (rule==nil and turnOrder[gStates.turnNumber].mage==gStates.positionMageKnight[5]) then
		return true
	else
		for a=1, #turnOrder, 1 do
			if turnOrder[a].seatPos==playerPosExpected then
				broadcastToAll(joinLang({"{en}Only player sitting at {ru}Только игрок, сидящий на месте {zh-cn}只有{ko}오직 플레이어 {es}Solo el jugador sentado en {fr}Seul le joueur assis à {pt-br}Único jogador sentando em {de}Nur Spieler, die auf ", translateWord[turnOrder[a].mage], "{en} or Game Master(Black) may press this.\n(Change seats by left clicking your Name found in the upper right corner){ru} или на месте Game Master (Черный) может нажать сюда.\n(Чтобы сменить место, щелкните ЛКМ по своему имени, указанному в правом верхнем углу){zh-cn}和黑色玩家可以操作(你可以单击右上角你的名字更改颜色){ko}본인이나 게임 마스터(검정)만이 클릭할 수 있습니다.\n(자리를 바꾸려면 우상단의 버튼에서 닉네임을 클릭하세요){es} o Game Master (Negro) puede presionar esto.\n(Cambie de asiento haciendo clic izquierdo en su nombre que se encuentra en la esquina superior derecha){fr} ou au Game Master (Black) peut appuyer dessus.\n(Changez de siège en cliquant avec le bouton gauche sur votre nom trouvé dans le coin supérieur droit){pt-br} Jogador Mestre (Preto) pode pressionar isto.\nMude assentos apertando no seu nome no canto superior direito{de} oder Game Master(Black) kann dies drücken.\n(Wechseln Sie den Sitzplatz, indem Sie mit der linken Maustaste auf Ihren Namen in der oberen rechten Ecke klicken)"}), warningColor)
				break
			end
		end
		return false
	end
end

--Add Icons to players Avatar and Rampaging Monsters
local addAvatarPause=true
avatarButtonXmlState={}
avatarButtonSpatialCell=3

function avatarButtonBucketKey(pos)
	return tostring(math.floor(pos[1]/avatarButtonSpatialCell))..":"..tostring(math.floor(pos[3]/avatarButtonSpatialCell))
end

function avatarButtonNearbyObjects(buckets, pos)
	local nearby={}
	local baseX=math.floor(pos[1]/avatarButtonSpatialCell)
	local baseZ=math.floor(pos[3]/avatarButtonSpatialCell)
	for x=baseX-1, baseX+1 do
		for z=baseZ-1, baseZ+1 do
			local bucket=buckets[tostring(x)..":"..tostring(z)]
			if bucket~=nil then for _, details in ipairs(bucket) do nearby[#nearby+1]=details end end
		end
	end
	return nearby
end

function avatarButtonXmlSignature(xml, scale, rotation)
	if xml==nil or xml[1]==nil or xml[1].tag==nil then return "empty" end
	local signature={tostring(scale), tostring(math.floor((rotation or 0)*10+0.5)/10)}
	for _, child in ipairs(xml[1].children or {}) do
		local attributes=child.attributes or {}
		local image=""
		if child.children~=nil and child.children[1]~=nil and child.children[1].attributes~=nil then image=child.children[1].attributes.image or "" end
		signature[#signature+1]=table.concat({child.tag or "", attributes.id or "", attributes.onClick or "", attributes.position or "", image}, "~")
	end
	return table.concat(signature, "|")
end

function applyAvatarButtonXml(obj, xml, signature)
	if obj==nil then return end
	local guid=obj.guid
	if avatarButtonXmlState[guid]~=signature then
		obj.UI.setXmlTable(xml)
		avatarButtonXmlState[guid]=signature
	end
end

function addAvatarButtons()
	if addAvatarPause==true then Wait.frames(function()
		--Snapshot relevant map objects once. Nearby shield/marker/ruin checks use spatial buckets;
		--rampager/destroyed-site controls remain a small dedicated list because stale remote buttons must be cleared.
		local mapButtonBuckets={}
		local mapActionObjects={}
		local mapObj=getObjectFromGUID(mapArea)
		if mapObj~=nil then
			for _, playObj in pairs(mapObj.getObjects()) do
				local guid=playObj.guid
				local name=playObj.getName()
				if name=="Shield" or name:sub(-6)=="Marker" or monsterPugs[guid]~=nil or gStates.rampagingMonsters[guid]==true or (gStates.destroyedSites~=nil and gStates.destroyedSites[guid]~=nil) then
					local position=playObj.getPosition()
					local details={obj=playObj, guid=guid, name=name, position=position, description=name=="Shield" and playObj.getDescription() or nil}
					local key=avatarButtonBucketKey(position)
					if mapButtonBuckets[key]==nil then mapButtonBuckets[key]={} end
					mapButtonBuckets[key][#mapButtonBuckets[key]+1]=details
					if gStates.rampagingMonsters[guid]==true or (gStates.destroyedSites~=nil and gStates.destroyedSites[guid]~=nil) then mapActionObjects[#mapActionObjects+1]=details end
				end
			end
		end

		--Only active turn-order Mage Knights can need avatar buttons. Resolve each physical avatar once.
		for order, player in pairs(turnOrder) do
			local details=mageKnightsByName[player.mage]
			if details~=nil and playerDropoutInactive(order)==true then
				for _, avatarGUID in ipairs({details.model, details.token, details.standee}) do
					local inactiveAvatar=getObjectFromGUID(avatarGUID)
					if inactiveAvatar~=nil then applyAvatarButtonXml(inactiveAvatar, {{}}, "empty") end
				end
			end
			if details~=nil and details.shieldContainer~=nil and playerDropoutInactive(order)==false and player.mage~=gStates.positionMageKnight[5] then
				local modelObj=getObjectFromGUID(details.model)
				local tokenObj=getObjectFromGUID(details.token)
				local standeeObj=getObjectFromGUID(details.standee)
				local avatarObj=standeeObj or tokenObj or modelObj
				if avatarObj~=nil then
					local scale=standeeObj~=nil and 1 or (tokenObj~=nil and 0.53 or 0.9)
					local rotation=avatarObj.getRotation()[2]
					local avPos=avatarObj.getPosition()
					local mageShield=nil
					local mageMarker={}
					local avatarButton={{tag="Panel", attributes={id=details.markerContainer.."RotationPlane",
						height=300, width=300,
						position="0 0 "..tostring(-25/scale), rotation="0 0 "..tostring(rotation-180),
						color="rgba(0,0,0,0.0)"},
						children={}}}
					local cityHasMonsters=false
					local cityHasShields=true
					local turnTokenObj=getObjectFromGUID(player.turnOrderTokenGUID)
					local turnTokenFaceUp=turnTokenObj~=nil and turnTokenObj.is_face_down==false

					--Use City Model location as Avatar Location if in City.
					if player.avatarLocation:sub(1, 4)=="city" or player.avatarLocation=="Volkare's Camp" then
						for zoneGUID, citySearch in pairs(cityScriptZones) do
							local zoneObj=getObjectFromGUID(zoneGUID)
							if zoneObj~=nil then
								local mageFound=false
								for _, detail in pairs(zoneObj.getObjects()) do
									if detail.getName()==player.mage then mageFound=true break end
								end
								if mageFound==true then
									if zoneGUID==volkare.discZone and (gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four") then
										local volkareObj=getObjectFromGUID(gStates.volkareModel)
										if volkareObj~=nil then avPos=volkareObj.getPosition() end
									else
										local cityObj=getObjectFromGUID(citySearch.cityGUID)
										if cityObj~=nil then avPos=cityObj.getPosition() end
									end
									local cityMonsters=gStates.cityMonsterQty[citySearch.cityGUID]
									if cityMonsters~=nil then
										for _, state in pairs(cityMonsters) do
											if state=="alive" then cityHasMonsters=true cityHasShields=false break end
										end
									end
									break
								end
							end
						end
					end

					--Only inspect objects in this avatar's neighbouring spatial buckets for local controls.
					local ruin="fight"
					local shieldCount=0
					for _, mapDetails in ipairs(avatarButtonNearbyObjects(mapButtonBuckets, avPos)) do
						local mapObject=mapDetails.obj
						local avatarToObjDistSquared=((mapDetails.position[1]-avPos[1])^2)+((mapDetails.position[3]-avPos[3])^2)
						if gStates.preEndTurn==false and monsterPugs[mapDetails.guid]~=nil and monsterPugs[mapDetails.guid].pugType=="yellow" and monsterPugs[mapDetails.guid].monsters==nil and avatarToObjDistSquared<1 and mapObject.is_face_down==false then
							ruin="offer"
							avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id="Attack"..details.mage,
								onClick="global/attackLocation",
								height=70/scale, width=50/scale,
								position="0 "..tostring(100/scale).." "..tostring(-25/scale), rotation="0 0 180",
								color="rgba(0,0,0,0.0)"},
								children={{tag="Image", attributes={image="Offer Button"}}}}
						end
						if mapDetails.name=="Shield" and volkarePursuitShieldRegistered(mapObject)~=true and avatarToObjDistSquared<1.44 then
							if mageShield==nil then mageShield={} end
							mageShield[mapDetails.description]=true
							shieldCount=shieldCount+1
						end
						if mapDetails.name:sub(-6)=="Marker" and avatarToObjDistSquared<1 then
							mageMarker[mapDetails.name:sub(1, #mapDetails.name-7)]=true
						end
					end

					--Rampager and destroyed-site buttons can remain on remote objects, so refresh this small list for the active player.
					if order==gStates.turnNumber and gStates.preEndTurn==false then
						for _, mapDetails in ipairs(mapActionObjects) do
							local mapObject=mapDetails.obj
							local avatarToObjDistSquared=((mapDetails.position[1]-avPos[1])^2)+((mapDetails.position[3]-avPos[3])^2)
							if gStates.rampagingMonsters[mapDetails.guid]==true then
								local existingButtons=mapObject.UI.getXmlTable() or {}
								local keptButtons={}
								for _, xmlParent in pairs(existingButtons) do if xmlParent.tag~="Button" then keptButtons[#keptButtons+1]=xmlParent end end
								existingButtons=keptButtons
								if player.combatIconHide~="Both" and turnTokenFaceUp==true and (avatarToObjDistSquared<9.61 or (avatarToObjDistSquared<26.01 and gStates.ambushingMonsters[mapDetails.guid]~=nil)) then
									existingButtons[#existingButtons+1]={tag="Button", attributes={id=mapDetails.guid..details.mage,
										onClick="global/attackLocation",
										height=70/0.9, width=70/0.9,
										position="0 "..tostring(120/0.9).." "..tostring(-20/0.9), rotation="0 0 180",
										color="rgba(0,0,0,0.0)"},
									children={{tag="Image", attributes={image="Attack Button"}}}}
								end
								if #existingButtons==0 then existingButtons={{}} end
								mapObject.UI.setXmlTable(existingButtons)
							end
							if gStates.gameScenario=="Against the Apocalypse Blitz" and gStates.destroyedSites~=nil and gStates.destroyedSites[mapDetails.guid]~=nil then
								local existingButtons=mapObject.UI.getXmlTable() or {}
								local keptButtons={}
								for _, xmlParent in pairs(existingButtons) do if xmlParent.tag~="Button" then keptButtons[#keptButtons+1]=xmlParent end end
								existingButtons=keptButtons
								if player.combatIconHide~="Both" and turnTokenFaceUp==true and avatarToObjDistSquared<9.61 and avatarToObjDistSquared>1 then
									existingButtons[#existingButtons+1]={tag="Button", attributes={id=mapDetails.guid..details.mage,
										onClick="global/destroyRestoreLocation",
										height=100/0.9, width=100/0.9,
										position="0 "..tostring(120/0.9).." "..tostring(-20/0.9), rotation="0 0 180",
										color="rgba(0,0,0,0.0)"},
									children={{tag="Image", attributes={image="Restore Button"}}}}
								end
								if #existingButtons==0 then existingButtons={{}} end
								mapObject.UI.setXmlTable(existingButtons)
							end
						end
					end

					local dungeonLordsConqueredSite=gStates.gameScenario=="Dungeon Lords" and (player.avatarLocation=="dungeon" or player.avatarLocation=="tomb") and mageShield~=nil

					--Marker can be dropped
					if mageMarker[details.mage]==nil then
						avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id=details.markerContainer.."MarkerDrop",
							onClick="global/shieldDrop",
							height=70/scale, width=70/scale,
							position=tostring(-70/scale).." "..tostring(100/scale).." "..tostring(-25/scale), rotation="0 0 180",
							color="rgba(0,0,0,0.0)"},
							children={{tag="Image", attributes={image="Marker Button "..details.mage}}}}
					end
					--Shield can be dropped
					if player.avatarLocation~=nil and ((mageShield==nil and (player.avatarLocation=="keep" or player.avatarLocation=="mage tower"
							or player.avatarLocation=="monastery" or player.avatarLocation=="ruin"
							or ((player.avatarLocation=="dungeon" or player.avatarLocation=="tomb") and gStates.gameScenario~="Dungeon Lords")
							or player.avatarLocation=="monster den" or player.avatarLocation=="spawning grounds"
							or (player.avatarLocation=="glade" and (gStates.gameScenario=="Life and Death" or gStates.gameScenario=="Druid Nights"))
							or (player.avatarLocation=="graveyard" and (gStates.gameScenario~="The Realm of the Dead Blitz" or realmDeadEnemiesAtPosition(avPos)~=true)))
						or ((player.avatarLocation=="maze" or player.avatarLocation=="labyrinth") and shieldCount<3 and (mageShield==nil or mageShield[details.mage]==nil))
						or ((player.avatarLocation=="ziggurat" or player.avatarLocation=="pyramid") and shieldCount<3 and (mageShield==nil or mageShield[details.mage]==nil))
						or (player.avatarLocation=="glade" and mageShield~=nil and mageShield[details.mage]==nil)
						or ((player.avatarLocation:sub(1, 4)=="city" or player.avatarLocation=="Volkare's Camp") and cityHasShields==false and scenarioList[gStates.scenarioRef][gStates.playersRef].cityLevels[#scenarioList[gStates.scenarioRef][gStates.playersRef].cityLevels]~=0))) then
						avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id=details.shieldContainer.."ShieldDrop",
							onClick="global/shieldDrop",
							height=70/scale, width=70/scale,
							position=tostring(62/scale).." "..tostring(100/scale).." "..tostring(-25/scale), rotation="0 0 180",
							color="rgba(0,0,0,0.0)"},
							children={{tag="Image", attributes={image="Shield Button "..details.mage}}}}
					end
					--Attack / Volkare Pursuit / Druid Ritual share one compact vertical stack.
					--Each available action takes the next 70-unit slot, so unavailable actions leave no gaps.
					local specialActionY=100
					--monster can be fought at avatar location
					if gStates.preEndTurn==false and player.avatarLocation~=nil and order==gStates.turnNumber and player.combatIconHide=="None" and turnTokenFaceUp==true
						and ((mageShield==nil and (player.avatarLocation=="mage tower"
							or player.avatarLocation=="monster den" or player.avatarLocation=="spawning grounds"
							or (player.avatarLocation=="glade" and gStates.gameScenario=="Life and Death") or player.avatarLocation=="graveyard"
							or (player.avatarLocation=="mine" and gStates.gameScenario=="Mines Liberation")
							or (player.avatarLocation:sub(1, 4)=="city" and gStates.gameScenario=="The Lost Relic Blitz")
							or player.avatarLocation=="monastery" or (player.avatarLocation=="ruin" and ruin=="fight")))
						or (((player.avatarLocation=="dungeon" or player.avatarLocation=="tomb") and dungeonLordsConqueredSite~=true)
							or player.avatarLocation=="hidden valley"
							or player.avatarLocation=="necropolis"
							or (player.avatarLocation=="keep"
								and (((mageShield==nil or mageShield[details.mage]==nil)
								and (gStates.coop==0 or gStates.WarOfFourComp==true))
									or (mageShield==nil and gStates.coop==1 and gStates.WarOfFourComp~=true)))
							or ((player.avatarLocation=="maze" or player.avatarLocation=="labyrinth") and shieldCount<3 and (mageShield==nil or mageShield[details.mage]==nil))
							or ((player.avatarLocation=="ziggurat" or player.avatarLocation=="pyramid") and shieldCount<3 and (mageShield==nil or mageShield[details.mage]==nil))
							or ((player.avatarLocation:sub(1, 4)=="city" or player.avatarLocation=="Volkare's Camp") and cityHasMonsters==true and scenarioList[gStates.scenarioRef][gStates.playersRef].cityLevels[#scenarioList[gStates.scenarioRef][gStates.playersRef].cityLevels]~=0))) then
						avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id="Attack"..details.mage,
							onClick="global/attackLocation",
							height=70/scale, width=70/scale,
							position="0 "..tostring(specialActionY/scale).." "..tostring(-25/scale), rotation="0 0 180",
							color="rgba(0,0,0,0.0)"},
							children={{tag="Image", attributes={image="Attack Button"}}}}
						specialActionY=specialActionY+70
					end
					--Against the Horsemen: a Horseman can only be attacked from the same hex. Keep this as a
					--separate Avatar action so an unconquered site's normal Attack can be chosen without also
					--adding the Horseman. If the Horseman action is chosen on a fortified site, attackLocation
					--still brings that site's mandatory defenders into the same combat.
					if gStates.preEndTurn==false and order==gStates.turnNumber and player.combatIconHide~="Both" and turnTokenFaceUp==true then
						for _,horseOption in ipairs(againstHorsemenAttackOptions(order,avPos)) do
							avatarButton[1].children[#avatarButton[1].children+1]={tag="Button",attributes={id="Horse|"..horseOption.key.."|"..details.mage,
								onClick="global/againstHorsemenAttackAction",height=70/scale,width=70/scale,
								position="0 "..tostring(specialActionY/scale).." "..tostring(-25/scale),rotation="0 0 180",color="rgba(0,0,0,0.0)"},
								children={{tag="Image",attributes={image="https://steamusercontent-a.akamaihd.net/ugc/12647478740119221952/A4E3602A20A7A1C0FA03DA5C0FBEDF8910DE1E7D/"}}}}
							specialActionY=specialActionY+70
						end
					end
					--Once the Volkare's Quest portal is closed it is an ordinary hex; if Volkare shares it with the active Mage Knight, use his dedicated army attack path.
					if gStates.preEndTurn==false and order==gStates.turnNumber and player.combatIconHide=="None" and turnTokenFaceUp==true
						and gStates.gameScenario=="Volkare's Quest" and gStates.volkarePortalClosed==true and player.avatarLocation=="portal"
						and gStates.volkareModel~=nil then
						local volkareObj=getObjectFromGUID(gStates.volkareModel)
						if volkareObj~=nil then
							local volkarePos=volkareObj.getPosition()
							if ((volkarePos[1]-avPos[1])^2)+((volkarePos[3]-avPos[3])^2)<1 then
								avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id="Volkar"..details.mage,
									onClick="global/attackLocation",
									height=70/scale, width=70/scale,
									position="0 "..tostring(specialActionY/scale).." "..tostring(-25/scale), rotation="0 0 180",
									color="rgba(0,0,0,0.0)"},
									children={{tag="Image", attributes={image="Attack Button"}}}}
								specialActionY=specialActionY+70
							end
						end
					end
					--Conquered Camp-as-City Pursuit. The fourth slot is shared with Druid Nights; if both are legal, Druid moves one slot higher.
					local pursuitInfo=volkarePursuitAvailable(order)
					if pursuitInfo~=nil then
						if gStates.volkarePursuitChoicePlayer==order then
							local choices={{"Green",-58,"rgb(0.25,0.72,0.25)"},{"Red",0,"rgb(0.78,0.22,0.22)"},{"Both",58,"rgb(0.75,0.75,0.75)"}}
							for _,choice in ipairs(choices) do
								avatarButton[1].children[#avatarButton[1].children+1]={tag="Button",attributes={id="VPursuit"..choice[1].."|"..details.mage,onClick="global/volkarePursuitAction",
									height=58/scale,width=54/scale,position=tostring(choice[2]/scale).." "..tostring(specialActionY/scale).." "..tostring(-25/scale),rotation="0 0 180",color=choice[3]},
									children={{tag="Text",attributes={text=choice[1]=="Both" and "G+R" or choice[1]:sub(1,1),fontSize=24/scale,color="rgb(1,1,1)",alignment="MiddleCenter"}}}}
							end
						else
							avatarButton[1].children[#avatarButton[1].children+1]={tag="Button",attributes={id="VPursuitOpen|"..details.mage,onClick="global/volkarePursuitAction",
								height=70/scale,width=70/scale,position="0 "..tostring(specialActionY/scale).." "..tostring(-25/scale),rotation="0 0 180",color="rgba(0,0,0,0.0)"},
								children={{tag="Image",attributes={image=volkarePursuitButtonImageURL}}}}
						end
						specialActionY=specialActionY+70
					end
					--Druid nights
					if player.avatarLocation~=nil and order==gStates.turnNumber and player.combatIconHide=="None" and turnTokenFaceUp==true and gStates.gameScenario=="Druid Nights" and #player.gladesMarked>=1 and gStates.dayRound==false and player.druidNightsLastRitualRound~=gStates.currentRound and druidNightsCanIncantHere(order)==true then
						avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id="Incant"..details.mage,
							onClick="global/druidNightsRitualAction",height=70/scale,width=70/scale,
							position="0 "..tostring(specialActionY/scale).." "..tostring(-25/scale),rotation="0 0 180",color="rgba(0,0,0,0.0)"},children={{tag="Image",attributes={image="Incantation Button"}}}}
					end
					--Restore Site. The Apocalypse expansion only permits restoration in Against the Apocalypse.
					if gStates.gameScenario=="Against the Apocalypse Blitz" and player.avatarLocation~=nil and order==gStates.turnNumber and player.combatIconHide=="None" and turnTokenFaceUp==true and player.avatarLocation=="destroyed" then
						avatarButton[1].children[#avatarButton[1].children+1]={tag="Button", attributes={id="Restor"..details.mage,
							onClick="global/destroyRestoreLocation",
							height=70/scale, width=70/scale,
							position="0 "..tostring(100/scale).." "..tostring(-25/scale), rotation="0 0 180",
							color="rgba(0,0,0,0.0)"},
							children={{tag="Image", attributes={image="Restore Button"}}}}
					end
					if #avatarButton[1].children==0 then avatarButton={{}} end
					local avatarXmlSignature=avatarButtonXmlSignature(avatarButton, scale, rotation)
					applyAvatarButtonXml(modelObj, avatarButton, avatarXmlSignature)
					applyAvatarButtonXml(tokenObj, avatarButton, avatarXmlSignature)
					applyAvatarButtonXml(standeeObj, avatarButton, avatarXmlSignature)
				end
			end
		end
		addAvatarPause=true
	end, 5) end
	addAvatarPause=false
end

--Refresh all deployed City level/Megapolis controls from their authoritative stored state.
function addCityButtons()
	if gStates.gameScenario~="The Lost Relic Blitz" then
		for deployedCityGUID, _ in pairs(gStates.cityDeployOrder or {}) do
			local data=gStates.cityMonsterQty~=nil and gStates.cityMonsterQty[deployedCityGUID] or nil
			local terrainGUID=data~=nil and data.extra~=nil and data.extra.terainGUID or nil
			if terrainGUID~=nil and getObjectFromGUID(deployedCityGUID)~=nil then cityLevelButtons(deployedCityGUID,terrainGUID) end
		end
		if gStates.volkareModel~=nil and getObjectFromGUID(gStates.volkareModel)~=nil then cityLevelButtons(gStates.volkareModel,"Volkar") end
	end
end

--drop a shield or marker on avatar location
function shieldDrop(player, mouseButton, id)
	if mouseButton=="-1" then
		for _, details in pairs(mageKnights) do
			local tempPos={}
			if getObjectFromGUID(details.model)~=nil then tempPos=getObjectFromGUID(details.model).getPosition() end
			if getObjectFromGUID(details.token)~=nil then tempPos=getObjectFromGUID(details.token).getPosition() end
			if getObjectFromGUID(details.standee)~=nil then tempPos=getObjectFromGUID(details.standee).getPosition() end
			if details.shieldContainer==id:sub(1, 6) then
				local sitePlayer=nil
				local sitePlayerIndex=nil
				for playerIndex,candidate in pairs(turnOrder) do if candidate.mage==details.mage then sitePlayer=candidate sitePlayerIndex=playerIndex break end end
				if gStates.gameScenario=="The Lost Relic Blitz" and sitePlayer~=nil and (sitePlayer.avatarLocation:sub(1,4)=="city" or sitePlayer.avatarLocation=="Volkare's Camp") then
					broadcastToAll("Defeat the Draconum to recover this Relic piece.", warningColor)
					addAvatarButtons()
					return
				end
				if gStates.gameScenario=="The Realm of the Dead Blitz" and sitePlayer~=nil and sitePlayer.avatarLocation=="graveyard" and realmDeadEnemiesAtPosition(tempPos)==true then
					broadcastToAll("Defeat the Graveyard enemies before sealing it.", warningColor)
					addAvatarButtons()
					return
				end
				if gStates.gameScenario=="Dungeon Lords" and sitePlayer~=nil and (sitePlayer.avatarLocation=="dungeon" or sitePlayer.avatarLocation=="tomb") then
					broadcastToAll("Dungeon Lords: Dungeons and Tombs are marked only after their combat is won.",positionToColor(gStates.turnNumber))
					addAvatarButtons()
					return
				end
				local shield=getObjectFromGUID(details.shieldContainer).takeObject({position={tempPos[1], 3, tempPos[3]}})
				if shield~=nil and gStates.gameScenario=="The Realm of the Dead Blitz" and sitePlayer~=nil and sitePlayer.avatarLocation=="graveyard" and sitePlayerIndex~=nil then
					refreshPlayerReputationFromShield(sitePlayerIndex)
					if sitePlayer.repGain<(7-sitePlayer.reputation) then
						sitePlayer.repGain=sitePlayer.repGain+1
						broadcastToAll(tostring(sitePlayer.mage).." sealed a Graveyard: +1 Reputation pending.", positionToColor(sitePlayerIndex))
						mainUIUpdate("Graveyard sealed")
					end
				end
				Wait.frames(function() Wait.condition(function()
					shield.lock()
					addAvatarButtons()
				end, function() return shield.resting end) end, 10)
				break
			end
			if details.markerContainer==id:sub(1, 6) then
				local marker=getObjectFromGUID(details.markerContainer).takeObject({position={tempPos[1], 3, tempPos[3]}})
				Wait.frames(function() Wait.condition(function()
					marker.lock()
					addAvatarButtons()
				end, function() return marker.resting end) end, 10)
				break
			end
		end
	end
end

--Build the buttons that live on a monster token so attaching/detaching Possessed updates them immediately.
function monsterObjectButtons(obj, forcedPossessed)
	local addedButtons={}
	if obj==nil or obj.guid==nil or monsterPugs[obj.guid]==nil then return addedButtons end
	local possessedAttached=forcedPossessed
	if possessedAttached==nil then
		possessedAttached=false
		for _, attachment in pairs(obj.getAttachments()) do
			if monsterPugs[attachment.guid]~=nil and monsterPugs[attachment.guid].pugType=="possessed" then possessedAttached=true break end
		end
	end
	if monsterPugs[obj.guid].monsters~=nil and monsterPugs[obj.guid].pugType~="yellow" and gStates.summonStates[obj.guid]~="SummonDone" then
		local summonButtonX=possessedAttached and 200 or 120
		addedButtons[#addedButtons+1]={tag="Button", attributes={id=obj.guid, onClick="global/summonMonster", height=70/0.9, width=70/0.9,
			position=tostring(summonButtonX/0.9).." 0 "..tostring(-15/0.9), rotation="0 0 180", color="rgba(0,0,0,0.0)"},
			children={{tag="Image", attributes={image="Attack Button"}}}}
	end
	local dragonGroundButtons=apocalypseDragonGroundHeadButtons~=nil and apocalypseDragonGroundHeadButtons(obj) or {}
	for _,button in ipairs(dragonGroundButtons) do addedButtons[#addedButtons+1]=button end
	if obj.guid==darkCrusader.token or obj.guid==elementalist.token then
		addedButtons[#addedButtons+1]={tag="Button", attributes={id=obj.guid.."OverkillUp", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", onClick="global/adjustOverkill", height=50/0.9, width=50/0.9,
			color="rgba(0,0,0,0.0)", position="-62 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"}, children={{tag="Image", attributes={id=obj.guid.."OverkillUpImage", image="Overkill Up"}}}}
		addedButtons[#addedButtons+1]={tag="Image", attributes={image="Overkill Text", height=50/0.9, width=55/0.9, position="0 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
			children={{tag="Text", attributes={id=obj.guid.."Overkill", color="rgb(0,0,0)", fontSize="45", fontStyle="Bold", alignment="MiddleCenter", text=gStates.leaderOverkill}}}}
		addedButtons[#addedButtons+1]={tag="Button", attributes={id=obj.guid.."OverkillDown", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", onClick="global/adjustOverkill", height=50/0.9, width=50/0.9,
			color="rgba(0,0,0,0.0)", position="62 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"}, children={{tag="Image", attributes={id=obj.guid.."OverkillDownImage", image="Overkill Down"}}}}
	end
	if possessedAttached then
		addedButtons[#addedButtons+1]={tag="Button", attributes={id="detach"..obj.guid, onClick="global/attachEnemy", height=30, width=30, color="rgba(0,0,0,0.0)", position="62 -100 -15", rotation="0 0 180"},
			children={{tag="Image", attributes={id=obj.guid.."detachImage", image="Unlink Button"}}}}
	end
	return addedButtons
end

--Refresh monster object UI without passing an empty table to TTS.
function setMonsterObjectButtons(obj, forcedPossessed)
	if obj==nil then return end
	local buttons=monsterObjectButtons(obj, forcedPossessed)
	if #buttons>0 then obj.UI.setXmlTable(buttons) else obj.UI.setXmlTable({{}}) end
end

--Object UI is not reliably restored by TTS after load/rewind. Rebuild a faction Leader's
--combat controls when the real Leader token is in either a player's Play Area or Unit Area.
function refreshLeaderOverkillButtons()
	for _, leaderGUID in ipairs({darkCrusader.token, elementalist.token}) do
		local leaderObj=getObjectFromGUID(leaderGUID)
		if leaderObj~=nil and objectInPlayerCombatArea(leaderGUID)==true then setMonsterObjectButtons(leaderObj) end
	end
end

--Remove Possessed from an enemy and return the detached token references.
function clearPossessedEnemy(obj)
	local detached={}
	if obj==nil then return detached end
	if #obj.getAttachments()>0 then detached=obj.removeAttachments() end
	if gStates.apocalypsePossessedEnemyByToken~=nil then
		for _, token in pairs(detached or {}) do gStates.apocalypsePossessedEnemyByToken[token.guid]=nil end
	end
	if gStates.apocalypsePossessedFactionByEnemy~=nil then gStates.apocalypsePossessedFactionByEnemy[obj.guid]=nil end
	--Keep detached Possessed-token faction data until the token itself is discarded. Quest-generated
	--Possessed tokens need that identity to award the correct faction reward after separation.
	if gStates.monsterPerks[obj.guid]~=nil then
		gStates.monsterPerks[obj.guid].fame=nil
		gStates.monsterPerks[obj.guid].attack=nil
		gStates.monsterPerks[obj.guid].reward=nil
		gStates.monsterPerks[obj.guid].boost=nil
		gStates.monsterPerks[obj.guid].armour=nil
		gStates.monsterPerks[obj.guid].faction=nil
		gStates.monsterPerks[obj.guid].questHalfFame=nil
	end
	local tokenValues=obj.getRotationValues()
	for _, rotationData in pairs(tokenValues) do
		for type, data in pairs(rotationData) do
			if type=="value" and data:sub(1, 10)=="Possessed " then rotationData[type]=data:sub(11) end
		end
	end
	obj.setRotationValues(tokenValues)
	setMonsterObjectButtons(obj, false)
	return detached
end

--Link and Unlink the chosen enemy
local justDetached={}
function attachEnemy(player, mouseButton, id, obj, zone)
	--find nearest monster
	if id=="attach" and obj~=nil then
		Wait.frames(function() Wait.condition(function()
			if getObjectFromGUID(obj.guid)~=nil then
				if gStates.apocalypsePossessedEnemyByToken~=nil and gStates.apocalypsePossessedEnemyByToken[obj.guid]~=nil then return end
				local zoneObj=zone~=nil and zone.guid~=nil and getObjectFromGUID(zone.guid) or nil
				local candidates=zoneObj~=nil and zoneObj.getObjects() or getAllObjects()
				for _, nearEnemy in pairs(candidates) do
					if nearEnemy.guid~=obj.guid and monsterPugs[nearEnemy.guid]~=nil and monsterPugs[nearEnemy.guid].pugType~="possessed" and justDetached[nearEnemy.guid]~=true and
						nearEnemy.getPosition()[1]-obj.getPosition()[1]>-0.5 and nearEnemy.getPosition()[1]-obj.getPosition()[1]<0.5 and nearEnemy.getPosition()[3]-obj.getPosition()[3]>-0.5 and nearEnemy.getPosition()[3]-obj.getPosition()[3]<0.5 then
						--Assign perks to monster token
						local perkToCheck={"fame", "attack", "reward", "boost", "armour"}
						for _, perk in pairs(perkToCheck) do
							if not (perk=="attack" and monsterPugs[nearEnemy.guid].monsters~=nil) then
								if monsterPugs[obj.guid][perk]~=nil then
									if gStates.monsterPerks[nearEnemy.guid]==nil then
										gStates.monsterPerks[nearEnemy.guid]={[perk]=monsterPugs[obj.guid][perk]}
									else if gStates.monsterPerks[nearEnemy.guid][perk]==nil then
										gStates.monsterPerks[nearEnemy.guid][perk]=monsterPugs[obj.guid][perk]
									else
										local current=gStates.monsterPerks[nearEnemy.guid][perk]
										local added=monsterPugs[obj.guid][perk]
										if perk=="attack" and type(current)=="table" and type(added)=="table" then
											--Attack perks are tables of damage-type lists, not numbers. Preserve every attack instead
											--of trying to add the tables (which caused the second Possessed token to error).
											for attackType, values in pairs(added) do
												if current[attackType]==nil then current[attackType]={} end
												for _, value in pairs(values) do current[attackType][#current[attackType]+1]=value end
											end
										elseif type(current)=="number" and type(added)=="number" then
											gStates.monsterPerks[nearEnemy.guid][perk]=current+added
										else
											gStates.monsterPerks[nearEnemy.guid][perk]=added
										end
									end end
								end
							end
						end
						local possessedFaction=(gStates.apocalypsePossessedFactionByToken~=nil and gStates.apocalypsePossessedFactionByToken[obj.guid]) or "Apoc"
						gStates.monsterPerks[nearEnemy.guid].faction=possessedFaction
						if gStates.apocalypsePossessedFactionByEnemy==nil then gStates.apocalypsePossessedFactionByEnemy={} end
						gStates.apocalypsePossessedFactionByEnemy[nearEnemy.guid]=possessedFaction
						--Add "Possessed" to enemy name.
						local tokenValues=nearEnemy.getRotationValues()
						for rot, rotationData in pairs(tokenValues) do
							for type, data in pairs(rotationData) do
								if type=="value" then tokenValues[rot][type]="Possessed "..data end
							end
						end
						nearEnemy.setRotationValues(tokenValues)
						--Link Enemy and possessed token
						obj.setPosition({nearEnemy.getPosition()[1],nearEnemy.getPosition()[2]+0.05,nearEnemy.getPosition()[3]})
						obj.setRotation({0.00, 180.00, 0.00})
						if gStates.apocalypsePossessedEnemyByToken==nil then gStates.apocalypsePossessedEnemyByToken={} end
						gStates.apocalypsePossessedEnemyByToken[obj.guid]=nearEnemy.guid
						nearEnemy.addAttachment(obj)
						local summonedPossessed=gStates.summonStates~=nil and (gStates.summonStates[nearEnemy.guid]=="summoned" or gStates.summonStates[obj.guid]=="summoned")
						if summonedPossessed~=true and zone~=nil and (zone.guid==playerPlayAreas[2] or zone.guid==playerPlayAreas[3] or zone.guid==playerPlayAreas[1] or zone.guid==playerPlayAreas[4]) then
							turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+gStates.monsterPerks[nearEnemy.guid].fame
							if factionRewardUsesJustFame(possessedFaction)==true then turnOrder[gStates.turnNumber].fameGain=turnOrder[gStates.turnNumber].fameGain+1 end
						end
						--Refresh the monster UI now that Possessed is attached.
						setMonsterObjectButtons(nearEnemy, true)
						if apocalypseQuestsUsed()==true then Wait.frames(function() apocalypseQuestRefreshOfferButtons() end,2) end
						Wait.frames(function() mainUIUpdate("possessed") end, 5)
						broadcastToAll("Enemy Possessed")
						break
					end
				end
			end
		end, function() return obj==nil or obj.resting end) end, 5)
	end
	--Unlink Object
	--seperate possessed tokens
	if id:sub(1, 6)=="detach" then
		if obj==nil then obj=getObjectFromGUID(id:sub(7, 13)) end
		justDetached[obj.guid]=true
		clearPossessedEnemy(obj)
		Wait.time(function() justDetached[obj.guid]=false end, 2)
		broadcastToAll("Enemy Seperated")
	end
end

--move monster tokens to player board
--gStates.attackedMonsters={}--guid={location, rotation}
--Record/compare the actual map hex so picking an avatar up does not undo a site interaction unless it leaves the hex.
function avatarHexIdentity(pos)
	local terrain, bearing=terrainHexAtPosition(pos)
	if terrain~=nil then return {terrainGUID=terrain.guid, bearing=bearing} end
end
function avatarMovedFromPickedUpHex(pos)
	local droppedHex=avatarHexIdentity(pos)
	if playerPickedUpHex~=nil and droppedHex~=nil then
		return playerPickedUpHex.terrainGUID~=droppedHex.terrainGUID or playerPickedUpHex.bearing~=droppedHex.bearing
	end
	if playerPickedUpPos[1]==nil then return false end
	return math.sqrt(((pos[1]-playerPickedUpPos[1])^2)+((pos[3]-playerPickedUpPos[3])^2))>1.5
end

--Undo temporary site/combat state only after a human moves the current avatar to a different hex.
function leaveAvatarSite(player)
	local playArea=getObjectFromGUID(playerPlayAreas[player.seatPos])
	if playArea~=nil then
		--Undo Possessed before returning the enemy so the attachment becomes a real token again.
		for _, obj in pairs(playArea.getObjects()) do
			if monsterPugs[obj.guid]~=nil then
				local possessedAttached=false
				for _, attachment in pairs(obj.getAttachments()) do
					if monsterPugs[attachment.guid]~=nil and monsterPugs[attachment.guid].pugType=="possessed" then possessedAttached=true break end
				end
				if possessedAttached then
					for _, attachment in pairs(clearPossessedEnemy(obj)) do
						local details=gStates.attackedMonsters[attachment.guid]
						if details~=nil then
							attachment.setRotation(details[2])
							attachment.setPositionSmooth(details[1])
							gStates.attackedMonsters[attachment.guid]=nil
						end
					end
				end
				if gStates.summonStates[obj.guid]=="SummonDone" then gStates.summonStates[obj.guid]=nil end
			end
		end
	end

	for guid, details in pairs(gStates.attackedMonsters) do
		if details[3]=="summoned" then
			gStates.summonStates[guid]=nil
			if details[4]~=nil then gStates.summonStates[details[4]]=nil end
		end
		if getObjectFromGUID(guid)~=nil then
			if getObjectFromGUID(guid).getName()=="{en}Volkare Reminder Token{zh-cn}沃里卡提醒标记{ko}볼케어 공격 토큰{es}Token de recordatorio de Volkare{fr}Jeton de rappel Volkare{pt-br}Token de lembrete de Volkare" then
				getObjectFromGUID(guid).destruct()
			else
				getObjectFromGUID(guid).setRotation(details[2])
				getObjectFromGUID(guid).setPositionSmooth(details[1])
			end
		end
	end
	gStates.attackedMonsters={}
	gStates.monsterOffsetX=0
	gStates.monsterOffsetZ=0
	gStates.volkarePursuitCombat=nil
	gStates.volkarePursuitChoicePlayer=nil
	combatCameraChoiceSuppressedPlayer=nil
	player.combatIconHide="None"

	--Pyramid/Ziggurat trap reminders only belong to the site being interacted with.
	if playArea~=nil then
		for _, obj in pairs(playArea.getObjects()) do
			if obj.getGMNotes()=="Trap Reminder Token" then
				gStates.monsterPerks[obj.guid]=nil
				obj.destruct()
			end
		end
	end
	UI.setAttribute("zigguratPyramidInteract", "active", "false")
	gStates.zigguratPyramidUI=nil
end

--Optional combat camera support. Follow Enemy is a global Camera Control option and also drives the Black Game Master camera.
--It now uses the exact Player Board camera view directly; no camera is attached to moving enemy objects.
function combatCameraPlayerIndex(playerRef)
	if type(playerRef)=="number" then return turnOrder[playerRef]~=nil and playerRef or nil end
	if type(playerRef)~="table" then return nil end
	for playerIndex, details in pairs(turnOrder) do
		if details==playerRef or (playerRef.mage~=nil and details.mage==playerRef.mage) then return playerIndex end
	end
	return nil
end

--Resolve the same Player Board view used by the Camera Control button.
--Normal colours resolve from their hand/seat; Black always views the current Mage Knight.
function cameraControlPlayerBoardView(color)
	if color==nil or color=="Grey" or Player[color]==nil then return nil end
	local hand=color~="Black" and Player[color].getHandTransform() or nil
	for turn, details in pairs(turnOrder) do
		local match=(color=="Black" and turn==gStates.turnNumber) or
			(color~="Black" and hand~=nil and details.seatPos==math.ceil((hand.position[1]+97.59)/40))
		if match then
			local board=details.playerBoardGUID~=nil and getObjectFromGUID(details.playerBoardGUID) or nil
			if board==nil then return nil end
			local pos=board.getPosition()
			return {position={pos[1]+4,0,pos[3]-1}, pitch=gStates.cameraControlTopDown or 75, yaw=0, distance=27}
		end
	end
	return nil
end

--Avatar drops can immediately begin a Keep/Mage Tower assault before addAvatarButtons has refreshed
--the new hex. Resolve nearby optional Rampagers directly so Follow Enemy does not pull the camera away
--before the player has had a chance to add one to that combat.
function combatNearbyRampagerChoice(playerIndex)
	local details=turnOrder[playerIndex]
	if details==nil or gStates.preEndTurn==true or details.combatIconHide=="Both" then return false end
	local turnToken=getObjectFromGUID(details.turnOrderTokenGUID)
	if turnToken==nil or turnToken.is_face_down==true then return false end
	local avatar=mageKnightAvatarPositionByName(details.mage)
	if avatar==nil or avatar[1]==nil then return false end
	local map=getObjectFromGUID(mapArea)
	if map==nil then return false end
	for _,obj in pairs(map.getObjects()) do
		if gStates.rampagingMonsters~=nil and gStates.rampagingMonsters[obj.guid]==true then
			local pos=obj.getPosition()
			local distance=((pos[1]-avatar[1])^2)+((pos[3]-avatar[3])^2)
			if distance<9.61 or (distance<26.01 and gStates.ambushingMonsters~=nil and gStates.ambushingMonsters[obj.guid]~=nil) then return true end
		end
	end
	return false
end

--Count the attack choices that are actually being offered right now rather than duplicating all of
--addAvatarButtons' legality rules. IDs are de-duplicated because an Avatar UI can be mirrored onto its
--model/token/standee representation.
function combatAttackOptionCount(playerIndex)
	local details=turnOrder[playerIndex]
	if details==nil then return 0 end
	local seen={}
	local function scanObject(obj)
		if obj==nil then return end
		local function scanNodes(nodes)
			for _, node in pairs(nodes or {}) do
				local attributes=node.attributes or {}
				if node.tag=="Button" and attributes.onClick=="global/volkarePursuitAction" then
					local buttonID=tostring(attributes.id or "")
					if buttonID:sub(-#details.mage)==details.mage then seen["VolkarePursuit"]=true end
				end
				if node.tag=="Button" and attributes.onClick=="global/attackLocation" then
					local buttonID=tostring(attributes.id or "")
					local prefix=buttonID:sub(1,6)
					local avatarAttack=(buttonID=="Attack"..details.mage or buttonID=="Volkar"..details.mage) and details.combatIconHide=="None"
					local rampagerAttack=buttonID:sub(7)==details.mage and details.combatIconHide~="Both" and gStates.rampagingMonsters~=nil and gStates.rampagingMonsters[prefix]==true
					if avatarAttack==true or rampagerAttack==true then seen[buttonID]=true end
				end
				if node.tag=="Button" and attributes.onClick=="global/againstHorsemenAttackAction" then
					local buttonID=tostring(attributes.id or "")
					if buttonID:sub(-#details.mage)==details.mage then seen[buttonID]=true end
				end
				if node.children~=nil then scanNodes(node.children) end
			end
		end
		scanNodes(obj.UI.getXmlTable() or {})
	end
	for _, mage in pairs(mageKnights) do
		if mage.mage==details.mage then
			scanObject(getObjectFromGUID(mage.model))
			scanObject(getObjectFromGUID(mage.token))
			scanObject(getObjectFromGUID(mage.standee))
			break
		end
	end
	local map=getObjectFromGUID(mapArea)
	if map~=nil then for _, obj in pairs(map.getObjects()) do scanObject(obj) end end
	--Horseman legality is cheap to resolve directly and avoids a one-frame UI race immediately after
	--an avatar drop. This is important to Follow Enemy: a valid Horseman choice keeps the camera on the map.
	for _,option in ipairs(againstHorsemenAttackOptions(playerIndex)) do
		seen["Horse|"..tostring(option.key).."|"..details.mage]=true
	end
	local count=0
	for _ in pairs(seen) do count=count+1 end
	return count
end

function cameraControlPresetView(id)
	local pitch=gStates.cameraControlTopDown or 75
	local presets={
		offerView={position={32.0,0,-13.35},pitch=pitch,yaw=0,distance=30},
		questView={position={55.24,0.98,8.06},pitch=pitch,yaw=0,distance=27},
	}
	return presets[id]
end

--Rewards Claimed reminders use the same Follow Enemy opt-out as automatic combat camera movement.
--Move the clicking player's camera, plus Black when it is being used as the seated Game Master view.
function rewardReminderCameraFocus(playerColor,id)
	if gStates.cameraFollowEnemy~=true then return false end
	local view=cameraControlPresetView(id)
	if view==nil then return false end
	local function focus(color)
		if color==nil or color=="Grey" or Player[color]==nil or Player[color].seated~=true then return end
		Player[color].lookAt(view)
	end
	focus(playerColor)
	if playerColor~="Black" then focus("Black") end
	return true
end

function combatCameraFocus(playerRef)
	if gStates.cameraFollowEnemy~=true then return end
	local playerIndex=combatCameraPlayerIndex(playerRef)
	if playerIndex==nil then return end
	if combatCameraChoiceSuppressedPlayer==playerIndex then return end
	local color=positionToColor(playerIndex)
	local function focusViewer(viewColor)
		if viewColor==nil or viewColor=="Grey" or Player[viewColor]==nil then return end
		local view=cameraControlPlayerBoardView(viewColor)
		if view~=nil then Player[viewColor].lookAt(view) end
	end
	focusViewer(color)
	--Black is the intended multi-hand/Game Master view. Give it the same Player Board jump as its Camera Control button.
	if color~="Black" and Player["Black"]~=nil and Player["Black"].seated==true then focusViewer("Black") end
end

function volkarePursuitAction(playerDud,mouseButton,id)
	if mouseButton~="-1" then return end
	local mage=id:match("|(.+)$")
	local playerIndex=nil
	for index,details in pairs(turnOrder) do if details.mage==mage then playerIndex=index break end end
	if playerIndex==nil or playerIndex~=gStates.turnNumber then return end
	if playerDud~=nil and playerDud.color~=nil and legalPlayerCheck(playerDud.color,turnOrder[playerIndex].seatPos)~=true then return end
	local info=volkarePursuitAvailable(playerIndex)
	if info==nil then gStates.volkarePursuitChoicePlayer=nil addAvatarButtons() return end
	if id:sub(1,12)=="VPursuitOpen" then gStates.volkarePursuitChoicePlayer=playerIndex addAvatarButtons() return end
	local choice=id:match("^VPursuit([^|]+)")
	if choice~="Green" and choice~="Red" and choice~="Both" then return end
	gStates.volkarePursuitChoicePlayer=nil
	gStates.volkarePursuitCombat={player=playerIndex,hexKey=info.key,position=info.position,monsters={}}
	if gStates.volkarePursuitEnemies==nil then gStates.volkarePursuitEnemies={} end
	combatCameraChoiceSuppressedPlayer=nil
	turnOrder[playerIndex].combatIconHide="Avatar"
	gStates.monsterOffsetX=0 gStates.monsterOffsetZ=0
	if choice=="Green" or choice=="Both" then drawMonster(monsterPiles.green,turnOrder[playerIndex],"VPDraw|Green") end
	if choice=="Red" or choice=="Both" then local delay=choice=="Both" and 7 or 0 Wait.frames(function() drawMonster(monsterPiles.red,turnOrder[playerIndex],"VPDraw|Red") end,delay) end
	broadcastToAll(joinLang({translateWord[turnOrder[playerIndex].mage],"{en} pursues Volkare's fleeing army.{ru} преследует отступающую армию Волкара.{zh-cn}追击沃卡里的溃军。{ko}: 볼케어의 패주하는 군대를 추격합니다.{es} persigue al ejército en fuga de Volkare.{fr} poursuit l'armée de Volkare en fuite.{pt-br} persegue o exército em fuga de Volkare.{de} verfolgt Volkares fliehende Armee."}),positionToColor(playerIndex))
	addAvatarButtons()
end

--Druid Nights Incantation is legal anywhere the Mage Knight cannot Interact with Locals.
--Use the map's interaction helper first so burned Monasteries and conquered/unconquered sites resolve correctly;
--the logical-location fallback also covers Portal/City parking where the physical avatar may be off the map.
function druidNightsCanIncantHere(playerIndex)
	local player=turnOrder[playerIndex]
	if player==nil or gStates.gameScenario~="Druid Nights" then return false end
	local hexes,mapObjects=apocalypseQuestMapHexes()
	local hex=apocalypseQuestPlayerHex(hexes,mapObjects,playerIndex)
	if hex~=nil then return apocalypseQuestHexInteractionSite(hex,mapObjects,playerIndex)~=true end
	local location=string.lower(tostring(player.avatarLocation or ""))
	if location=="village" or location=="monastery" or location=="keep" or location=="mage tower" or location=="camp" or location=="oasis" or location=="volkare's camp" or location:sub(1,4)=="city" then return false end
	return true
end

--Druid Nights Ritual is a separate combat action from a site attack. Keep it out of attackLocation
--so a legal site defender cannot intercept or add its assault side effects to the Incantation.
function druidNightsRitualAction(playerDud, mouseButton, id)
	if mouseButton~="-1" then return end
	local mage=tostring(id or ""):match("^Incant(.+)$")
	if mage==nil then return end
	local playerIndex=nil
	for index, details in pairs(turnOrder) do if details.mage==mage then playerIndex=index break end end
	if playerIndex==nil or playerIndex~=gStates.turnNumber then return end
	local player=turnOrder[playerIndex]
	if player==nil or gStates.gameScenario~="Druid Nights" or gStates.dayRound~=false or player.combatIconHide~="None" or player.gladesMarked==nil or #player.gladesMarked<1 or player.druidNightsLastRitualRound==gStates.currentRound or druidNightsCanIncantHere(playerIndex)~=true then return end
	local turnToken=getObjectFromGUID(player.turnOrderTokenGUID)
	if turnToken==nil or turnToken.is_face_down==true then return end
	if playerDud~=nil and playerDud.color~=nil and legalPlayerCheck(playerDud.color,player.seatPos)~=true then return end

	combatCameraChoiceSuppressedPlayer=nil
	gStates.monsterOffsetX=0
	gStates.monsterOffsetZ=0
	player.combatIconHide="Both"
	player.druidNightsLastRitualRound=gStates.currentRound
	player.druidNightsRitualCount=(player.druidNightsRitualCount or 0)+1
	broadcastToAll("{en}Performed Incantation to summon Monster(s) to your Player Board{ru}Прочтено заклинание, чтобы призвать Монстра(ов) на вашу игровую доску.{zh-cn}执行了咒语召唤怪物到你的玩家板{ko}주문을 시전하여 몬스터를 소환합니다{es}Encantamiento realizado para convocar Monstruos a tu Tablero de Jugador{fr}Incantation exécutée pour invoquer des monstres sur votre plateau de joueur{pt-br}Realizou um Encantamento para invocar Monstro(S) para seu Tabuleiro de Jogador{de}Beschwörung durchgeführt, um Monster auf dein Spielerbrett zu beschwören", positionToColor(playerIndex))
	if gStates.currentRound==gStates.rounds then player.druidNightsFinalRitual=true end
	local ritualCount=#player.gladesMarked
	local crystalMultiple=gStates.currentRound>=5 and 3 or (gStates.currentRound>=3 and 2 or 1)
	gStates.druidNightsSummon=ritualCount
	gStates.druidNightsCrystalReward=ritualCount*crystalMultiple
	local monsterSummoned=gStates.currentRound>=3 and monsterPiles.red or monsterPiles.tan
	for _=1, ritualCount do Wait.frames(function() drawMonster(monsterSummoned,player,id) end,10) end
	if gStates.currentRound>=5 then
		for _=1, ritualCount do Wait.frames(function() drawMonster(monsterPiles.tan,player,id) end,10) end
	end
	--Activated Glade shields remain on the map until the end of the Night; round reset removes them.
	addAvatarButtons()
end

function attackLocation(playerDud, mouseButton, id)
	if mouseButton=="-1" then
		if turnOrder[gStates.turnNumber].mage~=gStates.positionMageKnight[5] or (id:sub(1,6)=="Volkar" and id~="VolkareAttack") then
			if id=="VolkareAttack" then id="Volkar"..turnOrder[gStates.turnNumber].mage end
			for playerIndex, player in pairs(turnOrder) do
				if player.mage==id:sub(7, string.len(id)) then
					--If the map is still offering another legal attack, keep the camera on the map while the
					--player decides which fight they actually want. Adventure Site combat cannot pull in
					--neighbouring enemies, so once that fight starts always follow its enemies to the board.
					local sameHexAttack=id:sub(1,6)=="Attack"
					local adventureSiteAttack=sameHexAttack and ({["monster den"]=true,["spawning grounds"]=true,maze=true,labyrinth=true,ruin=true,dungeon=true,tomb=true,ziggurat=true,pyramid=true})[player.avatarLocation]==true
					local nearbyRampagerChoice=sameHexAttack and adventureSiteAttack~=true and combatNearbyRampagerChoice(playerIndex)
					combatCameraChoiceSuppressedPlayer=adventureSiteAttack~=true and (combatAttackOptionCount(playerIndex)>1 or nearbyRampagerChoice==true) and playerIndex or nil
					--Work out clicking avatar location
					local avPos=mageKnightAvatarPositionByName(id:sub(7,string.len(id))) or {}
					local clickedObj=getObjectFromGUID(id:sub(1,6))
					local rampagerAttack=clickedObj~=nil and gStates.rampagingMonsters[clickedObj.guid]==true
					local sameHexAvatarAttack=sameHexAttack
					local volkareAttack=id:sub(1,6)=="Volkar"
					if avPos[1]~=nil and rampagerAttack==false then
						assaultTargetPosition={avPos[1], avPos[2], avPos[3]}
						local _, _, _, assaultTargetFeature=terrainHexAtPosition(assaultTargetPosition)
						local fortifiedSiteAttack=sameHexAvatarAttack==true and (assaultTargetFeature=="keep" or assaultTargetFeature=="mage tower")
						--Keep and Mage Tower assaults can gain a second fortification from a printed wall,
						--so resolve the target from the map and ask when their entry side is unclear.
						if (sameHexAvatarAttack==false or fortifiedSiteAttack==true) and volkareAttack==false and wallAssaultChoiceResult==nil and wallAssaultChoiceNeeded(assaultTargetPosition)==true then
							showWallAssaultChoice("attackLocation", id)
							return
						end
					elseif avPos[1]~=nil and rampagerAttack==true then
						local target=clickedObj.getPosition()
						assaultTargetPosition={target[1], target[2], target[3]}
						if gStates.ambushingMonsters[clickedObj.guid]~=nil and monsterPugs[clickedObj.guid]~=nil and monsterPugs[clickedObj.guid].unfortified==nil
							and wallAssaultChoiceResult==nil and wallAssaultChoiceNeeded(assaultTargetPosition, avPos)==true then
							showWallAssaultChoice("rampagerAttack", id)
							return
						end
					end
					--Free Wine uses an ordinary Keep assault rather than a Quest combat. Record the actual
					--attack entry here so a failed assault can legally expose Quest 10's Fail action later.
					if sameHexAvatarAttack==true and player.avatarLocation=="keep" then apocalypseQuestFreeWineMarkAssaultStarted(playerIndex) end
					--move any monster token with the same co-ordinate as the avatar
					local ruinGUID=""
					local cityGUID=nil
					local cameraFollowed=false
					if (getObjectFromGUID(id:sub(1,6))==nil and id:sub(1,6)~="Volkar") or (getObjectFromGUID(id:sub(1,6))~=nil and (player.avatarLocation=="keep" or player.avatarLocation=="mage tower" or player.avatarLocation:sub(1, 4)=="city" or player.avatarLocation=="Volkare's Camp")) then
						local horseSelection=gStates.againstHorsemenAttackSelection
						for _, monster in pairs(getObjectFromGUID(mapArea).getObjects()) do
							if monsterPugs[monster.guid]~=nil then
								local horsemanName=horsemanTokenToName~=nil and horsemanTokenToName[monster.guid] or nil
								local horsemanSelected=horsemanName==nil or (horseSelection~=nil and horseSelection.player==playerIndex and horseSelection.targets~=nil and horseSelection.targets[monster.guid]==true)
								if horsemanSelected==true and math.sqrt(((monster.getPosition()[1]-avPos[1])^2)+((monster.getPosition()[3]-avPos[3])^2))<1 then
									local originalPos=monster.getPosition()
									gStates.attackedMonsters[monster.guid]={originalPos, monster.getRotation()}
									if horsemanName~=nil then gStates.monsterPlayLocation[monster.guid]={originalPos[1],originalPos[2],originalPos[3]} end
									if cameraFollowed==false then combatCameraFocus(playerIndex) cameraFollowed=true end
									monster.setPositionSmooth({(player.seatPos*40)-96+gStates.monsterOffsetX, 2.5, -39-gStates.monsterOffsetZ})
									monster.setRotation({0.00, 180.00, 0.00})
									gStates.monsterOffsetX=gStates.monsterOffsetX+2.5
									if monsterPugs[monster.guid].monsters~=nil and monsterPugs[monster.guid].name=="Ruin" then ruinGUID=monster.guid end
								end
							end
							if player.avatarLocation:sub(1, 4)=="city" then
								if (monster.getGMNotes()=="Blue City" or monster.getGMNotes()=="Green City" or monster.getGMNotes()=="Red City" or monster.getGMNotes()=="White City")
									and math.sqrt(((monster.getPosition()[1]-avPos[1])^2)+((monster.getPosition()[3]-avPos[3])^2))<1 then
									cityGUID=monster.guid
								end
							end
						end
					end
					--The explicit selection only controls this staging pass. Wall-choice retries keep it until they reach here.
					gStates.againstHorsemenAttackSelection=nil
					--draw monsters for ruin token if undefeated tokens don't exist.
					if ruinGUID~="" and gStates.monsterOffsetX==2.5 then
						broadcastToAll("{en}Monster Drawn to Player Board{ru}Жетон врага был помещен на стол игрока{zh-cn}怪物被抽到玩家面板了{ko}몬스터와 전투합니다{es}Monstruo Dibujado al Tablero del Jugador{fr}Monstre Dessiné sur le Plateau du Joueur{pt-br}Monstro Puxado para o Tabuleiro do Jogador{de}Monster auf das Spielerbrett gezogen", positionToColor(gStates.turnNumber))
						local tokenWait=0
						for _, monsterColor in pairs(monsterPugs[ruinGUID].monsters) do
							Wait.frames(function() tokenRefill() end, tokenWait+1)
							Wait.frames(function()
								local monster=getObjectFromGUID(monsterPiles[monsterColor]).takeObject({position={(player.seatPos*40)-96+gStates.monsterOffsetX, 2.5, -39-gStates.monsterOffsetZ}, rotation={0.00, 180.00, 0.00}})--brown
								combatCameraFocus(playerIndex)
								gStates.attackedMonsters[monster.guid]={{getObjectFromGUID(monsterPiles[monsterColor]).getPosition()[1], 2+((tokenWait/5)/10), getObjectFromGUID(monsterPiles[monsterColor]).getPosition()[3]}, {0.00, 0.00, 0.00}}
                                if gStates.ruinMonsters==nil then gStates.ruinMonsters={[monster.guid]=ruinGUID} else gStates.ruinMonsters[monster.guid]=ruinGUID end
                                gStates.monsterOffsetX=gStates.monsterOffsetX+2.5
							end, tokenWait+5)
							tokenWait=tokenWait+5
						end
					end
					--draw all monsters left on city card
					if getObjectFromGUID(id:sub(1,6))==nil and (player.avatarLocation:sub(1, 4)=="city" or player.avatarLocation=="Volkare's Camp" or player.avatarLocation=="hidden valley" or player.avatarLocation=="necropolis" or id:sub(1,6)=="Volkar") then
						--figure out which city avatar is in if not dropped on the city model
						if player.avatarLocation:sub(1, 4)=="city" and cityGUID==nil then
							for zone, citySearch in pairs(cityScriptZones) do
								for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
									if detail.getName()==player.mage then
										cityGUID=citySearch.cityGUID
										break
									end
								end
							end
						end
						if player.avatarLocation=="hidden valley" then cityGUID=elementalist.terrainHex end
						if player.avatarLocation=="necropolis" then cityGUID=darkCrusader.terrainHex end
						if player.avatarLocation=="Volkare's Camp" or id:sub(1, 6)=="Volkar" then
							cityGUID=volkare.terrainHex
							if gStates.gameScenario=="Volkare's Return" or gStates.gameScenario=="Volkare's Return Blitz" or gStates.gameScenario=="Volkare's Quest" or gStates.gameScenario=="The War of Four" then
								cityGUID=volkare.model
							end
						end
						--detect if coop assault possible
						if cityGUID~=nil and gStates.gameScenario~="The Lost Relic Blitz" then
							local cityPositionGUID=cityGUID
							if cityGUID==volkare.model and gStates.volkareModel~=nil then cityPositionGUID=gStates.volkareModel end
							local cityPositionObj=getObjectFromGUID(cityPositionGUID)
							if cityPositionObj==nil then return end
							local cityPosition=cityPositionObj.getPosition()
							local magesInRange=findNearbyMages({cityPosition[1], cityPosition[2], cityPosition[3]}, 2.5)
							if gStates.cityMonsterQty[cityGUID].extra~=nil and gStates.cityMonsterQty[cityGUID].extra.megapolisPair~=nil then
								local secondCity=getObjectFromGUID(gStates.cityMonsterQty[cityGUID].extra.megapolisPair)
								if gStates.cityMonsterQty[cityGUID].extra.megapolisPair==cityGUID then
									for secCityGuid, secDetails in pairs(gStates.cityMonsterQty) do
										if secDetails.extra.megapolisPair==cityGUID and secCityGuid~=cityGUID then
											secondCity=getObjectFromGUID(secCityGuid)
											break
										end
									end
								end
								local magesInRangeTwo=findNearbyMages({secondCity.getPosition()[1], secondCity.getPosition()[2], secondCity.getPosition()[3]}, 2.5)
								for _, mageNameTwo in pairs (magesInRangeTwo) do
									local found=false
									for _, mageName in pairs (magesInRange) do
										if mageName.mage==mageNameTwo.mage then found=true end
									end
									if found==false then magesInRange[#magesInRange+1]=mageNameTwo end
								end
							end
							local count=1
							local mcount=0
							local volkareAssignment=cityGUID==volkare.model
							gStates.coopAssaultUnassigned={primary={}, secondary={}}
							gStates.assaultData={[player.mage]={primary={}, secondary={}, UIPos={count}, joined=true}}
							for monsterGUID, state in pairs(gStates.cityMonsterQty[cityGUID]) do
								if monsterGUID~="extra" and getObjectFromGUID(monsterGUID)~=nil and state~="dead" then
									local dividable=monsterGUID~=elementalist.token and monsterGUID~=darkCrusader.token
									if dividable then mcount=mcount+1 end
									local primary=(player.avatarLocation~="Volkare's Camp" and id:sub(1, 6)~="Volkar") or ((player.avatarLocation=="Volkare's Camp" or id:sub(1, 6)=="Volkar") and (monsterPugs[monsterGUID].pugType=="green" or monsterPugs[monsterGUID].pugType=="gray"))
									local secondary=(player.avatarLocation=="Volkare's Camp" or id:sub(1, 6)=="Volkar") and (monsterPugs[monsterGUID].pugType=="red" or monsterPugs[monsterGUID].pugType=="white")
									if primary then
										local destination=volkareAssignment and dividable and gStates.coopAssaultUnassigned.primary or gStates.assaultData[player.mage].primary
										destination[#destination+1]=monsterGUID
									end
									if secondary then
										local destination=volkareAssignment and dividable and gStates.coopAssaultUnassigned.secondary or gStates.assaultData[player.mage].secondary
										destination[#destination+1]=monsterGUID
									end
								end
							end
							local cityDefense=UI.getAttribute("CoopAssaultMainTableText1", "text")=="{en}Combined Defense Possible{ru}Доступна Совместная защита города{zh-tw}可以進行合作防守{zh-cn}可以进行合作防守{ko}협력 수비 가능{es}Defensa Combinada Posible{fr}Défense Combinée Possible{pt-br}Defesa Combinada Possível{de}Gemeinsame Verteidigung möglich"
							for _, mageName in pairs(magesInRange) do
								if mageName.mage~=player.mage and gStates.volkareState~="Attacking Player" then count=count+1 gStates.assaultData[mageName.mage]={primary={}, secondary={}, UIPos={count}, joined=cityDefense} end
							end
							--Volkare's shared fight can be combined even with only one army enemy; that enemy starts unassigned.
							if count>=2 and (mcount>=2 or (volkareAssignment and mcount>=1)) then
								gStates.coopAssaultCityGUID=cityGUID
								gStates.coopAssaultLocation=player.avatarLocation
								applyColorBarButtons()
								coopAssaultUIUpdate()
							else
								--No cooperative assault is actually available. For Volkare, his army was staged in the
								--shared unassigned pools while we checked whether a combined defense was possible.
								--With only one defender, give every staged enemy back to that defender before attackCity.
								local currentAssault=gStates.assaultData[player.mage]
								if volkareAssignment==true then
									for _, army in pairs({"primary", "secondary"}) do
										for _, monsterGUID in pairs(gStates.coopAssaultUnassigned[army] or {}) do
											currentAssault[army][#currentAssault[army]+1]=monsterGUID
										end
									end
								end
								gStates.assaultData={[player.mage]=currentAssault}
								gStates.coopAssaultUnassigned={}
								attackCity(nil, "-1", id:sub(1,6))
							end
						end
					end
					--Work out if avatar or rampage was clicked
					player.combatIconHide="Avatar"
					if id:sub(1,6)~="Volkar" then
						if getObjectFromGUID(id:sub(1,6))==nil then
							--use avatar location to draw Monsters if none exist
							if gStates.monsterOffsetX==0 then
								if (player.avatarLocation=="dungeon" or player.avatarLocation=="monster den" or player.avatarLocation=="maze"--brown
									or player.avatarLocation=="spawning grounds") and id:sub(1, 6)=="Attack" then--two browns
									broadcastToAll("Monster Drawn to Player Board", positionToColor(gStates.turnNumber))
									drawMonster(monsterPiles.tan, player, id)
									if player.avatarLocation=="spawning grounds" then Wait.frames(function() drawMonster(monsterPiles.tan, player, id) end, 10)	end
								end
								if player.avatarLocation=="monastery" and id:sub(1, 6)=="Attack" then drawMonster(monsterPiles.purple, player, id) broadcastToAll("{en}Monastery Defender Drawn to Player Board{ru}Жетон защитника Монастыря был помещен на стол игрока{zh-cn}修道院驻军移到玩家面板上{ko}수도원의 수비자와 전투합니다{es}Defensor del Monasterio dibujado en el tablero del jugador{fr}Défenseur du Monastère dessiné sur le plateau du joueur{pt-br}Defensor do Monastério puxado para o tabuleiro do joador{de}Verteidiger des Klosters auf Spielertafel gezogen", positionToColor(gStates.turnNumber)) end
								if (player.avatarLocation=="tomb" or player.avatarLocation=="labyrinth") and id:sub(1, 6)=="Attack" then drawMonster(monsterPiles.red, player, id) broadcastToAll("{en}Dragon Drawn to Player Board{ru}Жетон Драконума был помещен на стол игрока{zh-cn}将龙放到玩家面板{ko}드래곤과 전투하세요{es}Dragón dibujado al tablero del jugador{fr}Dragon dessiné sur le plateau du joueur{pt-br}Dragão Puxado para o tabuleiro do jogador{de}Drache auf Spielertafel gezogen", positionToColor(gStates.turnNumber)) end
								if player.avatarLocation=="keep" and id:sub(1, 6)=="Attack" then
									local found=false
									for _, shield in pairs(getObjectFromGUID(mapArea).getObjects()) do
										if shield.getName()=="Shield" and volkarePursuitShieldRegistered(shield)~=true and (shield.getDescription()==player.mage or gStates.coop==1) and math.sqrt(((shield.getPosition()[1]-avPos[1])^2)+((shield.getPosition()[3]-avPos[3])^2))<1 then found=true break end
									end
									if found==false then drawMonster(monsterPiles.gray, player, id) broadcastToAll("{en}Keep Defender Drawn to Player Board{ru}Защитник крепости был помещен на стол игрока{zh-cn}保持防御者在玩家板上{ko}성의 수비자와 전투합니다{es}Mantenga al Defensor atraído al tablero del jugador{fr}Gardez le Défenseur dessiné sur le plateau du joueur{pt-br}Defensor do Forte puxado para o tabuleiro do jogador{de}Verteidiger auf Spielerbrett gezogen halten", positionToColor(gStates.turnNumber)) end
								end
								if (player.avatarLocation=="ziggurat" or player.avatarLocation=="pyramid") then
									--update Interface to be fresh and match the location.
									UI.setAttribute("zigguratPyramidInteractClimb1", "interactable", "true")
									UI.setAttribute("zigguratPyramidInteractClimb2", "interactable", "false")
									UI.setAttribute("zigguratPyramidInteractFight1", "interactable", "true")
									UI.setAttribute("zigguratPyramidInteractFight2", "interactable", "false")
									UI.setAttribute("zigguratPyramidInteractFight3", "interactable", "false")
									UI.setAttribute("zigguratPyramidInteractFight1Image", "color", "White")
									UI.setAttribute("zigguratPyramidInteractFight2Image", "color", "Gray")
									UI.setAttribute("zigguratPyramidInteractFight3Image", "color", "Gray")
									UI.setAttribute("zigguratPyramidInteractClimb1Image", "color", "White")
									UI.setAttribute("zigguratPyramidInteractClimb2Image", "color", "Gray")
									UI.setAttribute("zigguratPyramidInteractText1", "text", "{en}Ziggurat Interaction{ru}Взаимодействие с зиккуратом{zh-tw}階梯神廟互動{zh-cn}阶梯神庙互动{ko}지구라트 상호작용{es}Interacción con el zigurat{fr}Interaction avec la ziggourat{pt-br}Interação com a Zigurate{de}Zikkurat-Interaktion")
									UI.setAttribute("zigguratPyramidInteractText2", "text", "{en}Entered Floor 1. Pick one of the three Trap Tokens\nto Deal with. Then either:-{ru}Вышли на 1-й этаж. Выберите один из трёх жетонов ловушки,\nс которым нужно разобраться. Затем либо:—{zh-tw}進入第一層，從三個陷阱中，處理其中一個。 \n然後選擇：{zh-cn}进入第一层，从三个陷阱中，处理其中一个。 \n然后选择：{ko}1층에 진입했습니다. 3개의 함정 중 하나 선택하여 방어.\n그 후 다음 중 선택:-{es}Has entrado en la planta 1. Elige una de las tres fichas de trampa\ncon las que quieres lidiar. A continuación, puedes: -{fr}Entrée au 1er étage. Choisissez l'un des trois jetons 'Piège'\nà gérer. Ensuite, vous pouvez soit : -{pt-br}Entrou no 1º andar. Escolha uma das três fichas de armadilha\npara lidar com ela. Em seguida, faça uma das seguintes opções:-{de}Du betrittst Etage 1. Wähle einen der drei Fallenzettel aus,\nmit dem du dich befassen möchtest. Dann entweder:-")
									UI.setAttribute("zigguratPyramidInteractClimb1Text", "text", "{en}Ascend to Floor 2 and Pick one of two Trap Tokens to Deal with.{ru}Поднимитесь на 2-й этаж и выберите один из двух жетонов ловушки, с которым нужно разобраться.{zh-tw}前往第二層，\n從兩個陷阱中，\n處理其中一個。{zh-cn}前往第二层，\n从两个陷阱中，\n处理其中一个。{ko}2층 등반 후 2개의 함정 중 하나 선택하여 방어{es}Subir a la planta 2 y elegir una de las dos fichas de trampa con las que enfrentarte.{fr}Monter au niveau 2 et choisir l'un des deux jetons de piège à éliminer.{pt-br}Subir para o 2º andar e escolher uma das duas fichas de armadilha para lidar.{de}Steige zu Etage 2 auf und wähle einen der beiden Fallenzettel aus, um ihn zu bewältigen.")
									UI.setAttribute("zigguratPyramidInteractFight1Text", "text", "{en}Fight the Floor 1 Apocalypse Possessed Green Enemy for 2 random Crystals.{ru}Сразитесь с зеленым врагом, одержимым Апокалипсисом, на 1-м этаже, чтобы получить 2 случайных кристалла.{zh-tw}擊敗第一層的末日附身\n綠色敵人，獲得兩顆隨機\n魔晶。{zh-cn}击败第一层的末日附身\n绿色敌人，获得两颗随机\n魔晶。{ko}1층의 '빙의된 아포칼립스' 녹색 적과 전투,  보상: 무작위 수정 2개{es}Lucha contra el enemigo verde poseído por el Apocalipsis del piso 1 para conseguir 2 cristales aleatorios.{fr}Combattez l'ennemi vert possédé par l'Apocalypse du niveau 1 pour obtenir 2 cristaux aléatoires.{pt-br}Lute contra o inimigo verde possuído pelo Apocalipse do 1º andar para ganhar 2 cristais aleatórios.{de}Bekämpfe den von der Apokalypse besessenen grünen Gegner auf Etage 1 für 2 zufällige Kristalle.")
									UI.setAttribute("zigguratPyramidInteractClimb2Text", "text", "{en}Ascend to Floor 3 and Deal with the last Trap Token.{ru}Поднимитесь на 3-й этаж и разберитесь с последним жетоном ловушки.{zh-tw}前往第三層，\n處理最後一個\n陷阱。{zh-cn}前往第三层，\n处理最后一个\n陷阱。{ko}3층 등반 후 함정 1개 방어{es}Sube al piso 3 y ocúpate de la última ficha de trampa.{fr}Montez au niveau 3 et occupez-vous du dernier jeton Piège.{pt-br}Suba para o 3º andar e lide com a última ficha de armadilha.{de}Steige zu Etage 3 auf und kümmere dich um den letzten Fallenzettel.")
									UI.setAttribute("zigguratPyramidInteractFight2Text", "text", "{en}Fight the Floor 2 Apocalypse Possessed Purple Enemy for a Spell.{ru}Сразитесь с фиолетовым врагом, одержимым Апокалипсисом, на 2-м этаже, чтобы получить заклинание.{zh-tw}擊敗第二層的末日附身\n紫色敵人，獲得一張法術{zh-cn}击败第二层的末日附身\n紫色敌人，获得一张法术{ko}2층의 '빙의된 아포칼립스' 보라색 적과 전투, 보상: 마법 카드{es}Lucha contra el enemigo morado poseído por el Apocalipsis del piso 2 para conseguir un hechizo.{fr}Combattez l'ennemi violet possédé par l'Apocalypse du niveau 2 pour obtenir un sort.{pt-br}Lute contra o inimigo roxo possuído pelo Apocalipse do 2º andar para ganhar um feitiço.{de}Bekämpfe den von der Apokalypse besessenen violetten Gegner auf Etage 2 für einen Zauber.")
									UI.setAttribute("zigguratPyramidInteractFight3Text", "text", "{en}Fight the Floor 3 Apocalypse Possessed Tan Enemy for an Artifact.{ru}Сразитесь с коричневым врагом, одержимым Апокалипсисом, на 3-м этаже, чтобы получить артефакт.{zh-tw}擊敗第三層的末日附身棕色敵人，獲得一件神器。{zh-cn}击败第三层的末日附身棕色敌人，获得一件神器。{ko}3층의 ‘빙의된 아포칼립스'  갈색 적과 전투, 보상: 유물{es}Lucha contra el enemigo marrón claro poseído por el Apocalipsis del piso 3 para conseguir un artefacto.{fr}Combattez l'ennemi beige possédé par l'Apocalypse de l'étage 3 pour obtenir un artefact.{pt-br}Lute contra o inimigo bege possuído pelo Apocalipse do Piso 3 para ganhar um artefato.{de}Kämpfe gegen den apokalypsebesessenen hellbraunen Gegner auf Etage 3 um ein Artefakt.")
									if player.avatarLocation=="pyramid" then
										UI.setAttribute("zigguratPyramidInteractText1", "text", "{en}Pyramid Interaction{ru}Взаимодействие с пирамидой{zh-tw}金字塔互動{zh-cn}金字塔互动{ko}피라미드 상호작용{es}Interacción con la pirámide{fr}Interaction avec la pyramide{pt-br}Interação com a Pirâmide{de}Pyramiden-Interaktion")
										UI.setAttribute("zigguratPyramidInteractFight1Text", "text", "{en}Fight the Floor 1 Apocalypse Possessed Gray Enemy for 2 Crystals of your choice.{ru}Сразитесь с серым врагом, одержимым Апокалипсисом, на 1-м этаже, чтобы получить 2 кристалла на ваш выбор.{zh-tw}擊敗第一層的末日附身\n灰色敵人，獲得兩顆任意\n魔晶。{zh-cn}击败第一层的末日附身\n灰色敌人，获得两颗任意\n魔晶。{ko}1층의 ‘빙의된 아포칼립스’ 회색 적과 전투, 보상: 선택 수정 2개 {es}Lucha contra el enemigo gris poseído por el Apocalipsis del piso 1 para conseguir 2 cristales de tu elección.{fr}Combattez l'ennemi gris possédé par l'Apocalypse de l'étage 1 pour obtenir 2 cristaux de votre choix.{pt-br}Lute contra o inimigo cinza possuído pelo Apocalipse do Piso 1 para ganhar 2 cristais à sua escolha.{de}Kämpfe gegen den apokalypsebesessenen grauen Gegner auf Etage 1 um 2 Kristalle deiner Wahl.")
										UI.setAttribute("zigguratPyramidInteractFight2Text", "text", "{en}Fight the Floor 2 Apocalypse Possessed White Enemy for a Spell & 2 Crystals of your choice.{ru}Сразитесь с белым врагом, одержимым Апокалипсисом, на 2-м этаже, чтобы получить заклинание и 2 кристалла на ваш выбор.{zh-tw}擊敗第二層的末日附身\n白色敵人，獲得一張法術\n和兩顆任意魔晶。{zh-cn}击败第二层的末日附身\n白色敌人，获得一张法术\n和两颗任意魔晶。{ko}2층의 ‘빙의된 아포칼립스’ 흰색 적과 전투, 보상: 마법 1장과 선택 수정 2개{es}Lucha contra el enemigo blanco poseído por el Apocalipsis del piso 2 para conseguir un hechizo y 2 cristales de tu elección.{fr}Combattez l'ennemi blanc possédé par l'Apocalypse de l'étage 2 pour obtenir un sort et 2 cristaux de votre choix.{pt-br}Lute contra o inimigo branco possuído pelo Apocalipse do Piso 2 para ganhar um feitiço e 2 cristais à sua escolha.{de}Kämpfe gegen den apokalypsebesessenen weißen Gegner auf Etage 2 um einen Zauber und 2 Kristalle deiner Wahl.")
										UI.setAttribute("zigguratPyramidInteractFight3Text", "text", "{en}Fight the Floor 3 Apocalypse Possessed Red Enemy for an Artifact & 2 Crystals of your choice.{ru}Сразитесь с красным врагом, одержимым Апокалипсисом, на 3-м этаже, чтобы получить артефакт и 2 кристалла на ваш выбор.{zh-tw}擊敗第三層的末日附身紅色敵人，\n獲得一件神器和兩顆任意魔晶。{zh-cn}击败第三层的末日附身红色敌人，\n获得一件神器和两颗任意魔晶。{ko}3층의 ‘빙의된 아포칼립스’ 적색 적과 전투, 보상: 유물 1장과 선택 수정 2개{es}Lucha contra el enemigo rojo poseído por el Apocalipsis del piso 3 para conseguir un artefacto y 2 cristales de tu elección.{fr}Combattez l'ennemi rouge possédé par l'Apocalypse de l'étage 3 pour obtenir un artefact et 2 cristaux de votre choix.{pt-br}Lute contra o inimigo vermelho possuído pelo Apocalipse do Piso 3 para ganhar um artefato e 2 cristais à sua escolha.{de}Kämpfe gegen den apokalypsebesessenen roten Gegner auf Etage 3 um ein Artefakt und 2 Kristalle deiner Wahl.")
									end
									--check for existing shields and lock off buttons.
									local avPos=mageKnightAvatarPosition(gStates.turnNumber) or {}
									local terrain, _, sitePos=terrainHexAtPosition(avPos)
									if sitePos~=nil then avPos=sitePos else avPos[3]=(math.floor(((avPos[3]-1)/2.0785)+0.5)*2.0785)+0.5 end
									local fight2Done, fight3Done=false, false
									for _, shieldCheck in pairs(getObjectFromGUID(mapArea).getObjects()) do
										if shieldCheck.getName()=="Shield" and volkarePursuitShieldRegistered(shieldCheck)~=true and math.sqrt(((shieldCheck.getPosition()[1]-avPos[1])^2)+((shieldCheck.getPosition()[3]-avPos[3])^2))<1.5 then
											local floor=zigguratPyramidFloorFromPosition(terrain, avPos, shieldCheck.getPosition())
											if floor==1 then
												UI.setAttribute("zigguratPyramidInteractFight1Image", "color", "Red")
												UI.setAttribute("zigguratPyramidInteractFight1", "interactable", "false")
											elseif floor==3 then
												UI.setAttribute("zigguratPyramidInteractFight3Image", "color", "Red")
												UI.setAttribute("zigguratPyramidInteractClimb2Image", "color", "Red")
												UI.setAttribute("zigguratPyramidInteractFight3", "interactable", "false")
												UI.setAttribute("zigguratPyramidInteractClimb2", "interactable", "false")
												fight3Done=true
											else
												UI.setAttribute("zigguratPyramidInteractFight2Image", "color", "Red")
												UI.setAttribute("zigguratPyramidInteractFight2", "interactable", "false")
												fight2Done=true
											end
										end
									end
									if fight3Done==true and fight2Done==true then
										UI.setAttribute("zigguratPyramidInteractClimb1Image", "color", "Red")
										UI.setAttribute("zigguratPyramidInteractClimb1", "interactable", "false")
									end
									UI.setAttribute("zigguratPyramidInteract", "active", "true")
									--deploy three trap tokens.
									local trapBag=monsterPiles.pyramidTrap
									if player.avatarLocation=="ziggurat" then trapBag=monsterPiles.zigguratTrap end
									drawMonster(trapBag, player, id)
									Wait.frames(function() drawMonster(trapBag, player, id) end, 10)
									Wait.frames(function() drawMonster(trapBag, player, id) end, 10)
								end
							end
							--Hide button
							if player.avatarLocation~="keep" and player.avatarLocation~="mage tower" and player.avatarLocation:sub(1, 4)~="city" and player.avatarLocation~="Volkare's Camp" and player.avatarLocation~="hidden valley" and player.avatarLocation~="necropolis" then player.combatIconHide="Both" end
							locationAttacked=true
							if gStates.coopAssaultCityGUID==nil and assaultTargetHasWall(assaultTargetPosition)==true then
								local wallFortified=resolveAssaultWallFortified(assaultTargetPosition, assaultApproachOrigin, true)
								Wait.frames(function() applyCurrentAssaultWallFortified(wallFortified) end, 15)
							end
						else
							--Rampager attacks are not assaults: the avatar stays put, so adjacent wall crossing is always known.
							--Only an Ambushing Rampager attacked from its extended range can need the manual wall answer above.
							local rampagerGUID=id:sub(1,6)
							local rampager=getObjectFromGUID(rampagerGUID)
							local target=rampager.getPosition()
							local rampagerTargetPos={target[1], target[2], target[3]}
							local wallFortified=resolveAssaultWallFortified(rampagerTargetPos, avPos, true)
							gStates.attackedMonsters[rampagerGUID]={rampager.getPosition(), rampager.getRotation()}
							setAssaultWallFortified(rampager, wallFortified)
							if cameraFollowed==false then combatCameraFocus(playerIndex) cameraFollowed=true end
							rampager.setPositionSmooth({(player.seatPos*40)-96+gStates.monsterOffsetX, 2.5, -39-gStates.monsterOffsetZ})
							settleAssaultWallFortified(rampagerGUID, wallFortified)
							rampager.setRotation({0.00, 180.00, 0.00})
							Wait.frames(function() local obj=getObjectFromGUID(rampagerGUID) if obj~=nil then obj.UI.setXmlTable({{}}) end end, 10)
							gStates.monsterOffsetX=gStates.monsterOffsetX+2.5
							locationAttacked=false
							clearWallAssaultChoice()
							assaultTargetPosition=nil
						end
					end
					addAvatarButtons()
					break
				end
			end
		else
			broadcastToAll("{en}Flip the the Turn Order token of the Mage Knight who Volkare is attacking, and finish Volkare's turn.\n(If not fully Attending the battle, manually move his tokens){ru}Переверните жетон порядка хода Героя, которого атакует Волкар, и завершите ход Волкара\n(Если вы не используете долгую подготовку к битве, вручную переместите его жетоны){zh-cn}翻转沃卡里正在攻击的玩家的顺位板，并完成沃卡里的回合\n（如果没有完成，请手动移动他的标记）{ko}볼케어가 공격하는 플레이어의 라운드 순서 토큰을 뒤집고, 볼케어의 차례를 종료합니다.\n(부분적인 전투 참여의 경우 직접 뒤집으세요.){es}Da la vuelta a la ficha de Orden de turno del Caballero mago que Volkare está atacando y termina el turno de Volkare.\n(Si no asiste por completo a la batalla, mueva manualmente sus fichas){fr}Retournez le jeton Ordre du Tour du Chevalier Mage que Volkare attaque et terminez le tour de Volkare\n(Si vous n'assistez pas complètement à la bataille, déplacez manuellement ses jetons){pt-br}Vire a ficha de ordem de turno do Mage Knight que Volkare está atacando, e termine o Turno de Volkare\n(Se não estiver Atendendo por completo a batalha, então manualmente mova suas fichas{de}Drehe das Zugreihenfolgeplättchen des Magierritters, den Volkare angreift, um und beende Volkares Zug.\n(Wenn er nicht vollständig am Kampf teilnimmt, verschiebe seine Spielsteine manuell)", warningColor)
		end
	end
end

--Lock a Destroyed Site token only after any scripted smooth move has finished and physics has had time to settle it.
function lockDestroyedSiteWhenSettled(token)
	if token==nil then return end
	local tokenGUID=token.guid
	Wait.condition(function()
		Wait.frames(function()
			Wait.condition(function()
				local obj=getObjectFromGUID(tokenGUID)
				if obj~=nil then obj.lock() end
			end, function()
				local obj=getObjectFromGUID(tokenGUID)
				return obj==nil or obj.resting
			end)
		end, 2)
	end, function()
		local obj=getObjectFromGUID(tokenGUID)
		return obj==nil or obj.isSmoothMoving()==false
	end)
end

--Destroyed Site tokens visually replace the site but do not erase conquest Shields.
--Lift Shields out of the way while the Destroyed marker settles, then place them on top.
function destroyedSiteStackShields(token,terrain,bearing)
	if token==nil or terrain==nil or bearing==nil then return false end
	local map=getObjectFromGUID(mapArea)
	if map==nil then return false end
	local center=angleToXY(terrain,bearing)
	if center==nil then return false end
	local shields={}
	for _,obj in pairs(map.getObjects()) do
		if obj.getName()=="Shield" and (volkarePursuitShieldRegistered==nil or volkarePursuitShieldRegistered(obj)~=true) then
			local pos=obj.getPosition()
			if ((pos[1]-center[1])^2)+((pos[3]-center[2])^2)<1.0 then
				shields[#shields+1]={guid=obj.guid,locked=obj.getLock()==true,x=pos[1],z=pos[3]}
			end
		end
	end
	if #shields==0 then return false end

	for index,details in ipairs(shields) do
		local shield=getObjectFromGUID(details.guid)
		if shield~=nil then
			shield.unlock()
			shield.setPosition({details.x,2.7+((index-1)*0.12),details.z})
		end
	end

	local tokenGUID=token.guid
	local function stack()
		local marker=getObjectFromGUID(tokenGUID)
		if marker==nil then return end
		local markerPos=marker.getPosition()
		for index,details in ipairs(shields) do
			local shield=getObjectFromGUID(details.guid)
			if shield~=nil then
				shield.unlock()
				--Place slightly high, then let physics settle the Shield onto the Destroyed marker.
				--Do not test resting in the same frame: TTS can preserve the old resting=true until physics starts.
				shield.setPosition({details.x,markerPos[2]+0.17+((index-1)*0.12),details.z})
				if details.locked==true then
					local shieldGUID=details.guid
					Wait.frames(function()
						Wait.condition(function()
							local settled=getObjectFromGUID(shieldGUID)
							if settled~=nil then settled.lock() end
						end,function()
							local settling=getObjectFromGUID(shieldGUID)
							return settling==nil or settling.resting==true
						end,3,function()
							local settled=getObjectFromGUID(shieldGUID)
							if settled~=nil then settled.lock() end
						end)
					end,1)
				end
			end
		end
	end
	Wait.condition(stack,function()
		local marker=getObjectFromGUID(tokenGUID)
		return marker==nil or marker.getLock()==true or (marker.isSmoothMoving()==false and marker.resting==true)
	end,5,stack)
	return true
end

--Apply Destroyed Site state from one authoritative path. positionToken=false is used when takeObject is already moving the token from its bag.
function destroySite(token, terrain, bearing, positionToken)
	if token==nil or terrain==nil or bearing==nil or terrainTiles[terrain.guid]==nil then return false end
	local feature=terrainTiles[terrain.guid].hexFeature[bearing]
	if feature==nil or feature=="" or feature=="portal" or feature=="destroyed" or feature:sub(1,7)=="raised " then return false end
	if positionToken~=false then
		local hexPos=angleToXY(terrain, bearing)
		token.unlock()
		token.setPosition({hexPos[1], 2, hexPos[2]})
		lockDestroyedSiteWhenSettled(token)
	end
	destroyedSiteStackShields(token,terrain,bearing)
	if gStates.destroyedSites==nil then gStates.destroyedSites={} end
	gStates.destroyedSites[token.guid]={hexFeature=feature, terrainTile=terrain.guid, hexAngle=bearing}
	terrainTiles[terrain.guid].hexFeature[bearing]="destroyed"
	if gStates.hexOverideSave[terrain.guid]==nil then gStates.hexOverideSave[terrain.guid]={} end
	gStates.hexOverideSave[terrain.guid][bearing]="destroyed"
	broadcastToAll(feature.." Destroyed")
	Wait.frames(function() apocalypseQuestRefreshOfferButtons() end, 2)
	return true
end

--Undo only the map assignment. Used when a player deliberately unlocks and moves an active Destroyed token.
function undoDestroyedSitePlacement(destroyed)
	if destroyed==nil or gStates.destroyedSites==nil then return false end
	local data=gStates.destroyedSites[destroyed.guid]
	if data==nil or terrainTiles[data.terrainTile]==nil then return false end
	terrainTiles[data.terrainTile].hexFeature[data.hexAngle]=data.hexFeature
	if gStates.hexOverideSave[data.terrainTile]~=nil then gStates.hexOverideSave[data.terrainTile][data.hexAngle]=nil end
	gStates.destroyedSites[destroyed.guid]=nil
	Wait.frames(function() apocalypseQuestRefreshOfferButtons() end, 2)
	return true
end

function restoreDestroyedSite(destroyed, player)
	if destroyed==nil or player==nil or gStates.destroyedSites==nil then return false end
	local data=gStates.destroyedSites[destroyed.guid]
	if data==nil or terrainTiles[data.terrainTile]==nil then return false end
	broadcastToAll("Site Restored")
	if data.hexFeature=="keep" or data.hexFeature=="mage tower" then
		dropShield({destroyed.getPosition()[1], 2, destroyed.getPosition()[3]}, true)
		player.fameGain=player.fameGain+1
		broadcastToAll("and Fame Gained")
	end
	if data.hexFeature=="monastery" then playMonastery() end
	if data.hexFeature=="village" or data.hexFeature=="oasis" or data.hexFeature=="camp" then
		player.repGain=player.repGain+1
		broadcastToAll("and Reputation Gained")
	end
	undoDestroyedSitePlacement(destroyed)
	destroyed.unlock()
	destroyed.setPositionSmooth({(player.seatPos*40)-117.2+(math.random()*6.5), 3, -35+(math.random()*3.2)})
	fakeDropAvatar()
	return true
end

function destroyRestoreLocation(playerDud, mouseButton, id, type, obj)
	if mouseButton=="-1" then
		if type=="destroy" then
			--destroy
			local featureSearch={"vill", "oasi", "camp", "keep", "mage", "glad", {"ramp", "drac"}, "mine", "mona"}
			local searchOrder={"0", "300", "60", "center", "240", "120", "180"}
			--add tile rotation
			local found=false
			for feature=1, 10, 1 do
				for i=1, 7, 1 do
					local hexFeature=terrainTiles[obj.guid].hexFeature[searchOrder[i]]:sub(1,4)
					if gStates.againstTheApocSitePosition~=7 and hexFeature==featureSearch[gStates.againstTheApocSitePosition] then
						local hexPos=angleToXY(obj, searchOrder[i])
						local terrainGUID=obj.guid
						local hexAngle=searchOrder[i]
						local drawnToken=getObjectFromGUID(GUID.bag.destroyedSite).takeObject({
							position={hexPos[1], 2, hexPos[2]}, smooth=true,
							callback_function=function(spawnedToken)
								spawnedToken.unlock()
								lockDestroyedSiteWhenSettled(spawnedToken)
							end})
						found=destroySite(drawnToken, getObjectFromGUID(terrainGUID), hexAngle, false)
						if found==true then break end
					end
					if gStates.againstTheApocSitePosition==7 and (hexFeature==featureSearch[7][1] or hexFeature==featureSearch[7][2]) then
						--deploy possessed token
						getObjectFromGUID(GUID.bag.possessed).takeObject({position={angleToXY(obj, searchOrder[i])[1], 2, angleToXY(obj, searchOrder[i])[2]}})
						found=true
						break
					end
				end
				gStates.againstTheApocSitePosition=gStates.againstTheApocSitePosition+1
				if gStates.againstTheApocSitePosition==10 then gStates.againstTheApocSitePosition=1 end
				--Move the shield token
				getObjectFromGUID("e735d3").setPosition({getObjectFromGUID("f64a50").getPosition()[1]-2.37, 1.05, getObjectFromGUID("f64a50").getPosition()[3]+2.895-(0.685*gStates.againstTheApocSitePosition)})
				if found==true then break end
			end
		else
			--Only Against the Apocalypse permits Destroyed Sites to be restored.
			if gStates.gameScenario~="Against the Apocalypse Blitz" then return end
			--restore
			for _, player in pairs(turnOrder) do
				if player.mage==id:sub(7, string.len(id)) then
					--Work out clicking avatar location
					local avPos=mageKnightAvatarPositionByName(id:sub(7,string.len(id))) or {}
					for _, destroyed in pairs(getObjectFromGUID(mapArea).getObjects()) do
						if destroyed.getGMNotes()=="Destroyed" and gStates.destroyedSites~=nil and gStates.destroyedSites[destroyed.guid]~=nil then
							if math.sqrt(((destroyed.getPosition()[1]-avPos[1])^2)+((destroyed.getPosition()[3]-avPos[3])^2))<1 then
								restoreDestroyedSite(destroyed, player)
								break
							end
						end
					end
				end
			end
		end
	end
end

function playMonastery()
	gStates.monasteryCount=gStates.monasteryCount+1
	if gStates.monasteryCount>=0 then
		--Look for an empty spot in advanced action offer location
		local params={rotation ={0, 180, 0}}
		local monasteryOffer={"b7cb3b", "d925e4", "caf03e", "5c4c6d", "d51391", "7700a8"} --advanced action monastery offer zones
		local drawDecks={GUID.zone.regularUnit,GUID.zone.eliteUnit,GUID.zone.actionDeck} --Zone covering Regular units draw deck, Elite Units Draw Deck, Advanced Actions Draw Deck
		for i=1, #monasteryOffer, 1 do
			local objCard=getObjectFromGUID(monasteryOffer[i]).getObjects()
			local found=false
			for j=1, #objCard, 1 do
				if objCard[j].type=="Card" or objCard[j].type=="Deck" then found=true break end
			end
			if found==false then params.position={40.8-i*4.8, 0.98, -10.2} break end
		end
		--Play an advanced action card
		standardDeckCycleShuffleIfReached("Advanced Action")
		local MonasteryDeck=getObjectFromGUID(GUID.zone.actionDeck).getObjects()
		while MonasteryDeck==nil do Wait.frames(function() MonasteryDeck=getObjectFromGUID(GUID.zone.actionDeck).getObjects() end, 10) end
		local drawnCard=getObjectFromGUID(MonasteryDeck[1].guid).takeObject(params)
		Wait.condition(function() drawnCard.lock() end, function() return drawnCard.resting end)
		broadcastToAll("{en}Monastery is teaching a new Advanced Action{ru}Монастырь обучает новому Особому действию{zh-cn}修道院现在传授新的高级行动{ko}수도원에 새로운 상급 액션이 추가되었습니다{es}El Monasterio está enseñando una nueva Acción Avanzada{fr}Le Monastère enseigne une nouvelle Action Avancée{pt-br}Monastério está encinsando uma nova Ação Avançada{de}Das Kloster lehrt eine neue fortgeschrittene Aktion", {1,1,0.5})
	end
end

function drawMonster(color, player, id, possessedFaction)
	local drawID=tostring(id or "")
	local volkarePursuitDraw=drawID:sub(1,7)=="VPDraw|"
	tokenRefill()
	Wait.frames(function()
		local monsterDrawn=getObjectFromGUID(color).takeObject({position={(player.seatPos*40)-96+gStates.monsterOffsetX, 2.5, -39-gStates.monsterOffsetZ}, rotation={0.00, 180.00, 0.00}})
		if color==monsterPiles.possessed and possessedFaction~=nil then
			if gStates.apocalypsePossessedFactionByToken==nil then gStates.apocalypsePossessedFactionByToken={} end
			gStates.apocalypsePossessedFactionByToken[monsterDrawn.guid]=possessedFaction
		end
		if color~=monsterPiles.pyramidTrap and color~=monsterPiles.zigguratTrap then
			local pilePos=getObjectFromGUID(color).getPosition()
			local returnPos={pilePos[1],2,pilePos[3]}
			gStates.attackedMonsters[monsterDrawn.guid]={returnPos,{0.00,0.00,0.00}}
			if volkarePursuitDraw==true then
				gStates.volkarePursuitEnemies[monsterDrawn.guid]=true
				--Pursuit enemies are spent once drawn: defeated or not, end-turn cleanup sends them to
				--their normal discard bag. Do not give them a map/source return location. Defeated
				--Shades of Tezla enemies still pass through discardMonster(..., true), so their native
				--faction reward token is awarded normally; face-down undefeated enemies get no reward.
				gStates.monsterPlayLocation[monsterDrawn.guid]=nil
				if gStates.volkarePursuitCombat~=nil then gStates.volkarePursuitCombat.monsters[monsterDrawn.guid]=true end
			end
			combatCameraFocus(player)
		end
		monsterDrawn.setDecals({})
		if color~=monsterPiles.possessed then
			gStates.monsterOffsetX=gStates.monsterOffsetX+2.5
			if gStates.monsterOffsetX>12 then gStates.monsterOffsetX=0 gStates.monsterOffsetZ=gStates.monsterOffsetZ+2.5 end

			--add no units and night rules Decals
			Wait.time(function()
				if drawID:sub(1,6)~="Incant" and volkarePursuitDraw~=true then
					if player.avatarLocation=="dungeon" or player.avatarLocation=="tomb" or player.avatarLocation=="monastery" or player.avatarLocation=="ziggurat" or player.avatarLocation=="pyramid" then
						monsterDrawn.addDecal({name="NoUnits", position={-0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.4, 0.6, 1}, url="https://steamusercontent-a.akamaihd.net/ugc/12623966286982295316/7CFECB9A34CA9DBEBB8A04DC44B488E56360781B/"})
						if gStates.monsterPerks[monsterDrawn.guid]==nil then gStates.monsterPerks[monsterDrawn.guid]={noUnits=true} else gStates.monsterPerks[monsterDrawn.guid].noUnits=true end
					end
					if player.avatarLocation=="maze" or player.avatarLocation=="labyrinth" then
						monsterDrawn.addDecal({name="OneUnit", position={-0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.4, 0.6, 1}, url="https://steamusercontent-a.akamaihd.net/ugc/10559851086144974805/566B77BBAB91B7B7B5848E26BE14B17F4B96F44F/"})
						if gStates.monsterPerks[monsterDrawn.guid]==nil then gStates.monsterPerks[monsterDrawn.guid]={oneUnit=true} else gStates.monsterPerks[monsterDrawn.guid].oneUnit=true end
					end
					if player.avatarLocation=="dungeon" or player.avatarLocation=="tomb" or player.avatarLocation=="graveyard" or player.avatarLocation=="necropolis" then
						monsterDrawn.addDecal({name="NightRules", position={0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}, url=nightRulesDecal})
						if gStates.monsterPerks[monsterDrawn.guid]==nil then gStates.monsterPerks[monsterDrawn.guid]={nightRules=true} else gStates.monsterPerks[monsterDrawn.guid].nightRules=true end
					end
				end
			end, 0.5)
		end
	end, 5)
end

function zigguratPyramidInteract(_, mouseButton, id)
	if mouseButton=="-1" then
		local trapBag=monsterPiles.pyramidTrap
		local firstFight=monsterPiles.gray
		local secondFight=monsterPiles.white
		local thirdFight=monsterPiles.red
		if turnOrder[gStates.turnNumber].avatarLocation=="ziggurat" then
			trapBag=monsterPiles.zigguratTrap
			firstFight=monsterPiles.green
			secondFight=monsterPiles.purple
			thirdFight=monsterPiles.tan
		end
		--remove face down traps
		local playAreaObjects={}
		if getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos])~=nil then playAreaObjects=getObjectFromGUID(playerPlayAreas[turnOrder[gStates.turnNumber].seatPos]).getObjects() end
		for _, obj in pairs(playAreaObjects) do
			if obj.getGMNotes()=="Trap Reminder Token" and obj.is_face_down==true then obj.destruct() end
			local adjust=0
			if id=="zigguratPyramidInteractFight3" then adjust=0 end
			if obj.getGMNotes()=="Trap Reminder Token" and obj.is_face_down==false and obj.getPosition()[3]<=-39-gStates.monsterOffsetZ+adjust+0.5 then
				obj.setPosition({(turnOrder[gStates.turnNumber].seatPos*40)-101, 2.5, -39-gStates.monsterOffsetZ+adjust})
			end
		end
		--adjust interface
		if id=="zigguratPyramidInteractClimb1" then
			UI.setAttribute("zigguratPyramidInteractClimb1Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractClimb1", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight1Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractFight1", "interactable", "false")
			if UI.getAttribute("zigguratPyramidInteractClimb2Image", "color")=="Gray" then
				UI.setAttribute("zigguratPyramidInteractClimb2Image", "color", "White")
				UI.setAttribute("zigguratPyramidInteractClimb2", "interactable", "true")
			end
			if UI.getAttribute("zigguratPyramidInteractFight2Image", "color")=="Gray" then
				UI.setAttribute("zigguratPyramidInteractFight2Image", "color", "White")
				UI.setAttribute("zigguratPyramidInteractFight2", "interactable", "true")
			end
			drawMonster(trapBag, turnOrder[gStates.turnNumber], id)
			gStates.monsterOffsetZ=gStates.monsterOffsetZ+2.5
			gStates.monsterOffsetX=0
			Wait.frames(function() drawMonster(trapBag, turnOrder[gStates.turnNumber], id) end, 10)
		end
		if id=="zigguratPyramidInteractClimb2" then
			UI.setAttribute("zigguratPyramidInteractClimb2Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractClimb2", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight2Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractFight2", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight3Image", "color", "White")
			UI.setAttribute("zigguratPyramidInteractFight3", "interactable", "true")
			gStates.monsterOffsetX=0
			gStates.monsterOffsetZ=gStates.monsterOffsetZ+2.5
			drawMonster(trapBag, turnOrder[gStates.turnNumber], id)
		end
		if id=="zigguratPyramidInteractFight1" then
			UI.setAttribute("zigguratPyramidInteractClimb1Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractClimb2Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractFight2Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractFight3Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractClimb1", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight1", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight1Image", "color", "Yellow")
			drawMonster(monsterPiles.possessed, turnOrder[gStates.turnNumber], id, "Apoc")
			drawMonster(firstFight, turnOrder[gStates.turnNumber], id)
		end
		if id=="zigguratPyramidInteractFight2" then
			UI.setAttribute("zigguratPyramidInteractClimb2Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractFight3Image", "color", "Gray")
			UI.setAttribute("zigguratPyramidInteractClimb2", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight2", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight2Image", "color", "Yellow")
			drawMonster(monsterPiles.possessed, turnOrder[gStates.turnNumber], id, "Apoc")
			drawMonster(secondFight, turnOrder[gStates.turnNumber], id)
		end
		if id=="zigguratPyramidInteractFight3" then
			UI.setAttribute("zigguratPyramidInteractFight3", "interactable", "false")
			UI.setAttribute("zigguratPyramidInteractFight3Image", "color", "Yellow")
			drawMonster(monsterPiles.possessed, turnOrder[gStates.turnNumber], id, "Apoc")
			drawMonster(thirdFight, turnOrder[gStates.turnNumber], id)
		end
	end
end

--Move armies and garrisons to player boards
function attackCity(player, mouseButton, id)
	if mouseButton=="-1" then
		local coopStart=id=="startAssault"
		local wallTargetPos=assaultTargetPosition
		if coopStart==true and gStates.coopAssaultCityGUID~=nil and getObjectFromGUID(gStates.coopAssaultCityGUID)~=nil then
			local target=getObjectFromGUID(gStates.coopAssaultCityGUID).getPosition()
			wallTargetPos={target[1], target[2], target[3]}
		end
		local startAssaultType=coopStart==true and coopAssaultTargetType() or nil
		--Dragon heads are not city defenders and never gain printed wall fortification from the
		--lair hex. The three Dragon spaces keep their normal terrain but the Dragon combat itself
		--uses only the heads' printed abilities.
		if startAssaultType=="dragon" then wallTargetPos=nil end
		local wallTargetHasWall=wallTargetPos~=nil and assaultTargetHasWall(wallTargetPos)==true
		if coopStart==true then
			if coopAssaultReadyToBegin()==false then coopAssaultUIUpdate() return end
			local participants=0
			for _, assignedMonsters in pairs(gStates.assaultData) do
				if assignedMonsters.joined==true then participants=participants+1 end
				if #assignedMonsters.secondary>=1 then id="111111" end
			end
			if wallTargetHasWall==true and wallAssaultChoiceResult==nil and wallAssaultChoiceNeeded(wallTargetPos)==true then
				UI.hide("CoopAssault")
				showWallAssaultChoice("attackCity", "startAssault")
				return
			end
			if participants>=2 then
				gStates.coopAssaultPhase="combat" gStates.coopRewardQueue={} gStates.coopRewardIndex=1 gStates.coopAssaultParticipants={} gStates.coopAssaultScenarioEndPending=false
				gStates.coopAssaultType=startAssaultType
				gStates.coopAssaultInitiator=gStates.turnNumber
				local leadMage=turnOrder[gStates.turnNumber].mage
				local cityAssault=gStates.coopAssaultType=="city"
				local volkareAssault=gStates.coopAssaultType=="volkare"
				local horsemenAssault=gStates.coopAssaultType=="horsemen"
				local dragonAssault=gStates.coopAssaultType=="dragon"
				for playerIndex, playerData in pairs(turnOrder) do
					local assigned=gStates.assaultData[playerData.mage]
					if assigned~=nil and assigned.joined==true and (playerData.mage~=leadMage or cityAssault or volkareAssault or horsemenAssault or dragonAssault) then
						local avatar=coopAssaultAvatarObject(playerIndex)
						if playerData.mage~=leadMage and avatar~=nil then refreshAvatarLocationOnly(playerIndex, avatar) end
						local assaultFromPosition=avatar~=nil and avatar.getPosition() or nil
						if playerData.mage==leadMage and assaultApproachOrigin~=nil then assaultFromPosition={assaultApproachOrigin[1], assaultApproachOrigin[2], assaultApproachOrigin[3]} end
						local original={avatarLocation=playerData.avatarLocation,avatarSharedHex=playerData.avatarSharedHex,avatarSwapCity=playerData.avatarSwapCity,position=avatar~=nil and avatar.getPosition() or nil,assaultFromPosition=assaultFromPosition,lead=playerData.mage==leadMage}
						if horsemenAssault==true and playerData.mage==leadMage and gStates.againstHorsemenAssaultOrigin~=nil then
							local saved=gStates.againstHorsemenAssaultOrigin
							original.avatarLocation=saved.avatarLocation
							original.avatarSharedHex=saved.avatarSharedHex
							original.avatarSwapCity=saved.avatarSwapCity
							original.position=saved.position or original.position
							original.assaultFromPosition=saved.position or original.assaultFromPosition
						elseif dragonAssault==true and playerData.mage==leadMage and gStates.apocalypseDragonAssaultOrigin~=nil then
							local saved=gStates.apocalypseDragonAssaultOrigin
							original.avatarLocation=saved.avatarLocation
							original.avatarSharedHex=saved.avatarSharedHex
							original.avatarSwapCity=saved.avatarSwapCity
							original.position=saved.position or original.position
							original.assaultFromPosition=saved.position or original.assaultFromPosition
						end
						gStates.coopAssaultParticipants[playerIndex]=original
						if playerData.mage~=leadMage and gStates.coopAssaultLocation~=nil then playerData.avatarLocation=gStates.coopAssaultLocation end
					end
				end
				if dragonAssault==true then apocalypseDragonBeginCoopGroundCombat() end
			else
				--If every helper declines the Dragon assault, fall back to the ordinary one-player
				--ground fight instead of moving its persistent heads through generic city cleanup.
				if startAssaultType=="dragon" then
					UI.hide("CoopAssault")
					gStates.coopAssaultPhase=nil
					gStates.coopAssaultParticipants={}
					gStates.coopAssaultCityGUID=nil
					gStates.coopAssaultLocation=nil
					gStates.coopAssaultType=nil
					gStates.coopAssaultInitiator=nil
					gStates.assaultData={}
					gStates.coopAssaultUnassigned={}
					gStates.apocalypseDragonAssaultOrigin=nil
					applyColorBarButtons()
					apocalypseDragonBeginGroundCombat(gStates.turnNumber)
					return
				end
				--A lone Mage Knight fighting the ritual garrison is a normal solo assault. Keep only the
				--approach origin so a failed assault can still retreat after surviving Horsemen return.
				if startAssaultType=="horsemen" then
					gStates.againstHorsemenSoloAssault={player=gStates.turnNumber,origin=gStates.againstHorsemenAssaultOrigin}
				end
				gStates.coopAssaultPhase=nil gStates.coopAssaultParticipants={} gStates.coopAssaultCityGUID=nil gStates.coopAssaultLocation=nil gStates.coopAssaultType=nil gStates.coopAssaultInitiator=nil
				applyColorBarButtons()
			end
		end
		--move the card's monsters
		local played=false
		local OffsetX=0
		local OffsetZ=0
		local token=nil
		for playerIndex, playerData in pairs(turnOrder) do
			if gStates.assaultData[playerData.mage]~=nil and (coopStart==false or gStates.assaultData[playerData.mage].joined==true) then
				local assaultFromPosition=nil
				if wallTargetHasWall==true then
					if coopStart==true and gStates.coopAssaultParticipants[playerIndex]~=nil then assaultFromPosition=gStates.coopAssaultParticipants[playerIndex].assaultFromPosition
					elseif playerData.mage==turnOrder[gStates.turnNumber].mage then
						if assaultApproachOrigin~=nil then assaultFromPosition={assaultApproachOrigin[1], assaultApproachOrigin[2], assaultApproachOrigin[3]}
						else local avatar=coopAssaultAvatarObject(playerIndex) if avatar~=nil then assaultFromPosition=avatar.getPosition() end end
					end
				end
				local wallFortified=false
				if wallTargetHasWall==true then
					if playerData.mage==turnOrder[gStates.turnNumber].mage then wallFortified=resolveAssaultWallFortified(wallTargetPos, assaultFromPosition, true)
					else wallFortified=resolveAssaultWallFortified(wallTargetPos, assaultFromPosition, false) end
				end
				if playerData.mage~=turnOrder[gStates.turnNumber].mage then
					OffsetX=0 OffsetZ=0
					if getObjectFromGUID(playerData.turnOrderTokenGUID).is_face_down==false and id~="Volkar" and
						(coopStart==false or gStates.assaultData[playerData.mage].joined==true) then
						token=getObjectFromGUID(playerData.turnOrderTokenGUID)
						token.flip()
					end
				else
					OffsetX=gStates.monsterOffsetX OffsetZ=gStates.monsterOffsetZ
				end
				local inFight=false
				local cameraFollowed=false
				--Dragon co-op reserves slot 1 for Control; distributed coloured heads start at slot 2.
				local dragonCombatSlot=(coopStart==true and gStates.coopAssaultType=="dragon") and 2 or 1
				for _, army in pairs({"primary", "secondary"}) do
					for _, monsterGUID in pairs(gStates.assaultData[playerData.mage][army]) do
						if getObjectFromGUID(monsterGUID)~=nil then
							local monsterObj=getObjectFromGUID(monsterGUID)
							gStates.attackedMonsters[monsterGUID]={monsterObj.getPosition(), monsterObj.getRotation()}
							if wallTargetHasWall==true then setAssaultWallFortified(monsterObj, wallFortified) end
							monsterObj.unlock()
							if cameraFollowed==false then combatCameraFocus(playerIndex) cameraFollowed=true end
							local destination={(playerData.seatPos*40)-96+OffsetX, 2.5, -39-OffsetZ}
							if coopStart==true and gStates.coopAssaultType=="dragon" and apocalypseDragonGroundTokenPosition~=nil then
								local dragonPosition=apocalypseDragonGroundTokenPosition(playerIndex,dragonCombatSlot)
								if dragonPosition~=nil then destination={dragonPosition[1],2.5,dragonPosition[3]} end
								dragonCombatSlot=dragonCombatSlot+1
							end
							monsterObj.setPositionSmooth(destination)
							if wallTargetHasWall==true then settleAssaultWallFortified(monsterGUID, wallFortified) end
							getObjectFromGUID(monsterGUID).setRotation({0.00, 180.00, 0.00})
							if coopStart~=true or gStates.coopAssaultType~="dragon" then
								OffsetX=OffsetX+2.5
								if OffsetX>12 then OffsetX=0 OffsetZ=OffsetZ+2.5 end
							end
							played=true
							inFight=true
						end
					end
				end
				local sharedVolkare=coopStart==true and gStates.coopAssaultType=="volkare" and gStates.assaultData[playerData.mage].joined==true
				if (playerData.avatarLocation=="Volkare's Camp" or id=="111111" or id=="Volkar" or sharedVolkare) and (inFight==true or sharedVolkare) then
					local monster=getObjectFromGUID(GUID.bag.volkareReminder).takeObject({position={(playerData.seatPos*40)-98.5, 2.5, -39}})
					gStates.attackedMonsters[monster.guid]={{getObjectFromGUID(GUID.bag.volkareReminder).getPosition()[1], 2, getObjectFromGUID(GUID.bag.volkareReminder).getPosition()[3]}, {0.00, 0.00, 0.00}}
				end
				if turnOrder[gStates.turnNumber].mage==playerData.mage then gStates.monsterOffsetX=OffsetX gStates.monsterOffsetZ=OffsetZ end
			end
		end
		if played==true then
			if coopStart==true and gStates.coopAssaultType=="dragon" then broadcastToAll("The Apocalypse Dragon heads have been distributed to the participating Mage Knights.",{1,0.75,0.2})
			else broadcastToAll("{en}Garrison moved to Player Board.{ru}Гарнизон был помещен на стол игрока{zh-cn}守军移动到玩家面板{ko}수비자와 전투합니다{es}Garrison se movió al tablero de jugador.{fr}La garnison a été transférée au plateau des joueurs.{pt-br}Guarnição mvida para o tabuleiro do jogador{de}Garrison wird auf die Spielertafel verschoben.", positionToColor(gStates.turnNumber)) end
		end
		--Give later faction-leader participants an unlocked, buttonless copy now so they can plan their combat.
		if coopStart==true and gStates.coopAssaultPhase=="combat" and gStates.coopAssaultType=="leader" then createCoopLeaderPreviewClones() end
		gStates.assaultData={}
		gStates.coopAssaultUnassigned={}
		if coopStart==true then gStates.againstHorsemenAssaultOrigin=nil gStates.apocalypseDragonAssaultOrigin=nil end
		if UI.getAttribute("CoopAssaultMainTableText1", "text")=="{en}Combined Defense Possible{ru}Доступна Совместная защита города{zh-tw}可以進行合作防守{zh-cn}可以进行合作防守{ko}협력 수비 가능{es}Defensa Combinada Posible{fr}Défense Combinée Possible{pt-br}Defesa Combinada Possível{de}Gemeinsame Verteidigung möglich" then
			if token~=nil then
				Wait.condition(function()
					nextTurnMerged("incrementTurn")
				end, function() return token.resting end)
			end
		end
		UI.setAttribute("CoopAssaultMainTableText1", "text", "{en}Combined Assault Possible{ru}Доступен Совместный штурм города{zh-tw}可以進行合作突襲{zh-cn}可以进行合作突袭{ko}협력 강습 가능{es}Asalto Combinado Posible{fr}Assaut Combiné Possible{pt-br}Ataque Combinado Possível{de}Gemeinsamer Angriff möglich")
		UI.setAttribute("CoopAssaultMainTableText2", "text", "{en}Nearby Mage Knights can choose to join this assault by skipping their next turn. This tool randomly gives the amount of defenders chosen to each player. (Remember to pay movement costs){ru}Герои, находящиеся на соседней с городом клетке, могут присоединиться к штурму. Этот инструмент случайным образом выдаст каждому игроку защитников согласно выбранному количеству, а также перевернет их Жетоны Порядка хода лицом вниз.{zh-tw}附近的魔法騎士可以選擇加入突襲。\n此工具會依據數量隨機分配敵人給每位參與者，\n同時也會將這些玩家的輪次順位標記翻面。\n{zh-cn}附近的魔法骑士可以选择加入突袭。 \n此工具会依据数量随机分配敌人给每位参与者，\n同时也会将这些玩家的轮次顺位标记翻面。 \n{ko}근처의 메이지 나이트들은 이 강습에 참여할 수 있습니다. 이 툴은 참여한 각 플레이어에게 무작위로 선택된 수비자 토큰을 배분합니다. 그리고 라운드 순서 토큰을 뒤집습니다.{es}Los caballeros magos cercanos pueden elegir unirse al asalto. Esta herramienta da al azar la cantidad de defensores elegidos para cada jugador, mientras que también coloca boca abajo su Ficha de Orden de Turno.{fr}Les chevaliers mages à proximité peuvent choisir de se joindre à l'assaut. Cet outil donne au hasard le nombre de défenseurs choisis à chaque joueur, tout en retournant son jeton d'ordre du tour face cachée.{pt-br}Os Mage Knights próximos podem escolher se juntar ao ataque. Esta ferramenta fornece aleatoriamente a quantidade de defensores escolhidos para cada jogador, ao mesmo tempo que vira a ficha de ordem do turno para baixo.{de}Mage Knights in der Nähe können sich dem Angriff anschließen. Mit diesem Werkzeug erhält jeder Spieler zufällig die gewählte Anzahl an Verteidigern und dreht gleichzeitig sein Zugreihenfolgeplättchen um.")
		UI.setAttribute("CoopAssaultMainTableText3", "active", "false")
		UI.setAttribute("startAssaultText", "text", "{en}Begin Assault{ru}Начать штурм{zh-tw}開始突襲{zh-cn}开始突袭{ko}강습 시작{es}Empezar Asalto{fr}Commencer l'Assaut{pt-br}Comece o Assalto{de}Angriff Starten")
		UI.hide("CoopAssault")
		if coopStart==true then clearWallAssaultChoice() assaultApproachOrigin=nil assaultTargetPosition=nil end
	end
end

--Faction leader tokens stay with the assault flow and are passed between participants, but are not defenders to divide.
function coopAssaultDividableCount(monsters)
	local count=0
	for _, monsterGUID in pairs(monsters or {}) do
		if monsterGUID~=elementalist.token and monsterGUID~=darkCrusader.token then count=count+1 end
	end
	return count
end

function coopAssaultHasLeader(monsters)
	for _, monsterGUID in pairs(monsters or {}) do
		if monsterGUID==elementalist.token or monsterGUID==darkCrusader.token then return true end
	end
	return false
end

function coopAssaultLeadMage()
	local leadMage=turnOrder[gStates.turnNumber].mage
	if leadMage==gStates.positionMageKnight[5] then
		for mage, assignedMonsters in pairs(gStates.assaultData) do if assignedMonsters.UIPos[1]==1 then leadMage=mage break end end
	end
	return leadMage
end

function coopAssaultAssignmentSource(army)
	if coopAssaultTargetType()=="volkare" then
		if gStates.coopAssaultUnassigned==nil then gStates.coopAssaultUnassigned={primary={}, secondary={}} end
		if gStates.coopAssaultUnassigned[army]==nil then gStates.coopAssaultUnassigned[army]={} end
		return gStates.coopAssaultUnassigned[army]
	end
	local leadMage=coopAssaultLeadMage()
	return gStates.assaultData[leadMage]~=nil and gStates.assaultData[leadMage][army] or nil
end

function coopAssaultCityMinimumEnemyRule()
	local assaultType=coopAssaultTargetType()
	return (assaultType=="city" or assaultType=="horsemen" or assaultType=="dragon") and UI.getAttribute("CoopAssaultMainTableText1", "text")~="{en}Combined Defense Possible{ru}Доступна Совместная защита города{zh-tw}可以進行合作防守{zh-cn}可以进行合作防守{ko}협력 수비 가능{es}Defensa Combinada Posible{fr}Défense Combinée Possible{pt-br}Defesa Combinada Possível{de}Gemeinsame Verteidigung möglich"
end

function coopAssaultReadyToBegin()
	local assaultType=coopAssaultTargetType()
	local joined=0
	if assaultType=="volkare" then
		if coopAssaultDividableCount(gStates.coopAssaultUnassigned~=nil and gStates.coopAssaultUnassigned.primary or {})>0 or coopAssaultDividableCount(gStates.coopAssaultUnassigned~=nil and gStates.coopAssaultUnassigned.secondary or {})>0 then return false end
	end
	for _, assignedMonsters in pairs(gStates.assaultData) do
		if assignedMonsters.joined==true then
			joined=joined+1
			if (assaultType=="city" or assaultType=="horsemen" or assaultType=="dragon") and coopAssaultDividableCount(assignedMonsters.primary)+coopAssaultDividableCount(assignedMonsters.secondary)==0 and coopAssaultHasLeader(assignedMonsters.primary)==false and coopAssaultHasLeader(assignedMonsters.secondary)==false then return false end
		end
	end
	if assaultType=="city" or assaultType=="horsemen" or assaultType=="dragon" then return joined>=1 end
	return joined>=2
end

function coopAssaultUIUpdate()
	local entry=0
	local rowCount=0
	local size="half"
	local assaultType=coopAssaultTargetType()
