	else
		UI.setAttribute("CoopAssaultMainTableText2", "text", defense and "{en}The City is under attack. Players must skip their next turn and Defend. This tool randomly gives the amount of attackers chosen to each player. All must face Volkare" or "{en}Nearby Mage Knights can choose to join this assault by skipping their next turn. This tool randomly gives the amount of defenders chosen to each player. (Remember to pay movement costs)")
		UI.setAttribute("CoopAssaultMainTableText3", "active", "false")
	end
	local ready=coopAssaultReadyToBegin()
	UI.setAttribute("startAssault", "interactable", ready and "true" or "false")
	UI.setAttribute("startAssaultImage", "image", ready and "Sliced Button/Button New Active" or "Sliced Button/Button New Deactive")
	UI.setAttribute("CoopAssault", "width", "525")
	UI.setAttribute("CoopAssault", "height", tostring(((rowCount+1)*30)+90))
	UI.setAttribute("CoopAssaultMainTableHeading", "columnSpan", "5")
	UI.setAttribute("CoopAssaultMainTableHeading", "preferredHeight", "56")
	UI.setAttribute("CoopAssaultMainTable", "columnWidths", "135 85 100 85 120")
	if size=="half" then
		UI.setAttribute("CoopAssault", "width", "340")
		UI.setAttribute("CoopAssault", "height", tostring(((rowCount+1)*30)+95))
		UI.setAttribute("CoopAssaultMainTableHeading", "columnSpan", "3")
		UI.setAttribute("CoopAssaultMainTableHeading", "preferredHeight", "61")
		UI.setAttribute("CoopAssaultMainTable", "columnWidths", "135 85 120 85 120")
	end
	UI.show("CoopAssault")
end

function coopAssaultJoin(player, mouseButton, id)
	if mouseButton~="-1" then return end
	local uiPos=tonumber(id:sub(5,5))
	local leadMage=coopAssaultLeadMage()
	for mage, assignedMonsters in pairs(gStates.assaultData) do
		if assignedMonsters.UIPos[1]==uiPos then
			if mage==leadMage then return end
			local playerIndex=nil
			for index, details in pairs(turnOrder) do if details.mage==mage then playerIndex=index break end end
			if playerIndex==nil or legalPlayerCheck(player.color, turnOrder[playerIndex].seatPos)~=true then return end
			if assignedMonsters.joined==true then
				local sourcePrimary=coopAssaultAssignmentSource("primary")
				local sourceSecondary=coopAssaultAssignmentSource("secondary")
				for _, army in pairs({{"primary", sourcePrimary}, {"secondary", sourceSecondary}}) do
					for i=#assignedMonsters[army[1]], 1, -1 do
						local guid=assignedMonsters[army[1]][i]
						if guid~=elementalist.token and guid~=darkCrusader.token and army[2]~=nil then army[2][#army[2]+1]=guid table.remove(assignedMonsters[army[1]], i) end
					end
				end
				assignedMonsters.joined=false
			else
				if coopAssaultCityMinimumEnemyRule()==true then
					local sourcePrimary=coopAssaultAssignmentSource("primary") or {}
					local sourceSecondary=coopAssaultAssignmentSource("secondary") or {}
					local sourceTotal=coopAssaultDividableCount(sourcePrimary)+coopAssaultDividableCount(sourceSecondary)
					if sourceTotal<=1 then
						broadcastToAll("Each Mage Knight joining a combined assault must have at least one defender assigned.", positionToColor(playerIndex))
						break
					end
					local choices={}
					for i, guid in pairs(sourcePrimary) do if guid~=elementalist.token and guid~=darkCrusader.token then choices[#choices+1]={army="primary", index=i} end end
					for i, guid in pairs(sourceSecondary) do if guid~=elementalist.token and guid~=darkCrusader.token then choices[#choices+1]={army="secondary", index=i} end end
					if #choices==0 then break end
					local pick=choices[math.random(1,#choices)]
					local source=pick.army=="primary" and sourcePrimary or sourceSecondary
					assignedMonsters[pick.army][#assignedMonsters[pick.army]+1]=source[pick.index]
					table.remove(source,pick.index)
				end
				assignedMonsters.joined=true
			end
			break
		end
	end
	coopAssaultUIUpdate()
end

function assaultAdjust(player, mouseButton, id)
	if mouseButton~="-1" then return end
	local uiPos=tonumber(id:sub(5,5))
	local army=id:sub(19,22)=="Seco" and "secondary" or "primary"
	local action=id:sub(23,24)
	local source=coopAssaultAssignmentSource(army)
	for mage, assignedMonsters in pairs(gStates.assaultData) do
		if assignedMonsters.UIPos[1]==uiPos then
			local playerIndex=nil
			for index, details in pairs(turnOrder) do if details.mage==mage then playerIndex=index break end end
			if playerIndex==nil or legalPlayerCheck(player.color, turnOrder[playerIndex].seatPos)~=true then return end
			local cityMinimum=coopAssaultCityMinimumEnemyRule()
			local sourcePrimary=coopAssaultAssignmentSource("primary") or {}
			local sourceSecondary=coopAssaultAssignmentSource("secondary") or {}
			local sourceTotal=coopAssaultDividableCount(sourcePrimary)+coopAssaultDividableCount(sourceSecondary)
			local assignedTotal=coopAssaultDividableCount(assignedMonsters.primary)+coopAssaultDividableCount(assignedMonsters.secondary)
			if action=="Up" and source~=nil and coopAssaultDividableCount(source)>0 and (cityMinimum==false or sourceTotal>1) then
				local choices={}
				for i, guid in pairs(source) do if guid~=elementalist.token and guid~=darkCrusader.token then choices[#choices+1]=i end end
				if #choices>0 then local pick=choices[math.random(1,#choices)] assignedMonsters[army][#assignedMonsters[army]+1]=source[pick] table.remove(source,pick) assignedMonsters.joined=true end
			elseif action=="Do" and source~=nil and coopAssaultDividableCount(assignedMonsters[army])>0 and (cityMinimum==false or assignedTotal>1) then
				local choices={}
				for i, guid in pairs(assignedMonsters[army]) do if guid~=elementalist.token and guid~=darkCrusader.token then choices[#choices+1]=i end end
				if #choices>0 then local pick=choices[math.random(1,#choices)] source[#source+1]=assignedMonsters[army][pick] table.remove(assignedMonsters[army],pick) end
			end
			break
		end
	end
	coopAssaultUIUpdate()
end

--Faction identity can come from printed monster data or temporarily from monsterPerks when a normal
--enemy token substitutes for an exhausted faction pile. Faction-dependent behaviour uses this globally.
function monsterEffectiveFaction(monsterGUID)
	local perks=gStates.monsterPerks~=nil and gStates.monsterPerks[monsterGUID] or nil
	if perks~=nil and perks.faction~=nil then return perks.faction end
	local data=monsterPugs~=nil and monsterPugs[monsterGUID] or nil
	return data~=nil and data.faction or nil
end

function markMonsterFactionSubstitute(token, faction)
	if token==nil or faction==nil then return token end
	local printed=monsterPugs~=nil and monsterPugs[token.guid] or nil
	if printed~=nil and printed.faction==faction then return token end
	if gStates.monsterPerks[token.guid]==nil then gStates.monsterPerks[token.guid]={} end
	gStates.monsterPerks[token.guid].faction=faction
	return token
end

function factionMonsterPileGUID(standardGUID, faction)
	local suffix=faction=="Dark" and "Dark" or faction=="Elem" and "Elem" or nil
	if suffix~=nil then
		for _, color in ipairs({"green","tan","red"}) do
			if standardGUID==monsterPiles[color] then
				local factionGUID=monsterPiles[color..suffix]
				local factionPile=factionGUID~=nil and getObjectFromGUID(factionGUID) or nil
				if factionPile~=nil and factionPile.getQuantity()>0 then return factionGUID, false end
				return standardGUID, true
			end
		end
	end
	return standardGUID, false
end

function takeFactionMonster(standardGUID, faction, params)
	if monsterPiles[standardGUID]~=nil then standardGUID=monsterPiles[standardGUID] end
	local pileGUID, substitute=factionMonsterPileGUID(standardGUID, faction)
	local pile=pileGUID~=nil and getObjectFromGUID(pileGUID) or nil
	if pile==nil or pile.getQuantity()==0 then return nil, pileGUID end
	local token=pile.takeObject(params)
	if substitute==true then markMonsterFactionSubstitute(token, faction) end
	return token, pileGUID
end

function apocalypseDragonPossessSummonedEnemy(enemyGUID,target)
	local enemy=getObjectFromGUID(enemyGUID)
	if target==nil then
		if enemy==nil then return false end
		local p=enemy.getPosition()
		target={p[1],p[2],p[3]}
	end
	local bag=getObjectFromGUID(GUID.bag.possessed)
	if bag==nil or bag.getQuantity()==0 then
		tokenRefill()
		bag=getObjectFromGUID(GUID.bag.possessed)
	end
	if bag==nil or bag.getQuantity()==0 then return false end
	--Match the working Quest possessed-enemy path: draw both tokens to the same X/Z, with the
	--Possessed token above the enemy. Falling through the player scripting zone performs the link.
	local possessed=bag.takeObject({position={target[1],target[2]+1.10,target[3]},rotation={0,180,0},smooth=true})
	if possessed==nil then return false end
	gStates.apocalypsePossessedFactionByToken=gStates.apocalypsePossessedFactionByToken or {}
	gStates.apocalypsePossessedFactionByToken[possessed.guid]="Apoc"
	--Control-head summons are temporary enemies: neither the summoned monster nor its Possessed
	--token may award Fame or a Faction Reward. Mark the attachment with the same summoned state
	--used by ordinary monster cleanup so every reward path treats both pieces consistently.
	gStates.summonStates=gStates.summonStates or {}
	gStates.summonStates[possessed.guid]="summoned"
	return true
end

--summun monsters to the left of a summoner.
function summonMonster(player, mouseButton, id)
	if mouseButton=="-1" then
		--draw tokens to the left of summoners token
		broadcastToAll("{en}Monster Summoned some support{ru}Враг призвал подмогу{zh-cn}怪物叫了些同谋{ko}몬스터가 소환되었습니다{es}Monster convocó algo de apoyo{fr}Monstre a invoqué du soutien{pt-br}Monstro Invocou algum suporte.{de}Monster beschwört etwas Unterstützung", positionToColor(gStates.turnNumber))
		local location=getObjectFromGUID(id).getPosition()
		local search=monsterPugs[id].monsters
		local summonerFaction=monsterEffectiveFaction(id)
		local tokenWait=0
		local cameraFocused=false
		for order, monsterColor in pairs(search) do
			Wait.frames(function() tokenRefill() end, tokenWait+1)
			Wait.frames(function()
				local summonTarget={location[1]-(2.5*order),2.5,location[3]}
				local summonedMonster, summonPileGUID=takeFactionMonster(monsterColor, summonerFaction, {position=summonTarget, rotation={0.00, 180.00, 0.00}})
				if summonedMonster~=nil then
					local summonPile=getObjectFromGUID(summonPileGUID)
					local returnPos={summonPile.getPosition()[1], 2, summonPile.getPosition()[3]}
					if cameraFocused==false then combatCameraFocus(turnOrder[gStates.turnNumber]) cameraFocused=true end
					gStates.attackedMonsters[summonedMonster.guid]={returnPos, {0.00, 0.00, 0.00}, "summoned", id}
					if id==darkCrusader.token or (summonerFaction=="Dark" and turnOrder[gStates.turnNumber].avatarLocation=="graveyard") then summonedMonster.addDecal({name="NightRules", position={0.85, 0.15, -0.85}, rotation={90, 180, 0}, scale={0.6, 0.6, 1}, url=nightRulesDecal}) end
					gStates.summonStates[summonedMonster.guid]="summoned"
					--Control-head summons are Apocalypse possessed enemies. Use the ordinary global
					--Possessed attachment path so their modified attacks/psychic data behave normally.
					local dragonControl=apocalypseDragonGroundControlToken~=nil and select(1,apocalypseDragonGroundControlToken(id))==true
					if dragonControl==true and gStates.apocalypseDragonGroundCombat~=nil then
						apocalypseDragonPossessSummonedEnemy(summonedMonster.guid,summonTarget)
					end
					if gStates.monsterPerks[summonedMonster.guid]==nil then gStates.monsterPerks[summonedMonster.guid]={nightRules=true} else gStates.monsterPerks[summonedMonster.guid].nightRules=true end
					cityBonusDecals(getObjectFromGUID(id), summonedMonster)
					--add possessed perks
					if getObjectFromGUID(id).getAttachments()[1]~=nil and tokenWait==5 then
						local possessedToken=getObjectFromGUID(id).getAttachments()[1].guid
						if monsterPugs[possessedToken].attack~=nil then
							if gStates.monsterPerks[summonedMonster.guid]==nil then
								gStates.monsterPerks[summonedMonster.guid]={[attack]=monsterPugs[possessedToken].attack}
							else
								gStates.monsterPerks[summonedMonster.guid].attack=monsterPugs[possessedToken].attack
							end
						end
						if monsterPugs[possessedToken].boost~=nil then if gStates.monsterPerks[summonedMonster.guid]==nil then gStates.monsterPerks[summonedMonster.guid]={[boost]=monsterPugs[possessedToken].boost} else gStates.monsterPerks[summonedMonster.guid].boost=monsterPugs[possessedToken].boost end end
					end
				else
					broadcastToAll("{en}Sorry, there are no tokens left to deploy{zh-cn}抱歉，没有token可供部署{ko}여분의 토큰이 없습니다{es}Lo sentimos, no quedan tokens para implementar{fr}Désolé, il n'y a plus de jetons à déployer{pt-br}Desculpe, Não tem Fichas sobrando para distribuir", warningColor)
				end
			end, tokenWait+5)
			tokenWait=tokenWait+5
		end
		--turn off button
		if id==darkCrusader.token then
			getObjectFromGUID(id).UI.setXmlTable({
				{tag="Button", attributes={id=id.."OverkillUp", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked",	onClick="global/adjustOverkill", height=50/0.9, width=50/0.9,
					color="rgba(0,0,0,0.0)", position="-62 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
					children={{tag="Image", attributes={id=id.."OverkillUpImage", image="Overkill Up"}}}},
				{tag="Image", attributes={image="Overkill Text", height=50/0.9, width=55/0.9, position="0 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
					children={{tag="Text", attributes={id=id.."Overkill",	color="rgb(0,0,0)", fontSize="45", fontStyle="Bold", alignment="MiddleCenter", text=gStates.leaderOverkill}}}},
				{tag="Button", attributes={id=id.."OverkillDown", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", onClick="global/adjustOverkill", height=50/0.9, width=50/0.9,
					color="rgba(0,0,0,0.0)", position="62 "..tostring(-120/0.9).." "..tostring(-15/0.9), rotation="0 0 180"},
					children={{tag="Image", attributes={id=id.."OverkillDownImage", image="Overkill Down"}}}}})
		else
			gStates.summonStates[id]="SummonDone"
			setMonsterObjectButtons(getObjectFromGUID(id))
		end
	end
end

--Leader overkill adjust
function adjustOverkill(player, mouseButton, id)
	if mouseButton=="-1" then
		local level=gStates.elementalistLevel-gStates.leaderReduction
		if id:sub(1,6)==darkCrusader.token then level=gStates.darkCrusaderLevel-gStates.leaderReduction end
		if id:sub(7,16)=="OverkillUp" and gStates.leaderOverkill<level then
			gStates.leaderOverkill=gStates.leaderOverkill+1
		end
		if id:sub(7,18)=="OverkillDown" and gStates.leaderOverkill>1 then
			gStates.leaderOverkill=gStates.leaderOverkill-1
		end
		getObjectFromGUID(id:sub(1,6)).UI.setAttribute(id:sub(1,14), "Text", gStates.leaderOverkill)
		mainUIUpdate("Leader Overkilled")
	end
end

local pursuitStunnedImageURL="https://steamusercontent-a.akamaihd.net/ugc/9820771160644960489/29318B61F2A30E0E941F355C3664303B0C95BC60/"
function setPursuitStunnedImage(monsterObj, stunned)
	if monsterObj==nil then return end
	local xml=monsterObj.UI.getXmlTable() or {}
	for a=#xml, 1, -1 do if xml[a].attributes~=nil and xml[a].attributes.id=="Pursuit Stunned" then table.remove(xml, a) end end
	if stunned==true then xml[#xml+1]={tag="Image", attributes={id="Pursuit Stunned", height=110, width=110, position="0 0 -15", rotation="0 0 180", image=pursuitStunnedImageURL}} end
	if #xml==0 then xml={{}} end
	monsterObj.UI.setXmlTable(xml)
end

--Moves all rampaging tokens when Pursuit Variant Used
function pursuingRampagers(player, mouseButton, id)
	if mouseButton=="-1" then
		gStates.pursuitTwoOption=false
		--loop through all recorded pursuing monsters
		if gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]~=nil and gStates.tacticShown==false then
			--delete the help arrows
			for guid, _ in pairs(gStates.arrowDelete) do
				if getObjectFromGUID(guid)~=nil then getObjectFromGUID(guid).destruct() end
			end
			gStates.arrowDelete={}
			local height=0.2
			for monsterGUID, monsterDetails in pairs(gStates.pursuingMonsters[turnOrder[gStates.turnNumber].mage]) do
				if monsterDetails.state=="Pursuing" then
					--find initial vector to move closer to the player
					local playerPos={}
					local playerRealPos=playerPos
					for b, details in pairs(mageKnights) do
						if details.mage==turnOrder[gStates.turnNumber].mage then
							if getObjectFromGUID(details.model)~=nil then playerPos=getObjectFromGUID(details.model).getPosition() end
							if getObjectFromGUID(details.token)~=nil then playerPos=getObjectFromGUID(details.token).getPosition() end
							if getObjectFromGUID(details.standee)~=nil then playerPos=getObjectFromGUID(details.standee).getPosition() end
						end
					end
					playerRealPos={playerPos[1], playerPos[2], playerPos[3]}
					if turnOrder[gStates.turnNumber].avatarLocation:sub(1, 4)=="city" or turnOrder[gStates.turnNumber].avatarLocation=="Volkare's Camp" then
						--figure out which city avatar is in
						for zone, citySearch in pairs(cityScriptZones) do
							for obj, detail in pairs(getObjectFromGUID(zone).getObjects()) do
								if detail.getName()==turnOrder[gStates.turnNumber].mage then
									playerPos=getObjectFromGUID(citySearch.cityGUID).getPosition()
									break
								end
							end
						end
					end
					local realBearing=(math.floor((math.deg(math.atan2(monsterDetails.location[3]-playerPos[3], monsterDetails.location[1]-playerPos[1]))/2)+0.5)*2)+2
					local playerBearing=math.floor((realBearing/60)+0.5)*60
					local inline=false
					if realBearing>=360 then playerBearing=playerBearing-360 realBearing=realBearing-360 end
					if realBearing<0 then playerBearing=playerBearing+360 realBearing=realBearing+360 end
					if realBearing<playerBearing+10 and realBearing>playerBearing-10 then inline=true end
					local clockwise=1
					if realBearing<playerBearing then clockwise=-1 end
					local canAttack=false
					local protection="none"
					local rampageNewPos={}
					function hexCheck()
						local objectsInPlay=getObjectFromGUID(mapArea).getObjects()
						local terrainFound=false
						local terTile, hexBearing=terrainHexAtPosition(rampageNewPos, objectsInPlay)
						if terTile~=nil and hexBearing~=nil then
							--make sure the hex isn't a fortified site
							if terrainTiles[terTile.guid].hexFeature[hexBearing]~="keep" and
								terrainTiles[terTile.guid].hexFeature[hexBearing]~="mage tower" and
								terrainTiles[terTile.guid].hexFeature[hexBearing]:sub(1, 4)~="city" then
								terrainFound=true
								if terrainTiles[terTile.guid].hexFeature[hexBearing]=="village" or
									terrainTiles[terTile.guid].hexFeature[hexBearing]=="camp" or
									terrainTiles[terTile.guid].hexFeature[hexBearing]=="monastery" and gStates.monasteryBurned[terTile.guid]~=true then
								protection="Interaction"
							end
							if terrainTiles[terTile.guid].wallList~=nil and terrainTiles[terTile.guid].wallList[hexBearing]~=nil then
								local hexOriginBearing=terrainHexBearing(terTile, monsterDetails.location)
								if hexOriginBearing~=nil then
									if terrainTiles[terTile.guid].wallList[hexBearing][hexOriginBearing]~=nil then
										protection="Wall"
										end
									end
								end
							else
								protection="Fortified"
								if terrainTiles[terTile.guid].hexFeature[tostring(hexBearing)]:sub(1, 4)=="city" then
									local cityZone={[cityModel.blue]=GUID.zone.blueCity, [cityModel.red]=GUID.zone.redCity, [cityModel.green]=GUID.zone.greenCity, [cityModel.white]=GUID.zone.whiteCity}
									for _, obj in pairs(objectsInPlay) do
										if cityZone[obj.guid]~=nil then
											local found=false
											for _, obj2 in pairs(getObjectFromGUID(cityZone[obj.guid]).getObjects()) do
												if obj2.getName()==turnOrder[gStates.turnNumber].mage then
													if math.sqrt(((rampageNewPos[1]-obj.getPosition()[1])^2)+((rampageNewPos[3]-obj.getPosition()[3])^2))<1 then
														protection="City"
														if turnOrder[gStates.turnNumber].defeatedCities[obj.guid]==nil and gStates.cityLevels[#gStates.cityLevels]~=0 then canAttack=true end
														found=true
														break
													end
												end
											end
											if found==true then break end
										end
									end
								end
							end
						end
						local avatarToRampageDist=math.sqrt(((rampageNewPos[1]-playerPos[1])^2)+((rampageNewPos[3]-playerPos[3])^2))
						if terrainFound==true then
							--make sure there isnt an other player
							local magefound=false
							local test={Arythea=1, Braevalar=1, Goldyx=1, Krang=1, Norowas=1, Tovak=1, Wolfhawk=1, Coral=1, Ymirgh=1, Novak=1, Duscenia=1, Jormund=1, Volkare=1}
							for _, obj in pairs(objectsInPlay) do
								if obj.getName()~=turnOrder[gStates.turnNumber].mage and test[obj.getName()]==1 then
									if math.sqrt(((rampageNewPos[1]-obj.getPosition()[1])^2)+((rampageNewPos[3]-obj.getPosition()[3])^2))<1 then
										magefound=true
										break
									end
								end
							end
							if magefound==false then
								--see if it moves on to player boards
								if avatarToRampageDist<0.5 and protection=="none" then canAttack=true end
								return "Good"
							end
						end
						if terrainFound==false and protection~="none" and avatarToRampageDist<0.5 then
							--need to check if the site has a shield or not to determin if he attacks or stays
							local shieldfound=false
							for _, obj in pairs(objectsInPlay) do
								if obj.getName()=="Shield" and volkarePursuitShieldRegistered(obj)~=true and obj.getDescription()==turnOrder[gStates.turnNumber].mage then
									if math.sqrt(((rampageNewPos[1]-obj.getPosition()[1])^2)+((rampageNewPos[3]-obj.getPosition()[3])^2))<1 then
										shieldfound=true
										break
									end
								end
							end
							if shieldfound==false and protection~="City" then canAttack=true end
							return "Good"
						end
						return "Bad"
					end

					--check he won't move out of bounds and alter his course
					local hexIncrement={60, -120, 180, -240, 300}
					local hexFound=false
					local count=0
					while hexFound==false do
						rampageNewPos={monsterDetails.location[1]-(2.39*math.cos(math.rad(playerBearing))), monsterDetails.location[2], monsterDetails.location[3]-(2.39*math.sin(math.rad(playerBearing)))}
						if hexCheck()=="Bad" and count<5 then
							count=count+1
							playerBearing=playerBearing+(hexIncrement[count]*clockwise)
						else
							hexFound=true
						end
					end

					--check for scondary option
					local otherBearing=math.floor((math.deg(math.atan2(monsterDetails.location[3]-playerPos[3], monsterDetails.location[1]-playerPos[1]))/2)+0.5)*2
					if otherBearing>=360 then otherBearing=otherBearing-360 end
					if otherBearing<0 then otherBearing=otherBearing+360 end
					local twoOptions=1
					if (inline==true and count>0 and count<4) or (inline==false and (count==0 or count==2)) then
						if inline==false and count==0 then otherBearing=playerBearing+(hexIncrement[count+1]*clockwise) end
						if inline==false and count==2 and (clockwise==1 or (otherBearing~=30 and otherBearing~=90 and otherBearing~=150 and otherBearing~=210 and otherBearing~=270 and otherBearing~=330)) then
							otherBearing=playerBearing+(hexIncrement[count-1]*clockwise) end
						if inline==false and count==2 and clockwise==-1 and (otherBearing==30 or otherBearing==90 or otherBearing==150 or otherBearing==210 or otherBearing==270 or otherBearing==330) then
							otherBearing=playerBearing+(hexIncrement[count+1]*clockwise) end
						if inline==true and (count==1 or count==3) then otherBearing=playerBearing+(hexIncrement[count+1]*clockwise) end
						if otherBearing>=360 then otherBearing=otherBearing-360 end
						if otherBearing<0 then otherBearing=otherBearing+360 end
						rampageNewPos={monsterDetails.location[1]-(2.39*math.cos(math.rad(otherBearing))), monsterDetails.location[2], monsterDetails.location[3]-(2.39*math.sin(math.rad(otherBearing)))}
						if hexCheck()=="Good" then
							twoOptions=2
							gStates.pursuitTwoOption=true
						end
					end

					--move rampage monster one hex in a closer direction
					local noMove=false
					local rampageNewPos={monsterDetails.location[1]-(2.39*math.cos(math.rad(playerBearing))), monsterDetails.location[2]+height, monsterDetails.location[3]-(2.39*math.sin(math.rad(playerBearing)))}
					if math.sqrt(((turnOrder[gStates.turnNumber].turnStartLoc.x-playerRealPos[1])^2)+((turnOrder[gStates.turnNumber].turnStartLoc.z-playerRealPos[3])^2))<2 and id==nil then
						rampageNewPos=monsterDetails.location
						noMove=true
						gStates.pursuitTwoOption=false
					else
						if id~=nil then gStates.skippedMove=true else gStates.skippedMove=false end
						if math.sqrt(((rampageNewPos[1]-playerPos[1])^2)+((rampageNewPos[3]-playerPos[3])^2))<0.5 or count>3 then
							rampageNewPos=monsterDetails.location
							noMove=true
							if count<4 and canAttack==false then
								if protection=="Interaction" or protection=="City" then broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} avoids pursuit at an Interaction site.{ru} избегает преследования в месте взаимодействия.{zh-cn}避免在有交涉的板块追击{ko}: 교류 장소에선 추적을 회피합니다.{es} evita la persecución en un sitio de Interacción.{fr} évite les poursuites sur un site d'Interaction.{pt-br} Evita perseguir em um lugar de interação.{de} vermeidet die Verfolgung an einem Interaktionsort."}), positionToColor(gStates.turnNumber)) end
								if protection=="Wall" then broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} avoids pursuit behind the wall.{ru} избегает преследования, находясь за стеной.{zh-cn}避免在有城墙的板块追击{ko}: 벽 뒤에선 추적을 회피합니다.{es} evita la persecución detrás de la pared.{fr} évite les poursuites derrière le mur.{pt-br} Evita perseguir atrás de um Muro.{de} vermeidet die Verfolgung hinter einer Mauer."}), positionToColor(gStates.turnNumber)) end
								if protection=="Fortified" then broadcastToAll(joinLang({translateWord[turnOrder[gStates.turnNumber].mage], "{en} avoids pursuit at a Fortified site.{ru} избегает преследования в укрепленном месте.{zh-cn}避免在有城防的板块追击{ko}: 요새화된 장소에선 추적을 회피합니다.{es} evita la persecución en un sitio Fortificado.{fr} évite les poursuites sur un site Fortifié.{pt-br} Evita perseguir em um local Fortificado.{de} vermeidet die Verfolgung an einem befestigten Ort."}), positionToColor(gStates.turnNumber)) end
							end
						end
						if canAttack==true then
							--Use the shared combat grid so pursuing attackers cannot overlap defenders deployed at the same time.
							rampageNewPos={(turnOrder[gStates.turnNumber].seatPos*40)-96+gStates.monsterOffsetX, 2.5, -39-gStates.monsterOffsetZ}
							gStates.monsterOffsetX=gStates.monsterOffsetX+2.5
							if gStates.monsterOffsetX>12 then gStates.monsterOffsetX=0 gStates.monsterOffsetZ=gStates.monsterOffsetZ+2.5 end
							noMove=false
							 gStates.monsterPlayLocation[monsterGUID]=monsterDetails.location
							getObjectFromGUID(monsterGUID).UI.setXmlTable({{}})
							broadcastToAll(joinLang({"{en}Pursuing Monster Attacked {ru}Преследующие враги напали на {zh-cn}被追击怪物所攻击{ko}추적 중인 몬스터의 공격: {es}Persecución de Monstruos Atacados por {fr}Poursuivant le Monstre Attaqué {pt-br}Monstro Perseguidor Atacado {de}Verfolgtes Monster angegriffen ", translateWord[turnOrder[gStates.turnNumber].mage]}), positionToColor(gStates.turnNumber))
						end
					end
					getObjectFromGUID(monsterGUID).setPositionSmooth(rampageNewPos)

					if canAttack==false then gStates.monsterPlayLocation[monsterGUID]=rampageNewPos end
					height=height+0.2

					--Add an arrow to help find which tokens moved
					if noMove==false then
						for i=1, twoOptions, 1 do
							local arrowPos={monsterDetails.location[1]-(1.1*math.cos(math.rad(playerBearing))), 1.11, monsterDetails.location[3]-(1.1*math.sin(math.rad(playerBearing)))}
							local arrow=getObjectFromGUID("6647eb").clone({position=arrowPos})
							local convert={[0]=270, [30]=240, [60]=210, [90]=180, [120]=150, [150]=120, [180]=90, [210]=60, [240]=30, [270]=0, [300]=330, [330]=300, [360]=270}
							if playerBearing>=360 then playerBearing=playerBearing-360 end
							if playerBearing<0 then playerBearing=playerBearing+360 end
							arrow.setRotation({90.00, convert[playerBearing], 0.00})
							arrow.setColorTint("Orange")
							arrow.setPosition(arrowPos) arrow.lock() gStates.arrowDelete[arrow.guid]="Del"
							playerBearing=otherBearing
						end
					end
					mainUIUpdate("pursuit")
				end
			end
			Wait.frames(function() addAvatarButtons() end, 60)
		end
	end
end

--Adjust the offer size
local OfferPause=false
function offerAdjust(player, mouseButton, id)
	if mouseButton=="-1" and OfferPause==false then
		OfferPause=true
		--update Offer size expected.
		if id=="e4372aOfferUp" then gStates.offerSize=gStates.offerSize+1 else gStates.offerSize=gStates.offerSize-1 end
		--move both decks and their detecting Zones, drop the decks onto existing cards.
		getObjectFromGUID(GUID.deck.spell).setPositionSmooth({(4.8*(gStates.offerSize+1))+21.6, 2.5, -22.2})
		getObjectFromGUID(GUID.deck.action).setPositionSmooth({(4.8*(gStates.offerSize+1))+21.6, 2.5, -16.2})
		getObjectFromGUID(GUID.zone.spellDeck).setPosition({(4.8*(gStates.offerSize+1))+21.6, 2.05, -22.2})
		getObjectFromGUID(GUID.zone.actionDeck).setPosition({(4.8*(gStates.offerSize+1))+21.6, 2.05, -16.2})
		--change size of offer Zone
		getObjectFromGUID(GUID.zone.offer).setScale({4.8*gStates.offerSize, 0.3, 9.57})
		getObjectFromGUID(GUID.zone.offer).setPosition({(2.4*(gStates.offerSize-1))+26.4, 1.13, -19.2})
		if id=="e4372aOfferUp" then
			--run fill slide after a wait frame.
			fillSlide()
			--Wait.condition(function() fillSlide() end, function() return getObjectFromGUID(GUID.deck.spell).resting end)
		else
			--flip existing cards if shrinking the offer.
			for _, card in pairs(getObjectFromGUID(GUID.zone.offer).getObjects()) do
				if math.floor(((card.getPosition()[1]-21.6)/4.8)+0.5)==gStates.offerSize+1 and card.type=="Card" then
					standardDeckCycleMarkReturned(gameCardType(card), card)
					card.unlock()
					card.setRotation({0.00, 180.00, 180.00})
				end
			end
		end
		Wait.frames(function()
			OfferPause=false
			getObjectFromGUID(GUID.deck.spell).UI.setXmlTable({	{tag="Button", attributes={id="e4372aOfferUp", onClick="global/offerAdjust", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", height=150, width=240, position="60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
															children={	{tag="Image", attributes={id="e4372aOfferUpImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																		{tag="Text", attributes={fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text=">"}}}},
															{tag="Button", attributes={id="e4372aOfferDown", onClick="global/offerAdjust", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked", height=150, width=240, position="-60 190 -10", rotation="0 180 180", scale="0.32 0.32"},
															children={	{tag="Image", attributes={id="e4372aOfferDownImage", image="Sliced Button/Button Object Active", type="Sliced"}},
																		{tag="Text", attributes={fontSize="90", fontStyle="Normal", alignment="MiddleCenter", text="<"}}}}})
		end, 60)
	end
end

--Player seat colors only change during setup/load or when a player uses the color controls.
--Keep physical tinting out of mainUIUpdate so ordinary card play never recolors unchanged objects.
function refreshPlayerSeatColors()
	if gStates==nil or gStates.handColors==nil then return end
	for _, playerData in pairs(turnOrder) do
		if playerData.seatPos~=nil and playerData.mage~=gStates.positionMageKnight[5] then
			local color=nil
			for handColor, seatPos in pairs(gStates.handColors) do if seatPos==playerData.seatPos then color=handColor break end end
			if color~=nil then
				for _, mageData in pairs(mageKnights) do
					if mageData.mage==playerData.mage then
						local model=getObjectFromGUID(mageData.model)
						local standee=getObjectFromGUID(mageData.standee)
						local bar=getObjectFromGUID(colorBand[playerData.seatPos])
						if model~=nil then model.setColorTint(color) end
						if standee~=nil then standee.setColorTint(color) end
						if bar~=nil then bar.setColorTint(color) end
						break
					end
				end
			end
		end
	end
end

local tactic4HandBonusPause=nil
function refreshTactic4HandBonus(updateUI)
	if gStates==nil or gStates.turnNumber==nil or turnOrder[gStates.turnNumber]==nil then return false end
	local playerData=turnOrder[gStates.turnNumber]
	local bonus=0
	if playerData.tactic==4 and gStates.dayRound==true and gStates.tacticShown==false and playerData.seatPos~=nil and playerData.seatPos<5 then
		local handZone=getObjectFromGUID(handZones[playerData.seatPos])
		if handZone~=nil then
			local cardsInHand=0
			for _, obj in pairs(handZone.getObjects()) do
				if obj.type=="Card" then
					cardsInHand=cardsInHand+1
					if cardsInHand>=2 then bonus=1 break end
				end
			end
		end
	end
	local changed=gStates.tactic4HandBonus~=bonus
	gStates.tactic4HandBonus=bonus
	if changed==true and updateUI==true and gStates.firstStarted==true then mainUIUpdate("Tactic 4 Hand Bonus Changed") end
	return changed
end
function scheduleTactic4HandBonusRefresh()
	if tactic4HandBonusPause~=nil then Wait.stop(tactic4HandBonusPause) end
	tactic4HandBonusPause=Wait.time(function()
		tactic4HandBonusPause=nil
		refreshTactic4HandBonus(true)
	end, 0.05)
end

--Add a row of buttons to allow changing of hand color
function applyColorBarButtons()
	for position, barGUID in pairs(colorBand) do
		local buttons={{tag="Button", attributes={id=barGUID.."changeMatDown",
			onClick="global/changeMatImage", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked",
			height=29, width=3, color="rgba(0,0,0,0.0)",
			position="-90 30 -40", rotation="0 0 180"},
				children={{tag="Image", attributes={id=barGUID.."changeMatDownImage", image="Overkill Down"}}}},
			{tag="Button", attributes={id=barGUID.."changeMatUp",
			onClick="global/changeMatImage", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked",
			height=29, width=3, color="rgba(0,0,0,0.0)",
			position="-95 30 -40", rotation="0 0 180"},
				children={{tag="Image", attributes={id=barGUID.."changeMatUpImage", image="Overkill Up"}}}}}
		if getObjectFromGUID(barGUID)~=nil then
			local barSkip=false
			local barPlayerIndex=nil
			local barPlayerData=nil
			for playerIndex, playerData in pairs(turnOrder) do
				if playerData.seatPos==position then
					if playerData.mage==gStates.positionMageKnight[5] then barSkip=true
					else barPlayerIndex=playerIndex barPlayerData=playerData end
					break
				end
			end
			local handColorList={"White", "Brown", "Red", "Orange", "Yellow", "Green", "Teal", "Blue", "Purple", "Pink"}
			local loopCount=1
			for _, handColor in pairs(handColorList) do
				local available=true
				for _, playerData in pairs(turnOrder) do
					for _, seat in pairs(Player.getAvailableColors()) do
						if playerData.mage~=gStates.positionMageKnight[5] and math.ceil((Player[seat].getHandTransform().position[1]+97.59)/40)==playerData.seatPos and seat==handColor then available=false break end
					end
				end
				if available==true then
					buttons[#buttons+1]={tag="Button", attributes={id=barGUID..handColor,
						onClick="global/changePositionColor",
						height=25, width=3,
						position=tostring(102-(loopCount*5)).." 30 -40", rotation="0 0 180",
						color=handColor}}
					loopCount=loopCount+1
				end
			end
			if barPlayerData~=nil then
				local dropText="DROP OUT"
				local dropVisible=false
				local dropInteractable=false
				local dropImage="Sliced Button/Button Object Active"
				if barPlayerData.dropoutState=="dropped" then
					dropText="DROPPED OUT" dropVisible=true dropImage="Sliced Button/Button Object Deactive"
				elseif barPlayerData.dropoutState=="pending" then
					dropText="UNDO DROP OUT" dropVisible=dropoutCoopLocked()==false dropInteractable=dropVisible
				elseif gStates.firstStarted==true and barPlayerIndex~=gStates.turnNumber and dropoutCoopLocked()==false and activeMageKnightCount()>=3 then
					dropVisible=true dropInteractable=true
				end
				if dropVisible==true then
					--The color bar is a cube scaled {19.80, 0.01, 2.50}; counter-scale X/Z so this renders like a normal Claim-style button.
					buttons[#buttons+1]={tag="Button", attributes={id=barGUID.."DropOut", onClick="global/dropOutPlayer", onMouseDown="global/buttonClicked", onMouseUp="global/buttonClicked",
						height=200, width=800, position="-70 30 -40", rotation="0 0 0", scale="0.01778 0.1408", interactable=dropInteractable},
						children={{tag="Image", attributes={id=barGUID.."DropOutImage", image=dropImage, type="Sliced"}},
							{tag="Text", attributes={id=barGUID.."DropOutText", font="Fonts/MKCardText", fontSize=90, fontStyle="Normal", alignment="MiddleCenter", resizeTextForBestFit="true", resizeTextMaxSize=90, text=dropText}}}}
				end
			end
			if barSkip==false then getObjectFromGUID(barGUID).UI.setXmlTable(buttons) end
		end
	end
end

local dropoutMatImage="https://steamusercontent-a.akamaihd.net/ugc/9970617178500111609/C9D8D7517B7FAF114F10D8195AC38269F0504E37/"

local function setDropoutMatImage(playerData, droppingOut)
	if playerData==nil or playerData.playerBoardGUID==nil then return end
	local board=getObjectFromGUID(playerData.playerBoardGUID)
	if board==nil then return end
	if droppingOut==true then
		local custom=board.getCustomObject()
		if playerData.preDropoutMatImage==nil and custom~=nil and custom.image~=nil then playerData.preDropoutMatImage=custom.image end
		board.setCustomObject({image=dropoutMatImage})
	elseif playerData.preDropoutMatImage~=nil then
		board.setCustomObject({image=playerData.preDropoutMatImage})
		playerData.preDropoutMatImage=nil
	else
		return
	end
	board.reload()
end

function dropOutPlayer(player, mouseButton, id)
	if mouseButton~="-1" then return end
	local barGUID=id:sub(1,6)
	local playerIndex=nil
	local playerData=nil
	for position, testGUID in pairs(colorBand) do
		if testGUID==barGUID then
			for a, details in pairs(turnOrder) do
				if details.seatPos==position and details.mage~=gStates.positionMageKnight[5] then playerIndex=a playerData=details break end
			end
			break
		end
	end
	if playerData==nil or legalPlayerCheck(player.color, playerData.seatPos, "NoDummyException")~=true then return end
	if dropoutCoopLocked()==true then
		broadcastToAll("Players cannot drop out while a cooperative assault or defense is being resolved.", positionToColor(playerIndex))
		applyColorBarButtons()
		return
	end
	if gStates.firstStarted==true and playerIndex==gStates.turnNumber then
		broadcastToAll("You cannot drop out during your own turn.", positionToColor(playerIndex))
		applyColorBarButtons()
		return
	end
	if playerData.dropoutState=="dropped" then return end
	if playerData.dropoutState=="pending" then
		playerData.dropoutState=nil
		setDropoutMatImage(playerData, false)
		broadcastToAll(joinLang({translateWord[playerData.mage], "{en} cancelled dropping out.{ru} отменил выход из игры.{zh-tw} 取消了退出遊戲。{zh-cn} 取消了退出游戏。{ko} 게임 나가기를 취소했습니다.{es} canceló su abandono de la partida.{fr} a annulé son départ de la partie.{pt-br} cancelou a saída do jogo.{de} hat das Verlassen des Spiels abgebrochen."}), positionToColor(playerIndex))
	else
		--Never allow dropouts to reduce the game below two active Mage Knights.
		if activeMageKnightCount()<3 then
			broadcastToAll("At least two Mage Knights must remain in the game.", positionToColor(playerIndex))
			applyColorBarButtons()
			return
		end
		playerData.dropoutState="pending"
		setDropoutMatImage(playerData, true)
		broadcastToAll(joinLang({translateWord[playerData.mage], "{en} will drop out when turn order next advances. Press Undo Drop Out before then to cancel.{ru} выйдет из игры при следующем переходе хода. До этого можно отменить выход.{zh-tw} 將在下一次推進回合順序時退出遊戲；在此之前可按撤銷退出。{zh-cn} 将在下一次推进回合顺序时退出游戏；在此之前可按撤销退出。{ko} 다음 차례 진행 시 게임에서 나갑니다. 그 전까지 나가기 취소를 누를 수 있습니다.{es} abandonará la partida cuando avance el orden de turno. Puede deshacerlo antes de entonces.{fr} quittera la partie au prochain changement de tour. Vous pouvez annuler avant cela.{pt-br} sairá do jogo quando a ordem de turno avançar. Você pode desfazer antes disso.{de} verlässt das Spiel beim nächsten Zugwechsel. Bis dahin kann der Austritt rückgängig gemacht werden."}), positionToColor(playerIndex))
	end
	applyColorBarButtons()
end

--Change a hand's color and refresh.
function changePositionColor(player, mouseButton, id)
	local barConversion={[colorBand[1]]=1, [colorBand[2]]=2, [colorBand[3]]=3, [colorBand[4]]=4}
	local barGUID=id:sub(1,6)
	local newColor=id:sub(7, string.len(id))
	local currentColor=Hands.getHands()[barConversion[barGUID]].getValue()
	if mouseButton=="-1" and legalPlayerCheck(player.color, gStates.handColors[currentColor], "NoDummyException")==true then
		--swap an existing unused color to stop two hands having the same colour
		if gStates.handColors[newColor]~=nil then
			for _, freeHandColor in pairs(Player.getColors()) do
				if gStates.handColors[freeHandColor]==nil then
					Hands.getHands()[gStates.handColors[newColor]].setValue(freeHandColor)
					gStates.handColors[freeHandColor]=gStates.handColors[newColor]
					gStates.handColors[newColor]=nil
					break
				end
			end
		end
		--change hand colour
		gStates.handColors[newColor]=gStates.handColors[currentColor]
		gStates.handColors[currentColor]=nil
		Hands.getHands()[barConversion[barGUID]].setValue(newColor)
		Player[currentColor].changeColor(newColor)
		applyColorBarButtons()
		refreshPlayerSeatColors()
		outOfTurnUIStateKey=nil
		mainUIUpdate("Player Changed Colour")
		Wait.frames(function() Player[newColor].lookAt({position={getObjectFromGUID(barGUID).getPosition()[1], getObjectFromGUID(barGUID).getPosition()[2], getObjectFromGUID(barGUID).getPosition()[3]-10}, pitch=75, yaw=0, distance=30}) end, 2)
	end
end

